    /** @return array<string,string> Runtime filename => trusted source path. */
    private static function theme_runtime_sources(): array {
        $sources = [];
        foreach (self::THEME_RUNTIME_FILES as $file) {
            if ($file === 'membership.php') continue; // Supplied only by the separately installed extension.
            if ($file === 'redirects.php' && !Kodety_Edition::has('redirects')) continue;
            $sources[$file] = KODETY_DIR . 'theme-runtime/' . $file;
        }
        $filtered = apply_filters('kodety_theme_runtime_sources', $sources);
        if (!is_array($filtered)) return $sources;
        $safe = [];
        foreach ($filtered as $file => $source) {
            $file = is_string($file) ? basename($file) : '';
            $source = is_string($source) ? $source : '';
            if ($file === '' || !str_ends_with($file, '.php') || $source === '' || !is_file($source)) continue;
            $safe[$file] = $source;
        }
        return $safe;
    }

    /** @return list<string> */
    private static function theme_runtime_files(): array {
        return array_keys(self::theme_runtime_sources());
    }
