    private function __construct() {
        Kodety_Sitemap::register();
        // Multi-project agency mode is retired. Preserve its private files and
        // options for recovery, but make every runtime surface single-project
        // before any other subsystem reads the old setting.
        if (get_option('kodety_workspace_mode', 'single') !== 'single') {
            update_option('kodety_workspace_mode', 'single', false);
        }
        add_filter('pre_update_option_kodety_workspace_mode', static fn(mixed $value): string => 'single', PHP_INT_MAX);
        add_filter('option_kodety_workspace_mode', static fn(mixed $value): string => 'single', PHP_INT_MAX);
        $uploads = wp_upload_dir();
        $this->storage_dir = trailingslashit($uploads['basedir']) . 'kodety';
        // Token-scoped previews can also be opened by external review tools.
        // Emit permissive read-only CORS before WordPress resolves the file so
        // redirects, errors, HEAD and preflight responses keep the contract.
        add_action('init', [$this, 'send_project_preview_cors_headers'], -1000);
        add_action('send_headers', [$this, 'send_project_preview_cors_headers'], -1000);
        add_filter('wp_headers', [$this, 'filter_project_preview_cors_headers'], PHP_INT_MAX);
        add_action('init', [$this, 'register_collections'], 5);
        add_action('init', [$this, 'register_route']);
        add_action('parse_request', [$this, 'detect_direct_route'], 0);
        add_filter('post_link', [$this, 'cms_post_permalink'], 10, 2);
        add_filter('post_type_link', [$this, 'cms_post_permalink'], 10, 2);
        add_filter('map_meta_cap', [$this, 'protect_read_only_cms_items'], 10, 4);
        add_filter('rest_request_before_callbacks', [$this, 'protect_project_cms_rest_item'], 10, 3);
        add_filter('wp_insert_post_empty_content', [$this, 'enforce_free_item_limit_on_insert'], 10, 2);
        add_action('pre_get_posts', [$this, 'scope_agency_cms_query'], 5);
        add_filter('wp_post_revision_meta_keys', [$this, 'revision_meta_keys'], 10, 2);
        add_filter('query_vars', fn(array $vars): array => array_merge(
            $vars,
            [
                'kodety_app',
