    /** Only a document from this installation may bypass HTTP and read public assets from disk. */
    private function import_source_is_same_wordpress(string $url): bool {
        if (!function_exists('home_url') || !preg_match('~^https?://~i', $url)) return false;
        $source = wp_parse_url($url);
        $home = wp_parse_url(home_url('/'));
        if (!is_array($source) || !is_array($home) || empty($source['host']) || empty($home['host'])) return false;
        $source_host = strtolower(rtrim((string) $source['host'], '.'));
        $home_host = strtolower(rtrim((string) $home['host'], '.'));
        $source_scheme = strtolower((string) ($source['scheme'] ?? 'http'));
        $home_scheme = strtolower((string) ($home['scheme'] ?? 'http'));
        $source_port = (int) ($source['port'] ?? ($source_scheme === 'https' ? 443 : 80));
        $home_port = (int) ($home['port'] ?? ($home_scheme === 'https' ? 443 : 80));
        if ($source_host === '' || !hash_equals($home_host, $source_host) || $source_port !== $home_port) return false;
        $home_path = '/' . trim(rawurldecode((string) ($home['path'] ?? '/')), '/');
        if ($home_path === '/') return true;
        $source_path = '/' . trim(rawurldecode((string) ($source['path'] ?? '/')), '/');
        return $source_path === $home_path || str_starts_with($source_path, $home_path . '/');
    }

    /**
     * Replace the WordPress admin bar with the Onun Kodety launcher on the live site.
     *
     * Project members edit through the floating launcher, so the default toolbar
     * only adds clutter on the front-end. It is left untouched inside wp-admin and
     * for anyone who cannot edit this project.
     */
    public function hide_admin_bar_for_editors(bool $show): bool {
        if (is_admin()) return $show;
        return current_user_can(self::CAP_EDIT_WORKSPACE) ? false : $show;
    }

    /**
     * WordPress roles describe editorial ownership; Onun Kodety capabilities describe
     * product surfaces. A trusted Designer receives the complete shared
     * workspace. Native Editors also enter that workspace, while
     * Author/Contributor stay inside the native CMS permission model.
     */
    public static function install_roles_and_capabilities(): void {
        $editor = get_role('editor');
        $designer = get_role(self::ROLE_DESIGNER);
        if (!$designer) {
            $native_editor_caps = $editor && is_array($editor->capabilities)
                ? array_filter($editor->capabilities)
                : [
                    'read' => true,
                    'edit_posts' => true,
                    'edit_others_posts' => true,
                    'edit_published_posts' => true,
                    'publish_posts' => true,
                    'delete_posts' => true,
                    'delete_others_posts' => true,
                    'delete_published_posts' => true,
                    'edit_pages' => true,
                    'edit_others_pages' => true,
                    'edit_published_pages' => true,
                    'publish_pages' => true,
                    'delete_pages' => true,
                    'delete_others_pages' => true,
                    'delete_published_pages' => true,
                    'upload_files' => true,
                ];
            $designer = add_role(self::ROLE_DESIGNER, 'Onun Kodety Designer', $native_editor_caps);
        } elseif ($editor && is_array($editor->capabilities)) {
            // Keep the custom role aligned with newly introduced native
            // editorial capabilities without erasing explicit site overrides.
            foreach ($editor->capabilities as $capability => $granted) {
                if ($granted) $designer->add_cap((string) $capability);
            }
        }

        $managed_capabilities = [
            self::CAP_EDIT_WORKSPACE,
            'kodety_manage_cms', // Legacy alias retained only for trusted roles.
            self::CAP_ACCESS_CMS,
            self::CAP_MANAGE_CMS_SCHEMA,
            self::CAP_MANAGE_CMS_TEMPLATES,
            self::CAP_USE_AI,
            self::CAP_VIEW_ANALYTICS,
            self::CAP_MANAGE_ANALYTICS,
            'kodety_publish',
            'kodety_import',
        ];
        $grants = [
            'administrator' => $managed_capabilities,
            self::ROLE_DESIGNER => [
                self::CAP_EDIT_WORKSPACE,
                'kodety_manage_cms',
                self::CAP_ACCESS_CMS,
                self::CAP_MANAGE_CMS_SCHEMA,
                self::CAP_MANAGE_CMS_TEMPLATES,
                self::CAP_USE_AI,
                self::CAP_VIEW_ANALYTICS,
                self::CAP_MANAGE_ANALYTICS,
                'kodety_import',
            ],
            'editor' => [
                self::CAP_EDIT_WORKSPACE,
                self::CAP_ACCESS_CMS,
                self::CAP_USE_AI,
                self::CAP_VIEW_ANALYTICS,
            ],
            'author' => [self::CAP_ACCESS_CMS],
            'contributor' => [self::CAP_ACCESS_CMS],
            'subscriber' => [],
        ];
        foreach ($grants as $role_name => $allowed) {
            $role = get_role($role_name);
            if (!$role) continue;
            foreach ($managed_capabilities as $capability) {
                if (in_array($capability, $allowed, true)) $role->add_cap($capability);
                else $role->remove_cap($capability);
            }
        }
    }

    public static function activate(): void {
        if (is_multisite()) {
            wp_die(
                'O Onun Kodety ainda não pode ser ativado em Multisite: temas são compartilhados pela rede e uma publicação poderia substituir outro site.',
                'Onun Kodety — Multisite não suportado',
                ['response' => 400, 'back_link' => true]
            );
        }
        $fresh_install = get_option('kodety_schema_version', null) === null;
        self::install_roles_and_capabilities();
        $administrator = get_role('administrator');
        if ($administrator) $administrator->add_cap('kodety_manage_emails');
        $editor = get_role('editor');
        if ($editor) $editor->remove_cap('kodety_manage_emails');
        // The Onun Kodety WordPress interface is the default experience. Users can
        // still switch back to the native admin surface from Settings.
        add_option('kodety_interface_enabled', '1', '', false);
        add_option('kodety_block_editor_skin_enabled', '0', '', false);
        add_option('kodety_mcp_enabled', '0', '', false);
        add_option('kodety_mcp_revision', 0, '', false);
        add_option('kodety_mcp_project_connections', [], '', false);
        add_option('kodety_ai_settings', [], '', false);
        add_option('kodety_ai_api_key', '', '', false);
        add_option('kodety_editor_corner_icon', 'kodety-logo', '', false);
        add_option('kodety_brand_logo_id', 0, '', false);
        add_option('kodety_admin_logo_id', 0, '', false);
        add_option('kodety_login_image_id', 0, '', false);
        add_option('kodety_admin_accent_color', self::DEFAULT_ADMIN_ACCENT_COLOR, '', false);
        add_option('kodety_admin_ui_locale', 'auto', '', false);
        add_option('kodety_workspace_mode', 'single', '', false);
        add_option('kodety_onboarding_status', $fresh_install ? 'pending' : 'complete', '', false);
        add_option('kodety_project_name', '', '', false);
        add_option('kodety_workspace_project_id', '', '', false);
        add_option('kodety_published_project_id', '', '', false);
        add_option('kodety_workspace_revision', 0, '', false);
        add_option('kodety_workspace_css_digest', '', '', false);
        add_option(self::PAGES_SYNC_NOTIFIED_OPTION, '', '', false);
        add_option(self::PUBLISH_SYNC_ERROR_OPTION, [], '', false);
        add_option('kodety_cms_templates', [], '', false);
        add_option('kodety_field_definitions', [], '', false);
        add_option('kodety_optimization_settings', self::default_optimization_settings(), '', false);
        add_option('kodety_last_published_at', '', '', false);
        add_option('kodety_schema_version', self::SCHEMA_VERSION, '', false);
        if ($fresh_install) update_option('kodety_onboarding_status', 'pending', false);
        add_option('kodety_acf_install_pending', '1', '', false);
        self::install_default_permalink_structure();
        self::instance()->ensure_directories();
        // Activation can happen while an older generated theme is live. Repair
        // its runtime in the same request; the transaction rolls back cleanly
        // and leaves a retryable stale ACK if the host rejects a write.
        self::instance()->maybe_refresh_active_theme_runtime(true);
        self::instance()->register_route();
        flush_rewrite_rules();
    }

    /**
     * Give new Onun Kodety sites readable URLs without taking ownership of the
     * setting forever. Once initialized, a later manual WordPress choice is
     * preserved across Onun Kodety updates and reactivations.
     */
    private static function install_default_permalink_structure(): void {
        if ((string) get_option(self::PERMALINK_SETUP_OPTION, '') === '1') return;

        global $wp_rewrite;
        if (is_object($wp_rewrite) && method_exists($wp_rewrite, 'set_permalink_structure')) {
            $wp_rewrite->set_permalink_structure(self::DEFAULT_PERMALINK_STRUCTURE);
        } else {
            update_option('permalink_structure', self::DEFAULT_PERMALINK_STRUCTURE, false);
        }

        // Some constrained hosts provide a partial rewrite object. Confirm the
        // persisted option before marking setup complete.
        if ((string) get_option('permalink_structure', '') !== self::DEFAULT_PERMALINK_STRUCTURE) {
            update_option('permalink_structure', self::DEFAULT_PERMALINK_STRUCTURE, false);
        }
        if ((string) get_option('permalink_structure', '') === self::DEFAULT_PERMALINK_STRUCTURE) {
            update_option(self::PERMALINK_SETUP_OPTION, '1', false);
        }
    }

    public function maybe_upgrade(): void {
        $schema_version = (int) get_option('kodety_schema_version', 0);
        // A missing value and zero both mean “use the bundled artwork”, so the
        // option can be backfilled safely without a data migration.
        add_option('kodety_login_image_id', 0, '', false);
        if ($schema_version < 6) {
            foreach (['administrator', 'editor'] as $role_name) {
                $role = get_role($role_name);
                if (!$role) continue;
                $role->add_cap('kodety_edit');
                $role->add_cap('kodety_manage_cms');
                if ($role_name === 'administrator') {
                    $role->add_cap('kodety_publish');
                    $role->add_cap('kodety_manage_emails');
                    $role->add_cap('kodety_import');
                } else {
                    $role->remove_cap('kodety_publish');
                    $role->remove_cap('kodety_manage_emails');
                    $role->remove_cap('kodety_import');
                }
            }
            add_option('kodety_optimization_settings', self::default_optimization_settings(), '', false);
            add_option('kodety_last_published_at', '', '', false);
            add_option('kodety_workspace_project_id', '', '', false);
            add_option('kodety_published_project_id', '', '', false);
            // ZIP is a transport format, not the database of the site. Migrate the
            // editable project and legacy release archives to native, inspectable
            // workspace directories before discarding the old containers.
            $this->ensure_directories();
            if (!$this->migrate_native_workspace_storage()) return;
            // Legacy releases predate projectId, so they cannot be classified
            // safely. Keep only the live one during this one-time migration.
            $this->prune_release_storage((string) get_option('kodety_current_release', ''), 1);
            update_option('kodety_assets_synced_release', '', false);
            update_option('kodety_schema_version', 6, false);
            $schema_version = 6;
        }

        if ($schema_version < 7) {
            add_option('kodety_admin_accent_color', self::DEFAULT_ADMIN_ACCENT_COLOR, '', false);
            $icon = sanitize_key((string) get_option('kodety_editor_corner_icon', 'kodety-logo'));
            $has_client_logo = absint(get_option('kodety_brand_logo_id', 0)) > 0;
            if ($icon !== 'client-logo' || !$has_client_logo) {
                update_option('kodety_editor_corner_icon', 'kodety-logo', false);
            }
            delete_option('kodety_brand_name');
            update_option('kodety_schema_version', 7, false);
            $schema_version = 7;
        }

        if ($schema_version < 8) {
            // Onun Kodety's default accent is now blue. Only sites still carrying the
            // old default are moved: a colour someone actually picked is their
            // choice and stays untouched.
            if (strtolower((string) get_option('kodety_admin_accent_color', '')) === '#e4f222') {
                update_option('kodety_admin_accent_color', self::DEFAULT_ADMIN_ACCENT_COLOR, false);
            }
            update_option('kodety_schema_version', 8, false);
            $schema_version = 8;
        }

        if ($schema_version < 10) {
            add_option('kodety_workspace_mode', 'single', '', false);
            add_option('kodety_onboarding_status', 'complete', '', false);
            // Existing sites used one logo for both the WordPress shell and
            // product surfaces. Preserve their wp-admin appearance while the
            // Builder returns to the permanent Onun Kodety identity.
            $legacy_admin_logo = absint(get_option('kodety_brand_logo_id', 0));
            add_option('kodety_admin_logo_id', $legacy_admin_logo, '', false);
            update_option('kodety_schema_version', 10, false);
            $schema_version = 10;
        }

        if ($schema_version < 11) {
            update_option('kodety_workspace_mode', 'single', false);
            update_option('kodety_schema_version', 11, false);
            $schema_version = 11;
        }

        if ($schema_version < 13) {
            // Older releases enabled regex/DOM publication transforms by
            // default. Those transforms are not safe for arbitrary authored
            // HTML: whitespace between inline spans is semantic, CSS strings
            // may intentionally contain spaces, and loading attributes affect
            // GSAP/Lenis measurements. Migrate every existing installation to
            // the lossless publication contract; no reimport is required.
            update_option('kodety_optimization_settings', self::default_optimization_settings(), false);
            update_option('kodety_schema_version', 13, false);
            $schema_version = 13;
        }

        if ($schema_version < 14) {
            // Move only the former Onun Kodety default. Any other saved colour was
            // explicitly chosen by the site owner and must remain untouched.
            if (strtolower((string) get_option('kodety_admin_accent_color', '')) === '#57aeff') {
                update_option('kodety_admin_accent_color', self::DEFAULT_ADMIN_ACCENT_COLOR, false);
            }
            update_option('kodety_schema_version', 14, false);
            $schema_version = 14;
        }

        if ($schema_version < 15) {
            // CMS options and items predate explicit workspace ownership. Claim
            // them for the already-mounted workspace before strict scoped reads
            // are enabled; an unavailable/ambiguous workspace retries on the
            // next request instead of exposing the legacy store to another ID.
            if (!$this->migrate_legacy_cms_project_scope()) return;
            update_option('kodety_schema_version', 15, false);
            $schema_version = 15;
        }

        if ($schema_version < self::SCHEMA_VERSION) {
            self::install_roles_and_capabilities();
            update_option('kodety_schema_version', self::SCHEMA_VERSION, false);
            $schema_version = self::SCHEMA_VERSION;
        }
    }

    public static function deactivate(): void {
        if (function_exists('wp_unschedule_hook')) {
            wp_unschedule_hook(self::PUBLISH_SYNC_RETRY_HOOK);
        } elseif (function_exists('wp_clear_scheduled_hook')) {
            wp_clear_scheduled_hook(self::PUBLISH_SYNC_RETRY_HOOK);
        }
        flush_rewrite_rules();
    }

    /**
     * Builder surfaces are extensible without making an extension patch core
     * rewrite, authorization and shell code in several different places.
     *
     * @return array<string,array{capability:string,extension:string,shared:bool}>
     */
    public function builder_apps(): array {
        $apps = [
            'editor' => ['capability' => self::CAP_EDIT_WORKSPACE, 'extension' => '', 'shared' => true],
            'cms' => ['capability' => self::CAP_ACCESS_CMS, 'extension' => '', 'shared' => true],
            'settings' => ['capability' => self::CAP_EDIT_WORKSPACE, 'extension' => '', 'shared' => true],
            'localization' => ['capability' => self::CAP_EDIT_WORKSPACE, 'extension' => '', 'shared' => true],
            'templates' => ['capability' => self::CAP_EDIT_WORKSPACE, 'extension' => '', 'shared' => false],
            // Keep the route stable even before/after extension activation.
            // Authorization below still blocks direct access while Kodefy is
            // inactive, but WordPress never needs a manual permalink refresh.
            'kodefy' => ['capability' => 'manage_options', 'extension' => 'kodefy-shopify', 'shared' => false],
            'analytics' => ['capability' => self::CAP_VIEW_ANALYTICS, 'extension' => 'kodety-analytics', 'shared' => true],
            'members' => ['capability' => 'kodety_view_members', 'extension' => 'kodety-membership', 'shared' => true],
        ];
        $filtered = apply_filters('kodety_builder_apps', $apps, $this);
        if (!is_array($filtered)) $filtered = $apps;
        $normalized = [];
        foreach ($filtered as $slug => $definition) {
            $slug = sanitize_key((string) $slug);
            if ($slug === '' || $slug === 'admin' || !is_array($definition)) continue;
            $capability = sanitize_key((string) ($definition['capability'] ?? self::CAP_EDIT_WORKSPACE));
            if ($capability === '') $capability = self::CAP_EDIT_WORKSPACE;
            $normalized[$slug] = [
                'capability' => $capability,
                'extension' => sanitize_key((string) ($definition['extension'] ?? '')),
                'shared' => !empty($definition['shared']),
            ];
        }
        return $normalized ?: $apps;
    }

    private function builder_app_pattern(bool $shared_only = false): string {
        $slugs = [];
        foreach ($this->builder_apps() as $slug => $definition) {
            if ($shared_only && empty($definition['shared'])) continue;
            $slugs[] = preg_quote($slug, '~');
        }
        return implode('|', $slugs);
    }

    public function register_route(): void {
        add_rewrite_rule('^kodety/?$', 'index.php?kodety_app=admin', 'top');
        add_rewrite_rule(
            '^kodety/preview/([A-Za-z0-9_-]{24,80})(?:/(.*))?$',
            'index.php?kodety_preview=$matches[1]&kodety_preview_path=$matches[2]',
            'top'
        );
        add_rewrite_rule(
            '^kodety/player/youtube/?$',
            'index.php?kodety_youtube_embed=1',
            'top'
        );
        foreach (array_keys($this->builder_apps()) as $app) {
            add_rewrite_rule(
                '^kodety/' . preg_quote($app, '~') . '/?$',
                'index.php?kodety_app=' . $app,
                'top'
            );
        }
        // The folder picker left the project menu. It now has its own address so
        // the capability stays reachable without an entry that invites accidents.
        add_rewrite_rule('^kodety/editor/folder/?$', 'index.php?kodety_app=editor&kodety_folder_picker=1', 'top');
        if (class_exists('Kodety_Sharing')) {
            $shared_apps = $this->builder_app_pattern(true);
            add_rewrite_rule(
                '^kodety/share/(' . Kodety_Sharing::token_pattern() . ')/(' . $shared_apps . ')/?$',
                'index.php?kodety_share=$matches[1]&kodety_app=$matches[2]',
                'top'
            );
            add_rewrite_rule(
                '^kodety/share/(' . Kodety_Sharing::token_pattern() . ')/?$',
                'index.php?kodety_share=$matches[1]&kodety_app=editor',
                'top'
            );
        }
        add_rewrite_rule('^kodety/layouts/(.+)$', 'index.php?kodety_asset=$matches[1]', 'top');
        foreach (get_post_types(['public' => true], 'objects') as $post_type) {
            if (!$post_type instanceof WP_Post_Type || in_array($post_type->name, ['attachment', 'page'], true)) continue;
            $base = $this->cms_route_base($post_type->name);
            if ($base === '') continue;
            add_rewrite_rule('^' . preg_quote($base, '~') . '/([^/]+)/?$', 'index.php?post_type=' . $post_type->name . '&name=$matches[1]', 'top');
        }
        if (get_option('kodety_cms_route_version', '') !== '9') {
            update_option('kodety_cms_route_version', '9', false);
            flush_rewrite_rules(false);
        }
    }

    private function cms_route_base(string $post_type): string {
        foreach ($this->collection_definitions() as $definition) {
            if (($definition['slug'] ?? '') !== $post_type) continue;
            return sanitize_title((string) ($definition['urlSlug'] ?? $definition['name'] ?? $post_type));
        }
        $object = get_post_type_object($post_type);
        if ($post_type === 'post') return sanitize_title((string) ($object?->labels->name ?: 'posts'));
        if (is_array($object?->rewrite) && !empty($object->rewrite['slug'])) return sanitize_title((string) $object->rewrite['slug']);
        return sanitize_title($post_type);
    }

    private function cms_item_permalink(WP_Post $post): string {
        $base = $this->cms_route_base($post->post_type);
        $slug = sanitize_title($post->post_name ?: (string) $post->ID);
        return home_url(user_trailingslashit(trim($base . '/' . $slug, '/')));
    }

    /** Keep WordPress canonical URLs aligned with the Onun Kodety CMS template route. */
    public function cms_post_permalink(string $permalink, WP_Post $post): string {
        $templates = $this->cms_template_definitions();
        if (empty($templates[$post->post_type])) return $permalink;
        return $this->cms_item_permalink($post);
    }

    public function detect_direct_route(WP $wp): void {
        $request_path = trim(rawurldecode((string) parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH)), '/');
        $home_path = trim((string) parse_url(home_url('/'), PHP_URL_PATH), '/');
        if ($home_path !== '' && str_starts_with($request_path, $home_path . '/')) {
            $request_path = trim(substr($request_path, strlen($home_path)), '/');
        }
        if (preg_match('~^kodety/preview/([A-Za-z0-9_-]{24,80})(?:/(.*))?/?$~', $request_path, $matches)) {
            $wp->query_vars = [
                'kodety_preview' => (string) $matches[1],
                'kodety_preview_path' => (string) ($matches[2] ?? ''),
            ];
            return;
        }
        if ($request_path === 'kodety/player/youtube') {
            $wp->query_vars = ['kodety_youtube_embed' => '1'];
            return;
        }
        if (
            class_exists('Kodety_Sharing')
            && preg_match(
                '~^kodety/share/(' . Kodety_Sharing::token_pattern() . ')(?:/(' . $this->builder_app_pattern(true) . '))?/?$~',
                $request_path,
                $matches
            )
        ) {
            $wp->query_vars = [
                'kodety_share' => (string) $matches[1],
                'kodety_app' => (string) ($matches[2] ?? 'editor'),
            ];
            return;
        }
        if (preg_match('~^kodety(?:/(' . $this->builder_app_pattern() . '))?$~', $request_path, $matches)) {
            $wp->query_vars = ['kodety_app' => $matches[1] ?? 'admin'];
            return;
        }
        if (str_starts_with($request_path, 'kodety/layouts/')) {
            $wp->query_vars = ['kodety_asset' => substr($request_path, strlen('kodety/layouts/'))];
            return;
        }
        if (function_exists('kodety_localization_request') && function_exists('kodety_localization_settings')) {
            $localized_request = kodety_localization_request($request_path, kodety_localization_settings());
            if (!empty($localized_request['prefixed'])) {
                $request_path = (string) ($localized_request['base_route'] ?? $request_path);
            }
        }
        // Friendly CMS routes must also work when WordPress uses the "Plain"
        // permalink structure (where WP_Rewrite persists no rules) or when a
        // host has stale rewrite rules. Only types with an assigned Onun Kodety
        // template are intercepted, so ordinary WordPress routes stay intact.
        foreach ($this->cms_template_definitions() as $post_type => $html_path) {
            if ($html_path === '' || in_array($post_type, ['attachment', 'page'], true)) continue;
            $object = get_post_type_object($post_type);
            if (!$object instanceof WP_Post_Type || !$object->public) continue;
            $base = $this->cms_route_base($post_type);
            if ($base === '') continue;
            if (!preg_match('~^' . preg_quote($base, '~') . '/([^/]+)/?$~u', $request_path, $matches)) continue;
            $slug = sanitize_title((string) $matches[1]);
            if ($slug === '') continue;
            $wp->query_vars = ['post_type' => $post_type, 'name' => $slug];
            return;
        }
    }

    private function public_locale_country_code(mixed $candidate): string {
        if (!is_scalar($candidate)) return '';
        $country = strtoupper(trim((string) $candidate));
        if ($country === 'UK') $country = 'GB';
        if (!preg_match('/^[A-Z]{2}$/D', $country)) return '';
        return in_array($country, ['A1', 'A2', 'AP', 'EU', 'O1', 'T1', 'XX', 'ZZ'], true)
            ? ''
            : $country;
    }

    private function public_locale_request_country(): string {
        $server_keys = [
            // Cloudflare IP Geolocation / visitor location headers.
            'HTTP_CF_IPCOUNTRY',
            // Amazon CloudFront origin request policy.
            'HTTP_CLOUDFRONT_VIEWER_COUNTRY',
            // Vercel request geolocation.
            'HTTP_X_VERCEL_IP_COUNTRY',
            // Fastly example convention when client.geo.country_code is
            // forwarded to the origin by VCL.
            'HTTP_FASTLY_GEO_COUNTRY',
            // Apache/MaxMind GeoIP, including Hostinger hosting after GeoIPEnable.
            'GEOIP_COUNTRY_CODE',
        ];
        $filtered_keys = apply_filters('kodety_public_locale_country_server_keys', $server_keys);
        if (is_array($filtered_keys)) {
            $server_keys = array_values(array_unique(array_filter(
                $filtered_keys,
                static fn(mixed $key): bool => is_string($key)
                    && preg_match('/^[A-Z][A-Z0-9_]{1,127}$/D', $key) === 1
            )));
        }
        foreach ($server_keys as $server_key) {
            $country = $this->public_locale_country_code($_SERVER[$server_key] ?? '');
            if ($country !== '') return $country;
        }
        return '';
    }

    /** PageSpeed Insights identifies its network request with this marker. */
    private function public_locale_is_pagespeed_request(): bool {
        $user_agent = $_SERVER['HTTP_USER_AGENT'] ?? '';
        return is_string($user_agent)
            && stripos(substr($user_agent, 0, 512), 'Chrome-Lighthouse') !== false;
    }

    private function public_locale_region(array $locale): string {
        $region = $this->public_locale_country_code($locale['region'] ?? '');
        if ($region !== '') return $region;
        $segments = preg_split('/[-_]/', (string) ($locale['code'] ?? '')) ?: [];
        foreach (array_reverse(array_slice($segments, 1)) as $segment) {
            $region = $this->public_locale_country_code($segment);
            if ($region !== '') return $region;
        }
        return '';
    }

    /** @param list<array<string,mixed>> $locales */
    private function public_locale_by_code(array $locales, string $code): ?array {
        foreach ($locales as $locale) {
            if (strcasecmp($code, (string) ($locale['code'] ?? '')) === 0) return $locale;
        }
        return null;
    }

    /** @param list<array<string,mixed>> $locales */
    private function public_locale_for_country(array $locales, string $country, array $default_locale): array {
        foreach ($locales as $locale) {
            if ($this->public_locale_region($locale) === $country) return $locale;
        }
        foreach ($locales as $locale) {
            $code = strtolower(str_replace('_', '-', (string) ($locale['code'] ?? '')));
            $language = strtolower((string) ($locale['language'] ?? strtok($code, '-')));
            if ($language === 'en') return $locale;
        }
        return $default_locale;
    }

    /** @param list<array<string,mixed>> $locales */
    private function public_locale_for_browser(array $locales): ?array {
        $preferences = [];
        foreach (explode(',', (string) ($_SERVER['HTTP_ACCEPT_LANGUAGE'] ?? '')) as $order => $part) {
            $segments = array_map('trim', explode(';', $part));
            $range = strtolower(str_replace('_', '-', (string) array_shift($segments)));
            if ($range === '' || !preg_match('/^(?:\*|[a-z]{1,8}(?:-[a-z0-9]{1,8})*)$/D', $range)) continue;
            $quality = 1.0;
            foreach ($segments as $parameter) {
                if (preg_match('/^q\s*=\s*(0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/iD', $parameter, $match)) {
                    $quality = (float) $match[1];
                    break;
                }
            }
            if ($quality > 0) $preferences[] = compact('range', 'quality', 'order');
        }
        usort($preferences, static fn(array $left, array $right): int =>
            $right['quality'] <=> $left['quality'] ?: $left['order'] <=> $right['order']
        );
        foreach ($preferences as $preference) {
            if ($preference['range'] === '*') continue;
            foreach ($locales as $locale) {
                if (strtolower(str_replace('_', '-', (string) ($locale['code'] ?? ''))) === $preference['range']) {
                    return $locale;
                }
            }
            $language = (string) strtok($preference['range'], '-');
            foreach ($locales as $locale) {
                $code = strtolower(str_replace('_', '-', (string) ($locale['code'] ?? '')));
                if (strtolower((string) ($locale['language'] ?? strtok($code, '-'))) === $language) return $locale;
            }
        }
        return null;
    }

    /** Route automatic locale selection before the generated theme renders any
     * HTML. Explicit prefixed URLs and the manual selector cookie always win. */
    public function route_public_locale(): void {
        $method = strtoupper((string) ($_SERVER['REQUEST_METHOD'] ?? 'GET'));
        if (!in_array($method, ['GET', 'HEAD'], true)
            || headers_sent()
            || $this->public_locale_is_pagespeed_request()
            || is_admin()
            || (function_exists('wp_doing_ajax') && wp_doing_ajax())
            || (defined('REST_REQUEST') && REST_REQUEST)
            || (function_exists('is_preview') && is_preview())
        ) return;
        foreach (['kodety_app', 'kodety_preview', 'kodety_asset', 'kodety_member_asset', 'kodety_youtube_embed'] as $query_var) {
            if ((string) get_query_var($query_var) !== '') return;
        }
        if (!function_exists('kodety_localization_request')
            || !function_exists('kodety_manifest_relative_for_request')
            || !function_exists('kodety_localization_page_route')
            || !function_exists('kodety_runtime_public_url')
        ) return;

        $theme_directory = get_template_directory();
        $localization_path = $theme_directory . '/localization.json';
        $manifest_path = $theme_directory . '/manifest.json';
        if (!is_file($localization_path) || !is_file($manifest_path)) return;
        $localization = json_decode((string) file_get_contents($localization_path), true);
        $manifest = json_decode((string) file_get_contents($manifest_path), true);
        if (!is_array($localization) || !is_array($manifest)) return;

        $locales = array_values(array_filter(
            (array) ($localization['locales'] ?? []),
            static fn(mixed $locale): bool => is_array($locale)
                && trim((string) ($locale['code'] ?? '')) !== ''
                && ($locale['enabled'] ?? true) !== false
        ));
        if (!$locales) return;
        $default_code = (string) ($localization['defaultLocale'] ?? $localization['sourceLocale'] ?? '');
        $default_locale = $this->public_locale_by_code($locales, $default_code) ?? $locales[0];

        $request_uri = (string) ($_SERVER['REQUEST_URI'] ?? '/');
        $request_path = trim((string) parse_url($request_uri, PHP_URL_PATH), '/');
        $home_path = trim((string) parse_url(home_url('/'), PHP_URL_PATH), '/');
        if ($home_path !== '' && ($request_path === $home_path || str_starts_with($request_path, $home_path . '/'))) {
            $request_path = trim(substr($request_path, strlen($home_path)), '/');
        }
        $locale_request = kodety_localization_request($request_path, $localization, $manifest);
        // A prefixed route is an explicit visitor choice for this navigation.
        if (!empty($locale_request['prefixed'])) return;

        $manual_code = isset($_COOKIE['kodety_locale_choice'])
            ? sanitize_text_field(wp_unslash((string) $_COOKIE['kodety_locale_choice']))
            : '';
        $preferred = $manual_code !== '' ? $this->public_locale_by_code($locales, $manual_code) : null;
        if (!$preferred) {
            $automatic = (int) ($localization['version'] ?? 0) < 3
                ? true
                : (($localization['automaticLocale'] ?? true) === true);
            if (!$automatic) return;
            $country = $this->public_locale_request_country();
            $preferred = $country !== ''
                ? $this->public_locale_for_country($locales, $country, $default_locale)
                : ($this->public_locale_for_browser($locales) ?? $default_locale);
        }

        $preferred_code = (string) ($preferred['code'] ?? '');
        if ($preferred_code === '' || strcasecmp($preferred_code, (string) ($default_locale['code'] ?? '')) === 0) return;
        $authored_relative = kodety_manifest_relative_for_request(
            $manifest,
            (string) ($locale_request['base_route'] ?? '')
        );
        $localized_target = $authored_relative !== ''
            ? kodety_localization_page_route($authored_relative, $preferred_code, $localization, $manifest)
            : trim((string) ($preferred['slug'] ?? '') . '/' . (string) ($locale_request['base_route'] ?? ''), '/');
        if ($localized_target === '' || trim($localized_target, '/') === trim($request_path, '/')) return;

        $redirect_url = kodety_runtime_public_url(user_trailingslashit($localized_target));
        $query = (string) parse_url($request_uri, PHP_URL_QUERY);
        if ($query !== '') $redirect_url .= '?' . $query;
        nocache_headers();
        if (wp_safe_redirect($redirect_url, 302, 'Onun Kodety Localization')) exit;
    }

    /** Whether the current HTTP request belongs to the public preview namespace. */
    private function is_project_preview_http_request(): bool {
        $request_path = trim(rawurldecode((string) parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH)), '/');
        $home_path = trim((string) parse_url(home_url('/'), PHP_URL_PATH), '/');
        if ($home_path !== '' && ($request_path === $home_path || str_starts_with($request_path, $home_path . '/'))) {
            $request_path = trim(substr($request_path, strlen($home_path)), '/');
        }
        return preg_match('~^kodety/preview/[A-Za-z0-9_-]{24,80}(?:/|$)~', $request_path) === 1;
    }

    /** Allow public, token-scoped preview assets to be embedded from anywhere. */
    public function send_project_preview_cors_headers(): void {
        if (!$this->is_project_preview_http_request() || headers_sent()) return;
        // A user may globally choose X-Frame-Options: DENY, but the random,
        // read-only preview namespace is itself rendered inside Onun Kodety's
        // sandbox when a route needs native query-string semantics.
        header_remove('X-Frame-Options');
        header('Access-Control-Allow-Origin: *', true);
        header('Access-Control-Allow-Methods: GET, HEAD, OPTIONS', true);
        header('Access-Control-Allow-Headers: Accept, Content-Type, Origin, Range', true);
        header('Access-Control-Expose-Headers: Accept-Ranges, Content-Length, Content-Range', true);
        header('Cross-Origin-Resource-Policy: cross-origin', true);
        header('Timing-Allow-Origin: *', true);
        if (strtoupper((string) ($_SERVER['REQUEST_METHOD'] ?? 'GET')) === 'OPTIONS') {
            status_header(204);
            header('Content-Length: 0', true);
            exit;
        }
    }

    /** Preserve preview CORS when WordPress assembles or replaces its header set. */
    public function filter_project_preview_cors_headers(array $headers): array {
        if (!$this->is_project_preview_http_request()) return $headers;
        unset($headers['X-Frame-Options']);
        $headers['Access-Control-Allow-Origin'] = '*';
        $headers['Access-Control-Allow-Methods'] = 'GET, HEAD, OPTIONS';
        $headers['Access-Control-Allow-Headers'] = 'Accept, Content-Type, Origin, Range';
        $headers['Access-Control-Expose-Headers'] = 'Accept-Ranges, Content-Length, Content-Range';
        $headers['Cross-Origin-Resource-Policy'] = 'cross-origin';
        $headers['Timing-Allow-Origin'] = '*';
        return $headers;
    }

    /**
     * YouTube rejects opaque/data-document embeds because they cannot emit an
     * HTTP Referer. Keep the authored Preview isolated, but give YouTube a tiny
     * trusted same-site parent that contains no project HTML or user script.
     */
    public function serve_youtube_embed(): void {
        if ((string) get_query_var('kodety_youtube_embed') !== '1') return;

        $raw_url = isset($_GET['url']) ? trim((string) wp_unslash($_GET['url'])) : '';
        if ($raw_url === '' || strlen($raw_url) > 4096 || preg_match('/[\x00-\x1F\x7F]/', $raw_url)) {
            status_header(400);
            exit;
        }
        if (str_starts_with($raw_url, '//')) $raw_url = 'https:' . $raw_url;
        $embed_url = esc_url_raw($raw_url, ['https']);
        $parts = $embed_url !== '' ? wp_parse_url($embed_url) : false;
        $host = is_array($parts) ? strtolower((string) ($parts['host'] ?? '')) : '';
        $path = is_array($parts) ? (string) ($parts['path'] ?? '') : '';
        $allowed_hosts = [
            'youtube.com',
            'www.youtube.com',
            'youtube-nocookie.com',
            'www.youtube-nocookie.com',
        ];
        if (
            !is_array($parts)
            || strtolower((string) ($parts['scheme'] ?? '')) !== 'https'
            || !in_array($host, $allowed_hosts, true)
            || !preg_match('~^/embed/[A-Za-z0-9_-]+/?$~', $path)
            || isset($parts['user'])
            || isset($parts['pass'])
            || (isset($parts['port']) && (int) $parts['port'] !== 443)
        ) {
            status_header(400);
            exit;
        }

        $home_parts = wp_parse_url(home_url('/'));
        $home_scheme = is_array($home_parts) ? strtolower((string) ($home_parts['scheme'] ?? '')) : '';
        $home_host = is_array($home_parts) ? (string) ($home_parts['host'] ?? '') : '';
        if (!in_array($home_scheme, ['http', 'https'], true) || $home_host === '') {
            status_header(500);
            exit;
        }
        $home_origin = $home_scheme . '://' . $home_host;
        if (!empty($home_parts['port'])) $home_origin .= ':' . (int) $home_parts['port'];
        $embed_url = add_query_arg([
            'origin' => $home_origin,
            'widget_referrer' => $home_origin,
        ], strtok($embed_url, '#'));

        status_header(200);
        nocache_headers();
        header_remove('X-Frame-Options');
        header('Content-Type: text/html; charset=utf-8', true);
        header('X-Content-Type-Options: nosniff', true);
        header('Referrer-Policy: strict-origin-when-cross-origin', true);
        header('Permissions-Policy: accelerometer=*, autoplay=*, clipboard-write=*, encrypted-media=*, fullscreen=*, gyroscope=*, picture-in-picture=*, web-share=*', true);
        header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; frame-src https://youtube.com https://www.youtube.com https://youtube-nocookie.com https://www.youtube-nocookie.com; base-uri 'none'; form-action 'none'; object-src 'none'", true);

        echo '<!doctype html><html><head><meta charset="utf-8"><meta name="referrer" content="strict-origin-when-cross-origin"><meta name="viewport" content="width=device-width,initial-scale=1"><style>html,body,iframe{display:block;width:100%;height:100%;margin:0;border:0;background:#000;overflow:hidden}</style></head><body><iframe title="YouTube" src="'
            . esc_url($embed_url)
            . '" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; fullscreen; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></body></html>';
        exit;
    }

    public function serve_editor_asset(): void {
        $asset = (string) get_query_var('kodety_asset');
        if ($asset === '') return;
        $asset = str_replace('\\', '/', rawurldecode($asset));
        if (str_contains($asset, '../') || str_contains($asset, "\0")) { status_header(400); exit; }
        $root = realpath(KODETY_DIR . 'assets/kodety/layouts');
        $file = realpath(KODETY_DIR . 'assets/kodety/layouts/' . ltrim($asset, '/'));
        if (!$root || !$file || !str_starts_with($file, trailingslashit($root)) || !is_file($file)) { status_header(404); exit; }
        $types = wp_get_mime_types();
        $extension = strtolower(pathinfo($file, PATHINFO_EXTENSION));
        $mime = in_array($extension, ['js', 'mjs', 'cjs'], true) ? 'application/javascript' : 'application/octet-stream';
        foreach ($types as $extensions => $candidate) if (in_array($extension, explode('|', $extensions), true)) { $mime = $candidate; break; }
        header('Content-Type: ' . $mime);
        header('Content-Length: ' . filesize($file));
        header('Cache-Control: public, max-age=31536000, immutable');
        readfile($file);
        exit;
    }

    /** Normalize a browser/project path without making filesystem spelling
     * (NFC vs NFD accents, case or encoded spaces) part of preview correctness. */
    private function preview_path_key(string $path): string {
        $path = trim(str_replace('\\', '/', rawurldecode($path)), '/');
        if (class_exists('Normalizer')) {
            $normalized = Normalizer::normalize($path, Normalizer::FORM_C);
            if (is_string($normalized)) $path = $normalized;
        }
        if (function_exists('remove_accents')) {
            $path = remove_accents($path);
        }
        $path = (string) preg_replace('/\p{Mn}+/u', '', $path);
        $path = (string) preg_replace('~/+~', '/', $path);
        return function_exists('mb_strtolower') ? mb_strtolower($path, 'UTF-8') : strtolower($path);
    }

    /** Atomically replace the derived lookup index. A legacy Settings and an
     * Analytics request may backfill the same immutable workspace under
     * concurrent shared locks; readers must observe either complete version,
     * never a truncated JSON file. */
    private function persist_preview_file_manifest(string $root, array $paths, array $surface_paths): void {
        $paths = array_filter($paths, 'is_string');
        $surface_paths = array_keys($surface_paths);
        sort($surface_paths, SORT_NATURAL | SORT_FLAG_CASE);
        $directory = $root . '/.incode';
        if (!is_dir($directory) && !wp_mkdir_p($directory)) return;
        $manifest = [
            'version' => 3,
            'generatedBy' => 'kodety-server',
            'paths' => $paths,
            'surfacePaths' => $surface_paths,
        ];
        $json_flags = JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE;
        // Runtime/packaging harnesses intentionally load this class without a
        // complete WordPress bootstrap. Keep the derived manifest available in
        // those environments while retaining WordPress' safer encoder in
        // production (notably its invalid UTF-8 recovery).
        $encoded = function_exists('wp_json_encode')
            ? wp_json_encode($manifest, $json_flags)
            : json_encode($manifest, $json_flags);
        if (!is_string($encoded)) return;
        $target = $directory . '/preview-files.json';
        $temporary = tempnam($directory, '.preview-files-');
        if (!is_string($temporary)) {
            file_put_contents($target, $encoded, LOCK_EX);
            return;
        }
        try {
            if (file_put_contents($temporary, $encoded, LOCK_EX) !== strlen($encoded)) return;
            @chmod($temporary, 0644);
            if (@rename($temporary, $target)) {
                $temporary = '';
                return;
            }
            // Some Windows filesystems do not replace an existing destination
            // with rename(). Retain the previous locked-write behavior there.
            file_put_contents($target, $encoded, LOCK_EX);
        } finally {
            if ($temporary !== '' && is_file($temporary)) @unlink($temporary);
        }
    }

    /** Persist the same tolerant file lookup contract used by the Builder.
     * Serving assets then stays O(1) instead of recursively scanning a large
     * draft directory for every image, module, font and video request. */
    private function write_preview_file_manifest(string $root): void {
        if (!is_dir($root)) return;
        $paths = [];
        $surface_paths = [];
        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($root, FilesystemIterator::SKIP_DOTS)
        );
        foreach ($iterator as $entry) {
            if (!$entry instanceof SplFileInfo || !$entry->isFile() || $entry->isLink()) continue;
            $relative = str_replace('\\', '/', substr($entry->getPathname(), strlen($root) + 1));
            if ($relative === '.incode/preview-files.json') continue;
            if ($this->project_surface_includes_file('settings', $relative)) {
                $surface_paths[$relative] = true;
            }
            $key = $this->preview_path_key($relative);
            if ($key === '') continue;
            if (isset($paths[$key]) && $paths[$key] !== $relative) {
                $paths[$key] = null;
                continue;
            }
            if (!array_key_exists($key, $paths)) $paths[$key] = $relative;
        }
        $this->persist_preview_file_manifest($root, $paths, $surface_paths);
    }

    /** Resolve exact paths first, then a unique suffix/basename just like the
     * editor resolver does for ZIPs and folder imports with different roots. */
    private function resolve_preview_file(string $root, array $candidates, bool $write_manifest = true): string|false {
        foreach (array_unique(array_filter(array_map('strval', $candidates))) as $candidate) {
            $resolved = realpath($root . '/' . ltrim($candidate, '/'));
            if ($resolved && is_file($resolved) && str_starts_with($resolved, trailingslashit($root))) return $resolved;
        }

        $manifest_file = $root . '/.incode/preview-files.json';
        $manifest = is_file($manifest_file)
            ? json_decode((string) file_get_contents($manifest_file), true)
            : null;
        $paths = is_array($manifest['paths'] ?? null) ? $manifest['paths'] : [];
        if (!$paths && $write_manifest) {
            $this->write_preview_file_manifest($root);
            $manifest = is_file($manifest_file)
                ? json_decode((string) file_get_contents($manifest_file), true)
                : null;
            $paths = is_array($manifest['paths'] ?? null) ? $manifest['paths'] : [];
        }
        if (!$paths) return false;

        $candidate_keys = array_values(array_unique(array_filter(array_map(
            fn(string $candidate): string => $this->preview_path_key($candidate),
            array_map('strval', $candidates)
        ))));
        foreach ($candidate_keys as $key) {
            $relative = $paths[$key] ?? null;
            if (!is_string($relative) || $relative === '') continue;
            $resolved = realpath($root . '/' . $relative);
            if ($resolved && is_file($resolved) && str_starts_with($resolved, trailingslashit($root))) return $resolved;
        }

        $suffix_matches = [];
        foreach ($paths as $path_key => $relative) {
            if (!is_string($relative) || $relative === '' || str_starts_with($relative, '.incode/')) continue;
            foreach ($candidate_keys as $key) {
                if ($path_key === $key || str_ends_with($path_key, '/' . $key)) {
                    $suffix_matches[$relative] = true;
                    break;
                }
            }
        }
        if (count($suffix_matches) === 1) {
            $relative = (string) array_key_first($suffix_matches);
            $resolved = realpath($root . '/' . $relative);
            if ($resolved && is_file($resolved) && str_starts_with($resolved, trailingslashit($root))) return $resolved;
        }

        $basenames = array_values(array_unique(array_filter(array_map(
            static fn(string $key): string => basename($key),
            $candidate_keys
        ))));
        $basename_matches = [];
        foreach ($paths as $path_key => $relative) {
            if (!is_string($relative) || $relative === '' || str_starts_with($relative, '.incode/')) continue;
            if (in_array(basename($path_key), $basenames, true)) $basename_matches[$relative] = true;
        }
        if (count($basename_matches) !== 1) return false;
        $relative = (string) array_key_first($basename_matches);
        $resolved = realpath($root . '/' . $relative);
        return $resolved && is_file($resolved) && str_starts_with($resolved, trailingslashit($root)) ? $resolved : false;
    }

    /**
     * Keep authored links inside the unguessable preview namespace without
     * replacing their browser semantics. Rewriting href before the default
     * action (rather than cancelling a bubble-phase click and assigning
     * location) preserves target, modifier keys, downloads, hashes and
     * authored handlers. It also closes the failure mode where stopPropagation
     * let a root-relative page link escape into WordPress and render wp-login
     * inside the preview frame.
     */
    private function project_preview_navigation_runtime(
        string $preview_base,
        string $token,
        string $project_site_base = ''
    ): string {
        $site_base = trailingslashit(
            $project_site_base !== '' ? $project_site_base : $this->active_project_site_url()
        );
        return '<script data-kodety-preview-runtime>(function(){'
            . 'var base=new URL(' . wp_json_encode($preview_base) . ');'
            . 'var site=new URL(' . wp_json_encode($site_base) . ');'
            . 'var token=' . wp_json_encode($token) . ';'
            . 'var basePath=base.pathname.replace(/\\/+$/,"/");'
            . 'var sitePath=site.pathname.replace(/\\/+$/,"/");'
            . 'function route(raw){if(!raw||raw.charAt(0)==="#"||/[\\u0000-\\u001f\\u007f]/.test(raw))return null;'
            . 'var scheme=(raw.match(/^([a-z][a-z0-9+.-]*):/i)||[])[1]||"";'
            . 'if(scheme&&!/^https?$/i.test(scheme))return null;try{'
            . 'var u=new URL(raw,document.baseURI||location.href);if(!/^https?:$/i.test(u.protocol)||u.origin!==base.origin)return null;'
            . 'if(u.pathname.indexOf(basePath)===0)return u.href;var path=u.pathname;'
            . 'if(sitePath!=="/"&&path===sitePath.slice(0,-1))path="/";'
            . 'else if(sitePath!=="/"&&path.indexOf(sitePath)===0)path="/"+path.slice(sitePath.length);'
            . 'path=path.replace(/^\\/+/,"");var legacy="kodety/preview/";'
            . 'if(path.indexOf(legacy)===0){path=path.slice(legacy.length);var scoped=token+"/";if(path.indexOf(scoped)===0)path=path.slice(scoped.length)}'
            . 'return new URL(path+u.search+u.hash,base).href}catch(e){return null}}'
            . 'function rewrite(anchor){var raw=anchor.getAttribute("href");var next=route(raw);'
            . 'if(next&&anchor.href!==next)anchor.setAttribute("href",next)}'
            . 'function rewriteTree(root){if(root&&root.matches&&root.matches("a[href],area[href]"))rewrite(root);'
            . 'if(root&&root.querySelectorAll)root.querySelectorAll("a[href],area[href]").forEach(rewrite)}'
            . 'rewriteTree(document);new MutationObserver(function(records){records.forEach(function(record){'
            . 'if(record.type==="attributes")rewrite(record.target);else record.addedNodes.forEach(rewriteTree)})'
            . '}).observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:["href"]});'
            . 'function anchorForEvent(event){var path=typeof event.composedPath==="function"?event.composedPath():[];'
            . 'for(var i=0;i<path.length;i++){var node=path[i];if(node&&node.matches&&node.matches("a[href],area[href]"))return node}'
            . 'var target=event.target&&event.target.closest?event.target:event.target&&event.target.parentElement;'
            . 'return target&&target.closest?target.closest("a[href],area[href]"):null}'
            . '["click","auxclick"].forEach(function(type){window.addEventListener(type,function(event){var anchor=anchorForEvent(event);if(anchor)rewrite(anchor)},true)});'
            . '})();</script>';
    }

    /**
     * Serve the latest draft package as an ordinary isolated website. Unlike
     * the editor srcDoc this route has no selection bridge or event
     * cancellation. Its small link normalizer only keeps internal destinations
     * under the preview token, so authored navigation, targets, downloads,
     * overlays and scripts keep their native browser behavior. The random
     * token is the only public handle; project metadata and hidden editor files
     * are never exposed.
     */
    public function serve_project_preview(): void {
        $token = trim((string) get_query_var('kodety_preview'));
        if ($token === '') return;
        // Re-assert at the final response boundary in case another plugin or
        // the host's WordPress integration rebuilt the header collection.
        $this->send_project_preview_cors_headers();
        $stored_token = (string) get_option('kodety_preview_token', '');
        $snapshot_directory = $stored_token !== '' && hash_equals($stored_token, $token)
            ? ''
            : $this->snapshot_preview_directory($token);
        if (
            !preg_match('/^[A-Za-z0-9_-]{24,80}$/', $token)
            || (($stored_token === '' || !hash_equals($stored_token, $token)) && $snapshot_directory === '')
        ) {
            status_header(404);
            exit;
        }
        // Keep every preview response embeddable, including errors, fonts,
        // modules and range-based media reads.
        header('Access-Control-Allow-Origin: *', true);
        header('Access-Control-Allow-Methods: GET, HEAD, OPTIONS', true);
        header('Access-Control-Allow-Headers: Accept, Content-Type, Origin, Range', true);
        header('Access-Control-Expose-Headers: Accept-Ranges, Content-Length, Content-Range', true);
        header('Cross-Origin-Resource-Policy: cross-origin', true);
        header('Timing-Allow-Origin: *', true);

        $requested = str_replace('\\', '/', rawurldecode((string) get_query_var('kodety_preview_path')));
        $requested = trim($requested, '/');
        $segments = $requested === '' ? [] : explode('/', $requested);
        foreach ($segments as $segment) {
            if ($segment === '' || $segment === '.' || $segment === '..' || str_starts_with($segment, '.')) {
                status_header(404);
                exit;
            }
        }
        if (str_contains($requested, "\0")) {
            status_header(400);
            exit;
        }

        $preview_directory = $snapshot_directory !== ''
            ? $snapshot_directory
            : $this->private_storage_dir() . '/preview/project';
        $root = is_dir($preview_directory) ? realpath($preview_directory) : false;
        if (!$root || !is_dir($root)) {
            status_header(404);
            exit;
        }
        $metadata = [];
        $metadata_file = $root . '/.incode/project.json';
        if (is_file($metadata_file)) {
            $decoded = json_decode((string) file_get_contents($metadata_file), true);
            if (is_array($decoded)) $metadata = $decoded;
        }
        $project_root = trim(str_replace('\\', '/', (string) ($metadata['rootPath'] ?? '')), '/');
        if ($project_root !== '' && (str_contains($project_root, '../') || str_starts_with($project_root, '.'))) {
            $project_root = '';
        }
        $home_page = trim(str_replace('\\', '/', (string) ($metadata['homeHtmlPath'] ?? $metadata['mainHtmlPath'] ?? '')), '/');
        if ($home_page === '' || str_contains($home_page, '../') || str_starts_with($home_page, '.')) {
            $home_page = $project_root !== '' ? $project_root . '/index.html' : 'index.html';
        }
        $candidates = $requested === ''
            ? [$home_page, $project_root . '/index.html', 'index.html', 'index.htm']
            : [
                $requested,
                $requested . '.html',
                $requested . '.htm',
                $requested . '/index.html',
                $requested . '/index.htm',
                $project_root . '/' . $requested,
                $project_root . '/' . $requested . '.html',
                $project_root . '/' . $requested . '/index.html',
            ];
        $file = $this->resolve_preview_file($root, $candidates, $snapshot_directory === '');
        // A tolerant manifest lookup must never turn a public basename into
        // a hidden snapshot document. Historical sources remain immutable.
        if ($file && $snapshot_directory !== '' && preg_match('~(?:^|/)\.~', substr($file, strlen($root) + 1))) {
            $file = false;
        }
        if (!$file) {
            status_header(404);
            header('X-Robots-Tag: noindex, nofollow, noarchive');
            exit;
        }

        $extension = strtolower(pathinfo($file, PATHINFO_EXTENSION));
        $mime = match ($extension) {
            'html', 'htm' => 'text/html; charset=UTF-8',
            'css' => 'text/css; charset=UTF-8',
            'js', 'mjs', 'cjs' => 'application/javascript; charset=UTF-8',
            'json', 'map' => 'application/json; charset=UTF-8',
            'svg' => 'image/svg+xml',
            'webmanifest' => 'application/manifest+json',
            'wasm' => 'application/wasm',
            default => (string) (wp_check_filetype($file)['type'] ?? 'application/octet-stream'),
        };
        if ($mime === '') $mime = 'application/octet-stream';
        status_header(200);
        header('Content-Type: ' . $mime);
        header('X-Robots-Tag: noindex, nofollow, noarchive');
        header('Referrer-Policy: strict-origin');
        header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0', true);
        header('Pragma: no-cache', true);
        header('Expires: Wed, 11 Jan 1984 05:00:00 GMT', true);
        if ($extension === 'svg') {
            // SVG becomes a script-capable document when opened directly.
            // Subresource images remain usable, while top-level SVG routes stay
            // in the same opaque preview boundary as HTML.
            header("Content-Security-Policy: sandbox allow-downloads allow-forms allow-modals allow-popups allow-popups-to-escape-sandbox allow-scripts", true);
        }
        $preview_base = trailingslashit(home_url('/kodety/preview/' . rawurlencode($token)));

        if (!in_array($extension, ['html', 'htm'], true)) {
            $file_size = (int) filesize($file);
            header('Accept-Ranges: bytes');
            $range = (string) ($_SERVER['HTTP_RANGE'] ?? '');
            if ($file_size > 0 && preg_match('/^bytes=(\d*)-(\d*)$/', trim($range), $range_matches)) {
                $start = $range_matches[1] === '' ? 0 : (int) $range_matches[1];
                $end = $range_matches[2] === '' ? $file_size - 1 : (int) $range_matches[2];
                if ($range_matches[1] === '' && $range_matches[2] !== '') {
                    $suffix = min($file_size, max(0, (int) $range_matches[2]));
                    $start = $file_size - $suffix;
                    $end = $file_size - 1;
                }
                if ($start < 0 || $end < $start || $start >= $file_size) {
                    status_header(416);
                    header('Content-Range: bytes */' . $file_size);
                    exit;
                }
                $end = min($end, $file_size - 1);
                $length = $end - $start + 1;
                status_header(206);
                header('Content-Range: bytes ' . $start . '-' . $end . '/' . $file_size);
                header('Content-Length: ' . $length);
                $stream = fopen($file, 'rb');
                if ($stream === false) {
                    status_header(500);
                    exit;
                }
                fseek($stream, $start);
                $remaining = $length;
                while ($remaining > 0 && !feof($stream)) {
                    $chunk = fread($stream, min(1024 * 1024, $remaining));
                    if ($chunk === false || $chunk === '') break;
                    echo $chunk;
                    $remaining -= strlen($chunk);
                }
                fclose($stream);
                exit;
            }
            header('Content-Length: ' . $file_size);
            readfile($file);
            exit;
        }

        $html = (string) file_get_contents($file);
        $navigation_runtime = $this->project_preview_navigation_runtime(
            $preview_base,
            $token,
            $this->active_project_site_url()
        );
        if (stripos($html, '</body>') !== false) {
            $html = preg_replace('/<\/body>/i', $navigation_runtime . '</body>', $html, 1) ?? $html;
        } else {
            $html .= $navigation_runtime;
        }
        // The Builder retains the user-activated about:blank until async
        // packaging finishes. Sever that trusted opener before any authored
        // classic/module script can observe the hosted document.
        $opener_boundary = '<script data-kodety-preview-boundary>try{window.opener=null}catch(e){}</script>';
        if (preg_match('/<head\b[^>]*>/i', $html)) {
            $html = preg_replace('/<head\b[^>]*>/i', '$0' . $opener_boundary, $html, 1) ?? $html;
        } elseif (preg_match('/<!doctype\b[^>]*>/i', $html)) {
            $html = preg_replace('/<!doctype\b[^>]*>/i', '$0' . $opener_boundary, $html, 1) ?? $html;
        } else {
            $html = $opener_boundary . $html;
        }
        // A preview may also be opened as a top-level tab by Cmd/Ctrl/middle
        // click. Keep project JavaScript in an opaque origin there too, not only
        // when the same response is nested in the Builder's sandboxed iframe.
        header("Content-Security-Policy: sandbox allow-downloads allow-forms allow-modals allow-popups allow-popups-to-escape-sandbox allow-scripts", true);
        header('Content-Length: ' . strlen($html));
        echo $html;
        exit;
    }

    /** Stream an explicitly marked member download through WordPress. The
     * encrypted source blob is never redirected or exposed as a public URL. */
    public function serve_membership_asset(): void {
        $asset_id = trim((string) get_query_var('kodety_member_asset'));
        if ($asset_id === '') return;
        $not_found = static function (): void {
            if (function_exists('nocache_headers')) nocache_headers();
            status_header(404);
            exit;
        };
        if (
            class_exists('Kodety_Extensions')
            && !Kodety_Extensions::instance()->is_active('kodety-membership')
        ) {
            $not_found();
        }
        if (
            strtoupper((string) ($_SERVER['REQUEST_METHOD'] ?? 'GET')) !== 'GET'
            || !preg_match('/^asset-[a-f0-9]{24}$/', $asset_id)
            || $this->membership_download_rate_limited(
                'ip',
                substr((string) ($_SERVER['REMOTE_ADDR'] ?? ''), 0, 128),
                120
            )
        ) {
            $not_found();
        }
        $requested_release = trim((string) get_query_var('kodety_member_release'));
        $current_release = (string) get_option('kodety_current_release', '');
        if (
            $current_release === ''
            || $requested_release === ''
            || !hash_equals($current_release, $requested_release)
            || !preg_match('/^[A-Za-z0-9-]{1,96}$/', $current_release)
        ) {
            $not_found();
        }
        $plain = null;
        $download_slot = null;
        try {
            $release_root = $this->releases_dir() . '/' . $current_release . '/project';
            if (!is_dir($release_root)) $not_found();
            $project_root = $this->collapse_single_root($release_root);
            // The generated theme already owns a validated, page-sharded
            // membership index. Loading that small manifest avoids decrypting
            // and revalidating every private page on each download request.
            $runtime = $this->published_membership_download_manifest();
            $asset = is_array($runtime['assets'][$asset_id] ?? null)
                ? $runtime['assets'][$asset_id]
                : null;
            $project_id = (string) ($runtime['projectId'] ?? '');
            if (
                !$asset
                || !$this->membership_download_asset_is_valid($asset_id, $asset)
                || !class_exists('Kodety_Members')
                || !method_exists('Kodety_Members', 'evaluate_access')
                || !method_exists('Kodety_Members', 'current_member_id')
            ) {
                $not_found();
            }
            if (!$this->membership_asset_is_authorized($asset, $project_id)) $not_found();
            $member_id = max(0, (int) Kodety_Members::current_member_id());
            if ($this->membership_download_rate_limited(
                'asset',
                ($member_id > 0 ? 'member:' . $member_id : 'guest') . '|' . $asset_id,
                30
            )) {
                $not_found();
            }
            $download_slot = $this->acquire_membership_download_slot();
            if (!is_resource($download_slot)) $not_found();
            $encrypted = $this->membership_asset_file($project_root, $asset);
            $plain = tempnam(get_temp_dir(), 'kodety-member-file-');
            if (!is_string($plain)) throw new RuntimeException('Não foi possível preparar o download.');
            @unlink($plain);
            $this->open_membership_asset($encrypted, $plain, $asset, $project_id);
            // A plan can be revoked while a large blob is being decrypted.
            if (!$this->membership_asset_is_authorized($asset, $project_id)) {
                throw new RuntimeException('O acesso ao download foi revogado.');
            }
            $filename = sanitize_file_name((string) ($asset['filename'] ?? 'download'));
            if ($filename === '') $filename = 'download';
            if (function_exists('nocache_headers')) nocache_headers();
            header('Content-Type: application/octet-stream');
            header('Content-Disposition: attachment; filename="' . str_replace('"', '', $filename) . '"; filename*=UTF-8\'\'' . rawurlencode($filename));
            header('Content-Length: ' . (string) filesize($plain));
            header('Cache-Control: private, no-store, no-cache, must-revalidate, max-age=0', true);
            header('Pragma: no-cache', true);
            header('Vary: Cookie', false);
            header('X-Content-Type-Options: nosniff', true);
            readfile($plain);
            @unlink($plain);
            $this->release_membership_download_slot($download_slot);
            exit;
        } catch (Throwable $error) {
            if (is_string($plain) && is_file($plain)) @unlink($plain);
            $this->release_membership_download_slot($download_slot);
            error_log('[Onun Kodety] Download protegido recusado: ' . $error->getMessage());
            $not_found();
        }
    }

    /** Bound expensive authenticated decryptions independently of browser UA. */
    private function membership_download_rate_limited(
        string $scope,
        string $identity,
        int $default_limit
    ): bool {
        $key = 'kodety_mem_dl_' . substr(hash_hmac(
            'sha256',
            $scope . '|' . $identity,
            wp_salt('nonce')
        ), 0, 36);
        $lock = @fopen(sys_get_temp_dir() . '/.' . $key . '.lock', 'c');
        if (is_resource($lock)) @flock($lock, LOCK_EX);
        try {
            $state = get_transient($key);
            $state = is_array($state) ? $state : ['count' => 0, 'started' => time()];
            $window = 10 * MINUTE_IN_SECONDS;
            if ((int) ($state['started'] ?? 0) <= time() - $window) {
                $state = ['count' => 0, 'started' => time()];
            }
            $limit = max(5, min(500, (int) apply_filters(
                'kodety_membership_download_rate_limit',
                $default_limit,
                $scope
            )));
            if ((int) ($state['count'] ?? 0) >= $limit) return true;
            $state['count'] = (int) ($state['count'] ?? 0) + 1;
            set_transient($key, $state, $window + MINUTE_IN_SECONDS);
            return false;
        } finally {
            if (is_resource($lock)) {
                @flock($lock, LOCK_UN);
                fclose($lock);
            }
        }
    }

    /** @return array<string,mixed> */
    private function published_membership_download_manifest(): array {
        if (
            !function_exists('wp_get_theme')
            || wp_get_theme()->get_stylesheet() !== 'kodety-generated'
        ) {
            return [];
        }
        $path = rtrim(get_template_directory(), '/\\') . '/membership-content.php';
        if (!is_file($path)) return [];
        try {
            $candidate = include $path;
        } catch (Throwable) {
            return [];
        }
        if (
            !is_array($candidate)
            || (int) ($candidate['version'] ?? 0) !== 1
            || ($candidate['enabled'] ?? false) !== true
            || !is_array($candidate['assets'] ?? null)
            || count($candidate['assets']) > 500
        ) {
            return [];
        }
        $project_id = strtolower(trim((string) ($candidate['projectId'] ?? '')));
        $published_project_id = strtolower(trim((string) get_option(
            'kodety_published_project_id',
            ''
        )));
        $release = trim((string) ($candidate['release'] ?? ''));
        $current_release = trim((string) get_option('kodety_current_release', ''));
        if (
            !preg_match('/^[a-z0-9][a-z0-9_-]{0,95}$/', $project_id)
            || $published_project_id === ''
            || !hash_equals($published_project_id, $project_id)
            || $release === ''
            || $current_release === ''
            || !hash_equals($current_release, $release)
        ) {
            return [];
        }
        return $candidate;
    }

    /** @param array<string,mixed> $asset */
    private function membership_download_asset_is_valid(string $asset_id, array $asset): bool {
        $source_path = ltrim(str_replace(
            '\\',
            '/',
            (string) ($asset['sourcePath'] ?? '')
        ), '/');
        $contexts = is_array($asset['contexts'] ?? null) ? $asset['contexts'] : [];
        if (
            !preg_match('/^asset-[a-f0-9]{24}$/', $asset_id)
            || !hash_equals($asset_id, (string) ($asset['id'] ?? ''))
            || !$this->membership_authored_asset_path_is_valid($source_path)
            || (string) ($asset['storagePath'] ?? '')
                !== '.incode/membership/assets/' . $asset_id . '.bin'
            || (int) ($asset['size'] ?? 0) <= 0
            || (int) ($asset['size'] ?? 0) > self::MEMBERSHIP_MAX_PROTECTED_ASSET_BYTES
            || !preg_match('/^[a-f0-9]{64}$/', (string) ($asset['sha256'] ?? ''))
            || (string) ($asset['encryption']['algorithm'] ?? '')
                !== 'aes-256-gcm-chunked-v1'
            || (int) ($asset['encryption']['chunkSize'] ?? 0) !== 1024 * 1024
            || trim((string) ($asset['filename'] ?? '')) === ''
            || strlen((string) ($asset['filename'] ?? '')) > 255
            || !$contexts
            || count($contexts) > 100
        ) {
            return false;
        }
        foreach ($contexts as $context) {
            $rules = is_array($context) && is_array($context['allOf'] ?? null)
                ? $context['allOf']
                : [];
            if (!$rules || count($rules) > 64) return false;
            foreach ($rules as $rule) {
                if (!is_array($rule) || !$this->membership_access_rule_is_valid($rule)) {
                    return false;
                }
            }
        }
        return true;
    }

    /** @param array<string,mixed> $asset */
    private function membership_asset_is_authorized(array $asset, string $project_id): bool {
        if (
            !class_exists('Kodety_Members')
            || !method_exists('Kodety_Members', 'evaluate_access')
            || !method_exists('Kodety_Members', 'current_member_id')
        ) {
            return false;
        }
        $member_id = max(0, (int) Kodety_Members::current_member_id());
        foreach ((array) ($asset['contexts'] ?? []) as $context) {
            if (!is_array($context) || !is_array($context['allOf'] ?? null)) continue;
            $allowed = true;
            foreach ($context['allOf'] as $rule) {
                if (!is_array($rule)) {
                    $allowed = false;
                    break;
                }
                $decision = Kodety_Members::evaluate_access(
                    $rule,
                    $member_id ?: null,
                    $project_id
                );
                if (!is_array($decision) || ($decision['allowed'] ?? false) !== true) {
                    $allowed = false;
                    break;
                }
            }
            if ($allowed) return true;
        }
        return false;
    }

    /** @return resource|null */
    private function acquire_membership_download_slot(): mixed {
        $site = substr(hash_hmac('sha256', home_url('/'), wp_salt('nonce')), 0, 16);
        for ($slot = 0; $slot < 4; $slot += 1) {
            $handle = @fopen(
                sys_get_temp_dir() . '/.kodety-member-download-' . $site . '-' . $slot,
                'c'
            );
            if (!is_resource($handle)) continue;
            if (@flock($handle, LOCK_EX | LOCK_NB)) return $handle;
            fclose($handle);
        }
        return null;
    }

    /** @param resource|null $slot */
    private function release_membership_download_slot(mixed $slot): void {
        if (!is_resource($slot)) return;
        @flock($slot, LOCK_UN);
        fclose($slot);
    }

    /** Browser isolation is an explicit preference for private Agent surfaces. */
    public function browser_agent_runtime_requested(): bool {
        $app = get_query_var('kodety_app');
        if (!is_string($app) || !in_array($app, ['editor', 'settings'], true)
            || (string) get_query_var('kodety_share') !== ''
            || (class_exists('Kodety_Sharing') && Kodety_Sharing::instance()->context())
            || !current_user_can(self::CAP_USE_AI)) {
            return false;
        }
        // Any explicit query value wins, including "server" or an invalid
        // value. An invalid query must not fall back to an older browser cookie.
        $selection = array_key_exists('kodety_agent_runtime', $_GET)
            ? $_GET['kodety_agent_runtime']
            : ($_COOKIE['kodety_agent_runtime'] ?? null);
        return is_string($selection) && wp_unslash($selection) === 'webcontainer';
    }

    public function app_template(string $template): string {
        $agency_site = sanitize_key((string) get_query_var('kodety_agency_site'));
        if ($agency_site !== '' && (string) get_query_var('kodety_agency_asset') === '') {
            global $wp_query;
            if ($wp_query instanceof WP_Query) $wp_query->is_404 = false;
            status_header(200);
            return get_template_directory() . '/index.php';
        }
        $app = sanitize_key((string) get_query_var('kodety_app'));
        if ($app === '') return $template;
        $share_requested = (string) get_query_var('kodety_share') !== '';
        $share = class_exists('Kodety_Sharing') ? Kodety_Sharing::instance()->context() : null;
        if ($share_requested && !$share) {
            wp_die(
                'Este link de compartilhamento é inválido ou foi revogado.',
                'Compartilhamento indisponível',
                ['response' => 403, 'back_link' => false]
            );
        }
        if ($share && !Kodety_Sharing::instance()->is_accessible()) {
            $message = !empty($share['authRequired']) && !is_user_logged_in()
                ? 'Este compartilhamento exige uma conta já autenticada. Abra o link depois de entrar no WordPress em outra guia.'
                : 'Este projeto não está disponível nesta sessão do workspace.';
            wp_die(
                esc_html($message),
                'Compartilhamento restrito',
                ['response' => 403, 'link_url' => '', 'back_link' => false]
            );
        }
        if (!$share && !is_user_logged_in()) {
            auth_redirect();
            exit;
        }
        if ($app === 'admin') { wp_safe_redirect(admin_url()); exit; }
        $builder_apps = $this->builder_apps();
        $definition = is_array($builder_apps[$app] ?? null) ? $builder_apps[$app] : null;
        if (!$definition) {
            wp_die('Esta área do Builder não existe.', 'Área indisponível', ['response' => 404]);
        }
        if ($share && empty($definition['shared'])) {
            wp_die('Esta área não está disponível neste compartilhamento.', 'Área indisponível', ['response' => 403, 'link_url' => '', 'back_link' => false]);
        }
        $required_extension = (string) ($definition['extension'] ?? '');
        if (
            $required_extension !== ''
            && class_exists('Kodety_Extensions')
            && !Kodety_Extensions::instance()->is_active($required_extension)
        ) {
            wp_die(
                $share
                    ? 'Esta área não está disponível neste compartilhamento.'
                    : 'Esta área está desativada. Ative a extensão correspondente em Onun Kodety → Extensões.',
                'Extensão Onun Kodety inativa',
                $share
                    ? ['response' => 503, 'link_url' => '', 'back_link' => false]
                    : ['response' => 503, 'link_url' => admin_url('admin.php?page=kodety#kodety-extensions')]
            );
        }
        $required_capability = (string) ($definition['capability'] ?? self::CAP_EDIT_WORKSPACE);
        if (!current_user_can($required_capability)) {
            wp_die('Você não possui permissão para acessar esta área do Onun Kodety.', 'Acesso negado', ['response' => 403]);
        }
        status_header(200);
        nocache_headers();
        if ($this->browser_agent_runtime_requested() && !headers_sent()) {
            header('Cross-Origin-Opener-Policy: same-origin', true);
            header('Cross-Origin-Embedder-Policy: credentialless', true);
        }
        return KODETY_DIR . 'templates/editor-shell.php';
    }

