            [
                'methods' => 'POST',
                'callback' => [$this, 'create_cms_item'],
                'permission_callback' => fn(): bool => current_user_can(self::CAP_ACCESS_CMS),
            ],
        ]);
        register_rest_route('kodety/v1', '/cms/items/(?P<post_type>[a-zA-Z0-9_-]+)/import', [
            'methods' => 'POST',
            'callback' => [$this, 'import_cms_items'],
            'permission_callback' => fn(): bool => current_user_can(self::CAP_ACCESS_CMS),
        ]);
        register_rest_route('kodety/v1', '/cms/items/(?P<post_type>[a-zA-Z0-9_-]+)/(?P<post_id>\d+)', [
            [
                'methods' => 'GET',
                'callback' => [$this, 'cms_item'],
                'permission_callback' => fn(WP_REST_Request $request): bool|WP_Error =>
                    $this->can_access_cms_item($request, 'read'),
            ],
            [
                'methods' => 'POST',
                'callback' => [$this, 'update_cms_item'],
                'permission_callback' => fn(WP_REST_Request $request): bool|WP_Error =>
                    $this->can_access_cms_item($request, 'edit'),
            ],
            [
                'methods' => 'DELETE',
                'callback' => [$this, 'delete_cms_item'],
                'permission_callback' => fn(WP_REST_Request $request): bool|WP_Error =>
                    $this->can_access_cms_item($request, 'delete'),
            ],
        ]);
    }

    /** Return 404 for a sibling item before map_meta_cap can turn it into 403. */
    public function can_access_cms_item(WP_REST_Request $request, string $operation = 'edit'): bool|WP_Error {
        if (!current_user_can(self::CAP_ACCESS_CMS)) return false;
        $post_type = sanitize_key((string) $request['post_type']);
        $post_id = absint($request['post_id']);
        $post = get_post($post_id);
        if (
            !$post instanceof WP_Post
            || $post->post_type !== $post_type
            || !$this->cms_item_belongs_to_current_project($post_id, $post_type)
        ) {
            return new WP_Error('kodety_invalid_item', 'Item inválido.', ['status' => 404]);
        }
        if ($operation === 'read') return current_user_can('read_post', $post_id);
        return current_user_can($operation === 'delete' ? 'delete_post' : 'edit_post', $post_id);
    }

    /**
     * Proxy the Google Fonts metadata through WordPress. The browser endpoint
     * does not allow arbitrary origins, while this authenticated same-origin
     * route can keep a durable last-known-good catalog for offline host hiccups.
     */
    public function google_fonts_catalog(): WP_REST_Response|WP_Error {
        $cached = get_transient('kodety_google_fonts_catalog');
        if (is_array($cached) && $cached) {
            $response = new WP_REST_Response(['data' => $cached]);
            $response->header('Cache-Control', 'private, max-age=3600');
            return $response;
        }
        $stored = get_option('kodety_google_fonts_catalog_cache', []);
        $stored_fonts = is_array($stored) && is_array($stored['fonts'] ?? null)
            ? $stored['fonts']
            : [];
        $remote = wp_remote_get('https://fonts.google.com/metadata/fonts', [
            'timeout' => 20,
            'redirection' => 3,
            'headers' => [
                'Accept' => 'application/json',
                'User-Agent' => 'Onun Kodety/' . KODETY_VERSION . '; ' . home_url('/'),
            ],
        ]);
        if (is_wp_error($remote)) {
            if ($stored_fonts) return new WP_REST_Response(['data' => $stored_fonts, 'stale' => true]);
            return new WP_Error('kodety_google_fonts_unavailable', 'O catálogo do Google Fonts está temporariamente indisponível.', ['status' => 503]);
        }
        $status = (int) wp_remote_retrieve_response_code($remote);
        $body = trim((string) wp_remote_retrieve_body($remote));
        if ($status < 200 || $status >= 300 || $body === '' || strlen($body) > 20 * MB_IN_BYTES) {
            if ($stored_fonts) return new WP_REST_Response(['data' => $stored_fonts, 'stale' => true]);
            return new WP_Error('kodety_google_fonts_invalid_response', 'O Google Fonts não retornou um catálogo válido.', ['status' => 502]);
        }
        if (str_starts_with($body, ")]}'")) {
            $newline = strpos($body, "\n");
            $body = $newline === false ? substr($body, 4) : substr($body, $newline + 1);
        }
        $payload = json_decode($body, true);
        // Google renamed the live catalog key from `family` to
        // `familyMetadataList`. Keep the legacy key as a compatibility path so
        // cached/proxied responses from either schema continue to work.
        $families = is_array($payload) && is_array($payload['familyMetadataList'] ?? null)
            ? $payload['familyMetadataList']
            : (is_array($payload) && is_array($payload['family'] ?? null)
                ? $payload['family']
                : []);
        $fonts = [];
        foreach ($families as $family) {
            if (!is_array($family)) continue;
            $name = sanitize_text_field((string) ($family['family'] ?? ''));
            if ($name === '') continue;
            $variants = [];
            if (is_array($family['fonts'] ?? null)) foreach (array_keys($family['fonts']) as $raw_variant) {
                $variant = sanitize_text_field((string) $raw_variant);
                if ($variant === '') continue;
                // Current metadata uses `400i`; the CSS loader and picker use
                // the public Google Fonts vocabulary (`regular`,
                // `400italic`, ...).
                if (preg_match('/^(\d+)i$/', $variant, $match)) $variant = $match[1] . 'italic';
                elseif ($variant === '400') $variant = 'regular';
                $variants[] = $variant;
            }
            $axes = [];
            if (is_array($family['axes'] ?? null)) foreach ($family['axes'] as $axis) {
                if (!is_array($axis)) continue;
                $tag = sanitize_key((string) ($axis['tag'] ?? ''));
                $raw_start = $axis['start'] ?? $axis['min'] ?? null;
                $raw_end = $axis['end'] ?? $axis['max'] ?? null;
                $start = is_numeric($raw_start) ? (float) $raw_start : null;
                $end = is_numeric($raw_end) ? (float) $raw_end : null;
                if ($tag !== '' && $start !== null && $end !== null) {
                    $axes[] = ['tag' => $tag, 'start' => $start, 'end' => $end];
                }
            }
            $category = strtolower(trim((string) ($family['category'] ?? 'sans-serif')));
            $category = str_replace([' ', '_'], '-', $category);
            if (!in_array($category, ['serif', 'sans-serif', 'display', 'handwriting', 'monospace'], true)) {
                $category = 'sans-serif';
            }
            $entry = [
                'family' => $name,
                'variants' => $variants ?: ['regular'],
                'category' => $category,
            ];
            if ($axes) $entry['axes'] = $axes;
            $fonts[] = $entry;
        }
        if (!$fonts) {
            if ($stored_fonts) return new WP_REST_Response(['data' => $stored_fonts, 'stale' => true]);
            return new WP_Error('kodety_google_fonts_empty', 'O catálogo do Google Fonts veio vazio.', ['status' => 502]);
        }
        set_transient('kodety_google_fonts_catalog', $fonts, 12 * HOUR_IN_SECONDS);
        update_option('kodety_google_fonts_catalog_cache', [
            'updatedAt' => current_time('c'),
            'fonts' => $fonts,
        ], false);
        $response = new WP_REST_Response(['data' => $fonts]);
        $response->header('Cache-Control', 'private, max-age=3600');
        return $response;
    }

    /** Theme activation and cache-wide mutations are administrator operations. */
    public function can_publish(): bool {
        return !is_multisite()
            && current_user_can('kodety_publish')
            && current_user_can('edit_theme_options');
    }

    public function register_collections(): void {
        $definitions = $this->collection_definitions();
        if ($this->workspace_mode() === 'agency') {
            foreach (array_keys($this->agency_projects()) as $project_id) {
                foreach ($this->collection_definitions(sanitize_key((string) $project_id)) as $definition) {
                    $definitions[] = $definition;
                }
            }
        }
        foreach ($definitions as $definition) {
            $slug = sanitize_key((string) ($definition['slug'] ?? ''));
            if ($slug === '') continue;
            $rest_filter = 'rest_pre_insert_' . $slug;
            if (
                function_exists('add_filter')
                && (!function_exists('has_filter') || has_filter($rest_filter, [$this, 'enforce_free_rest_item_limit']) === false)
            ) {
                add_filter($rest_filter, [$this, 'enforce_free_rest_item_limit'], 10, 2);
            }
            if (post_type_exists($slug)) continue;
            $singular = sanitize_text_field((string) ($definition['singular'] ?? $definition['name'] ?? $slug));
            $plural = sanitize_text_field((string) ($definition['name'] ?? $singular));
            register_post_type($slug, [
                'labels' => ['name' => $plural, 'singular_name' => $singular, 'add_new_item' => 'Adicionar ' . $singular, 'edit_item' => 'Editar ' . $singular],
                'public' => true,
                'show_ui' => true,
                'show_in_menu' => false,
                'show_in_admin_bar' => false,
                'show_in_rest' => true,
                'rest_base' => $slug,
                'supports' => ['title', 'editor', 'excerpt', 'thumbnail', 'revisions', 'custom-fields'],
                'has_archive' => true,
                // Explicit meta-cap mapping is what lets Author/Contributor
                // ownership work identically in native wp-admin and Onun Kodety CMS.
                'capability_type' => 'post',
                'map_meta_cap' => true,
                'capabilities' => !empty($definition['readOnly'])
                    ? ['create_posts' => 'do_not_allow']
                    : [],
                // Keep the registered rewrite base aligned with cms_route_base(),
                // which resolves urlSlug -> name -> slug in that order.
                'rewrite' => ['slug' => sanitize_title((string) ($definition['urlSlug'] ?? $definition['name'] ?? $slug))],
                'menu_icon' => 'dashicons-database',
            ]);
        }
    }

    public function cms_types(): WP_REST_Response {
        $definitions = $this->collection_definitions();
        $collection_slugs = array_column($definitions, 'slug');
        $definitions_by_slug = [];
        foreach ($definitions as $definition) {
            $definition_slug = sanitize_key((string) ($definition['slug'] ?? ''));
            if ($definition_slug !== '') $definitions_by_slug[$definition_slug] = $definition;
        }
        $items = [];
        foreach (get_post_types(['show_in_rest' => true], 'objects') as $type) {
            if (in_array($type->name, ['attachment', 'nav_menu_item', 'wp_block', 'wp_template', 'wp_template_part', 'wp_navigation', 'wp_global_styles', 'wp_font_family', 'wp_font_face'], true)) continue;
            if ($this->is_project_collection_outside_current_scope($type->name)) continue;
            if (!current_user_can($type->cap->edit_posts)) continue;
            $is_collection = in_array($type->name, $collection_slugs, true);
            $items[] = [
                'slug' => $type->name,
                'name' => $type->labels->name,
                'singular' => $type->labels->singular_name,
                'restBase' => $type->rest_base ?: match ($type->name) { 'post' => 'posts', 'page' => 'pages', default => $type->name },
                'collection' => $is_collection,
                'itemCount' => $is_collection ? $this->cms_collection_item_count($type->name) : null,
                'urlSlug' => $is_collection
                    ? sanitize_title((string) ($definitions_by_slug[$type->name]['urlSlug'] ?? $type->rewrite['slug'] ?? $type->name))
                    : null,
                'readOnly' => $this->cms_collection_read_only($type->name),
                'capabilities' => [
                    'create' => !$this->cms_collection_read_only($type->name)
                        && current_user_can($type->cap->create_posts ?? $type->cap->edit_posts),
                    'publish' => !$this->cms_collection_read_only($type->name)
                        && current_user_can($type->cap->publish_posts ?? 'publish_posts'),
                ],
            ];
        }
        return new WP_REST_Response([
            'types' => $items,
            'revision' => $this->cms_schema_revision(),
        ]);
    }

    /** Hide project-owned posts from direct core REST item endpoints. */
    public function protect_project_cms_rest_item(
        mixed $response,
        mixed $handler,
        WP_REST_Request $request
    ): mixed {
        if (is_wp_error($response)) return $response;
        $route = method_exists($request, 'get_route') ? (string) $request->get_route() : '';
        if (!str_starts_with($route, '/wp/v2/')) return $response;
        $route_parts = explode('/', trim($route, '/'));
        if (count($route_parts) < 4 || !ctype_digit((string) $route_parts[3])) return $response;
        $post_id = absint($route_parts[3]);
        if ($post_id <= 0) return $response;
        $post = get_post($post_id);
        if (!$post instanceof WP_Post) return $response;
        $type = get_post_type_object($post->post_type);
        $rest_base = $type instanceof WP_Post_Type
            ? sanitize_key((string) ($type->rest_base ?: $type->name))
            : '';
        if ($rest_base === '' || $rest_base !== sanitize_key(rawurldecode((string) $route_parts[2]))) {
            return $response;
        }
        $is_project_item = metadata_exists('post', $post_id, '_kodety_project_id')
            || $this->is_project_collection($post->post_type)
            || $this->is_project_collection_outside_current_scope($post->post_type);
        if (!$is_project_item || $this->cms_item_belongs_to_current_project($post_id, $post->post_type)) {
            return $response;
        }
        return new WP_Error('rest_post_invalid_id', 'ID de item inválido.', ['status' => 404]);
    }

    /** Guard native collection REST endpoints in addition to Onun Kodety's own API. */
    public function enforce_free_rest_item_limit(mixed $prepared_post, WP_REST_Request $request): mixed {
        $post_type = sanitize_key((string) ($prepared_post->post_type ?? $request->get_param('type') ?? ''));
        if ($this->is_project_collection_outside_current_scope($post_type)) {
            return new WP_Error('kodety_invalid_post_type', 'Tipo de conteúdo inválido.', ['status' => 404]);
        }
        if (!Kodety_Edition::is_unlicensed()) return $prepared_post;
        $post_id = (int) ($prepared_post->ID ?? $request->get_param('id') ?? 0);
        if ($post_id > 0 || !$this->is_managed_collection($post_type)) return $prepared_post;
        return Kodety_Edition::item_limit_error($post_type) ?: $prepared_post;
    }

    /**
     * Last-resort guard for native wp-admin and direct wp_insert_post() calls.
     * Returning true makes WordPress reject the insert without mutating data.
     */
    public function enforce_free_item_limit_on_insert(bool $maybe_empty, array $postarr): bool {
        if ($maybe_empty) return true;
        $post_type = sanitize_key((string) ($postarr['post_type'] ?? 'post'));
        if ($this->is_project_collection_outside_current_scope($post_type)) return true;
        if (!Kodety_Edition::is_unlicensed()) return false;
        if (!$this->is_managed_collection($post_type)) return $maybe_empty;
        $status = sanitize_key((string) ($postarr['post_status'] ?? 'draft'));
        if (in_array($status, ['trash', 'auto-draft', 'inherit'], true)) return $maybe_empty;
        $post_id = (int) ($postarr['ID'] ?? 0);
        if ($post_id > 0) {
            $previous_status = get_post_status($post_id);
            if (!in_array($previous_status, ['trash', 'auto-draft', 'inherit'], true)) return $maybe_empty;
        }
        return Kodety_Edition::item_limit_error($post_type) !== null;
    }

    public function cms_collections(): WP_REST_Response {
        return new WP_REST_Response($this->collection_definitions());
    }

    /** @return list<int> Active item IDs visible to the current project. */
    private function cms_collection_item_ids(string $post_type): array {
        $post_statuses = function_exists('get_post_stati')
            ? array_values(array_diff(get_post_stati(), ['trash', 'auto-draft', 'inherit']))
            : ['publish', 'draft', 'pending', 'future', 'private'];
        $query = [
            'post_type' => sanitize_key($post_type),
            'post_status' => $post_statuses,
            'posts_per_page' => -1,
            'fields' => 'ids',
            'orderby' => 'ID',
            'order' => 'ASC',
            'no_found_rows' => true,
        ];
        $project_id = $this->cms_project_scope_key();
        if ($project_id !== '') {
            $query['meta_query'] = [
                [
                    'key' => '_kodety_project_id',
                    'value' => $project_id,
                    'compare' => '=',
                ],
            ];
        } else {
            $query['meta_query'] = [[
                'key' => '_kodety_project_id',
                'compare' => 'NOT EXISTS',
            ]];
        }
        $post_ids = get_posts($query);
        return array_values(array_filter(array_map('absint', is_array($post_ids) ? $post_ids : [])));
    }

    private function cms_collection_item_count(string $post_type): int {
        return count($this->cms_collection_item_ids($post_type));
    }

    /** WordPress returns false both for an unchanged option and for a failed
     * write. The persisted value, not that ambiguous boolean, is the ACK. */
    private function write_cms_option_with_ack(string $option, array $value): bool {
        $option = $this->project_cms_option_name($option);
        update_option($option, $value, false);
        $stored = get_option($option, null);
        return is_array($stored) && $this->cms_persisted_values_match($stored, $value, false);
    }

    /** Write template state to its destination without consulting the mounted workspace. */
    private function write_cms_option_for_scope_with_ack(
        string $option,
        array $value,
        string $project_id
    ): bool {
        $project_id = sanitize_key($project_id);
        if (
            $project_id !== ''
            && in_array($option, ['kodety_collections', 'kodety_field_definitions', 'kodety_cms_templates'], true)
        ) {
            $option .= '__project_' . $project_id;
        }
        update_option($option, $value, false);
        $stored = get_option($option, null);
        return is_array($stored) && $this->cms_persisted_values_match($stored, $value, false);
    }

    /** Serialize Onun Kodety CMS compare-and-swap writers across PHP workers. */
    private function with_cms_mutation_lock(callable $operation): mixed {
        if ($this->cms_lock_depth > 0) {
            $this->cms_lock_depth++;
            try {
                return $operation();
            } finally {
                $this->cms_lock_depth--;
            }
        }
        $uploads = function_exists('wp_get_upload_dir') ? wp_get_upload_dir() : [];
        $base = is_array($uploads) ? (string) ($uploads['basedir'] ?? '') : '';
        if ($base === '') $base = sys_get_temp_dir();
        $directory = rtrim($base, '/\\') . '/kodety/private/cms';
        $created = function_exists('wp_mkdir_p') ? wp_mkdir_p($directory) : (is_dir($directory) || mkdir($directory, 0777, true));
        if (!$created || !is_dir($directory)) {
            return new WP_Error(
                'kodety_cms_lock_unavailable',
                'O CMS está temporariamente indisponível porque o bloqueio transacional não pôde ser criado.',
                ['status' => 503]
            );
        }
        $handle = fopen($directory . '/.write.lock', 'c+');
        if (!$handle || !flock($handle, LOCK_EX)) {
            if (is_resource($handle)) fclose($handle);
            return new WP_Error(
                'kodety_cms_lock_unavailable',
                'O CMS está temporariamente indisponível porque o bloqueio transacional não pôde ser adquirido.',
                ['status' => 503]
            );
        }
        $this->cms_lock_handle = $handle;
        $this->cms_lock_depth = 1;
        try {
            if (function_exists('wp_cache_delete')) {
                foreach (['alloptions', 'notoptions', 'kodety_workspace_project_id'] as $option) wp_cache_delete($option, 'options');
                foreach (['kodety_collections', 'kodety_field_definitions', 'kodety_cms_templates'] as $option) {
                    wp_cache_delete($this->project_cms_option_name($option), 'options');
                }
            }
            return $operation();
        } finally {
            $this->cms_lock_depth = 0;
            $this->cms_lock_handle = null;
            flock($handle, LOCK_UN);
            fclose($handle);
        }
    }

    private function cms_workspace_project_id(): string {
        $project_id = (string) get_option('kodety_workspace_project_id', '');
        return function_exists('sanitize_key')
            ? sanitize_key($project_id)
            : (preg_replace('/[^a-z0-9_-]/', '', strtolower($project_id)) ?: '');
    }

    private function cms_revision_scope(): string {
        $project_id = $this->workspace_mode() === 'agency'
            ? ((function_exists('is_admin') && is_admin())
                ? $this->agency_active_project_id()
                : $this->cms_project_scope_key())
            : $this->cms_workspace_project_id();
        return $project_id !== '' ? 'workspace:' . $project_id : 'workspace:legacy-single';
    }

    private function cms_revision_token(string $resource, mixed $state): string {
        return 'kodety-cms-v1-' . hash('sha256', serialize([
            'resource' => $resource,
            'scope' => $this->cms_revision_scope(),
            'state' => $state,
        ]));
    }

    private function cms_schema_revision(): string {
        return $this->cms_revision_token('schema', [
            'collections' => $this->project_cms_option('kodety_collections', []),
            'fields' => $this->project_cms_option('kodety_field_definitions', []),
            'templates' => $this->project_cms_option('kodety_cms_templates', []),
        ]);
    }

    /** @return array<string,mixed> */
    private function cms_schema_current(): array {
        return [
            'collections' => $this->collection_definitions(),
            'fields' => is_array($this->project_cms_option('kodety_field_definitions', []))
                ? $this->project_cms_option('kodety_field_definitions', [])
                : [],
            'templates' => $this->cms_template_definitions(),
        ];
    }

    private function cms_item_revision(WP_Post $post): string {
        $thumbnail_id = (int) get_post_thumbnail_id($post);
        $custom_values = [];
        foreach ($this->custom_field_definitions($post->post_type) as $field) {
            $custom_values[(string) $field['name']] = get_post_meta($post->ID, (string) $field['name'], true);
        }
        $acf_values = function_exists('get_fields') ? get_fields($post->ID) : [];
        return $this->cms_revision_token('item:' . $post->post_type . ':' . $post->ID, [
            'id' => $post->ID,
            'type' => $post->post_type,
            'title' => $post->post_title,
            'excerpt' => $post->post_excerpt,
            'content' => $post->post_content,
            'status' => $post->post_status,
            'slug' => $post->post_name,
            'author' => (int) $post->post_author,
            'modifiedGmt' => (string) ($post->post_modified_gmt ?? ''),
            'projectId' => sanitize_key((string) get_post_meta($post->ID, '_kodety_project_id', true)),
            'thumbnailId' => $thumbnail_id,
            'thumbnailAlt' => $thumbnail_id > 0
                ? (string) get_post_meta($thumbnail_id, '_wp_attachment_image_alt', true)
                : '',
            'custom' => $custom_values,
            'acf' => is_array($acf_values) ? $acf_values : [],
        ]);
    }

    private function cms_expected_revision_error(
        WP_REST_Request $request,
        string $resource,
        string $revision,
        mixed $current
    ): ?WP_Error {
        $raw_expected = $request->get_param('expectedRevision');
        $expected = is_string($raw_expected) ? trim($raw_expected) : '';
        if ($expected === '') {
            return new WP_Error(
                'kodety_revision_required',
                'Leia o recurso novamente e envie expectedRevision antes de salvar.',
                [
                    'status' => 400,
                    'resource' => $resource,
                    'expectedRevision' => null,
                    'revision' => $revision,
                    'current' => $current,
                ]
            );
        }
        if (strlen($expected) <= 160 && hash_equals($revision, $expected)) return null;
        return new WP_Error(
            'kodety_revision_conflict',
            'O recurso mudou em outra aba. Atualize os dados e tente novamente.',
            [
                'status' => 409,
                'resource' => $resource,
                'expectedRevision' => substr($expected, 0, 160),
                'revision' => $revision,
                'current' => $current,
            ]
        );
    }

    public function create_collection(WP_REST_Request $request): WP_REST_Response|WP_Error {
        return $this->with_cms_mutation_lock(fn(): WP_REST_Response|WP_Error => $this->create_collection_locked($request));
    }

    private function create_collection_locked(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $name = sanitize_text_field((string) $request->get_param('name'));
        $singular = sanitize_text_field((string) ($request->get_param('singular') ?: $name));
        $base = sanitize_title((string) ($request->get_param('slug') ?: $name));
        $slug = sanitize_key('kodety_' . str_replace('-', '_', $base));
        if ($name === '' || $base === '') return new WP_Error('kodety_invalid_collection', 'Informe o nome da coleção.', ['status' => 400]);
        $revision = $this->cms_schema_revision();
        $revision_error = $this->cms_expected_revision_error($request, 'schema', $revision, $this->cms_schema_current());
        if ($revision_error) return $revision_error;
        if (strlen($slug) > 20) $slug = substr($slug, 0, 20);
        if (post_type_exists($slug)) return new WP_Error('kodety_collection_exists', 'Já existe uma coleção com este identificador.', ['status' => 409]);
        $raw_previous_definitions = $this->project_cms_option('kodety_collections', []);
        $previous_definitions = is_array($raw_previous_definitions) ? $raw_previous_definitions : [];
        $definitions = $this->collection_definitions();
        $limit_error = Kodety_Edition::collection_limit_error($definitions);
        if ($limit_error) return $limit_error;
        $definition = ['slug' => $slug, 'name' => $name, 'singular' => $singular, 'urlSlug' => $base, 'fields' => []];
        $definitions[] = $definition;
        if (!$this->write_cms_option_with_ack('kodety_collections', $definitions)) {
            $rollback_ok = $this->write_cms_option_with_ack('kodety_collections', $previous_definitions);
            return new WP_Error(
                'kodety_collection_persistence_failed',
                'A collection não pôde ser confirmada no WordPress.',
                ['status' => 500, 'rollbackFailed' => !$rollback_ok]
            );
        }
        $this->register_collections();
        flush_rewrite_rules(false);
        return new WP_REST_Response($definition + ['revision' => $this->cms_schema_revision()], 201);
    }

    /** Rename collection labels without changing either stable route identifier. */
    public function update_collection(WP_REST_Request $request): WP_REST_Response|WP_Error {
        return $this->with_cms_mutation_lock(fn(): WP_REST_Response|WP_Error => $this->update_collection_locked($request));
    }

    private function update_collection_locked(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $post_type = sanitize_key((string) $request['post_type']);
        $raw_definitions = $this->project_cms_option('kodety_collections', []);
        $definitions = is_array($raw_definitions) ? array_values(array_filter($raw_definitions, 'is_array')) : [];
        $index = null;
        foreach ($definitions as $candidate_index => $definition) {
            if (sanitize_key((string) ($definition['slug'] ?? '')) === $post_type) {
                $index = $candidate_index;
                break;
            }
        }
        if ($index === null) {
            return new WP_Error('kodety_collection_not_found', 'Collection não encontrada.', ['status' => 404]);
        }
        if (!empty($definitions[$index]['readOnly'])) {
            return new WP_Error('kodety_read_only_collection', 'Esta collection é sincronizada e não pode ser renomeada.', ['status' => 403]);
        }

        $stable_slug = (string) ($definitions[$index]['slug'] ?? '');
        $stable_url_slug = (string) (
            $definitions[$index]['urlSlug']
            ?? $definitions[$index]['name']
            ?? $stable_slug
        );
        $requested_slug = $request->get_param('slug');
        $requested_url_slug = $request->get_param('urlSlug');
        if (
            ($requested_slug !== null && (string) $requested_slug !== $stable_slug)
            || ($requested_url_slug !== null && (string) $requested_url_slug !== $stable_url_slug)
        ) {
            return new WP_Error(
                'kodety_collection_slug_immutable',
                'O slug interno e o slug de URL são imutáveis depois que a collection é criada.',
                [
                    'status' => 400,
                    'slug' => (string) ($definitions[$index]['slug'] ?? ''),
                    'urlSlug' => (string) ($definitions[$index]['urlSlug'] ?? ''),
                ]
            );
        }
        $name = sanitize_text_field((string) $request->get_param('name'));
        $singular = sanitize_text_field((string) ($request->get_param('singular') ?: $name));
        if ($name === '' || $singular === '') {
            return new WP_Error('kodety_invalid_collection', 'Informe os nomes plural e singular da collection.', ['status' => 400]);
        }
        $revision = $this->cms_schema_revision();
        $revision_error = $this->cms_expected_revision_error(
            $request,
            'collection:' . $post_type,
            $revision,
            $definitions[$index]
        );
        if ($revision_error) return $revision_error;

        $previous_definitions = $definitions;
        $definitions[$index] = [
            ...$definitions[$index],
            'name' => $name,
            'singular' => $singular,
        ];
        if (!$this->write_cms_option_with_ack('kodety_collections', $definitions)) {
            $rollback_ok = $this->write_cms_option_with_ack('kodety_collections', $previous_definitions);
            return new WP_Error(
                'kodety_collection_persistence_failed',
                'A renomeação da collection não pôde ser confirmada no WordPress.',
                ['status' => 500, 'rollbackFailed' => !$rollback_ok]
            );
        }
        return new WP_REST_Response($definitions[$index] + ['revision' => $this->cms_schema_revision()]);
    }

    /** Remove only an empty collection definition; content is never cascaded. */
    public function delete_collection(WP_REST_Request $request): WP_REST_Response|WP_Error {
        return $this->with_cms_mutation_lock(fn(): WP_REST_Response|WP_Error => $this->delete_collection_locked($request));
    }

    private function delete_collection_locked(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $post_type = sanitize_key((string) $request['post_type']);
        if (sanitize_key((string) $request->get_param('confirmation')) !== $post_type) {
            return new WP_Error('kodety_collection_confirmation_required', 'Confirme o identificador da collection para excluí-la.', ['status' => 400]);
        }
        $delete_items = $request->get_param('deleteItems');
        if ($delete_items === null || rest_sanitize_boolean($delete_items)) {
            return new WP_Error(
                'kodety_collection_cascade_forbidden',
                'A exclusão em cascata não é permitida. Envie deleteItems como false e remova os itens separadamente.',
                ['status' => 400, 'deleteItems' => false]
            );
        }
        $raw_definitions = $this->project_cms_option('kodety_collections', []);
        $definitions = is_array($raw_definitions) ? array_values(array_filter($raw_definitions, 'is_array')) : [];
        $definition = null;
        foreach ($definitions as $candidate) {
            if (sanitize_key((string) ($candidate['slug'] ?? '')) === $post_type) {
                $definition = $candidate;
                break;
            }
        }
        if (!is_array($definition)) {
            return new WP_Error('kodety_collection_not_found', 'Collection não encontrada.', ['status' => 404]);
        }
        if (!empty($definition['readOnly'])) {
            return new WP_Error('kodety_read_only_collection', 'Esta collection é sincronizada e não pode ser excluída.', ['status' => 403]);
        }

        $revision = $this->cms_schema_revision();
        $revision_error = $this->cms_expected_revision_error(
            $request,
            'collection:' . $post_type,
            $revision,
            $definition
        );
        if ($revision_error) return $revision_error;

        $post_ids = $this->cms_collection_item_ids($post_type);
        if ($post_ids !== []) {
            return new WP_Error(
                'kodety_collection_not_empty',
                'A collection ainda possui itens. Remova-os separadamente antes de excluir a collection.',
                [
                    'status' => 409,
                    'itemCount' => count($post_ids),
                    'revision' => $revision,
                    'current' => $definition,
                ]
            );
        }

        $previous_definitions = $definitions;
        $previous_fields_raw = $this->project_cms_option('kodety_field_definitions', []);
        $previous_fields = is_array($previous_fields_raw) ? $previous_fields_raw : [];
        $previous_templates_raw = $this->project_cms_option('kodety_cms_templates', []);
        $previous_templates = is_array($previous_templates_raw) ? $previous_templates_raw : [];
        $next_definitions = array_values(array_filter(
            $definitions,
            static fn(array $candidate): bool => sanitize_key((string) ($candidate['slug'] ?? '')) !== $post_type
        ));
        $next_fields = $previous_fields;
        $next_templates = $previous_templates;
        unset($next_fields[$post_type], $next_templates[$post_type]);

        $definitions_ok = $this->write_cms_option_with_ack('kodety_collections', $next_definitions);
        $fields_ok = $definitions_ok && $this->write_cms_option_with_ack('kodety_field_definitions', $next_fields);
        $templates_ok = $fields_ok && $this->write_cms_option_with_ack('kodety_cms_templates', $next_templates);
        if (!$templates_ok) {
            // Attempt every restore independently. Short-circuiting after one
            // failed option would leave the other schema stores stale even
            // though their snapshots are still available under this lock.
            $definitions_rollback_ok = $this->write_cms_option_with_ack('kodety_collections', $previous_definitions);
            $fields_rollback_ok = $this->write_cms_option_with_ack('kodety_field_definitions', $previous_fields);
            $templates_rollback_ok = $this->write_cms_option_with_ack('kodety_cms_templates', $previous_templates);
            $rollback_ok = $definitions_rollback_ok && $fields_rollback_ok && $templates_rollback_ok;
            return new WP_Error(
                'kodety_collection_persistence_failed',
                'A exclusão da collection não pôde ser confirmada no WordPress.',
                ['status' => 500, 'rollbackFailed' => !$rollback_ok]
            );
        }

        flush_rewrite_rules(false);
        return new WP_REST_Response([
            'deleted' => $post_type,
            'deletedItems' => 0,
            'bindingsFallback' => true,
            'revision' => $this->cms_schema_revision(),
        ]);
    }

    public function cms_schema(): WP_REST_Response {
        $types_payload = $this->cms_types()->get_data();
        $types = is_array($types_payload) && is_array($types_payload['types'] ?? null)
            ? $types_payload['types']
            : [];
        $schema = [];
        foreach ($types as $type) {
            $slug = sanitize_key((string) ($type['slug'] ?? ''));
            if ($slug === '') continue;
            $fields = [];
            if (post_type_supports($slug, 'title')) $fields[] = ['key' => 'title', 'label' => 'Título', 'type' => 'text', 'source' => 'wordpress'];
            if (post_type_supports($slug, 'excerpt')) $fields[] = ['key' => 'excerpt', 'label' => 'Resumo', 'type' => 'textarea', 'source' => 'wordpress'];
            if (post_type_supports($slug, 'editor')) $fields[] = ['key' => 'content', 'label' => 'Conteúdo', 'type' => 'richtext', 'source' => 'wordpress'];
            if (post_type_supports($slug, 'thumbnail')) {
                $fields[] = ['key' => 'featured_image', 'label' => 'Imagem destacada', 'type' => 'image', 'source' => 'wordpress'];
                $fields[] = ['key' => 'featured_image_alt', 'label' => 'Texto alternativo da imagem', 'type' => 'text', 'source' => 'wordpress'];
            }
            $fields[] = ['key' => 'permalink', 'label' => 'Link do item', 'type' => 'url', 'source' => 'wordpress'];
            $fields[] = ['key' => 'date', 'label' => 'Data de publicação', 'type' => 'date', 'source' => 'wordpress'];
            $fields[] = ['key' => 'author', 'label' => 'Autor', 'type' => 'text', 'source' => 'wordpress'];
            $fields[] = ['key' => 'slug', 'label' => 'Slug', 'type' => 'text', 'source' => 'wordpress'];
            if (function_exists('acf_get_field_groups') && function_exists('acf_get_fields')) {
                foreach ((array) acf_get_field_groups(['post_type' => $slug]) as $group) {
                    foreach ((array) acf_get_fields($group) as $field) {
                        $name = sanitize_key((string) ($field['name'] ?? ''));
                        if ($name === '') continue;
                        $fields[] = [
                            'key' => 'field:' . $name,
                            'label' => sanitize_text_field((string) ($field['label'] ?? $name)),
                            'type' => sanitize_key((string) ($field['type'] ?? 'text')),
                            'source' => 'acf',
                        ];
                    }
                }
            }
            foreach ($this->custom_field_definitions($slug) as $field) {
                $fields[] = [
                    'key' => 'field:' . $field['name'],
                    'label' => $field['label'],
                    'type' => $field['type'],
                    'source' => 'kodety',
                    'description' => $field['description'],
                    'required' => $field['required'],
                    'default' => $field['default'],
                    'min' => $field['min'],
                    'max' => $field['max'],
                    'step' => $field['step'],
                    'unit' => $field['unit'],
                ];
            }
            $type['fields'] = array_values(array_reduce($fields, static function (array $carry, array $field): array {
                $carry[$field['key']] = $field;
                return $carry;
            }, []));
            $schema[] = $type;
        }
        return new WP_REST_Response([
            'types' => $schema,
            'templates' => $this->cms_template_definitions(),
            'revision' => $this->cms_schema_revision(),
            'customFields' => [
                'active' => function_exists('acf_get_field_groups'),
                'plugin' => 'Advanced Custom Fields',
            ],
        ]);
    }

    public function cms_templates(): WP_REST_Response {
        return new WP_REST_Response($this->cms_template_definitions());
    }

    /** Kodety-native custom fields for one type: collection definition fields merged with the editable option. */
    private function custom_field_definitions(string $post_type): array {
        $normalize = function (mixed $field): ?array {
            if (!is_array($field)) return null;
            $name = sanitize_key((string) ($field['name'] ?? $field['key'] ?? ''));
            if ($name === '') return null;
            $type = sanitize_key((string) ($field['type'] ?? 'text')) ?: 'text';
            return [
                'name' => $name,
                'label' => sanitize_text_field((string) ($field['label'] ?? $name)) ?: $name,
                'type' => $type,
                'description' => sanitize_textarea_field((string) ($field['description'] ?? '')),
                'required' => rest_sanitize_boolean($field['required'] ?? false),
                'default' => $this->sanitize_cms_field_default($type, $field['default'] ?? ''),
                'min' => isset($field['min']) && $field['min'] !== '' ? (float) $field['min'] : '',
                'max' => isset($field['max']) && $field['max'] !== '' ? (float) $field['max'] : '',
                'step' => isset($field['step']) && (float) $field['step'] > 0 ? (float) $field['step'] : 1,
                'unit' => sanitize_text_field((string) ($field['unit'] ?? '')),
            ];
        };
        $fields = [];
        foreach ($this->collection_definitions() as $definition) {
            if (($definition['slug'] ?? '') !== $post_type) continue;
            foreach ((array) ($definition['fields'] ?? []) as $field) {
                $clean = $normalize($field);
                if ($clean) $fields[$clean['name']] = $clean;
            }
        }
        $stored = $this->project_cms_option('kodety_field_definitions', []);
        foreach ((array) (is_array($stored) ? ($stored[$post_type] ?? []) : []) as $field) {
            $clean = $normalize($field);
            if ($clean) $fields[$clean['name']] = $clean;
        }
        return array_values($fields);
    }

    /** Include Kodety-native CMS fields in WordPress revisions so restoring a
     * revision restores the complete item, not just title/content. */
    public function revision_meta_keys(array $keys, string $post_type): array {
        foreach ($this->custom_field_definitions($post_type) as $field) {
            $name = sanitize_key((string) ($field['name'] ?? ''));
            if ($name !== '' && !str_starts_with($name, '_')) $keys[] = $name;
        }
        return array_values(array_unique($keys));
    }

    private function sanitize_cms_field_default(string $type, mixed $value): mixed {
        if ($type === 'boolean') return rest_sanitize_boolean($value);
        if ($type === 'number') return $value === '' || $value === null ? '' : (float) $value;
        if ($type === 'url') return esc_url_raw((string) $value);
        if ($type === 'image') {
            if (!is_array($value)) return esc_url_raw((string) $value);
            $crop = sanitize_key((string) ($value['crop'] ?? 'original'));
            if (!in_array($crop, ['original', 'square', 'landscape', 'portrait'], true)) $crop = 'original';
            return [
                'url' => esc_url_raw((string) ($value['url'] ?? '')),
                'alt' => sanitize_text_field((string) ($value['alt'] ?? '')),
                'focalX' => max(0, min(100, (float) ($value['focalX'] ?? 50))),
                'focalY' => max(0, min(100, (float) ($value['focalY'] ?? 50))),
                'crop' => $crop,
            ];
        }
        if ($type === 'textarea') return sanitize_textarea_field((string) $value);
        if ($type === 'richtext') return wp_kses_post((string) $value);
        if ($type === 'color') return sanitize_hex_color((string) $value) ?: '';
        if ($type === 'date') return preg_match('/^\d{4}-\d{2}-\d{2}$/', (string) $value) ? (string) $value : '';
        return sanitize_text_field((string) $value);
    }

    private function cms_field_value_missing(mixed $value): bool {
        if (is_array($value) && array_key_exists('url', $value)) return trim((string) $value['url']) === '';
        return $value === null || $value === '' || (is_array($value) && $value === []);
    }

    public function cms_fields(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $post_type = sanitize_key((string) $request['post_type']);
        if (!post_type_exists($post_type) || $this->is_project_collection_outside_current_scope($post_type)) {
            return new WP_Error('kodety_invalid_post_type', 'Tipo de conteúdo inválido.', ['status' => 404]);
        }
        return new WP_REST_Response([
            'postType' => $post_type,
            'fields' => $this->custom_field_definitions($post_type),
            'revision' => $this->cms_schema_revision(),
        ]);
    }

    public function save_cms_fields(WP_REST_Request $request): WP_REST_Response|WP_Error {
        return $this->with_cms_mutation_lock(fn(): WP_REST_Response|WP_Error => $this->save_cms_fields_locked($request));
    }

    private function save_cms_fields_locked(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $post_type = sanitize_key((string) $request['post_type']);
        if ($this->is_project_collection_outside_current_scope($post_type)) {
            return new WP_Error('kodety_invalid_post_type', 'Tipo de conteúdo inválido.', ['status' => 404]);
        }
        if ($this->cms_collection_read_only($post_type)) {
            return new WP_Error('kodety_read_only_collection', 'Os fields desta collection são definidos automaticamente pela integração.', ['status' => 403]);
        }
        $type = get_post_type_object($post_type);
        if (!$type || !$type->show_ui) return new WP_Error('kodety_invalid_post_type', 'Tipo de conteúdo inválido.', ['status' => 404]);
        $raw = $request->get_param('fields');
        if (!is_array($raw)) return new WP_Error('kodety_invalid_fields', 'Envie uma lista de campos.', ['status' => 400]);
        $revision = $this->cms_schema_revision();
        $revision_error = $this->cms_expected_revision_error(
            $request,
            'fields:' . $post_type,
            $revision,
            [
                'postType' => $post_type,
                'fields' => $this->custom_field_definitions($post_type),
            ]
        );
        if ($revision_error) return $revision_error;
        $allowed_types = ['text', 'textarea', 'richtext', 'image', 'url', 'number', 'boolean', 'date', 'color'];
        $reserved = ['title', 'excerpt', 'content', 'featured_image', 'featured_image_alt', 'permalink', 'date', 'author', 'slug', 'status'];
        $clean = [];
        foreach ($raw as $field) {
            if (!is_array($field)) continue;
            $name = sanitize_key((string) ($field['name'] ?? ''));
            if ($name === '' || isset($clean[$name]) || in_array($name, $reserved, true)) continue;
            $field_type = sanitize_key((string) ($field['type'] ?? 'text'));
            if (!in_array($field_type, $allowed_types, true)) $field_type = 'text';
            $clean[$name] = [
                'name' => $name,
                'label' => sanitize_text_field((string) ($field['label'] ?? $name)) ?: $name,
                'type' => $field_type,
                'description' => sanitize_textarea_field((string) ($field['description'] ?? '')),
                'required' => rest_sanitize_boolean($field['required'] ?? false),
                'default' => $this->sanitize_cms_field_default($field_type, $field['default'] ?? ''),
                'min' => isset($field['min']) && $field['min'] !== '' ? (float) $field['min'] : '',
                'max' => isset($field['max']) && $field['max'] !== '' ? (float) $field['max'] : '',
                'step' => isset($field['step']) && (float) $field['step'] > 0 ? (float) $field['step'] : 1,
                'unit' => sanitize_text_field((string) ($field['unit'] ?? '')),
            ];
        }
        $stored = $this->project_cms_option('kodety_field_definitions', []);
        if (!is_array($stored)) $stored = [];
        $previous_stored = $stored;
        if ($clean) $stored[$post_type] = array_values($clean);
        else unset($stored[$post_type]);
        if (!$this->write_cms_option_with_ack('kodety_field_definitions', $stored)) {
            $rollback_ok = $this->write_cms_option_with_ack('kodety_field_definitions', $previous_stored);
            return new WP_Error(
                'kodety_fields_persistence_failed',
                'Os campos não puderam ser confirmados no WordPress.',
                ['status' => 500, 'rollbackFailed' => !$rollback_ok]
            );
        }
        // The editable option becomes the single source of truth; clear any
        // legacy field list stored inside the collection definition so removed
        // fields do not resurface through the merge.
        $definitions = $this->project_cms_option('kodety_collections', []);
        $previous_definitions = is_array($definitions) ? $definitions : [];
        $changed = false;
        if (is_array($definitions)) {
            foreach ($definitions as $index => $definition) {
                if (!is_array($definition) || ($definition['slug'] ?? '') !== $post_type || empty($definition['fields'])) continue;
                $definitions[$index]['fields'] = [];
                $changed = true;
            }
        }
        if ($changed && !$this->write_cms_option_with_ack('kodety_collections', $definitions)) {
            $fields_rollback_ok = $this->write_cms_option_with_ack('kodety_field_definitions', $previous_stored);
            $collections_rollback_ok = $this->write_cms_option_with_ack('kodety_collections', $previous_definitions);
            return new WP_Error(
                'kodety_fields_persistence_failed',
                'Os campos foram recusados durante a atualização da collection.',
                [
                    'status' => 500,
                    'rollbackFailed' => !$fields_rollback_ok || !$collections_rollback_ok,
                ]
            );
        }
        return new WP_REST_Response([
            'postType' => $post_type,
            'fields' => array_values($clean),
            'revision' => $this->cms_schema_revision(),
        ]);
    }

    /** @return list<string> */
    private function cms_allowed_post_statuses(WP_Post_Type $type): array {
        $statuses = [];
        if (current_user_can($type->cap->edit_posts)) {
            $statuses[] = 'draft';
            $statuses[] = 'pending';
        }
        if (current_user_can($type->cap->edit_published_posts ?? $type->cap->edit_posts)) {
            $statuses[] = 'publish';
            $statuses[] = 'future';
        }
        if (current_user_can($type->cap->read_private_posts ?? $type->cap->edit_others_posts)) {
            $statuses[] = 'private';
        }
        return array_values(array_unique($statuses));
    }

    public function cms_items(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $post_type = sanitize_key((string) $request['post_type']);
        $type = get_post_type_object($post_type);
        if (
            !$type
            || !$type->show_ui
            || $this->is_project_collection_outside_current_scope($post_type)
            || !current_user_can($type->cap->edit_posts)
        ) {
            return new WP_Error('kodety_invalid_post_type', 'Tipo de conteúdo inválido.', ['status' => 404]);
        }
        $per_page = max(1, min(100, absint($request->get_param('per_page') ?: 50)));
        $page = max(1, absint($request->get_param('page') ?: 1));
        $search = sanitize_text_field((string) ($request->get_param('search') ?: ''));
        $status = sanitize_key((string) ($request->get_param('status') ?: ''));
        $allowed_statuses = $this->cms_allowed_post_statuses($type);
        if ($status !== '' && !in_array($status, $allowed_statuses, true)) {
            return new WP_REST_Response([
                'items' => [],
                'total' => 0,
                'totalPages' => 0,
                'page' => $page,
                'revision' => $this->cms_schema_revision(),
            ]);
        }
        $orderby = sanitize_key((string) ($request->get_param('orderby') ?: 'date'));
        if (!in_array($orderby, ['date', 'modified', 'title', 'menu_order', 'rand'], true)) $orderby = 'date';
        $order = strtoupper(sanitize_text_field((string) ($request->get_param('order') ?: 'DESC'))) === 'ASC' ? 'ASC' : 'DESC';
        $arguments = [
            'post_type' => $post_type,
            'post_status' => in_array($status, $allowed_statuses, true) ? [$status] : $allowed_statuses,
            'posts_per_page' => $per_page,
            'paged' => $page,
            's' => $search,
            'orderby' => $orderby,
            'order' => $order,
            'no_found_rows' => false,
        ];
        if (!current_user_can($type->cap->edit_others_posts ?? $type->cap->edit_posts)) {
            $arguments['author'] = get_current_user_id();
        }
        $scope = $this->cms_project_scope_key();
        $strict_project_scope = $this->is_project_collection($post_type);
        if ($strict_project_scope && $scope !== '') {
            $arguments['meta_query'] = [
                [
                    'key' => '_kodety_project_id',
                    'value' => $scope,
                    'compare' => '=',
                ],
            ];
        } elseif ($strict_project_scope) {
            $arguments['meta_query'] = [[
                'key' => '_kodety_project_id',
                'compare' => 'NOT EXISTS',
            ]];
        } elseif ($scope !== '') {
            $arguments['meta_query'] = [
                'relation' => 'OR',
                [
                    'key' => '_kodety_project_id',
                    'value' => $scope,
                    'compare' => '=',
                ],
                [
                    'key' => '_kodety_project_id',
                    'compare' => 'NOT EXISTS',
                ],
            ];
        } else {
            $arguments['meta_query'] = [[
                'key' => '_kodety_project_id',
                'compare' => 'NOT EXISTS',
            ]];
        }
        $query = new WP_Query($arguments);
        $editable_posts = array_values(array_filter(
            $query->posts,
            fn(mixed $post): bool => $post instanceof WP_Post
                && ($this->cms_collection_read_only($post->post_type) || current_user_can('edit_post', $post->ID))
        ));
        return new WP_REST_Response([
            'items' => array_map(fn(WP_Post $post): array => $this->cms_item_payload($post), $editable_posts),
            'total' => count($editable_posts) === count($query->posts)
                ? (int) $query->found_posts
                : count($editable_posts),
            'totalPages' => (int) $query->max_num_pages,
            'page' => $page,
            'revision' => $this->cms_schema_revision(),
        ]);
    }

    public function cms_item(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $post_type = sanitize_key((string) $request['post_type']);
        $post_id = absint($request['post_id']);
        $post = get_post($post_id);
        if (
            !$post instanceof WP_Post
            || $post->post_type !== $post_type
            || !$this->cms_item_belongs_to_current_project($post_id, $post_type)
        ) {
            return new WP_Error('kodety_invalid_item', 'Item não encontrado.', ['status' => 404]);
        }
        return new WP_REST_Response($this->cms_item_payload($post));
    }

    /**
     * Create one CMS item and return its durable WordPress record.
     *
     * Batch imports suppress the public saved hook until every row has an ACK;
     * otherwise consumers could observe rows that are subsequently rolled back.
     *
     * @param array<string,mixed> $values
     */
    private function create_cms_item_record(
        string $post_type,
        array $values,
        bool $emit_saved_action = true
    ): WP_Post|WP_Error {
        if ($this->is_project_collection_outside_current_scope($post_type)) {
            return new WP_Error('kodety_invalid_post_type', 'Tipo de conteúdo inválido.', ['status' => 404]);
        }
        if ($this->cms_collection_read_only($post_type)) {
            return new WP_Error('kodety_read_only_collection', 'Esta collection é sincronizada por uma integração e não aceita edição manual.', ['status' => 403]);
        }
        $type = get_post_type_object($post_type);
        if (!$type || !$type->show_ui || $post_type === 'attachment') {
            return new WP_Error('kodety_invalid_post_type', 'Tipo de conteúdo inválido.', ['status' => 404]);
        }
        if (!current_user_can($type->cap->create_posts ?? $type->cap->edit_posts)) {
            return new WP_Error('kodety_forbidden', 'Sem permissão para criar itens.', ['status' => 403]);
        }
        if ($this->is_project_collection($post_type)) {
            $limit_error = Kodety_Edition::item_limit_error($post_type);
            if ($limit_error) return $limit_error;
        }
        foreach ($this->custom_field_definitions($post_type) as $field) {
            $key = 'field:' . $field['name'];
            if (!array_key_exists($key, $values) && !$this->cms_field_value_missing($field['default'])) $values[$key] = $field['default'];
            if ($field['required'] && (!array_key_exists($key, $values) || $this->cms_field_value_missing($values[$key]))) {
                return new WP_Error('kodety_required_field', sprintf('O campo “%s” é obrigatório.', $field['label']), ['status' => 400, 'field' => $key]);
            }
        }
        $title = sanitize_text_field((string) ($values['title'] ?? ''));
        $status = sanitize_key((string) ($values['status'] ?? 'draft'));
        if (!in_array($status, ['publish', 'draft', 'pending'], true)) {
            return new WP_Error('kodety_invalid_status', 'Status de conteúdo inválido.', ['status' => 400, 'field' => 'status']);
        }
        if ($status === 'publish' && !current_user_can($type->cap->publish_posts ?? 'publish_posts')) {
            return new WP_Error('kodety_cannot_publish_item', 'Sem permissão para publicar itens desta collection.', ['status' => 403]);
        }
        $insert_title = $title !== '' ? $title : ($type->labels->singular_name ?: 'Novo item');
        $result = wp_insert_post(wp_slash([
            'post_type' => $post_type,
            'post_status' => $status,
            'post_title' => $insert_title,
        ]), true);
        if (is_wp_error($result)) return $result;
        $post_id = (int) $result;
        if ($post_id <= 0) {
            return new WP_Error('kodety_create_failed', 'O item não pôde ser criado no WordPress.', ['status' => 500]);
        }
        $project_id = $this->cms_project_scope_key();
        if ($project_id !== '' && $this->is_project_collection($post_type)) {
            update_post_meta($post_id, '_kodety_project_id', $project_id);
            if (!hash_equals($project_id, sanitize_key((string) get_post_meta($post_id, '_kodety_project_id', true)))) {
                return $this->rollback_created_cms_item(
                    $post_id,
                    new WP_Error('kodety_create_ack_failed', 'O WordPress não confirmou o projeto do item.', ['status' => 500])
                );
            }
        }
        $inserted = get_post($post_id);
        if (!$inserted instanceof WP_Post
            || $inserted->post_type !== $post_type
            || $inserted->post_status !== $status
            || $inserted->post_title !== $insert_title) {
            return $this->rollback_created_cms_item(
                $post_id,
                new WP_Error('kodety_create_ack_failed', 'O WordPress não confirmou os dados iniciais do item.', ['status' => 500])
            );
        }
        unset($values['title'], $values['status']);
        $applied = $this->apply_cms_item_values($post_id, $values, $emit_saved_action);
        if (is_wp_error($applied)) {
            return $this->rollback_created_cms_item($post_id, $applied);
        }
        clean_post_cache($post_id);
        $created = get_post($post_id);
        if (!$created instanceof WP_Post) {
            return $this->rollback_created_cms_item(
                $post_id,
                new WP_Error('kodety_invalid_item', 'Item não encontrado após a criação.', ['status' => 500])
            );
        }
        return $created;
    }

    public function create_cms_item(WP_REST_Request $request): WP_REST_Response|WP_Error {
        return $this->with_cms_mutation_lock(fn(): WP_REST_Response|WP_Error => $this->create_cms_item_locked($request));
    }

    private function create_cms_item_locked(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $post_type = sanitize_key((string) $request['post_type']);
        if ($this->is_project_collection_outside_current_scope($post_type)) {
            return new WP_Error('kodety_invalid_post_type', 'Tipo de conteúdo inválido.', ['status' => 404]);
        }
        $raw_values = $request->get_param('values');
        if (!is_array($raw_values)) return new WP_Error('kodety_invalid_values', 'Valores inválidos.', ['status' => 400]);
        $values = $raw_values;
        if (!array_key_exists('status', $values) && $request->get_param('status') !== null) {
            $values['status'] = $request->get_param('status');
        }
        $revision = $this->cms_schema_revision();
        $revision_error = $this->cms_expected_revision_error(
            $request,
            'items:' . $post_type,
            $revision,
            [
                'postType' => $post_type,
                'fields' => $this->custom_field_definitions($post_type),
            ]
        );
        if ($revision_error) return $revision_error;
        $created = $this->create_cms_item_record($post_type, $values);
        if (is_wp_error($created)) return $created;
        return new WP_REST_Response($this->cms_item_payload($created), 201);
    }

    /**
     * Atomically import a bounded list of CMS rows.
     *
     * WordPress does not provide a portable transaction across posts, postmeta
     * and ACF. Each row therefore uses the normal ACK-protected writer; on the
     * first error every earlier row is force-deleted and read back before an
     * error is returned. No saved hook is emitted until the whole batch holds.
     */
    public function import_cms_items(WP_REST_Request $request): WP_REST_Response|WP_Error {
        return $this->with_cms_mutation_lock(fn(): WP_REST_Response|WP_Error => $this->import_cms_items_locked($request));
    }

    private function import_cms_items_locked(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $post_type = sanitize_key((string) $request['post_type']);
        if ($this->is_project_collection_outside_current_scope($post_type)) {
            return new WP_Error('kodety_invalid_post_type', 'Tipo de conteúdo inválido.', ['status' => 404]);
        }
        $items = $request->get_param('items');
        if (!is_array($items) || $items === []) {
            return new WP_Error('kodety_invalid_import', 'Envie ao menos uma linha para importar.', ['status' => 400]);
        }
        if (count($items) > 1000) {
            return new WP_Error('kodety_import_too_large', 'Importe no máximo 1.000 itens por arquivo.', ['status' => 413]);
        }
        $revision = $this->cms_schema_revision();
        $revision_error = $this->cms_expected_revision_error(
            $request,
            'items:' . $post_type,
            $revision,
            [
                'postType' => $post_type,
                'fields' => $this->custom_field_definitions($post_type),
            ]
        );
        if ($revision_error) return $revision_error;

        /** @var list<int> $created_ids */
        $created_ids = [];
        foreach (array_values($items) as $index => $item) {
            if (!is_array($item) || !isset($item['values']) || !is_array($item['values'])) {
                $error = new WP_Error(
                    'kodety_invalid_import_row',
                    sprintf('A linha %d do CSV é inválida.', $index + 2),
                    ['status' => 400, 'row' => $index + 2]
                );
            } else {
                $created = $this->create_cms_item_record($post_type, $item['values'], false);
                if (!is_wp_error($created)) {
                    $created_ids[] = $created->ID;
                    continue;
                }
                $error = $created;
            }

            $rollback_failed = [];
            foreach (array_reverse($created_ids) as $created_id) {
                wp_delete_post($created_id, true);
                if (get_post($created_id) instanceof WP_Post) $rollback_failed[] = $created_id;
            }
            if ($rollback_failed !== []) {
                return new WP_Error(
                    'kodety_import_rollback_failed',
                    'A importação falhou e alguns itens parciais não puderam ser removidos.',
                    [
                        'status' => 500,
                        'row' => $index + 2,
                        'cause' => $error->get_error_code(),
                        'rollbackFailed' => true,
                        'postIds' => $rollback_failed,
                    ]
                );
            }
            $error_data = $error->get_error_data();
            $error_status = is_array($error_data) ? (int) ($error_data['status'] ?? 400) : 400;
            return new WP_Error(
                $error->get_error_code(),
                method_exists($error, 'get_error_message')
                    ? $error->get_error_message()
                    : sprintf('A linha %d do CSV não pôde ser importada.', $index + 2),
                [
                    'status' => $error_status,
                    'row' => $index + 2,
                    'rollbackFailed' => false,
                ]
            );
        }

        foreach ($created_ids as $created_id) do_action('kodety_cms_item_saved', $created_id);
        return new WP_REST_Response([
            'imported' => count($created_ids),
            'items' => array_map(
                static fn(int $post_id): array => ['id' => $post_id, 'type' => $post_type],
                $created_ids
            ),
            'revision' => $this->cms_schema_revision(),
        ], 201);
    }

    /**
     * Create one collection item from a server-verified public form mapping.
     *
     * This deliberately accepts only Onun Kodety collections and scalar fields. The
     * public endpoint never receives a WordPress capability, field name or
     * collection choice that was not signed into the published form first.
     *
     * @param array<string,mixed> $values
     * @return array{id:int,type:string,status:string}|WP_Error
     */
    public function create_cms_item_from_form(string $post_type, array $values, string $status = 'draft'): array|WP_Error {
        return $this->with_cms_mutation_lock(
            fn(): array|WP_Error => $this->create_cms_item_from_form_locked($post_type, $values, $status)
        );
    }

    private function create_cms_item_from_form_locked(string $post_type, array $values, string $status = 'draft'): array|WP_Error {
        $post_type = sanitize_key($post_type);
        $collection = null;
        foreach ($this->collection_definitions() as $definition) {
            if (sanitize_key((string) ($definition['slug'] ?? '')) === $post_type) {
                $collection = $definition;
                break;
            }
        }
        $type = get_post_type_object($post_type);
        if (!is_array($collection) || !$type || !$type->show_ui || $post_type === 'attachment') {
            return new WP_Error('kodety_form_cms_collection', 'A collection conectada ao formulário não está disponível.', ['status' => 404]);
        }
        $limit_error = Kodety_Edition::item_limit_error($post_type);
        if ($limit_error) return $limit_error;
        $status = sanitize_key($status);
        if (!in_array($status, ['draft', 'pending', 'publish'], true)) {
            return new WP_Error('kodety_form_cms_status', 'O status configurado para o novo item é inválido.', ['status' => 400]);
        }

        $allowed = [];
        if (post_type_supports($post_type, 'title')) $allowed['title'] = true;
        if (post_type_supports($post_type, 'excerpt')) $allowed['excerpt'] = true;
        if (post_type_supports($post_type, 'editor')) $allowed['content'] = true;
        $allowed['slug'] = true;
        $scalar_types = [
            'text', 'textarea', 'richtext', 'wysiwyg', 'number', 'range', 'email',
            'url', 'date', 'date_picker', 'date_time_picker', 'time_picker',
            'select', 'radio', 'checkbox', 'true_false', 'boolean', 'toggle', 'color',
        ];
        foreach ($this->custom_field_definitions($post_type) as $field) {
            if (in_array((string) ($field['type'] ?? ''), $scalar_types, true)) {
                $allowed['field:' . $field['name']] = true;
            }
        }
        if (function_exists('acf_get_field_groups') && function_exists('acf_get_fields')) {
            foreach ((array) acf_get_field_groups(['post_type' => $post_type]) as $group) {
                foreach ((array) acf_get_fields($group) as $field) {
                    $name = sanitize_key((string) ($field['name'] ?? ''));
                    $field_type = sanitize_key((string) ($field['type'] ?? 'text'));
                    if ($name !== '' && in_array($field_type, $scalar_types, true)) $allowed['field:' . $name] = true;
                }
            }
        }
        foreach ($values as $key => $_value) {
            if (!is_string($key) || !isset($allowed[$key])) {
                return new WP_Error('kodety_form_cms_field', 'Um campo conectado ao formulário não está mais disponível no CMS.', ['status' => 400, 'field' => (string) $key]);
            }
        }
        foreach ($this->custom_field_definitions($post_type) as $field) {
            $key = 'field:' . $field['name'];
            if (!array_key_exists($key, $values) && !$this->cms_field_value_missing($field['default'])) $values[$key] = $field['default'];
            if ($field['required'] && (!array_key_exists($key, $values) || $this->cms_field_value_missing($values[$key]))) {
                return new WP_Error('kodety_required_field', sprintf('O campo “%s” é obrigatório.', $field['label']), ['status' => 400, 'field' => $key]);
            }
        }

        $title = sanitize_text_field((string) ($values['title'] ?? ''));
        $insert_title = $title !== ''
            ? $title
            : sanitize_text_field((string) ($collection['singular'] ?? $type->labels->singular_name ?? 'Novo item')) . ' · ' . current_time('Y-m-d H:i');
        $result = wp_insert_post(wp_slash([
            'post_type' => $post_type,
            'post_status' => $status,
            'post_title' => $insert_title,
        ]), true);
        if (is_wp_error($result)) return $result;
        $post_id = (int) $result;
        if ($post_id <= 0) {
            return new WP_Error('kodety_form_cms_create', 'O item do CMS não pôde ser criado.', ['status' => 500]);
        }
        $project_id = $this->cms_project_scope_key();
        if ($project_id !== '') {
            update_post_meta($post_id, '_kodety_project_id', $project_id);
            if (!hash_equals($project_id, sanitize_key((string) get_post_meta($post_id, '_kodety_project_id', true)))) {
                return $this->rollback_created_cms_item(
                    $post_id,
                    new WP_Error('kodety_form_cms_ack', 'O WordPress não confirmou o projeto do item do CMS.', ['status' => 500])
                );
            }
        }
        $inserted = get_post($post_id);
        if (!$inserted instanceof WP_Post
            || $inserted->post_type !== $post_type
            || $inserted->post_status !== $status
            || $inserted->post_title !== $insert_title) {
            return $this->rollback_created_cms_item(
                $post_id,
                new WP_Error('kodety_form_cms_ack', 'O WordPress não confirmou o novo item do CMS.', ['status' => 500])
            );
        }
        unset($values['title']);
        $applied = $this->apply_cms_item_values($post_id, $values);
        if (is_wp_error($applied)) return $this->rollback_created_cms_item($post_id, $applied);
        clean_post_cache($post_id);
        $created = get_post($post_id);
        if (!$created instanceof WP_Post) {
            return $this->rollback_created_cms_item(
                $post_id,
                new WP_Error('kodety_form_cms_missing', 'O item do CMS desapareceu após a criação.', ['status' => 500])
            );
        }
        return ['id' => $post_id, 'type' => $post_type, 'status' => $created->post_status];
    }

    private function rollback_created_cms_item(int $post_id, WP_Error $cause): WP_Error {
        wp_delete_post($post_id, true);
        if (!get_post($post_id) instanceof WP_Post) return $cause;
        return new WP_Error(
            'kodety_create_rollback_failed',
            'A criação falhou e o item parcial não pôde ser removido.',
            [
                'status' => 500,
                'postId' => $post_id,
                'cause' => $cause->get_error_code(),
                'rollbackFailed' => true,
            ]
        );
    }

    public function update_cms_item(WP_REST_Request $request): WP_REST_Response|WP_Error {
        return $this->with_cms_mutation_lock(fn(): WP_REST_Response|WP_Error => $this->update_cms_item_locked($request));
    }

    private function update_cms_item_locked(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $post_type = sanitize_key((string) $request['post_type']);
        if ($this->cms_collection_read_only($post_type)) {
            return new WP_Error('kodety_read_only_collection', 'Esta collection é sincronizada por uma integração e não aceita edição manual.', ['status' => 403]);
        }
        $post_id = absint($request['post_id']);
        clean_post_cache($post_id);
        $post = get_post($post_id);
        if (
            !$post instanceof WP_Post
            || $post->post_type !== $post_type
            || !$this->cms_item_belongs_to_current_project($post_id, $post_type)
        ) {
            return new WP_Error('kodety_invalid_item', 'Item não encontrado.', ['status' => 404]);
        }
        $revision = $this->cms_item_revision($post);
        $revision_error = $this->cms_expected_revision_error(
            $request,
            'item:' . $post_type . ':' . $post_id,
            $revision,
            $this->cms_item_payload($post)
        );
        if ($revision_error) return $revision_error;
        $values = $request->get_param('values');
        if (!is_array($values)) return new WP_Error('kodety_invalid_values', 'Valores inválidos.', ['status' => 400]);
        foreach ($this->custom_field_definitions($post_type) as $field) {
            $key = 'field:' . $field['name'];
            if ($field['required'] && array_key_exists($key, $values) && $this->cms_field_value_missing($values[$key])) {
                return new WP_Error('kodety_required_field', sprintf('O campo “%s” é obrigatório.', $field['label']), ['status' => 400, 'field' => $key]);
            }
        }
        $applied = $this->apply_cms_item_values($post_id, $values);
        if (is_wp_error($applied)) return $applied;
        clean_post_cache($post_id);
        $updated_post = get_post($post_id);
        if (!$updated_post instanceof WP_Post) return new WP_Error('kodety_invalid_item', 'Item não encontrado.', ['status' => 404]);
        return new WP_REST_Response($this->cms_item_payload($updated_post));
    }

    public function delete_cms_item(WP_REST_Request $request): WP_REST_Response|WP_Error {
        return $this->with_cms_mutation_lock(fn(): WP_REST_Response|WP_Error => $this->delete_cms_item_locked($request));
    }

    private function delete_cms_item_locked(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $post_type = sanitize_key((string) $request['post_type']);
        if ($this->cms_collection_read_only($post_type)) {
            return new WP_Error('kodety_read_only_collection', 'Esta collection é sincronizada por uma integração e não aceita exclusão manual.', ['status' => 403]);
        }
        $post_id = absint($request['post_id']);
        clean_post_cache($post_id);
        $post = get_post($post_id);
        if (
            !$post instanceof WP_Post
            || $post->post_type !== $post_type
            || !$this->cms_item_belongs_to_current_project($post_id, $post_type)
        ) {
            return new WP_Error('kodety_invalid_item', 'Item não encontrado.', ['status' => 404]);
        }
        $revision = $this->cms_item_revision($post);
        $revision_error = $this->cms_expected_revision_error(
            $request,
            'item:' . $post_type . ':' . $post_id,
            $revision,
            $this->cms_item_payload($post)
        );
        if ($revision_error) return $revision_error;
        if (!wp_trash_post($post_id)) return new WP_Error('kodety_delete_failed', 'Não foi possível mover o item para a lixeira.', ['status' => 500]);
        clean_post_cache($post_id);
        $trashed = get_post($post_id);
        if (!$trashed instanceof WP_Post || $trashed->post_status !== 'trash') {
            return new WP_Error('kodety_delete_ack_failed', 'O WordPress não confirmou o item na lixeira.', ['status' => 500]);
        }
        return new WP_REST_Response([
            'deleted' => $post_id,
            'status' => 'trash',
            'revision' => $this->cms_item_revision($trashed),
        ]);
    }

    /** Database storage stringifies scalar metadata but preserves structured
     * values. Compare those persisted semantics instead of ambiguous API
     * booleans (`false` also means "already equal" in the metadata APIs). */
    private function cms_persisted_values_match(
        mixed $actual,
        mixed $expected,
        bool $normalize_scalars = true
    ): bool {
        if (is_array($actual) || is_array($expected)) {
            if (!is_array($actual) || !is_array($expected) || array_keys($actual) !== array_keys($expected)) return false;
            foreach ($expected as $key => $value) {
                if (!$this->cms_persisted_values_match($actual[$key], $value, $normalize_scalars)) return false;
            }
            return true;
        }
        if (is_object($actual) || is_object($expected)) return maybe_serialize($actual) === maybe_serialize($expected);
        if (!$normalize_scalars) return $actual === $expected;
        $normalize = static function (mixed $value): string {
            if ($value === null || $value === false) return '';
            if ($value === true) return '1';
            return (string) $value;
        };
        return $normalize($actual) === $normalize($expected);
    }

    /** @param array<string,array{objectId:int,key:string,exists:bool,value:mixed}> $snapshots */
    private function snapshot_cms_meta(array &$snapshots, int $object_id, string $key): void {
        $snapshot_key = $object_id . ':' . $key;
        if (isset($snapshots[$snapshot_key])) return;
        $snapshots[$snapshot_key] = [
            'objectId' => $object_id,
            'key' => $key,
            'exists' => metadata_exists('post', $object_id, $key),
            'value' => get_post_meta($object_id, $key, true),
        ];
    }

    private function cms_post_matches_update(WP_Post $post, array $update): bool {
        $fields = [
            'post_title' => 'post_title',
            'post_excerpt' => 'post_excerpt',
            'post_content' => 'post_content',
            'post_status' => 'post_status',
            'post_name' => 'post_name',
        ];
        foreach ($fields as $input => $property) {
            if (array_key_exists($input, $update) && (string) $post->{$property} !== (string) $update[$input]) return false;
        }
        return true;
    }

    /**
     * @param array<string,array{objectId:int,key:string,exists:bool,value:mixed}> $meta_snapshots
     */
    private function restore_cms_item_state(
        int $post_id,
        WP_Post $post_before,
        array $meta_snapshots,
        bool $restore_post
    ): bool {
        $ok = true;
        foreach (array_reverse($meta_snapshots) as $snapshot) {
            $object_id = $snapshot['objectId'];
            $key = $snapshot['key'];
            if ($snapshot['exists']) {
                update_post_meta($object_id, $key, wp_slash($snapshot['value']));
                $restored = metadata_exists('post', $object_id, $key)
                    && $this->cms_persisted_values_match(get_post_meta($object_id, $key, true), $snapshot['value']);
            } else {
                delete_post_meta($object_id, $key);
                $restored = !metadata_exists('post', $object_id, $key);
            }
            if (!$restored) $ok = false;
            if ($object_id === $post_id && !str_starts_with($key, '_') && function_exists('acf_flush_value_cache')) {
                acf_flush_value_cache($post_id, $key);
            }
        }
        if ($restore_post) {
            $post_restore = [
                'ID' => $post_id,
                'post_title' => $post_before->post_title,
                'post_excerpt' => $post_before->post_excerpt,
                'post_content' => $post_before->post_content,
                'post_status' => $post_before->post_status,
                'post_name' => $post_before->post_name,
            ];
            $restored_id = wp_update_post(wp_slash($post_restore), true);
            $restored_post = get_post($post_id);
            if (is_wp_error($restored_id)
                || (int) $restored_id !== $post_id
                || !$restored_post instanceof WP_Post
                || !$this->cms_post_matches_update($restored_post, $post_restore)) {
                $ok = false;
            }
        }
        clean_post_cache($post_id);
        return $ok;
    }

    /**
     * @param array<string,array{objectId:int,key:string,exists:bool,value:mixed}> $meta_snapshots
     */
    private function cms_item_persistence_error(
        int $post_id,
        WP_Post $post_before,
        array $meta_snapshots,
        bool $restore_post,
        string $field,
        string $message
    ): WP_Error {
        $rollback_ok = $this->restore_cms_item_state($post_id, $post_before, $meta_snapshots, $restore_post);
        return new WP_Error(
            'kodety_cms_persistence_failed',
            $message,
            ['status' => 500, 'field' => $field, 'rollbackFailed' => !$rollback_ok]
        );
    }

    /** Apply Builder-submitted values (native fields, status, custom fields, thumbnail) to one item. */
    private function apply_cms_item_values(
        int $post_id,
        array $values,
        bool $emit_saved_action = true
    ): ?WP_Error {
        $post = get_post($post_id);
        if (!$post instanceof WP_Post) {
            return new WP_Error('kodety_invalid_item', 'Item não encontrado.', ['status' => 404]);
        }
        $post_before = clone $post;
        $custom_definitions = [];
        foreach ($this->custom_field_definitions($post->post_type) as $definition) {
            $custom_definitions[$definition['name']] = $definition;
        }
        $allowed_native_fields = [
            'title', 'excerpt', 'content', 'status', 'slug', 'permalink',
            'featured_image', 'featured_image_alt',
        ];
        foreach ($values as $key => $_value) {
            if (!is_string($key)) {
                return new WP_Error('kodety_invalid_field', 'Nome de campo inválido.', ['status' => 400]);
            }
            if (str_starts_with($key, 'field:')) continue;
            if (in_array($key, ['date', 'author'], true)) {
                return new WP_Error('kodety_readonly_field', 'O campo solicitado é somente leitura.', ['status' => 400, 'field' => $key]);
            }
            if (!in_array($key, $allowed_native_fields, true)) {
                return new WP_Error('kodety_unknown_field', 'O campo solicitado não existe neste item.', ['status' => 400, 'field' => $key]);
            }
        }

        /** @var list<array{field:string,value:mixed,kind:string,acf:?array}> $custom_writes */
        $custom_writes = [];
        foreach ($values as $key => $input_value) {
            if (!str_starts_with($key, 'field:')) continue;
            $raw_field = substr($key, 6);
            $field = sanitize_key($raw_field);
            if ($field === '' || $raw_field !== $field || str_starts_with($field, '_')) {
                return new WP_Error('kodety_protected_field', 'O campo solicitado é inválido ou protegido pelo WordPress.', ['status' => 400, 'field' => $key]);
            }
            $definition = $custom_definitions[$field] ?? null;
            // A Kodety-native definition is the source of truth when an ACF
            // field happens to reuse the same name.
            if (is_array($definition)) {
                $value = $this->sanitize_cms_field_default((string) $definition['type'], $input_value);
                if ($definition['type'] === 'number' && $value !== '') {
                    if ($definition['min'] !== '') $value = max((float) $definition['min'], (float) $value);
                    if ($definition['max'] !== '') $value = min((float) $definition['max'], (float) $value);
                }
                if ($definition['required'] && $this->cms_field_value_missing($value)) {
                    return new WP_Error(
                        'kodety_required_field',
                        sprintf('O campo “%s” é obrigatório.', $definition['label']),
                        ['status' => 400, 'field' => $key]
                    );
                }
                $custom_writes[] = ['field' => $field, 'value' => $value, 'kind' => 'native', 'acf' => null];
                continue;
            }
            $acf_field = function_exists('get_field_object') ? get_field_object($field, $post_id, false, false) : null;
            if (!is_array($acf_field)) {
                return new WP_Error('kodety_unknown_field', 'O campo não está registrado nesta collection.', ['status' => 400, 'field' => $key]);
            }
            if (!function_exists('update_field') || !function_exists('get_field')) {
                return new WP_Error('kodety_acf_unavailable', 'O campo ACF não está disponível para gravação.', ['status' => 503, 'field' => $key]);
            }
            $value = $input_value;
            if (($acf_field['type'] ?? '') === 'image') {
                if ($this->cms_field_value_missing($value) || $value === false) {
                    $value = '';
                } else {
                    $attachment_id = $this->resolve_attachment_id($value);
                    $attachment = $attachment_id > 0 ? get_post($attachment_id) : null;
                    if (!$attachment instanceof WP_Post
                        || $attachment->post_type !== 'attachment'
                        || !wp_attachment_is_image($attachment_id)
                        || !current_user_can('edit_post', $attachment_id)) {
                        return new WP_Error('kodety_invalid_acf_image', 'A imagem do campo ACF não é válida.', ['status' => 400, 'field' => $key]);
                    }
                    $value = $attachment_id;
                }
            }
            if (!empty($acf_field['required']) && ($this->cms_field_value_missing($value) || $value === false)) {
                return new WP_Error('kodety_required_field', 'O campo ACF é obrigatório.', ['status' => 400, 'field' => $key]);
            }
            if (function_exists('acf_validate_value') && acf_validate_value($value, $acf_field, $key) === false) {
                return new WP_Error('kodety_invalid_acf_value', 'O valor do campo ACF é inválido.', ['status' => 400, 'field' => $key]);
            }
            $custom_writes[] = ['field' => $field, 'value' => $value, 'kind' => 'acf', 'acf' => $acf_field];
        }

        $featured_attachment_id = null;
        if (array_key_exists('featured_image', $values)) {
            if (function_exists('post_type_supports') && !post_type_supports($post->post_type, 'thumbnail')) {
                return new WP_Error('kodety_unsupported_featured_image', 'Este tipo de conteúdo não aceita imagem destacada.', ['status' => 400]);
            }
            $empty_featured_image = $values['featured_image'] === '' || $values['featured_image'] === null || $values['featured_image'] === 0;
            $featured_attachment_id = $empty_featured_image ? 0 : $this->resolve_attachment_id($values['featured_image']);
            if (!$empty_featured_image && $featured_attachment_id <= 0) {
                return new WP_Error('kodety_invalid_featured_image', 'A imagem destacada não pôde ser localizada na biblioteca.', ['status' => 400]);
            }
            if ($featured_attachment_id > 0) {
                $attachment = get_post($featured_attachment_id);
                if (!$attachment instanceof WP_Post
                    || $attachment->post_type !== 'attachment'
                    || !wp_attachment_is_image($featured_attachment_id)
                    || !current_user_can('edit_post', $featured_attachment_id)) {
                    return new WP_Error('kodety_invalid_featured_image', 'A imagem destacada não é válida ou não pode ser usada por este usuário.', ['status' => 403]);
                }
            }
        }
        $alt_attachment_id = array_key_exists('featured_image', $values)
            ? (int) $featured_attachment_id
            : (int) get_post_thumbnail_id($post_id);
        $featured_image_alt = null;
        if (array_key_exists('featured_image_alt', $values)) {
            if ($alt_attachment_id <= 0) {
                return new WP_Error('kodety_featured_image_required', 'Escolha uma imagem destacada antes de editar o texto alternativo.', ['status' => 400, 'field' => 'featured_image_alt']);
            }
            $alt_attachment = get_post($alt_attachment_id);
            if (!$alt_attachment instanceof WP_Post
                || $alt_attachment->post_type !== 'attachment'
                || !current_user_can('edit_post', $alt_attachment_id)) {
                return new WP_Error('kodety_invalid_featured_image', 'A imagem destacada não pode ser editada por este usuário.', ['status' => 403]);
            }
            $featured_image_alt = sanitize_text_field((string) $values['featured_image_alt']);
        }

        $post_update = ['ID' => $post_id];
        if (array_key_exists('title', $values)) $post_update['post_title'] = sanitize_text_field((string) $values['title']);
        if (array_key_exists('excerpt', $values)) $post_update['post_excerpt'] = sanitize_textarea_field((string) $values['excerpt']);
        if (array_key_exists('content', $values)) $post_update['post_content'] = wp_kses_post((string) $values['content']);
        if (array_key_exists('status', $values)) {
            $status = sanitize_key((string) $values['status']);
            if (!in_array($status, ['publish', 'draft', 'pending', 'private'], true)) {
                return new WP_Error('kodety_invalid_status', 'Status de conteúdo inválido.', ['status' => 400, 'field' => 'status']);
            }
            $type = get_post_type_object($post->post_type);
            if (in_array($status, ['publish', 'private'], true)
                && (!$type || !current_user_can($type->cap->publish_posts ?? 'publish_posts'))) {
                return new WP_Error('kodety_cannot_publish_item', 'Sem permissão para publicar itens desta collection.', ['status' => 403]);
            }
            $post_update['post_status'] = $status;
        }
        $slug_value = null;
        if (array_key_exists('slug', $values)) {
            $slug_value = sanitize_title((string) $values['slug']);
        } elseif (array_key_exists('permalink', $values)) {
            $permalink_path = wp_parse_url((string) $values['permalink'], PHP_URL_PATH);
            if (is_string($permalink_path) && $permalink_path !== '') {
                $slug_value = sanitize_title(basename(untrailingslashit($permalink_path)));
            }
        }
        if (array_key_exists('slug', $values) || array_key_exists('permalink', $values)) {
            if (!is_string($slug_value) || $slug_value === '') {
                return new WP_Error('kodety_invalid_slug', 'O slug do item é inválido.', ['status' => 400, 'field' => 'slug']);
            }
            $target_status = (string) ($post_update['post_status'] ?? $post->post_status);
            if (function_exists('wp_unique_post_slug')) {
                $slug_value = wp_unique_post_slug(
                    $slug_value,
                    $post_id,
                    $target_status,
                    $post->post_type,
                    (int) ($post->post_parent ?? 0)
                );
            }
            $post_update['post_name'] = $slug_value;
        }

        /** @var array<string,array{objectId:int,key:string,exists:bool,value:mixed}> $meta_snapshots */
        $meta_snapshots = [];
        foreach ($custom_writes as $write) {
            $this->snapshot_cms_meta($meta_snapshots, $post_id, $write['field']);
            if ($write['kind'] === 'acf' && is_string($write['acf']['key'] ?? null) && $write['acf']['key'] !== '') {
                $this->snapshot_cms_meta($meta_snapshots, $post_id, '_' . $write['field']);
            }
        }
        if (array_key_exists('featured_image', $values)) {
            $this->snapshot_cms_meta($meta_snapshots, $post_id, '_thumbnail_id');
        }
        if ($featured_image_alt !== null) {
            $this->snapshot_cms_meta($meta_snapshots, $alt_attachment_id, '_wp_attachment_image_alt');
        }

        $post_write_started = false;
        if (count($post_update) > 1) {
            $post_write_started = true;
            $updated = wp_update_post(wp_slash($post_update), true);
            $updated_post = get_post($post_id);
            if (is_wp_error($updated)
                || (int) $updated !== $post_id
                || !$updated_post instanceof WP_Post
                || !$this->cms_post_matches_update($updated_post, $post_update)) {
                return $this->cms_item_persistence_error(
                    $post_id,
                    $post_before,
                    $meta_snapshots,
                    true,
                    'post',
                    'Os campos nativos não puderam ser confirmados no WordPress.'
                );
            }
        }
        foreach ($custom_writes as $write) {
            $field = $write['field'];
            $value = $write['value'];
            if ($write['kind'] === 'native') {
                update_post_meta($post_id, $field, wp_slash($value));
                $stored = get_post_meta($post_id, $field, true);
                if (!$this->cms_persisted_values_match($stored, $value)) {
                    return $this->cms_item_persistence_error(
                        $post_id,
                        $post_before,
                        $meta_snapshots,
                        $post_write_started,
                        'field:' . $field,
                        'Um campo da collection não pôde ser confirmado no WordPress.'
                    );
                }
                continue;
            }
            $acf_field = $write['acf'];
            $selector = is_string($acf_field['key'] ?? null) && $acf_field['key'] !== ''
                ? $acf_field['key']
                : $field;
            // Programmatic ACF writes ultimately reach update_metadata(), which
            // expects slashed input just like native WordPress post/meta APIs.
            $acf_result = update_field($selector, wp_slash($value), $post_id);
            $stored = get_field($selector, $post_id, false);
            $reference_matches = !is_string($acf_field['key'] ?? null)
                || $acf_field['key'] === ''
                || $this->cms_persisted_values_match(
                    get_post_meta($post_id, '_' . $field, true),
                    $acf_field['key']
                );
            if (is_wp_error($acf_result)
                || !$this->cms_persisted_values_match($stored, $value)
                || !$reference_matches) {
                return $this->cms_item_persistence_error(
                    $post_id,
                    $post_before,
                    $meta_snapshots,
                    $post_write_started,
                    'field:' . $field,
                    'Um campo ACF não pôde ser confirmado no WordPress.'
                );
            }
        }
        if (array_key_exists('featured_image', $values)) {
            if ((int) $featured_attachment_id > 0) set_post_thumbnail($post_id, (int) $featured_attachment_id);
            else delete_post_thumbnail($post_id);
            if ((int) get_post_thumbnail_id($post_id) !== (int) $featured_attachment_id) {
                return $this->cms_item_persistence_error(
                    $post_id,
                    $post_before,
                    $meta_snapshots,
                    $post_write_started,
                    'featured_image',
                    'A imagem destacada não pôde ser confirmada no WordPress.'
                );
            }
        }
        if ($featured_image_alt !== null) {
            update_post_meta($alt_attachment_id, '_wp_attachment_image_alt', wp_slash($featured_image_alt));
            if (!$this->cms_persisted_values_match(
                get_post_meta($alt_attachment_id, '_wp_attachment_image_alt', true),
                $featured_image_alt
            )) {
                return $this->cms_item_persistence_error(
                    $post_id,
                    $post_before,
                    $meta_snapshots,
                    $post_write_started,
                    'featured_image_alt',
                    'O texto alternativo não pôde ser confirmado no WordPress.'
                );
            }
        }
        // Consumers only observe a state whose post, metadata, ACF reference,
        // thumbnail and alt text all received a durable readback ACK.
        if ($emit_saved_action) do_action('kodety_cms_item_saved', $post_id);
        return null;
    }

    /** Accept an attachment reference as ID, numeric string or media library URL. */
    private function resolve_attachment_id(mixed $reference): int {
        if (is_numeric($reference)) return absint($reference);
        if (is_array($reference) && isset($reference['id']) && is_numeric($reference['id'])) return absint($reference['id']);
        if (is_string($reference) && $reference !== '' && preg_match('~^https?://~i', $reference)) {
            return (int) attachment_url_to_postid($reference);
        }
        return 0;
    }

    private function cms_item_payload(WP_Post $post): array {
        $thumbnail_id = get_post_thumbnail_id($post);
        $values = [
            'title' => get_the_title($post),
            'excerpt' => get_the_excerpt($post),
            'content' => (string) $post->post_content,
            'featured_image' => $thumbnail_id ? (string) wp_get_attachment_image_url($thumbnail_id, 'full') : '',
            'featured_image_alt' => $thumbnail_id ? (string) get_post_meta($thumbnail_id, '_wp_attachment_image_alt', true) : '',
            'permalink' => $this->cms_item_permalink($post),
            'date' => get_the_date('', $post),
            'author' => get_the_author_meta('display_name', (int) $post->post_author),
            'slug' => $post->post_name,
        ];
        if (function_exists('get_fields')) {
            foreach ((array) get_fields($post->ID) as $key => $value) {
                $field_object = function_exists('get_field_object') ? get_field_object($key, $post->ID, false, false) : null;
                if (is_array($field_object) && ($field_object['type'] ?? '') === 'image') {
                    if (is_array($value) && isset($value['url'])) $value = (string) $value['url'];
                    elseif (is_numeric($value)) $value = (string) (wp_get_attachment_image_url(absint($value), 'full') ?: '');
                }
                $values['field:' . sanitize_key((string) $key)] = $value;
            }
        }
        // Kodety-native fields live in plain post meta and must be present in the
        // payload even without ACF, otherwise the Builder preview stays empty.
        // They also deliberately override an ACF field with the same name,
        // matching the write-side source-of-truth rule above.
        foreach ($this->custom_field_definitions($post->post_type) as $field) {
            $key = 'field:' . $field['name'];
            $value = get_post_meta($post->ID, $field['name'], true);
            if ($field['type'] === 'image' && is_numeric($value)) $value = (string) (wp_get_attachment_image_url(absint($value), 'full') ?: '');
            $values[$key] = $value;
        }
        return [
            'id' => $post->ID,
            'type' => $post->post_type,
            'status' => $post->post_status,
            'label' => get_the_title($post) ?: sprintf('Item #%d', $post->ID),
            'editUrl' => current_user_can('edit_post', $post->ID) ? get_edit_post_link($post, 'raw') : '',
            'dateIso' => (string) get_post_time('c', true, $post),
            'modifiedIso' => (string) get_post_modified_time('c', true, $post),
            'featuredImageId' => (int) $thumbnail_id,
            'thumbnail' => $thumbnail_id ? (string) wp_get_attachment_image_url($thumbnail_id, 'medium') : '',
            'capabilities' => [
                'edit' => current_user_can('edit_post', $post->ID),
                'delete' => current_user_can('delete_post', $post->ID),
                'publish' => current_user_can(
                    get_post_type_object($post->post_type)?->cap->publish_posts ?? 'publish_posts'
                ),
            ],
            'values' => $values,
            'revision' => $this->cms_item_revision($post),
        ];
    }

    public function save_cms_template(WP_REST_Request $request): WP_REST_Response|WP_Error {
        return $this->with_cms_mutation_lock(fn(): WP_REST_Response|WP_Error => $this->save_cms_template_locked($request));
    }

    private function save_cms_template_locked(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $post_type = sanitize_key((string) $request->get_param('postType'));
        $html_path = ltrim(str_replace('\\', '/', sanitize_text_field((string) $request->get_param('htmlPath'))), '/');
        if ($post_type === '' || !post_type_exists($post_type)) return new WP_Error('kodety_invalid_post_type', 'Tipo de conteúdo inválido.', ['status' => 400]);
        if ($html_path !== '' && (!preg_match('/\.html?$/i', $html_path) || str_contains($html_path, '../'))) return new WP_Error('kodety_invalid_template', 'Arquivo HTML inválido.', ['status' => 400]);
        $revision = $this->cms_schema_revision();
        $current_templates = $this->cms_template_definitions();
        $revision_error = $this->cms_expected_revision_error(
            $request,
            'template:' . $post_type,
            $revision,
            [
                'postType' => $post_type,
                'htmlPath' => (string) ($current_templates[$post_type] ?? ''),
                'templates' => $current_templates,
            ]
        );
        if ($revision_error) return $revision_error;
        $raw_previous_templates = $this->project_cms_option('kodety_cms_templates', []);
        $previous_templates = is_array($raw_previous_templates) ? $raw_previous_templates : [];
        $templates = $this->cms_template_definitions();
        if ($html_path === '') {
            unset($templates[$post_type]);
        } else {
            // One page is the template for one collection. Assigning the
            // current page from the Builder therefore performs a real move,
            // instead of silently leaving it attached to multiple types.
            foreach ($templates as $assigned_type => $assigned_path) {
                if ($assigned_type !== $post_type && $assigned_path === $html_path) unset($templates[$assigned_type]);
            }
            $templates[$post_type] = $html_path;
        }
        if (!$this->write_cms_option_with_ack('kodety_cms_templates', $templates)) {
            $rollback_ok = $this->write_cms_option_with_ack('kodety_cms_templates', $previous_templates);
            return new WP_Error(
                'kodety_template_persistence_failed',
                'A página CMS não pôde ser confirmada no WordPress.',
                ['status' => 500, 'rollbackFailed' => !$rollback_ok]
            );
        }
        return new WP_REST_Response([
            'postType' => $post_type,
            'htmlPath' => $html_path,
            'templates' => $templates,
            'revision' => $this->cms_schema_revision(),
        ]);
    }

    private function cms_template_definitions(): array {
        $templates = $this->project_cms_option('kodety_cms_templates', []);
        if (!is_array($templates)) return [];
        $clean = [];
        foreach ($templates as $post_type => $html_path) {
            $post_type = sanitize_key((string) $post_type);
            $html_path = ltrim(str_replace('\\', '/', sanitize_text_field((string) $html_path)), '/');
            if ($post_type !== '' && $html_path !== '' && !str_contains($html_path, '../')) $clean[$post_type] = $html_path;
        }
        return $clean;
    }

    public function maybe_install_custom_fields_plugin(): void {
        if (!function_exists('is_plugin_active')) require_once ABSPATH . 'wp-admin/includes/plugin.php';
        if (get_option('kodety_acf_install_pending', null) === null) add_option('kodety_acf_install_pending', '1', '', false);
        if (get_option('kodety_acf_install_pending', '0') !== '1' || !current_user_can('install_plugins')) return;
        $plugin_file = 'advanced-custom-fields/acf.php';
        if (is_file(WP_PLUGIN_DIR . '/' . $plugin_file)) {
            if (!is_plugin_active($plugin_file) && current_user_can('activate_plugins')) activate_plugin($plugin_file);
            update_option('kodety_acf_install_pending', '0', false);
            return;
        }
        if (!function_exists('plugins_api')) require_once ABSPATH . 'wp-admin/includes/plugin-install.php';
        if (!class_exists('Plugin_Upgrader')) require_once ABSPATH . 'wp-admin/includes/class-wp-upgrader.php';
        $api = plugins_api('plugin_information', ['slug' => 'advanced-custom-fields', 'fields' => ['sections' => false]]);
        if (is_wp_error($api) || empty($api->download_link)) return;
        $skin = new Automatic_Upgrader_Skin();
        $result = (new Plugin_Upgrader($skin))->install($api->download_link);
        if ($result === true && is_file(WP_PLUGIN_DIR . '/' . $plugin_file)) {
            activate_plugin($plugin_file);
            update_option('kodety_acf_install_pending', '0', false);
        }
    }

    public function set_cms_template_from_admin(): void {
        if (!current_user_can(self::CAP_MANAGE_CMS_TEMPLATES)) wp_die('Sem permissão.', 403);
        $post_id = absint($_GET['post'] ?? 0);
        check_admin_referer('kodety_set_cms_template_' . $post_id);
        $post = get_post($post_id);
        if (!$post instanceof WP_Post || $post->post_type !== 'page') wp_die('Página inválida.', 400);
        $path = (string) get_post_meta($post_id, '_kodety_html_path', true);
        if ($path === '') wp_die('Esta página não pertence ao projeto Onun Kodety.', 400);
        wp_safe_redirect(add_query_arg(['kodety_html' => $path, 'kodety_cms_template' => '1'], home_url('/kodety/editor/')));
        exit;
    }

    private function collection_definitions(?string $project_id = null): array {
        $definitions = $project_id === null
            ? $this->project_cms_option('kodety_collections', [])
            : $this->project_cms_option_for_scope('kodety_collections', $project_id, []);
        $definitions = is_array($definitions) ? array_values(array_filter($definitions, 'is_array')) : [];
        return Kodety_Edition::visible_collection_definitions($definitions);
    }

    private function cms_collection_read_only(string $post_type): bool {
        $post_type = sanitize_key($post_type);
        foreach ($this->collection_definitions() as $definition) {
            if (sanitize_key((string) ($definition['slug'] ?? '')) !== $post_type) continue;
            return !empty($definition['readOnly']);
        }
        return false;
    }

    /** Claim pre-project CMS state for the workspace mounted during upgrade. */
    private function migrate_legacy_cms_project_scope(): bool {
        $options = ['kodety_collections', 'kodety_field_definitions', 'kodety_cms_templates'];
        $legacy = [];
        $has_legacy_state = false;
        foreach ($options as $option) {
            $value = get_option($option, []);
            $legacy[$option] = is_array($value) ? $value : [];
            if ($legacy[$option] !== []) $has_legacy_state = true;
        }
        $scope = $this->cms_workspace_project_id();
        if ($scope === '') return !$has_legacy_state;

        $result = $this->with_cms_mutation_lock(function () use ($options, $scope): bool {
            if (!hash_equals($scope, $this->cms_workspace_project_id())) return false;
            $owner = sanitize_key((string) get_option(self::CMS_LEGACY_SCOPE_OWNER_OPTION, ''));
            if ($owner !== '' && !hash_equals($owner, $scope)) return false;
            if ($owner === '') {
                update_option(self::CMS_LEGACY_SCOPE_OWNER_OPTION, $scope, false);
                $owner = sanitize_key((string) get_option(self::CMS_LEGACY_SCOPE_OWNER_OPTION, ''));
                if ($owner === '' || !hash_equals($owner, $scope)) return false;
            }

            $missing = new stdClass();
            foreach ($options as $option) {
                $target = $option . '__project_' . $scope;
                if (get_option($target, $missing) !== $missing) continue;
                $legacy_value = get_option($option, []);
                $legacy_value = is_array($legacy_value) ? $legacy_value : [];
                update_option($target, $legacy_value, false);
                $stored = get_option($target, $missing);
                if (
                    $stored === $missing
                    || !is_array($stored)
                    || !$this->cms_persisted_values_match($stored, $legacy_value, false)
                ) {
                    return false;
                }
            }

            $definitions = get_option('kodety_collections__project_' . $scope, []);
            $post_types = [];
            foreach (is_array($definitions) ? $definitions : [] as $definition) {
                if (!is_array($definition)) continue;
                $post_type = sanitize_key((string) ($definition['slug'] ?? ''));
                if ($post_type !== '') $post_types[$post_type] = true;
            }
            if ($post_types) {
                $post_ids = get_posts([
                    'post_type' => array_keys($post_types),
                    'post_status' => function_exists('get_post_stati')
                        ? array_values(get_post_stati())
                        : ['publish', 'draft', 'pending', 'future', 'private', 'trash'],
                    'posts_per_page' => -1,
                    'fields' => 'ids',
                    'orderby' => 'ID',
                    'order' => 'ASC',
                    'no_found_rows' => true,
                    'kodety_legacy_scope_migration' => true,
                ]);
                foreach (is_array($post_ids) ? $post_ids : [] as $post_id) {
                    $post_id = absint($post_id);
                    if ($post_id <= 0) continue;
                    $item_scope = sanitize_key((string) get_post_meta($post_id, '_kodety_project_id', true));
                    if ($item_scope !== '') continue;
                    update_post_meta($post_id, '_kodety_project_id', $scope);
                    $stored_scope = sanitize_key((string) get_post_meta($post_id, '_kodety_project_id', true));
                    if ($stored_scope === '' || !hash_equals($scope, $stored_scope)) return false;
                }
            }
            return true;
        });
        return $result === true;
    }

    /** Prevent wp-admin and generic REST clients from mutating integration-managed items. */
    public function protect_read_only_cms_items(array $caps, string $cap, int $user_id, array $args): array {
        if (!in_array($cap, ['edit_post', 'delete_post'], true)) return $caps;
        $post = get_post(absint($args[0] ?? 0));
        if (!$post instanceof WP_Post) return $caps;
        $is_project_item = metadata_exists('post', $post->ID, '_kodety_project_id')
            || $this->is_project_collection($post->post_type)
            || $this->is_project_collection_outside_current_scope($post->post_type);
        if (!$is_project_item) return $caps;
        if (!$this->cms_item_belongs_to_current_project($post->ID, $post->post_type)) return ['do_not_allow'];
        return $this->cms_collection_read_only($post->post_type) ? ['do_not_allow'] : $caps;
    }

    /**
     * CMS authoring options belong to the selected agency project.
     *
     * The unsuffixed option remains only for a truly ID-less legacy workspace.
     * Once a project ID exists, every read and write uses its exact namespace.
     */
    private function project_cms_option_name(string $option): string {
        if (!in_array($option, ['kodety_collections', 'kodety_field_definitions', 'kodety_cms_templates'], true)) return $option;
        $project_id = $this->workspace_mode() === 'agency'
            ? $this->agency_active_project_id()
            : $this->cms_workspace_project_id();
        return $project_id !== '' ? $option . '__project_' . $project_id : $option;
    }

    private function project_cms_option_for_scope(string $option, string $project_id, mixed $default = []): mixed {
        $project_id = function_exists('sanitize_key')
            ? sanitize_key($project_id)
            : (preg_replace('/[^a-z0-9_-]/', '', strtolower($project_id)) ?: '');
        if ($project_id === '' || !in_array($option, ['kodety_collections', 'kodety_field_definitions', 'kodety_cms_templates'], true)) {
            return get_option($option, $default);
        }
        $missing = new stdClass();
        $value = get_option($option . '__project_' . $project_id, $missing);
        return $value === $missing ? $default : $value;
    }

    public function project_cms_option(string $option, mixed $default = []): mixed {
        $scope = $this->workspace_mode() === 'agency'
            ? (is_admin() ? $this->agency_active_project_id() : $this->cms_project_scope_key())
            : $this->cms_workspace_project_id();
        return $this->project_cms_option_for_scope($option, $scope, $default);
    }

    public function update_project_cms_option(string $option, array $value, ?array $expected_current = null): bool {
        // Internal integrations also perform read-modify-write. Refuse legacy
        // blind writes; their caller must supply the exact snapshot it read so
        // the comparison can happen after acquiring the same CMS lock as REST.
        if ($expected_current === null) return false;
        $result = $this->with_cms_mutation_lock(function () use ($option, $value, $expected_current): bool {
            $current = $this->project_cms_option($option, []);
            $current = is_array($current) ? $current : [];
            if (!$this->cms_persisted_values_match($current, $expected_current, false)) return false;
            if ($option === 'kodety_collections') {
                $limit = Kodety_Edition::limit('collections');
                if ($limit !== null && count(array_filter($value, 'is_array')) > $limit) return false;
            }
            return $this->write_cms_option_with_ack($option, $value);
        });
        return $result === true;
    }

    public function is_managed_collection(string $post_type): bool {
        return $this->is_project_collection(sanitize_key($post_type));
    }

    private function cms_project_scope_key(): string {
        if ($this->workspace_mode() !== 'agency') return $this->cms_workspace_project_id();
        if (class_exists('Kodety_Sharing')) {
            $shared_project_id = Kodety_Sharing::instance()->project_id();
            if ($shared_project_id !== '' && $shared_project_id !== 'single') {
                return $shared_project_id;
            }
        }
        $projects = $this->agency_projects();
        if (!is_admin()) {
            $path = (string) wp_parse_url((string) ($_SERVER['REQUEST_URI'] ?? '/'), PHP_URL_PATH);
            if (defined('REST_REQUEST') && REST_REQUEST && str_contains(trim($path, '/'), 'wp-json/')) {
                $referer_path = (string) wp_parse_url(
                    (string) ($_SERVER['HTTP_REFERER'] ?? ''),
                    PHP_URL_PATH
                );
                if ($referer_path !== '' && !str_contains($referer_path, '/wp-admin/')) {
                    $path = $referer_path;
                } else {
                    return $this->agency_active_project_id();
                }
            }
            $path = trim($path, '/');
            $segment = sanitize_title(explode('/', $path, 2)[0] ?? '');
            foreach ($projects as $id => $project) {
                if (!is_array($project)) continue;
                if ($segment !== '' && sanitize_title((string) ($project['slug'] ?? '')) === $segment) {
                    return sanitize_key((string) $id);
                }
            }
            foreach ($projects as $id => $project) {
                if (is_array($project) && !empty($project['isRoot'])) return sanitize_key((string) $id);
            }
        }
        return $this->agency_active_project_id();
    }

    private function is_project_collection(string $post_type): bool {
        $scope = $this->cms_project_scope_key();
        $definitions = $scope !== ''
            ? $this->collection_definitions($scope)
            : $this->collection_definitions();
        foreach ($definitions as $definition) {
            if (sanitize_key((string) ($definition['slug'] ?? '')) === $post_type) return true;
        }
        return false;
    }

    /** A registered agency post type may belong exclusively to a sibling project. */
    private function is_project_collection_outside_current_scope(string $post_type): bool {
        $post_type = sanitize_key($post_type);
        if ($post_type === '' || $this->is_project_collection($post_type)) return false;
        $scope = $this->cms_project_scope_key();
        foreach (array_keys($this->agency_projects()) as $project_id) {
            $project_id = sanitize_key((string) $project_id);
            if ($project_id === '' || ($scope !== '' && hash_equals($scope, $project_id))) continue;
            foreach ($this->collection_definitions($project_id) as $definition) {
                if (sanitize_key((string) ($definition['slug'] ?? '')) === $post_type) return true;
            }
        }
        return false;
    }

    private function cms_item_belongs_to_current_project(int $post_id, string $post_type): bool {
        $is_project_collection = $this->is_project_collection($post_type);
        if (!$is_project_collection && $this->is_project_collection_outside_current_scope($post_type)) return false;
        $scope = $this->cms_project_scope_key();
        $item_scope = sanitize_key((string) get_post_meta($post_id, '_kodety_project_id', true));
        if (!$is_project_collection && !metadata_exists('post', $post_id, '_kodety_project_id')) return true;
        if ($scope === '') return $item_scope === '';
        return $item_scope !== '' && hash_equals($scope, $item_scope);
    }

    /** Keep public archives/items from one agency project out of every other site. */
    public function scope_agency_cms_query(WP_Query $query): void {
        if ($query->get('kodety_legacy_scope_migration')) return;
        $post_types = (array) $query->get('post_type');
        $outside_scope = array_values(array_filter(
            $post_types,
            fn(mixed $post_type): bool => is_string($post_type) && $this->is_project_collection_outside_current_scope($post_type)
        ));
        if ($outside_scope) {
            $query->set('post__in', [0]);
            return;
        }
        $collections = array_values(array_filter(
            $post_types,
            fn(mixed $post_type): bool => is_string($post_type) && $this->is_project_collection($post_type)
        ));
        $scope = $this->cms_project_scope_key();
        $scope_clause = null;
        if ($collections) {
            $scope_clause = $scope !== '' ? [
                'key' => '_kodety_project_id',
                'value' => $scope,
                'compare' => '=',
            ] : [
                'key' => '_kodety_project_id',
                'compare' => 'NOT EXISTS',
            ];
        } else {
            // Core REST, public, wp-admin and AJAX searches may query `post`,
            // `any` or no explicit post type. Preserve ordinary unscoped
            // WordPress content while excluding sibling-owned records on every
            // surface; internal cross-scope maintenance needs an explicit marker.
            $scope_clause = $scope !== '' ? [
                'relation' => 'OR',
                [
                    'key' => '_kodety_project_id',
                    'value' => $scope,
                    'compare' => '=',
                ],
                [
                    'key' => '_kodety_project_id',
                    'compare' => 'NOT EXISTS',
                ],
            ] : [
                'key' => '_kodety_project_id',
                'compare' => 'NOT EXISTS',
            ];
        }
        $meta_query = $query->get('meta_query');
        $meta_query = is_array($meta_query) ? $meta_query : [];
        $query->set('meta_query', $meta_query === []
            ? [$scope_clause]
            : ['relation' => 'AND', $meta_query, $scope_clause]);
    }

    private function workspace_mode(): string {
        return 'single';
    }

    private function project_admin_page_slug(): string {
        return 'kodety';
    }

    private function project_admin_url(string $hash = ''): string {
        return admin_url('admin.php?page=' . $this->project_admin_page_slug()) . $hash;
    }

    public function maybe_redirect_to_onboarding(): void {
        $test_requested = isset($_GET['onboarding'])
            && sanitize_text_field((string) wp_unslash($_GET['onboarding'])) === 'teste';
        $page = sanitize_key((string) ($_GET['page'] ?? ''));
        if (
            $test_requested
            && current_user_can('manage_options')
            && !wp_doing_ajax()
            && !wp_doing_cron()
            && !(defined('WP_CLI') && WP_CLI)
            && $page !== 'kodety-onboarding'
        ) {
            wp_safe_redirect(admin_url('admin.php?page=kodety-onboarding&onboarding=teste'));
            exit;
        }
        if (
            get_option('kodety_onboarding_status', 'complete') !== 'pending'
            || !current_user_can('manage_options')
            || wp_doing_ajax()
            || wp_doing_cron()
            || (defined('WP_CLI') && WP_CLI)
        ) {
            return;
        }
        if ($page === 'kodety-onboarding') return;
        global $pagenow;
        if ($pagenow === 'admin-post.php') return;
        wp_safe_redirect(admin_url('admin.php?page=kodety-onboarding'));
        exit;
    }

    public function admin_menu(): void {
        remove_menu_page('edit.php');
        $i18n = class_exists('Kodety_Admin_I18n') ? Kodety_Admin_I18n::instance() : null;
        $label = static fn(string $key, string $fallback): string => $i18n
            ? $i18n->message($key)
            : $fallback;
        $agency_mode = $this->workspace_mode() === 'agency';
        if ($agency_mode) {
            // Pages belong to a specific project in an agency workspace. The
            // shared WordPress list is therefore ambiguous; project selection
            // must happen in the agency dashboard first.
            remove_menu_page('edit.php?post_type=page');
        }
        add_menu_page('Onun Kodety CMS', 'Onun Kodety CMS', self::CAP_ACCESS_CMS, 'kodety-cms', '__return_null', 'dashicons-database', 5);
        add_submenu_page('kodety-cms', $label('cms.overview', 'Visão geral do CMS'), $label('cms.overview_short', 'Visão geral'), self::CAP_ACCESS_CMS, 'kodety-cms', '__return_null');
        add_submenu_page('kodety-cms', $label('cms.new_item', 'Novo item'), $label('cms.new_item', 'Novo item'), self::CAP_ACCESS_CMS, 'kodety-cms-new-item', '__return_null');
        add_submenu_page('kodety-cms', $label('cms.collections', 'Collections'), $label('cms.collections', 'Collections'), self::CAP_MANAGE_CMS_SCHEMA, 'kodety-cms-collections', '__return_null');
        add_submenu_page('kodety-cms', $label('cms.fields', 'Campos'), $label('cms.fields', 'Campos'), self::CAP_MANAGE_CMS_SCHEMA, 'kodety-cms-fields', '__return_null');
        if (!class_exists('Kodety_Extensions') || Kodety_Extensions::instance()->is_active('kodety-analytics')) {
            add_menu_page('Onun Kodety Analytics', 'Analytics', self::CAP_VIEW_ANALYTICS, 'kodety-analytics', '__return_null', 'dashicons-chart-area', 6);
        }
        add_menu_page('Onun Kodety', 'Onun Kodety', self::CAP_EDIT_WORKSPACE, 'kodety', [$this, 'admin_home_page'], 'dashicons-layout', 58);
        if ($agency_mode) {
            add_submenu_page('kodety', $label('nav.settings', 'Configurações'), $label('nav.settings', 'Configurações'), self::CAP_EDIT_WORKSPACE, 'kodety', [$this, 'admin_home_page']);
        }
        add_submenu_page('kodety', $label('nav.builder', 'Builder'), $label('nav.builder', 'Builder'), self::CAP_EDIT_WORKSPACE, 'kodety-editor', '__return_null');
        $onboarding_hook = add_submenu_page(null, $i18n ? $i18n->translate('Primeiros passos Onun Kodety') : 'Primeiros passos Onun Kodety', $i18n ? $i18n->translate('Primeiros passos Onun Kodety') : 'Primeiros passos Onun Kodety', 'manage_options', 'kodety-onboarding', [$this, 'onboarding_page']);
        // Keep WordPress authentication and capability checks, but render
        // before admin-header.php: this document owns all of its CSS and JS.
        if ($onboarding_hook) add_action('load-' . $onboarding_hook, [$this, 'render_onboarding_document']);
        add_submenu_page(null, $i18n ? $i18n->translate('Substituir asset Onun Kodety') : 'Substituir asset Onun Kodety', $i18n ? $i18n->translate('Substituir asset Onun Kodety') : 'Substituir asset Onun Kodety', 'upload_files', 'kodety-replace-asset', [$this, 'replace_asset_page']);
    }

    public function admin_home_page(): void {
        $this->admin_page();
    }

    public function admin_redirects(): void {
        $admin_page = sanitize_key((string) ($_GET['page'] ?? ''));
        if (
            $admin_page === 'kodety-project-settings'
            && current_user_can(self::CAP_EDIT_WORKSPACE)
        ) {
            wp_safe_redirect($this->project_admin_url('#kodety-settings'));
            exit;
        }
        $cms_targets = [
            'kodety-cms' => ['query' => [], 'capability' => self::CAP_ACCESS_CMS],
            'kodety-cms-collections' => ['query' => ['view' => 'collections'], 'capability' => self::CAP_MANAGE_CMS_SCHEMA],
            'kodety-cms-fields' => ['query' => ['view' => 'fields'], 'capability' => self::CAP_MANAGE_CMS_SCHEMA],
            'kodety-cms-new-item' => ['query' => ['action' => 'new-item'], 'capability' => self::CAP_ACCESS_CMS],
        ];
        if (
            isset($cms_targets[$admin_page])
            && current_user_can($cms_targets[$admin_page]['capability'])
        ) {
            wp_safe_redirect(add_query_arg($cms_targets[$admin_page]['query'], home_url('/kodety/cms/')));
            exit;
        }
        if ($admin_page === 'kodety-editor' && current_user_can(self::CAP_EDIT_WORKSPACE)) {
            // In agency mode the generic Builder entry has no safe implicit
            // target. Send the user to the project dashboard; project cards
            // remain responsible for restoring and opening the chosen project.
            wp_safe_redirect(
                $this->workspace_mode() === 'agency'
                    ? admin_url()
                    : home_url('/kodety/editor/')
            );
            exit;
        }
        if ($admin_page === 'kodety-analytics' && current_user_can(self::CAP_VIEW_ANALYTICS)) {
            wp_safe_redirect(home_url('/kodety/analytics/'));
            exit;
        }

        global $pagenow;
        $collection_slugs = array_values(array_filter(array_map(
            static fn(array $definition): string => sanitize_key((string) ($definition['slug'] ?? '')),
            $this->collection_definitions()
        )));
        $requested_type = sanitize_key((string) ($_GET['post_type'] ?? ''));
        if (
            in_array($requested_type, $collection_slugs, true)
            && in_array($pagenow, ['post-new.php', 'edit.php'], true)
            && current_user_can(self::CAP_ACCESS_CMS)
        ) {
            $query = ['collection' => $requested_type];
            if ($pagenow === 'post-new.php') $query['action'] = 'new-item';
            wp_safe_redirect(add_query_arg($query, home_url('/kodety/cms/')));
            exit;
        }
        // "Adicionar página" (menu, dashboard e o "+ Novo" da barra) sempre
        // apontam para post-new.php. Com um projeto no workspace, a página nova
        // pertence ao projeto: abre o builder, que cria a página vazia dentro
        // dele. Sem workspace importado não há onde criar, então o editor
        // nativo continua respondendo.
        if (
            $pagenow === 'post-new.php'
            && $requested_type === 'page'
            && empty($_GET['kodety_native'])
            && current_user_can(self::CAP_EDIT_WORKSPACE)
            && is_dir($this->workspace_dir())
        ) {
            wp_safe_redirect(add_query_arg('kodety_new_page', '1', home_url('/kodety/editor/')));
            exit;
        }
        if ($pagenow === 'post.php' && current_user_can(self::CAP_ACCESS_CMS)) {
            $cms_post = get_post(absint($_GET['post'] ?? 0));
            if ($cms_post instanceof WP_Post && in_array($cms_post->post_type, $collection_slugs, true)) {
                wp_safe_redirect(add_query_arg(['collection' => $cms_post->post_type], home_url('/kodety/cms/')));
                exit;
            }
        }
        if (
            $pagenow === 'post.php'
            && sanitize_key((string) ($_GET['action'] ?? '')) === 'edit'
            && empty($_GET['kodety_native'])
            && current_user_can(self::CAP_EDIT_WORKSPACE)
        ) {
            $post = get_post(absint($_GET['post'] ?? 0));
            $editor_url = $post instanceof WP_Post ? $this->managed_page_editor_url($post) : '';
            if ($editor_url !== '') {
                wp_safe_redirect($editor_url);
                exit;
            }
        }
    }

    private function is_interface_enabled(): bool {
        return in_array(get_option('kodety_interface_enabled', '1'), ['1', 1, true], true);
    }

    public static function interface_accent_contrast_ratio(string $value): float {
        $color = strtolower(trim($value));
        if (!preg_match('/^#[0-9a-f]{6}$/', $color)) return 0.0;
        $channels = [
            hexdec(substr($color, 1, 2)) / 255,
            hexdec(substr($color, 3, 2)) / 255,
            hexdec(substr($color, 5, 2)) / 255,
        ];
        $linear = array_map(static function (float $channel): float {
            return $channel <= 0.04045
                ? $channel / 12.92
                : (($channel + 0.055) / 1.055) ** 2.4;
        }, $channels);
        $luminance = (0.2126 * $linear[0]) + (0.7152 * $linear[1]) + (0.0722 * $linear[2]);
        return ($luminance + 0.05) / 0.05;
    }

    public static function is_valid_interface_accent_color(string $value): bool {
        $color = strtolower(trim($value));
        return preg_match('/^#[0-9a-f]{6}$/', $color) === 1
            && self::interface_accent_contrast_ratio($color) >= self::MIN_BLACK_TEXT_CONTRAST;
    }

    public static function normalize_interface_accent_color($value): string {
        if (!is_string($value)) return self::DEFAULT_ADMIN_ACCENT_COLOR;
        $color = strtolower(trim($value));
        return self::is_valid_interface_accent_color($color)
            ? $color
            : self::DEFAULT_ADMIN_ACCENT_COLOR;
    }

    private function admin_accent_css(bool $include_native_tokens = true): string {
        $accent = self::normalize_interface_accent_color(get_option(
            'kodety_admin_accent_color',
            self::DEFAULT_ADMIN_ACCENT_COLOR
        ));
        $is_default_accent = strtolower($accent) === strtolower(self::DEFAULT_ADMIN_ACCENT_COLOR);
        $hover = $is_default_accent
            ? self::DEFAULT_ADMIN_ACCENT_HOVER_COLOR
            : 'color-mix(in srgb,var(--kodety-admin-accent) 86%,white)';
        $foreground = '#000';
        return ':root{'
            . '--kodety-admin-accent:' . $accent . ';'
            . '--kodety-admin-accent-hover:' . $hover . ';'
            . '--kodety-admin-accent-soft:color-mix(in srgb,var(--kodety-admin-accent) 10%,transparent);'
            . '--kodety-admin-accent-foreground:' . $foreground . ';'
            . ($include_native_tokens ? '--wp-admin-theme-color:var(--kodety-admin-accent);'
            . '--wp-admin-theme-color-darker-10:var(--kodety-admin-accent-hover);'
            . '--wp-admin-theme-color-darker-20:var(--kodety-admin-accent-hover);'
            . '--wp-components-color-accent:var(--kodety-admin-accent);'
            . '--wp-components-color-accent-darker-10:var(--kodety-admin-accent-hover);'
            . '--wp-components-color-accent-darker-20:var(--kodety-admin-accent-hover);'
            . '--wp-components-color-accent-inverted:var(--kodety-admin-accent-foreground);' : '')
            . '}';
    }

    private function add_admin_accent_style(string $handle): void {
        wp_add_inline_style($handle, $this->admin_accent_css());
    }

    private function is_block_editor_screen(?WP_Screen $screen): bool {
        return $screen instanceof WP_Screen
            && method_exists($screen, 'is_block_editor')
            && $screen->is_block_editor();
    }

    private function is_native_editor_screen(?WP_Screen $screen): bool {
        return $this->is_block_editor_screen($screen)
            || ($screen instanceof WP_Screen && in_array($screen->base, ['site-editor', 'customize'], true));
    }

    /** CSS-only editor chrome; never enqueue this in the authored canvas iframe. */
    public function editor_chrome_assets(): void {
        if (!$this->is_interface_enabled()) return;
        $file = KODETY_DIR . 'admin/components/editor-chrome.css';
        wp_enqueue_style('kodety-editor-chrome', KODETY_URL . 'admin/components/editor-chrome.css', [], is_file($file) ? (string) filemtime($file) : KODETY_VERSION);
        $this->add_admin_accent_style('kodety-editor-chrome');
    }

    private function is_plugin_owned_admin_screen(?WP_Screen $screen): bool {
        if (
            !$screen instanceof WP_Screen
            || in_array($screen->id, ['toplevel_page_kodety', 'kodety_page_kodety-project-settings'], true)
        ) {
            return false;
        }

        // Plugin-defined content types and taxonomies often ship complex admin
        // applications (ACF is a common example). Preserve their own surface.
        if ($screen->post_type && !str_starts_with((string) $screen->post_type, 'kodety_')) {
            $post_type = get_post_type_object((string) $screen->post_type);
            if ($post_type && empty($post_type->_builtin)) return true;
        }
        if ($screen->taxonomy && !str_starts_with((string) $screen->taxonomy, 'kodety_')) {
            $taxonomy = get_taxonomy((string) $screen->taxonomy);
            if ($taxonomy && empty($taxonomy->_builtin)) return true;
        }

        // Menu pages registered by third-party plugins use these screen IDs.
        // Core screens use stable bases such as options-general, themes or tools.
        return str_starts_with($screen->id, 'toplevel_page_')
            || str_contains($screen->id, '_page_')
            || $screen->base === 'admin_page';
    }

    /** Third-party applications receive only the surrounding Onun Kodety shell. */
    private function admin_surface_scope(?WP_Screen $screen): string {
        $owned_pages = [
            'kodety', 'kodety-project-settings', 'kodety-editor', 'kodety-replace-asset',
            'kodety-cms', 'kodety-cms-new-item', 'kodety-cms-collections', 'kodety-cms-fields',
            'kodety-analytics', 'kodety-media', 'kodety-members', 'kodety-emails',
            'kodety-email-campaigns', 'kodety-email-templates', 'kodety-email-contacts',
            'kodety-email-lists', 'kodety-email-health', 'kodety-email-settings',
            'kodety-manual', 'kodety-templates',
        ];
        if ($screen && preg_match('/_page_(kodety(?:-[a-z0-9-]+)?)$/', $screen->id, $match)
            && in_array($match[1], $owned_pages, true)) {
            return 'owned';
        }
        return $this->is_plugin_owned_admin_screen($screen) ? 'third-party' : 'native';
    }

    public function admin_assets(): void {
        $screen = get_current_screen();
        $is_kodety_page = $screen && in_array($screen->id, [
            'toplevel_page_kodety',
            'kodety_page_kodety-project-settings',
        ], true);
        $is_agency_page = $screen && $screen->id === 'dashboard'
            && $this->workspace_mode() === 'agency';
        $is_onboarding_page = $screen && $screen->id === 'admin_page_kodety-onboarding';
        $interface_enabled = $this->is_interface_enabled();
        $editor_corner_icon = sanitize_key((string) get_option('kodety_editor_corner_icon', 'kodety-logo'));
        if (!in_array($editor_corner_icon, ['kodety-logo', 'client-logo'], true)) $editor_corner_icon = 'kodety-logo';
        $brand_logo_id = absint(get_option('kodety_admin_logo_id', 0));
        $brand_logo_url = $brand_logo_id ? (string) wp_get_attachment_image_url($brand_logo_id, 'thumbnail') : '';
        if ($editor_corner_icon === 'client-logo' && $brand_logo_url === '') $editor_corner_icon = 'kodety-logo';
        if ($is_onboarding_page) {
            return;
        }
        if ($is_agency_page) {
            $agency_style = KODETY_DIR . 'admin/agency.css';
            $agency_script = KODETY_DIR . 'admin/agency.js';
            $icons_script = KODETY_DIR . 'admin/components/kodety-icons.bundle.js';
            wp_enqueue_style('kodety-agency', KODETY_URL . 'admin/agency.css', $interface_enabled ? ['kodety-wp-admin-audit'] : [], is_file($agency_style) ? (string) filemtime($agency_style) : KODETY_VERSION);
            wp_enqueue_script('kodety-admin-icons', KODETY_URL . 'admin/components/kodety-icons.bundle.js', [], is_file($icons_script) ? (string) filemtime($icons_script) : KODETY_VERSION, true);
            wp_enqueue_script('kodety-agency', KODETY_URL . 'admin/agency.js', ['kodety-admin-icons'], is_file($agency_script) ? (string) filemtime($agency_script) : KODETY_VERSION, true);
            $this->add_admin_accent_style('kodety-agency');
        }
        if ($is_kodety_page && !$is_agency_page) {
            // Resolve hash navigation before the first content paint. The URL
            // fragment is unavailable to PHP; this selects only a known panel.
            add_action('admin_head', static function (): void {
                echo '<script id="kodety-project-initial-area">(()=>{const a=location.hash.replace(/^#kodety-(?:area-)?/,""),v=a==="mcp"?"codex":a;document.documentElement.dataset.kodetyProjectArea=["project","extensions","interface","settings","optimizations","security","codex"].includes(v)?v:"project"})()</script>';
            }, 0);
            $toggle_style_file = KODETY_DIR . 'admin/interface-toggle.css';
            $toggle_script_file = KODETY_DIR . 'admin/interface-toggle.js';
            $page_style_file = KODETY_DIR . 'admin/kodety-page.css';
            $page_script_file = KODETY_DIR . 'admin/kodety-page.js';
            $page_icons_file = KODETY_DIR . 'admin/components/kodety-icons.bundle.js';
            wp_enqueue_style('kodety-interface-toggle', KODETY_URL . 'admin/interface-toggle.css', [], is_file($toggle_style_file) ? (string) filemtime($toggle_style_file) : KODETY_VERSION);
            wp_enqueue_script('kodety-interface-toggle', KODETY_URL . 'admin/interface-toggle.js', [], is_file($toggle_script_file) ? (string) filemtime($toggle_script_file) : KODETY_VERSION, ['in_footer' => false, 'strategy' => 'defer']);
            if (!$interface_enabled) {
                wp_enqueue_style('kodety-project-page', KODETY_URL . 'admin/kodety-page.css', ['kodety-interface-toggle'], is_file($page_style_file) ? (string) filemtime($page_style_file) : KODETY_VERSION);
                $this->add_admin_accent_style('kodety-project-page');
                wp_enqueue_script('kodety-admin-icons', KODETY_URL . 'admin/components/kodety-icons.bundle.js', [], is_file($page_icons_file) ? (string) filemtime($page_icons_file) : KODETY_VERSION, ['in_footer' => false, 'strategy' => 'defer']);
                wp_enqueue_script('kodety-project-page', KODETY_URL . 'admin/kodety-page.js', ['kodety-admin-icons'], is_file($page_script_file) ? (string) filemtime($page_script_file) : KODETY_VERSION, ['in_footer' => false, 'strategy' => 'defer']);
            }
        }

        // The importer and editor do not depend on the optional wp-admin skin.
        if (!$interface_enabled) return;

        // Editors receive a small CSS-only chrome. Their canvas and native
        // React state stay owned by WordPress; no sidebar adapters run here.
        if ($this->is_native_editor_screen($screen)) {
            $this->editor_chrome_assets();
            return;
        }

        $native_plugin_surface = $this->is_plugin_owned_admin_screen($screen);
        $admin_surface = $this->admin_surface_scope($screen);

        $component_dir = KODETY_DIR . 'admin/components/';
        $component_url = KODETY_URL . 'admin/components/';
        $shell_style_file = $component_dir . 'shell.bundle.css';
        $design_system_style_file = $component_dir . 'design-system.bundle.css';
        $audit_style_name = 'wp-admin-audit.standard.bundle.css';
        if ($admin_surface === 'owned') {
            $audit_style_name = 'wp-admin-audit.bundle.css';
        } elseif ($screen && $screen->base === 'dashboard') {
            $audit_style_name = 'wp-admin-audit.dashboard.bundle.css';
        } elseif ($screen && $screen->base === 'edit-comments') {
            $audit_style_name = 'wp-admin-audit.comments.bundle.css';
        } elseif ($screen && ($screen->base === 'plugins' || (is_network_admin() && in_array($screen->base, ['site-themes', 'themes'], true)))) {
            $audit_style_name = 'wp-admin-audit.plugins.bundle.css';
        } elseif ($screen && in_array($screen->base, ['options-connectors', 'font-library'], true)) {
            $audit_style_name = 'wp-admin-audit.apps.bundle.css';
        } elseif ($screen && (in_array($screen->base, ['edit', 'users', 'edit-tags', 'link-manager', 'export-personal-data', 'erase-personal-data', 'sites'], true) || (is_network_admin() && in_array($screen->base, ['site-users'], true)))) {
            $audit_style_name = in_array($screen->base, ['export-personal-data', 'erase-personal-data'], true) ? 'wp-admin-audit.tools.bundle.css' : 'wp-admin-audit.lists.bundle.css';
        } elseif ($screen && in_array($screen->base, ['upload', 'media'], true)) {
            $audit_style_name = 'wp-admin-audit.media.bundle.css';
        } elseif ($screen && in_array($screen->base, ['tools', 'import', 'export', 'site-health'], true)) {
            $audit_style_name = 'wp-admin-audit.tools.bundle.css';
        } elseif ($screen && in_array($screen->base, ['themes', 'theme-install', 'plugin-install'], true)) {
            $audit_style_name = 'wp-admin-audit.catalog.bundle.css';
        } elseif ($screen && in_array($screen->base, ['nav-menus', 'widgets'], true)) {
            $audit_style_name = 'wp-admin-audit.menus.bundle.css';
        } elseif ($screen && (str_starts_with($screen->base, 'options-') || in_array($screen->base, ['profile', 'user-edit', 'user-new', 'site-settings', 'site-info'], true))) {
            $audit_style_name = 'wp-admin-audit.settings.bundle.css';
        }
        $audit_style_file = $component_dir . $audit_style_name;
        $icons_script_file = $component_dir . 'kodety-icons.bundle.js';
        $shell_script_file = $component_dir . 'shell.bundle.js';

        $agency_mode = $this->workspace_mode() === 'agency';
        $admin_data = [
            'uiLocale' => class_exists('Kodety_Admin_I18n')
                ? Kodety_Admin_I18n::instance()->effective_locale()
                : str_replace('_', '-', determine_locale()),
            'adminUrl' => admin_url(),
            'homeUrl' => home_url('/'),
            'logoutUrl' => html_entity_decode(wp_logout_url(home_url('/')), ENT_QUOTES, 'UTF-8'),
            'editorUrl' => $agency_mode ? admin_url() : home_url('/kodety/editor/'),
            'cmsUrl' => home_url('/kodety/cms/'),
            'workspaceMode' => $agency_mode ? 'agency' : 'single',
            'kodetyLogoUrl' => KODETY_URL . 'admin/images/kodety-logo-full.svg',
            'projectAreas' => [
                'import' => current_user_can('kodety_import') && $this->can_publish(),
                'extensions' => current_user_can('manage_options'),
                'optimizations' => $this->can_publish(),
                'security' => current_user_can('manage_options'),
                'settings' => true,
            ],
            'brandLogoUrl' => $brand_logo_url,
            'editorCornerIcon' => $editor_corner_icon,
            'nativePluginSurface' => $native_plugin_surface,
            'adminSurface' => $admin_surface,
            'screen' => [
                'id' => $screen ? $screen->id : '',
                'base' => $screen ? $screen->base : '',
                'postType' => $screen ? (string) $screen->post_type : '',
                'taxonomy' => $screen ? (string) $screen->taxonomy : '',
                'profile' => $screen ? $this->admin_screen_profile($screen) : 'default',
            ],
        ];

        // One visual foundation and one small structural adapter. WordPress
        // retains its forms, state, media controllers and table interactions.
        wp_enqueue_style('kodety-ui-shell', $component_url . 'shell.bundle.css', [], (string) filemtime($shell_style_file));
        add_action('in_admin_header', static function () use ($admin_data): void {
            require KODETY_DIR . 'admin/components/shell-first-frame.php';
            if ($admin_data['adminSurface'] !== 'third-party') require KODETY_DIR . 'admin/components/navigation-loading.php';
        });
        if ($admin_surface !== 'third-party') {
            wp_enqueue_style('kodety-ui-design-system', $component_url . 'design-system.bundle.css', ['kodety-ui-shell'], (string) filemtime($design_system_style_file));
            wp_enqueue_style('kodety-wp-admin-audit', $component_url . $audit_style_name, ['kodety-ui-design-system'], (string) filemtime($audit_style_file));
        }
        if ($screen && $screen->base === 'plugin-install' && ($_GET['tab'] ?? '') === 'plugin-information') {
            $plugin_information_style = $component_dir . 'plugin-information.css';
            wp_enqueue_style('kodety-plugin-information', $component_url . 'plugin-information.css', ['kodety-wp-admin-audit'], is_file($plugin_information_style) ? (string) filemtime($plugin_information_style) : KODETY_VERSION);
        }
        wp_enqueue_script('kodety-admin-icons', $component_url . 'kodety-icons.bundle.js', [], (string) filemtime($icons_script_file), ['in_footer' => false, 'strategy' => 'defer']);
        wp_enqueue_script('kodety-ui-shell', $component_url . 'shell.bundle.js', ['kodety-admin-icons'], (string) filemtime($shell_script_file), ['in_footer' => false, 'strategy' => 'defer']);
        $workspace_script_file = $component_dir . 'native-workspace.bundle.js';
        if ($admin_surface === 'native') {
            $workspace_dependencies = ['kodety-ui-shell'];
            if ($audit_style_name === 'wp-admin-audit.tools.bundle.css') {
                wp_enqueue_script('kodety-native-tools', $component_url . 'native-tools.bundle.js', ['kodety-ui-shell'], (string) filemtime($component_dir . 'native-tools.bundle.js'), ['in_footer' => false, 'strategy' => 'defer']);
                $workspace_dependencies[] = 'kodety-native-tools';
            }
            wp_enqueue_script('kodety-native-workspace', $component_url . 'native-workspace.bundle.js', $workspace_dependencies, is_file($workspace_script_file) ? (string) filemtime($workspace_script_file) : KODETY_VERSION, ['in_footer' => false, 'strategy' => 'defer']);
        }
        if ($screen && $screen->base === 'dashboard' && !$is_agency_page) {
            $dashboard_style = $component_dir . 'dashboard.bundle.css';
            wp_enqueue_style('kodety-ui-dashboard', $component_url . 'dashboard.bundle.css', ['kodety-wp-admin-audit'], (string) filemtime($dashboard_style));
        }
        if ($is_kodety_page && !$is_agency_page) {
            wp_enqueue_style('kodety-project-page', KODETY_URL . 'admin/kodety-page.css', ['kodety-interface-toggle', 'kodety-wp-admin-audit'], (string) filemtime($page_style_file));
            wp_enqueue_script('kodety-project-page', KODETY_URL . 'admin/kodety-page.js', ['kodety-admin-icons'], (string) filemtime($page_script_file), ['in_footer' => false, 'strategy' => 'defer']);
        }
        if ($admin_surface === 'third-party') {
            wp_add_inline_style('kodety-ui-shell', $this->admin_accent_css(false));
        } else {
            $this->add_admin_accent_style('kodety-wp-admin-audit');
        }
        wp_add_inline_script('kodety-admin-icons', 'window.kodetyAdmin=' . wp_json_encode($admin_data) . ';', 'before');
        // Every surface needs a navigation fallback if the shell fails. Only
        // native content waits for its structural adapter to finish.
        wp_add_inline_script('kodety-admin-icons', <<<'JS'
(() => {
    const root = document.documentElement;
    const native = window.kodetyAdmin.adminSurface === 'native';
    const ownSurface = window.kodetyAdmin.adminSurface !== 'third-party';
    if (ownSurface) root.classList.add('kodety-admin-pending');
    if (native) root.classList.add('kodety-native-pending');
    let watchdog;
    let coreReady = false;
    let navigationBridge = false;
    const bridgeNavigation = event => {
        if (!document.body?.classList.contains('kodety-shell-failed')) return;
        const toggle = document.querySelector('#wp-admin-bar-menu-toggle a');
        const wrap = document.querySelector('#wpwrap');
        if (!toggle || !wrap) return;
        const clicked = event.type === 'click' && event.target.closest?.('#wp-admin-bar-menu-toggle');
        const escaped = event.key === 'Escape' && wrap.classList.contains('wp-responsive-open');
        if (!clicked && !escaped) return;
        event.preventDefault();
        const open = clicked && !wrap.classList.contains('wp-responsive-open');
        wrap.classList.toggle('wp-responsive-open', open);
        toggle.setAttribute('aria-expanded', String(open));
        (open ? document.querySelector('#adminmenu a') : toggle)?.focus();
    };
    document.addEventListener('DOMContentLoaded', () => {
        coreReady = true;
        if (!navigationBridge) return;
        document.removeEventListener('click', bridgeNavigation);
        document.removeEventListener('keydown', bridgeNavigation);
        document.querySelector('#wpwrap')?.classList.remove('wp-responsive-open');
        document.querySelector('#wp-admin-bar-menu-toggle a')?.setAttribute('aria-expanded', 'false');
    }, { once: true });
    const restoreNavigation = () => {
        const body = document.body;
        if (!body) {
            document.addEventListener('DOMContentLoaded', restoreNavigation, { once: true });
            return;
        }
        if (!body.classList.contains('kodety-ui-shell-ready')) {
            window.kodetyComponentShell?.destroy?.();
            body.classList.add('kodety-shell-failed');
            if (!coreReady && !navigationBridge) {
                document.addEventListener('click', bridgeNavigation);
                document.addEventListener('keydown', bridgeNavigation);
                navigationBridge = true;
            }
        }
    };
    const failed = event => {
        const source = event.target?.src || event.filename || '';
        if (!/(?:kodety-icons|shell|native-workspace)\.bundle\.js/.test(source)) return;
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', reveal, { once: true });
        } else reveal();
    };
    const reveal = () => {
        root.classList.remove('kodety-native-pending');
        if (root.classList.contains('kodety-admin-pending')) {
            root.classList.remove('kodety-admin-pending');
            root.classList.add('kodety-admin-entering');
        }
        window.clearTimeout(watchdog);
        window.removeEventListener('error', failed, true);
        restoreNavigation();
    };
    window.kodetyNativeReveal = reveal;
    window.addEventListener('error', failed, true);
    if (!native) document.addEventListener('DOMContentLoaded', reveal, { once: true });
    watchdog = window.setTimeout(reveal, 4000);
})();
JS
        , 'before');
    }

    public function admin_body_classes(string $classes): string {
        $screen = get_current_screen();
        if ($screen && $screen->id === 'admin_page_kodety-onboarding') {
            return trim($classes . ' kodety-onboarding-page');
        }
        if (
            $screen
            && $screen->id === 'dashboard'
            && $this->workspace_mode() === 'agency'
        ) {
            $classes = trim($classes . ' kodety-agency-page');
        }
        if (!$this->is_interface_enabled()) return $classes;
        if ($this->is_native_editor_screen($screen)) return trim($classes . ' kodety-editor-chrome');
        $native_plugin_surface = $this->is_plugin_owned_admin_screen($screen);
        $admin_surface = $this->admin_surface_scope($screen);
        $extra = $native_plugin_surface
            ? ['kodety-os', 'kodety-native-plugin-surface']
            : ['kodety-admin-skin', 'kodety-os'];
        $extra[] = 'kodety-admin-' . $admin_surface;
        if ($screen) {
            $extra[] = 'kodety-profile-' . sanitize_html_class($this->admin_screen_profile($screen));
            $extra[] = 'kodety-screen-' . sanitize_html_class(str_replace(['_', '.'], '-', $screen->id));
            if ($screen->post_type) $extra[] = 'kodety-post-type-' . sanitize_html_class($screen->post_type);
            if ($screen->taxonomy) $extra[] = 'kodety-taxonomy-' . sanitize_html_class($screen->taxonomy);
        }
        if (is_network_admin()) $extra[] = 'kodety-network-admin';
        if (is_user_admin()) $extra[] = 'kodety-user-admin';
        return trim($classes . ' ' . implode(' ', $extra));
    }

    private function admin_screen_profile(WP_Screen $screen): string {
        if (method_exists($screen, 'is_block_editor') && $screen->is_block_editor()) return 'block-editor';
        if ($screen->base === 'dashboard') return 'dashboard';
        if (in_array($screen->base, ['edit', 'edit-comments', 'users', 'plugins', 'sites', 'site-users', 'site-themes', 'link-manager', 'export-personal-data', 'erase-personal-data'], true)) return 'list';
        if ($screen->base === 'themes' && is_network_admin()) return 'list';
        if (in_array($screen->base, ['upload', 'media'], true)) return 'library';
        if (in_array($screen->base, ['themes', 'theme-install', 'plugin-install'], true)) return 'gallery';
        if (in_array($screen->base, ['post', 'term', 'user-edit', 'profile'], true)) return 'form';
        if (preg_match('/^(options-|settings_page_|site-health|privacy|permalink)/', $screen->id)) return 'settings';
        if (in_array($screen->base, ['customize', 'site-editor', 'widgets', 'theme-editor', 'plugin-editor'], true)) return 'fullscreen';
        return 'default';
    }

    public function dashboard_setup(): void {
        $is_agency_dashboard = $this->workspace_mode() === 'agency'
            && current_user_can(self::CAP_EDIT_WORKSPACE);
        if (!$this->is_interface_enabled() && !$is_agency_dashboard) return;
        if (!current_user_can('read')) return;
        if (
            !current_user_can(self::CAP_EDIT_WORKSPACE)
            && !current_user_can(self::CAP_ACCESS_CMS)
            && !current_user_can(self::CAP_VIEW_ANALYTICS)
        ) return;
        global $wp_meta_boxes;
        foreach (['normal', 'side', 'column3', 'column4'] as $context) {
            $wp_meta_boxes['dashboard'][$context]['core'] = [];
            $wp_meta_boxes['dashboard'][$context]['high'] = [];
            $wp_meta_boxes['dashboard'][$context]['default'] = [];
            $wp_meta_boxes['dashboard'][$context]['low'] = [];
        }
        $callback = $is_agency_dashboard
            ? [$this, 'agency_page']
            : [$this, 'render_dashboard'];
        wp_add_dashboard_widget('kodety_dashboard', 'Onun Kodety', $callback);
    }

    public function render_dashboard(): void {
        $can_edit_workspace = current_user_can(self::CAP_EDIT_WORKSPACE);
        $can_manage_site = current_user_can('manage_options');
        $can_update_core = current_user_can('update_core');
        $can_upload_files = current_user_can('upload_files');
        $can_moderate_comments = current_user_can('moderate_comments');
        $can_edit_theme = current_user_can('edit_theme_options');
        $can_edit_others = current_user_can('edit_others_posts');
        $content_post_types = [];
        if (current_user_can('edit_posts')) $content_post_types[] = 'post';
        if (current_user_can('edit_pages')) $content_post_types[] = 'page';
        if ($content_post_types === []) $content_post_types[] = 'post';

        $visible_statuses = ['draft', 'pending'];
        if (current_user_can('edit_published_posts')) {
            $visible_statuses[] = 'publish';
            $visible_statuses[] = 'future';
        }
        if (current_user_can('read_private_posts')) $visible_statuses[] = 'private';

        $content_counts = array_fill_keys(['publish', 'draft', 'pending', 'future', 'private'], 0);
        if ($can_edit_others) {
            foreach ($content_post_types as $post_type) {
                $counts = wp_count_posts($post_type);
                foreach ($content_counts as $status => $count) {
                    if (in_array($status, $visible_statuses, true)) {
                        $content_counts[$status] += (int) ($counts->{$status} ?? 0);
                    }
                }
            }
