    /** @param list<string> $post_types */
    private function dashboard_content_count(array $post_types, string $status, int $author_id): int {
        $query = new WP_Query([
            'post_type' => $post_types,
            'post_status' => $status,
            'author' => $author_id,
            'fields' => 'ids',
            'posts_per_page' => 1,
            'no_found_rows' => false,
            'cache_results' => false,
            'update_post_meta_cache' => false,
            'update_post_term_cache' => false,
        ]);
        return (int) $query->found_posts;
    }

    private function directory_size(string $directory): int {
        if ($directory === '' || !is_dir($directory)) return 0;
        $size = 0;
        try {
            $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($directory, FilesystemIterator::SKIP_DOTS));
            foreach ($iterator as $file) if ($file->isFile() && !$file->isLink()) $size += $file->getSize();
        } catch (Throwable) {
            return $size;
        }
        return $size;
    }

    /**
     * Front-end editing launcher.
     *
     * Renders a fixed pencil button on the live site — vertically centered on the
     * right edge — but only for signed-in users who belong to this project (the
     * `kodety_edit` capability). Everyone else, including logged-out visitors, sees
     * nothing. Clicking the button opens a small overlay to jump into the CMS,
     * Settings, Translations or Analytics workspaces instead of going straight to
     * the editor.
