    /**
     * Local fallbacks keep the importer readable before the Solar registry
     * hydrates its icons, and when the optional admin skin is disabled.
     * Product brand marks remain embedded independently of that registry.
     */
    private function url_import_icon(string $name): string {
        $icons = [
            'website' => '<circle cx="12" cy="12" r="8.5"/><path d="M3.8 12h16.4M12 3.5c2.2 2.3 3.3 5.1 3.3 8.5S14.2 18.2 12 20.5C9.8 18.2 8.7 15.4 8.7 12S9.8 5.8 12 3.5Z"/>',
            'chevron-down' => '<path d="m7 9.5 5 5 5-5"/>',
            'search' => '<circle cx="10.5" cy="10.5" r="5.5"/><path d="m15 15 4 4"/>',
            // Official white brand marks, embedded so wp-admin never depends
            // on a third-party request at render time. Sources:
            // https://www.framer.com/brand/
            // https://brand.webflow.com/brand-assets
            'framer' => '<path fill="#FFF" stroke="none" d="M44.65 33.992h50.7v25.349H70zm0 25.349H70l25.35 25.35h-50.7zm0 25.35H70v25.35z"/>',
            'webflow' => '<path fill="#FFF" stroke="none" fill-rule="evenodd" clip-rule="evenodd" d="M1080 0L735.385 673.684H411.695L555.915 394.481H549.444C430.463 548.934 252.941 650.61 -0.000976562 673.684V398.344C-0.000976562 398.344 161.812 388.787 256.938 288.776H-0.000976562V0.0053214H288.77V237.515L295.252 237.489L413.254 0.0053214H631.644V236.009L638.125 235.999L760.555 0H1080Z"/>',
            'code' => '<path d="m8.5 7-5 5 5 5M15.5 7l5 5-5 5M14 4.5l-4 15"/>',
            'monitor' => '<rect x="3" y="4.5" width="18" height="12" rx="2"/><path d="M9 20h6M12 16.5V20"/>',
            'tablet' => '<rect x="5.5" y="2.5" width="13" height="19" rx="2"/><path d="M10 18.5h4"/>',
            'mobile' => '<rect x="7" y="2.5" width="10" height="19" rx="2"/><path d="M10.5 18.5h3"/>',
            'shield' => '<path d="M12 3 20 6v5.5c0 4.6-3.1 7.8-8 9.5-4.9-1.7-8-4.9-8-9.5V6l8-3Z"/><path d="m8.5 12 2.2 2.2 4.8-5"/>',
            'warning' => '<circle cx="12" cy="12" r="9"/><path d="M12 7v6M12 17h.01"/>',
            'archive' => '<rect x="3" y="5.5" width="18" height="4" rx="1"/><path d="M5 9.5V20h14V9.5M9.5 14h5"/>',
            'info' => '<circle cx="12" cy="12" r="9"/><path d="M12 10.5V17M12 7h.01"/>',
            'lock' => '<rect x="4.5" y="10" width="15" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
            'download' => '<path d="M12 3v11M7.5 10.5 12 15l4.5-4.5M4 20h16"/>',
        ];
        $icon = $icons[$name] ?? $icons['info'];
        $brand_icon = in_array($name, ['framer', 'webflow'], true);
        $solar_icon = $name === 'mobile' ? 'smartphone' : (isset($icons[$name]) ? $name : 'info');
        $view_box = match ($name) {
            'framer' => '44.65 33.992 50.7 76.049',
            'webflow' => '0 0 1080 674',
            default => '0 0 24 24',
        };
        return '<span class="kodety-import-url__icon kodety-import-url__icon--' . esc_attr($name)
            . ($brand_icon ? ' kodety-import-url__icon--brand' : '') . '" aria-hidden="true"'
            . ($brand_icon ? '' : ' data-kodety-icon="' . esc_attr($solar_icon) . '" data-kodety-icon-size="18"') . '>'
            . '<svg viewBox="' . esc_attr($view_box) . '" width="18" height="18" fill="none"'
            . ($brand_icon ? '' : ' stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"')
            . ' xmlns="http://www.w3.org/2000/svg" focusable="false">'
            . $icon
            . '</svg></span>';
    }

