    /**
     * Normalize the extension manager inventory for the project hub.
     *
     * Keeping the adapter here means the markup only depends on a stable view
     * model while the installer remains owned by Kodety_Extensions.
     *
     * @return array<int, array{
     *   slug: string,
     *   name: string,
     *   description: string,
     *   version: string,
     *   icon: string,
     *   installed: bool,
     *   active: bool,
     *   bundled: bool,
     *   required: bool
     * }>
     */
    private function dashboard_extensions(): array {
        $bundled_fallback = [
            ['slug' => 'kodety-cms', 'name' => 'Onun Kodety CMS', 'description' => 'Conteúdo, páginas dinâmicas e coleções conectadas ao Builder.', 'version' => KODETY_VERSION, 'icon' => 'pages', 'installed' => true, 'active' => true, 'bundled' => true, 'required' => true],
            ['slug' => 'kodety-analytics', 'name' => 'Onun Kodety Analytics', 'description' => 'Métricas do site e visão de desempenho sem sair do Onun Kodety.', 'version' => KODETY_VERSION, 'icon' => 'analytics', 'installed' => true, 'active' => true, 'bundled' => true, 'required' => true],
            ['slug' => 'kodety-settings', 'name' => 'Onun Kodety Settings', 'description' => 'Preferências compartilhadas e configurações operacionais do site.', 'version' => KODETY_VERSION, 'icon' => 'settings', 'installed' => true, 'active' => true, 'bundled' => true, 'required' => true],
            ['slug' => 'kodety-emails', 'name' => 'Onun Kodety Emails', 'description' => 'Caixas, remetentes e histórico de mensagens transacionais.', 'version' => KODETY_VERSION, 'icon' => 'mail', 'installed' => true, 'active' => true, 'bundled' => true, 'required' => false],
            ['slug' => 'kodety-marketing', 'name' => 'Onun Kodety Marketing', 'description' => 'Campanhas, listas, automações e resultados de email marketing.', 'version' => KODETY_VERSION, 'icon' => 'marketing', 'installed' => true, 'active' => true, 'bundled' => true, 'required' => false],
            ['slug' => 'kodety-membership', 'name' => 'Onun Kodety Membership', 'description' => 'Membros, planos, acessos e conteúdo protegido.', 'version' => KODETY_VERSION, 'icon' => 'users', 'installed' => true, 'active' => false, 'bundled' => true, 'required' => false],
        ];

        if (!class_exists('Kodety_Extensions')) return $bundled_fallback;

        try {
            $manager = Kodety_Extensions::instance();
            $catalog = $manager->catalog();
            $installed = $manager->installed();
        } catch (Throwable $error) {
            return $bundled_fallback;
        }

        if (!is_array($catalog)) $catalog = [];
        if (!is_array($installed)) $installed = [];

        $normalize = static function (array $source): array {
            $result = [];
            foreach ($source as $key => $item) {
                if (!is_array($item)) continue;
                $manifest = isset($item['manifest']) && is_array($item['manifest']) ? $item['manifest'] : [];
                $record = array_merge($manifest, $item);
                $slug = sanitize_key((string) ($record['slug'] ?? (is_string($key) ? $key : '')));
                if ($slug === '') continue;
                $record['slug'] = $slug;
                $result[$slug] = $record;
            }
            return $result;
        };

        $catalog_by_slug = $normalize($catalog);
        $installed_by_slug = $normalize($installed);
        $extensions = [];

        foreach (array_unique(array_merge(array_keys($catalog_by_slug), array_keys($installed_by_slug))) as $slug) {
            $record = array_merge($catalog_by_slug[$slug] ?? [], $installed_by_slug[$slug] ?? []);
            $is_installed = isset($installed_by_slug[$slug])
                || !empty($record['installed'])
                || in_array((string) ($record['status'] ?? ''), ['active', 'inactive', 'installed'], true);
            $is_active = !empty($record['active']) || (string) ($record['status'] ?? '') === 'active';
            if ($is_installed && method_exists($manager, 'is_active')) {
                try {
                    $is_active = (bool) $manager->is_active($slug);
                } catch (Throwable $error) {
                    // Preserve the manifest state when an extension is partially installed.
                }
            }

            $icon = sanitize_key((string) ($record['icon'] ?? 'plugins'));
            if ($icon === '' || $icon === 'plugins') {
                if (str_contains($slug, 'analytic')) $icon = 'analytics';
                elseif (str_contains($slug, 'market')) $icon = 'marketing';
                elseif (str_contains($slug, 'email') || str_contains($slug, 'mail')) $icon = 'mail';
                elseif (str_contains($slug, 'member')) $icon = 'users';
                elseif (str_contains($slug, 'setting')) $icon = 'settings';
                elseif (str_contains($slug, 'cms')) $icon = 'pages';
                else $icon = 'plugins';
            }

            $extensions[] = [
                'slug' => $slug,
                'name' => sanitize_text_field((string) ($record['name'] ?? ucwords(str_replace('-', ' ', $slug)))),
                'description' => sanitize_text_field((string) ($record['description'] ?? 'Extensão integrada ao ecossistema Onun Kodety.')),
                'version' => sanitize_text_field((string) ($record['version'] ?? '')),
                'icon' => $icon,
                'installed' => $is_installed,
                'active' => $is_installed && $is_active,
                'bundled' => !empty($record['bundled']) || !empty($record['core']) || !empty($record['built_in']),
                'required' => !empty($record['required']),
            ];
        }

        return $extensions;
    }

    public function login_assets(): void {
        if (!$this->is_interface_enabled()) return;
        $style_file = KODETY_DIR . 'admin/login.css';
        $script_file = KODETY_DIR . 'admin/login.js';
        $showcase_file = KODETY_DIR . 'admin/images/login-showcase.webp';
        $logo_file = KODETY_DIR . 'admin/images/kodety-logo-full.svg';
        $versioned_asset_url = static function (string $relative_path, string $file): string {
            $version = is_file($file) ? (string) filemtime($file) : KODETY_VERSION;
            return add_query_arg('ver', $version, KODETY_URL . ltrim($relative_path, '/'));
        };

        $fallback_showcase_url = $versioned_asset_url('admin/images/login-showcase.webp', $showcase_file);
        $showcase_url = $fallback_showcase_url;
        $login_image_id = absint(get_option('kodety_login_image_id', 0));
        if ($login_image_id > 0 && wp_attachment_is_image($login_image_id)) {
            $attachment_mime = (string) get_post_mime_type($login_image_id);
            $attachment_metadata = wp_get_attachment_metadata($login_image_id);
            $validated_attachment_size = absint(get_post_meta($login_image_id, '_kodety_login_image_bytes', true));
            $attachment_size = $validated_attachment_size > 0
                ? $validated_attachment_size
                : (is_array($attachment_metadata) ? absint($attachment_metadata['filesize'] ?? 0) : 0);
            $attachment_url = wp_get_attachment_image_url($login_image_id, 'full');
            if (
                in_array($attachment_mime, ['image/png', 'image/jpeg', 'image/webp'], true)
                && ($attachment_size === 0 || $attachment_size <= self::LOGIN_IMAGE_MAX_BYTES)
                && is_string($attachment_url)
                && $attachment_url !== ''
            ) {
                $showcase_url = $attachment_url;
            }
        }

        wp_enqueue_style('kodety-login', KODETY_URL . 'admin/login.css', [], is_file($style_file) ? (string) filemtime($style_file) : KODETY_VERSION);
        wp_enqueue_script('kodety-login', KODETY_URL . 'admin/login.js', [], is_file($script_file) ? (string) filemtime($script_file) : KODETY_VERSION, true);
        wp_add_inline_script('kodety-login', 'window.kodetyLoginConfig = ' . wp_json_encode([
            'showcaseUrl' => $showcase_url,
            'fallbackShowcaseUrl' => $fallback_showcase_url,
            'fullLogoUrl' => $versioned_asset_url('admin/images/kodety-logo-full.svg', $logo_file),
        ], JSON_UNESCAPED_SLASHES | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) . ';', 'before');
    }

    /**
     * URLs for the Onun Kodety mark used as the favicon of every Onun Kodety surface.
     *
     * The SVG covers current browsers; the PNG is the fallback for Safari
     * below 16.4 and for iOS home-screen shortcuts, which ignore SVG icons.
     *
     * @return array{svg: string, png: string}
     */
    public static function favicon_urls(): array {
        $build = static function (string $file): string {
            $path = KODETY_DIR . 'assets/' . $file;
            $version = is_file($path) ? (string) filemtime($path) : KODETY_VERSION;
            return add_query_arg('ver', $version, KODETY_URL . 'assets/' . $file);
        };
        return [
            'svg' => $build('kodety-favicon.svg'),
            'png' => $build('kodety-favicon-180.png'),
        ];
    }

    /**
     * Brand wp-admin and the login screen with the Onun Kodety mark.
     *
     * WordPress prints the public site icon on both screens. Those screens are
     * Onun Kodety's own surface rather than the published site, so its mark replaces
     * the site icon there while the front-end keeps whatever the project set.
     */
    public function render_kodety_favicon(): void {
        if (!$this->is_interface_enabled()) return;
        remove_action('admin_head', 'wp_site_icon');
        remove_action('login_head', 'wp_site_icon');
        $icons = self::favicon_urls();
        printf(
            '<link rel="icon" href="%s" type="image/svg+xml" sizes="any">' . "\n"
                . '<link rel="icon" href="%s" type="image/png" sizes="180x180">' . "\n"
                . '<link rel="apple-touch-icon" href="%s">' . "\n",
            esc_url($icons['svg']),
            esc_url($icons['png']),
            esc_url($icons['png'])
        );
    }

    public function login_header_url(string $url): string {
        return $this->is_interface_enabled() ? home_url('/') : $url;
    }

    public function login_header_text(string $text): string {
        return $this->is_interface_enabled() ? 'Onun Kodety' : $text;
    }

    public function login_document_title(string $login_title, string $title): string {
        if (!$this->is_interface_enabled()) return $login_title;
        $action_title = trim(wp_strip_all_tags($title));
        $branded_title = $action_title !== '' ? $action_title . ' &lsaquo; Onun Kodety' : 'Onun Kodety';
        if (function_exists('wp_is_recovery_mode') && wp_is_recovery_mode()) {
            return sprintf(__('Recovery Mode &#8212; %s'), $branded_title);
        }
        return $branded_title;
    }

    public function login_body_classes(array $classes): array {
        return $this->is_interface_enabled() ? array_merge($classes, ['kodety-login']) : $classes;
    }

    public function login_redirect(string $redirect_to, string $requested, $user): string {
        return $user instanceof WP_User && user_can($user, 'kodety_edit') ? admin_url() : $redirect_to;
    }

    /** @return array<string,array<string,mixed>> */
    private function agency_projects(): array {
        $stored = get_option('kodety_agency_projects', []);
        if (!is_array($stored)) return [];
        $projects = [];
        foreach ($stored as $id => $project) {
            $id = sanitize_key((string) $id);
            if ($id === '' || !is_array($project)) continue;
            $projects[$id] = [
                'id' => $id,
                'name' => substr(sanitize_text_field((string) ($project['name'] ?? 'Projeto sem nome')), 0, 120),
                'folderId' => sanitize_key((string) ($project['folderId'] ?? '')),
                'originalName' => sanitize_file_name((string) ($project['originalName'] ?? 'projeto.zip')),
                'createdAt' => sanitize_text_field((string) ($project['createdAt'] ?? current_time('c'))),
                'updatedAt' => sanitize_text_field((string) ($project['updatedAt'] ?? current_time('c'))),
                'size' => max(0, (int) ($project['size'] ?? 0)),
                'coverVersion' => max(0, (int) ($project['coverVersion'] ?? 0)),
                'slug' => sanitize_title((string) ($project['slug'] ?? $project['name'] ?? $id)),
                'isRoot' => !empty($project['isRoot']),
                'release' => sanitize_key((string) ($project['release'] ?? '')),
                'publishedAt' => sanitize_text_field((string) ($project['publishedAt'] ?? '')),
            ];
            if ($projects[$id]['slug'] === '') $projects[$id]['slug'] = sanitize_title($id);
        }
        return $projects;
    }

    private function agency_unique_slug(string $seed, string $exclude_id = ''): string {
        $base = sanitize_title($seed);
        if ($base === '' || in_array($base, ['kodety', 'wp-admin', 'wp-json', 'wp-login', 'wp-content'], true)) {
            $base = 'site';
        }
        $base = substr($base, 0, 80);
        $used = [];
        foreach ($this->agency_projects() as $project) {
            if ($project['id'] === $exclude_id) continue;
            $used[(string) $project['slug']] = true;
        }
        $slug = $base;
        $suffix = 2;
        while (isset($used[$slug])) {
            $slug = substr($base, 0, 74) . '-' . $suffix;
            $suffix += 1;
        }
        return $slug;
    }

    /** @return array<string,mixed>|null */
    private function agency_project_by_slug(string $slug): ?array {
        $slug = sanitize_title($slug);
        if ($slug === '') return null;
        foreach ($this->agency_projects() as $project) {
            if ($project['slug'] === $slug && $project['release'] !== '') return $project;
        }
        return null;
    }

    /** @return array<string,mixed>|null */
    private function agency_root_project(): ?array {
        foreach ($this->agency_projects() as $project) {
            if ($project['isRoot'] && $project['release'] !== '') return $project;
        }
        return null;
    }

    private function agency_request_is_reserved(string $request_path): bool {
        $first = strtolower((string) strtok($request_path, '/'));
        return in_array($first, [
            'kodety',
            'kodety-site-assets',
            'wp-admin',
            'wp-json',
            'wp-login.php',
            'wp-cron.php',
            'wp-content',
            'wp-includes',
            'xmlrpc.php',
            'robots.txt',
            'favicon.ico',
            'wp-sitemap.xml',
            'feed',
        ], true);
    }

    /** @param mixed $context
     *  @return array<string,string>
     */
    public function agency_runtime_context(mixed $context): array {
        $project_id = sanitize_key((string) get_query_var('kodety_agency_site'));
        $route = trim(str_replace('\\', '/', (string) get_query_var('kodety_agency_route')), '/');
        $projects = $this->agency_projects();
        if (
            $this->workspace_mode() !== 'agency'
            || $project_id === ''
            || !isset($projects[$project_id])
            || $projects[$project_id]['release'] === ''
        ) {
            return is_array($context) ? $context : [];
        }
        $directory = $this->agency_project_dir($project_id) . '/published';
        if (!is_dir($directory . '/site') || !is_file($directory . '/manifest.json')) {
            return is_array($context) ? $context : [];
        }
        $slug = (string) $projects[$project_id]['slug'];
        $base_url = !empty($projects[$project_id]['isRoot'])
            ? home_url('/')
            : home_url('/' . $slug . '/');
        return [
            'projectId' => $project_id,
            'slug' => $slug,
            'route' => $route,
            'directory' => $directory,
            'directoryUri' => home_url('/kodety-site-assets/' . rawurlencode($slug)),
            'baseUrl' => trailingslashit($base_url),
            'release' => (string) $projects[$project_id]['release'],
        ];
    }

    public function disable_agency_canonical_redirect(mixed $redirect, string $requested = ''): mixed {
        return sanitize_key((string) get_query_var('kodety_agency_site')) !== '' ? false : $redirect;
    }

    /**
     * Managed Media Library URLs are intentionally project-specific in agency
     * mode. Publishing another project may replace those shared attachments, so
     * every retained site must resolve them from its own immutable snapshot.
     *
     * @param mixed $html
     * @param mixed $context
     */
    public function agency_runtime_html(mixed $html, mixed $context = []): string {
        if (!is_string($html) || !is_array($context)) return is_string($html) ? $html : '';
        $directory = (string) ($context['directory'] ?? '');
        $directory_uri = (string) ($context['directoryUri'] ?? '');
        if (
            $this->workspace_mode() !== 'agency'
            || (string) ($context['projectId'] ?? '') === ''
            || $directory === ''
            || $directory_uri === ''
        ) return $html;
        return $this->agency_rewrite_managed_asset_urls($html, $directory, $directory_uri);
    }

    private function agency_rewrite_managed_asset_urls(
        string $content,
        string $runtime_directory,
        string $runtime_directory_uri
    ): string {
        $site_root = realpath(rtrim($runtime_directory, '/\\') . '/site');
        if (!$site_root || $content === '' || $runtime_directory_uri === '') return $content;
        $site_prefix = trailingslashit($site_root);
        $public_prefix = trailingslashit(rtrim($runtime_directory_uri, '/\\') . '/site');

        return (string) preg_replace_callback(
            '~(?P<url>(?:(?:https?:)?//[^\s"\'`()<>\\\\,]+)?/[^\s"\'`()<>\\\\,]*?/kodety/assets/(?P<asset>[^\s"\'`()<>\\\\,]+))~i',
            static function (array $match) use ($site_root, $site_prefix, $public_prefix): string {
                $raw_asset = (string) ($match['asset'] ?? '');
                if ($raw_asset === '') return (string) $match[0];
                $suffix_offset = strcspn($raw_asset, '?#');
                $raw_path = substr($raw_asset, 0, $suffix_offset);
                $suffix = substr($raw_asset, $suffix_offset);
                $decoded = rawurldecode(html_entity_decode($raw_path, ENT_QUOTES | ENT_HTML5, 'UTF-8'));
                $segments = [];
                foreach (explode('/', str_replace('\\', '/', $decoded)) as $segment) {
                    if ($segment === '' || $segment === '.') continue;
                    if ($segment === '..' || str_contains($segment, "\0")) return (string) $match[0];
                    $segments[] = $segment;
                }
                if (!$segments) return (string) $match[0];

                $relative = implode('/', $segments);
                $candidates = [$relative];
                $filename = array_pop($segments);
                $localized_filename = preg_replace(
                    '/-[a-f0-9]{12}(\.[a-z0-9]+)$/i',
                    '$1',
                    (string) $filename
                );
                if (is_string($localized_filename) && $localized_filename !== $filename) {
                    $candidates[] = implode('/', array_merge($segments, [$localized_filename]));
                }

                foreach (array_values(array_unique($candidates)) as $candidate) {
                    $file = realpath($site_root . '/' . $candidate);
                    if (!$file || !is_file($file) || !str_starts_with($file, $site_prefix)) continue;
                    $encoded = implode('/', array_map('rawurlencode', explode('/', $candidate)));
                    return $public_prefix . $encoded . $suffix;
                }
                return (string) $match[0];
            },
            $content
        );
    }

    public function serve_agency_asset(): void {
        $project_id = sanitize_key((string) get_query_var('kodety_agency_site'));
        $asset = rawurldecode((string) get_query_var('kodety_agency_asset'));
        if ($project_id === '' || $asset === '') return;
        $asset = ltrim(str_replace('\\', '/', $asset), '/');
        if (str_contains($asset, '../') || str_contains($asset, "\0")) {
            status_header(400);
            exit;
        }
        $root = realpath($this->agency_project_dir($project_id) . '/published');
        $file = realpath($this->agency_project_dir($project_id) . '/published/' . $asset);
        $extension = strtolower(pathinfo($asset, PATHINFO_EXTENSION));
        if (
            !$root
            || !$file
            || !str_starts_with($file, trailingslashit($root))
            || !is_file($file)
            || in_array($extension, ['php', 'phtml', 'html', 'htm', 'json'], true)
        ) {
            status_header(404);
            exit;
        }
        $mime = wp_check_filetype($file)['type'] ?: $this->asset_mime_type($file);
        if (in_array($extension, ['js', 'mjs', 'cjs'], true)) $mime = 'application/javascript';
        $text_asset = in_array($extension, ['css', 'js', 'mjs', 'cjs', 'map'], true);
        $contents = $text_asset ? file_get_contents($file) : false;
        if (is_string($contents)) {
            $projects = $this->agency_projects();
            $slug = (string) ($projects[$project_id]['slug'] ?? '');
            if ($slug !== '') {
                $contents = $this->agency_rewrite_managed_asset_urls(
                    $contents,
                    $root,
                    home_url('/kodety-site-assets/' . rawurlencode($slug))
                );
            }
        }
        header('Content-Type: ' . $mime);
        header('Content-Length: ' . (is_string($contents) ? strlen($contents) : (int) filesize($file)));
        header('Cache-Control: public, max-age=31536000, immutable');
        header('X-Content-Type-Options: nosniff');
        if (is_string($contents)) echo $contents; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- retained project asset.
        else readfile($file);
        exit;
    }

    /** @return array<string,array{id:string,name:string,createdAt:string}> */
    private function agency_folders(): array {
        $stored = get_option('kodety_agency_folders', []);
        if (!is_array($stored)) return [];
        $folders = [];
        foreach ($stored as $id => $folder) {
            $id = sanitize_key((string) $id);
            if ($id === '' || !is_array($folder)) continue;
            $name = substr(sanitize_text_field((string) ($folder['name'] ?? 'Pasta')), 0, 80);
            $folders[$id] = [
                'id' => $id,
                'name' => $name !== '' ? $name : 'Pasta',
                'createdAt' => sanitize_text_field((string) ($folder['createdAt'] ?? current_time('c'))),
            ];
        }
        return $folders;
    }

    private function agency_root_dir(): string {
        return $this->private_storage_dir() . '/agency';
    }

    private function agency_project_dir(string $project_id): string {
        return $this->agency_root_dir() . '/' . sanitize_key($project_id);
    }

    private function agency_unique_id(string $seed = 'project'): string {
        $base = sanitize_title($seed);
        if ($base === '') $base = 'project';
        $base = substr($base, 0, 52);
        $projects = $this->agency_projects();
        do {
            $suffix = strtolower(wp_generate_password(6, false, false));
            $id = sanitize_key($base . '-' . $suffix);
        } while (isset($projects[$id]) || is_dir($this->agency_project_dir($id)));
        return $id;
    }

    private function agency_active_project_id(): string {
        return sanitize_key((string) get_option('kodety_agency_active_project', ''));
    }

    /**
     * A share URL is permanently scoped to its project. The owner may open a
     * different agency project while guests are viewing this one, so shared
     * requests read/write that project's snapshot instead of the global
     * workspace currently mounted in the owner's Builder.
     */
    private function shared_project_id(): string {
        if ($this->workspace_mode() !== 'agency' || !class_exists('Kodety_Sharing')) return '';
        $project_id = Kodety_Sharing::instance()->project_id();
        return $project_id !== 'single' ? sanitize_key($project_id) : '';
    }

    public function active_project_site_url(): string {
        if ($this->workspace_mode() !== 'agency') return home_url('/');
        $active_id = $this->shared_project_id() ?: $this->agency_active_project_id();
        $projects = $this->agency_projects();
        if ($active_id === '' || !isset($projects[$active_id])) return home_url('/');
        return !empty($projects[$active_id]['isRoot'])
            ? home_url('/')
            : home_url('/' . $projects[$active_id]['slug'] . '/');
    }

    /**
     * Metadata for the project mounted in this request. Shared agency requests
     * may point at a project other than the one open in the owner's Builder.
     *
     * @return array{name:string,originalName:string,workspaceProjectId:string}
     */
    public function request_project_metadata(): array {
        $name = (string) get_option('kodety_project_name', '');
        $original_name = (string) get_option('kodety_original_name', 'site.zip');
        $workspace_project_id = (string) get_option('kodety_workspace_project_id', '');
        $shared_project_id = $this->shared_project_id();
        if ($shared_project_id !== '') {
            $projects = $this->agency_projects();
            $project = is_array($projects[$shared_project_id] ?? null)
                ? $projects[$shared_project_id]
                : [];
            if (trim((string) ($project['name'] ?? '')) !== '') {
                $name = (string) $project['name'];
            }
            if (trim((string) ($project['originalName'] ?? '')) !== '') {
                $original_name = (string) $project['originalName'];
            }
            $workspace = $this->workspace_dir();
            if (is_dir($workspace)) {
                $resolved_id = $this->project_id_from_directory($workspace);
                if ($resolved_id !== '') $workspace_project_id = $resolved_id;
            }
        }
        return [
            'name' => $name,
            'originalName' => $original_name,
            'workspaceProjectId' => $workspace_project_id,
        ];
    }

    private function agency_snapshot_current(string $project_id): void {
        $project_id = sanitize_key($project_id);
        $workspace = $this->workspace_dir();
        if ($project_id === '' || !is_dir($workspace)) return;
        $target = $this->agency_project_dir($project_id);
        $next = $target . '.next';
        $previous = $target . '.previous';
        if (is_dir($next)) $this->remove_tree($next);
        wp_mkdir_p($next . '/workspace');
        $this->copy_workspace_tree($workspace, $next . '/workspace');
        file_put_contents($next . '/template.json', $this->project_template_manifest_json(), LOCK_EX);
        if (is_file($target . '/cover.png')) {
            copy($target . '/cover.png', $next . '/cover.png');
        }
        if (is_dir($target . '/published')) {
            $this->copy_workspace_tree($target . '/published', $next . '/published');
        }
        if (is_dir($previous)) $this->remove_tree($previous);
        if (is_dir($target) && !rename($target, $previous)) {
            $this->remove_tree($next);
            throw new RuntimeException('Não foi possível preparar o snapshot anterior deste projeto.');
        }
        if (!rename($next, $target)) {
            if (is_dir($previous)) rename($previous, $target);
            throw new RuntimeException('Não foi possível salvar o projeto no workspace da agência.');
        }
        if (is_dir($previous)) $this->remove_tree($previous);

        $projects = $this->agency_projects();
        if (isset($projects[$project_id])) {
            $projects[$project_id]['updatedAt'] = current_time('c');
            $projects[$project_id]['size'] = $this->directory_size($target . '/workspace');
            $name = trim((string) get_option('kodety_project_name', ''));
            if ($name !== '') $projects[$project_id]['name'] = substr(sanitize_text_field($name), 0, 120);
            $projects[$project_id]['originalName'] = sanitize_file_name((string) get_option('kodety_original_name', 'projeto.zip'));
            update_option('kodety_agency_projects', $projects, false);
        }
    }

    private function agency_register_current_project(
        string $name = '',
        string $folder_id = '',
        string $slug = '',
        bool $is_root = false
    ): string {
        if (!is_dir($this->workspace_dir())) throw new RuntimeException('O projeto atual ainda não possui um workspace.');
        $projects = $this->agency_projects();
        $active_id = $this->agency_active_project_id();
        if ($active_id !== '' && isset($projects[$active_id])) {
            $this->agency_snapshot_current($active_id);
            return $active_id;
        }
        $resolved_name = trim($name) !== ''
            ? substr(sanitize_text_field($name), 0, 120)
            : trim((string) get_option('kodety_project_name', ''));
        if ($resolved_name === '') $resolved_name = 'Projeto sem nome';
        $project_id = $this->agency_unique_id($resolved_name);
        $is_root = $projects === [] || $is_root;
        if ($is_root) {
            foreach ($projects as &$project) $project['isRoot'] = false;
            unset($project);
        }
        $projects[$project_id] = [
            'id' => $project_id,
            'name' => $resolved_name,
            'folderId' => sanitize_key($folder_id),
            'originalName' => sanitize_file_name((string) get_option('kodety_original_name', 'projeto.zip')),
            'createdAt' => current_time('c'),
            'updatedAt' => current_time('c'),
            'size' => $this->directory_size($this->workspace_dir()),
            'coverVersion' => 0,
            'slug' => $this->agency_unique_slug($slug !== '' ? $slug : $resolved_name),
            'isRoot' => $is_root,
            'release' => '',
            'publishedAt' => '',
        ];
        update_option('kodety_agency_projects', $projects, false);
        update_option('kodety_agency_active_project', $project_id, false);
        $this->agency_snapshot_current($project_id);
        return $project_id;
    }

    private function agency_capture_published_theme(string $project_id, string $theme_dir, string $release): void {
        $project_id = sanitize_key($project_id);
        $projects = $this->agency_projects();
        if (
            $project_id === ''
            || !isset($projects[$project_id])
            || !is_dir($theme_dir . '/site')
            || !is_file($theme_dir . '/manifest.json')
        ) return;
        $target = $this->agency_project_dir($project_id) . '/published';
        $next = $target . '.next';
        $previous = $target . '.previous';
        if (is_dir($next)) $this->remove_tree($next);
        $this->copy_workspace_tree($theme_dir, $next);

        $theme_site_url = trailingslashit(get_theme_root_uri() . '/kodety-generated/site');
        $agency_site_url = trailingslashit(
            home_url('/kodety-site-assets/' . rawurlencode((string) $projects[$project_id]['slug']) . '/site')
        );
        foreach (new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($next . '/site', FilesystemIterator::SKIP_DOTS)
        ) as $file) {
            if (!$file->isFile() || $file->isLink()) continue;
            $extension = strtolower($file->getExtension());
            if (!in_array($extension, ['css', 'js', 'mjs', 'cjs', 'html', 'htm', 'map'], true)) continue;
            $contents = (string) file_get_contents($file->getPathname());
            $rewritten = str_replace(
                [$theme_site_url, wp_make_link_relative($theme_site_url)],
                [$agency_site_url, wp_make_link_relative($agency_site_url)],
                $contents
            );
            $rewritten = $this->agency_rewrite_managed_asset_urls(
                $rewritten,
                $next,
                home_url('/kodety-site-assets/' . rawurlencode((string) $projects[$project_id]['slug']))
            );
            if ($rewritten !== $contents) file_put_contents($file->getPathname(), $rewritten, LOCK_EX);
        }
        if (is_dir($previous)) $this->remove_tree($previous);
        if (is_dir($target) && !rename($target, $previous)) {
            $this->remove_tree($next);
            throw new RuntimeException('Não foi possível preparar a publicação anterior deste projeto.');
        }
        if (!rename($next, $target)) {
            if (is_dir($previous)) rename($previous, $target);
            throw new RuntimeException('Não foi possível manter este projeto publicado na agência.');
        }
        if (is_dir($previous)) $this->remove_tree($previous);

        $projects = $this->agency_projects();
        if (!isset($projects[$project_id])) return;
        $projects[$project_id]['release'] = sanitize_key($release);
        $projects[$project_id]['publishedAt'] = current_time('c');
        $projects[$project_id]['updatedAt'] = current_time('c');
        update_option('kodety_agency_projects', $projects, false);
    }

    private function agency_restore_project(string $project_id): void {
        $project_id = sanitize_key($project_id);
        $projects = $this->agency_projects();
        $source = $this->agency_project_dir($project_id);
        if (!isset($projects[$project_id]) || !is_dir($source . '/workspace')) {
            throw new RuntimeException('Este projeto não possui um snapshot válido.');
        }
        $manifest = is_file($source . '/template.json')
            ? (string) file_get_contents($source . '/template.json')
            : $this->project_template_manifest_json();
        $transport = $this->package_editable_workspace_as_zip(
            $source . '/workspace',
            'kodety-agency-open-',
            $manifest
        );
        $previous_active_id = $this->agency_active_project_id();
        // Template restoration resolves project-scoped CMS/Analytics options
        // from the active id, so select the destination before importing its
        // manifest. Roll it back if the workspace transaction fails.
        update_option('kodety_agency_active_project', $project_id, false);
        try {
            $this->stage_builder_import($transport, (string) $projects[$project_id]['originalName']);
        } catch (Throwable $error) {
            update_option('kodety_agency_active_project', $previous_active_id, false);
            throw $error;
        } finally {
            if (is_file($transport)) @unlink($transport);
        }
        update_option('kodety_project_name', (string) $projects[$project_id]['name'], false);
        $projects[$project_id]['updatedAt'] = current_time('c');
        update_option('kodety_agency_projects', $projects, false);
    }

    /**
     * Import a ZIP into an agency project as one serialized workspace change.
     *
     * The selected project intentionally remains open in the Builder: the
     * upload contract redirects there with the manual publish panel open, and
     * any later publishing/capture is scoped by agency_active_project_id().
     * Published copies of every other project remain untouched.
     */
    private function agency_stage_builder_import(
        string $target_id,
        string $zip_path,
        string $original_name,
        string $new_project_name = ''
    ): string {
        return $this->with_workspace_lock(function () use (
            $target_id,
            $zip_path,
            $original_name,
            $new_project_name
        ): string {
            $target_id = sanitize_key($target_id);
            $projects_before = $this->agency_projects();
            $active_before = $this->agency_active_project_id();
            $creating = $target_id === 'new-project';

            if (!$creating && !isset($projects_before[$target_id])) {
                throw new RuntimeException('O projeto escolhido não existe mais. Selecione outro destino.');
            }

            if ($active_before !== '' && isset($projects_before[$active_before])) {
                $this->agency_snapshot_current($active_before);
            }

            try {
                if ($creating) {
                    update_option('kodety_agency_active_project', '', false);
                    $this->stage_builder_import($zip_path, $original_name);
                    $resolved_name = substr(sanitize_text_field($new_project_name), 0, 120);
                    if ($resolved_name === '') {
                        $resolved_name = sanitize_text_field(pathinfo($original_name, PATHINFO_FILENAME));
                    }
                    if ($resolved_name === '') $resolved_name = 'Novo projeto';
                    update_option('kodety_project_name', $resolved_name, false);
                    return $this->agency_register_current_project($resolved_name);
                }

                if ($active_before !== $target_id) {
                    $this->agency_restore_project($target_id);
                }
                $this->stage_builder_import($zip_path, $original_name);
                $this->agency_snapshot_current($target_id);
                return $target_id;
            } catch (Throwable $error) {
                if ($creating) {
                    $projects_after = $this->agency_projects();
                    foreach (array_diff(array_keys($projects_after), array_keys($projects_before)) as $created_id) {
                        $created_directory = $this->agency_project_dir((string) $created_id);
                        if (is_dir($created_directory)) $this->remove_tree($created_directory);
                    }
                    update_option('kodety_agency_projects', $projects_before, false);
                }

                if ($active_before !== '' && isset($projects_before[$active_before])) {
                    try {
                        $this->agency_restore_project($active_before);
                    } catch (Throwable $restore_error) {
                        throw new RuntimeException(
                            $error->getMessage()
                            . ' O projeto anterior também não pôde ser reaberto automaticamente: '
                            . $restore_error->getMessage(),
                            0,
                            $error
                        );
                    }
                } else {
                    update_option('kodety_agency_active_project', '', false);
                }
                throw $error;
            }
        });
    }

    private function create_blank_workspace(string $name): void {
        $name = substr(sanitize_text_field($name), 0, 120);
        if ($name === '') $name = 'Novo projeto';
        $token = wp_generate_password(10, false, false);
        $directory = trailingslashit(get_temp_dir()) . 'kodety-blank-' . $token;
        wp_mkdir_p($directory . '/.incode');
        $project_id = sanitize_key(sanitize_title($name) . '-' . strtolower(wp_generate_password(6, false, false)));
        $html = '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'
            . esc_html($name)
            . '</title></head><body style="margin:0;background:#fff;color:#111;font-family:Arial,sans-serif"><main style="min-height:100vh;padding:64px"><h1 style="margin:0;font-size:48px;line-height:1.05">'
            . esc_html($name)
            . '</h1><p style="margin:18px 0 0;color:#555;font-size:18px">Comece a criar no Onun Kodety.</p></main></body></html>';
        file_put_contents($directory . '/index.html', $html, LOCK_EX);
        file_put_contents($directory . '/.incode/project.json', (string) wp_json_encode([
            'version' => 2,
            'projectId' => $project_id,
            'name' => $name,
            'mainHtmlPath' => 'index.html',
        ], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE), LOCK_EX);
        $transport = null;
        try {
            $transport = $this->package_directory_as_zip($directory, 'kodety-blank-');
            $this->stage_builder_import($transport, sanitize_file_name($name) . '.zip');
        } finally {
            if (is_string($transport) && is_file($transport)) @unlink($transport);
            if (is_dir($directory)) $this->remove_tree($directory);
        }
    }

    private function upload_admin_workspace_logo(string $field): int {
        if (
            !isset($_FILES[$field])
            || !is_array($_FILES[$field])
            || (int) ($_FILES[$field]['error'] ?? UPLOAD_ERR_NO_FILE) === UPLOAD_ERR_NO_FILE
        ) {
            return absint(get_option('kodety_admin_logo_id', 0));
        }
        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-admin/includes/media.php';
        require_once ABSPATH . 'wp-admin/includes/image.php';
        $uploaded_id = media_handle_upload($field, 0, [], [
            'test_form' => false,
            'mimes' => ['jpg|jpeg' => 'image/jpeg', 'png' => 'image/png', 'webp' => 'image/webp'],
        ]);
        if (is_wp_error($uploaded_id)) {
            throw new RuntimeException($uploaded_id->get_error_message());
        }
        update_option('kodety_admin_logo_id', absint($uploaded_id), false);
        update_option('kodety_editor_corner_icon', 'client-logo', false);
        return absint($uploaded_id);
    }

    /**
     * Detect content that still depends on Elementor before Onun Kodety owns the
     * active theme and public routes.
     *
     * `_elementor_edit_mode=builder` is Elementor's canonical "built with"
     * marker. `_elementor_data` is also checked for legacy/imported documents
     * whose edit-mode flag is missing. Only IDs are loaded, never the large
     * layout JSON itself, and `elementor_library` is queried independently so
     * Theme Builder templates remain detectable while Elementor is disabled.
     *
     * @return array{active:bool,pageCount:int,contentCount:int,templateCount:int,frontPage:bool}
     */
    private function elementor_onboarding_summary(): array {
        $summary = [
            'active' => defined('ELEMENTOR_VERSION') || class_exists('Elementor\\Plugin', false),
            'pageCount' => 0,
            'contentCount' => 0,
            'templateCount' => 0,
            'frontPage' => false,
        ];

        // Do not bootstrap Elementor or materialize every matching post just
        // to render the first onboarding screen. On established Elementor
        // sites the former unbounded get_posts() queries could exhaust the
        // request memory immediately after Onun Kodety was installed. This single
        // aggregate query bypasses third-party query filters and returns only
        // four scalar values, regardless of the number of pages/templates.
        global $wpdb;
        if (
            isset($wpdb)
            && is_object($wpdb)
            && isset($wpdb->posts, $wpdb->postmeta)
            && method_exists($wpdb, 'get_row')
            && method_exists($wpdb, 'prepare')
        ) {
            $front_page_id = absint(get_option('page_on_front', 0));
            $sql = $wpdb->prepare(
                "SELECT
                    COUNT(DISTINCT CASE WHEN p.post_type = 'page' AND pm.post_id IS NOT NULL THEN p.ID END) AS page_count,
                    COUNT(DISTINCT CASE WHEN p.post_type NOT IN ('page', 'elementor_library') AND pm.post_id IS NOT NULL THEN p.ID END) AS content_count,
                    COUNT(DISTINCT CASE WHEN p.post_type = 'elementor_library' THEN p.ID END) AS template_count,
                    COUNT(DISTINCT CASE WHEN p.ID = %d AND p.post_type = 'page' AND pm.post_id IS NOT NULL THEN p.ID END) AS front_page_count
                FROM {$wpdb->posts} AS p
                LEFT JOIN {$wpdb->postmeta} AS pm
                    ON pm.post_id = p.ID
                    AND (
                        (pm.meta_key = '_elementor_edit_mode' AND pm.meta_value = 'builder')
                        OR pm.meta_key = '_elementor_data'
                    )
                WHERE p.post_status IN ('publish', 'future', 'draft', 'pending', 'private')
                    AND (p.post_type = 'elementor_library' OR pm.post_id IS NOT NULL)",
                $front_page_id
            );
            $counts = $wpdb->get_row($sql, ARRAY_A);
            if (is_array($counts)) {
                $summary['pageCount'] = max(0, (int) ($counts['page_count'] ?? 0));
                $summary['contentCount'] = max(0, (int) ($counts['content_count'] ?? 0));
                $summary['templateCount'] = max(0, (int) ($counts['template_count'] ?? 0));
                $summary['frontPage'] = (int) ($counts['front_page_count'] ?? 0) > 0;
                return $summary;
            }
        }

        // Lightweight fallback for partial/test WordPress environments where
        // $wpdb is unavailable. Production WordPress always uses the bounded
        // aggregate path above.
        if (!function_exists('get_posts')) return $summary;

        $fetch_ids = static function (array $query): array {
            try {
                $matches = get_posts(array_merge([
                    'post_status' => ['publish', 'future', 'draft', 'pending', 'private'],
                    'numberposts' => 1000,
                    'fields' => 'ids',
                    'orderby' => 'ID',
                    'order' => 'ASC',
                    'suppress_filters' => true,
                ], $query));
            } catch (Throwable) {
                return [];
            }

            $ids = [];
            foreach (is_array($matches) ? $matches : [] as $match) {
                $id = is_object($match) && isset($match->ID) ? (int) $match->ID : (int) $match;
                if ($id > 0) $ids[$id] = true;
            }
            return $ids;
        };
        $marked_ids = static function (string $post_type) use ($fetch_ids): array {
            $ids = $fetch_ids([
                'post_type' => $post_type,
                'meta_key' => '_elementor_edit_mode',
                'meta_value' => 'builder',
            ]);
            foreach ($fetch_ids([
                'post_type' => $post_type,
                'meta_key' => '_elementor_data',
                'meta_compare' => 'EXISTS',
            ]) as $id => $_present) {
                $ids[$id] = true;
            }
            return $ids;
        };

        $page_ids = $marked_ids('page');
        $template_ids = $fetch_ids(['post_type' => 'elementor_library']);
        $document_ids = $marked_ids('any');
        $other_content_ids = array_diff_key($document_ids, $page_ids, $template_ids);

        $summary['pageCount'] = count($page_ids);
        $summary['contentCount'] = count($other_content_ids);
        $summary['templateCount'] = count($template_ids);
        $front_page_id = absint(get_option('page_on_front', 0));
        $summary['frontPage'] = $front_page_id > 0 && isset($page_ids[$front_page_id]);
        return $summary;
    }

    /** Return one verified pre-deactivation render for the requested page. */
    private function elementor_rendered_snapshot_for_post(int $post_id): array {
        if ($post_id <= 0) return [];
        $candidates = [
            get_option('kodety_elementor_rendered_snapshot_' . $post_id, []),
            get_option('kodety_elementor_rendered_snapshot', []),
        ];
        foreach ($candidates as $snapshot) {
            if (!is_array($snapshot)
                || (int) ($snapshot['postId'] ?? 0) !== $post_id
                || !is_string($snapshot['html'] ?? null)
                || trim((string) $snapshot['html']) === ''
            ) continue;
            $sha256 = (string) ($snapshot['sha256'] ?? '');
            if ($sha256 === '' || !hash_equals($sha256, hash('sha256', (string) $snapshot['html']))) continue;
            return $snapshot;
        }
        return [];
    }

    /**
     * Inventory local Elementor pages for the onboarding selector. Snapshot
     * readiness is informational only: Elementor Free stays active and the
     * selected page can be rendered safely when conversion is confirmed.
     *
     * @return list<array{postId:int,title:string,status:string,statusLabel:string,url:string,snapshotAvailable:bool,captureMethod:string,capturedAt:int}>
     */
    private function elementor_onboarding_pages(): array {
        $ids = [];
        if (function_exists('get_posts')) {
            try {
                $matches = get_posts([
                    'post_type' => 'page',
                    'post_status' => ['publish', 'future', 'private', 'draft', 'pending'],
                    'numberposts' => 1000,
                    'fields' => 'ids',
                    'orderby' => 'ID',
                    'order' => 'ASC',
                    'suppress_filters' => true,
                    'meta_key' => '_elementor_data',
                    'meta_compare' => 'EXISTS',
                ]);
                foreach (is_array($matches) ? $matches : [] as $match) {
                    $post_id = absint(is_object($match) && isset($match->ID) ? $match->ID : $match);
                    if ($post_id > 0) $ids[$post_id] = true;
                }
            } catch (Throwable) {
                // The snapshot registry below remains usable in lightweight
                // WordPress/test environments where get_posts is incomplete.
            }
        }
        $registry = get_option('kodety_elementor_rendered_snapshots', []);
        foreach (is_array($registry['pages'] ?? null) ? $registry['pages'] : [] as $entry) {
            $post_id = is_array($entry) ? absint($entry['postId'] ?? 0) : 0;
            if ($post_id > 0) $ids[$post_id] = true;
        }
        $legacy = get_option('kodety_elementor_rendered_snapshot', []);
        $legacy_post_id = is_array($legacy) ? absint($legacy['postId'] ?? 0) : 0;
        if ($legacy_post_id > 0) $ids[$legacy_post_id] = true;

        $status_labels = [
            'publish' => 'Publicada',
            'future' => 'Agendada',
            'private' => 'Privada',
            'draft' => 'Rascunho',
            'pending' => 'Pendente',
        ];
        $pages = [];
        foreach (array_keys($ids) as $post_id) {
            $post = function_exists('get_post') ? get_post($post_id) : null;
            if (is_object($post) && isset($post->post_type) && (string) $post->post_type !== 'page') continue;
            $snapshot = $this->elementor_rendered_snapshot_for_post($post_id);
            $title = is_object($post) ? trim((string) ($post->post_title ?? '')) : trim((string) ($snapshot['title'] ?? ''));
            $status = is_object($post) ? (string) ($post->post_status ?? '') : (string) ($snapshot['status'] ?? '');
            $url = function_exists('get_permalink') ? get_permalink($post_id) : '';
            if (!is_string($url) || $url === '') $url = (string) ($snapshot['sourceUrl'] ?? '');
            if ($title === '') $title = 'Página Elementor #' . $post_id;
            $pages[] = [
                'postId' => $post_id,
                'title' => $title,
                'status' => $status,
                'statusLabel' => $status_labels[$status] ?? ($status !== '' ? ucfirst($status) : 'Página'),
                'url' => $url,
                'snapshotAvailable' => $snapshot !== [],
                'captureMethod' => (string) ($snapshot['captureMethod'] ?? ''),
                'capturedAt' => (int) ($snapshot['capturedAt'] ?? 0),
            ];
        }
        usort($pages, static function (array $left, array $right): int {
            $availability = (int) $right['snapshotAvailable'] <=> (int) $left['snapshotAvailable'];
            return $availability !== 0 ? $availability : ($left['postId'] <=> $right['postId']);
        });
        return $pages;
    }

    /** Pick the first local Elementor page for legacy callers. */
    private function elementor_default_import_post_id(): int {
        $pages = $this->elementor_onboarding_pages();
        foreach ($pages as $page) {
            if (!empty($page['snapshotAvailable'])) return (int) $page['postId'];
        }
        if ($pages !== []) return (int) ($pages[0]['postId'] ?? 0);

        $front_page_id = absint(get_option('page_on_front', 0));
        if ($front_page_id > 0 && !is_wp_error($this->elementor_import_document($front_page_id))) {
            return $front_page_id;
        }

        $matches = get_posts([
            'post_type' => 'page',
            'post_status' => ['publish', 'future', 'private', 'draft', 'pending'],
            'numberposts' => 1000,
            'fields' => 'ids',
            'orderby' => 'ID',
            'order' => 'ASC',
            'suppress_filters' => true,
            'meta_key' => '_elementor_data',
            'meta_compare' => 'EXISTS',
        ]);
        foreach (is_array($matches) ? $matches : [] as $match) {
            $post_id = absint(is_object($match) && isset($match->ID) ? $match->ID : $match);
            if ($post_id > 0 && !is_wp_error($this->elementor_import_document($post_id))) return $post_id;
        }
        return 0;
    }

    /** Pick a local Elementor page URL for the advanced converter panel. */
    private function elementor_default_import_url(): string {
        $post_id = $this->elementor_default_import_post_id();
        if ($post_id > 0) {
            $url = get_permalink($post_id);
            if (is_string($url) && $url !== '') return $url;
        }
        return home_url('/');
    }

    /** Build the selected Elementor page with its current HTML/CSS/JS. */
    private function elementor_published_project_zip(int $post_id, string $source_url): string|WP_Error {
        try {
            // Render again at confirmation time. Elementor Free remains active
            // while Elementor Pro/Pro Elements has already been unloaded in a
            // previous request, so this is both the freshest and safest source
            // for widget HTML plus generated post/Kit CSS.
            if (
                $this->import_source_is_same_wordpress($source_url)
                && class_exists('Elementor\\Plugin')
                && function_exists('kodety_render_elementor_document_for_snapshot')
            ) {
                $live_html = kodety_render_elementor_document_for_snapshot($post_id, $source_url);
                if ($live_html !== '') {
                    $prepared = $this->prepare_imported_html($live_html, $source_url, 'elementor');
                    return $this->import_bundle_page_assets($prepared, $source_url, 'elementor', 'animated');
                }
            }

            $snapshot = $this->elementor_rendered_snapshot_for_post($post_id);
            $snapshot_html = is_string($snapshot['html'] ?? null) ? (string) $snapshot['html'] : '';
            $snapshot_url = is_string($snapshot['sourceUrl'] ?? null)
                ? (string) $snapshot['sourceUrl']
                : $source_url;
            if ($snapshot_html !== '') {
                $prepared = $this->prepare_imported_html($snapshot_html, $snapshot_url, 'elementor');
                return $this->import_bundle_page_assets($prepared, $snapshot_url, 'elementor', 'animated');
            }

            // A local conversion must never fall through to the external URL
            // importer. Besides losing the pre-deactivation CSS, that path can
            // surface unrelated host restrictions
            // instead of explaining that this page lacks a local render.
            if ($this->import_source_is_same_wordpress($source_url)) {
                return new WP_Error(
                    'kodety_elementor_snapshot_missing',
                    'Não foi possível renderizar esta página. Confirme que o Elementor gratuito está ativo e que Elementor Pro e Pro Elements estão desativados; depois tente converter novamente.',
                    ['status' => 409]
                );
            }

            $result = $this->fetch_external_project($source_url, 0, '', 'elementor', 'animated');
            if (is_wp_error($result)) return $result;
            if (($result['kind'] ?? '') !== 'zip' || ($result['platform'] ?? '') !== 'elementor') {
                return new WP_Error('kodety_elementor_published_invalid', 'A página publicada não retornou um projeto Elementor válido.', ['status' => 422]);
            }
            $path = tempnam(get_temp_dir(), 'kodety-elementor-published-');
            if ($path === false || file_put_contents($path, (string) ($result['content'] ?? ''), LOCK_EX) === false) {
                if (is_string($path)) @unlink($path);
                return new WP_Error('kodety_elementor_published_write_failed', 'Não foi possível preparar a página publicada do Elementor.', ['status' => 500]);
            }
            return $path;
        } catch (Throwable $error) {
            if (isset($path) && is_string($path) && is_file($path)) @unlink($path);
            return new WP_Error('kodety_elementor_published_failed', $error->getMessage(), ['status' => 500]);
        }
    }

    /** Convert the explicitly selected Elementor page into the active draft. */
    private function stage_elementor_import(int $post_id): int {
        $import_revision = (int) get_option('kodety_workspace_revision', 0);
        if ($post_id <= 0) {
            throw new RuntimeException('Selecione uma página Elementor antes de iniciar a conversão.');
        }
        if (!current_user_can('edit_post', $post_id)) {
            throw new RuntimeException('Você não tem permissão para converter esta página Elementor.');
        }
        if (is_wp_error($this->elementor_import_document($post_id))) {
            throw new RuntimeException('A página selecionada não contém um documento Elementor válido.');
        }
        $source_url = get_permalink($post_id);
        if (!is_string($source_url) || $source_url === '') {
            $source_url = add_query_arg('page_id', (string) $post_id, home_url('/'));
        }
        $zip_path = $this->elementor_published_project_zip($post_id, $source_url);
        $filename = 'elementor-' . $post_id . '-publicado.zip';
        if (is_wp_error($zip_path)) {
            throw new RuntimeException(
                'Não conseguimos obter o HTML, CSS e JavaScript publicados desta página Elementor. '
                . 'Nenhuma conversão estrutural incompleta foi aplicada. Detalhe: '
                . $zip_path->get_error_message()
            );
        }
        try {
            $this->stage_builder_import($zip_path, $filename, true, $import_revision);
        } finally {
            if (is_file($zip_path)) @unlink($zip_path);
        }
        return $post_id;
    }

    /**
     * The public Studio shell and the Chrome extension both run WordPress on
     * Playground's origin, so PHP cannot safely infer the parent application
     * from HTTP_HOST. The shell writes the project metadata after mounting it
     * and also defines KODETY_BROWSER_STUDIO_RUNTIME inside PHP-WASM memory.
     * That marker cannot survive a ZIP export, browser restart, or deployment
     * to a hosted WordPress, even if the database option is transferred.
     *
     * @return array{enabled:true,projectId:string,projectSlug:string,displayPath:string,siteUrl:string,previewUrl:string,proxyBaseUrl:string,studioOrigin:string,studioLanguage:string,wordpressLocale:string}|null
     */
    public function browser_studio_runtime(): ?array {
        $runtime = get_option('kodety_browser_runtime', null);
        if (
            !is_array($runtime)
            || empty($runtime['enabled'])
            || (string) ($runtime['kind'] ?? '') !== self::BROWSER_STUDIO_RUNTIME_KIND
            || !defined('KODETY_BROWSER_STUDIO_RUNTIME')
        ) return null;

        $project_id = sanitize_text_field((string) ($runtime['projectId'] ?? ''));
        $project_name = sanitize_text_field((string) ($runtime['projectName'] ?? ''));
        $project_slug = sanitize_title((string) ($runtime['projectSlug'] ?? ''));
        $studio_origin = rtrim(trim((string) ($runtime['studioOrigin'] ?? '')), '/');
        if (
            $project_id === ''
            || !preg_match('/^[a-z0-9-]{8,80}$/i', $project_id)
            || (string) constant('KODETY_BROWSER_STUDIO_RUNTIME') !== $project_id
            || $project_slug === ''
            || !$this->is_browser_studio_origin($studio_origin)
        ) return null;

        $studio_language = ($runtime['studioLanguage'] ?? '') === 'en' ? 'en' : 'pt';
        $preview_url = add_query_arg('kodety-preview', $project_id, trailingslashit($studio_origin));
        if ($project_name !== '') $preview_url = add_query_arg('name', $project_name, $preview_url);
        $preview_url = add_query_arg('lang', $studio_language, $preview_url);
        $proxy_base_url = trailingslashit($studio_origin)
            . '__kodety_preview__/'
            . rawurlencode($project_id)
            . '/';

        return [
            'enabled' => true,
            'projectId' => $project_id,
            'projectSlug' => $project_slug,
            'displayPath' => '/' . $project_slug,
            'siteUrl' => home_url('/'),
            'previewUrl' => $preview_url,
            'proxyBaseUrl' => $proxy_base_url,
            'studioOrigin' => $studio_origin,
            'studioLanguage' => $studio_language,
            'wordpressLocale' => ($runtime['wordpressLocale'] ?? '') === 'pt_BR' ? 'pt_BR' : 'en_US',
        ];
    }

    private function is_browser_studio_origin(string $origin): bool {
        $parts = wp_parse_url($origin);
        if (!is_array($parts)) return false;
        $scheme = strtolower((string) ($parts['scheme'] ?? ''));
        $host = strtolower((string) ($parts['host'] ?? ''));
        $path = trim((string) ($parts['path'] ?? ''), '/');
        if ($path !== '' || isset($parts['user']) || isset($parts['pass']) || isset($parts['query']) || isset($parts['fragment'])) return false;
        if ($scheme === 'https' && $host !== '') return true;
        if ($scheme === 'http' && in_array($host, ['127.0.0.1', 'localhost'], true)) return true;
        return $scheme === 'chrome-extension' && preg_match('/^[a-p]{32}$/', $host) === 1;
    }

    public function render_onboarding_document(): void {
        if (!current_user_can('manage_options')) wp_die('Sem permissão.', '', ['response' => 403]);
        nocache_headers();
        $this->onboarding_page();
        exit;
    }

    public function onboarding_page(array $state = []): void {
        if (!current_user_can('manage_options')) return;
        $test_mode = (isset($_GET['onboarding']) && is_string($_GET['onboarding'])
            && sanitize_text_field(wp_unslash($_GET['onboarding'])) === 'teste');
        $i18n = class_exists('Kodety_Admin_I18n') ? Kodety_Admin_I18n::instance() : null;
        $t = static fn(string $source): string => $i18n ? $i18n->translate($source) : $source;
        $locale = str_replace('_', '-', $i18n ? $i18n->effective_locale() : get_locale());
        $direction = $i18n ? ($i18n->catalogs()[$locale]['direction'] ?? 'ltr') : (is_rtl() ? 'rtl' : 'ltr');
        $asset_url = static fn(string $relative): string => add_query_arg(
            'ver',
            is_file(KODETY_DIR . $relative) ? (string) filemtime(KODETY_DIR . $relative) : KODETY_VERSION,
            KODETY_URL . $relative
        );
        $accent = self::normalize_interface_accent_color($state['accent'] ?? get_option('kodety_admin_accent_color', self::DEFAULT_ADMIN_ACCENT_COLOR));
        $has_existing_project = $this->has_workspace();
        $elementor_summary = $this->elementor_onboarding_summary();
        $elementor_detected = (int) $elementor_summary['pageCount'] > 0
            || (int) $elementor_summary['contentCount'] > 0
            || (int) $elementor_summary['templateCount'] > 0;
        $elementor_pro_was_deactivated = is_array(get_option('kodety_elementor_pro_deactivated_on_activation', null));
        $elementor_pages = $elementor_detected ? $this->elementor_onboarding_pages() : [];
        $selected_elementor_post_id = absint($state['elementorPostId'] ?? 0);
        if ($selected_elementor_post_id <= 0) {
            foreach ($elementor_pages as $elementor_page) {
                if (!empty($elementor_page['snapshotAvailable'])) {
                    $selected_elementor_post_id = (int) $elementor_page['postId'];
                    break;
                }
            }
            if ($selected_elementor_post_id <= 0 && $elementor_pages !== []) {
                $selected_elementor_post_id = (int) ($elementor_pages[0]['postId'] ?? 0);
            }
        }
        $current_project_name = (string) ($state['name'] ?? get_option('kodety_project_name', ''));
        if ($current_project_name === '' && !isset($state['name'])) $current_project_name = get_bloginfo('name');
        $source = $state['source'] ?? ($has_existing_project ? 'existing' : 'blank');
        if ($source === 'elementor' && !$elementor_detected) $source = $has_existing_project ? 'existing' : 'blank';
        $logo_id = absint(get_option('kodety_admin_logo_id', 0));
        $logo_url = $logo_id ? (string) wp_get_attachment_image_url($logo_id, 'thumbnail') : '';
        $security = Kodety_Security::instance();
        $studio_runtime = $this->browser_studio_runtime();
        $login_locked = $security->login_slug_locked();
        $current_login_slug = $security->active_slug();
        $login_slug = $login_locked ? $current_login_slug : (string) ($state['slug'] ?? ($current_login_slug ?: Kodety_Security::DEFAULT_SLUG));
        $login_url = $login_locked ? $security->login_url() : home_url('/' . $login_slug);
        $login_base = trailingslashit(home_url());
        $initial_step = max(1, min(4, (int) ($state['step'] ?? 1)));
        $error = (string) ($state['error'] ?? '');
        $steps = [
            1 => ['Boas-vindas', 'Seu espaço de criação'],
            2 => ['Projeto', 'Escolha como começar'],
            3 => ['Identidade', 'Deixe o painel com sua marca'],
            4 => $studio_runtime
                ? ['Projeto local', 'Volte pela biblioteca de projetos']
                : ['Login seguro', 'Defina seu próximo acesso'],
        ];
        $messages = [
            'counter' => 'Etapa {current} de {total}',
            'start' => 'Vamos começar',
            'next' => 'Continuar',
            'finish' => $test_mode ? 'Encerrar prévia' : 'Concluir configuração',
            'submitting' => $test_mode ? 'Encerrando prévia…' : 'Preparando workspace…',
            'emptyFile' => 'Nenhum arquivo selecionado',
            'emptyLogo' => 'PNG, JPG ou WebP · opcional',
            'invalidZip' => 'Selecione um arquivo ZIP para importar.',
            'selectElementorPage' => 'Selecione uma página Elementor.',
            'convertingElementor' => 'Convertendo Elementor…',
            'invalidLogo' => 'Escolha uma imagem PNG, JPG ou WebP.',
            'emptyName' => 'Informe o nome do projeto.',
            'emptySlug' => 'Defina um endereço para o login antes de continuar.',
            'invalidSlug' => 'Use até 80 letras minúsculas, números e hífens, sem espaços ou barras.',
            'reservedSlug' => 'Este endereço é reservado. Escolha outro para o seu login.',
            'acknowledge' => 'Confirme que guardou o link de login para continuar.',
            'defaultSlug' => 'Padrão Onun Kodety',
            'customSlug' => 'Personalizado',
            'invalidUrl' => 'Preencha um endereço válido para ver o link.',
            'copied' => 'Link copiado.',
            'copyHint' => 'Depois de sair da conta, use este link para entrar novamente.',
            'copyFallback' => 'Link selecionado. Use Ctrl+C ou ⌘C para copiar.',
            'projectPlaceholder' => 'Seu projeto',
        ];
        $onboarding_config = [
            'initialStep' => $initial_step,
            'hasProject' => $has_existing_project,
            'defaultAccent' => self::DEFAULT_ADMIN_ACCENT_COLOR,
            'login' => array_merge(Kodety_Security::onboarding_slug_rules(), [
                'baseUrl' => $login_base,
                'currentSlug' => $current_login_slug,
                'defaultSlug' => Kodety_Security::DEFAULT_SLUG,
                'locked' => $login_locked,
                'url' => $login_url,
            ]),
            'messages' => array_map($t, $messages),
            'studio' => $studio_runtime,
        ];
        require KODETY_DIR . 'templates/onboarding.php';
    }

    public function complete_onboarding(): void {
        if (!current_user_can('manage_options')) wp_die('Sem permissão.', '', ['response' => 403]);
        check_admin_referer('kodety_complete_onboarding', 'kodety_onboarding_nonce');
        if (
            isset($_POST['kodety_onboarding_test'])
            && is_string($_POST['kodety_onboarding_test'])
            && wp_unslash($_POST['kodety_onboarding_test']) === '1'
        ) {
            wp_safe_redirect(admin_url());
            exit;
        }
        $posted = static fn(string $key, string $fallback = ''): string => isset($_POST[$key]) && is_string($_POST[$key])
            ? wp_unslash($_POST[$key]) : $fallback;
        $name = substr(sanitize_text_field($posted('kodety_project_name')), 0, 120);
        $accent = strtolower(trim($posted('kodety_admin_accent_color', self::DEFAULT_ADMIN_ACCENT_COLOR)));
        $requested_source = sanitize_key($posted('kodety_project_source', 'blank'));
        $source = in_array($requested_source, ['existing', 'import', 'elementor', 'blank'], true) ? $requested_source : 'blank';
        $elementor_post_id = absint($posted('kodety_elementor_post_id'));
        if ($source !== 'blank') $name = (string) get_option('kodety_project_name', get_bloginfo('name'));
        if ($posted('kodety_elementor_convert_now') === '1') {
            if (!current_user_can(self::CAP_EDIT_WORKSPACE)) {
                wp_die('Sem permissão para converter o Elementor.', '', ['response' => 403]);
            }
            try {
                $this->stage_elementor_import($elementor_post_id);
                update_option('kodety_workspace_mode', 'single', false);
                update_option('kodety_onboarding_status', 'complete', false);
            } catch (Throwable $error) {
                status_header(400);
                nocache_headers();
                $this->onboarding_page([
                    'step' => 2,
                    'error' => $error->getMessage(),
                    'name' => $name,
                    'accent' => $accent,
                    'source' => 'elementor',
                    'elementorPostId' => $elementor_post_id,
                    'slug' => $posted('kodety_admin_slug'),
                ]);
                exit;
            }
            wp_safe_redirect(add_query_arg([
                'kodety_elementor_import' => 'published',
                'kodety_elementor_post_id' => $elementor_post_id,
                'kodety_html' => 'index.html',
            ], home_url('/kodety/editor/')));
            exit;
        }
        $error_step = 4;
        try {
            $security = Kodety_Security::instance();
            // Validate the address and acknowledgement before changing a
            // project, uploading a logo or persisting any onboarding setting.
            $slug = $security->validate_onboarding_slug($_POST['kodety_admin_slug'] ?? null);
            $studio_runtime_enabled = $this->browser_studio_runtime() !== null;
            if (!$studio_runtime_enabled && $posted('kodety_login_saved') !== '1') {
                throw new InvalidArgumentException('Confirme que guardou o link de login para continuar.');
            }
            $error_step = 2;
            if ($source === 'existing' && !$this->has_workspace()) $source = 'blank';
            if ($source === 'blank' && trim($name) === '') throw new InvalidArgumentException('Informe o nome do projeto.');
            if ($source === 'import') {
                $file = $_FILES['kodety_project_zip'] ?? null;
                if (!is_array($file) || (int) ($file['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK || empty($file['tmp_name'])) {
                    throw new RuntimeException('Selecione um ZIP válido para importar.');
                }
            }
            $error_step = 3;
            if (!self::is_valid_interface_accent_color($accent)) $accent = self::DEFAULT_ADMIN_ACCENT_COLOR;
            $this->upload_admin_workspace_logo('kodety_admin_logo');
            $error_step = 2;
            if ($source === 'import') {
                $this->stage_builder_import((string) $file['tmp_name'], sanitize_file_name((string) ($file['name'] ?? 'projeto.zip')));
            } elseif ($source === 'elementor') {
                $this->stage_elementor_import($elementor_post_id);
            } elseif ($source === 'blank') {
                $this->create_blank_workspace($name);
            }
            update_option('kodety_workspace_mode', 'single', false);
            update_option('kodety_admin_accent_color', $accent, false);
            $error_step = 4;
            $security->save_onboarding_slug($slug);
            update_option('kodety_onboarding_status', 'complete', false);
        } catch (Throwable $error) {
            status_header(400);
            nocache_headers();
            $this->onboarding_page([
                'step' => $error_step,
                'error' => $error->getMessage(),
                'name' => $name,
                'accent' => $accent,
                'source' => $source,
                'elementorPostId' => $elementor_post_id,
                'slug' => $posted('kodety_admin_slug'),
            ]);
            exit;
        }
        if ($source === 'elementor') {
            wp_safe_redirect(add_query_arg([
                'kodety_elementor_import' => 'published',
                'kodety_html' => 'index.html',
            ], home_url('/kodety/editor/')));
            exit;
        }
        wp_safe_redirect(home_url('/kodety/editor/'));
        exit;
    }

    /** Compatibility endpoint; conversion still requires an explicit page. */
    public function convert_elementor_onboarding(): void {
        if (!current_user_can('manage_options') || !current_user_can(self::CAP_EDIT_WORKSPACE)) {
            wp_die('Sem permissão para converter o Elementor.', '', ['response' => 403]);
        }
        check_admin_referer('kodety_convert_elementor_onboarding', '_wpnonce');
        $post_id = isset($_REQUEST['kodety_elementor_post_id'])
            ? absint(wp_unslash($_REQUEST['kodety_elementor_post_id']))
            : 0;
        try {
            $this->stage_elementor_import($post_id);
            update_option('kodety_workspace_mode', 'single', false);
            update_option('kodety_onboarding_status', 'complete', false);
        } catch (Throwable $error) {
            wp_die(
                esc_html($error->getMessage()),
                'Não foi possível converter o Elementor',
                ['response' => 400, 'back_link' => true]
            );
        }
        wp_safe_redirect(add_query_arg([
            'kodety_elementor_import' => 'published',
            'kodety_elementor_post_id' => $post_id,
            'kodety_html' => 'index.html',
        ], home_url('/kodety/editor/')));
        exit;
    }

    public function save_workspace_mode(): void {
        if (!current_user_can('manage_options')) wp_die('Sem permissão.', '', ['response' => 403]);
        check_admin_referer('kodety_save_workspace_mode', 'kodety_workspace_mode_nonce');
        update_option('kodety_workspace_mode', 'single', false);
        wp_safe_redirect($this->project_admin_url('#kodety-settings'));
        exit;
    }

    public function delete_snapshots_from_admin(): void {
        if (!current_user_can('manage_options')) wp_die('Sem permissão.', '', ['response' => 403]);
        check_admin_referer('kodety_delete_snapshots', 'kodety_storage_nonce');
        try {
            $include_current = !empty($_POST['kodety_include_current_snapshot']);
            $result = $this->with_workspace_lock(
                fn(): array => $this->delete_release_snapshots($include_current)
            );
            $message = sprintf(
                '%d snapshot(s) removido(s).%s',
                (int) $result['deletedCount'],
                $include_current ? ' O snapshot publicado atual também foi incluído.' : ' O snapshot publicado atual foi preservado.'
            );
            $this->redirect_notice('success', $message);
        } catch (Throwable $error) {
            wp_die(esc_html($error->getMessage()), 'Não foi possível apagar os snapshots', ['response' => 500, 'back_link' => true]);
        }
    }

    public function delete_current_project_from_admin(): void {
        if (!current_user_can('manage_options')) wp_die('Sem permissão.', '', ['response' => 403]);
        check_admin_referer('kodety_delete_current_project', 'kodety_delete_project_nonce');
        try {
            $project = $this->storage_project_status();
            $this->with_workspace_lock(function () use ($project): array {
                return $project['mode'] === 'agency' && $project['id'] !== 'single'
                    ? $this->delete_agency_project($project['id'])
                    : $this->delete_single_project();
            });
            wp_safe_redirect($project['mode'] === 'agency' ? admin_url() : admin_url('admin.php?page=kodety'));
            exit;
        } catch (Throwable $error) {
            wp_die(esc_html($error->getMessage()), 'Não foi possível excluir o projeto', ['response' => 500, 'back_link' => true]);
        }
    }

