                $this->agency_register_current_project();
            } catch (Throwable $error) {
                echo '<div class="notice kodety-notice notice-error"><p>' . esc_html($error->getMessage()) . '</p></div>';
            }
        }
        $projects = $this->agency_projects();
        $folders = $this->agency_folders();
        $active_id = $this->agency_active_project_id();
        if ($projects && !array_filter($projects, static fn(array $project): bool => !empty($project['isRoot']))) {
            $root_id = isset($projects[$active_id]) ? $active_id : (string) array_key_first($projects);
            if ($root_id !== '' && isset($projects[$root_id])) {
                $projects[$root_id]['isRoot'] = true;
                update_option('kodety_agency_projects', $projects, false);
            }
