    public function agency_create_project(): void {
        if (!current_user_can(self::CAP_EDIT_WORKSPACE)) wp_die('Sem permissão.', '', ['response' => 403]);
        check_admin_referer('kodety_agency_create_project', 'kodety_agency_nonce');
        try {
            $active = $this->agency_active_project_id();
            if ($active !== '') $this->agency_snapshot_current($active);
            $name = substr(sanitize_text_field((string) wp_unslash($_POST['project_name'] ?? 'Novo projeto')), 0, 120);
            $folder_id = sanitize_key((string) wp_unslash($_POST['folder_id'] ?? ''));
            if ($folder_id !== '' && !isset($this->agency_folders()[$folder_id])) $folder_id = '';
            $slug = sanitize_title((string) wp_unslash($_POST['project_slug'] ?? $name));
            $is_root = !empty($_POST['project_root']);
            $source = wp_unslash($_POST['source'] ?? 'blank') === 'import' ? 'import' : 'blank';
            if ($source === 'import') {
                $file = $_FILES['project_zip'] ?? null;
                if (!is_array($file) || (int) ($file['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK || empty($file['tmp_name'])) {
                    throw new RuntimeException('Selecione um ZIP válido.');
                }
                $this->stage_builder_import((string) $file['tmp_name'], sanitize_file_name((string) ($file['name'] ?? 'projeto.zip')));
            } else {
                $this->create_blank_workspace($name);
            }
            update_option('kodety_agency_active_project', '', false);
            $this->agency_register_current_project($name, $folder_id, $slug, $is_root);
            wp_safe_redirect(home_url('/kodety/editor/'));
            exit;
        } catch (Throwable $error) {
            wp_die(esc_html($error->getMessage()), 'Não foi possível criar o projeto', ['response' => 400, 'back_link' => true]);
        }
    }

    public function agency_project_action(): void {
        if (!current_user_can(self::CAP_EDIT_WORKSPACE)) wp_die('Sem permissão.', '', ['response' => 403]);
        check_admin_referer('kodety_agency_project_action', 'kodety_agency_nonce');
        $operation = sanitize_key((string) wp_unslash($_REQUEST['operation'] ?? ''));
        $project_id = sanitize_key((string) wp_unslash($_REQUEST['project_id'] ?? ''));
        $projects = $this->agency_projects();
        if (!isset($projects[$project_id])) wp_die('Projeto não encontrado.', '', ['response' => 404, 'back_link' => true]);
        try {
            $active = $this->agency_active_project_id();
            if ($operation === 'activate') {
                if ($active !== '' && $active !== $project_id) $this->agency_snapshot_current($active);
                if ($active !== $project_id) $this->agency_restore_project($project_id);
                wp_safe_redirect(home_url('/kodety/editor/'));
                exit;
            }
            if ($operation === 'export') {
                if ($active === $project_id) $this->agency_snapshot_current($project_id);
                $source = $this->agency_project_dir($project_id);
                $manifest = is_file($source . '/template.json') ? (string) file_get_contents($source . '/template.json') : null;
                $zip = $this->package_editable_workspace_as_zip($source . '/workspace', 'kodety-agency-export-', $manifest);
                $bytes = (string) file_get_contents($zip);
                @unlink($zip);
                while (ob_get_level() > 0) ob_end_clean();
                nocache_headers();
                header('Content-Type: application/zip');
                header('Content-Disposition: attachment; filename="' . sanitize_file_name($projects[$project_id]['name']) . '.zip"');
                header('Content-Length: ' . strlen($bytes));
                header('X-Content-Type-Options: nosniff');
                echo $bytes;
                exit;
            }
            if ($operation === 'rename') {
                $name = substr(sanitize_text_field((string) wp_unslash($_POST['project_name'] ?? '')), 0, 120);
                if ($name === '') throw new RuntimeException('Informe um nome para o projeto.');
                $projects[$project_id]['name'] = $name;
                $projects[$project_id]['updatedAt'] = current_time('c');
                if ($active === $project_id) update_option('kodety_project_name', $name, false);
                update_option('kodety_agency_projects', $projects, false);
            } elseif ($operation === 'save_route') {
                $slug = $this->agency_unique_slug(
                    (string) wp_unslash($_POST['project_slug'] ?? $projects[$project_id]['slug']),
                    $project_id
                );
                $is_root = !empty($_POST['project_root']);
                if ($is_root) {
                    foreach ($projects as &$candidate) $candidate['isRoot'] = false;
                    unset($candidate);
                }
                $old_slug = (string) $projects[$project_id]['slug'];
                $projects[$project_id]['slug'] = $slug;
                $projects[$project_id]['isRoot'] = $is_root;
                $projects[$project_id]['updatedAt'] = current_time('c');
                update_option('kodety_agency_projects', $projects, false);
                if ($old_slug !== $slug && is_dir($this->agency_project_dir($project_id) . '/published/site')) {
                    $published = $this->agency_project_dir($project_id) . '/published/site';
                    $old_url = trailingslashit(home_url('/kodety-site-assets/' . rawurlencode($old_slug) . '/site'));
                    $new_url = trailingslashit(home_url('/kodety-site-assets/' . rawurlencode($slug) . '/site'));
                    foreach (new RecursiveIteratorIterator(
                        new RecursiveDirectoryIterator($published, FilesystemIterator::SKIP_DOTS)
                    ) as $file) {
                        if (!$file->isFile() || $file->isLink()) continue;
                        if (!in_array(strtolower($file->getExtension()), ['css', 'js', 'mjs', 'cjs', 'html', 'htm', 'map'], true)) continue;
                        $contents = (string) file_get_contents($file->getPathname());
                        $rewritten = str_replace($old_url, $new_url, $contents);
                        if ($contents !== $rewritten) file_put_contents($file->getPathname(), $rewritten, LOCK_EX);
                    }
                }
            } elseif ($operation === 'move') {
                $folder_id = sanitize_key((string) wp_unslash($_POST['folder_id'] ?? ''));
                if ($folder_id !== '' && !isset($this->agency_folders()[$folder_id])) {
                    throw new RuntimeException('A pasta escolhida não existe mais.');
                }
                $projects[$project_id]['folderId'] = $folder_id;
                $projects[$project_id]['updatedAt'] = current_time('c');
                update_option('kodety_agency_projects', $projects, false);
            } elseif ($operation === 'duplicate') {
                if ($active === $project_id) $this->agency_snapshot_current($project_id);
                $new_id = $this->agency_unique_id($projects[$project_id]['name'] . '-copy');
                $this->copy_workspace_tree($this->agency_project_dir($project_id), $this->agency_project_dir($new_id));
                $copy = $projects[$project_id];
                $copy['id'] = $new_id;
                $copy['name'] .= ' — cópia';
                $copy['slug'] = $this->agency_unique_slug($copy['name']);
                $copy['isRoot'] = false;
                $copy['createdAt'] = current_time('c');
                $copy['updatedAt'] = current_time('c');
                $projects[$new_id] = $copy;
                update_option('kodety_agency_projects', $projects, false);
            } elseif ($operation === 'delete') {
                $this->delete_agency_project($project_id);
            } else {
                throw new RuntimeException('Ação de projeto inválida.');
            }
            wp_safe_redirect(admin_url());
            exit;
        } catch (Throwable $error) {
            wp_die(esc_html($error->getMessage()), 'Não foi possível atualizar o projeto', ['response' => 500, 'back_link' => true]);
        }
    }

    public function agency_folder_action(): void {
        if (!current_user_can(self::CAP_EDIT_WORKSPACE)) wp_die('Sem permissão.', '', ['response' => 403]);
        check_admin_referer('kodety_agency_folder_action', 'kodety_agency_nonce');
        $operation = sanitize_key((string) wp_unslash($_POST['operation'] ?? ''));
        $folders = $this->agency_folders();
        if ($operation === 'create') {
            $name = substr(sanitize_text_field((string) wp_unslash($_POST['folder_name'] ?? '')), 0, 80);
            if ($name === '') wp_die('Informe o nome da pasta.', '', ['response' => 400, 'back_link' => true]);
            $id = sanitize_key(sanitize_title($name) . '-' . strtolower(wp_generate_password(5, false, false)));
            $folders[$id] = ['id' => $id, 'name' => $name, 'createdAt' => current_time('c')];
            update_option('kodety_agency_folders', $folders, false);
        } elseif ($operation === 'rename') {
            $folder_id = sanitize_key((string) wp_unslash($_POST['folder_id'] ?? ''));
            $name = substr(sanitize_text_field((string) wp_unslash($_POST['folder_name'] ?? '')), 0, 80);
            if (!isset($folders[$folder_id]) || $name === '') {
                wp_die('Pasta inválida.', '', ['response' => 400, 'back_link' => true]);
            }
            $folders[$folder_id]['name'] = $name;
            update_option('kodety_agency_folders', $folders, false);
        } elseif ($operation === 'delete') {
            $folder_id = sanitize_key((string) wp_unslash($_POST['folder_id'] ?? ''));
            unset($folders[$folder_id]);
            update_option('kodety_agency_folders', $folders, false);
            $projects = $this->agency_projects();
            foreach ($projects as &$project) if ($project['folderId'] === $folder_id) $project['folderId'] = '';
            unset($project);
            update_option('kodety_agency_projects', $projects, false);
        } else {
            wp_die('Ação de pasta inválida.', '', ['response' => 400, 'back_link' => true]);
        }
        wp_safe_redirect(admin_url());
        exit;
    }

    public function agency_project_cover(): void {
        if (!current_user_can(self::CAP_EDIT_WORKSPACE)) {
            wp_die('Sem permissão.', '', ['response' => 403]);
        }
        $project_id = sanitize_key((string) wp_unslash($_GET['project_id'] ?? ''));
        check_admin_referer('kodety_agency_project_cover_' . $project_id);
        $projects = $this->agency_projects();
        $cover = $this->agency_project_dir($project_id) . '/cover.png';
        $size = is_file($cover) ? (int) (filesize($cover) ?: 0) : 0;
        $details = $size > 0 && $size <= 12 * MB_IN_BYTES ? @getimagesize($cover) : false;
        if (!isset($projects[$project_id]) || !$details || ($details[2] ?? 0) !== IMAGETYPE_PNG) {
            wp_die('Capa não encontrada.', '', ['response' => 404]);
        }
        while (ob_get_level() > 0) ob_end_clean();
        header('Content-Type: image/png');
        header('Content-Length: ' . $size);
        header('Cache-Control: private, max-age=31536000, immutable');
        header('X-Content-Type-Options: nosniff');
        readfile($cover);
        exit;
    }

    public function admin_page(): void {
        if (!current_user_can('kodety_edit')) return;
        $workspace_path = $this->workspace_dir();
        $has_project = $this->has_workspace();
        $interface_enabled = $this->is_interface_enabled();
        // Mesma fonte que o painel de publicação do Builder consome pela REST
        // (/kodety/v1/optimizations): a opção salva, nunca os defaults. Sem esta
        // linha os checkboxes liam uma variável inexistente e voltavam sempre
        // desmarcados, mesmo com tudo ativo no banco.
        $optimization_settings = $this->optimization_settings();
        $editor_corner_icon = sanitize_key((string) get_option('kodety_editor_corner_icon', 'kodety-logo'));
        if (!in_array($editor_corner_icon, ['kodety-logo', 'client-logo'], true)) $editor_corner_icon = 'kodety-logo';
        $brand_logo_id = absint(get_option('kodety_admin_logo_id', 0));
        $brand_logo_url = $brand_logo_id ? (string) wp_get_attachment_image_url($brand_logo_id, 'thumbnail') : '';
        $login_image_id = absint(get_option('kodety_login_image_id', 0));
        $login_image_url = $login_image_id ? (string) wp_get_attachment_image_url($login_image_id, 'medium_large') : '';
        if ($editor_corner_icon === 'client-logo' && $brand_logo_url === '') $editor_corner_icon = 'kodety-logo';
        $admin_accent_color = self::normalize_interface_accent_color(get_option(
            'kodety_admin_accent_color',
            self::DEFAULT_ADMIN_ACCENT_COLOR
        ));
        $admin_accent_contrast = self::interface_accent_contrast_ratio($admin_accent_color);
        $admin_ui_i18n = class_exists('Kodety_Admin_I18n') ? Kodety_Admin_I18n::instance() : null;
        $admin_ui_locale_selection = $admin_ui_i18n ? $admin_ui_i18n->selection() : 'auto';
        $admin_ui_catalogs = $admin_ui_i18n ? $admin_ui_i18n->catalogs() : [];
        $admin_ui_effective_locale = $admin_ui_i18n ? $admin_ui_i18n->effective_locale() : 'en';
        $admin_ui_effective_catalog = $admin_ui_catalogs[$admin_ui_effective_locale] ?? ['nativeName' => 'English'];
        $release = (string) get_option('kodety_current_release', '');
        $storage_snapshots = current_user_can('manage_options') ? $this->release_snapshot_inventory() : [];
        $storage_project = current_user_can('manage_options') ? $this->storage_project_status() : [];
        $original_name = sanitize_file_name((string) get_option('kodety_original_name', 'project.zip')) ?: 'project.zip';
        $project_theme = wp_get_theme('kodety-generated');
        $active_theme = wp_get_theme();
        $theme_exists = $project_theme->exists();
        $theme_active = $active_theme->get_stylesheet() === 'kodety-generated';
        $theme_name = $theme_exists ? (string) $project_theme->get('Name') : 'Onun Kodety Generated Site';
        $legacy_zip = $this->current_zip();
        $zip_size = is_dir($workspace_path)
            ? $this->directory_size($workspace_path)
            : (is_file($legacy_zip) ? (int) (filesize($legacy_zip) ?: 0) : 0);
        $zip_modified = is_dir($workspace_path)
            ? (int) (filemtime($workspace_path) ?: 0)
            : (is_file($legacy_zip) ? (int) (filemtime($legacy_zip) ?: 0) : 0);
        $direct_upload_max_size = min((int) wp_max_upload_size(), 8 * 1024 * 1024);
        $project_upload_max_size = self::PROJECT_ARCHIVE_MAX_BYTES;
        $extension_archive_limit = class_exists('Kodety_Extensions')
            ? Kodety_Extensions::max_archive_bytes()
            : 256 * 1024 * 1024;
        $extension_upload_max_size = min((int) wp_max_upload_size(), $extension_archive_limit);
        $chunk_upload_url = rest_url('kodety/v1/project/chunk');
        $chunk_upload_nonce = wp_create_nonce('wp_rest');
        $can_install_extensions = current_user_can('manage_options')
            && current_user_can('install_plugins');
        $can_activate_extensions = current_user_can('manage_options')
            && current_user_can('activate_plugins');
        $extensions = current_user_can('manage_options') ? $this->dashboard_extensions() : [];
        $publish_label = 'Importar e publicar no Builder';
        $elementor_converter_requested = isset($_GET['kodety_elementor_converter'])
            && sanitize_text_field((string) wp_unslash($_GET['kodety_elementor_converter'])) === '1';
        $elementor_runtime_active = defined('ELEMENTOR_VERSION') || class_exists('Elementor\\Plugin', false);
        $elementor_default_url = $elementor_converter_requested ? $this->elementor_default_import_url() : '';
        $agency_mode = $this->workspace_mode() === 'agency';
        $agency_projects = $agency_mode ? $this->agency_projects() : [];
        $agency_active_id = $agency_mode ? $this->agency_active_project_id() : '';
        $agency_default_target = '';
        if ($agency_mode) {
            if ($agency_active_id !== '' && isset($agency_projects[$agency_active_id])) {
                $agency_default_target = $agency_active_id;
            } else {
                foreach ($agency_projects as $candidate_id => $candidate) {
                    if (!empty($candidate['isRoot'])) {
                        $agency_default_target = (string) $candidate_id;
                        break;
                    }
                }
                if ($agency_default_target === '' && $agency_projects) {
                    $agency_default_target = (string) array_key_first($agency_projects);
                }
                if ($agency_default_target === '') $agency_default_target = 'new-project';
            }
        }
        $default_has_project = $agency_mode
            ? isset($agency_projects[$agency_default_target])
            : $has_project;
        $replacement_project_name = '';
        $replacement_original_name = $original_name;
        $replacement_size = $zip_size;
        $replacement_modified = $zip_modified;
        if ($agency_mode && isset($agency_projects[$agency_default_target])) {
            $default_project = $agency_projects[$agency_default_target];
            $replacement_project_name = (string) $default_project['name'];
            $replacement_original_name = (string) $default_project['originalName'];
            $replacement_size = (int) $default_project['size'];
            $replacement_modified = strtotime((string) $default_project['updatedAt']) ?: 0;
            if ($agency_default_target === $agency_active_id) {
                $replacement_original_name = $original_name;
                $replacement_size = $zip_size;
                $replacement_modified = $zip_modified;
            }
        } elseif (!$agency_mode && $has_project) {
            $replacement_project_name = trim((string) get_option('kodety_project_name', 'Projeto atual'));
        }
        if ($replacement_project_name === '') $replacement_project_name = 'Projeto atual';
        $backup_url = wp_nonce_url(
            add_query_arg('action', 'kodety_download_project_backup', admin_url('admin-post.php')),
            'kodety_download_project_backup'
        );
        if ($agency_mode && isset($agency_projects[$agency_default_target])) {
            $backup_url = wp_nonce_url(
                add_query_arg([
                    'action' => 'kodety_download_project_backup',
                    'project_id' => $agency_default_target,
                ], admin_url('admin-post.php')),
                'kodety_download_project_backup_' . $agency_default_target
            );
        }
        $agency_import_options = [];
        if ($agency_mode) {
            $ordered_project_ids = array_keys($agency_projects);
            usort($ordered_project_ids, static function (string $left, string $right) use (
                $agency_projects,
                $agency_active_id
            ): int {
                $left_rank = $left === $agency_active_id
                    ? 0
                    : (!empty($agency_projects[$left]['isRoot']) ? 1 : 2);
                $right_rank = $right === $agency_active_id
                    ? 0
                    : (!empty($agency_projects[$right]['isRoot']) ? 1 : 2);
                if ($left_rank !== $right_rank) return $left_rank <=> $right_rank;
                return strcasecmp(
                    (string) $agency_projects[$left]['name'],
                    (string) $agency_projects[$right]['name']
                );
            });
            foreach ($ordered_project_ids as $project_id) {
                $project = $agency_projects[$project_id];
                $is_open = $project_id === $agency_active_id;
                $option_original_name = $is_open ? $original_name : (string) $project['originalName'];
                $option_size = $is_open ? $zip_size : (int) $project['size'];
                $option_modified = $is_open
                    ? $zip_modified
                    : (strtotime((string) $project['updatedAt']) ?: 0);
                $option_suffix = [];
                if ($is_open) $option_suffix[] = 'aberto no Builder';
                if (!empty($project['isRoot'])) $option_suffix[] = 'padrão do domínio';
                $option_label = (string) $project['name'];
                if ($option_suffix) $option_label .= ' — ' . implode(' · ', $option_suffix);
                $option_backup_url = wp_nonce_url(
                    add_query_arg([
                        'action' => 'kodety_download_project_backup',
                        'project_id' => $project_id,
                    ], admin_url('admin-post.php')),
                    'kodety_download_project_backup_' . $project_id
                );
                $agency_import_options[] = [
                    'id' => $project_id,
                    'label' => $option_label,
                    'name' => (string) $project['name'],
                    'originalName' => $option_original_name,
                    'size' => $option_size,
                    'updated' => $option_modified > 0
                        ? Kodety_Admin_I18n::instance()->format_date($option_modified)
                        : '',
                    'backupUrl' => $option_backup_url,
                ];
            }
        }
        if (!$has_project) {
            $project_status = 'Sem projeto';
            $project_status_class = 'is-empty';
            $theme_state = 'Aguardando a primeira importação';
        } elseif ($theme_active) {
            $project_status = 'Sincronizado';
            $project_status_class = 'is-success';
            $theme_state = 'Ativo no WordPress';
        } elseif ($theme_exists) {
            $project_status = 'Tema inativo';
            $project_status_class = 'is-warning';
            $theme_state = 'Instalado, mas não está ativo';
        } else {
            $project_status = 'Requer reparo';
            $project_status_class = 'is-danger';
            $theme_state = 'O tema gerado não foi encontrado';
        }
        ?>
