                    <?php if (current_user_can('manage_options')):
                        $security = Kodety_Security::instance();
                        $security_settings = $security->settings();
                        $active_login_slug = $security->active_slug();
                        $security_is_studio = $this->browser_studio_runtime() !== null;
                        $security_login_base = $security_is_studio ? '/' : trailingslashit(home_url());
                        $security_login_url = $security_is_studio
                            ? '/' . ltrim($active_login_slug !== '' ? $active_login_slug : 'wp-login.php', '/')
                            : $security->login_url();
                        $slug_locked_by_config = defined('KODETY_ADMIN_SLUG') || (defined('KODETY_DISABLE_ADMIN_SLUG') && KODETY_DISABLE_ADMIN_SLUG);
                        $security_score_keys = [
                            'login_throttle', 'generic_login_errors', 'block_enumeration',
                            'disable_xmlrpc', 'disable_file_edit', 'hide_wp_version', 'security_headers',
                        ];
                        $security_score_enabled = count(array_filter(
                            $security_score_keys,
                            static fn(string $key): bool => !empty($security_settings[$key])
                        ));
                        $security_score = min(100, (int) round(
                            ($security_score_enabled / count($security_score_keys)) * 80
                            + (is_ssl() ? 20 : 0)
                        ));
                        $security_score_class = $security_score >= 85 ? 'is-success' : ($security_score >= 60 ? 'is-warning' : 'is-danger');
                        ?>
