    public function save_interface_preference(): void {
        if (!current_user_can('manage_options')) wp_die('Sem permissão.', '', ['response' => 403]);
        check_admin_referer('kodety_save_interface', 'kodety_interface_nonce');
        $preference = isset($_POST['kodety_preference']) && is_string($_POST['kodety_preference'])
            ? sanitize_key(wp_unslash($_POST['kodety_preference']))
            : 'admin';
        $field = $preference === 'block_editor' ? 'kodety_block_editor_skin_enabled' : 'kodety_interface_enabled';
        $submitted = isset($_POST[$field]) && is_string($_POST[$field])
            ? sanitize_text_field(wp_unslash($_POST[$field]))
            : '0';
        $enabled = $submitted === '1';
        update_option($field, $enabled ? '1' : '0', false);
        wp_safe_redirect(add_query_arg([
            'page' => $this->project_admin_page_slug(),
            'kodety_interface_updated' => '1',
        ], admin_url('admin.php')) . '#kodety-interface');
        exit;
    }

    public function save_interface_accent(): void {
        if (!current_user_can('manage_options')) wp_die('Sem permissão.', '', ['response' => 403]);
        check_admin_referer('kodety_save_interface_accent', 'kodety_interface_accent_nonce');
        $submitted = isset($_POST['kodety_admin_accent_color']) && is_string($_POST['kodety_admin_accent_color'])
            ? strtolower(trim(wp_unslash($_POST['kodety_admin_accent_color'])))
            : '';
        if (!self::is_valid_interface_accent_color($submitted)) {
            wp_die(
                'Escolha uma cor hexadecimal que alcance contraste mínimo de 4,5:1 com texto preto.',
                'Cor de destaque sem contraste suficiente',
                ['response' => 400, 'back_link' => true]
            );
        }
        update_option('kodety_admin_accent_color', $submitted, false);
        wp_safe_redirect(add_query_arg([
            'page' => $this->project_admin_page_slug(),
            'kodety_accent_updated' => '1',
        ], admin_url('admin.php')) . '#kodety-interface');
        exit;
    }

    public function save_brand_settings(): void {
        if (!current_user_can('manage_options')) wp_die('Sem permissão.', '', ['response' => 403]);
        check_admin_referer('kodety_save_brand', 'kodety_brand_nonce');
        if (class_exists('Kodety_Admin_I18n') && isset($_POST['kodety_admin_ui_locale'])) {
            $admin_ui_locale = Kodety_Admin_I18n::instance()->sanitize_selection($_POST['kodety_admin_ui_locale']);
            update_option(Kodety_Admin_I18n::OPTION, $admin_ui_locale, false);
        }
        $brand_logo_id = absint(get_option('kodety_admin_logo_id', 0));
        if (isset($_POST['kodety_remove_brand_logo'])) {
            $brand_logo_id = 0;
            update_option('kodety_admin_logo_id', 0, false);
        }
        if (isset($_FILES['kodety_brand_logo']) && is_array($_FILES['kodety_brand_logo']) && (int) ($_FILES['kodety_brand_logo']['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_NO_FILE) {
            require_once ABSPATH . 'wp-admin/includes/file.php';
            require_once ABSPATH . 'wp-admin/includes/media.php';
            require_once ABSPATH . 'wp-admin/includes/image.php';
            $uploaded_id = media_handle_upload('kodety_brand_logo', 0, [], [
                'test_form' => false,
                'mimes' => ['jpg|jpeg' => 'image/jpeg', 'png' => 'image/png', 'webp' => 'image/webp'],
            ]);
            if (is_wp_error($uploaded_id)) wp_die(esc_html($uploaded_id->get_error_message()), 'Não foi possível enviar a logo', ['response' => 400]);
            $brand_logo_id = absint($uploaded_id);
            update_option('kodety_admin_logo_id', $brand_logo_id, false);
        }
        $current_login_image_id = absint(get_option('kodety_login_image_id', 0));
        $next_login_image_id = isset($_POST['kodety_remove_login_image']) ? 0 : $current_login_image_id;
        if (isset($_FILES['kodety_login_image']) && is_array($_FILES['kodety_login_image']) && (int) ($_FILES['kodety_login_image']['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_NO_FILE) {
            $upload_error = (int) ($_FILES['kodety_login_image']['error'] ?? UPLOAD_ERR_NO_FILE);
            $temporary_file = isset($_FILES['kodety_login_image']['tmp_name']) && is_string($_FILES['kodety_login_image']['tmp_name'])
                ? (string) $_FILES['kodety_login_image']['tmp_name']
                : '';
            $original_name = isset($_FILES['kodety_login_image']['name']) && is_string($_FILES['kodety_login_image']['name'])
                ? sanitize_file_name(wp_unslash($_FILES['kodety_login_image']['name']))
                : '';
            if (
                $upload_error !== UPLOAD_ERR_OK
                || $temporary_file === ''
                || (!is_uploaded_file($temporary_file) && !is_readable($temporary_file))
            ) {
                wp_die('Não foi possível ler a imagem selecionada.', 'Não foi possível enviar a imagem do login', ['response' => 400, 'back_link' => true]);
            }

            $submitted_size = (int) (filesize($temporary_file) ?: 0);
            if ($submitted_size <= 0 || $submitted_size > self::LOGIN_IMAGE_MAX_BYTES) {
                wp_die('A imagem deve ter no máximo 1 MB.', 'Não foi possível enviar a imagem do login', ['response' => 400, 'back_link' => true]);
            }
            $allowed_login_image_mimes = [
                'jpg|jpeg' => 'image/jpeg',
                'png' => 'image/png',
                'webp' => 'image/webp',
            ];
            $checked_file = wp_check_filetype_and_ext($temporary_file, $original_name, $allowed_login_image_mimes);
            $detected_mime = (string) wp_get_image_mime($temporary_file);
            $image_details = function_exists('wp_getimagesize')
                ? wp_getimagesize($temporary_file)
                : @getimagesize($temporary_file);
            $allowed_image_types = [IMAGETYPE_JPEG, IMAGETYPE_PNG, IMAGETYPE_WEBP];
            $image_width = is_array($image_details) ? absint($image_details[0] ?? 0) : 0;
            $image_height = is_array($image_details) ? absint($image_details[1] ?? 0) : 0;
            $image_type = is_array($image_details) ? absint($image_details[2] ?? 0) : 0;
            if (
                !is_array($checked_file)
                || empty($checked_file['ext'])
                || !in_array((string) ($checked_file['type'] ?? ''), array_values($allowed_login_image_mimes), true)
                || !in_array($detected_mime, array_values($allowed_login_image_mimes), true)
                || (string) ($checked_file['type'] ?? '') !== $detected_mime
                || !in_array($image_type, $allowed_image_types, true)
                || $image_width <= 0
                || $image_height <= 0
            ) {
                wp_die('Use uma imagem PNG, JPG ou WebP de até 1 MB.', 'Não foi possível enviar a imagem do login', ['response' => 400, 'back_link' => true]);
            }
            if ($image_width > self::LOGIN_IMAGE_MAX_DIMENSION || $image_height > self::LOGIN_IMAGE_MAX_DIMENSION) {
                wp_die('A imagem deve ter no máximo 4096 px por lado.', 'Não foi possível enviar a imagem do login', ['response' => 400, 'back_link' => true]);
            }
            if ($image_width > intdiv(self::LOGIN_IMAGE_MAX_PIXELS, $image_height)) {
                wp_die('A imagem deve ter no máximo 12 megapixels.', 'Não foi possível enviar a imagem do login', ['response' => 400, 'back_link' => true]);
            }

            require_once ABSPATH . 'wp-admin/includes/file.php';
            require_once ABSPATH . 'wp-admin/includes/media.php';
            require_once ABSPATH . 'wp-admin/includes/image.php';
            $uploaded_login_image_id = media_handle_upload('kodety_login_image', 0, [], [
                'test_form' => false,
                'mimes' => ['jpg|jpeg' => 'image/jpeg', 'png' => 'image/png', 'webp' => 'image/webp'],
            ]);
            if (is_wp_error($uploaded_login_image_id)) {
                wp_die(esc_html($uploaded_login_image_id->get_error_message()), 'Não foi possível enviar a imagem do login', ['response' => 400, 'back_link' => true]);
            }
            $uploaded_login_image_id = absint($uploaded_login_image_id);
            $uploaded_login_image_url = $uploaded_login_image_id > 0
                ? wp_get_attachment_image_url($uploaded_login_image_id, 'full')
                : false;
            if (
                $uploaded_login_image_id <= 0
                || get_post_type($uploaded_login_image_id) !== 'attachment'
                || get_post_status($uploaded_login_image_id) === 'trash'
                || !in_array((string) get_post_mime_type($uploaded_login_image_id), array_values($allowed_login_image_mimes), true)
                || !is_string($uploaded_login_image_url)
                || $uploaded_login_image_url === ''
            ) {
                if ($uploaded_login_image_id > 0 && get_post_type($uploaded_login_image_id) === 'attachment') {
                    wp_delete_attachment($uploaded_login_image_id, true);
                }
                wp_die('Não foi possível validar a imagem enviada.', 'Não foi possível enviar a imagem do login', ['response' => 400, 'back_link' => true]);
            }
            update_post_meta($uploaded_login_image_id, '_kodety_login_image_bytes', $submitted_size);
            update_post_meta($uploaded_login_image_id, '_kodety_login_image_width', $image_width);
            update_post_meta($uploaded_login_image_id, '_kodety_login_image_height', $image_height);
            $next_login_image_id = $uploaded_login_image_id;
        }
        update_option('kodety_login_image_id', $next_login_image_id, false);
        $icon = isset($_POST['kodety_editor_corner_icon']) && is_string($_POST['kodety_editor_corner_icon'])
            ? sanitize_key(wp_unslash($_POST['kodety_editor_corner_icon']))
            : 'kodety-logo';
        if (!in_array($icon, ['kodety-logo', 'client-logo'], true)) $icon = 'kodety-logo';
        if ($icon === 'client-logo' && !$brand_logo_id) $icon = 'kodety-logo';
        update_option('kodety_editor_corner_icon', $icon, false);
        wp_safe_redirect(add_query_arg([
            'page' => $this->project_admin_page_slug(),
            'kodety_brand_updated' => '1',
        ], admin_url('admin.php')) . '#kodety-settings');
        exit;
    }

    public function save_optimization_settings(): void {
        if (!$this->can_publish()) wp_die('Você não tem permissão para alterar a publicação.', '', ['response' => 403]);
        check_admin_referer('kodety_save_optimizations', 'kodety_optimizations_nonce');
        $settings = Kodety_Publication_Optimizer::defaults();
        foreach (array_merge(['enabled'], array_keys(Kodety_Publication_Optimizer::options())) as $key) {
            $settings[$key] = isset($_POST['kodety_optimization_' . $key]);
        }
        $settings['exclusions'] = preg_split('/\R/', (string) wp_unslash($_POST['kodety_optimization_exclusions'] ?? '')) ?: [];
        try {
            $result = $this->persist_optimizations([
                'settings' => $settings,
                'expectedRevision' => (string) wp_unslash($_POST['kodety_optimization_revision'] ?? ''),
                'expectedRelease' => (string) wp_unslash($_POST['kodety_optimization_release'] ?? ''),
                'applyPublished' => ($_POST['kodety_optimization_operation'] ?? '') === 'apply',
            ]);
        } catch (Throwable $error) {
            $result = new WP_Error('kodety_optimization_save_failed', $error->getMessage());
        }
        $redirect = ['page' => $this->project_admin_page_slug()];
        if (is_wp_error($result)) $redirect['kodety_optimization_error'] = $result->get_error_message();
        else $redirect['kodety_optimizations_updated'] = !empty($result['appliedToPublished']) ? 'applied' : 'saved';
        wp_safe_redirect(add_query_arg($redirect, admin_url('admin.php')) . '#kodety-optimizations');
        exit;
    }

    public function admin_import(): void {
        if (!current_user_can('kodety_import') || !$this->can_publish()) {
            wp_die('Sem permissão para publicar o site.', '', ['response' => 403]);
        }
        check_admin_referer('kodety_import_zip');
        $import_revision = (int) get_option('kodety_workspace_revision', 0);
        $lock_error = $this->admin_import_editor_lock_error();
        if ($lock_error) $this->redirect_notice('error', $lock_error->get_error_message());
        $agency_mode = $this->workspace_mode() === 'agency';
        $agency_target = '';
        $target_has_project = $this->has_workspace();
        $target_project_name = trim((string) get_option('kodety_project_name', 'projeto atual'));
        if ($target_project_name === '') $target_project_name = 'projeto atual';

        if ($agency_mode) {
            try {
                if ($this->has_workspace() && $this->agency_active_project_id() === '') {
                    $this->agency_register_current_project();
                }
            } catch (Throwable $error) {
                $this->redirect_notice('error', $error->getMessage());
            }
            $projects = $this->agency_projects();
            $agency_target = sanitize_key((string) wp_unslash(
                $_POST['kodety_agency_import_target'] ?? $this->agency_active_project_id()
            ));
            if ($agency_target === '') {
                $agency_target = (string) array_key_first($projects);
            }
            if ($agency_target !== 'new-project' && !isset($projects[$agency_target])) {
                $this->redirect_notice('error', 'O projeto escolhido não existe mais. Selecione outro destino.');
            }
            $target_has_project = $agency_target !== 'new-project';
            if ($target_has_project) {
                $target_project_name = (string) $projects[$agency_target]['name'];
            }
        }

        if ($target_has_project) {
            $replacement_acknowledged = isset($_POST['kodety_replace_acknowledged'])
                && (string) wp_unslash($_POST['kodety_replace_acknowledged']) === '1';
            $replacement_phrase = isset($_POST['kodety_replace_phrase'])
                ? trim((string) wp_unslash($_POST['kodety_replace_phrase']))
                : '';
            if (!$replacement_acknowledged || !hash_equals('SUBSTITUIR', $replacement_phrase)) {
                $this->redirect_notice(
                    'error',
                    'A substituição de “' . $target_project_name
                    . '” foi cancelada. Confirme as perdas e digite SUBSTITUIR.'
                );
            }
        }
        if (empty($_FILES['kodety_zip']) || !is_array($_FILES['kodety_zip'])) $this->redirect_notice('error', 'Selecione um arquivo ZIP.');
        $file = $_FILES['kodety_zip'];
        $upload_error = (int) ($file['error'] ?? UPLOAD_ERR_NO_FILE);
        if ($upload_error !== UPLOAD_ERR_OK) {
            $upload_messages = [
                UPLOAD_ERR_INI_SIZE => 'O arquivo ultrapassa o limite configurado no servidor.',
                UPLOAD_ERR_FORM_SIZE => 'O arquivo ultrapassa o limite permitido para esta importação.',
                UPLOAD_ERR_PARTIAL => 'O upload foi interrompido antes de terminar. Tente novamente.',
                UPLOAD_ERR_NO_FILE => 'Selecione um arquivo ZIP.',
                UPLOAD_ERR_NO_TMP_DIR => 'O servidor não possui uma pasta temporária disponível.',
                UPLOAD_ERR_CANT_WRITE => 'O servidor não conseguiu gravar o arquivo temporário.',
                UPLOAD_ERR_EXTENSION => 'Uma extensão do servidor interrompeu o upload.',
            ];
            $this->redirect_notice('error', $upload_messages[$upload_error] ?? 'Não foi possível enviar o arquivo ZIP.');
        }
        if (empty($file['tmp_name'])) $this->redirect_notice('error', 'Selecione um arquivo ZIP.');
        try {
            $original_name = sanitize_file_name($file['name'] ?? 'site.zip') ?: 'site.zip';
            $shopify_theme_import = $this->zip_contains_shopify_theme((string) $file['tmp_name']);
            if ($agency_mode) {
                $new_project_name = isset($_POST['kodety_agency_new_project_name'])
                    ? substr(sanitize_text_field((string) wp_unslash($_POST['kodety_agency_new_project_name'])), 0, 120)
                    : '';
                $this->agency_stage_builder_import(
                    $agency_target,
                    (string) $file['tmp_name'],
                    $original_name,
                    $new_project_name
                );
            } else {
                $this->stage_builder_import((string) $file['tmp_name'], $original_name, false, $import_revision);
            }
            wp_safe_redirect(add_query_arg(
                $shopify_theme_import ? 'kodety_shopify_theme' : 'kodety_open_publish',
                '1',
                home_url('/kodety/editor/')
            ));
            exit;
        } catch (Throwable $error) {
            $this->redirect_notice('error', $error->getMessage());
        }
    }

    /**
     * Replace only the editable workspace during an administrative ZIP import.
     *
     * The Builder owns the JavaScript build (including Vite projects), so the
     * active release must remain untouched until the redirected editor has
     * loaded this workspace, produced kodety-build and published it normally.
     */
    private function stage_builder_import(
        string $zip_path,
        string $original_name,
        bool $reset_project_id = false,
        ?int $expected_revision = null,
        ?WP_REST_Request $request = null
    ): void {
        $expected_revision ??= (int) get_option('kodety_workspace_revision', 0);
        $actual_css_digest = $this->css_digest_from_zip($zip_path);
        $this->with_workspace_lock(function () use (
            $zip_path,
            $original_name,
            $actual_css_digest,
            $reset_project_id,
            $expected_revision,
            $request
        ): void {
            $this->assert_admin_import_workspace_revision($expected_revision, $request);
            $current_revision = (int) get_option('kodety_workspace_revision', 0);
            $workspace = $this->activate_workspace_from_zip($zip_path, $actual_css_digest, true);
            $workspace_digest = $this->css_digest_from_directory($workspace);
            $project_name = $this->project_name_from_directory($workspace);
            $project_id = $this->project_id_from_directory($workspace);

            update_option('kodety_original_name', $original_name, false);
            update_option('kodety_workspace_revision', $current_revision + 1, false);
            update_option('kodety_workspace_css_digest', $workspace_digest, false);
            update_option('kodety_draft_updated_at', current_time('c'), false);
            if ($project_name !== '') update_option('kodety_project_name', $project_name, false);
            if ($project_id !== '' || $reset_project_id) {
                // Elementor packages are intentionally portable and carry no
                // projectId. Clear their old association inside the same lock;
                // retain legacy behavior for every other staging caller.
                update_option('kodety_workspace_project_id', $project_id, false);
            }
            // The uploaded ZIP is already the editable transport the Builder
            // will request after the redirect. Cache those exact private bytes
            // under the new revision now instead of recompressing a large
            // workspace while the first canvas waits to open.
            try {
                $this->write_project_zip_cache_from_file(
                    $current_revision + 1,
                    $this->project_template_state_digest(),
                    $zip_path
                );
            } catch (Throwable) {
                // Cache generation is best effort; the canonical workspace is
                // already valid and download_project() can rebuild if needed.
            }
        });
    }

    /** Whether applying a template would replace an existing draft. */
    public function has_editable_workspace(): bool {
        return $this->has_workspace();
    }

    /**
     * Open a trusted library source as an editable draft without publishing it.
     * A source can be a flat project ZIP or a complete Onun Kodety project folder.
     */
    public function install_template_source(string $source, string $original_name, string $template_name = '', ?WP_REST_Request $request = null): void {
        if (!current_user_can('kodety_import') || !current_user_can(self::CAP_EDIT_WORKSPACE)) {
            throw new RuntimeException('Sem permissão para aplicar templates.');
        }
        $expected_revision = ($request ? $this->expected_workspace_revision($request) : null)
            ?? (int) get_option('kodety_workspace_revision', 0);
        $resolved = realpath($source);
        if (!is_string($resolved) || (!is_file($resolved) && !is_dir($resolved)) || is_link($source)) {
            throw new RuntimeException('Os arquivos deste template não estão disponíveis.');
        }
        $temporary = null;
        try {
            $zip_path = $resolved;
            if (is_dir($resolved)) {
                $temporary = $this->package_directory_as_zip($resolved, 'kodety-template-');
                $zip_path = $temporary;
            }
            $original_name = sanitize_file_name($original_name) ?: 'kodety-template.zip';
            if ($this->workspace_mode() === 'agency') {
                $target = $this->agency_active_project_id();
                $this->agency_stage_builder_import(
                    $target !== '' ? $target : 'new-project',
                    $zip_path,
                    $original_name,
                    $template_name
                );
            } else {
                $this->stage_builder_import($zip_path, $original_name, false, $expected_revision, $request);
            }
        } finally {
            if (is_string($temporary) && is_file($temporary)) @unlink($temporary);
        }
    }

    public function admin_download_project_backup(): void {
        if (!current_user_can('kodety_import')) wp_die('Sem permissão.', '', ['response' => 403]);
        $requested_project_id = sanitize_key((string) wp_unslash($_GET['project_id'] ?? ''));
        $bytes = false;
        $original_name = '';

        if ($this->workspace_mode() === 'agency' && $requested_project_id !== '') {
            check_admin_referer('kodety_download_project_backup_' . $requested_project_id);
            $projects = $this->agency_projects();
            if (!isset($projects[$requested_project_id])) {
                wp_die('O projeto escolhido não existe mais.', '', ['response' => 404, 'back_link' => true]);
            }
            try {
                $bytes = $this->with_workspace_lock(function () use ($requested_project_id, $projects): string {
                    if ($this->agency_active_project_id() === $requested_project_id) {
                        $this->agency_snapshot_current($requested_project_id);
                    }
                    $source = $this->agency_project_dir($requested_project_id);
                    if (!is_dir($source . '/workspace')) {
                        throw new RuntimeException('O snapshot deste projeto não está disponível.');
                    }
                    $manifest = is_file($source . '/template.json')
                        ? (string) file_get_contents($source . '/template.json')
                        : null;
                    $transport = $this->package_editable_workspace_as_zip(
                        $source . '/workspace',
                        'kodety-agency-backup-',
                        $manifest
                    );
                    try {
                        $contents = file_get_contents($transport);
                        if (!is_string($contents) || $contents === '') {
                            throw new RuntimeException('O backup foi gerado sem conteúdo.');
                        }
                        return $contents;
                    } finally {
                        if (is_file($transport)) @unlink($transport);
                    }
                });
                $original_name = sanitize_file_name((string) $projects[$requested_project_id]['originalName']);
            } catch (Throwable $error) {
                wp_die(
                    esc_html($error->getMessage()),
                    'Não foi possível gerar o backup',
                    ['response' => 500, 'back_link' => true]
                );
            }
        } else {
            check_admin_referer('kodety_download_project_backup');
            if (!$this->has_workspace()) {
                wp_die('Nenhum projeto está disponível para backup.', '', ['response' => 404, 'back_link' => true]);
            }
            $archive = $this->prepare_project_download_archive();
            if (is_wp_error($archive)) {
                $error_data = $archive->get_error_data();
                wp_die(esc_html($archive->get_error_message()), 'Não foi possível gerar o backup', [
                    'response' => is_array($error_data) ? (int) ($error_data['status'] ?? 500) : 500,
                    'back_link' => true,
                ]);
            }
            $original_name = sanitize_file_name((string) get_option('kodety_original_name', 'projeto.zip'));
            if ($original_name === '') $original_name = 'projeto.zip';
            if (!str_ends_with(strtolower($original_name), '.zip')) $original_name .= '.zip';
            $download_name = sanitize_file_name('backup-' . wp_date('Y-m-d-His') . '-' . $original_name);
            $this->stream_project_archive(
                (string) $archive['path'],
                $download_name,
                'attachment',
                (bool) $archive['temporary']
            );
        }

        if (!is_string($bytes) || $bytes === '') {
            wp_die('O backup foi gerado sem conteúdo.', 'Não foi possível gerar o backup', ['response' => 500, 'back_link' => true]);
        }

        if ($original_name === '') $original_name = 'projeto.zip';
        if (!str_ends_with(strtolower($original_name), '.zip')) $original_name .= '.zip';
        $download_name = sanitize_file_name('backup-' . wp_date('Y-m-d-His') . '-' . $original_name);

        while (ob_get_level() > 0) ob_end_clean();
        nocache_headers();
        header('Content-Type: application/zip');
        header('Content-Disposition: attachment; filename="' . str_replace('"', '', $download_name) . '"');
        header('Content-Length: ' . strlen($bytes));
        header('X-Content-Type-Options: nosniff');
        echo $bytes;
        exit;
    }

    public function admin_download_snapshot(): void {
        if (!current_user_can('manage_options')) wp_die('Sem permissão.', '', ['response' => 403]);
        $requested_release = wp_unslash($_GET['release'] ?? '');
        $release = is_string($requested_release) ? $this->release_id($requested_release) : '';
        if ($release === '' || $release !== $requested_release) {
            wp_die('O snapshot solicitado é inválido.', '', ['response' => 400, 'back_link' => true]);
        }
        check_admin_referer('kodety_download_snapshot_' . $release);
        $archive = $this->prepare_snapshot_download_archive($release);
        if (is_wp_error($archive)) {
            $data = $archive->get_error_data();
            wp_die(esc_html($archive->get_error_message()), 'Não foi possível baixar o snapshot', [
                'response' => is_array($data) ? (int) ($data['status'] ?? 500) : 500,
                'back_link' => true,
            ]);
        }
        $this->stream_project_archive($archive, 'snapshot-' . $release . '.zip', 'attachment', true);
    }

    /** Stream the editable ZIP to the authenticated Builder without wrapping
     * it in base64 JSON. A 75 MB ZIP otherwise becomes a 100+ MB REST payload
     * and can exhaust PHP/Chromium before the editor has a project to open. */
    public function admin_download_editor_project(): void {
        if (!current_user_can(self::CAP_EDIT_WORKSPACE)) {
            wp_die('Sem permissão para abrir este projeto.', '', ['response' => 403]);
        }
        check_admin_referer('kodety_download_editor_project');
        // Reloading the Builder used to package and stream the complete ZIP
        // before the browser could discover that its IndexedDB snapshot was
        // already the current workspace. Large sites paid for an unnecessary
        // filesystem walk, ZIP build, network transfer and client inflation on
        // every open. Validate the tiny revision + template contract first and
        // return a real conditional response without touching the archive.
        $known_revision_raw = isset($_SERVER['HTTP_X_KODETY_KNOWN_WORKSPACE_REVISION'])
            ? trim((string) wp_unslash($_SERVER['HTTP_X_KODETY_KNOWN_WORKSPACE_REVISION']))
            : '';
        $known_template_digest = isset($_SERVER['HTTP_X_KODETY_KNOWN_TEMPLATE_DIGEST'])
            ? strtolower(trim((string) wp_unslash($_SERVER['HTTP_X_KODETY_KNOWN_TEMPLATE_DIGEST'])))
            : '';
        if (
            $known_revision_raw !== ''
            && preg_match('/^\d+$/D', $known_revision_raw)
            && preg_match('/^[a-f0-9]{64}$/D', $known_template_digest)
            && $this->has_workspace()
        ) {
            try {
                $current_revision = (int) get_option('kodety_workspace_revision', 0);
                $current_template_digest = $this->project_template_state_digest();
                if (
                    (int) $known_revision_raw === $current_revision
                    && hash_equals($current_template_digest, $known_template_digest)
                ) {
                    while (ob_get_level() > 0) ob_end_clean();
                    status_header(304);
                    nocache_headers();
                    header('Content-Length: 0');
                    header('X-Content-Type-Options: nosniff');
                    header('X-Kodety-Workspace-Revision: ' . $current_revision);
                    header('X-Kodety-Template-Digest: ' . $current_template_digest);
                    header('X-Kodety-CSS-Digest: ' . str_replace(["\r", "\n"], '', (string) get_option('kodety_workspace_css_digest', '')));
                    exit;
                }
            } catch (Throwable $error) {
                // A conditional check is only an optimization. Fall through to
                // the canonical archive path so its existing error contract is
                // preserved when template metadata cannot be read.
            }
        }
        $archive = $this->prepare_project_download_archive();
        if (is_wp_error($archive)) {
            $data = $archive->get_error_data();
            wp_die(esc_html($archive->get_error_message()), 'Não foi possível abrir o projeto', [
                'response' => is_array($data) ? (int) ($data['status'] ?? 500) : 500,
                'back_link' => true,
            ]);
        }
        $metadata = $this->request_project_metadata();
        $receipt = $this->project_upload_receipt((int) $archive['revision']);
        $this->stream_project_archive(
            (string) $archive['path'],
            (string) $metadata['originalName'],
            'inline',
            (bool) $archive['temporary'],
            [
                'X-Kodety-Original-Name' => rawurlencode((string) $metadata['originalName']),
                'X-Kodety-Project-Name' => rawurlencode((string) $metadata['name']),
                'X-Kodety-Workspace-Revision' => (string) $archive['revision'],
                'X-Kodety-Received-Project-Digest' => (string) ($receipt['projectDigest'] ?? ''),
                'X-Kodety-Received-Project-Id' => (string) ($receipt['projectId'] ?? ''),
                'X-Kodety-Template-Digest' => (string) $archive['templateDigest'],
                'X-Kodety-CSS-Digest' => (string) get_option('kodety_workspace_css_digest', ''),
                'X-Kodety-Release' => rawurlencode((string) get_option('kodety_current_release', '')),
            ]
        );
    }

    /** Renew the long-lived Builder's REST credentials without reloading its
     * in-memory project. admin-ajax authenticates the WordPress cookie without
     * requiring the expired REST nonce that this endpoint replaces. */
    public function refresh_rest_session(): void {
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'A sessão do WordPress expirou.'], 401);
        }
        $can_open_kodety = current_user_can(self::CAP_EDIT_WORKSPACE)
            || current_user_can(self::CAP_ACCESS_CMS)
            || current_user_can(self::CAP_VIEW_ANALYTICS);
        if (!$can_open_kodety) {
            wp_send_json_error(['message' => 'Sem permissão para renovar esta sessão.'], 403);
        }
        nocache_headers();
        $project_download_url = current_user_can(self::CAP_EDIT_WORKSPACE)
            ? add_query_arg([
                'action' => 'kodety_download_editor_project',
                '_wpnonce' => wp_create_nonce('kodety_download_editor_project'),
            ], admin_url('admin-post.php'))
            : '';
        wp_send_json_success([
            'nonce' => wp_create_nonce('wp_rest'),
            'projectDownloadUrl' => $project_download_url,
        ]);
    }

    /** @param array<string,string> $extra_headers */
    private function stream_project_archive(
        string $path,
        string $download_name,
        string $disposition,
        bool $delete_after,
        array $extra_headers = []
    ): void {
        if (!is_file($path) || !is_readable($path)) {
            if ($delete_after && is_file($path)) @unlink($path);
            wp_die('O arquivo preparado não está disponível.', 'Não foi possível abrir o projeto', [
                'response' => 500,
                'back_link' => true,
            ]);
        }
        $size = (int) (@filesize($path) ?: 0);
        $download_name = sanitize_file_name($download_name) ?: 'projeto.zip';
        if (!str_ends_with(strtolower($download_name), '.zip')) $download_name .= '.zip';
        $disposition = $disposition === 'attachment' ? 'attachment' : 'inline';
        while (ob_get_level() > 0) ob_end_clean();
        nocache_headers();
        header('Content-Type: application/zip');
        header('Content-Disposition: ' . $disposition . '; filename="' . str_replace('"', '', $download_name) . '"');
        header('Content-Length: ' . $size);
        header('X-Content-Type-Options: nosniff');
        foreach ($extra_headers as $name => $value) {
            if (!preg_match('/^[A-Za-z0-9-]+$/D', $name)) continue;
            header($name . ': ' . str_replace(["\r", "\n"], '', $value));
        }
        $handle = @fopen($path, 'rb');
        if (!$handle) {
            if ($delete_after) @unlink($path);
            wp_die('O arquivo preparado não pôde ser lido.', 'Não foi possível abrir o projeto', [
                'response' => 500,
                'back_link' => true,
            ]);
        }
        fpassthru($handle);
        fclose($handle);
        if ($delete_after) @unlink($path);
        exit;
    }

    private function project_surface_relative_path(string $path): string {
        $normalized = ltrim(str_replace('\\', '/', trim($path)), '/');
        if (
            $normalized === ''
            || str_contains($normalized, "\0")
            || preg_match('/^[A-Za-z]:/', $normalized)
            || in_array('..', explode('/', $normalized), true)
        ) {
            throw new DomainException('O caminho solicitado é inválido.');
        }
        return $normalized;
    }

    private function project_surface_mime_type(string $path): string {
        $type = wp_check_filetype($path)['type'] ?? '';
        if (is_string($type) && $type !== '') return $type;
        return match (strtolower((string) pathinfo($path, PATHINFO_EXTENSION))) {
            'html', 'htm' => 'text/html',
            'json' => 'application/json',
            'css' => 'text/css',
            'js', 'mjs' => 'text/javascript',
            'svg' => 'image/svg+xml',
            'txt' => 'text/plain',
            default => 'application/octet-stream',
        };
    }

    private function project_surface_includes_file(string $surface, string $path): bool {
        if ($path === '.incode/project.json') return true;
        if (
            $surface === 'settings'
            && (
                $path === '.incode/framer-import.json'
                || $path === '.incode/url-import.json'
                || str_starts_with($path, '.incode/animations/') && str_ends_with(strtolower($path), '.json')
            )
        ) return true;
        // Variants, generated builds and renderer artifacts have their own
        // on-demand/full transports. Sending them in Overview/Settings can
        // multiply startup payloads without a single consumer using them.
        if (
            preg_match(
                '#(?:^|/)(?:\.incode|\.kodety-experiments|\.kodety-social|kodety-build)(?:/|$)#i',
                $path
            ) === 1
        ) return false;
        if (preg_match('/\.html?$/i', $path)) return true;
        if ($surface !== 'settings') return false;
        return preg_match('/\.(?:css|scss|sass|less)$/i', $path) === 1
            || $this->project_surface_is_lazy_asset($surface, $path);
    }

    /** Font paths are enough to build the Settings picker catalog. Their
     * bytes stay out of bootstrap and are fetched with revision CAS only after
     * an author actually selects a project font for a Social Image. */
    private function project_surface_is_lazy_asset(string $surface, string $path): bool {
        return $surface === 'settings'
            && preg_match('/\.(?:woff2?|ttf|otf)$/i', $path) === 1
            && preg_match('#(?:^|/)(?:\.incode|\.kodety-social)(?:/|$)#i', $path) !== 1;
    }

    /** @return list<string> */
    private function project_surface_candidate_paths(string $workspace_real, string $surface): array {
        $manifest_path = $workspace_real . '/.incode/preview-files.json';
        $manifest = null;
        $manifest_size = is_file($manifest_path) ? filesize($manifest_path) : false;
        if (is_int($manifest_size) && $manifest_size > 0 && $manifest_size <= 16 * 1024 * 1024) {
            $decoded = json_decode((string) file_get_contents($manifest_path), true);
            if (is_array($decoded)) $manifest = $decoded;
        }
        $manifest_candidates = ($manifest['version'] ?? null) === 3
            && ($manifest['generatedBy'] ?? '') === 'kodety-server'
            && is_array($manifest['surfacePaths'] ?? null)
                ? $manifest['surfacePaths']
                : null;
        $paths = [];
        $root_prefix = rtrim($workspace_real, '/\\') . DIRECTORY_SEPARATOR;
        if (is_array($manifest_candidates)) {
            foreach ($manifest_candidates as $candidate) {
                if (!is_string($candidate)) continue;
                try {
                    $relative = $this->project_surface_relative_path($candidate);
                } catch (Throwable) {
                    continue;
                }
                if (!$this->project_surface_includes_file($surface, $relative)) continue;
                $absolute = realpath($root_prefix . $relative);
                if (
                    !$absolute
                    || !str_starts_with($absolute, $root_prefix)
                    || !is_file($absolute)
                    || is_link($absolute)
                ) continue;
                $paths[$relative] = true;
                if (count($paths) > self::PROJECT_DELTA_MAX_OPERATIONS) {
                    throw new LengthException('Esta área possui arquivos textuais demais para o carregamento leve.');
                }
            }
            $resolved = array_keys($paths);
            sort($resolved, SORT_NATURAL | SORT_FLAG_CASE);
            return $resolved;
        }

        // Compatibility fallback for workspaces created before the indexed
        // preview manifest. Build the complete canonical index during this
        // unavoidable first traversal so every later panel request is O(paths)
        // in the small manifest rather than O(files) in the whole workspace.
        $manifest_paths = [];
        $manifest_surface_paths = [];
        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($workspace_real, FilesystemIterator::SKIP_DOTS),
            RecursiveIteratorIterator::LEAVES_ONLY
        );
        foreach ($iterator as $item) {
            if (!$item instanceof SplFileInfo || !$item->isFile() || $item->isLink()) continue;
            $relative = str_replace('\\', '/', substr($item->getPathname(), strlen($workspace_real) + 1));
            if ($relative === '.incode/preview-files.json') continue;
            if ($this->project_surface_includes_file('settings', $relative)) {
                $manifest_surface_paths[$relative] = true;
            }
            $key = $this->preview_path_key($relative);
            if ($key !== '') {
                if (isset($manifest_paths[$key]) && $manifest_paths[$key] !== $relative) {
                    $manifest_paths[$key] = null;
                } elseif (!array_key_exists($key, $manifest_paths)) {
                    $manifest_paths[$key] = $relative;
                }
            }
            if (!$this->project_surface_includes_file($surface, $relative)) continue;
            $paths[$relative] = true;
            if (count($paths) > self::PROJECT_DELTA_MAX_OPERATIONS) {
                throw new LengthException('Esta área possui arquivos textuais demais para o carregamento leve.');
            }
        }
        $this->persist_preview_file_manifest(
            $workspace_real,
            $manifest_paths,
            $manifest_surface_paths
        );
        $resolved = array_keys($paths);
        sort($resolved, SORT_NATURAL | SORT_FLAG_CASE);
        return $resolved;
    }

    /**
     * Return only the authored text required by Settings/Analytics. This avoids
     * packaging, transferring and inflating every image, font and video before
     * either workspace can paint its first useful screen.
     */
    public function project_surface(WP_REST_Request $request): WP_REST_Response|WP_Error {
        try {
            return $this->with_workspace_read_lock(
                fn(): WP_REST_Response|WP_Error => $this->project_surface_locked($request)
            );
        } catch (Throwable $error) {
            return new WP_Error(
                'kodety_project_surface_unavailable',
                $error->getMessage(),
                ['status' => 503, 'retryable' => true]
            );
        }
    }

    /** Analytics viewers must be able to inspect experiments and saved UTM
     * profiles without receiving the rest of the authoring metadata. */
    private function analytics_viewer_project_metadata(string $path): string {
        $size = is_file($path) ? filesize($path) : false;
        if (!is_int($size) || $size <= 0 || $size > 2 * 1024 * 1024 || !is_readable($path)) {
            return '{"version":1}';
        }
        $decoded = json_decode((string) file_get_contents($path), true);
        if (!is_array($decoded)) return '{"version":1}';
        $analytics = is_array($decoded['analytics'] ?? null) ? $decoded['analytics'] : [];
        $safe_analytics = [];
        foreach (['experiments', 'utmCenter', 'utms', 'utmCenterVersion'] as $key) {
            if (array_key_exists($key, $analytics)) $safe_analytics[$key] = $analytics[$key];
        }
        $safe = ['version' => 1];
        if ($safe_analytics !== []) $safe['analytics'] = $safe_analytics;
        if (is_array($decoded['utmCenter'] ?? null)) $safe['utmCenter'] = $decoded['utmCenter'];
        $encoded = wp_json_encode($safe, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        return is_string($encoded) && strlen($encoded) <= 2 * 1024 * 1024
            ? $encoded
            : '{"version":1}';
    }

    /** Read a single revision while holding the same filesystem lock used by
     * autosave/publish swaps. Otherwise a reader can observe workspace N+1
     * while the WordPress revision option still identifies it as N. */
    private function project_surface_locked(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $surface = sanitize_key((string) $request->get_param('surface'));
        if (!in_array($surface, ['settings', 'analytics'], true)) {
            return new WP_Error('kodety_project_surface_invalid', 'A área solicitada é inválida.', ['status' => 400]);
        }
        $workspace = $this->workspace_dir();
        $workspace_real = is_dir($workspace) ? realpath($workspace) : false;
        if (!is_string($workspace_real) || $workspace_real === '') {
            return new WP_Error('kodety_no_project', 'Nenhum projeto foi importado.', ['status' => 404]);
        }
        $project_root = $this->collapse_single_root($workspace_real);
        $project_root_real = realpath($project_root);
        if (!is_string($project_root_real) || $project_root_real === '') {
            return new WP_Error('kodety_no_project', 'O diretório do projeto não está disponível.', ['status' => 404]);
        }
        $include_source = current_user_can(self::CAP_EDIT_WORKSPACE);
        if ($include_source && $surface === 'analytics' && class_exists('Kodety_Sharing')) {
            $sharing = Kodety_Sharing::instance();
            $share_context = $sharing->context($request);
            // Read-only shares receive CAP_EDIT_WORKSPACE for GET routes so
            // the existing route map remains reusable. That transport grant
            // must never be mistaken for authoring permission here: Analytics
            // viewers only receive the explicitly sanitized metadata surface.
            if (is_array($share_context) && !$sharing->can_edit($request)) {
                $include_source = false;
            }
        }
        if (
            $surface === 'settings'
            && $include_source
            && (
                is_file($project_root_real . '/.incode/membership/runtime.json')
                || is_file($project_root_real . '/.incode/coded-build.json')
            )
        ) {
            // These projects have a distinct authoring graph: Membership keeps
            // editorHtml encrypted while the disk HTML is scrubbed, and coded
            // builds restore originals before editing. The full transport runs
            // those hydration passes and is the only lossless Settings source.
            $response = new WP_REST_Response([
                'success' => true,
                'requiresFullProject' => true,
                'workspaceRevision' => (int) get_option('kodety_workspace_revision', 0),
                'workspaceDigest' => (string) get_option('kodety_workspace_css_digest', ''),
                'templateDigest' => '',
            ]);
            $response->header('Cache-Control', 'private, no-store, no-cache, must-revalidate, max-age=0');
            $response->header('Pragma', 'no-cache');
            return $response;
        }
        $requested_revision = $request->get_param('revision');
        $current_revision = (int) get_option('kodety_workspace_revision', 0);
        if (
            (is_int($requested_revision) || is_string($requested_revision))
            && preg_match('/^\d+$/D', (string) $requested_revision)
            && (int) $requested_revision === $current_revision
        ) {
            $response = new WP_REST_Response([
                'success' => true,
                'notModified' => true,
                'workspaceRevision' => $current_revision,
                'workspaceDigest' => (string) get_option('kodety_workspace_css_digest', ''),
                'templateDigest' => '',
            ]);
            $response->header('Cache-Control', 'private, no-store, no-cache, must-revalidate, max-age=0');
            $response->header('Pragma', 'no-cache');
            return $response;
        }
        $last_error = null;
        for ($attempt = 0; $attempt < 2; $attempt++) {
            $revision = (int) get_option('kodety_workspace_revision', 0);
            $files = [];
            $total_bytes = 0;
            try {
                foreach ($this->project_surface_candidate_paths($project_root_real, $surface) as $relative) {
                    $absolute = $project_root_real . '/' . $relative;
                    if ($this->project_surface_is_lazy_asset($surface, $relative)) {
                        if (!$include_source) continue;
                        $files[$relative] = [
                            'path' => $relative,
                            'mimeType' => $this->project_surface_mime_type($relative),
                            'lazyAsset' => true,
                        ];
                        continue;
                    }
                    $viewer_metadata = !$include_source
                        && $surface === 'analytics'
                        && $relative === '.incode/project.json';
                    $contents = $include_source
                        ? file_get_contents($absolute)
                        : ($viewer_metadata ? $this->analytics_viewer_project_metadata($absolute) : '');
                    $size = $include_source ? filesize($absolute) : strlen((string) $contents);
                    if ($include_source && (!is_int($size) || $size < 0)) {
                        throw new RuntimeException('Um arquivo textual do projeto não pôde ser medido com segurança.');
                    }
                    if ($include_source && $total_bytes + $size > self::PROJECT_DELTA_MAX_BODY_BYTES) {
                        throw new LengthException('Os arquivos textuais desta área excedem o limite leve de 64 MB.');
                    }
                    if (!is_string($contents) || ($include_source && preg_match('//u', $contents) !== 1)) {
                        throw new RuntimeException('Um arquivo textual do projeto não pôde ser lido com segurança.');
                    }
                    $total_bytes += strlen($contents);
                    $files[$relative] = [
                        'path' => $relative,
                        'mimeType' => $this->project_surface_mime_type($relative),
                        'text' => $contents,
                    ];
                }
            } catch (Throwable $error) {
                $last_error = $error;
                break;
            }
            if ((int) get_option('kodety_workspace_revision', 0) !== $revision) continue;

            $metadata = [];
            if (isset($files['.incode/project.json']['text'])) {
                $decoded = json_decode((string) $files['.incode/project.json']['text'], true);
                if (is_array($decoded)) $metadata = $decoded;
            }
            $html_paths = array_values(array_filter(
                array_keys($files),
                static fn(string $path): bool => preg_match('/\.html?$/i', $path) === 1
            ));
            sort($html_paths, SORT_NATURAL | SORT_FLAG_CASE);
            $main_html_path = ltrim(str_replace('\\', '/', (string) (
                $metadata['homeHtmlPath'] ?? $metadata['mainHtmlPath'] ?? ''
            )), '/');
            if ($main_html_path === '' || !isset($files[$main_html_path])) {
                $main_html_path = '';
                foreach ($html_paths as $candidate) {
                    if (preg_match('#(?:^|/)index\.html?$#i', $candidate)) {
                        $main_html_path = $candidate;
                        break;
                    }
                }
                if ($main_html_path === '') $main_html_path = (string) ($html_paths[0] ?? '');
            }
            $request_metadata = $this->request_project_metadata();
            $response = new WP_REST_Response([
                'success' => true,
                'project' => [
                    'name' => (string) ($request_metadata['name'] ?: get_bloginfo('name')),
                    'rootPath' => ltrim(str_replace('\\', '/', (string) ($metadata['rootPath'] ?? '')), '/'),
                    'mainHtmlPath' => $main_html_path,
                    'files' => $files,
                ],
                'workspaceRevision' => $revision,
                'workspaceDigest' => (string) get_option('kodety_workspace_css_digest', ''),
                'templateDigest' => '',
            ]);
            $response->header('Cache-Control', 'private, no-store, no-cache, must-revalidate, max-age=0');
            $response->header('Pragma', 'no-cache');
            return $response;
        }
        if ($last_error instanceof LengthException) {
            return new WP_Error('kodety_project_surface_too_large', $last_error->getMessage(), ['status' => 413]);
        }
        return new WP_Error(
            'kodety_project_surface_unavailable',
            $last_error instanceof Throwable
                ? $last_error->getMessage()
                : 'O projeto mudou enquanto esta área era carregada. Tente novamente.',
            ['status' => $last_error ? 500 : 409]
        );
    }

    /** Read one binary only when a lightweight Settings feature actually uses it. */
    public function project_surface_asset(WP_REST_Request $request): WP_REST_Response|WP_Error {
        try {
            return $this->with_workspace_read_lock(
                fn(): WP_REST_Response|WP_Error => $this->project_surface_asset_locked($request)
            );
        } catch (Throwable $error) {
            return new WP_Error(
                'kodety_project_surface_asset_unavailable',
                $error->getMessage(),
                ['status' => 503, 'retryable' => true]
            );
        }
    }

    private function project_surface_asset_locked(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $requested_revision = $request->get_param('revision');
        if (
            !(is_int($requested_revision) || is_string($requested_revision))
            || !preg_match('/^\d+$/D', (string) $requested_revision)
        ) {
            return new WP_Error(
                'kodety_project_surface_asset_revision_required',
                'A revisão do asset não foi informada.',
                ['status' => 400]
            );
        }
        $revision = (int) get_option('kodety_workspace_revision', 0);
        if ((int) $requested_revision !== $revision) {
            return new WP_Error(
                'kodety_project_surface_asset_conflict',
                'O projeto mudou antes de carregar este asset.',
                ['status' => 409, 'currentRevision' => $revision]
            );
        }
        try {
            $relative = $this->project_surface_relative_path((string) $request->get_param('path'));
        } catch (Throwable $error) {
            return new WP_Error('kodety_project_surface_asset_invalid', $error->getMessage(), ['status' => 400]);
        }
        $workspace = $this->workspace_dir();
        $workspace_real = is_dir($workspace) ? realpath($workspace) : false;
        $project_root_real = is_string($workspace_real)
            ? realpath($this->collapse_single_root($workspace_real))
            : false;
        $absolute = is_string($project_root_real) ? realpath($project_root_real . '/' . $relative) : false;
        if (
            !is_string($project_root_real)
            || !is_string($absolute)
            || !str_starts_with($absolute, $project_root_real . DIRECTORY_SEPARATOR)
            || !is_file($absolute)
            || is_link($absolute)
        ) {
            return new WP_Error('kodety_project_surface_asset_missing', 'O asset solicitado não existe.', ['status' => 404]);
        }
        $size = (int) (@filesize($absolute) ?: 0);
        if ($size < 1 || $size > self::PROJECT_SURFACE_ASSET_MAX_BYTES) {
            return new WP_Error('kodety_project_surface_asset_too_large', 'O asset solicitado excede o limite seguro.', ['status' => 413]);
        }
        $bytes = file_get_contents($absolute);
        if (!is_string($bytes) || strlen($bytes) !== $size) {
            return new WP_Error('kodety_project_surface_asset_failed', 'O asset solicitado não pôde ser lido.', ['status' => 500]);
        }
        $confirmed_revision = (int) get_option('kodety_workspace_revision', 0);
        if ($confirmed_revision !== $revision) {
            return new WP_Error(
                'kodety_project_surface_asset_conflict',
                'O projeto mudou enquanto este asset era carregado.',
                ['status' => 409, 'currentRevision' => $confirmed_revision]
            );
        }
        $response = new WP_REST_Response([
            'path' => $relative,
            'mimeType' => $this->project_surface_mime_type($relative),
            'data' => base64_encode($bytes),
            'workspaceRevision' => $revision,
        ]);
        $response->header('Cache-Control', 'private, no-store, no-cache, must-revalidate, max-age=0');
        return $response;
    }

    public function download_project(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $archive = $this->prepare_project_download_archive();
        if (is_wp_error($archive)) return $archive;
        try {
            $bytes = file_get_contents((string) $archive['path']);
            if (!is_string($bytes) || $bytes === '') {
                return new WP_Error('kodety_project_download_failed', 'Não foi possível ler o ZIP do projeto.', ['status' => 500]);
            }
            return $this->project_download_response(
                $bytes,
                (int) $archive['revision'],
                (string) $archive['templateDigest']
            );
        } finally {
            if (!empty($archive['temporary']) && is_file((string) $archive['path'])) {
                @unlink((string) $archive['path']);
            }
        }
    }

    /**
     * Prepare one revision-keyed ZIP path without loading the archive into PHP
     * memory. The legacy REST response may still read it for compatibility;
     * the Builder and backup paths stream it directly.
     *
     * @return array{path:string,temporary:bool,revision:int,templateDigest:string}|WP_Error
     */
    private function prepare_project_download_archive(): array|WP_Error {
        try {
            if (is_file($this->project_delta_journal_path())) {
                $this->with_workspace_lock(static fn(): bool => true);
            }
        } catch (Throwable $error) {
            return new WP_Error('kodety_project_delta_recovery_failed', $error->getMessage(), ['status' => 503]);
        }
        $workspace = $this->workspace_dir();
        if (!is_dir($workspace)) {
            return new WP_Error('kodety_no_project', 'Nenhum projeto foi importado.', ['status' => 404]);
        }
        try {
            $template_digest = $this->project_template_state_digest();
            $revision = (int) get_option('kodety_workspace_revision', 0);
            $cached_path = $this->project_zip_cache_path($revision, $template_digest);
            if (
                is_file($cached_path)
                && is_readable($cached_path)
                && (int) (@filesize($cached_path) ?: 0) > 0
                && hash_equals($template_digest, $this->project_template_state_digest())
            ) {
                return [
                    'path' => $cached_path,
                    'temporary' => false,
                    'revision' => $revision,
                    'templateDigest' => $template_digest,
                ];
            }

            return $this->with_workspace_lock(function () use ($workspace): array|WP_Error {
                if (!is_dir($workspace)) {
                    return new WP_Error('kodety_no_project', 'Nenhum projeto foi importado.', ['status' => 404]);
                }
                $transport = null;
                $keep_transport = false;
                try {
                    $this->repair_component_studio_directory($workspace);
                    $template_manifest = $this->project_template_manifest_json();
                    $template_digest = hash('sha256', $template_manifest);
                    $revision = (int) get_option('kodety_workspace_revision', 0);
                    $cached_path = $this->project_zip_cache_path($revision, $template_digest);
                    if (is_file($cached_path) && is_readable($cached_path) && (int) (@filesize($cached_path) ?: 0) > 0) {
                        return [
                            'path' => $cached_path,
                            'temporary' => false,
                            'revision' => $revision,
                            'templateDigest' => $template_digest,
                        ];
                    }
                    $transport = $this->package_editable_workspace_as_zip(
                        $workspace,
                        'kodety-project-',
                        $template_manifest
                    );
                    $this->write_project_zip_cache_from_file($revision, $template_digest, $transport);
                    if (is_file($cached_path) && is_readable($cached_path) && (int) (@filesize($cached_path) ?: 0) > 0) {
                        return [
                            'path' => $cached_path,
                            'temporary' => false,
                            'revision' => $revision,
                            'templateDigest' => $template_digest,
                        ];
                    }
                    $keep_transport = true;
                    return [
                        'path' => $transport,
                        'temporary' => true,
                        'revision' => $revision,
                        'templateDigest' => $template_digest,
                    ];
                } finally {
                    if (!$keep_transport && is_string($transport) && is_file($transport)) @unlink($transport);
                }
            });
        } catch (Throwable $error) {
            return new WP_Error('kodety_project_template_export_failed', $error->getMessage(), ['status' => 500]);
        }
    }

    /**
     * Build the project-download REST response from raw ZIP bytes. Metadata is
     * read from options, so both the fresh-build and cache-hit paths return an
     * identical contract.
     */
    private function project_download_response(string $bytes, int $revision, string $template_digest): WP_REST_Response {
        $metadata = $this->request_project_metadata();
        $receipt = $this->project_upload_receipt($revision);
        $response = new WP_REST_Response([
            // The Builder exchanges one binary payload, built on demand from
            // native files; no ZIP remains as authoritative server-side state.
            'data' => base64_encode($bytes),
            'name' => $metadata['originalName'],
            // The transport filename is not the workspace identity. Expose it
            // separately so the Builder survives a publish/reload cycle even when
            // a host normalizes uploads to kodety-editor.zip.
            'projectName' => $metadata['name'],
            'release' => (string) get_option('kodety_current_release', ''),
            'workspaceRevision' => $revision,
            'receivedProjectDigest' => (string) ($receipt['projectDigest'] ?? ''),
            'receivedProjectId' => (string) ($receipt['projectId'] ?? ''),
            'templateDigest' => $template_digest,
            'cssDigest' => (string) get_option('kodety_workspace_css_digest', ''),
        ]);
        // The editable workspace is user-private state. Some managed WordPress
        // hosts cache REST GETs unless this is explicit, which used to make a
        // reload silently reopen the project from before the last publish.
        $response->header('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0');
        $response->header('Pragma', 'no-cache');
        $response->header('Expires', '0');
        return $response;
    }

    /** The download adds server-owned manifests and may decrypt transport
     * artifacts. Preserve the exact accepted ZIP digest separately; it proves
     * a lost ACK only while both the archived and live revisions still match. */
    private function project_upload_receipt(int $archive_revision): ?array {
        $receipt = get_option('kodety_workspace_upload_receipt', null);
        if (
            !is_array($receipt)
            || !is_int($receipt['workspaceRevision'] ?? null)
            || $receipt['workspaceRevision'] !== $archive_revision
            || $archive_revision !== (int) get_option('kodety_workspace_revision', 0)
            || !is_string($receipt['projectId'] ?? null)
            || $receipt['projectId'] === ''
            || $receipt['projectId'] !== (string) get_option('kodety_workspace_project_id', '')
            || !is_string($receipt['projectDigest'] ?? null)
            || !preg_match('/^[a-f0-9]{64}$/D', $receipt['projectDigest'])
        ) return null;
        return $receipt;
    }

    private function project_cache_dir(): string {
        return $this->private_storage_dir() . '/cache';
    }

    private function project_zip_cache_path(int $revision, string $template_digest): string {
        $template_digest = preg_match('/^[a-f0-9]{64}$/', $template_digest)
            ? substr($template_digest, 0, 16)
            : 'legacy';
        $scope = $this->workspace_mode() === 'agency'
            ? ($this->shared_project_id() ?: $this->agency_active_project_id())
            : 'single';
        $scope = sanitize_key($scope) ?: 'single';
        return $this->project_cache_dir()
            . '/project-'
            . $scope
            . '-r'
            . $revision
            . '-t'
            . $template_digest
            . '.zip';
    }

    /** Best-effort read of a cached project package for a workspace revision. */
    private function read_project_zip_cache(int $revision, string $template_digest): ?string {
        $path = $this->project_zip_cache_path($revision, $template_digest);
        if (!is_file($path)) return null;
        $bytes = file_get_contents($path);
        return is_string($bytes) && $bytes !== '' ? $bytes : null;
    }

    /**
     * Cache a freshly built package and prune archives from other revisions.
     * Purely an optimization: any failure leaves the download working, just
     * without the cache. Stale-revision files are never read (different key).
     */
    private function write_project_zip_cache(
        int $revision,
        string $template_digest,
        string $bytes
    ): void {
        if ($bytes === '') return;
        $dir = $this->project_cache_dir();
        if (!is_dir($dir) && !wp_mkdir_p($dir)) return;
        // The cache lives under private storage; add an index guard in case the
        // host serves the uploads directory listing.
        $guard = $dir . '/index.php';
        if (!is_file($guard)) @file_put_contents($guard, "<?php // Silence is golden.\n");
        $target = $this->project_zip_cache_path($revision, $template_digest);
        $temporary = $target . '.tmp-' . getmypid();
        if (@file_put_contents($temporary, $bytes) === false) { @unlink($temporary); return; }
        $this->activate_project_zip_cache_file($temporary, $target);
    }

    /**
     * Cache an existing editable transport without reading the complete ZIP
     * into PHP memory. Autosave and wp-admin import already produced these
     * bytes, so copying them makes the next Builder opening a direct cache hit.
     */
    private function write_project_zip_cache_from_file(
        int $revision,
        string $template_digest,
        string $source,
        ?string $template_manifest = null
    ): void {
        if (!is_file($source) || !is_readable($source) || filesize($source) <= 0) return;
        $dir = $this->project_cache_dir();
        if (!is_dir($dir) && !wp_mkdir_p($dir)) return;
        $guard = $dir . '/index.php';
        if (!is_file($guard)) @file_put_contents($guard, "<?php // Silence is golden.\n");
        $target = $this->project_zip_cache_path($revision, $template_digest);
        $temporary = $target . '.tmp-' . getmypid();
        @unlink($temporary);
        $template_matches = $template_manifest === null;
        if ($template_manifest !== null) {
            if (
                !hash_equals($template_digest, hash('sha256', $template_manifest))
                || !class_exists('ZipArchive')
            ) {
                return;
            }
            $source_zip = new ZipArchive();
            if ($source_zip->open($source) === true) {
                $existing_manifest = $source_zip->getFromName(self::PROJECT_TEMPLATE_MANIFEST);
                $template_matches = is_string($existing_manifest)
                    && hash_equals($template_manifest, $existing_manifest);
                $source_zip->close();
            }
        }
        // Upload staging and the private cache share a filesystem in normal
        // installations. A hard link keeps the acknowledged ZIP without a
        // second full disk write; unlinking the upload path afterwards leaves
        // the cache inode intact.
        if ($template_matches && function_exists('link') && @link($source, $temporary)) {
            $this->activate_project_zip_cache_file($temporary, $target);
            return;
        }
        $source_size = (int) (@filesize($source) ?: 0);
        if ($source_size > self::PROJECT_ZIP_CACHE_COPY_MAX_BYTES) return;
        if (!@copy($source, $temporary)) { @unlink($temporary); return; }
        if ($template_manifest !== null && !$template_matches) {
            $zip = new ZipArchive();
            if ($zip->open($temporary) !== true) { @unlink($temporary); return; }
            $updated = $zip->addFromString(self::PROJECT_TEMPLATE_MANIFEST, $template_manifest);
            $zip->close();
            if (!$updated) { @unlink($temporary); return; }
        }
        $this->activate_project_zip_cache_file($temporary, $target);
    }

    /** Atomically expose one complete cache file, then prune older revisions. */
    private function activate_project_zip_cache_file(string $temporary, string $target): void {
        if (!@rename($temporary, $target)) { @unlink($temporary); return; }
        $dir = dirname($target);
        foreach ((array) glob($dir . '/project-*-r*.zip') as $file) {
            if (is_string($file) && $file !== $target) @unlink($file);
        }
    }

    /** SHA-256 over the sorted SHA-256 values of all CSS and HTML payloads.
     * HTML is included because visual edits can legitimately persist as inline
     * style declarations. Paths are
     * intentionally excluded so ZIPs wrapped in a single folder validate just
     * like the same project exported at the archive root. */
    private function css_digest_from_zip(string $zip_path): string {
        if (!class_exists('ZipArchive')) throw new RuntimeException('A extensão PHP ZipArchive precisa estar habilitada na hospedagem.');
        $zip = new ZipArchive();
        if ($zip->open($zip_path) !== true) throw new RuntimeException('O projeto recebido não é um ZIP válido.');
        $digests = [];
        try {
            for ($index = 0; $index < $zip->numFiles; $index++) {
                $name = str_replace('\\', '/', (string) $zip->getNameIndex($index));
                $segments = array_values(array_filter(explode('/', $name), static fn(string $part): bool => $part !== ''));
                if (in_array('__MACOSX', $segments, true) || str_starts_with(basename($name), '._')) continue;
                if (!preg_match('/\.(?:css|html?)$/i', $name)) continue;
                $contents = $zip->getFromIndex($index);
                if (!is_string($contents)) throw new RuntimeException('Não foi possível ler um arquivo CSS do ZIP.');
                $digests[] = hash('sha256', $contents);
            }
        } finally {
            $zip->close();
        }
        sort($digests, SORT_STRING);
        return hash('sha256', implode("\0", $digests));
    }

    /** The isolated component canvas is generated UI and can never be a site
     * page. Older editor builds could accidentally save it as index.html. */
    private function zip_contains_component_studio(string $zip_path): bool {
        if (!class_exists('ZipArchive')) throw new RuntimeException('A extensão PHP ZipArchive precisa estar habilitada na hospedagem.');
        $zip = new ZipArchive();
        if ($zip->open($zip_path) !== true) throw new RuntimeException('O workspace não é um ZIP válido.');
        try {
            for ($index = 0; $index < $zip->numFiles; $index++) {
                $name = (string) $zip->getNameIndex($index);
                if (!preg_match('/\.html?$/i', $name)) continue;
                $html = $zip->getFromIndex($index);
                if (is_string($html) && str_contains($html, 'data-kodety-component-studio')) return true;
            }
            return false;
        } finally {
            $zip->close();
        }
    }

    private function zip_main_html_path(string $zip_path): string {
        $zip = new ZipArchive();
        if ($zip->open($zip_path) !== true) return '';
        try {
            for ($index = 0; $index < $zip->numFiles; $index++) {
                $name = str_replace('\\', '/', (string) $zip->getNameIndex($index));
                if (!str_ends_with($name, '.incode/project.json')) continue;
                $metadata = json_decode((string) $zip->getFromIndex($index), true);
                return is_array($metadata) ? (string) ($metadata['mainHtmlPath'] ?? '') : '';
            }
            return '';
        } finally {
            $zip->close();
        }
    }

    private function latest_healthy_workspace(string $main_html_path): string {
        $directories = glob($this->releases_dir() . '/*', GLOB_ONLYDIR) ?: [];
        rsort($directories, SORT_STRING);
        foreach ($directories as $directory) {
            $candidate = $directory . '/project.zip';
            if (!is_file($candidate) || $this->zip_contains_component_studio($candidate)) continue;
            if ($main_html_path !== '' && $this->zip_main_html_path($candidate) !== $main_html_path) continue;
            return $candidate;
        }
        return '';
    }

    /** Restores only corrupted HTML entries from the newest healthy release
     * of the same project. CSS, assets and current component metadata survive. */
    private function repair_component_studio_workspace(string $workspace): bool {
        if (!$this->zip_contains_component_studio($workspace)) return false;
        $fallback = $this->latest_healthy_workspace($this->zip_main_html_path($workspace));
        if ($fallback === '') {
            throw new RuntimeException('O workspace contém um canvas temporário no lugar da página e não há release saudável compatível para recuperar.');
        }
        $temporary = tempnam($this->private_storage_dir(), 'kodety-repair-');
        if (!$temporary || !copy($workspace, $temporary)) throw new RuntimeException('Não foi possível preparar a recuperação do workspace.');
        $current = new ZipArchive();
        $healthy = new ZipArchive();
        try {
            if ($current->open($temporary) !== true || $healthy->open($fallback) !== true) {
                throw new RuntimeException('Não foi possível abrir a release de recuperação.');
            }
            $replaced = 0;
            $names = [];
            for ($index = 0; $index < $current->numFiles; $index++) {
                $name = (string) $current->getNameIndex($index);
                if (!preg_match('/\.html?$/i', $name)) continue;
                $html = $current->getFromIndex($index);
                if (is_string($html) && str_contains($html, 'data-kodety-component-studio')) $names[] = $name;
            }
            foreach ($names as $name) {
                $healthy_html = $healthy->getFromName($name);
                if (!is_string($healthy_html)) continue;
                $current->deleteName($name);
                $current->addFromString($name, $healthy_html);
                $replaced++;
            }
            if ($replaced === 0) throw new RuntimeException('A release saudável não contém a página necessária para recuperar o workspace.');
        } finally {
            $current->close();
            $healthy->close();
        }
        if ($this->zip_contains_component_studio($temporary)) {
            @unlink($temporary);
            throw new RuntimeException('A recuperação não conseguiu remover o canvas temporário da página.');
        }
        if (!rename($temporary, $workspace)) {
            @unlink($temporary);
            throw new RuntimeException('Não foi possível ativar o workspace recuperado.');
        }
        update_option('kodety_workspace_revision', (int) get_option('kodety_workspace_revision', 0) + 1, false);
        update_option('kodety_workspace_css_digest', $this->css_digest_from_zip($workspace), false);
        update_option('kodety_draft_updated_at', current_time('c'), false);
        return true;
    }

    private function css_digest_from_directory(
        string $directory,
        bool $include_private = true,
        array $excluded_relative_paths = []
    ): string {
        $digests = [];
        $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($directory, FilesystemIterator::SKIP_DOTS));
        foreach ($iterator as $file) {
            if (!$file->isFile() || $file->isLink() || !in_array(strtolower($file->getExtension()), ['css', 'html', 'htm'], true)) continue;
            if (!$include_private || $excluded_relative_paths) {
                $relative = ltrim(str_replace('\\', '/', substr(
                    $file->getPathname(),
                    strlen(rtrim($directory, '/\\'))
                )), '/');
                if (
                    (!$include_private && preg_match('~(?:^|/)\.incode(?:/|$)~', $relative))
                    || isset($excluded_relative_paths[$relative])
                ) continue;
            }
            $contents = file_get_contents($file->getPathname());
            if (!is_string($contents)) throw new RuntimeException('Não foi possível validar um arquivo CSS preparado para publicação.');
            $digests[] = hash('sha256', $contents);
        }
        sort($digests, SORT_STRING);
        return hash('sha256', implode("\0", $digests));
    }

    /** SHA-256 over every project path, byte length and payload hash. Unlike
     * the visual CSS/HTML digest, this attests JS, JSON, media and metadata too. */
    private function project_digest_from_directory(string $directory): string {
        $root = realpath($directory);
        if (!$root || !is_dir($root)) throw new RuntimeException('A árvore do projeto não está disponível.');
        $records = [];
        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($root, FilesystemIterator::SKIP_DOTS)
        );
        foreach ($iterator as $file) {
            if ($file->isLink()) throw new RuntimeException('A árvore do projeto contém um link simbólico.');
            if (!$file->isFile()) continue;
            $relative = ltrim(str_replace('\\', '/', substr($file->getPathname(), strlen($root))), '/');
            $size = $file->getSize();
            $digest = hash_file('sha256', $file->getPathname());
            if ($relative === '' || $size < 0 || !is_string($digest)) {
                throw new RuntimeException('Um arquivo do projeto não pôde ser validado.');
            }
            $records[] = hash('sha256', $relative) . "\0" . $size . "\0" . $digest;
        }
        sort($records, SORT_STRING);
        return hash('sha256', implode("\0", $records));
    }

    /** Compute the same complete graph digest directly from an incoming ZIP.
     * Duplicate/case-colliding entries are rejected because extraction would
     * otherwise make their winning payload host-dependent. */
    private function project_digest_from_zip(string $zip_path): string {
        if (!class_exists('ZipArchive')) throw new RuntimeException('A extensão PHP ZipArchive precisa estar habilitada na hospedagem.');
        $zip = new ZipArchive();
        if ($zip->open($zip_path) !== true) throw new RuntimeException('O projeto recebido não é um ZIP válido.');
        $records = [];
        $seen = [];
        try {
            for ($index = 0; $index < $zip->numFiles; $index++) {
                $stat = $zip->statIndex($index);
                $archive_name = (string) ($stat['name'] ?? '');
                $name = str_replace('\\', '/', $archive_name);
                $normalized = ltrim($name, '/');
                if ($normalized === '' || str_ends_with($normalized, '/')) continue;
                $folded = $this->project_delta_casefold_path($normalized);
                if (isset($seen[$folded])) {
                    throw new RuntimeException('O ZIP contém caminhos de arquivo duplicados ou incompatíveis.');
                }
                $seen[$folded] = true;
                $stream = $zip->getStream($archive_name);
                if (!is_resource($stream)) throw new RuntimeException('Um arquivo do ZIP não pôde ser lido.');
                try {
                    $context = hash_init('sha256');
                    $bytes = hash_update_stream($context, $stream);
                    if (!is_int($bytes) || $bytes < 0) throw new RuntimeException('Um arquivo do ZIP ficou incompleto.');
                    $digest = hash_final($context);
                } finally {
                    fclose($stream);
                }
                $size = (int) ($stat['size'] ?? -1);
                if ($size < 0 || $bytes !== $size) throw new RuntimeException('Um arquivo do ZIP ficou incompleto.');
                $records[] = hash('sha256', $normalized) . "\0" . $size . "\0" . $digest;
            }
        } finally {
            $zip->close();
        }
        sort($records, SORT_STRING);
        return hash('sha256', implode("\0", $records));
    }

    private function expected_workspace_revision(WP_REST_Request $request): ?int {
        $raw = trim((string) $request->get_header('x-kodety-expected-revision'));
        return $raw !== '' && ctype_digit($raw) ? (int) $raw : null;
    }

    private function expected_css_digest(WP_REST_Request $request): ?string {
        $digest = strtolower(trim((string) $request->get_header('x-kodety-css-digest')));
        return preg_match('/^[a-f0-9]{64}$/', $digest) ? $digest : null;
    }

    private function expected_project_digest(WP_REST_Request $request): ?string {
        $digest = strtolower(trim((string) $request->get_header('x-kodety-project-digest')));
        return preg_match('/^[a-f0-9]{64}$/', $digest) ? $digest : null;
    }

    private function publish_request_id(WP_REST_Request $request): string {
        $request_id = trim((string) $request->get_header('x-kodety-publish-request-id'));
        return preg_match('/^[A-Za-z0-9_-]{16,128}$/D', $request_id) ? $request_id : '';
    }

    private function publish_receipt(string $request_id, string $fingerprint): ?array {
        if ($request_id === '' || $fingerprint === '') return null;
        $receipts = get_option(self::PUBLISH_RECEIPTS_OPTION, []);
        $receipt = is_array($receipts) && is_array($receipts[$request_id] ?? null)
            ? $receipts[$request_id]
            : null;
        if (
            !$receipt
            || !hash_equals($fingerprint, (string) ($receipt['fingerprint'] ?? ''))
            || time() - (int) ($receipt['createdAt'] ?? 0) > DAY_IN_SECONDS
            || !is_array($receipt['result'] ?? null)
        ) return null;
        $result = $receipt['result'];
        $release = (string) ($result['release'] ?? '');
        $current_release = (string) get_option('kodety_current_release', '');
        if ($release === '' || $current_release === '' || !hash_equals($release, $current_release)) {
            return null;
        }
        $theme_stylesheet = (string) ($result['theme_stylesheet'] ?? '');
        if ($theme_stylesheet !== '' && !hash_equals($theme_stylesheet, (string) wp_get_theme()->get_stylesheet())) {
            return null;
        }
        return $result;
    }

    private function remember_publish_receipt(string $request_id, string $fingerprint, array $result): void {
        if ($request_id === '' || $fingerprint === '') return;
        $receipts = get_option(self::PUBLISH_RECEIPTS_OPTION, []);
        if (!is_array($receipts)) $receipts = [];
        $cutoff = time() - DAY_IN_SECONDS;
        $receipts = array_filter(
            $receipts,
            static fn(mixed $receipt): bool => is_array($receipt)
                && (int) ($receipt['createdAt'] ?? 0) >= $cutoff
        );
        $receipts[$request_id] = [
            'createdAt' => time(),
            'fingerprint' => $fingerprint,
            'result' => $result,
        ];
        if (count($receipts) > self::PUBLISH_RECEIPT_LIMIT) {
            $receipts = array_slice($receipts, -self::PUBLISH_RECEIPT_LIMIT, null, true);
        }
        update_option(self::PUBLISH_RECEIPTS_OPTION, $receipts, false);
    }

    /** Return an acknowledged delta result before checking CAS. A browser can
     * lose the HTTP response after the filesystem swap has committed; replaying
     * the same request ID must return that ACK instead of reporting a false
     * revision conflict. Reusing an ID for different bytes fails closed. */
    private function project_delta_receipt_key(string $workspace_locator, string $request_id): string {
        return hash('sha256', $workspace_locator . "\0" . $request_id);
    }

    private function project_delta_receipt(
        string $request_id,
        string $fingerprint,
        string $workspace_locator
    ): array|WP_Error|null {
        if ($request_id === '' || $fingerprint === '' || $workspace_locator === '') return null;
        $receipts = get_option(self::PROJECT_DELTA_RECEIPTS_OPTION, []);
        $receipt_key = $this->project_delta_receipt_key($workspace_locator, $request_id);
        $receipt = is_array($receipts) && is_array($receipts[$receipt_key] ?? null)
            ? $receipts[$receipt_key]
            : null;
        if (!$receipt || time() - (int) ($receipt['createdAt'] ?? 0) > DAY_IN_SECONDS) return null;
        if (
            !hash_equals((string) ($receipt['workspaceLocator'] ?? ''), $workspace_locator)
            || !hash_equals((string) ($receipt['requestId'] ?? ''), $request_id)
        ) return null;
        if (!hash_equals((string) ($receipt['fingerprint'] ?? ''), $fingerprint)) {
            return new WP_Error(
                'kodety_project_delta_request_conflict',
                'Este identificador de autosave já foi usado por outro conteúdo.',
                ['status' => 409]
            );
        }
        return is_array($receipt['result'] ?? null) ? $receipt['result'] : null;
    }

    /** Persist a small idempotency receipt and prove it is readable before the
     * old workspace backup is discarded. */
    private function remember_project_delta_receipt(
        string $request_id,
        string $fingerprint,
        string $workspace_locator,
        array $result
    ): bool {
        if ($request_id === '' || $fingerprint === '' || $workspace_locator === '') return false;
        $receipts = get_option(self::PROJECT_DELTA_RECEIPTS_OPTION, []);
        if (!is_array($receipts)) $receipts = [];
        $cutoff = time() - DAY_IN_SECONDS;
        $receipts = array_filter(
            $receipts,
            static fn(mixed $receipt): bool => is_array($receipt)
                && (int) ($receipt['createdAt'] ?? 0) >= $cutoff
        );
        $receipt_key = $this->project_delta_receipt_key($workspace_locator, $request_id);
        $receipts[$receipt_key] = [
            'createdAt' => time(),
            'workspaceLocator' => $workspace_locator,
            'requestId' => $request_id,
            'fingerprint' => $fingerprint,
            'result' => $result,
        ];
        if (count($receipts) > self::PROJECT_DELTA_RECEIPT_LIMIT) {
            $receipts = array_slice($receipts, -self::PROJECT_DELTA_RECEIPT_LIMIT, null, true);
        }
        update_option(self::PROJECT_DELTA_RECEIPTS_OPTION, $receipts, false);
        $confirmed = $this->project_delta_receipt($request_id, $fingerprint, $workspace_locator);
        return is_array($confirmed) && $confirmed === $result;
    }

    private function project_delta_workspace_from_locator(string $locator): string {
        if ($locator === 'workspace') return $this->private_storage_dir() . '/workspace';
        if (!preg_match('~^agency/([a-z0-9_-]{1,191})/workspace$~D', $locator, $match)) {
            throw new RuntimeException('O journal incremental contém um locator de workspace inválido.');
        }
        $project_id = (string) $match[1];
        if (!hash_equals($project_id, sanitize_key($project_id))) {
            throw new RuntimeException('O journal incremental contém um projeto inseguro.');
        }
        return $this->private_storage_dir() . '/agency/' . $project_id . '/workspace';
    }

    /** Normalize resolved filesystem paths for containment checks on both POSIX
     * and Windows hosts without weakening case-sensitive POSIX comparisons. */
    private function project_delta_canonical_real_path(string $path): string {
        $normalized = rtrim(str_replace('\\', '/', $path), '/');
        return DIRECTORY_SEPARATOR === '\\' ? strtolower($normalized) : $normalized;
    }

    private function project_delta_workspace_locator(string $workspace): string {
        $private = realpath($this->private_storage_dir());
        $workspace_real = realpath($workspace);
        if (!$private || !$workspace_real || !is_dir($workspace_real)) {
            throw new RuntimeException('O workspace incremental não possui localização confirmada.');
        }
        $private_canonical = $this->project_delta_canonical_real_path($private);
        $workspace_canonical = $this->project_delta_canonical_real_path($workspace_real);
        $prefix = $private_canonical . '/';
        if (!str_starts_with($workspace_canonical, $prefix)) {
            throw new RuntimeException('O workspace incremental está fora do armazenamento privado.');
        }
        $locator = substr($workspace_canonical, strlen($prefix));
        $resolved = $this->project_delta_workspace_from_locator($locator);
        $resolved_real = realpath($resolved);
        if (
            !$resolved_real
            || !hash_equals(
                $workspace_canonical,
                $this->project_delta_canonical_real_path($resolved_real)
            )
        ) {
            throw new RuntimeException('O locator incremental diverge do workspace selecionado.');
        }
        return $locator;
    }

    private function project_delta_journal_path(): string {
        return $this->private_storage_dir() . '/.project-delta-journal.json';
    }

    /** Persist the recovery intent on the same filesystem before the first
     * directory rename. The journal contains only bounded options/ACK data and
     * relative staging names; it can never redirect recovery outside private
     * Onun Kodety storage. */
    private function write_project_delta_journal(array $journal): void {
        $encoded = wp_json_encode($journal, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        if (!is_string($encoded) || strlen($encoded) > 2 * 1024 * 1024) {
            throw new RuntimeException('O journal do autosave incremental excede o limite seguro.');
        }
        $path = $this->project_delta_journal_path();
        $temporary = $path . '.tmp-' . bin2hex(random_bytes(6));
        try {
            $written = file_put_contents($temporary, $encoded, LOCK_EX);
            if ($written !== strlen($encoded) || !rename($temporary, $path)) {
                throw new RuntimeException('Não foi possível confirmar o journal do autosave incremental.');
            }
        } finally {
            if (is_file($temporary)) @unlink($temporary);
        }
    }

    private function clear_project_delta_journal(): void {
        $path = $this->project_delta_journal_path();
        if (is_file($path) && !@unlink($path)) {
            throw new RuntimeException('Não foi possível concluir a limpeza do journal incremental.');
        }
    }

    /** Recover a PHP/process crash between filesystem swap, option CAS and
     * idempotency receipt. A missing receipt while the old backup still exists
     * always rolls back; a durable receipt (or already-pruned backup) finishes
     * the committed cleanup. Must run under with_workspace_lock(). */
    private function recover_project_delta_journal(): void {
        $path = $this->project_delta_journal_path();
        if (!is_file($path)) return;
        $size = (int) (@filesize($path) ?: 0);
        $journal = $size > 0 && $size <= 2 * 1024 * 1024
            ? json_decode((string) file_get_contents($path), true)
            : null;
        if (!is_array($journal) || (int) ($journal['version'] ?? 0) !== 1) {
            throw new RuntimeException('O journal incremental está inválido e exige recuperação manual.');
        }
        $staging_name = (string) ($journal['staging'] ?? '');
        $backup_name = (string) ($journal['backup'] ?? '');
        if (
            !preg_match('/^\.workspace-delta-[a-f0-9]{16}$/D', $staging_name)
            || !preg_match('/^\.workspace-delta-backup-[a-f0-9]{16}$/D', $backup_name)
        ) {
            throw new RuntimeException('O journal incremental aponta para um staging inseguro.');
        }
        $private = $this->private_storage_dir();
        $staging = $private . '/' . $staging_name;
        $backup = $private . '/' . $backup_name;
        $workspace_locator = (string) ($journal['workspaceLocator'] ?? '');
        $workspace = $this->project_delta_workspace_from_locator($workspace_locator);
        $request_id = (string) ($journal['requestId'] ?? '');
        $fingerprint = (string) ($journal['fingerprint'] ?? '');
        $previous_digest = (string) ($journal['previousDigest'] ?? '');
        $next_digest = (string) ($journal['nextDigest'] ?? '');
        $previous_options = is_array($journal['previousOptions'] ?? null) ? $journal['previousOptions'] : null;
        $ack = is_array($journal['ack'] ?? null) ? $journal['ack'] : null;
        $next_revision = $journal['nextRevision'] ?? null;
        if (
            !preg_match('/^[A-Za-z0-9_-]{16,128}$/D', $request_id)
            || !preg_match('/^[a-f0-9]{64}$/D', $fingerprint)
            || !preg_match('/^[a-f0-9]{64}$/D', $previous_digest)
            || !preg_match('/^[a-f0-9]{64}$/D', $next_digest)
            || !is_array($previous_options)
            || !is_array($ack)
            || !is_int($next_revision)
            || $next_revision < 1
            || (int) ($previous_options['kodety_workspace_revision'] ?? -1) !== $next_revision - 1
            || !hash_equals(
                $previous_digest,
                (string) ($previous_options['kodety_workspace_css_digest'] ?? '')
            )
            || !is_array($previous_options[self::PROJECT_DELTA_RECEIPTS_OPTION] ?? null)
        ) {
            throw new RuntimeException('O journal incremental está incompleto e exige recuperação manual.');
        }

        // A persisted receipt remains proof of commit even if recovery happens
        // after the normal one-day replay window (for example, a site restored
        // from a host snapshot days later).
        $stored_receipts = get_option(self::PROJECT_DELTA_RECEIPTS_OPTION, []);
        $receipt_key = $this->project_delta_receipt_key($workspace_locator, $request_id);
        $stored_receipt = is_array($stored_receipts) && is_array($stored_receipts[$receipt_key] ?? null)
            ? $stored_receipts[$receipt_key]
            : null;
        $receipt_confirmed = is_array($stored_receipt)
            && hash_equals($workspace_locator, (string) ($stored_receipt['workspaceLocator'] ?? ''))
            && hash_equals($request_id, (string) ($stored_receipt['requestId'] ?? ''))
            && hash_equals($fingerprint, (string) ($stored_receipt['fingerprint'] ?? ''))
            && is_array($stored_receipt['result'] ?? null)
            && $stored_receipt['result'] === $ack;
        $options_confirmed = (int) get_option('kodety_workspace_revision', -1) === $next_revision
            && hash_equals($next_digest, (string) get_option('kodety_workspace_css_digest', ''));
        $workspace_digest = is_dir($workspace) ? $this->css_digest_from_directory($workspace) : '';
        $workspace_is_next = preg_match('/^[a-f0-9]{64}$/D', $workspace_digest)
            && hash_equals($next_digest, $workspace_digest);
        if ($options_confirmed && $workspace_is_next && ($receipt_confirmed || !is_dir($backup))) {
            if (is_dir($staging)) $this->remove_tree($staging);
            if (is_dir($backup)) $this->remove_tree($backup);
            if (is_dir($staging) || is_dir($backup)) {
                throw new RuntimeException('A limpeza do commit incremental será tentada novamente.');
            }
            $this->clear_project_delta_journal();
            return;
        }

        if (is_dir($backup)) {
            if (is_dir($workspace)) $this->remove_tree($workspace);
            if (!rename($backup, $workspace)) {
                throw new RuntimeException('O workspace anterior não pôde ser restaurado pelo journal incremental.');
            }
        } else {
            if (!is_dir($workspace)) {
                throw new RuntimeException('O journal incremental não encontrou o workspace nem seu backup.');
            }
            $current_digest = $this->css_digest_from_directory($workspace);
            if (!hash_equals($previous_digest, $current_digest)) {
                throw new RuntimeException('O workspace sem backup diverge do estado anterior registrado no journal.');
            }
        }
        $recoverable_options = [
            'kodety_draft_updated_at',
            'kodety_workspace_revision',
            'kodety_workspace_css_digest',
            'kodety_project_name',
            'kodety_workspace_project_id',
            self::PROJECT_DELTA_RECEIPTS_OPTION,
        ];
        foreach ($previous_options as $option => $value) {
            if (!is_string($option) || !in_array($option, $recoverable_options, true)) {
                throw new RuntimeException('O journal incremental contém uma opção não autorizada.');
            }
            update_option($option, $value, false);
        }
        if (is_dir($staging)) $this->remove_tree($staging);
        if (is_dir($staging)) throw new RuntimeException('O staging incremental não pôde ser removido após a recuperação.');
        $restored_digest = $this->css_digest_from_directory($workspace);
        if (
            !hash_equals($previous_digest, $restored_digest)
            || (int) get_option('kodety_workspace_revision', -1)
                !== (int) $previous_options['kodety_workspace_revision']
            || !hash_equals(
                $previous_digest,
                (string) get_option('kodety_workspace_css_digest', '')
            )
            || get_option(self::PROJECT_DELTA_RECEIPTS_OPTION, [])
                !== $previous_options[self::PROJECT_DELTA_RECEIPTS_OPTION]
        ) {
            throw new RuntimeException('A recuperação incremental não confirmou o workspace anterior.');
        }
        $this->clear_project_delta_journal();
    }

    /** Serialize draft replacement and theme activation across concurrent REST
     * requests, browser tabs and MCP operations in this PHP worker pool. */
    private function with_workspace_lock(callable $operation): mixed {
        if ($this->workspace_lock_depth > 0) {
            $this->workspace_lock_depth++;
            try {
                return $operation();
            } finally {
                $this->workspace_lock_depth--;
            }
        }
        $this->ensure_directories();
        $handle = fopen($this->storage_dir . '/.workspace.lock', 'c+');
        if (!$handle || !flock($handle, LOCK_EX)) {
            if (is_resource($handle)) fclose($handle);
            throw new RuntimeException('Não foi possível bloquear o workspace para salvar com segurança.');
        }
        $this->workspace_lock_handle = $handle;
        $this->workspace_lock_depth = 1;
        try {
            // Another worker may have committed after this request first read
            // get_option(). A mutex is only useful when CAS observes that commit.
            if (function_exists('wp_cache_delete')) {
                foreach (['alloptions', 'notoptions', 'kodety_workspace_revision', 'kodety_workspace_css_digest', 'kodety_workspace_project_id', self::PROJECT_DELTA_RECEIPTS_OPTION] as $option) {
                    wp_cache_delete($option, 'options');
                }
            }
            // A killed PHP worker releases flock automatically. Finish or roll
            // back any directory swap it left between filesystem and option
            // acknowledgement before another workspace operation can proceed.
            $this->recover_project_delta_journal();
            return $operation();
        } finally {
            $this->workspace_lock_depth = 0;
            $this->workspace_lock_handle = null;
            flock($handle, LOCK_UN);
            fclose($handle);
        }
    }

    /** Keep GET snapshots consistent with atomic workspace swaps without
     * queueing PHP workers indefinitely behind a large write. Shared locks let
     * concurrent readers proceed; a busy writer yields a bounded retryable 503
     * well before the browser's request timeout. */
    private function with_workspace_read_lock(callable $operation): mixed {
        if ($this->workspace_lock_depth > 0) return $operation();
        $this->ensure_directories();
        $handle = fopen($this->storage_dir . '/.workspace.lock', 'c+');
        if (!$handle) throw new RuntimeException('Não foi possível abrir o bloqueio de leitura do workspace.');
        $deadline = microtime(true) + 3.0;
        $locked = false;
        do {
            $locked = flock($handle, LOCK_SH | LOCK_NB);
            if ($locked) break;
            usleep(20_000);
        } while (microtime(true) < $deadline);
        if (!$locked) {
            fclose($handle);
            throw new RuntimeException('O projeto está concluindo outro salvamento. Tente novamente em instantes.');
        }
        // A killed writer can leave a journal after the OS releases its lock.
        // Upgrade through the canonical exclusive helper only for that rare
        // recovery path; ordinary GETs remain concurrent and read-only.
        if (is_file($this->project_delta_journal_path())) {
            flock($handle, LOCK_UN);
            fclose($handle);
            return $this->with_workspace_lock($operation);
        }
        try {
            return $operation();
        } finally {
            flock($handle, LOCK_UN);
            fclose($handle);
        }
    }

    /** Complete recovery after a caller has acquired storage/.workspace.lock.
     * MCP owns the same flock across multi-file commands and must recover before
     * resolving or mutating any path left by an interrupted delta swap. */
    public function recover_project_delta_for_locked_writer(): void {
        $this->recover_project_delta_journal();
    }

    /** Keep background native reconciliation single-flight without making a
     * second cron worker wait on image/page work already in progress. The OS
     * releases this lease even after a hard PHP fatal or memory exhaustion. */
    private function with_native_sync_lock(callable $operation): mixed {
        if ($this->native_sync_lock_depth > 0) {
            $this->native_sync_lock_depth++;
            try {
                return $operation();
            } finally {
                $this->native_sync_lock_depth--;
            }
        }
        $this->ensure_directories();
        $handle = fopen($this->storage_dir . '/.native-sync.lock', 'c+');
        if (!$handle || !flock($handle, LOCK_EX | LOCK_NB)) {
            if (is_resource($handle)) fclose($handle);
            throw new RuntimeException('Outra sincronização nativa ainda está em andamento.');
        }
        $this->native_sync_lock_handle = $handle;
        $this->native_sync_lock_depth = 1;
        try {
            return $operation();
        } finally {
            $this->native_sync_lock_depth = 0;
            $this->native_sync_lock_handle = null;
            flock($handle, LOCK_UN);
            fclose($handle);
        }
    }

    private function workspace_conflict(int $current): WP_Error {
        return new WP_Error(
            'kodety_workspace_conflict',
            'O workspace mudou durante esta operação. O editor preservou a versão mais recente e tentará sincronizar novamente.',
            ['status' => 409, 'currentRevision' => $current]
        );
    }

    private function project_draft_editor_lock_error(WP_REST_Request $request): ?WP_Error {
        if (
            class_exists('Kodety_Sharing')
            && Kodety_Sharing::has_editor_context($request)
            && !Kodety_Sharing::instance()->has_editor_lock($request)
        ) {
            return new WP_Error(
                'kodety_editor_lock_required',
                'Este projeto já está aberto para edição em outra sessão.',
                ['status' => 423]
            );
        }
        return null;
    }

    /** A full administrative replacement must not discard an active visual
     * draft. This is an import conflict, not a lock on other admin surfaces. */
    private function admin_import_editor_lock_error(?WP_REST_Request $request = null): ?WP_Error {
        if (
            class_exists('Kodety_Sharing')
            && Kodety_Sharing::instance()->has_active_editor_lock($request)
            && (!$request || !Kodety_Sharing::instance()->has_editor_lock($request))
        ) {
            return new WP_Error(
                'kodety_workspace_conflict',
                'A importação substitui o projeto inteiro. Encerre a edição visual antes de confirmar essa substituição; as alterações atuais foram preservadas.',
                ['status' => 409, 'currentRevision' => (int) get_option('kodety_workspace_revision', 0)]
            );
        }
        return null;
    }

    /** Run inside the workspace mutex immediately before replacing its files. */
    private function assert_admin_import_workspace_revision(int $expected_revision, ?WP_REST_Request $request = null): void {
        $current_revision = (int) get_option('kodety_workspace_revision', 0);
        if ($expected_revision !== $current_revision) {
            throw new DomainException('O projeto mudou durante a importação. As alterações atuais foram preservadas; revise o projeto antes de tentar substituir novamente.', 409);
        }
        $lock_error = $this->admin_import_editor_lock_error($request);
        if ($lock_error) throw new DomainException($lock_error->get_error_message(), 409);
    }

    /** Draft activation performs bounded ZIP validation and an atomic native
     * workspace swap. Give that final (small) request the same resource budget
     * as wp-admin instead of inheriting an unusually low front-end REST limit,
     * and finish the atomic swap if the browser briefly disconnects. */
    private function prepare_project_archive_request(): void {
        if (function_exists('wp_raise_memory_limit')) wp_raise_memory_limit('admin');
        if (function_exists('set_time_limit')) @set_time_limit(300);
        if (function_exists('ignore_user_abort')) @ignore_user_abort(true);
    }

    /** Persist the editable workspace without rebuilding or publishing the
     * generated theme. Settings, localization and canvas changes therefore
     * survive a reload, while Publish remains an explicit action. */
    public function save_project_draft(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $lock_error = $this->project_draft_editor_lock_error($request);
        if ($lock_error) return $lock_error;
        $this->prepare_project_archive_request();
        $body = $request->get_body();
        if ($body === '' || strlen($body) > self::PROJECT_ARCHIVE_MAX_BYTES) {
            return new WP_Error('kodety_invalid_draft', 'O rascunho está vazio ou acima do limite.', ['status' => 400]);
        }
        $temporary = null;
        try {
            $this->ensure_directories();
            $temporary = tempnam($this->private_storage_dir(), 'kodety-draft-');
            if (!$temporary || file_put_contents($temporary, $body, LOCK_EX) === false) {
                throw new RuntimeException('Não foi possível preparar o rascunho.');
            }
            return $this->persist_project_draft_archive($temporary, $request);
        } catch (Throwable $error) {
            return new WP_Error('kodety_draft_save_failed', $error->getMessage(), ['status' => 500]);
        } finally {
            if (is_string($temporary) && is_file($temporary)) @unlink($temporary);
        }
    }

    private function project_delta_fallback_error(
        string $code,
        string $message,
        int $status
    ): WP_Error {
        return new WP_Error($code, $message, [
            'status' => $status,
            // These flags are emitted only before staging or mutating anything.
            'fallbackToZip' => true,
            'safeToRetryAsZip' => true,
        ]);
    }

    /** @return list<string> */
    private function project_allowed_file_extensions(): array {
        return [
            'html','htm','liquid','css','js','mjs','cjs','json','txt','md','csv','xml','svg','webmanifest','map',
            'ts','tsx','jsx','yaml','yml','toml','lock','wasm','bin',
            'gif','png','jpg','jpeg','webp','avif','ico','bmp','tif','tiff',
            'mp4','m4v','mov','webm','ogv','ogg','mp3','wav','m4a','aac','flac',
            'woff','woff2','ttf','otf','eot','vtt','srt','pdf','glb','gltf','hdr','ktx2','lottie',
            'obj','mtl','usdz','cur','m3u8','mpd',
            'doc','docx','xls','xlsx','ppt','pptx','odt','ods','rtf','zip','rar','7z','tar','gz',
        ];
    }

    /** Return whether ZIP activation must ignore this ordinary project entry.
     * Unsupported files are a compatibility concern, not a reason to reject
     * an otherwise valid project. The complete ZIP path can safely omit them;
     * the delta path therefore negotiates that exact fallback before staging. */
    private function project_path_uses_zip_fallback(string $path): bool {
        $segments = explode('/', $path);
        foreach ($segments as $segment) {
            if (
                str_starts_with($segment, '.')
                && !in_array($segment, ['.incode', '.coday'], true)
            ) return true;
        }
        $basename = basename($path);
        if (in_array($basename, ['.htaccess', '.DS_Store', 'Thumbs.db'], true)) return true;
        $extension = strtolower(pathinfo($path, PATHINFO_EXTENSION));
        $allowed_extensionless = in_array(strtoupper($basename), ['CNAME', 'LICENSE', 'README'], true);
        return !$allowed_extensionless
            && ($extension === '' || !in_array($extension, $this->project_allowed_file_extensions(), true));
    }

    /** Validate one project-relative file path against the same browser-only
     * source contract used by ZIP extraction. Payload validation may request
     * an explicit ZIP fallback instead of surfacing a permanent save error. */
    private function normalize_project_delta_path(
        mixed $candidate,
        bool $negotiate_zip_fallback = false
    ): string {
        if (!is_string($candidate)) throw new DomainException('Uma alteração contém um caminho inválido.');
        $path = $candidate;
        if (
            $path === ''
            || strlen($path) > 1024
            || str_starts_with($path, '/')
            || preg_match('/^[A-Za-z]:/', $path)
            || str_contains($path, '\\')
            || str_contains($path, "\0")
            || preg_match('/[\x00-\x1F\x7F]/', $path)
        ) {
            throw new DomainException('Uma alteração contém um caminho inseguro.');
        }
        $segments = explode('/', $path);
        foreach ($segments as $segment) {
            if ($segment === '' || $segment === '.' || $segment === '..' || strlen($segment) > 255) {
                throw new DomainException('Uma alteração contém um caminho inseguro.');
            }
        }
        $basename = basename($path);
        if ($this->project_path_uses_zip_fallback($path)) {
            $message = 'O arquivo ' . sanitize_file_name($basename)
                . ' será ignorado pelo fallback de compatibilidade do ZIP.';
            if ($negotiate_zip_fallback) throw new UnexpectedValueException($message);
            throw new DomainException($message);
        }
        return $path;
    }

    private function project_delta_array_is_list(array $value): bool {
        if (!$value) return true;
        return array_keys($value) === range(0, count($value) - 1);
    }

    /** Apply a release-only compiler overlay to a disposable copy of the
     * exact editable workspace already acknowledged by WordPress. Every file
     * is declared with its uncompressed byte length and SHA-256; undeclared
     * ZIP entries, symlinks and authoring/template metadata changes fail
     * closed before the base archive is modified. */
    private function apply_materialized_publish_overlay_to_zip(
        string $base_zip_path,
        string $overlay_zip_path
    ): void {
        if (!class_exists('ZipArchive')) {
            throw new RuntimeException('A extensão PHP ZipArchive precisa estar habilitada na hospedagem.');
        }
        $overlay = new ZipArchive();
        if ($overlay->open($overlay_zip_path) !== true) {
            throw new RuntimeException('O overlay materializado é inválido ou está corrompido.');
        }
        $upsert_contents = [];
        $deletes = [];
        try {
            if ($overlay->numFiles > self::PROJECT_DELTA_MAX_OPERATIONS + 8) {
                throw new RuntimeException('O overlay materializado possui arquivos demais.');
            }
            $manifest_stat = $overlay->statName(self::MATERIALIZED_PUBLISH_OVERLAY_MANIFEST);
            if (
                !is_array($manifest_stat)
                || (int) ($manifest_stat['size'] ?? -1) < 1
                || (int) ($manifest_stat['size'] ?? 0) > self::MATERIALIZED_PUBLISH_OVERLAY_MANIFEST_MAX_BYTES
            ) {
                throw new RuntimeException('O manifesto do overlay materializado está ausente ou acima do limite.');
            }
            $manifest_json = $overlay->getFromName(self::MATERIALIZED_PUBLISH_OVERLAY_MANIFEST);
            if (!is_string($manifest_json)) {
                throw new RuntimeException('Não foi possível ler o manifesto do overlay materializado.');
            }
            try {
                $manifest = json_decode($manifest_json, true, 512, JSON_THROW_ON_ERROR);
            } catch (Throwable $error) {
                throw new RuntimeException('O manifesto do overlay materializado não contém JSON válido.', 0, $error);
            }
            $raw_upserts = is_array($manifest) ? ($manifest['upserts'] ?? null) : null;
            $raw_deletes = is_array($manifest) ? ($manifest['deletes'] ?? null) : null;
            if (
                !is_array($manifest)
                || (int) ($manifest['schemaVersion'] ?? 0) !== self::MATERIALIZED_PUBLISH_OVERLAY_SCHEMA_VERSION
                || (string) ($manifest['kind'] ?? '') !== self::MATERIALIZED_PUBLISH_OVERLAY_KIND
                || !is_array($raw_upserts)
                || !is_array($raw_deletes)
                || !$this->project_delta_array_is_list($raw_upserts)
                || !$this->project_delta_array_is_list($raw_deletes)
            ) {
                throw new RuntimeException('A versão do overlay materializado não é compatível.');
            }
            $operation_count = count($raw_upserts) + count($raw_deletes);
            if ($operation_count > self::PROJECT_DELTA_MAX_OPERATIONS) {
                throw new RuntimeException('O overlay materializado possui operações demais.');
            }

            $protected = [
                '.incode/project.json' => true,
                self::PROJECT_TEMPLATE_MANIFEST => true,
                self::MATERIALIZED_PUBLISH_OVERLAY_MANIFEST => true,
            ];
            $declared_upserts = [];
            $declared_deletes = [];
            foreach ($raw_upserts as $raw_upsert) {
                if (!is_array($raw_upsert)) {
                    throw new RuntimeException('Um arquivo do overlay materializado está incompleto.');
                }
                try {
                    $path = $this->normalize_project_delta_path($raw_upsert['path'] ?? null);
                } catch (Throwable $error) {
                    throw new RuntimeException('O overlay materializado contém um caminho inválido.', 0, $error);
                }
                $byte_length = $raw_upsert['byteLength'] ?? null;
                $sha256 = strtolower(trim((string) ($raw_upsert['sha256'] ?? '')));
                if (
                    isset($protected[$path])
                    || isset($declared_upserts[$path])
                    || !is_int($byte_length)
                    || $byte_length < 0
                    || $byte_length > self::PROJECT_DELTA_MAX_FILE_BYTES
                    || !preg_match('/^[a-f0-9]{64}$/D', $sha256)
                ) {
                    throw new RuntimeException('Um arquivo do overlay materializado é inválido ou tenta alterar metadados protegidos.');
                }
                $declared_upserts[$path] = [
                    'byteLength' => $byte_length,
                    'sha256' => $sha256,
                ];
            }
            foreach ($raw_deletes as $raw_delete) {
                try {
                    $path = $this->normalize_project_delta_path($raw_delete);
                } catch (Throwable $error) {
                    throw new RuntimeException('O overlay materializado contém uma exclusão inválida.', 0, $error);
                }
                if (
                    isset($protected[$path])
                    || isset($declared_deletes[$path])
                    || isset($declared_upserts[$path])
                ) {
                    throw new RuntimeException('O overlay materializado repete uma operação ou tenta excluir metadados protegidos.');
                }
                $declared_deletes[$path] = true;
                $deletes[] = $path;
            }

            $entry_indexes = [];
            $decoded_bytes = 0;
            for ($index = 0; $index < $overlay->numFiles; $index++) {
                $stat = $overlay->statIndex($index);
                $archive_name = (string) ($stat['name'] ?? '');
                $normalized = str_replace('\\', '/', $archive_name);
                $trimmed = rtrim($normalized, '/');
                $segments = explode('/', $trimmed);
                if (
                    $trimmed === ''
                    || str_starts_with($normalized, '/')
                    || preg_match('/^[A-Za-z]:/', $trimmed)
                    || in_array('', $segments, true)
                    || in_array('.', $segments, true)
                    || in_array('..', $segments, true)
                    || str_contains($trimmed, "\0")
                ) {
                    throw new RuntimeException('O overlay materializado contém um caminho inseguro.');
                }
                $operating_system = 0;
                $external_attributes = 0;
                if (
                    method_exists($overlay, 'getExternalAttributesIndex')
                    && $overlay->getExternalAttributesIndex($index, $operating_system, $external_attributes)
                    && (($external_attributes >> 16) & 0170000) === 0120000
                ) {
                    throw new RuntimeException('O overlay materializado contém links simbólicos não permitidos.');
                }
                if (str_ends_with($normalized, '/')) continue;
                if (isset($entry_indexes[$trimmed])) {
                    throw new RuntimeException('O overlay materializado repete o mesmo arquivo no ZIP.');
                }
                if ($trimmed === self::MATERIALIZED_PUBLISH_OVERLAY_MANIFEST) {
                    $entry_indexes[$trimmed] = $index;
                    continue;
                }
                if (!isset($declared_upserts[$trimmed])) {
                    throw new RuntimeException('O overlay materializado contém um arquivo não declarado.');
                }
                $size = (int) ($stat['size'] ?? -1);
                if ($size !== $declared_upserts[$trimmed]['byteLength']) {
                    throw new RuntimeException('O tamanho de um arquivo do overlay materializado não confere.');
                }
                $decoded_bytes += $size;
                if ($decoded_bytes > self::PROJECT_DELTA_MAX_BODY_BYTES) {
                    throw new RuntimeException('Os arquivos do overlay materializado excedem o limite incremental.');
                }
                $entry_indexes[$trimmed] = $index;
            }
            foreach ($declared_upserts as $path => $integrity) {
                if (!isset($entry_indexes[$path])) {
                    throw new RuntimeException('O overlay materializado não contém todos os arquivos declarados.');
                }
                $contents = $overlay->getFromIndex($entry_indexes[$path]);
                if (
                    !is_string($contents)
                    || strlen($contents) !== $integrity['byteLength']
                    || !hash_equals($integrity['sha256'], hash('sha256', $contents))
                ) {
                    throw new RuntimeException('A integridade de um arquivo do overlay materializado não confere.');
                }
                $upsert_contents[$path] = $contents;
            }
        } finally {
            $overlay->close();
        }

        $base = new ZipArchive();
        if ($base->open($base_zip_path) !== true) {
            throw new RuntimeException('A revisão salva não pôde ser aberta para materialização.');
        }
        $closed = false;
        try {
            if (
                $base->locateName(self::MATERIALIZED_PUBLISH_OVERLAY_MANIFEST) !== false
                && !$base->deleteName(self::MATERIALIZED_PUBLISH_OVERLAY_MANIFEST)
            ) {
                throw new RuntimeException('Não foi possível remover um manifesto antigo da revisão salva.');
            }
            foreach ($deletes as $path) {
                if ($base->locateName($path) !== false && !$base->deleteName($path)) {
                    throw new RuntimeException('Não foi possível aplicar uma exclusão do overlay materializado.');
                }
            }
            foreach ($upsert_contents as $path => $contents) {
                if ($base->locateName($path) !== false && !$base->deleteName($path)) {
                    throw new RuntimeException('Não foi possível substituir um arquivo do overlay materializado.');
                }
                if (!$base->addFromString($path, $contents)) {
                    throw new RuntimeException('Não foi possível aplicar um arquivo do overlay materializado.');
                }
            }
            if (!$base->close()) {
                throw new RuntimeException('Não foi possível confirmar o ZIP materializado.');
            }
            $closed = true;
        } catch (Throwable $error) {
            if (!$closed) @$base->close();
            throw $error;
        }
    }

    /** Decode and authenticate the bounded JSON transaction before acquiring
     * the workspace lock. No filesystem mutation is possible in this phase.
     *
     * @return array{
     *   baseRevision:int,
     *   baseDigest:?string,
     *   requestId:string,
     *   upserts:list<array{path:string,bytes:string,sha256:string}>,
     *   deletes:list<string>,
     *   moves:list<array{from:string,to:string}>
     * }
     */
    private function parse_project_delta_payload(string $body, WP_REST_Request $request): array {
        try {
            $payload = json_decode($body, true, 512, JSON_THROW_ON_ERROR);
        } catch (Throwable $error) {
            throw new DomainException('O change-set não contém JSON válido.', 0, $error);
        }
        if (!is_array($payload) || (int) ($payload['protocolVersion'] ?? 0) !== self::PROJECT_DELTA_PROTOCOL_VERSION) {
            throw new DomainException('A versão do protocolo incremental não é compatível.');
        }
        $base_revision = $payload['baseRevision'] ?? null;
        if (!is_int($base_revision) || $base_revision < 0) {
            throw new DomainException('A revisão base do change-set é obrigatória.');
        }
        $raw_expected_revision = trim((string) $request->get_header('x-kodety-expected-revision'));
        if ($raw_expected_revision !== '') {
            if (!ctype_digit($raw_expected_revision) || (int) $raw_expected_revision !== $base_revision) {
                throw new DomainException('A revisão do cabeçalho diverge do change-set.');
            }
        }
        $base_digest = null;
        if (array_key_exists('baseDigest', $payload) && $payload['baseDigest'] !== null) {
            $base_digest = strtolower(trim((string) $payload['baseDigest']));
            if (!preg_match('/^[a-f0-9]{64}$/D', $base_digest)) {
                throw new DomainException('A integridade base do change-set é inválida.');
            }
        }
        $request_id = is_string($payload['requestId'] ?? null)
            ? trim($payload['requestId'])
            : '';
        if (!preg_match('/^[A-Za-z0-9_-]{16,128}$/D', $request_id)) {
            throw new DomainException('O identificador idempotente do autosave é inválido.');
        }

        $raw_upserts = $payload['upserts'] ?? [];
        $raw_deletes = $payload['deletes'] ?? [];
        $raw_moves = $payload['moves'] ?? [];
        if (
            !is_array($raw_upserts)
            || !is_array($raw_deletes)
            || !is_array($raw_moves)
            || !$this->project_delta_array_is_list($raw_upserts)
            || !$this->project_delta_array_is_list($raw_deletes)
            || !$this->project_delta_array_is_list($raw_moves)
        ) {
            throw new DomainException('As operações do change-set são inválidas.');
        }
        $operation_count = count($raw_upserts) + count($raw_deletes) + count($raw_moves);
        if ($operation_count < 1 || $operation_count > self::PROJECT_DELTA_MAX_OPERATIONS) {
            throw new DomainException('O change-set está vazio ou possui operações demais.');
        }

        $upserts = [];
        $deletes = [];
        $moves = [];
        $upsert_paths = [];
        $delete_paths = [];
        $move_sources = [];
        $move_targets = [];
        $decoded_bytes = 0;
        foreach ($raw_upserts as $raw_upsert) {
            if (!is_array($raw_upsert)) throw new DomainException('Um arquivo do change-set está incompleto.');
            $path = $this->normalize_project_delta_path($raw_upsert['path'] ?? null, true);
            if (isset($upsert_paths[$path])) throw new DomainException('O change-set repete o mesmo arquivo.');
            $encoding = (string) ($raw_upsert['encoding'] ?? '');
            $content = $raw_upsert['content'] ?? null;
            $byte_length = $raw_upsert['byteLength'] ?? null;
            $sha256 = strtolower(trim((string) ($raw_upsert['sha256'] ?? '')));
            if (
                !in_array($encoding, ['utf8', 'base64'], true)
                || !is_string($content)
                || !is_int($byte_length)
                || $byte_length < 0
                || $byte_length > self::PROJECT_DELTA_MAX_FILE_BYTES
                || !preg_match('/^[a-f0-9]{64}$/D', $sha256)
            ) {
                throw new DomainException('Um arquivo do change-set excede os limites ou não possui integridade.');
            }
            if ($encoding === 'utf8') {
                if (preg_match('//u', $content) !== 1) {
                    throw new DomainException('Um arquivo de texto contém UTF-8 inválido.');
                }
                $bytes = $content;
            } else {
                $bytes = base64_decode($content, true);
                if (!is_string($bytes)) throw new DomainException('Um arquivo binário contém Base64 inválido.');
            }
            if (
                strlen($bytes) !== $byte_length
                || !hash_equals($sha256, hash('sha256', $bytes))
            ) {
                throw new DomainException('A integridade de um arquivo do change-set não confere.');
            }
            $decoded_bytes += $byte_length;
            if ($decoded_bytes > self::PROJECT_DELTA_MAX_BODY_BYTES) {
                throw new DomainException('Os arquivos do change-set excedem o limite incremental.');
            }
            $upsert_paths[$path] = true;
            $upserts[] = compact('path', 'bytes', 'sha256');
        }
        foreach ($raw_deletes as $raw_delete) {
            $path = $this->normalize_project_delta_path($raw_delete, true);
            if (isset($delete_paths[$path])) throw new DomainException('O change-set repete a mesma exclusão.');
            $delete_paths[$path] = true;
            $deletes[] = $path;
        }
        foreach ($raw_moves as $raw_move) {
            if (!is_array($raw_move)) throw new DomainException('Uma movimentação do change-set está incompleta.');
            $from = $this->normalize_project_delta_path($raw_move['from'] ?? null, true);
            $to = $this->normalize_project_delta_path($raw_move['to'] ?? null, true);
            if (
                $from === $to
                || isset($move_sources[$from])
                || isset($move_targets[$to])
            ) {
                throw new DomainException('Uma movimentação do change-set é ambígua.');
            }
            $move_sources[$from] = true;
            $move_targets[$to] = true;
            $moves[] = compact('from', 'to');
        }
        foreach (array_keys($delete_paths) as $path) {
            if (isset($upsert_paths[$path]) || isset($move_sources[$path]) || isset($move_targets[$path])) {
                throw new DomainException('O change-set tenta alterar e excluir o mesmo caminho.');
            }
        }
        foreach (array_keys($upsert_paths) as $path) {
            // A moved file may be rewritten at its destination in the same
            // transaction, but recreating its source is intentionally refused.
            if (isset($move_sources[$path])) {
                throw new DomainException('O change-set tenta mover e recriar o mesmo caminho.');
            }
        }
        return [
            'baseRevision' => $base_revision,
            'baseDigest' => $base_digest,
            'requestId' => $request_id,
            'upserts' => $upserts,
            'deletes' => $deletes,
            'moves' => $moves,
        ];
    }

    /** Large immutable browser assets are safe to hardlink into disposable
     * staging because every delta replacement uses temp+rename. Text, HTML and
     * all private metadata are copied: Membership and Shopify validation may
     * rewrite those files in place and must never share an inode with live. */
    private function project_delta_file_can_hardlink(string $relative): bool {
        if (
            str_starts_with($relative, '.incode/')
            || str_contains($relative, '/.incode/')
            || str_starts_with($relative, '.coday/')
            || str_contains($relative, '/.coday/')
        ) return false;
        return in_array(strtolower(pathinfo($relative, PATHINFO_EXTENSION)), [
            'wasm','bin','gif','png','jpg','jpeg','webp','avif','ico','bmp','tif','tiff',
            'mp4','m4v','mov','webm','ogv','ogg','mp3','wav','m4a','aac','flac',
            'woff','woff2','ttf','otf','eot','pdf','glb','gltf','hdr','ktx2','lottie',
            'obj','mtl','usdz','cur','doc','docx','xls','xlsx','ppt','pptx','odt','ods',
            'zip','rar','7z','tar','gz',
        ], true);
    }

    /** Clone a native workspace without copying unchanged media on hosts that
     * support same-filesystem hardlinks. copy() remains the transparent
     * compatibility fallback for filesystems that do not. */
    private function clone_project_delta_workspace_tree(
        string $source,
        string $destination,
        string $relative = ''
    ): void {
        if (!is_dir($source) || is_link($source)) {
            throw new RuntimeException('O workspace atual não pode ser clonado com segurança.');
        }
        if ((!is_dir($destination) && !wp_mkdir_p($destination)) || !is_dir($destination)) {
            throw new RuntimeException('Não foi possível criar o staging incremental.');
        }
        foreach (new DirectoryIterator($source) as $item) {
            if ($item->isDot()) continue;
            if ($item->isLink()) throw new DomainException('O workspace contém um link simbólico não permitido.');
            $name = $item->getFilename();
            $next_relative = $relative === '' ? $name : $relative . '/' . $name;
            $target = $destination . '/' . $name;
            if ($item->isDir()) {
                $this->clone_project_delta_workspace_tree($item->getPathname(), $target, $next_relative);
                continue;
            }
            if (!$item->isFile()) throw new DomainException('O workspace contém uma entrada especial não permitida.');
            $linked = $this->project_delta_file_can_hardlink($next_relative)
                && function_exists('link')
                && @link($item->getPathname(), $target);
            if (!$linked && !@copy($item->getPathname(), $target)) {
                throw new RuntimeException('Não foi possível clonar ' . $name . ' para o staging incremental.');
            }
        }
    }

    /** Resolve a validated project path below a real staging root. */
    private function project_delta_target(
        string $root,
        string $relative,
        bool $create_parent = true
    ): string {
        $root_real = realpath($root);
        if (!$root_real || !is_dir($root_real)) throw new RuntimeException('O staging incremental não está disponível.');
        $target = $root_real . '/' . $relative;
        if (!$create_parent) return $target;
        $parent = dirname($target);
        if ((!is_dir($parent) && !wp_mkdir_p($parent)) || !is_dir($parent)) {
            throw new RuntimeException('Não foi possível criar uma pasta do change-set.');
        }
        $parent_real = realpath($parent);
        $root_canonical = $this->project_delta_canonical_real_path($root_real);
        $parent_canonical = is_string($parent_real)
            ? $this->project_delta_canonical_real_path($parent_real)
            : '';
        if (
            !$parent_real
            || (
                $parent_canonical !== $root_canonical
                && !str_starts_with($parent_canonical, $root_canonical . '/')
            )
        ) {
            throw new DomainException('Uma alteração tentou sair do workspace.');
        }
        return $target;
    }

    private function write_project_delta_file(string $root, string $relative, string $bytes): void {
        $target = $this->project_delta_target($root, $relative);
        if (is_dir($target) || is_link($target)) {
            throw new DomainException('Um arquivo do change-set colide com uma pasta ou link.');
        }
        $temporary = dirname($target) . '/.' . basename($target) . '.kodety-delta-' . bin2hex(random_bytes(6));
        try {
            $written = file_put_contents($temporary, $bytes, LOCK_EX);
            if ($written !== strlen($bytes) || !rename($temporary, $target)) {
                throw new RuntimeException('Um arquivo do change-set não pôde ser gravado integralmente.');
            }
        } finally {
            if (is_file($temporary)) @unlink($temporary);
        }
    }

    /**
     * Parse the legacy coded-build snapshot that hydrateCodedProject() removes
     * when the Builder opens a project. Delta operations are calculated against
     * that hydrated authoring graph, never against the generated transport
     * files stored in the canonical WordPress workspace.
     *
     * This preflight runs against the locked live workspace before staging is
     * created. A manifest the browser would hydrate but that exceeds this safe
     * server subset can therefore request the explicit ZIP fallback without
     * making an ambiguous partial transaction. JSON/schema the browser ignores
     * is ignored here too.
     *
     * @return array{originals:array<string,string>,generated:list<string>}|null
     */
    private function project_delta_coded_build_manifest(string $root): ?array {
        $root_real = realpath($root);
        if (!$root_real || !is_dir($root_real)) {
            throw new RuntimeException('O workspace incremental não está disponível.');
        }
        // This deliberately matches CODED_BUILD_MANIFEST in the browser. A
        // nested lookalike is an ordinary project file and is not hydrated by
        // hydrateCodedProject(). Wrapper projects generated by the Builder keep
        // this manifest at the transport root and record wrapped file paths in
        // originals/generated.
        $manifest_path = $root_real . '/.incode/coded-build.json';
        if (!is_file($manifest_path)) return null;
        if (is_link($manifest_path)) {
            throw new DomainException('O manifesto legado do build usa um link simbólico não permitido.');
        }
        $size = filesize($manifest_path);
        if ($size === 0) return null;
        if ($size === false || $size > 16 * MB_IN_BYTES) {
            throw new DomainException('O manifesto legado do build excede o limite seguro.');
        }
        $encoded = file_get_contents($manifest_path);
        if (!is_string($encoded) || $encoded === '') {
            throw new RuntimeException('O manifesto legado do build não pôde ser lido.');
        }
        try {
            $manifest = json_decode($encoded, true, 512, JSON_THROW_ON_ERROR);
        } catch (Throwable) {
            // hydrateCodedProject() catches parse failures and keeps the file
            // graph byte-for-byte, so no server normalization is needed.
            return null;
        }
        $raw_version = is_array($manifest) ? ($manifest['version'] ?? null) : null;
        $version = is_int($raw_version) || is_float($raw_version)
            ? (float) $raw_version
            : (is_bool($raw_version)
                ? ($raw_version ? 1.0 : 0.0)
                : (is_string($raw_version) && is_numeric(trim($raw_version)) ? (float) trim($raw_version) : 0.0));
        $raw_originals = is_array($manifest) ? ($manifest['originals'] ?? null) : null;
        $raw_generated = is_array($manifest) ? ($manifest['generated'] ?? null) : null;
        if (
            !in_array($version, [1.0, 2.0], true)
            || !is_array($raw_originals)
            || !is_array($raw_generated)
        ) {
            return null;
        }
        if (
            !$this->project_delta_array_is_list($raw_generated)
            || count($raw_originals) > 10_000
            || count($raw_generated) > 10_000
        ) {
            throw new DomainException('O manifesto legado do build possui uma estrutura incompatível.');
        }

        $originals = [];
        foreach ($raw_originals as $raw_path => $text) {
            $path = $this->normalize_project_delta_path((string) $raw_path);
            if (!is_string($text) || isset($originals[$path])) {
                throw new DomainException('O manifesto legado do build contém uma fonte autoral inválida.');
            }
            $originals[$path] = $text;
        }
        $generated = [];
        $generated_paths = [];
        foreach ($raw_generated as $raw_path) {
            $path = $this->normalize_project_delta_path($raw_path);
            if (isset($generated_paths[$path])) continue;
            $generated_paths[$path] = true;
            $generated[] = $path;
        }
        return compact('originals', 'generated');
    }

    /** Restore originals, remove generated artifacts, then remove the manifest
     * in the same order as hydrateCodedProject(). Only disposable staging is
     * changed; complete-file temp+rename writes preserve transactionality. */
    private function hydrate_project_delta_coded_workspace(string $root, ?array $manifest): void {
        if ($manifest === null) return;
        foreach ($manifest['originals'] as $path => $text) {
            $this->write_project_delta_file($root, $path, $text);
        }
        foreach ($manifest['generated'] as $path) {
            $target = $this->project_delta_target($root, $path, false);
            if (is_link($target) || is_dir($target)) {
                throw new DomainException('Um artefato gerado do build colide com uma pasta ou link.');
            }
            // JavaScript delete is intentionally idempotent when an older
            // manifest mentions an artifact that is already absent.
            if (is_file($target) && !@unlink($target)) {
                throw new RuntimeException('Um artefato gerado do build não pôde ser removido do staging.');
            }
        }
        $manifest_path = $this->project_delta_target($root, '.incode/coded-build.json', false);
        if (is_link($manifest_path) || is_dir($manifest_path)) {
            throw new DomainException('O manifesto legado do build colide com uma pasta ou link.');
        }
        if (is_file($manifest_path) && !@unlink($manifest_path)) {
            throw new RuntimeException('O manifesto legado do build não pôde ser removido do staging.');
        }
    }

    /** Apply deletes, cycle-safe moves and complete-file upserts only inside a
     * disposable staging tree. */
    private function apply_project_delta_operations(string $root, array $payload): void {
        foreach ($payload['deletes'] as $relative) {
            $target = $this->project_delta_target($root, $relative, false);
            if (!is_file($target) || is_link($target) || !@unlink($target)) {
                throw new DomainException('Um arquivo solicitado para exclusão não existe mais.');
            }
        }

        $moves = $payload['moves'];
        if ($moves) {
            $move_sources = [];
            foreach ($moves as $move) $move_sources[$move['from']] = true;
            foreach ($moves as $move) {
                $source = $this->project_delta_target($root, $move['from'], false);
                $target = $this->project_delta_target($root, $move['to'], false);
                if (!is_file($source) || is_link($source)) {
                    throw new DomainException('A origem de uma movimentação não existe mais.');
                }
                if ((is_file($target) || is_link($target) || is_dir($target)) && !isset($move_sources[$move['to']])) {
                    throw new DomainException('O destino de uma movimentação já existe.');
                }
            }
            $temporary_directory = rtrim($root, '/\\') . '/.kodety-delta-moves-' . bin2hex(random_bytes(6));
            if (!wp_mkdir_p($temporary_directory) || !is_dir($temporary_directory)) {
                throw new RuntimeException('Não foi possível preparar as movimentações do change-set.');
            }
            try {
                $temporary_moves = [];
                foreach ($moves as $index => $move) {
                    $source = $this->project_delta_target($root, $move['from'], false);
                    $temporary = $temporary_directory . '/' . $index;
                    if (!rename($source, $temporary)) {
                        throw new RuntimeException('Uma movimentação não pôde ser preparada.');
                    }
                    $temporary_moves[] = ['temporary' => $temporary, 'to' => $move['to']];
                }
                foreach ($temporary_moves as $move) {
                    $target = $this->project_delta_target($root, $move['to']);
                    if (!rename($move['temporary'], $target)) {
                        throw new RuntimeException('Uma movimentação não pôde ser concluída.');
                    }
                }
            } finally {
                if (is_dir($temporary_directory)) $this->remove_tree($temporary_directory);
            }
        }

        foreach ($payload['upserts'] as $upsert) {
            $this->write_project_delta_file($root, $upsert['path'], $upsert['bytes']);
            $target = $this->project_delta_target($root, $upsert['path']);
            $actual = hash_file('sha256', $target);
            if (!is_string($actual) || !hash_equals($upsert['sha256'], $actual)) {
                throw new RuntimeException('Um arquivo divergiu depois de gravado no staging.');
            }
        }
    }

    /** Revalidate the complete resulting tree, including unchanged files from
     * the base revision. This prevents a small delta from laundering a path,
     * symlink or over-limit tree that the ZIP importer would reject. */
    private function assert_project_delta_tree(string $root): void {
        $root_real = realpath($root);
        if (!$root_real || !is_dir($root_real)) throw new RuntimeException('O staging incremental não está disponível.');
        $files = 0;
        $bytes = 0;
        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($root_real, FilesystemIterator::SKIP_DOTS),
            RecursiveIteratorIterator::SELF_FIRST
        );
        foreach ($iterator as $item) {
            if ($item->isLink()) throw new DomainException('O projeto contém um link simbólico não permitido.');
            if ($item->isDir()) continue;
            if (!$item->isFile()) throw new DomainException('O projeto contém uma entrada especial não permitida.');
            $relative = ltrim(str_replace('\\', '/', substr($item->getPathname(), strlen($root_real))), '/');
            $this->normalize_project_delta_path($relative);
            $files++;
            if ($files > 10000) throw new DomainException('O projeto possui arquivos demais.');
            $size = $item->getSize();
            if ($size < 0 || $size > self::PROJECT_DELTA_MAX_FILE_BYTES) {
                throw new DomainException('Um arquivo do projeto excede 256 MB.');
            }
            $bytes += $size;
            if ($bytes > self::PROJECT_ARCHIVE_MAX_BYTES) {
                throw new DomainException('O conteúdo do projeto excede 800 MB.');
            }
        }
    }

    private function project_delta_casefold_path(string $path): string {
        if (class_exists('Normalizer')) {
            $normalized = Normalizer::normalize($path, Normalizer::FORM_C);
            if (is_string($normalized)) $path = $normalized;
        }
        return function_exists('mb_strtolower') ? mb_strtolower($path, 'UTF-8') : strtolower($path);
    }

    /** Prove the final logical manifest before touching staging paths. macOS
     * and common WordPress volumes are case-insensitive; treating Foo.css and
     * foo.css as two project files would overwrite one of them during apply.
     * Directory prefixes are checked too, including NFC when intl is present. */
    private function assert_project_delta_manifest(string $root, array $payload): void {
        $root_real = realpath($root);
        if (!$root_real || !is_dir($root_real)) throw new RuntimeException('O staging incremental não está disponível.');
        $manifest = [];
        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($root_real, FilesystemIterator::SKIP_DOTS)
        );
        foreach ($iterator as $item) {
            if ($item->isLink()) throw new DomainException('O projeto contém um link simbólico não permitido.');
            if (!$item->isFile()) continue;
            $relative = ltrim(str_replace('\\', '/', substr($item->getPathname(), strlen($root_real))), '/');
            $manifest[$relative] = true;
        }
        foreach ($payload['deletes'] as $path) {
            if (!isset($manifest[$path])) throw new DomainException('Um arquivo solicitado para exclusão não existe mais.');
            unset($manifest[$path]);
        }
        $move_sources = [];
        foreach ($payload['moves'] as $move) {
            if (!isset($manifest[$move['from']])) {
                throw new DomainException('A origem de uma movimentação não existe mais.');
            }
            $move_sources[$move['from']] = true;
        }
        foreach ($payload['moves'] as $move) {
            if (isset($manifest[$move['to']]) && !isset($move_sources[$move['to']])) {
                throw new DomainException('O destino de uma movimentação já existe.');
            }
        }
        foreach ($payload['moves'] as $move) unset($manifest[$move['from']]);
        foreach ($payload['moves'] as $move) $manifest[$move['to']] = true;
        foreach ($payload['upserts'] as $upsert) $manifest[$upsert['path']] = true;

        $folded_prefixes = [];
        foreach (array_keys($manifest) as $path) {
            $segments = explode('/', $path);
            $prefix = '';
            $last = count($segments) - 1;
            foreach ($segments as $index => $segment) {
                $prefix = $prefix === '' ? $segment : $prefix . '/' . $segment;
                $folded = $this->project_delta_casefold_path($prefix);
                $kind = $index === $last ? 'file' : 'directory';
                if (isset($folded_prefixes[$folded])) {
                    $existing = $folded_prefixes[$folded];
                    if ($existing['path'] !== $prefix || $existing['kind'] !== $kind) {
                        throw new DomainException(
                            'O projeto contém caminhos que colidem por maiúsculas, minúsculas ou normalização Unicode.'
                        );
                    }
                    continue;
                }
                $folded_prefixes[$folded] = ['path' => $prefix, 'kind' => $kind];
            }
        }
    }

    /** Persist one complete-file change-set against an acknowledged native
     * workspace revision. The legacy ZIP endpoints remain untouched and are
     * advertised only as a pre-mutation fallback when this capability is
     * disabled or the request cannot fit the bounded delta transport. */
    public function save_project_draft_delta(WP_REST_Request $request): WP_REST_Response|WP_Error {
        if (!apply_filters('kodety_project_delta_enabled', true)) {
            try {
                if (is_file($this->project_delta_journal_path())) {
                    $this->with_workspace_lock(static fn(): bool => true);
                }
            } catch (Throwable $error) {
                return new WP_Error(
                    'kodety_project_delta_recovery_failed',
                    $error->getMessage(),
                    ['status' => 503, 'retryable' => true]
                );
            }
            return $this->project_delta_fallback_error(
                'kodety_project_delta_disabled',
                'O autosave incremental está desativado nesta instalação.',
                501
            );
        }
        $lock_error = $this->project_draft_editor_lock_error($request);
        if ($lock_error) return $lock_error;
        $this->prepare_project_archive_request();
        $delta_root_mode = strtolower(trim((string) $request->get_header('X-Kodety-Delta-Root')));
        if (!in_array($delta_root_mode, ['', 'project'], true)) {
            return new WP_Error(
                'kodety_invalid_project_delta_root',
                'A raiz lógica do change-set é inválida.',
                ['status' => 400]
            );
        }
        $project_relative_delta = $delta_root_mode === 'project';
        $body = $request->get_body();
        if ($body === '') {
            return new WP_Error('kodety_invalid_project_delta', 'O change-set está vazio.', ['status' => 400]);
        }
        if (strlen($body) > self::PROJECT_DELTA_MAX_BODY_BYTES) {
            return $this->project_delta_fallback_error(
                'kodety_project_delta_too_large',
                'O change-set excede o limite incremental desta hospedagem.',
                413
            );
        }
        try {
            $payload = $this->parse_project_delta_payload($body, $request);
        } catch (UnexpectedValueException $error) {
            return $this->project_delta_fallback_error(
                'kodety_project_delta_file_fallback',
                $error->getMessage(),
                415
            );
        } catch (Throwable $error) {
            // Payload parsing happens before the lock, staging or any write.
            // Let the Builder retry the same project through the complete ZIP
            // transport instead of surfacing a permanent autosave rejection.
            return $this->project_delta_fallback_error(
                'kodety_invalid_project_delta',
                $error->getMessage(),
                422
            );
        }
        // Root mode is part of idempotency: replaying the same body against a
        // wrapper-inclusive Builder graph and a collapsed Settings graph must
        // never reuse the other operation's receipt.
        $fingerprint = hash('sha256', $delta_root_mode . "\0" . $body);
        try {
            $result = $this->with_workspace_lock(function () use ($payload, $fingerprint, $project_relative_delta): array|WP_Error {
                $workspace = $this->workspace_dir();
                if (!is_dir($workspace) || is_link($workspace)) {
                    return new WP_Error('kodety_no_project', 'Nenhum projeto foi importado.', ['status' => 404]);
                }
                $workspace_locator = $this->project_delta_workspace_locator($workspace);
                $receipt = $this->project_delta_receipt(
                    $payload['requestId'],
                    $fingerprint,
                    $workspace_locator
                );
                if (is_wp_error($receipt) || is_array($receipt)) return $receipt;

                $current_revision = (int) get_option('kodety_workspace_revision', 0);
                if ($payload['baseRevision'] !== $current_revision) {
                    return $this->workspace_conflict($current_revision);
                }
                $current_digest = (string) get_option('kodety_workspace_css_digest', '');
                if (!preg_match('/^[a-f0-9]{64}$/D', $current_digest)) {
                    return new WP_Error(
                        'kodety_workspace_digest_unavailable',
                        'A revisão atual ainda não possui integridade confirmada para autosave incremental.',
                        ['status' => 409, 'currentRevision' => $current_revision]
                    );
                }
                if (
                    $payload['baseDigest'] !== null
                    && (
                        !hash_equals($payload['baseDigest'], $current_digest)
                    )
                ) {
                    return new WP_Error(
                        'kodety_workspace_digest_conflict',
                        'A integridade do workspace mudou antes do autosave incremental.',
                        [
                            'status' => 409,
                            'currentRevision' => $current_revision,
                            'currentDigest' => $current_digest,
                        ]
                    );
                }
                try {
                    $coded_build_manifest = $this->project_delta_coded_build_manifest($workspace);
                } catch (Throwable $error) {
                    return $this->project_delta_fallback_error(
                        'kodety_project_delta_coded_build_fallback',
                        $error->getMessage(),
                        413
                    );
                }
                $token = bin2hex(random_bytes(8));
                $staging = $this->private_storage_dir() . '/.workspace-delta-' . $token;
                $backup = $this->private_storage_dir() . '/.workspace-delta-backup-' . $token;
                $previous_options = [
                    'kodety_draft_updated_at' => get_option('kodety_draft_updated_at', ''),
                    'kodety_workspace_revision' => get_option('kodety_workspace_revision', 0),
                    'kodety_workspace_css_digest' => get_option('kodety_workspace_css_digest', ''),
                    self::PROJECT_DELTA_RECEIPTS_OPTION => get_option(self::PROJECT_DELTA_RECEIPTS_OPTION, []),
                ];
                if ($workspace_locator === 'workspace') {
                    $previous_options['kodety_project_name'] = get_option('kodety_project_name', '');
                    $previous_options['kodety_workspace_project_id'] = get_option('kodety_workspace_project_id', '');
                }
                $swapped = false;
                $journal_written = false;
                try {
                    $this->clone_project_delta_workspace_tree($workspace, $staging);
                    // sanitizeProjectPriorities() hydrates coded-build before
                    // Membership in the browser. Preserve that exact ordering
                    // so the server and acknowledged snapshots have identical
                    // page/asset precedence when both features are enabled.
                    $this->hydrate_project_delta_coded_workspace($staging, $coded_build_manifest);
                    // The live authoring copy is sealed at rest. Open it only in
                    // disposable staging so unchanged private HTML/assets remain
                    // part of the complete project validated below.
                    $staging_root = $this->collapse_single_root($staging);
                    $membership_root = is_file($staging_root . '/.incode/membership/runtime.json')
                        ? $staging_root
                        : null;
                    if (is_string($membership_root)) {
                        // Delta paths are calculated after the browser hydrates
                        // Membership: private editorHtml replaces the scrubbed
                        // page, protected blobs return to sourcePath and the
                        // transport runtime disappears. Reconstruct that same
                        // authoring graph before validating/applying operations.
                        // Keep the resolved root because a wrapper project also
                        // upserts `.incode/project.json` at the container root,
                        // after which collapse_single_root() intentionally no
                        // longer points at the Membership directory.
                        $this->open_membership_artifact_for_transport($membership_root);
                        $this->hydrate_membership_workspace($membership_root);
                    }
                    // Builder deltas describe the exact ZIP/file graph, while
                    // Settings/Analytics surfaces intentionally expose paths
                    // relative to the collapsed authored root. Keep both
                    // contracts explicit so a wrapper project cannot receive
                    // duplicate HTML or `.incode` files at its outer root.
                    $delta_root = $project_relative_delta ? $staging_root : $staging;
                    $this->assert_project_delta_manifest($delta_root, $payload);
                    $this->apply_project_delta_operations($delta_root, $payload);
                    $this->assert_project_delta_tree($staging);

                    // Reuse every semantic pass from ZIP activation. Shopify
                    // previews remain byte-identical when their authored map is
                    // present; missing maps are rebuilt inside copied text files.
                    $this->prepare_shopify_theme_workspace($staging);
                    $workspace_html_files = $this->find_html_files($staging);
                    if (!$workspace_html_files) throw new DomainException('O projeto não contém páginas HTML.');
                    try {
                        Kodety_Edition::assert_project_collection_connections(
                            $workspace_html_files,
                            array_column($this->collection_definitions(), 'slug')
                        );
                    } catch (Throwable $error) {
                        throw new DomainException($error->getMessage(), 0, $error);
                    }
                    if ($this->directory_contains_component_studio($staging)) {
                        throw new DomainException('O canvas temporário de um componente não pode substituir o workspace.');
                    }
                    $staging_root = $this->collapse_single_root($staging);
                    $this->assert_project_localization_metadata($staging_root);
                    $membership_commit_root = is_string($membership_root) && is_dir($membership_root)
                        ? $membership_root
                        : $staging_root;
                    // A normal Builder draft now has no Membership transport
                    // artifact, matching the established ZIP autosave graph;
                    // these calls are therefore no-ops. If a compatible client
                    // explicitly supplies a fresh artifact, seal it at the
                    // project root resolved before wrapper metadata changed.
                    $this->seal_membership_assets($membership_commit_root);
                    $this->seal_membership_artifact($membership_commit_root);
                    if (!hash_equals($membership_commit_root, $staging_root)) {
                        // Also cover an artifact explicitly introduced at the
                        // container root by this transaction. A wrapper must
                        // not create an unsealed second Membership boundary.
                        $this->seal_membership_assets($staging_root);
                        $this->seal_membership_artifact($staging_root);
                    }
                    $this->assert_project_delta_tree($staging);
                    $this->write_preview_file_manifest($staging_root);

                    $workspace_digest = $this->css_digest_from_directory($staging);
                    $project_name = $this->project_name_from_directory($staging);
                    $project_id = $this->project_id_from_directory($staging);
                    $saved_at = current_time('c');
                    $next_revision = $current_revision + 1;
                    $ack = [
                        'success' => true,
                        'savedAt' => $saved_at,
                        'projectName' => $project_name,
                        'projectId' => $project_id,
                        'workspaceRevision' => $next_revision,
                        'cssDigest' => $workspace_digest,
                        'transport' => 'delta',
                    ];

                    $this->write_project_delta_journal([
                        'version' => 1,
                        'workspaceLocator' => $workspace_locator,
                        'requestId' => $payload['requestId'],
                        'fingerprint' => $fingerprint,
                        'staging' => basename($staging),
                        'backup' => basename($backup),
                        'previousDigest' => $current_digest,
                        'nextDigest' => $workspace_digest,
                        'nextRevision' => $next_revision,
                        'previousOptions' => $previous_options,
                        'ack' => $ack,
                    ]);
                    $journal_written = true;
                    if (!rename($workspace, $backup)) {
                        throw new RuntimeException('Não foi possível preparar a troca incremental do workspace.');
                    }
                    if (!rename($staging, $workspace)) {
                        if (!rename($backup, $workspace)) {
                            throw new RuntimeException('O staging falhou e o workspace anterior exige recuperação manual.');
                        }
                        throw new RuntimeException('Não foi possível ativar o staging incremental.');
                    }
                    $swapped = true;
                    update_option('kodety_draft_updated_at', $saved_at, false);
                    update_option('kodety_workspace_revision', $next_revision, false);
                    update_option('kodety_workspace_css_digest', $workspace_digest, false);
                    // A shared Agency request can be mounted on a snapshot that
                    // is not the owner's active workspace. Its identity lives in
                    // that snapshot/Agency registry and must not replace the
                    // active Builder's global name or Membership project id.
                    if ($workspace_locator === 'workspace') {
                        if ($project_name !== '') update_option('kodety_project_name', $project_name, false);
                        if ($project_id !== '') update_option('kodety_workspace_project_id', $project_id, false);
                    }
                    if (
                        (int) get_option('kodety_workspace_revision', -1) !== $next_revision
                        || !hash_equals($workspace_digest, (string) get_option('kodety_workspace_css_digest', ''))
                    ) {
                        throw new RuntimeException('O WordPress não confirmou a revisão incremental.');
                    }
                    if (!$this->remember_project_delta_receipt(
                        $payload['requestId'],
                        $fingerprint,
                        $workspace_locator,
                        $ack
                    )) {
                        throw new RuntimeException('O WordPress não confirmou o recibo idempotente do autosave.');
                    }
                    // A cache entry for the destination revision can survive an
                    // external filesystem/database restore. The revision and the
                    // CSS/HTML-only digest are not enough to prove that arbitrary
                    // assets in that ZIP match the workspace committed above.
                    // Invalidation is best effort because the workspace, options
                    // and idempotency receipt are already the durable authority.
                    try {
                        @unlink($this->project_zip_cache_path(
                            $next_revision,
                            $this->project_template_state_digest()
                        ));
                    } catch (Throwable) {
                        // download_project() rebuilds a missing cache on demand.
                    }
                    // The receipt and canonical options are now durable. Cache
                    // ZIPs are revision-keyed, so no stale archive can be read.
                    if (is_dir($backup)) $this->remove_tree($backup);
                    if (is_file($this->current_zip())) @unlink($this->current_zip());
                    if (!is_dir($backup)) {
                        try {
                            $this->clear_project_delta_journal();
                            $journal_written = false;
                        } catch (Throwable) {
                            // The ACK + revision and absence of the old backup
                            // prove the commit. A later locked request safely
                            // cleans the retained journal.
                        }
                    }
                    return $ack;
                } catch (Throwable $error) {
                    if ($swapped) {
                        if (is_dir($workspace)) $this->remove_tree($workspace);
                        $restored = is_dir($backup) && rename($backup, $workspace);
                        foreach ($previous_options as $option => $value) update_option($option, $value, false);
                        if (!$restored) {
                            throw new RuntimeException(
                                'O autosave incremental falhou e o workspace anterior exige recuperação manual.',
                                0,
                                $error
                            );
                        }
                    }
                    $rollback_options_confirmed = (int) get_option('kodety_workspace_revision', -1)
                            === (int) $previous_options['kodety_workspace_revision']
                        && hash_equals(
                            (string) $previous_options['kodety_workspace_css_digest'],
                            (string) get_option('kodety_workspace_css_digest', '')
                        )
                        && get_option(self::PROJECT_DELTA_RECEIPTS_OPTION, [])
                            === $previous_options[self::PROJECT_DELTA_RECEIPTS_OPTION];
                    if (
                        $journal_written
                        && is_dir($workspace)
                        && !is_dir($backup)
                        && $rollback_options_confirmed
                    ) {
                        $this->clear_project_delta_journal();
                        $journal_written = false;
                    }
                    throw $error;
                } finally {
                    if (is_dir($staging)) $this->remove_tree($staging);
                    if (!$swapped && is_dir($backup) && !is_dir($workspace)) @rename($backup, $workspace);
                }
            });
            if (is_wp_error($result)) return $result;
            $response = new WP_REST_Response($result);
            $response->header('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0');
            return $response;
        } catch (Throwable $error) {
            $invalid = $error instanceof DomainException;
            $data = ['status' => $invalid ? 422 : 503, 'retryable' => !$invalid];
            if ($invalid) {
                // Domain validation runs against disposable staging. Reaching
                // this catch means no swap happened or the previous workspace,
                // revision and digest were restored and confirmed. A full ZIP
                // retry is therefore safe and should be invisible to the user.
                $data['fallbackToZip'] = true;
                $data['safeToRetryAsZip'] = true;
            }
            return new WP_Error(
                $invalid ? 'kodety_invalid_project_delta' : 'kodety_project_delta_save_failed',
                $error->getMessage(),
                $data
            );
        }
    }

    /** Persist the small localization contract without re-uploading a project
     * that may contain hundreds of megabytes of media. HTML identity changes
     * still use the normal ZIP path; this endpoint is only for metadata-only
     * revisions selected by the localization client. */
    public function save_project_localization(WP_REST_Request $request): WP_REST_Response|WP_Error {
        if (!apply_filters('kodety_localization_extension_enabled', false)) {
            return new WP_Error('kodety_localization_unavailable', 'A extensão Multi-language não está ativa.', ['status' => 404]);
        }
        $lock_error = $this->project_draft_editor_lock_error($request);
        if ($lock_error) return $lock_error;
        $expected_revision = $this->expected_workspace_revision($request);
        if ($expected_revision === null) {
            return new WP_Error('kodety_localization_revision_required', 'A revisão atual do projeto é obrigatória.', ['status' => 400]);
        }
        $body = $request->get_body();
        if ($body === '' || strlen($body) > 64_000_000) {
            return new WP_Error('kodety_invalid_localization', 'A configuração de idiomas está vazia ou acima do limite.', ['status' => 400]);
        }
        $payload = json_decode($body, true);
        if (!is_array($payload) || !is_array($payload['localization'] ?? null)) {
            return new WP_Error('kodety_invalid_localization', 'A configuração de idiomas não contém JSON válido.', ['status' => 400]);
        }
        try {
            $result = $this->with_workspace_lock(function () use ($expected_revision, $payload): array|WP_Error {
                $current_revision = (int) get_option('kodety_workspace_revision', 0);
                if ($expected_revision !== $current_revision) return $this->workspace_conflict($current_revision);
                $workspace = $this->workspace_dir();
                if (!is_dir($workspace)) {
                    return new WP_Error('kodety_no_project', 'Nenhum projeto foi importado.', ['status' => 404]);
                }
                $metadata_path = rtrim($workspace, '/\\') . '/.incode/project.json';
                if (!is_file($metadata_path) || is_link($metadata_path)) {
                    throw new DomainException('Os metadados editáveis do projeto não estão disponíveis com segurança.');
                }
                $metadata_size = filesize($metadata_path);
                if (!is_int($metadata_size) || $metadata_size < 2 || $metadata_size > 64_000_000) {
                    throw new DomainException('Os metadados editáveis excedem o limite seguro de 64 MB.');
                }
                $metadata = json_decode((string) file_get_contents($metadata_path), true);
                if (!is_array($metadata)) {
                    throw new DomainException('Os metadados editáveis do projeto estão corrompidos.');
                }
                $metadata['localization'] = $payload['localization'];
                $this->assert_project_localization_metadata($workspace, $metadata);
                $encoded = wp_json_encode(
                    $metadata,
                    JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
                );
                if (!is_string($encoded) || strlen($encoded) > 64_000_000) {
                    throw new DomainException('A configuração de idiomas excede o limite seguro de 64 MB.');
                }
                $temporary = dirname($metadata_path) . '/project.json.localization-' . bin2hex(random_bytes(6));
                try {
                    $written = file_put_contents($temporary, $encoded, LOCK_EX);
                    if ($written !== strlen($encoded) || !rename($temporary, $metadata_path)) {
                        throw new RuntimeException('A configuração de idiomas não pôde ser gravada integralmente.');
                    }
                } finally {
                    if (is_file($temporary)) @unlink($temporary);
                }
                $saved_at = current_time('c');
                $next_revision = $current_revision + 1;
                update_option('kodety_draft_updated_at', $saved_at, false);
                update_option('kodety_workspace_revision', $next_revision, false);
                return compact('saved_at', 'next_revision');
            });
            if (is_wp_error($result)) return $result;
            $response = new WP_REST_Response([
                'success' => true,
                'savedAt' => $result['saved_at'],
                'workspaceRevision' => $result['next_revision'],
                'cssDigest' => (string) get_option('kodety_workspace_css_digest', ''),
            ]);
            $response->header('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0');
            return $response;
        } catch (Throwable $error) {
            $invalid = $error instanceof DomainException;
            return new WP_Error(
                $invalid ? 'kodety_invalid_localization' : 'kodety_localization_save_failed',
                $error->getMessage(),
                ['status' => $invalid ? 422 : 503, 'retryable' => !$invalid]
            );
        }
    }

    /** Receive a large draft as bounded requests so common 64 MB reverse-proxy
     * and PHP request limits do not reject an otherwise valid coded project. */
    public function save_project_draft_chunk(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $admin_import = trim((string) $request->get_header('x-kodety-admin-import')) === '1';
        $import_revision = (int) get_option('kodety_workspace_revision', 0);
        if ($admin_import) {
            if (!current_user_can('kodety_import') || !$this->can_publish()) {
                return new WP_Error('kodety_import_forbidden', 'Sem permissão para importar este projeto.', ['status' => 403]);
            }
            $lock_error = $this->admin_import_editor_lock_error($request);
            if ($lock_error) return $lock_error;
        }
        $lock_error = $this->project_draft_editor_lock_error($request);
        if ($lock_error) return $lock_error;
        $upload_id = strtolower(trim((string) $request->get_header('x-kodety-upload-id')));
        $raw_offset = trim((string) $request->get_header('x-kodety-upload-offset'));
        $raw_total = trim((string) $request->get_header('x-kodety-upload-total'));
        if (!preg_match('/^[a-f0-9]{32}$/', $upload_id)
            || !preg_match('/^(?:0|[1-9][0-9]*)$/', $raw_offset)
            || !preg_match('/^[1-9][0-9]*$/', $raw_total)) {
            return new WP_Error('kodety_invalid_draft_chunk', 'Os metadados do upload em partes são inválidos.', ['status' => 400]);
        }
        $offset = (int) $raw_offset;
        $total = (int) $raw_total;
        $body = $request->get_body();
        $chunk_size = strlen($body);
        if ($total > self::PROJECT_ARCHIVE_MAX_BYTES
            || $chunk_size < 1
            || $chunk_size > self::PROJECT_DRAFT_CHUNK_MAX_BYTES
            || $offset < 0
            || $offset > $total
            || $offset + $chunk_size > $total) {
            return new WP_Error('kodety_invalid_draft_chunk', 'Esta parte do ZIP está vazia ou acima do limite.', ['status' => 400]);
        }

        $upload_path = '';
        $upload_meta_path = '';
        $complete = false;
        try {
            $this->ensure_directories();
            $upload_directory = $this->private_storage_dir() . '/draft-uploads';
            if ((!is_dir($upload_directory) && !wp_mkdir_p($upload_directory)) || !is_dir($upload_directory)) {
                throw new RuntimeException('Não foi possível preparar o upload em partes.');
            }
            foreach (glob($upload_directory . '/draft-*.part') ?: [] as $stale) {
                $modified = is_file($stale) ? (int) (@filemtime($stale) ?: 0) : 0;
                if ($modified > 0 && $modified < time() - self::PROJECT_DRAFT_UPLOAD_MAX_AGE) {
                    @unlink($stale);
                    @unlink($stale . '.json');
                }
            }
            $upload_path = $upload_directory . '/draft-' . get_current_user_id() . '-' . $upload_id . '.part';
            $upload_meta_path = $upload_path . '.json';
            $handle = @fopen($upload_path, 'c+b');
            if (!$handle || !flock($handle, LOCK_EX)) {
                if (is_resource($handle)) fclose($handle);
                throw new RuntimeException('Não foi possível bloquear o upload em partes.');
            }
            try {
                if ($admin_import) {
                    // Keep the first request's revision across retries and all
                    // chunks. Reading it only at completion would overwrite any
                    // Settings/Language edits committed during the upload.
                    $metadata = is_file($upload_meta_path)
                        ? json_decode((string) file_get_contents($upload_meta_path), true)
                        : null;
                    if ($metadata === null && $offset === 0 && !is_file($upload_meta_path)) {
                        $metadata = ['expectedRevision' => $import_revision, 'total' => $total];
                        if (file_put_contents($upload_meta_path, wp_json_encode($metadata), LOCK_EX) === false) {
                            throw new RuntimeException('Não foi possível preservar a revisão inicial da importação.');
                        }
                    }
                    if (!is_array($metadata) || !is_int($metadata['expectedRevision'] ?? null) || ($metadata['total'] ?? null) !== $total) {
                        throw new DomainException('A revisão inicial deste upload não está disponível. Reinicie a importação; o projeto atual foi preservado.', 409);
                    }
                    $import_revision = $metadata['expectedRevision'];
                }
                $stat = fstat($handle);
                $stored = (int) ($stat['size'] ?? 0);
                if ($offset === 0) {
                    if (!ftruncate($handle, 0)) throw new RuntimeException('Não foi possível reiniciar o upload em partes.');
                    $stored = 0;
                }
                if ($stored !== $offset || fseek($handle, $offset) !== 0) {
                    return new WP_Error(
                        'kodety_draft_chunk_conflict',
                        'Uma parte do ZIP chegou fora de ordem. O Builder tentará o upload novamente.',
                        ['status' => 409, 'expectedOffset' => $stored]
                    );
                }
                $written = fwrite($handle, $body);
                if ($written !== $chunk_size || !fflush($handle)) {
                    throw new RuntimeException('O servidor não conseguiu gravar uma parte completa do ZIP.');
                }
                $complete = $offset + $chunk_size === $total;
            } finally {
                flock($handle, LOCK_UN);
                fclose($handle);
            }
            clearstatcache(true, $upload_path);
            $received = (int) (@filesize($upload_path) ?: 0);
            if ($received !== $offset + $chunk_size) {
                throw new RuntimeException('O upload em partes divergiu durante a gravação.');
            }
            if (!$complete) {
                $response = new WP_REST_Response([
                    'success' => true,
                    'complete' => false,
                    'received' => $received,
                    'total' => $total,
                ]);
                $response->header('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0');
                return $response;
            }
            if ($received !== $total) throw new RuntimeException('O ZIP em partes chegou incompleto.');
            if ($admin_import) return $this->complete_chunked_admin_import($upload_path, $request, $import_revision);
            $this->prepare_project_archive_request();
            return $this->persist_project_draft_archive($upload_path, $request);
        } catch (Throwable $error) {
            if ($upload_path !== '' && is_file($upload_path)) @unlink($upload_path);
            if ($upload_meta_path !== '' && is_file($upload_meta_path)) @unlink($upload_meta_path);
            $conflict = $error instanceof DomainException && $error->getCode() === 409;
            return new WP_Error($conflict ? 'kodety_workspace_conflict' : 'kodety_draft_chunk_failed', $error->getMessage(), ['status' => $conflict ? 409 : 500]);
        } finally {
            if ($complete && $upload_path !== '' && is_file($upload_path)) @unlink($upload_path);
            if ($complete && $upload_meta_path !== '' && is_file($upload_meta_path)) @unlink($upload_meta_path);
        }
    }

    /** Finish the wp-admin import only after every bounded request has reached
     * the private staging file. This keeps the existing replacement checks and
     * agency routing without sending the complete ZIP through PHP multipart. */
    private function complete_chunked_admin_import(
        string $upload_path,
        WP_REST_Request $request,
        int $expected_revision
    ): WP_REST_Response|WP_Error {
        try {
            $encoded_name = trim((string) $request->get_header('x-kodety-original-name'));
            $original_name = sanitize_file_name(rawurldecode($encoded_name)) ?: 'site.zip';
            if (!str_ends_with(strtolower($original_name), '.zip')) {
                throw new RuntimeException('O projeto deve ser enviado em um arquivo ZIP.');
            }

            $agency_mode = $this->workspace_mode() === 'agency';
            $agency_target = '';
            $target_has_project = $this->has_workspace();
            if ($agency_mode) {
                if ($this->has_workspace() && $this->agency_active_project_id() === '') {
                    $this->agency_register_current_project();
                }
                $projects = $this->agency_projects();
                $agency_target = sanitize_key((string) $request->get_header('x-kodety-agency-target'));
                if ($agency_target === '') $agency_target = (string) $this->agency_active_project_id();
                if ($agency_target === '') $agency_target = (string) array_key_first($projects);
                if ($agency_target === '') $agency_target = 'new-project';
                if ($agency_target !== 'new-project' && !isset($projects[$agency_target])) {
                    throw new RuntimeException('O projeto escolhido não existe mais. Selecione outro destino.');
                }
                $target_has_project = $agency_target !== 'new-project';
            }

            if ($target_has_project) {
                $acknowledged = trim((string) $request->get_header('x-kodety-replace-acknowledged')) === '1';
                $phrase = rawurldecode(trim((string) $request->get_header('x-kodety-replace-phrase')));
                if (!$acknowledged || !hash_equals('SUBSTITUIR', $phrase)) {
                    throw new RuntimeException('A substituição foi cancelada. Confirme as perdas e digite SUBSTITUIR.');
                }
            }

            $shopify_theme_import = $this->zip_contains_shopify_theme($upload_path);
            if ($agency_mode) {
                $new_project_name = substr(sanitize_text_field(rawurldecode(trim(
                    (string) $request->get_header('x-kodety-new-project-name')
                ))), 0, 120);
                $this->agency_stage_builder_import(
                    $agency_target,
                    $upload_path,
                    $original_name,
                    $new_project_name
                );
            } else {
                $this->stage_builder_import($upload_path, $original_name, false, $expected_revision, $request);
            }

            $response = new WP_REST_Response([
                'success' => true,
                'complete' => true,
                'redirectUrl' => add_query_arg(
                    $shopify_theme_import ? 'kodety_shopify_theme' : 'kodety_open_publish',
                    '1',
                    home_url('/kodety/editor/')
                ),
            ]);
            $response->header('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0');
            return $response;
        } catch (Throwable $error) {
            $conflict = $error instanceof DomainException && $error->getCode() === 409;
            return new WP_Error($conflict ? 'kodety_workspace_conflict' : 'kodety_chunked_import_failed', $error->getMessage(), ['status' => $conflict ? 409 : 400, 'currentRevision' => (int) get_option('kodety_workspace_revision', 0)]);
        }
    }

    private function persist_project_draft_archive(
        string $temporary,
        WP_REST_Request $request
    ): WP_REST_Response|WP_Error {
        $expected_revision = $this->expected_workspace_revision($request);
        if ($expected_revision === null) {
            return new WP_Error('kodety_draft_revision_required', 'A revisão atual do projeto é obrigatória para salvar o rascunho.', ['status' => 400]);
        }
        try {
            if ($this->zip_contains_component_studio($temporary)) {
                throw new RuntimeException('O canvas temporário de um componente não pode substituir uma página do site. O rascunho anterior foi preservado.');
            }
            if (!class_exists('ZipArchive')) throw new RuntimeException('A extensão PHP ZipArchive precisa estar habilitada na hospedagem.');
            $zip = new ZipArchive();
            if ($zip->open($temporary) !== true) throw new RuntimeException('O rascunho recebido não é um ZIP válido.');
            $has_html = false;
            try {
                if ($zip->numFiles > 10000) throw new RuntimeException('O projeto possui arquivos demais.');
                for ($index = 0; $index < $zip->numFiles; $index++) {
                    $stat = $zip->statIndex($index);
                    $name = str_replace('\\', '/', (string) ($stat['name'] ?? ''));
                    $normalized = ltrim($name, '/');
                    if ($normalized === '' || str_contains($normalized, '../') || str_contains($normalized, "\0")) {
                        throw new RuntimeException('O projeto contém um caminho inseguro.');
                    }
                    if (preg_match('/\.html?$/i', $normalized)) $has_html = true;
                }
            } finally {
                $zip->close();
            }
            if (!$has_html) throw new RuntimeException('O projeto não contém páginas HTML.');
            $actual_css_digest = $this->css_digest_from_zip($temporary);
            $expected_css_digest = $this->expected_css_digest($request);
            if ($expected_css_digest !== null && !hash_equals($expected_css_digest, $actual_css_digest)) {
                throw new RuntimeException('O ZIP recebido não contém o mesmo CSS do editor. O rascunho anterior foi preservado.');
            }
            $actual_project_digest = $this->project_digest_from_zip($temporary);
            $expected_project_digest = $this->expected_project_digest($request);
            if ($expected_project_digest !== null && !hash_equals($expected_project_digest, $actual_project_digest)) {
                throw new RuntimeException('O ZIP recebido não contém a mesma árvore de arquivos do editor. O rascunho anterior foi preservado.');
            }
            $restore_template = trim((string) $request->get_header('x-kodety-template-import')) === '1';
            $result = $this->with_workspace_lock(function () use (
                $temporary,
                $expected_revision,
                $actual_css_digest,
                $actual_project_digest,
                $expected_project_digest,
                $restore_template
            ): array|WP_Error {
                $current_revision = (int) get_option('kodety_workspace_revision', 0);
                if ($expected_revision !== $current_revision) {
                    return $this->workspace_conflict($current_revision);
                }
                $workspace = $this->activate_workspace_from_zip(
                    $temporary,
                    $actual_css_digest,
                    $restore_template,
                    $expected_project_digest
                );
                // Draft autosave only replaces native workspace files. Scanning,
                // hashing, copying and generating WordPress thumbnails for every
                // image here made a single inspector change process the complete
                // imported site. Media registration belongs to explicit Publish.
                $project_name = $this->project_name_from_directory($workspace);
                if ($project_name !== '') update_option('kodety_project_name', $project_name, false);
                $project_id = $this->project_id_from_directory($workspace);
                if ($project_id !== '') update_option('kodety_workspace_project_id', $project_id, false);
                $saved_at = current_time('c');
                $next_revision = $current_revision + 1;
                $workspace_digest = $this->css_digest_from_directory($workspace);
                update_option('kodety_draft_updated_at', $saved_at, false);
                update_option('kodety_workspace_revision', $next_revision, false);
                update_option('kodety_workspace_css_digest', $workspace_digest, false);
                // Invalidate the destination revision before releasing the
                // lock. A cache left by a database/filesystem restore must not
                // make the next open return a tree older than this ACK.
                try {
                    @unlink($this->project_zip_cache_path(
                        $next_revision,
                        $this->project_template_state_digest()
                    ));
                } catch (Throwable) {
                    // Download rebuilds a missing cache from the live workspace.
                }
                $project_digest = $actual_project_digest;
                // Written before releasing the same lock as activation/revision.
                // Any later writer advancing the revision invalidates this proof.
                update_option('kodety_workspace_upload_receipt', [
                    'projectId' => $project_id,
                    'projectDigest' => $project_digest,
                    'workspaceRevision' => $next_revision,
                ], false);
                return compact('project_name', 'project_id', 'saved_at', 'next_revision', 'workspace_digest', 'project_digest');
            });
            if (is_wp_error($result)) return $result;
            // Autosave already sent a complete editable ZIP. Keep it as the
            // revision-keyed response for the next project opening, otherwise
            // every saved inspector change forces WordPress to recompress the
            // whole workspace before the canvas can render again.
            try {
                $template_manifest = $this->project_template_manifest_json();
                $this->write_project_zip_cache_from_file(
                    (int) $result['next_revision'],
                    hash('sha256', $template_manifest),
                    $temporary,
                    $template_manifest
                );
            } catch (Throwable) {
                // A cache failure cannot turn a confirmed workspace save into
                // an error; download_project() retains its rebuild fallback.
            }
            $response = new WP_REST_Response([
                'success' => true,
                'savedAt' => $result['saved_at'],
                'projectName' => $result['project_name'],
                'projectId' => $result['project_id'],
                'workspaceRevision' => $result['next_revision'],
                'cssDigest' => $result['workspace_digest'],
                'projectDigest' => $result['project_digest'],
            ]);
            $response->header('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0');
            return $response;
        } catch (Throwable $error) {
            $localization_error = $error instanceof DomainException;
            return new WP_Error(
                $localization_error ? 'kodety_invalid_localization' : 'kodety_draft_save_failed',
                $error->getMessage(),
                ['status' => $localization_error ? 422 : 500]
            );
        }
    }

    public function publish_project(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $this->prepare_project_archive_request();
        $publish_saved_workspace = trim((string) $request->get_header('x-kodety-publish-workspace')) === '1';
        $publish_materialized = trim((string) $request->get_header('x-kodety-publish-materialized')) === '1';
        $publish_materialized_overlay = trim((string) $request->get_header('x-kodety-publish-materialized-overlay')) === '1';
        $publish_snapshot = trim((string) $request->get_header('x-kodety-publish-snapshot')) === '1';
        if ($publish_saved_workspace && $publish_materialized) {
            return new WP_Error('kodety_invalid_publish_mode', 'Escolha apenas uma origem para a publicação.', ['status' => 400]);
        }
        if ($publish_materialized_overlay && !$publish_materialized) {
            return new WP_Error('kodety_invalid_publish_overlay', 'O overlay exige uma publicação materializada.', ['status' => 400]);
        }
        if ($publish_snapshot && (!$publish_materialized || $publish_materialized_overlay)) {
            return new WP_Error(
                'kodety_invalid_publish_snapshot',
                'A publicação resiliente exige um pacote materializado completo.',
                ['status' => 400]
            );
        }
        $body = $request->get_body();
        $publish_body_limit = $publish_materialized_overlay
            ? self::PROJECT_DELTA_MAX_BODY_BYTES + self::MATERIALIZED_PUBLISH_OVERLAY_MANIFEST_MAX_BYTES
            : self::PROJECT_ARCHIVE_MAX_BYTES;
        if (!$publish_saved_workspace && ($body === '' || strlen($body) > $publish_body_limit)) {
            return new WP_Error('kodety_invalid_zip', 'ZIP vazio ou acima do limite.', ['status' => 400]);
        }
        $expected_css_digest = $this->expected_css_digest($request);
        $expected_revision = $this->expected_workspace_revision($request);
        if ($expected_revision === null) {
            return new WP_Error('kodety_publish_revision_required', 'A revisão atual do projeto é obrigatória para publicar sem sobrescrever alterações concorrentes.', ['status' => 400]);
        }
        $source_css_digest_header = strtolower(trim((string) $request->get_header('x-kodety-source-css-digest')));
        $source_css_digest = preg_match('/^[a-f0-9]{64}$/', $source_css_digest_header)
            ? $source_css_digest_header
            : null;
        $requested_workspace_project_id = $this->normalize_project_id(
            $request->get_header('x-kodety-workspace-project-id')
        );
        $invalid_confirmed_workspace_publish = !$publish_snapshot
            && ($publish_saved_workspace || $publish_materialized)
            && (
                $expected_css_digest === null
                || $expected_revision === null
                || ($publish_materialized && $source_css_digest === null)
            );
        $invalid_publish_snapshot = $publish_snapshot && $expected_css_digest === null;
        if ($invalid_confirmed_workspace_publish || $invalid_publish_snapshot) {
            return new WP_Error(
                'kodety_invalid_workspace_publish',
                $publish_snapshot
                    ? 'A publicação resiliente exige a integridade do pacote atual.'
                    : 'A publicação da revisão salva exige revisão e integridade confirmadas pelo WordPress.',
                ['status' => 400]
            );
        }
        $temporary = null;
        $actual_css_digest = null;
        $snapshot_project_id = '';
        try {
            if (!$publish_saved_workspace) {
                $temporary = tempnam(get_temp_dir(), 'kodety-publish-');
                if (!$temporary || file_put_contents($temporary, $body, LOCK_EX) === false) {
                    throw new RuntimeException('Não foi possível preparar a publicação.');
                }
                if (!$publish_materialized_overlay) {
                    if ($this->zip_contains_component_studio($temporary)) {
                        throw new RuntimeException('Publicação bloqueada: um canvas temporário de componente foi encontrado no lugar de uma página.');
                    }
                    $actual_css_digest = $this->css_digest_from_zip($temporary);
                    if ($expected_css_digest !== null && !hash_equals($expected_css_digest, $actual_css_digest)) {
                        throw new RuntimeException('O ZIP de publicação não contém o mesmo CSS do editor. Nada foi publicado.');
                    }
                    if ($publish_snapshot) {
                        $snapshot_project_id = $this->project_id_from_zip($temporary);
                        if (
                            $requested_workspace_project_id === ''
                            || $snapshot_project_id === ''
                            || !hash_equals($requested_workspace_project_id, $snapshot_project_id)
                        ) {
                            return new WP_Error(
                                'kodety_publish_snapshot_project_invalid',
                                'O snapshot não confirmou a identidade do projeto aberto.',
                                ['status' => 412]
                            );
                        }
                    }
                }
            }
            $raw_optimizations = $request->get_param('optimizations');
            if (is_string($raw_optimizations)) $raw_optimizations = json_decode($raw_optimizations, true);
            $optimizations = is_array($raw_optimizations) && ($raw_optimizations['version'] ?? null) === Kodety_Publication_Optimizer::VERSION
                ? Kodety_Publication_Optimizer::normalize($raw_optimizations)
                : $this->optimization_settings();
            $expected_optimization_revision = is_string($raw_optimizations['expectedRevision'] ?? null)
                ? $raw_optimizations['expectedRevision']
                : Kodety_Publication_Optimizer::revision($this->optimization_settings());
            $request_id = $this->publish_request_id($request);
            $encoded_optimizations = wp_json_encode($optimizations);
            $archive_digest = $publish_saved_workspace
                ? 'workspace:' . $expected_revision . ':' . $expected_css_digest
                : hash_file('sha256', (string) $temporary);
            $request_fingerprint = hash(
                'sha256',
                (is_string($archive_digest) ? $archive_digest : '')
                . "\0"
                . (is_string($encoded_optimizations) ? $encoded_optimizations : '')
            );
            $result = $this->with_workspace_lock(function () use (
                $temporary,
                $publish_saved_workspace,
                $publish_materialized,
                $publish_materialized_overlay,
                $publish_snapshot,
                $snapshot_project_id,
                $optimizations,
                $expected_optimization_revision,
                $expected_revision,
                $actual_css_digest,
                $expected_css_digest,
                $source_css_digest,
                $request_id,
                $request_fingerprint,
                $requested_workspace_project_id
            ): array|WP_Error {
                $receipt = $this->publish_receipt($request_id, $request_fingerprint);
                if ($receipt !== null) return array_merge($receipt, ['replayed' => true]);
                $current_optimizations = $this->optimization_settings();
                if ($current_optimizations !== $optimizations && !hash_equals(Kodety_Publication_Optimizer::revision($current_optimizations), $expected_optimization_revision)) {
                    return new WP_Error('kodety_optimization_conflict', 'As otimizações mudaram em outra janela. Reabra o menu de publicação antes de publicar.', ['status'=>409]);
                }
                $current_revision = (int) get_option('kodety_workspace_revision', 0);
                if ($publish_snapshot) {
                    $current_project_id = $this->normalize_project_id(
                        get_option('kodety_workspace_project_id', '')
                    );
                    if (
                        $current_project_id !== ''
                        && (
                            !hash_equals($current_project_id, $requested_workspace_project_id)
                            || !hash_equals($current_project_id, $snapshot_project_id)
                        )
                    ) {
                        return new WP_Error(
                            'kodety_publish_snapshot_project_changed',
                            'Outro projeto foi aberto antes da publicação. Volte ao projeto correto e publique novamente.',
                            ['status' => 412]
                        );
                    }
                }
                if ($expected_revision !== $current_revision) {
                    return $this->workspace_conflict($current_revision);
                }
                if ($publish_materialized && !$publish_snapshot) {
                    $confirmed_workspace_digest = (string) get_option('kodety_workspace_css_digest', '');
                    if (
                        $source_css_digest === null
                        || !preg_match('/^[a-f0-9]{64}$/', $confirmed_workspace_digest)
                        || !hash_equals($source_css_digest, $confirmed_workspace_digest)
                    ) {
                        return new WP_Error(
                            'kodety_workspace_digest_conflict',
                            'A revisão editável mudou antes da publicação. O Builder preservou a versão mais recente.',
                            ['status' => 409, 'currentRevision' => $current_revision]
                        );
                    }
                }
                $publish_path = $temporary;
                $publish_digest = $actual_css_digest;
                $remove_publish_path = false;
                try {
                    if ($publish_saved_workspace || $publish_materialized_overlay) {
                        $workspace = $this->workspace_dir();
                        if (!is_dir($workspace)) {
                            return new WP_Error('kodety_no_project', 'Nenhum projeto foi importado.', ['status' => 404]);
                        }
                        if ($publish_saved_workspace) {
                            $confirmed_workspace_digest = (string) get_option('kodety_workspace_css_digest', '');
                            if (
                                $expected_css_digest === null
                                || !preg_match('/^[a-f0-9]{64}$/', $confirmed_workspace_digest)
                                || !hash_equals($expected_css_digest, $confirmed_workspace_digest)
                            ) {
                                return new WP_Error(
                                    'kodety_workspace_digest_conflict',
                                    'A revisão salva mudou antes da publicação. O editor preservou a versão mais recente.',
                                    ['status' => 409, 'currentRevision' => $current_revision]
                                );
                            }
                        }
                        // Download caches are an opening-performance optimization,
                        // not publication authority. Package the live directory
                        // while holding the workspace lock so every acknowledged
                        // file (JS, JSON, media and metadata included) reaches the
                        // release even if a same-revision cache is stale.
                        $publish_path = $this->package_editable_workspace_as_zip(
                            $workspace,
                            'kodety-publish-workspace-'
                        );
                        $remove_publish_path = true;
                        if ($publish_materialized_overlay) {
                            if (!is_string($temporary) || $temporary === '') {
                                throw new RuntimeException('O overlay materializado não está disponível.');
                            }
                            $this->apply_materialized_publish_overlay_to_zip($publish_path, $temporary);
                        }
                        if ($this->zip_contains_component_studio($publish_path)) {
                            throw new RuntimeException('Publicação bloqueada: um canvas temporário de componente foi encontrado no lugar de uma página.');
                        }
                        $publish_digest = $this->css_digest_from_zip($publish_path);
                        if ($expected_css_digest === null || !hash_equals($expected_css_digest, $publish_digest)) {
                            throw new RuntimeException('A revisão salva não contém o mesmo CSS confirmado pelo editor. Nada foi publicado.');
                        }
                    }
                    if (!is_string($publish_path) || $publish_path === '' || !is_string($publish_digest)) {
                        throw new RuntimeException('Não foi possível preparar a publicação.');
                    }
                    // Saved-workspace publish is a read of the already-ACKed
                    // authoring state. Never re-import its transport package over
                    // that authority or advance the revision without an edit.
                    $preserve_editable_workspace = $publish_saved_workspace
                        || (
                            $publish_materialized
                            && (!$publish_snapshot || is_dir($this->workspace_dir()))
                        );
                    $release = $this->install_zip(
                        $publish_path,
                        'kodety-editor.zip',
                        $optimizations,
                        $publish_digest,
                        $preserve_editable_workspace
                    );
                    // Persist preferences only after the new release received
                    // its activation checkpoint. Pre-install writes would make
                    // a rejected/colliding archive mutate otherwise unchanged
                    // publication state.
                    update_option('kodety_optimization_settings', $optimizations, false);
                    $published_at = current_time('c');
                    $next_revision = (int) get_option('kodety_workspace_revision', $current_revision + 1);
                    update_option('kodety_last_published_at', $published_at, false);
                    $sync_pending = !empty($this->last_publish_sync_report['syncPending']);
                    $warnings = array_values(array_filter(array_map(
                        'strval',
                        is_array($this->last_publish_sync_report['warnings'] ?? null)
                            ? $this->last_publish_sync_report['warnings']
                            : []
                    )));
                    if ($publish_snapshot) {
                        $warnings[] = 'A release entrou no ar sem aguardar o rascunho concorrente; o Builder continuará a reconciliação em segundo plano.';
                    }
                    $warnings = array_values(array_unique($warnings));
                    $confirmed = compact('release', 'published_at', 'next_revision', 'sync_pending', 'warnings');
                    $confirmed['css_digest'] = $publish_digest;
                    $confirmed['theme_stylesheet'] = (string) wp_get_theme()->get_stylesheet();
                    $confirmed['replayed'] = false;
                    // The release is already online. Failure to retain this small
                    // deduplication receipt cannot roll it back; it only removes
                    // the optimization for a response-lost retry.
                    $this->remember_publish_receipt($request_id, $request_fingerprint, $confirmed);
                    return $confirmed;
                } finally {
                    if ($remove_publish_path && is_string($publish_path) && $publish_path !== '') @unlink($publish_path);
                }
            });
            if (is_wp_error($result)) return $result;
            $response = new WP_REST_Response([
                'success' => true,
                'publicationComplete' => !$result['sync_pending'],
                'releaseOnline' => true,
                'syncPending' => $result['sync_pending'],
                'warnings' => $result['warnings'],
                'release' => $result['release'],
                'publishedAt' => $result['published_at'],
                'workspaceRevision' => $result['next_revision'],
                'cssDigest' => (string) ($result['css_digest'] ?? $actual_css_digest ?? ''),
                'optimizations' => $this->last_optimization_report,
                'replayed' => !empty($result['replayed']),
            ], $result['sync_pending'] ? 202 : 200);
            $response->header('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0');
            return $response;
        } catch (Throwable $error) {
            if ($error instanceof Kodety_Pro_Feature_Exception) {
                return new WP_Error(
                    'kodety_pro_feature_required',
                    $error->getMessage(),
                    [
                        'status' => 403,
                        'feature' => $error->feature(),
                        'licensed' => false,
                        'licenseUrl' => Kodety_Edition::license_url(),
                        'upgradeUrl' => Kodety_Edition::upgrade_url(),
                    ]
                );
            }
            // Filesystem, host and database failures may be transient. The
            // Builder retries with the same request id, so a lost successful
            // response replays its receipt instead of creating another release.
            return new WP_Error('kodety_publish_failed', $error->getMessage(), ['status' => 503]);
        } finally {
            if (is_string($temporary) && $temporary !== '') @unlink($temporary);
        }
    }

    /**
     * Materialize a draft build without activating a theme or changing the
     * public site. A stable, unguessable URL is reused across updates so it can
     * be shared for review while the directory underneath is swapped atomically.
     */
    public function create_project_preview(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $body = $request->get_body();
        if ($body === '' || strlen($body) > self::PROJECT_ARCHIVE_MAX_BYTES) {
            return new WP_Error('kodety_invalid_preview_zip', 'ZIP vazio ou acima do limite.', ['status' => 400]);
        }
        $temporary = null;
        try {
            $temporary = tempnam(get_temp_dir(), 'kodety-preview-');
            if (!$temporary || file_put_contents($temporary, $body, LOCK_EX) === false) {
                throw new RuntimeException('Não foi possível preparar o preview.');
            }
            if ($this->zip_contains_component_studio($temporary)) {
                throw new RuntimeException('Preview bloqueado: um canvas temporário de componente substituiu uma página.');
            }
            $archive_digest = hash_file('sha256', $temporary) ?: '';
            $result = $this->with_workspace_lock(function () use ($temporary, $archive_digest): array {
                $this->ensure_directories();
                $preview_dir = $this->private_storage_dir() . '/preview';
                $target = $preview_dir . '/project';
                $next = $preview_dir . '/project.next';
                $previous = $preview_dir . '/project.previous';
                wp_mkdir_p($preview_dir);
                if (is_dir($next)) $this->remove_tree($next);
                wp_mkdir_p($next);
                try {
                    $this->extract_safe_zip($temporary, $next);
                    $preview_html_files = $this->find_html_files($next);
                    if (!$preview_html_files) {
                        throw new RuntimeException('O pacote de preview não contém páginas HTML.');
                    }
                    Kodety_Edition::assert_project_collection_connections(
                        $preview_html_files,
                        array_column($this->collection_definitions(), 'slug')
                    );
                    if ($this->directory_contains_component_studio($next)) {
                        throw new RuntimeException('O pacote de preview contém um canvas temporário de componente.');
                    }
                    // The public theme receives this runtime during activation;
                    // draft previews bypass theme installation, so materialize
                    // the same form behavior into their isolated HTML copy.
                    if (class_exists('Kodety_Emails')) {
                        foreach ($this->find_html_files($next) as $html_file) {
                            $html = (string) file_get_contents($html_file);
                            $runtime_html = Kodety_Emails::inject_runtime($html);
                            if ($runtime_html !== $html) file_put_contents($html_file, $runtime_html, LOCK_EX);
                        }
                    }
                    $this->write_preview_file_manifest($next);
                    if (is_dir($previous)) $this->remove_tree($previous);
                    if (is_dir($target) && !rename($target, $previous)) {
                        throw new RuntimeException('Não foi possível preparar a versão anterior do preview.');
                    }
                    if (!rename($next, $target)) {
                        if (is_dir($previous)) rename($previous, $target);
                        throw new RuntimeException('Não foi possível ativar o preview.');
                    }
                    if (is_dir($previous)) $this->remove_tree($previous);
                } catch (Throwable $error) {
                    if (is_dir($next)) $this->remove_tree($next);
                    throw $error;
                }

                $token = (string) get_option('kodety_preview_token', '');
                if (!preg_match('/^[A-Za-z0-9_-]{24,80}$/', $token)) {
                    try {
                        $token = bin2hex(random_bytes(24));
                    } catch (Throwable) {
                        $token = wp_generate_password(48, false, false);
                    }
                    update_option('kodety_preview_token', $token, false);
                }
                $updated_at = current_time('c');
                update_option('kodety_preview_updated_at', $updated_at, false);
                update_option('kodety_preview_digest', $archive_digest, false);
                return compact('token', 'updated_at');
            });

            $response = new WP_REST_Response([
                'success' => true,
                'url' => trailingslashit(home_url('/kodety/preview/' . rawurlencode($result['token']))),
                'updatedAt' => $result['updated_at'],
                'digest' => $archive_digest,
            ]);
            $response->header('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0');
            return $response;
        } catch (Throwable $error) {
            return new WP_Error('kodety_preview_failed', $error->getMessage(), ['status' => 503]);
        } finally {
            if (is_string($temporary) && $temporary !== '') @unlink($temporary);
        }
    }

    /** Report native reconciliation independently from release activation so a
     * Builder that received HTTP 202 can observe cron completion without
     * uploading and activating another release. `resume=1` deliberately runs
     * at most one bounded attempt for hosts whose cron cannot make progress. */
    public function publish_status(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $release = $this->release_id($request->get_param('release'));
        $current_release = (string) get_option('kodety_current_release', '');
        if ($release === '' || $current_release === '' || !hash_equals($current_release, $release)) {
            return new WP_Error(
                'kodety_publish_release_changed',
                'A release ativa mudou enquanto a sincronização era acompanhada.',
                ['status' => 409, 'currentRelease' => $current_release]
            );
        }
        $assets_synced = (string) get_option('kodety_assets_synced_release', '') === $release;
        $pages_synced = (string) get_option('kodety_pages_synced_release', '') === $release;
        $native_sync_incomplete = !$assets_synced || !$pages_synced;
        $sync_error = $this->publish_sync_error($release);
        $sync_terminal = $native_sync_incomplete && !empty($sync_error['terminal']);
        $resume = $request->get_param('resume');
        $resume_requested = in_array($resume, [true, 1, '1', 'true'], true);
        $poll_resume_required = $this->publish_sync_requires_poll_resume($release);
        if ($native_sync_incomplete && !$sync_terminal && $resume_requested) {
            $attempt = min(
                self::PUBLISH_SYNC_RETRY_MAX_ATTEMPTS,
                max(0, (int) ($sync_error['attempt'] ?? 0)) + 1
            );
            // A direct poll overtakes this exact cron payload. Remove only that
            // event; other releases and later attempts remain isolated.
            $this->clear_publish_sync_retry_attempt($release, $attempt);
            $this->retry_publish_sync($release, $attempt, !$poll_resume_required);
            // Completion is proven only by durable ACK readback, never by the
            // callback returning without throwing.
            $assets_synced = (string) get_option('kodety_assets_synced_release', '') === $release;
            $pages_synced = (string) get_option('kodety_pages_synced_release', '') === $release;
            $native_sync_incomplete = !$assets_synced || !$pages_synced;
            $sync_error = $this->publish_sync_error($release);
            $sync_terminal = $native_sync_incomplete && !empty($sync_error['terminal']);
        }
        if (!$native_sync_incomplete && $sync_error !== []) {
            $this->clear_publish_sync_error($release);
            $sync_error = [];
        }
        $sync_pending = $native_sync_incomplete && !$sync_terminal;
        $warnings = [];
        if (!$assets_synced) $warnings[] = 'A Biblioteca de Mídia ainda está pendente.';
        if (!$pages_synced) $warnings[] = 'As páginas nativas ainda estão pendentes.';
        if (
            $native_sync_incomplete
            && trim((string) ($sync_error['message'] ?? '')) !== ''
        ) {
            $warnings[] = 'Última tentativa: ' . trim((string) $sync_error['message']);
        }
        if ($sync_terminal) {
            $warnings[] = 'A sincronização nativa falhou de forma terminal e não será repetida automaticamente.';
        }
        $response = new WP_REST_Response([
            'success' => !$sync_terminal,
            'publicationComplete' => !$native_sync_incomplete,
            'releaseOnline' => true,
            'syncPending' => $sync_pending,
            'syncFailed' => $sync_terminal,
            'syncStatus' => $sync_terminal ? 'failed' : ($sync_pending ? 'pending' : 'complete'),
            'syncRetryable' => $sync_pending,
            'syncCanResume' => $sync_pending,
            'syncResumeRequired' => $sync_pending && $poll_resume_required,
            'syncAttempt' => max(0, (int) ($sync_error['attempt'] ?? 0)),
            'syncMaxAttempts' => self::PUBLISH_SYNC_RETRY_MAX_ATTEMPTS,
            'warnings' => array_values(array_unique($warnings)),
            'release' => $release,
            'workspaceRevision' => (int) get_option('kodety_workspace_revision', 0),
            'cssDigest' => (string) get_option('kodety_workspace_css_digest', ''),
        ], $sync_terminal ? 500 : ($sync_pending ? 202 : 200));
        $response->header('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0');
        return $response;
    }

    public function purge_cache_rest(): WP_REST_Response {
        $this->purge_published_site_cache();
        $response = new WP_REST_Response([
            'success' => true,
            'purgedAt' => current_time('c'),
        ]);
        $response->header('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0');
        return $response;
    }

    /**
     * Beta project importer. Fetches an external URL on the server (avoiding
     * browser CORS/mixed-content limits) and returns either a ZIP export or a
     * cleaned, self-contained HTML page to authenticated API clients. The
     * Builder no longer loads this flow. The fetch is SSRF-guarded via
     * wp_http_validate_url() and hard size/time limits.
     */
    public function import_from_url(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $source_url = (string) $request->get_param('url');
        $rendered_html = (string) $request->get_param('renderedHtml');
        $requested_platform = strtolower(trim((string) $request->get_param('platform')));
        $framer_mode = strtolower(trim((string) $request->get_param('framerMode')));
        $elementor_mode = strtolower(trim((string) $request->get_param('elementorMode')));
        if (!in_array($framer_mode, ['animated', 'static'], true)) $framer_mode = 'animated';
        if (!in_array($elementor_mode, ['visual', 'native'], true)) $elementor_mode = 'visual';
        if (!in_array($requested_platform, ['auto', 'framer', 'webflow', 'elementor', 'code'], true)) $requested_platform = 'auto';
        if ($rendered_html !== '') {
            $result = $this->bundle_rendered_external_project($rendered_html, $source_url, $framer_mode);
            if (is_wp_error($result)) return $result;
            return new WP_REST_Response([
                'kind' => $result['kind'],
                'filename' => $result['filename'],
                'sourceUrl' => $result['sourceUrl'],
                'platform' => $result['platform'],
                'importMode' => $result['platform'] === 'elementor' ? $elementor_mode : null,
                'contentBase64' => base64_encode($result['content']),
            ]);
        }

        $capture_delay = (int) $request->get_param('captureDelay');
        if (!in_array($capture_delay, [0, 5, 10], true)) $capture_delay = 0;
        $capture_token = sanitize_text_field((string) $request->get_param('captureToken'));
        if ($capture_delay > 0 && !preg_match('~^[A-Za-z0-9_-]{12,100}$~', $capture_token)) {
            return new WP_Error('kodety_import_capture_token', 'Não foi possível iniciar a captura isolada.', ['status' => 400]);
        }
        $result = $this->fetch_external_project($source_url, $capture_delay, $capture_token, $requested_platform, $framer_mode);
        if (is_wp_error($result)) return $result;
        return new WP_REST_Response([
            'kind' => $result['kind'],
            'filename' => $result['filename'],
            'sourceUrl' => $result['sourceUrl'],
            'platform' => $result['platform'],
            'importMode' => $result['platform'] === 'elementor' ? $elementor_mode : null,
            'contentBase64' => base64_encode($result['content']),
        ]);
    }

    /** Bundle a browser-rendered Framer document for either REST or wp-admin. */
    private function bundle_rendered_external_project(string $rendered_html, string $source_url, string $framer_mode): array|WP_Error {
        if (strlen($rendered_html) > 20 * MB_IN_BYTES) {
            return new WP_Error('kodety_import_rendered_too_large', 'O HTML capturado ultrapassa o limite de 20 MB.', ['status' => 413]);
        }
        if (!in_array($framer_mode, ['animated', 'static'], true)) $framer_mode = 'animated';
        $validated = $this->import_validate_source_url($source_url);
        if (is_wp_error($validated)) return $validated;
        try {
            $prepared = $this->prepare_imported_html($rendered_html, $validated, 'framer');
            $zip_path = $this->import_bundle_page_assets($prepared, $validated, 'framer', $framer_mode);
            try {
                $zip_bytes = (string) file_get_contents($zip_path);
            } finally {
                @unlink($zip_path);
            }
            if ($zip_bytes === '') throw new RuntimeException('Não foi possível montar o projeto capturado.');
            return [
                'kind' => 'zip',
                'filename' => 'projeto-renderizado.zip',
                'sourceUrl' => $validated,
                'platform' => 'framer',
                'content' => $zip_bytes,
            ];
        } catch (Throwable $error) {
            return new WP_Error('kodety_import_rendered_failed', $error->getMessage(), ['status' => 500]);
        }
    }

    /**
     * Fetch an external URL server-side and classify it as a project ZIP or a
     * cleaned, self-contained HTML page. Shared by the authenticated REST API
     * and the dashboard importer (imports + publishes). SSRF-guarded via
     * wp_http_validate_url() with hard size/time limits.
     *
     * @return array{kind:string,content:string,filename:string,sourceUrl:string}|WP_Error
     */
    private function fetch_external_project(string $url, int $capture_delay = 0, string $capture_token = '', string $requested_platform = 'auto', string $framer_mode = 'animated'): array|WP_Error {
        $validated = $this->import_validate_source_url($url);
        if (is_wp_error($validated)) return $validated;

        $max_bytes = 15 * MB_IN_BYTES;
        $response = $this->import_safe_remote_get($validated, [
            'timeout' => 20,
            'redirection' => 5,
            'reject_unsafe_urls' => true,
            'limit_response_size' => $max_bytes + 1,
            'user-agent' => 'KodetyImporter/1.0 (+WordPress)',
            'headers' => ['Accept' => 'text/html,application/xhtml+xml,application/zip;q=0.9,*/*;q=0.8'],
        ]);
        if (is_wp_error($response)) {
            return new WP_Error('kodety_import_fetch_failed', 'Não foi possível acessar a URL: ' . $response->get_error_message(), ['status' => 502]);
        }
        $status = (int) wp_remote_retrieve_response_code($response);
        if ($status < 200 || $status >= 400) {
            return new WP_Error('kodety_import_http_error', sprintf('A URL respondeu com HTTP %d.', $status), ['status' => 502]);
        }
        $body = (string) wp_remote_retrieve_body($response);
        if ($body === '') return new WP_Error('kodety_import_empty', 'A URL não retornou conteúdo.', ['status' => 422]);
        if (strlen($body) > $max_bytes) {
            return new WP_Error('kodety_import_too_large', 'O HTML publicado ultrapassa o limite de 15 MB.', ['status' => 413]);
        }

        $final_url = $this->import_validate_source_url($this->import_final_url($response, $validated));
        if (is_wp_error($final_url)) return $final_url;
        $content_type = strtolower((string) wp_remote_retrieve_header($response, 'content-type'));
        $looks_zip = str_contains($content_type, 'zip')
            || strncmp($body, "PK\x03\x04", 4) === 0
            || (bool) preg_match('~\.zip(\?|$)~i', (string) wp_parse_url($final_url, PHP_URL_PATH) . '?' . (string) wp_parse_url($final_url, PHP_URL_QUERY));

        if ($looks_zip) {
            if (!$this->import_zip_body_is_valid($body)) {
                return new WP_Error('kodety_import_bad_zip', 'O arquivo baixado não é um ZIP de projeto válido.', ['status' => 422]);
            }
            return ['kind' => 'zip', 'content' => $body, 'filename' => $this->import_filename_from_url($final_url, 'projeto.zip'), 'sourceUrl' => $final_url, 'platform' => 'code'];
        }

        $detected_platform = $this->import_detect_platform($body);
        if ($requested_platform === 'elementor' && $detected_platform !== 'elementor') {
            return new WP_Error(
                'kodety_import_not_elementor',
                'A URL não retornou uma página publicada pelo Elementor.',
                ['status' => 422]
            );
        }
        $platform = in_array($requested_platform, ['framer', 'webflow', 'elementor', 'code'], true)
            ? $requested_platform
            : $detected_platform;

        if ($platform === 'elementor' && (!class_exists('DOMDocument') || !class_exists('ZipArchive'))) {
            return new WP_Error(
                'kodety_elementor_runtime_missing',
                'A hospedagem precisa das extensões PHP DOM e ZipArchive para importar páginas Elementor com segurança.',
                ['status' => 500]
            );
        }

        // Delayed browser capture is a Framer-specific fallback. Webflow and
        // authored-code sites are more faithful when their original runtime is
        // preserved instead of re-executed and flattened into a captured DOM.
        if ($capture_delay > 0 && $platform === 'framer') {
            return [
                'kind' => 'capture',
                'content' => $this->prepare_capture_html($body, $final_url, $capture_delay, $capture_token),
                'filename' => 'captura.html',
                'sourceUrl' => $final_url,
                'platform' => $platform,
            ];
        }

        // A page becomes a self-contained project: styles inlined, then every
        // referenced asset downloaded into the ZIP so the import no longer
        // depends on the origin staying online.
        $prepared = $this->prepare_imported_html($body, $final_url, $platform);
        $zip_path = $this->import_bundle_page_assets($prepared, $final_url, $platform, $framer_mode);
        try {
            $zip_bytes = (string) file_get_contents($zip_path);
        } finally {
