        $source_scheme = strtolower((string) wp_parse_url($url, PHP_URL_SCHEME));
        $home_scheme = strtolower((string) wp_parse_url(home_url('/'), PHP_URL_SCHEME));
        $source_port = (int) (wp_parse_url($url, PHP_URL_PORT) ?: ($source_scheme === 'https' ? 443 : 80));
        $home_port = (int) (wp_parse_url(home_url('/'), PHP_URL_PORT) ?: ($home_scheme === 'https' ? 443 : 80));
        if ($source_host === '' || $home_host === '' || !hash_equals($home_host, $source_host)
            || $source_port !== $home_port
        ) {
            return new WP_Error(
                'kodety_elementor_native_remote',
                'A conversão nativa só pode ler páginas Elementor deste mesmo WordPress. Use Importação visual para outra origem.',
                ['status' => 422]
            );
        }

        $post_id = function_exists('url_to_postid') ? (int) url_to_postid($url) : 0;
        $source_path = trim((string) wp_parse_url($url, PHP_URL_PATH), '/');
        $home_path = trim((string) wp_parse_url(home_url('/'), PHP_URL_PATH), '/');
        if ($post_id <= 0 && $source_path === $home_path) $post_id = absint(get_option('page_on_front', 0));
        if ($post_id <= 0 && function_exists('get_page_by_path')) {
            $relative = $source_path;
            if ($home_path !== '' && ($relative === $home_path || str_starts_with($relative, $home_path . '/'))) {
                $relative = trim(substr($relative, strlen($home_path)), '/');
            }
            $candidate = $relative !== '' ? get_page_by_path($relative, OBJECT, 'page') : null;
            if (is_object($candidate) && isset($candidate->ID)) $post_id = (int) $candidate->ID;
        }
        $post = $post_id > 0 && function_exists('get_post') ? get_post($post_id) : null;
        if (!is_object($post) || ($post->post_type ?? '') !== 'page' || ($post->post_status ?? '') === 'trash') {
            return new WP_Error('kodety_elementor_page_not_found', 'Não encontramos uma página WordPress válida nessa URL.', ['status' => 404]);
        }
        if (!current_user_can('edit_post', $post_id)) {
            return new WP_Error(
                'kodety_elementor_page_forbidden',
                'Você não tem permissão para converter esta página Elementor.',
                ['status' => 403]
            );
        }
        $raw = get_post_meta($post_id, '_elementor_data', true);
        $built = (string) get_post_meta($post_id, '_elementor_edit_mode', true) === 'builder';
        if (!$built && (!is_string($raw) || trim($raw) === '') && !is_array($raw)) {
            return new WP_Error('kodety_elementor_data_missing', 'Essa página não possui dados de layout do Elementor.', ['status' => 422]);
        }
        return $post_id;
    }

    /** @return list<array<string,mixed>>|WP_Error */
    private function elementor_import_document(int $post_id): array|WP_Error {
        $raw = get_post_meta($post_id, '_elementor_data', true);
        if (is_string($raw)) {
            $decoded = json_decode($raw, true);
        } elseif (is_array($raw)) {
            $decoded = $raw;
        } else {
            $decoded = null;
        }
        if (is_array($decoded) && isset($decoded['content']) && is_array($decoded['content'])) $decoded = $decoded['content'];
        if (!is_array($decoded) || !$this->project_delta_array_is_list($decoded) || !$decoded) {
            return new WP_Error('kodety_elementor_data_invalid', 'Os dados de layout desta página Elementor estão vazios ou inválidos.', ['status' => 422]);
        }
        return $decoded;
    }

    /** Read only the Kit values required to resolve page-level global tokens. */
    private function elementor_import_globals(): array {
        $kit_id = absint(get_option('elementor_active_kit', 0));
        $settings = $kit_id > 0 ? get_post_meta($kit_id, '_elementor_page_settings', true) : [];
        if (is_string($settings)) {
            $decoded = json_decode($settings, true);
            $settings = is_array($decoded) ? $decoded : [];
        }
        if (!is_array($settings)) $settings = [];
        $globals = ['kitId' => $kit_id, 'colors' => [], 'typography' => [], 'breakpoints' => []];
        $active_breakpoints = is_array($settings['active_breakpoints'] ?? null) ? $settings['active_breakpoints'] : [];
        foreach (['tablet' => 1024, 'mobile' => 767, 'laptop' => 1366, 'tablet_extra' => 1200, 'mobile_extra' => 880, 'widescreen' => 2400] as $device => $default) {
            if (!in_array($device, ['tablet', 'mobile'], true)
                && !in_array($device, $active_breakpoints, true)
                && !in_array('viewport_' . $device, $active_breakpoints, true)) continue;
            $legacy_key = $device === 'tablet' ? 'viewport_lg' : ($device === 'mobile' ? 'viewport_md' : '');
            $value = $settings['viewport_' . $device] ?? ($legacy_key !== '' ? ($settings[$legacy_key] ?? $default) : $default);
            if (is_array($value)) $value = $value['size'] ?? $default;
            $width = is_numeric($value) ? (int) round((float) $value) : $default;
            $globals['breakpoints'][$device] = $width >= 1 && $width <= 10000 ? $width : $default;
        }
        foreach (['system_colors', 'custom_colors'] as $key) {
            foreach (is_array($settings[$key] ?? null) ? $settings[$key] : [] as $color) {
                if (!is_array($color)) continue;
                $id = sanitize_key((string) ($color['_id'] ?? $color['id'] ?? ''));
                $value = trim((string) ($color['color'] ?? ''));
                if ($id !== '' && $value !== '') $globals['colors'][$id] = $value;
            }
        }
        foreach (['system_typography', 'custom_typography'] as $key) {
            foreach (is_array($settings[$key] ?? null) ? $settings[$key] : [] as $typography) {
                if (!is_array($typography)) continue;
                $id = sanitize_key((string) ($typography['_id'] ?? $typography['id'] ?? ''));
                if ($id === '') continue;
                $normalized = [];
                foreach (['font_family', 'font_weight', 'font_size', 'line_height', 'letter_spacing', 'word_spacing', 'font_style', 'text_transform', 'text_decoration'] as $property) {
                    foreach (array_merge([''], array_map(static fn(string $device): string => '_' . $device, array_keys($globals['breakpoints']))) as $suffix) {
                        $value = $typography['typography_' . $property . $suffix] ?? $typography[$property . $suffix] ?? null;
                        if ($value !== null && $value !== '') $normalized[$property . $suffix] = $value;
                    }
                }
                if ($normalized) $globals['typography'][$id] = $normalized;
            }
        }
        return $globals;
    }

    /** Best-effort rendered fallbacks for third-party/dynamic widgets. */
    private function elementor_import_rendered_widgets(string $source_url, int $post_id = 0, ?string &$font_css = null): array {
        if (!class_exists('DOMDocument')) return [];
        $html = '';
        if (
            $post_id > 0
            && $this->import_source_is_same_wordpress($source_url)
            && class_exists('Elementor\\Plugin')
            && function_exists('kodety_render_elementor_document_for_snapshot')
        ) {
            // Local conversion must not depend on loopback HTTP or CDN state.
            // The free Elementor runtime can render every registered widget in
            // this clean request after the Pro layers were deactivated.
            $html = kodety_render_elementor_document_for_snapshot($post_id, $source_url);
        }
        if ($html === '') {
            $validated = $this->import_validate_source_url($source_url);
            if (is_wp_error($validated)) return [];
            $response = $this->import_safe_remote_get($validated, [
                'timeout' => 15,
                'redirection' => 3,
                'reject_unsafe_urls' => true,
                'limit_response_size' => 10 * MB_IN_BYTES,
                'user-agent' => 'KodetyElementorImporter/1.0 (+WordPress)',
                'headers' => ['Accept' => 'text/html,application/xhtml+xml'],
            ]);
            if (is_wp_error($response) || (int) wp_remote_retrieve_response_code($response) < 200
                || (int) wp_remote_retrieve_response_code($response) >= 400
            ) return [];
            $html = (string) wp_remote_retrieve_body($response);
        }
        if ($html === '') return [];
        $previous = libxml_use_internal_errors(true);
        $dom = new DOMDocument();
        $loaded = $dom->loadHTML('<?xml encoding="utf-8" ?>' . $html, LIBXML_NOWARNING | LIBXML_NOERROR | LIBXML_COMPACT);
        libxml_clear_errors();
        libxml_use_internal_errors($previous);
        if (!$loaded) return [];
        if ($font_css !== null) $font_css = $this->elementor_import_font_faces($dom, $source_url);
        $widgets = [];
        foreach (iterator_to_array($dom->getElementsByTagName('*')) as $element) {
            if (!$element instanceof DOMElement || !$element->hasAttribute('data-id')) continue;
            $is_classic_widget = $element->hasAttribute('data-widget_type');
            $is_atomic_widget = strtolower(trim($element->getAttribute('data-e-type'))) === 'widget';
            if (!$is_classic_widget && !$is_atomic_widget) continue;
            $id = trim($element->getAttribute('data-id'));
            $fragment = $dom->saveHTML($element);
            if ($id !== '' && is_string($fragment) && $fragment !== '' && strlen($fragment) <= 2 * MB_IN_BYTES) {
                $widgets[$id] = $fragment;
            }
        }
        return $widgets;
    }

    /** Preserve font resources without importing the source layout or runtime. */
    private function elementor_import_font_faces(DOMDocument $dom, string $source_url): string {
        $base_url = $source_url;
        foreach ($dom->getElementsByTagName('base') as $base) {
            if ($base instanceof DOMElement && trim($base->getAttribute('href')) !== '') {
                $base_url = $this->import_absolutize_url($base->getAttribute('href'), $source_url);
                break;
            }
        }
        $allow_local_files = $this->import_source_is_same_wordpress($source_url);
        $budget = ['count' => 0, 'bytes' => 0];
        $faces = [];
        // Font-face blocks cannot contain nested rules. Strings/comments may
        // contain braces, so consume those tokens before ordinary characters.
        $pattern = <<<'REGEX'
~ /\*[\s\S]*?\*/ (*SKIP)(*F)
| "(?:[^"\\]++|\\[\s\S])*" (*SKIP)(*F)
| '(?:[^'\\]++|\\[\s\S])*' (*SKIP)(*F)
| @font-face\s*\{(?:[^{}"'/]++|"(?:[^"\\]++|\\[\s\S])*"|'(?:[^'\\]++|\\[\s\S])*'|/\*[\s\S]*?\*/|/(?!\*))*\}
~ix
REGEX;
        foreach (iterator_to_array($dom->getElementsByTagName('*')) as $node) {
            if (!$node instanceof DOMElement) continue;
            $tag = strtolower($node->tagName);
            $css = '';
            if ($tag === 'style') {
                $css = $this->import_expand_css($node->textContent, $base_url, $budget, 0, $allow_local_files);
            } elseif ($tag === 'link' && $this->import_is_stylesheet_link($node)) {
                $url = $this->import_absolutize_url($node->getAttribute('href'), $base_url);
                $css = $this->import_fetch_stylesheet($url, $budget, 0, $allow_local_files) ?? '';
            }
            if ($css !== '' && preg_match_all($pattern, $css, $matches)) {
                foreach ($matches[0] as $face) $faces[hash('sha256', $face)] = $face;
            }
        }
        return implode("\n", array_values($faces));
    }

    /** Compile one local Elementor page into a self-contained Onun Kodety draft ZIP. */
    private function elementor_native_project_zip(int $post_id, string $source_url): string|WP_Error {
        if (!class_exists('DOMDocument') || !class_exists('ZipArchive')) {
            return new WP_Error(
                'kodety_elementor_runtime_missing',
                'A hospedagem precisa das extensões PHP DOM e ZipArchive para converter páginas Elementor.',
                ['status' => 500]
            );
        }
        // The converter is used only by the explicit native-import action.
        // Keeping it out of the plugin bootstrap isolates activation and the
        // normal wp-admin request from Elementor conversion dependencies.
        if (!class_exists('Kodety_Elementor_Importer', false)) {
            $importer_file = __DIR__ . '/class-kodety-elementor-importer.php';
            if (!is_readable($importer_file)) {
                return new WP_Error(
                    'kodety_elementor_importer_missing',
                    'O conversor Elementor não foi encontrado no pacote do Onun Kodety.',
                    ['status' => 500]
                );
            }
            require_once $importer_file;
        }
        if (!class_exists('Kodety_Elementor_Importer', false)) {
            return new WP_Error(
                'kodety_elementor_importer_unavailable',
                'O conversor Elementor não pôde ser carregado.',
                ['status' => 500]
            );
        }
        $document = $this->elementor_import_document($post_id);
        if (is_wp_error($document)) return $document;
        $post = get_post($post_id);
        if (!is_object($post)) return new WP_Error('kodety_elementor_page_not_found', 'A página Elementor não existe mais.', ['status' => 404]);
        $globals = $this->elementor_import_globals();
        try {
            $font_css = '';
            $rendered_widgets = $this->elementor_import_rendered_widgets($source_url, $post_id, $font_css);
            $converted = (new Kodety_Elementor_Importer())->convert($document, [
                'title' => get_the_title($post_id),
                'language' => str_replace('_', '-', get_locale()),
                'sourcePostId' => $post_id,
                'sourceUrl' => $source_url,
                'globals' => $globals,
                'renderedWidgets' => $rendered_widgets,
            ]);
            if ($font_css !== '') $converted['css'] = $font_css . "\n" . $converted['css'];
            $inline_style = '<style data-kodety-elementor-converted>' . str_ireplace('</style', '<\\/style', $converted['css']) . '</style>';
            $bundle_html = str_replace(
                '<link rel="stylesheet" href="css/elementor-converted.css">',
                $inline_style,
                $converted['html']
            );
            $zip_path = $this->import_bundle_page_assets($bundle_html, $source_url, 'elementor-native', 'static');
            $zip = new ZipArchive();
            if ($zip->open($zip_path) !== true) throw new RuntimeException('Não foi possível finalizar o pacote nativo do Elementor.');
            try {
                $index = $zip->getFromName('index.html');
                if (!is_string($index) || $index === '') throw new RuntimeException('A página convertida não foi incluída no pacote.');
                $previous = libxml_use_internal_errors(true);
                $dom = new DOMDocument();
                $loaded = $dom->loadHTML('<?xml encoding="utf-8" ?>' . $index, LIBXML_NOWARNING | LIBXML_NOERROR | LIBXML_COMPACT);
                libxml_clear_errors();
                libxml_use_internal_errors($previous);
                if (!$loaded) throw new RuntimeException('A página convertida não pôde ser serializada.');
                $css = '';
                foreach (iterator_to_array($dom->getElementsByTagName('style')) as $style) {
                    if (!$style instanceof DOMElement || !$style->hasAttribute('data-kodety-elementor-converted')) continue;
                    $css .= $style->textContent . "\n";
                    $link = $dom->createElement('link');
                    $link->setAttribute('rel', 'stylesheet');
                    $link->setAttribute('href', 'css/elementor-converted.css');
                    $style->parentNode?->replaceChild($link, $style);
                }
                if (trim($css) === '') throw new RuntimeException('O CSS editável da conversão não foi gerado.');
                $css = (string) preg_replace_callback(
                    '~url\(\s*(["\']?)(assets/imported/)~i',
                    static fn(array $match): string => 'url(' . $match[1] . '../' . $match[2],
                    $css
                );
                $css = (string) preg_replace('/\s*!\s*important\b/i', '', $css);
                $output = $this->save_html_preserving_raw_text($dom);
                if (!is_string($output) || $output === '') throw new RuntimeException('O HTML editável da conversão não foi gerado.');
                $output = (string) preg_replace('~<\?xml\s+encoding=["\']utf-8["\']\s*\?>~i', '', $output, 1);
                $converted['report']['kitId'] = (int) ($globals['kitId'] ?? 0);
                $converted['report']['sourceDataSha256'] = hash('sha256', (string) wp_json_encode($document, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
                $asset_report = json_decode((string) $zip->getFromName('.incode/url-import.json'), true);
                $converted['report']['fontFaceCount'] = preg_match_all('/@font-face\s*\{/i', $font_css);
                foreach (['localizedAssetCount', 'unresolvedAssetUrls'] as $key) {
                    if (isset($asset_report[$key])) $converted['report'][$key] = $asset_report[$key];
                }
                if (!empty($asset_report['unresolvedAssetUrls'])) {
                    $converted['report']['warnings'][] = 'Alguns recursos não puderam ser localizados e continuam dependendo da origem.';
                }
                $zip->addFromString('index.html', $output);
                $zip->addFromString('css/elementor-converted.css', $css);
                $zip->addFromString('.incode/project.json', (string) wp_json_encode($converted['project'], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
                $zip->addFromString('.incode/elementor-import.json', (string) wp_json_encode($converted['report'], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
                if ($zip->locateName('.incode/url-import.json') !== false) $zip->deleteName('.incode/url-import.json');
            } finally {
                $zip->close();
            }
            return $zip_path;
        } catch (Throwable $error) {
            if (isset($zip_path) && is_string($zip_path) && is_file($zip_path)) @unlink($zip_path);
            return new WP_Error('kodety_elementor_native_failed', $error->getMessage(), ['status' => 500]);
        }
    }

    /**
     * Dashboard beta importer. Elementor always stops at a private Builder
     * draft; other platforms retain the existing direct-publish behavior.
     */
    public function admin_import_url(): void {
        $requested_platform = isset($_POST['kodety_platform'])
            ? sanitize_key((string) wp_unslash($_POST['kodety_platform']))
            : 'auto';
        if (!in_array($requested_platform, ['auto', 'framer', 'webflow', 'elementor', 'code'], true)) $requested_platform = 'auto';
        $elementor_mode = isset($_POST['kodety_elementor_mode'])
            ? sanitize_key((string) wp_unslash($_POST['kodety_elementor_mode']))
            : 'visual';
        if (!in_array($elementor_mode, ['visual', 'native'], true)) $elementor_mode = 'visual';
        $elementor_request = $requested_platform === 'elementor';
        $has_permission = current_user_can('kodety_import')
            && ($elementor_request ? current_user_can(self::CAP_EDIT_WORKSPACE) : (bool) $this->can_publish());
        if (!$has_permission) {
            wp_die(
                $elementor_request ? 'Sem permissão para criar o rascunho Elementor.' : 'Sem permissão para publicar o site.',
                '',
                ['response' => 403]
            );
        }
        check_admin_referer('kodety_import_url');
        $import_revision = (int) get_option('kodety_workspace_revision', 0);
        $lock_error = $this->admin_import_editor_lock_error();
        if ($lock_error) $this->redirect_notice('error', $lock_error->get_error_message());
        if ($this->has_workspace()) {
            $replacement_acknowledged = isset($_POST['kodety_replace_acknowledged'])
                && (string) wp_unslash($_POST['kodety_replace_acknowledged']) === '1';
            $replacement_phrase = isset($_POST['kodety_replace_phrase'])
                ? trim((string) wp_unslash($_POST['kodety_replace_phrase']))
                : '';
            if (!$replacement_acknowledged || !hash_equals('SUBSTITUIR', $replacement_phrase)) {
                $this->redirect_notice('error', 'A substituição foi cancelada. Confirme as perdas e digite SUBSTITUIR antes de trocar o projeto atual.');
            }
        }
        $source_url = isset($_POST['kodety_url']) ? (string) wp_unslash($_POST['kodety_url']) : '';
        $captured_source_url = isset($_POST['kodety_captured_source_url'])
            ? (string) wp_unslash($_POST['kodety_captured_source_url'])
            : '';
        $framer_mode = isset($_POST['kodety_framer_mode'])
            ? sanitize_key((string) wp_unslash($_POST['kodety_framer_mode']))
            : 'animated';
        if (!in_array($framer_mode, ['animated', 'static'], true)) $framer_mode = 'animated';
        $rendered_html = isset($_POST['kodety_rendered_html'])
            ? (string) wp_unslash($_POST['kodety_rendered_html'])
            : '';
        $zip_path = null;
        $wrapped = null;
        $draft_mode = '';
        $failure = null;
        try {
            if ($elementor_request && $rendered_html !== '') {
                throw new RuntimeException('A importação Elementor não aceita HTML de captura Framer. Recarregue a página e tente novamente.');
            }
            if ($elementor_request && $elementor_mode === 'native') {
                $post_id = $this->elementor_import_post_id_from_url($source_url);
                if (is_wp_error($post_id)) throw new RuntimeException($post_id->get_error_message());
                $native_source_url = get_permalink($post_id);
                if (!is_string($native_source_url) || $native_source_url === '') $native_source_url = $source_url;
                $native = $this->elementor_native_project_zip($post_id, $native_source_url);
                if (is_wp_error($native)) throw new RuntimeException($native->get_error_message());
                $zip_path = $native;
                $this->stage_builder_import($zip_path, 'elementor-' . $post_id . '-nativo.zip', true, $import_revision);
                $draft_mode = 'native';
            } else {
                // A visual import from this WordPress must consume the private
                // handoff snapshot captured before Elementor was deactivated.
                // Asking the now inactive public page again loses its widgets.
                if ($elementor_request && $elementor_mode === 'visual') {
                    $local_post_id = $this->elementor_import_post_id_from_url($source_url);
                    if (!is_wp_error($local_post_id)) {
                        $local_source_url = get_permalink($local_post_id);
                        if (!is_string($local_source_url) || $local_source_url === '') $local_source_url = $source_url;
                        $published = $this->elementor_published_project_zip($local_post_id, $local_source_url);
                        if (is_wp_error($published)) throw new RuntimeException($published->get_error_message());
                        $zip_path = $published;
                        $this->stage_builder_import($zip_path, 'elementor-' . $local_post_id . '-publicado.zip', true, $import_revision);
                        $draft_mode = 'visual';
                    } elseif ($local_post_id->get_error_code() !== 'kodety_elementor_native_remote') {
                        throw new RuntimeException($local_post_id->get_error_message());
                    }
                }

                if ($draft_mode === '') {
                    $result = $rendered_html !== ''
                        ? $this->bundle_rendered_external_project(
                            $rendered_html,
                            $captured_source_url !== '' ? $captured_source_url : $source_url,
                            $framer_mode
                        )
                        : $this->fetch_external_project($source_url, 0, '', $requested_platform, $framer_mode);
                    if (is_wp_error($result)) throw new RuntimeException($result->get_error_message());
                    if ($result['kind'] === 'zip') {
                        $zip_path = tempnam(get_temp_dir(), 'kodety-url-');
                        if ($zip_path === false || file_put_contents($zip_path, $result['content'], LOCK_EX) === false) {
                            throw new RuntimeException('Não foi possível preparar o projeto baixado.');
                        }
                    } else {
                        $wrapped = $this->wrap_html_as_project_zip($result['content']);
                        $zip_path = $wrapped;
                    }
                    $result_platform = (string) ($result['platform'] ?? '');
                    if ($elementor_request && $result_platform !== 'elementor') {
                        throw new RuntimeException('A URL não retornou uma página Elementor válida. Use a origem Código para importar arquivos ZIP.');
                    }
                    if ($result_platform === 'elementor') {
                        $this->stage_builder_import(
                            $zip_path,
                            sanitize_file_name($result['filename'] ?: 'elementor-visual.zip'),
                            true,
                            $import_revision
                        );
                        $draft_mode = 'visual';
                    } else {
                        // Authorization follows the action that will happen,
                        // not a client-provided platform label.
                        if (!$this->can_publish()) throw new RuntimeException('Sem permissão para publicar o site.');
                        $this->with_workspace_lock(function () use ($zip_path, $result, $import_revision): void {
                            $this->assert_admin_import_workspace_revision($import_revision);
                            $this->install_zip($zip_path, sanitize_file_name($result['filename'] ?: 'site.zip'));
                        });
                        update_option('kodety_last_published_at', current_time('c'), false);
                    }
                }
            }
        } catch (Throwable $error) {
            $failure = $error;
        } finally {
            if (is_string($zip_path)) @unlink($zip_path);
            if (is_string($wrapped) && $wrapped !== $zip_path) @unlink($wrapped);
        }
        if ($failure instanceof Throwable) $this->redirect_notice('error', $failure->getMessage());
        if ($draft_mode !== '') {
            wp_safe_redirect(add_query_arg([
                'kodety_elementor_import' => $draft_mode,
                'kodety_html' => 'index.html',
            ], home_url('/kodety/editor/')));
            exit;
        }
        $this->redirect_notice('success', 'Projeto importado da URL e publicado com sucesso.');
    }

    public function can_import_from_url(): bool|WP_Error {
        return current_user_can('kodety_import');
    }

    /** Package a single HTML document into a temporary one-page project ZIP. */
    private function wrap_html_as_project_zip(string $html): string {
        if (!class_exists('ZipArchive')) throw new RuntimeException('A extensão PHP ZipArchive precisa estar habilitada na hospedagem.');
        $path = tempnam(get_temp_dir(), 'kodety-page-');
        if ($path === false) throw new RuntimeException('Não foi possível criar o pacote temporário.');
        $zip = new ZipArchive();
        if ($zip->open($path, ZipArchive::OVERWRITE) !== true) throw new RuntimeException('Não foi possível montar o projeto da página.');
        $zip->addFromString('index.html', $html);
        $zip->close();
        return $path;
    }

    /** Resolve the URL actually served, following any redirects wp_remote_get took. */
    private function import_final_url(array $response, string $fallback): string {
        $raw = $response['http_response'] ?? null;
        if ($raw instanceof WP_HTTP_Requests_Response) {
            $object = $raw->get_response_object();
            if (isset($object->url) && is_string($object->url) && $object->url !== '') return $object->url;
        }
        return $fallback;
    }

    /** Best-effort filename from a URL path, falling back to a default. */
    private function import_filename_from_url(string $url, string $default): string {
        $path = (string) wp_parse_url($url, PHP_URL_PATH);
        $name = basename($path);
        $name = sanitize_file_name($name);
        return $name !== '' && str_contains($name, '.') ? $name : $default;
    }

    /** Confirm a downloaded body is a ZIP a ZipArchive can actually open. */
    private function import_zip_body_is_valid(string $body): bool {
        if (!class_exists('ZipArchive')) return strncmp($body, "PK\x03\x04", 4) === 0;
        $temporary = tempnam(get_temp_dir(), 'kodety-import-');
        if ($temporary === false) return false;
        try {
            if (file_put_contents($temporary, $body, LOCK_EX) === false) return false;
            $zip = new ZipArchive();
            $ok = $zip->open($temporary) === true;
            if ($ok) $zip->close();
            return $ok;
        } finally {
            @unlink($temporary);
        }
    }

    /** Merge two Framer manifests, preferring the newer/exact data per target. */
    private function import_merge_framer_manifests(array $base, array $extra): array {
        $merged = array_replace($base, $extra);
        $merged['version'] = 1;

        $sources = [];
        foreach ([$base['source'] ?? '', $extra['source'] ?? ''] as $source) {
            if (is_string($source) && trim($source) !== '') $sources[] = trim($source);
        }
        if ($sources) $merged['source'] = implode('+', array_values(array_unique($sources)));

        $breakpoints = [];
        $seen_breakpoints = [];
        foreach (array_merge(is_array($extra['breakpoints'] ?? null) ? $extra['breakpoints'] : [], is_array($base['breakpoints'] ?? null) ? $base['breakpoints'] : []) as $breakpoint) {
            if (!is_array($breakpoint)) continue;
            $key = isset($breakpoint['query']) && is_string($breakpoint['query']) && $breakpoint['query'] !== ''
                ? 'query:' . $breakpoint['query']
                : ($breakpoint['mode'] ?? '') . ':' . ($breakpoint['width'] ?? '');
            if ($key === ':' || isset($seen_breakpoints[$key])) continue;
            $seen_breakpoints[$key] = true;
            $breakpoints[] = $breakpoint;
        }
        if ($breakpoints) $merged['breakpoints'] = $breakpoints;

        $animations = [];
        $seen_animations = [];
        foreach (array_merge(is_array($extra['animations'] ?? null) ? $extra['animations'] : [], is_array($base['animations'] ?? null) ? $base['animations'] : []) as $animation) {
            if (!is_array($animation)) continue;
            $trigger = is_string($animation['trigger'] ?? null) ? $animation['trigger'] : '';
            $target = is_string($animation['targetClass'] ?? null) ? $animation['targetClass'] : '';
            $key = $trigger . ':' . $target;
            if ($key === ':' || isset($seen_animations[$key])) continue;
            $seen_animations[$key] = true;
            $animations[] = $animation;
        }
        if ($animations) $merged['animations'] = $animations;

        $base_embedded = is_array($base['embedded'] ?? null) ? $base['embedded'] : [];
        $extra_embedded = is_array($extra['embedded'] ?? null) ? $extra['embedded'] : [];
        if ($base_embedded || $extra_embedded) {
            $merged['embedded'] = array_replace_recursive($base_embedded, $extra_embedded);
            foreach (['runtimeEntrypoints', 'runtimeModuleUrls'] as $runtime_key) {
                $urls = [];
                foreach (array_merge(
                    is_array($extra_embedded[$runtime_key] ?? null) ? $extra_embedded[$runtime_key] : [],
                    is_array($base_embedded[$runtime_key] ?? null) ? $base_embedded[$runtime_key] : []
                ) as $url) {
                    if (!is_string($url) || !preg_match('~^https?://~i', $url) || isset($urls[$url])) continue;
                    $urls[$url] = true;
                    if (count($urls) >= ($runtime_key === 'runtimeEntrypoints' ? 4 : 160)) break;
                }
                if ($urls) $merged['embedded'][$runtime_key] = array_keys($urls);
            }
        }
        if (($base['runtime'] ?? false) === true || ($extra['runtime'] ?? false) === true) $merged['runtime'] = true;
        else unset($merged['runtime']);
        return $merged;
    }

    /** Turn a Framer media query into the Builder's breakpoint representation. */
    private function import_framer_breakpoint(array $item): ?array {
        $query = trim((string) ($item['mediaQuery'] ?? $item['query'] ?? ''));
        if ($query === '') return null;
        $min = preg_match('~min-width\s*:\s*([0-9.]+)px~i', $query, $min_match) ? (float) $min_match[1] : null;
        $max = preg_match('~max-width\s*:\s*([0-9.]+)px~i', $query, $max_match) ? (float) $max_match[1] : null;
        if ($min === null && $max === null) return null;
        $mode = $max !== null ? 'max-width' : 'min-width';
        $width = max(1, (int) round($max ?? $min));
        $hash = preg_replace('~[^a-z0-9_-]+~i', '-', (string) ($item['hash'] ?? '')) ?: '';
        $label = $min !== null && $max !== null
            ? 'Framer ' . round($min) . '–' . round($max)
            : 'Framer ' . ($mode === 'max-width' ? '≤ ' : '≥ ') . $width;
        return [
            'id' => $hash !== '' ? 'framer-' . $hash : 'framer-' . ($mode === 'max-width' ? 'max' : 'min') . '-' . $width,
            'label' => $label,
            'mode' => $mode,
            'width' => $width,
            'query' => $query,
        ];
    }

    /** Leave the static/editor DOM at the visible final state of an appear animation. */
    private function import_materialize_framer_appear(DOMElement $element, array $initial, array $animate): void {
        $style = trim($element->getAttribute('style'));
        $set_style = static function (string $property, string $value) use (&$style): void {
            $pattern = '~(^|;)\s*' . preg_quote($property, '~') . '\s*:[^;]*~i';
            if (preg_match($pattern, $style)) $style = (string) preg_replace($pattern, '$1' . $property . ':' . $value, $style, 1);
            else $style .= ($style === '' || str_ends_with($style, ';') ? '' : ';') . $property . ':' . $value;
        };
        $css_number = static function (mixed $value, string $unit = ''): string {
            if (is_int($value) || is_float($value)) return (string) $value . ($value == 0 ? '' : $unit);
            return trim((string) $value);
        };
        $css_scale = static function (mixed $value) use ($css_number): string {
            if (is_string($value)) {
                $normalized = trim(str_replace(',', '.', $value));
                if (str_ends_with($normalized, '%')) {
                    $percent = substr($normalized, 0, -1);
                    if (is_numeric($percent)) return (string) ((float) $percent / 100);
                }
            }
            return $css_number($value);
        };

        $direct = [
            'opacity' => ['', 'opacity'], 'background' => ['', 'background'], 'backgroundColor' => ['', 'background-color'],
            'color' => ['', 'color'], 'borderColor' => ['', 'border-color'], 'borderRadius' => ['px', 'border-radius'],
            'borderWidth' => ['px', 'border-width'], 'boxShadow' => ['', 'box-shadow'], 'filter' => ['', 'filter'],
            'backdropFilter' => ['', 'backdrop-filter'], 'clipPath' => ['', 'clip-path'], 'width' => ['px', 'width'],
            'height' => ['px', 'height'], 'top' => ['px', 'top'], 'right' => ['px', 'right'], 'bottom' => ['px', 'bottom'],
            'left' => ['px', 'left'], 'visibility' => ['', 'visibility'],
        ];
        foreach ($direct as $key => [$unit, $property]) {
            if (!array_key_exists($key, $animate) || $animate[$key] === null || !is_scalar($animate[$key])) continue;
            $set_style($property, $css_number($animate[$key], $unit));
        }

        $transform_keys = ['transformPerspective','x','y','xPercent','yPercent','rotate','rotateX','rotateY','scale','scaleX','scaleY','skewX','skewY'];
        $has_transform = false;
        foreach ($transform_keys as $key) {
            if (array_key_exists($key, $initial) || array_key_exists($key, $animate)) { $has_transform = true; break; }
        }
        if ($has_transform) {
            $parts = [];
            if (isset($animate['transformPerspective'])) $parts[] = 'perspective(' . $css_number($animate['transformPerspective'], 'px') . ')';
            if (array_key_exists('x', $animate)) $parts[] = 'translateX(' . $css_number($animate['x'], 'px') . ')';
            if (array_key_exists('y', $animate)) $parts[] = 'translateY(' . $css_number($animate['y'], 'px') . ')';
            if (array_key_exists('xPercent', $animate)) $parts[] = 'translateX(' . $css_number($animate['xPercent'], '%') . ')';
            if (array_key_exists('yPercent', $animate)) $parts[] = 'translateY(' . $css_number($animate['yPercent'], '%') . ')';
            foreach (['rotate','rotateX','rotateY','skewX','skewY'] as $key) {
                if (array_key_exists($key, $animate)) $parts[] = $key . '(' . $css_number($animate[$key], 'deg') . ')';
            }
            if (array_key_exists('scale', $animate)) $parts[] = 'scale(' . $css_scale($animate['scale']) . ')';
            else {
                if (array_key_exists('scaleX', $animate)) $parts[] = 'scaleX(' . $css_scale($animate['scaleX']) . ')';
                if (array_key_exists('scaleY', $animate)) $parts[] = 'scaleY(' . $css_scale($animate['scaleY']) . ')';
            }
            if ($parts) $set_style('transform', implode(' ', $parts));
        }
        if ($style !== '') $element->setAttribute('style', $style);
        $element->setAttribute('data-kodety-framer-motion', 'load');
    }

    /** Attach only the breakpoint-class switcher, never Framer's React hydration. */
    private function import_attach_framer_responsive_runtime(DOMDocument $dom): void {
        $roots = [];
        foreach (iterator_to_array($dom->getElementsByTagName('meta')) as $meta) {
            if (!$meta instanceof DOMElement || strtolower($meta->getAttribute('name')) !== 'kodety-framer-import') continue;
            $manifest = json_decode(rawurldecode($meta->getAttribute('content')), true);
            $candidate_roots = is_array($manifest['embedded']['responsiveRoots'] ?? null) ? $manifest['embedded']['responsiveRoots'] : [];
            foreach (array_slice($candidate_roots, 0, 20) as $root) {
                if (!is_array($root)) continue;
                $selector = (string) ($root['selector'] ?? '');
                if (!preg_match('~^\.kodety-framer-responsive-root-[0-9]+$~', $selector)) continue;
                $variants = [];
                foreach (array_slice(is_array($root['variants'] ?? null) ? $root['variants'] : [], 0, 20) as $variant) {
                    if (!is_array($variant)) continue;
                    $hash = (string) ($variant['hash'] ?? '');
                    $query = trim((string) ($variant['query'] ?? ''));
                    if (!preg_match('~^[a-z0-9_-]+$~i', $hash) || $query === '' || strlen($query) > 240 || !preg_match('~(?:min|max)-width\s*:~i', $query)) continue;
                    $variants[] = ['hash' => $hash, 'query' => $query];
                }
                if (count($variants) > 1) $roots[] = ['selector' => $selector, 'variants' => $variants];
            }
        }
        if (!$roots) return;
        $encoded = wp_json_encode($roots, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP);
        if (!is_string($encoded) || $encoded === '') return;
        $javascript = '(function(){var groups=' . $encoded . ';var scheduled=false;function apply(){scheduled=false;groups.forEach(function(group){var root=document.querySelector(group.selector);if(!root)return;var active=null;group.variants.forEach(function(variant){root.classList.remove("framer-"+variant.hash);try{if(!active&&matchMedia(variant.query).matches)active=variant}catch(error){}});if(active){root.classList.add("framer-"+active.hash);root.setAttribute("data-kodety-framer-breakpoint",active.hash)}})}function schedule(){if(scheduled)return;scheduled=true;requestAnimationFrame(apply)}groups.forEach(function(group){group.variants.forEach(function(variant){try{var query=matchMedia(variant.query);if(query.addEventListener)query.addEventListener("change",schedule);else query.addListener(schedule)}catch(error){}})});addEventListener("resize",schedule,{passive:true});if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",apply,{once:true});else apply()})();';
        $script = $dom->createElement('script');
        $script->setAttribute('data-kodety-framer-responsive-runtime', '');
        $script->appendChild($dom->createTextNode($javascript));
        $body = $dom->getElementsByTagName('body')->item(0);
        if ($body instanceof DOMElement) $body->appendChild($script);
        else $dom->documentElement?->appendChild($script);
    }

    /**
     * Run the archived Framer application without letting React erase Builder
     * edits. The baseline remains part of the project: every Preview/publication
     * compares the current authored DOM against it, then reapplies only the
     * properties/layers the author changed while Framer owns everything else.
     *
     * @param array<string,string> $asset_rewrites Original URL => project path.
     */
    private function import_attach_framer_compat_runtime(DOMDocument $dom, string $entrypoint, array $asset_rewrites = []): bool {
        if (!str_starts_with($entrypoint, 'scripts/vendor/')) return false;
        $root = $dom->getElementById('main');
        if (!$root instanceof DOMElement) {
            foreach (iterator_to_array($dom->getElementsByTagName('*')) as $candidate) {
                if ($candidate instanceof DOMElement && $candidate->hasAttribute('data-framer-root')) { $root = $candidate; break; }
            }
        }
        if (!$root instanceof DOMElement) $root = $dom->getElementsByTagName('body')->item(0);
        if (!$root instanceof DOMElement) return false;

        $elements = [$root];
        foreach (iterator_to_array($root->getElementsByTagName('*')) as $element) {
            if (!$element instanceof DOMElement) continue;
            $tag = strtolower($element->tagName);
            if (in_array($tag, ['script', 'style', 'link', 'meta', 'noscript', 'template'], true)) continue;
            // Keep an SVG as one editable/synchronizable layer. Framer's symbol
            // warehouses can contain thousands of path/defs nodes and used to
            // exhaust the 3,500-node baseline before later page text existed.
            $technical_id = strtolower($element->getAttribute('id'));
            $technical_classes = array_map('strtolower', preg_split('~\s+~', trim($element->getAttribute('class'))) ?: []);
            $technical = $technical_id === 'svg-templates'
                || $technical_id === 'template-overlay'
                || $element->hasAttribute('data-framer-svg-template')
                || in_array('svg-templates', $technical_classes, true);
            $ancestor = $element->parentNode;
            while (!$technical && $ancestor instanceof DOMElement && $ancestor !== $root) {
                $ancestor_tag = strtolower($ancestor->tagName);
                $ancestor_id = strtolower($ancestor->getAttribute('id'));
                $ancestor_classes = array_map('strtolower', preg_split('~\s+~', trim($ancestor->getAttribute('class'))) ?: []);
                if ($ancestor_tag === 'svg'
                    || $ancestor_id === 'svg-templates'
                    || $ancestor_id === 'template-overlay'
                    || $ancestor->hasAttribute('data-framer-svg-template')
                    || in_array('svg-templates', $ancestor_classes, true)) $technical = true;
                $ancestor = $ancestor->parentNode;
            }
            if ($technical) continue;
            $elements[] = $element;
            if (count($elements) >= 3500) break;
        }
        foreach ($elements as $index => $element) $element->setAttribute('data-kodety-framer-node', 'fr-' . ($index + 1));

