            while ($next !== null) {
                if ($next instanceof DOMElement && $next->hasAttribute('data-kodety-framer-node')) {
                    $next_id = $next->getAttribute('data-kodety-framer-node');
                    break;
                }
                $next = $next->nextSibling;
            }
            $nodes[] = [
                'id' => $element->getAttribute('data-kodety-framer-node'),
                'tag' => strtolower($element->tagName),
                'path' => $element_path($element, $root),
                'parent' => $parent_id,
                'next' => $next_id,
                'class' => array_values(array_filter(preg_split('~\s+~', trim($element->getAttribute('class'))) ?: [])),
                'style' => $element->getAttribute('style'),
                'attrs' => $attributes,
                'leaf' => $leaf,
