        }
        $aliases = [];
        foreach ($asset_rewrites as $remote => $local) {
            if (!is_string($remote) || !is_string($local) || !preg_match('~^https?://~i', $remote) || !str_starts_with($local, 'assets/imported/')) continue;
            $aliases[$remote] = $local;
            if (count($aliases) >= 400) break;
        }
        $baseline = [
            'version' => 1,
            'root' => $root->getAttribute('data-kodety-framer-node'),
            'nodes' => $nodes,
            'assetAliases' => $aliases,
        ];
        $encoded = wp_json_encode($baseline, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT);
        if (!is_string($encoded) || $encoded === '' || strlen($encoded) > 2 * MB_IN_BYTES) return false;

        $body = $dom->getElementsByTagName('body')->item(0);
        if (!$body instanceof DOMElement) return false;
        $baseline_script = $dom->createElement('script');
        $baseline_script->setAttribute('type', 'application/json');
        $baseline_script->setAttribute('data-kodety-framer-baseline', '');
        $baseline_script->appendChild($dom->createTextNode($encoded));
        $body->appendChild($baseline_script);

        $guard = <<<'JS'
