    /** Resolve a relative ESM specifier inside the generated project tree. */
    private function import_resolve_project_module_path(string $module_path, string $specifier): string {
        $specifier = (string) preg_replace('~[?#].*$~', '', trim($specifier));
        $parts = explode('/', dirname($module_path) . '/' . $specifier);
        $resolved = [];
        foreach ($parts as $part) {
            if ($part === '' || $part === '.') continue;
            if ($part === '..') { array_pop($resolved); continue; }
            $resolved[] = $part;
        }
        return implode('/', $resolved);
    }

    /**
     * Only execute a localized Framer graph when it is truly self-contained.
     * Unsupported graphs remain archived and the converted CSS/Motion manifest
     * is used instead, so a single incompatible chunk cannot crash the canvas.
     *
     * @param array<string,array{body:string,path:string}> $runtime_downloaded
     * @return array{compatible:bool,issues:array<int,string>}
     */
    private function import_audit_framer_runtime_graph(string $entrypoint, array $runtime_downloaded): array {
        $paths = [];
        foreach ($runtime_downloaded as $asset) {
            if (is_array($asset) && is_string($asset['path'] ?? null)) $paths[$asset['path']] = true;
        }
        $issues = [];
        if ($entrypoint === '' || !isset($paths[$entrypoint])) $issues[] = 'entrypoint-missing';

        foreach ($runtime_downloaded as $asset) {
            if (!is_array($asset) || !is_string($asset['path'] ?? null) || !is_string($asset['body'] ?? null)) continue;
            $path = $asset['path'];
            $body = $asset['body'];
            $specifiers = [];
            foreach ([
                '~\bimport\s*(?:\(\s*)?(["\'`])([^"\'`]+)\1~',
                '~\b(?:import|export)\b[^;\n]{0,300}?\bfrom\s*(["\'`])([^"\'`]+)\1~',
            ] as $pattern) {
                if (!preg_match_all($pattern, $body, $matches, PREG_SET_ORDER)) continue;
                foreach ($matches as $match) $specifiers[$match[2]] = true;
            }
            foreach (array_keys($specifiers) as $specifier) {
                if (str_contains($specifier, '${')) {
                    $issues[] = $path . ':dynamic-template';
                    continue;
                }
                if (preg_match('~^(?:https?:|data:|blob:|/)~i', $specifier)) {
                    $issues[] = $path . ':external:' . substr($specifier, 0, 160);
                    continue;
                }
                if (!str_starts_with($specifier, './') && !str_starts_with($specifier, '../')) {
                    $issues[] = $path . ':bare:' . substr($specifier, 0, 160);
                    continue;
                }
                $dependency = $this->import_resolve_project_module_path($path, $specifier);
                if (!isset($paths[$dependency])) $issues[] = $path . ':missing:' . $dependency;
            }
            if (count($issues) >= 100) break;
        }
        $issues = array_values(array_unique($issues));
        return ['compatible' => !$issues, 'issues' => array_slice($issues, 0, 100)];
    }

    /** Convert Framer's embedded appear/breakpoint data before hydration is detached. */
    private function import_extract_framer_manifest(DOMDocument $dom, string $document_base): void {
        $manifest = [];
        $head = $dom->getElementsByTagName('head')->item(0);

        // A delayed browser capture may already have recorded hover/pressed/
        // focus and WAAPI transitions. Keep it and enrich it with exact SSR data.
        foreach (iterator_to_array($dom->getElementsByTagName('meta')) as $meta) {
            if (!$meta instanceof DOMElement || strtolower($meta->getAttribute('name')) !== 'kodety-framer-import') continue;
            $parsed = json_decode(rawurldecode($meta->getAttribute('content')), true);
            if (is_array($parsed) && ($parsed['version'] ?? null) === 1) $manifest = $this->import_merge_framer_manifests($manifest, $parsed);
            $meta->parentNode?->removeChild($meta);
        }

        $appear = null;
        $raw_appear = '';
        $raw_breakpoints = '';
        $raw_handover = '';
        $runtime_entrypoints = [];
        $runtime_module_urls = [];
        $declared_module_urls = [];
        foreach (iterator_to_array($dom->getElementsByTagName('script')) as $script) {
            if (!$script instanceof DOMElement) continue;
            $id = $script->getAttribute('id');
            if ($id === '__framer__appearAnimationsContent') $raw_appear = trim($script->textContent);
            elseif ($id === '__framer__breakpoints') $raw_breakpoints = trim($script->textContent);
            elseif ($id === '__framer__handoverData') $raw_handover = trim($script->textContent);
            if (strtolower(trim($script->getAttribute('type'))) === 'module' && $script->hasAttribute('src')) {
                $url = $this->import_absolutize_url(trim($script->getAttribute('src')), $document_base);
                if (preg_match('~^https?://~i', $url)) {
                    $declared_module_urls[] = $url;
                    $runtime_module_urls[$url] = true;
                    if ($script->getAttribute('data-framer-bundle') === 'main' || preg_match('~/script_main[^/]*\.mjs(?:[?#]|$)~i', $url)) $runtime_entrypoints[$url] = true;
                }
            }
        }
        foreach (iterator_to_array($dom->getElementsByTagName('link')) as $link) {
            if (!$link instanceof DOMElement || !$link->hasAttribute('href')) continue;
            $rels = preg_split('~\s+~', strtolower(trim($link->getAttribute('rel')))) ?: [];
            if (!in_array('modulepreload', $rels, true)) continue;
            $url = $this->import_absolutize_url(trim($link->getAttribute('href')), $document_base);
            if (preg_match('~^https?://~i', $url)) $runtime_module_urls[$url] = true;
        }
        if (!$runtime_entrypoints) {
            foreach (array_keys($runtime_module_urls) as $url) {
                if (preg_match('~/script_main[^/]*\.mjs(?:[?#]|$)~i', $url)) { $runtime_entrypoints[$url] = true; break; }
            }
            if (!$runtime_entrypoints && $declared_module_urls) $runtime_entrypoints[end($declared_module_urls)] = true;
        }

        $exact = [
            'version' => 1,
            'source' => 'framer-embedded',
            'breakpoints' => [],
            'animations' => [],
            'embedded' => [],
        ];
        if ($runtime_entrypoints) $exact['embedded']['runtimeEntrypoints'] = array_slice(array_keys($runtime_entrypoints), 0, 4);
        if ($runtime_module_urls) $exact['embedded']['runtimeModuleUrls'] = array_slice(array_keys($runtime_module_urls), 0, 160);
        if ($raw_breakpoints !== '') {
            $decoded = json_decode($raw_breakpoints, true);
            if (is_array($decoded)) {
                $exact['embedded']['breakpoints'] = $decoded;
                foreach ($decoded as $item) {
                    if (!is_array($item)) continue;
                    $breakpoint = $this->import_framer_breakpoint($item);
                    if ($breakpoint !== null) $exact['breakpoints'][] = $breakpoint;
                }
            }
        }
        if ($raw_handover !== '') {
            // Handover uses Framer's own serialization format. Preserve it as
            // inert project data for diagnostics/future extractors, never execute it.
            $exact['embedded']['handoverRaw'] = $raw_handover;
        }
        if ($raw_appear !== '') {
            $decoded = json_decode($raw_appear, true);
            if (is_array($decoded)) {
                $appear = $decoded;
                $exact['embedded']['appear'] = $decoded;
            }
        }

        if (is_array($appear)) {
            $targets = [];
            foreach (iterator_to_array($dom->getElementsByTagName('*')) as $element) {
                if (!$element instanceof DOMElement || !$element->hasAttribute('data-framer-appear-id')) continue;
                $appear_id = trim($element->getAttribute('data-framer-appear-id'));
                if ($appear_id === '') continue;
                $safe_id = preg_replace('~[^a-z0-9_-]+~i', '-', $appear_id) ?: '';
                if ($safe_id === '') continue;
                $preferred_class = 'framer-' . $safe_id;
                $classes = preg_split('~\s+~', trim($element->getAttribute('class'))) ?: [];
                $target_class = is_array($targets[$appear_id] ?? null) ? (string) $targets[$appear_id]['class'] : '';
                if ($target_class === '') {
                    foreach ($classes as $candidate_class) {
                        if ($candidate_class === $preferred_class || str_starts_with($candidate_class, $preferred_class . '-')) { $target_class = $candidate_class; break; }
                    }
                }
                if ($target_class === '') $target_class = 'kodety-framer-appear-' . $safe_id;
                if (!in_array($target_class, $classes, true)) {
                    $classes[] = $target_class;
                    $element->setAttribute('class', trim(implode(' ', array_filter($classes))));
                }
                $label = trim($element->getAttribute('data-framer-name'));
                if ($label === '') $label = trim($element->getAttribute('aria-label'));
                if ($label === '') $label = ucfirst(strtolower($element->tagName)) . ' · ' . $appear_id;
                if (!isset($targets[$appear_id])) $targets[$appear_id] = ['class' => $target_class, 'label' => substr($label, 0, 120), 'elements' => []];
                $targets[$appear_id]['elements'][] = $element;
            }

            foreach ($appear as $appear_id => $variants) {
                if (!is_string($appear_id) || !is_array($variants)) continue;
                $definition = is_array($variants['default'] ?? null) ? $variants['default'] : null;
                if ($definition === null) {
                    foreach ($variants as $candidate) {
                        if (is_array($candidate) && isset($candidate['initial'], $candidate['animate'])) { $definition = $candidate; break; }
                    }
                }
                if (!is_array($definition) || !is_array($definition['initial'] ?? null) || !is_array($definition['animate'] ?? null)) continue;
                $safe_id = preg_replace('~[^a-z0-9_-]+~i', '-', $appear_id) ?: '';
                if ($safe_id === '') continue;
                $target = $targets[$appear_id] ?? ['class' => 'framer-' . $safe_id, 'label' => 'Framer · ' . $appear_id];
                $initial = $definition['initial'];
                $animate = $definition['animate'];
                $transition = is_array($animate['transition'] ?? null) ? $animate['transition'] : (is_array($definition['transition'] ?? null) ? $definition['transition'] : []);
                unset($initial['transition'], $animate['transition']);
                foreach (is_array($target['elements'] ?? null) ? $target['elements'] : [] as $target_element) {
                    if ($target_element instanceof DOMElement) $this->import_materialize_framer_appear($target_element, $initial, $animate);
                }
                $ease = $transition['ease'] ?? '';
                if (is_array($ease) && count($ease) === 4) $ease = 'cubic-bezier(' . implode(',', array_map('floatval', $ease)) . ')';
                elseif (!is_string($ease)) $ease = '';
                $duration = (float) ($transition['duration'] ?? $transition['visualDuration'] ?? 0.4);
                $delay = (float) ($transition['delay'] ?? 0);
                $exact['animations'][] = [
                    'trigger' => 'load',
                    'targetClass' => $target['class'],
                    'elementLabel' => $target['label'],
                    'frames' => [array_merge(['offset' => 0], $initial), array_merge(['offset' => 1], $animate)],
                    'timing' => [
                        'delay' => max(0, $delay * 1000),
                        'duration' => max(10, $duration * 1000),
                        'easing' => $ease !== '' ? $ease : (string) ($transition['type'] ?? 'ease-out'),
                        'iterations' => 1,
                    ],
                    'framerVariants' => array_keys($variants),
                    'framerTransition' => $transition,
                ];
            }
        }

        if (!$exact['breakpoints']) unset($exact['breakpoints']);
        if (!$exact['animations']) unset($exact['animations']);
        if (!$exact['embedded']) unset($exact['embedded']);
        if (count($exact) > 2) $manifest = $this->import_merge_framer_manifests($manifest, $exact);
        if (!$manifest) return;

        $json = wp_json_encode($manifest, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        if (!is_string($json) || $json === '' || strlen($json) > 900000) return;
        if (!$head instanceof DOMElement) {
            $head = $dom->createElement('head');
            $dom->documentElement?->insertBefore($head, $dom->documentElement->firstChild);
        }
        $meta = $dom->createElement('meta');
        $meta->setAttribute('name', 'kodety-framer-import');
        $meta->setAttribute('content', rawurlencode($json));
        $head->appendChild($meta);
    }

    /** Remove source-builder branding from a project that is now hosted by
     * Onun Kodety. Webflow may create its badge after DOMContentLoaded, so preserved
     * Webflow/code runtimes also receive a small mutation cleanup. Framer's
     * hydrated case is handled inside its compatibility guard. */
    private function import_remove_platform_badges(DOMDocument $dom, string $platform): void {
        $document_element = $dom->documentElement;
        $looks_webflow = $platform === 'webflow'
            || ($document_element instanceof DOMElement
                && ($document_element->hasAttribute('data-wf-page') || $document_element->hasAttribute('data-wf-site')));
        $looks_framer = $platform === 'framer';
        if ($looks_webflow && $document_element instanceof DOMElement) {
            // This flag is what asks Webflow's own runtime to recreate the
            // branded badge after DOMContentLoaded. It is unrelated to IX2.
            $document_element->removeAttribute('data-wf-status');
        }
        foreach (iterator_to_array($dom->getElementsByTagName('*')) as $element) {
            if (!$element instanceof DOMElement) continue;
            if ($element->hasAttribute('data-kodety-platform-branding-cleanup')) {
                $element->parentNode?->removeChild($element);
                continue;
            }
            $classes = preg_split('~\s+~', trim($element->getAttribute('class'))) ?: [];
            if (($looks_webflow && in_array('w-webflow-badge', $classes, true))
                || ($looks_framer && (
                    in_array($element->getAttribute('id'), ['__framer-badge-container', 'framer-badge-container'], true)
                    || in_array('__framer-badge', $classes, true)
                ))) {
                $element->parentNode?->removeChild($element);
            }
        }
        if (!$looks_webflow) return;
        $head = $dom->getElementsByTagName('head')->item(0);
        if (!$head instanceof DOMElement) {
            $head = $dom->createElement('head');
            $dom->documentElement?->insertBefore($head, $dom->documentElement->firstChild);
        }
        // Higher specificity than Webflow's own .w-webflow-badge rule. No
        // !important is needed, keeping the Builder's style controls sovereign.
        $style = $dom->createElement('style');
        $style->setAttribute('data-kodety-platform-branding-cleanup', '');
        $style->appendChild($dom->createTextNode('html body a.w-webflow-badge,html body [data-wf-badge].w-webflow-badge{display:none;visibility:hidden;opacity:0;pointer-events:none}'));
        $head->insertBefore($style, $head->firstChild);
        $cleanup = $dom->createElement('script');
        $cleanup->setAttribute('data-kodety-platform-branding-cleanup', '');
        $cleanup->appendChild($dom->createTextNode(<<<'JS'
(()=>{const selector=".w-webflow-badge,[data-wf-badge].w-webflow-badge";const prune=root=>{if(root instanceof Element&&root.matches(selector)){root.remove();return}root.querySelectorAll?.(selector).forEach(element=>element.remove())};const start=()=>{prune(document);new MutationObserver(mutations=>mutations.forEach(mutation=>mutation.addedNodes.forEach(node=>{if(node instanceof Element)prune(node)}))).observe(document.documentElement,{childList:true,subtree:true})};document.documentElement.removeAttribute("data-wf-status");start();addEventListener("pageshow",()=>prune(document));addEventListener("load",()=>prune(document))})();
JS));
        $head->insertBefore($cleanup, $style->nextSibling);
    }

    /**
     * Framer marks tappable elements with data-highlight. Its browser/touch
     * fallback can survive a rendered capture as a colored rectangle even
     * though no pointer is active. Suppress only that idle artifact; genuine
     * keyboard focus remains visible through :focus-visible.
     */
    private function import_attach_framer_visual_cleanup(DOMDocument $dom): void {
        foreach (iterator_to_array($dom->getElementsByTagName('style')) as $existing) {
            if ($existing instanceof DOMElement && $existing->hasAttribute('data-kodety-framer-visual-cleanup')) {
                $existing->parentNode?->removeChild($existing);
            }
        }
        $head = $dom->getElementsByTagName('head')->item(0);
        if (!$head instanceof DOMElement) {
            $head = $dom->createElement('head');
            $dom->documentElement?->insertBefore($head, $dom->documentElement->firstChild);
        }
        $style = $dom->createElement('style');
        $style->setAttribute('data-kodety-framer-visual-cleanup', '');
        $style->appendChild($dom->createTextNode(
            'html body [data-highlight]:not(:focus-visible),html body [data-framer-highlight]:not(:focus-visible){outline:none!important;-webkit-tap-highlight-color:transparent}'
        ));
        $head->appendChild($style);
    }

    /** Promote meaningful Framer layer names into the Builder's native label. */
    private function import_promote_framer_layer_labels(DOMDocument $dom): void {
        foreach (iterator_to_array($dom->getElementsByTagName('*')) as $element) {
            if (!$element instanceof DOMElement || !$element->hasAttribute('data-framer-name')) continue;
            if (trim($element->getAttribute('data-label')) !== '') continue;
            $label = trim($element->getAttribute('data-framer-name'));
            $label = (string) preg_replace('~[\x00-\x1f\x7f]+~u', ' ', $label);
            $label = (string) preg_replace('~\s+~u', ' ', $label);
            if ($label === '' || preg_match('~^(?:default|variant(?:\s+\d+)?|frame(?:\s+\d+)?|group(?:\s+\d+)?|desktop|tablet|mobile)$~i', $label)) continue;
            $label = function_exists('mb_substr') ? mb_substr($label, 0, 120) : substr($label, 0, 120);
            if ($label !== '') $element->setAttribute('data-label', $label);
        }
    }

    /** Give a rendered Elementor tree useful, stable names in Onun Kodety Layers. */
    private function import_promote_elementor_layer_labels(DOMDocument $dom): void {
        $widget_labels = [
            'heading' => 'Título',
            'text-editor' => 'Texto',
            'image' => 'Imagem',
            'button' => 'Botão',
            'divider' => 'Divisor',
            'spacer' => 'Espaçador',
            'icon' => 'Ícone',
            'icon-list' => 'Lista com ícones',
            'video' => 'Vídeo',
            'image-carousel' => 'Carrossel de imagens',
            'media-carousel' => 'Carrossel de mídia',
            'nested-accordion' => 'Acordeão',
            'accordion' => 'Acordeão',
            'nested-tabs' => 'Abas',
            'tabs' => 'Abas',
            'toggle' => 'Alternador',
            'counter' => 'Contador',
            'progress' => 'Progresso',
            'testimonial' => 'Depoimento',
            'testimonial-carousel' => 'Carrossel de depoimentos',
            'social-icons' => 'Ícones sociais',
            'form' => 'Formulário Elementor',
            'search-form' => 'Busca',
            'nav-menu' => 'Menu',
            'menu-anchor' => 'Âncora',
            'html' => 'HTML',
            'shortcode' => 'Shortcode',
            'google_maps' => 'Mapa',
            'google-maps' => 'Mapa',
            'e-component' => 'Componente Elementor',
            'loop-grid' => 'Grade de conteúdo',
            'posts' => 'Lista de posts',
            'theme-site-logo' => 'Logo do site',
            'theme-site-title' => 'Nome do site',
            'theme-post-title' => 'Título do post',
            'theme-post-content' => 'Conteúdo do post',
            'theme-post-featured-image' => 'Imagem destacada',
        ];
        foreach (iterator_to_array($dom->getElementsByTagName('*')) as $element) {
            if (!$element instanceof DOMElement) continue;
            $source_widget_type = strtolower(trim($element->getAttribute('data-widget_type')));
            $widget_type = (string) preg_replace('/\..*$/', '', $source_widget_type);
            $element_type = strtolower(trim($element->getAttribute('data-element_type')));
            $atomic_type = strtolower(trim($element->getAttribute('data-e-type')));
            $classes = preg_split('/\s+/', strtolower(trim($element->getAttribute('class')))) ?: [];
            if ($widget_type === '' && $atomic_type === 'widget') {
                $tag = strtolower($element->tagName);
                if (in_array($tag, ['img', 'picture'], true) || array_filter($classes, static fn(string $class): bool => str_starts_with($class, 'e-image-'))) {
                    $widget_type = 'image';
                } elseif (in_array($tag, ['h1', 'h2', 'h3', 'h4', 'h5', 'h6'], true) || array_filter($classes, static fn(string $class): bool => str_starts_with($class, 'e-heading-'))) {
                    $widget_type = 'heading';
                } elseif ($tag === 'p' || array_filter($classes, static fn(string $class): bool => str_starts_with($class, 'e-paragraph-'))) {
                    $widget_type = 'text-editor';
                } elseif (in_array($tag, ['a', 'button'], true) || array_filter($classes, static fn(string $class): bool => str_starts_with($class, 'e-button-'))) {
                    $widget_type = 'button';
                } elseif ($tag === 'video') {
                    $widget_type = 'video';
                } elseif (in_array($tag, ['svg', 'i'], true) || array_filter($classes, static fn(string $class): bool => str_starts_with($class, 'e-icon-'))) {
                    $widget_type = 'icon';
                } else {
                    $widget_type = 'atomic-widget';
                }
                $source_widget_type = $widget_type . '.atomic';
            }
            $source_id = trim($element->getAttribute('data-id'));
            if ($source_id === '') $source_id = trim($element->getAttribute('data-interaction-id'));
            if ($source_id !== '' && !$element->hasAttribute('data-kodety-elementor-source')) {
                $element->setAttribute('data-kodety-elementor-source', substr($source_id, 0, 160));
            }
            if ($source_widget_type !== '') {
                $element->setAttribute('data-kodety-elementor-widget', substr($source_widget_type, 0, 160));
                $element->setAttribute('data-kodety-elementor-preserved', 'published-html');
            }
            if (trim($element->getAttribute('data-label')) !== '') continue;
            $label = $widget_labels[$widget_type] ?? '';
            if ($label === '' && $widget_type !== '') {
                $label = $widget_type === 'atomic-widget'
                    ? 'Widget atômico Elementor'
                    : 'Widget Elementor · ' . ucwords(str_replace(['-', '_'], ' ', $widget_type));
            } elseif ($label === '' && ($element_type !== '' || $atomic_type !== '')) {
                $label = match ($element_type !== '' ? $element_type : $atomic_type) {
                    'section' => 'Seção Elementor',
                    'column' => 'Coluna Elementor',
                    'container', 'e-flexbox' => 'Container Elementor',
                    'e-grid' => 'Grade Elementor',
                    'e-div-block' => 'Bloco Elementor',
                    'e-component' => 'Componente Elementor',
                    default => 'Elemento Elementor',
                };
            }
            if ($label !== '') $element->setAttribute('data-label', substr($label, 0, 120));
        }
    }

    /**
     * Keep the published Elementor DOM and its runtime while removing HTML
     * execution surfaces that Elementor itself does not need. Widgets normally
     * bind through the preserved frontend scripts, so embeds and form controls
     * remain real instead of becoming placeholders.
     */
    private function import_harden_elementor_runtime_document(DOMDocument $dom): void {
        foreach (iterator_to_array($dom->getElementsByTagName('*')) as $element) {
            if (!$element instanceof DOMElement) continue;
            $tag = strtolower($element->tagName);
            foreach (iterator_to_array($element->attributes ?? []) as $attribute) {
                $name = strtolower($attribute->name);
                $value = trim($attribute->value);
                if (str_starts_with($name, 'on') || $name === 'srcdoc') {
                    $element->removeAttribute($attribute->name);
                    continue;
                }
                if (in_array($name, ['href', 'xlink:href', 'src', 'poster', 'action', 'formaction', 'data'], true)
                    && preg_match('/^(?:javascript|vbscript|data:(?!image\/(?:png|gif|jpe?g|webp|avif);base64,))/i', $value)
                ) {
                    if ($name === 'href') $element->setAttribute('href', '#');
                    else $element->removeAttribute($attribute->name);
                    continue;
                }
                if (in_array($name, ['srcset', 'data-srcset', 'data-lazy-srcset'], true)
                    && preg_match('/(?:javascript|vbscript|data:(?!image\/(?:png|gif|jpe?g|webp|avif);base64,))/i', $value)
                ) {
                    $element->removeAttribute($attribute->name);
                    continue;
                }
                if ($name === 'style') {
                    // Keep declarations and URLs, but normalize priority so the
                    // imported document stays editable under Onun Kodety's CSS contract.
                    $style = (string) preg_replace('/\s*!\s*important\b/i', '', $value);
                    if (preg_match('/(?:expression\s*\(|(?:javascript|vbscript)\s*:|data\s*:\s*(?:text|application)\b)/i', $style)) $element->removeAttribute('style');
                    else $element->setAttribute('style', $style);
                }
            }
            if ($tag === 'form') {
                $element->setAttribute('data-kodety-elementor-form', 'preserved');
            }
            if ($tag === 'a' && strtolower($element->getAttribute('target')) === '_blank') {
                $rel = preg_split('/\s+/', strtolower(trim($element->getAttribute('rel')))) ?: [];
                $element->setAttribute('rel', implode(' ', array_values(array_unique(array_merge($rel, ['noopener', 'noreferrer'])))));
            }
        }
    }

    /**
     * Lenis takes ownership of the page scroll loop and conflicts with the
     * Builder canvas, which already owns scrolling/zoom. Keep every other
     * Elementor widget dependency, but remove this one runtime and its stale
     * document state. Native smooth scrolling is enough for anchor links.
     */
    private function import_remove_elementor_lenis_runtime(DOMDocument $dom): void {
        $removed = false;
        foreach (iterator_to_array($dom->getElementsByTagName('script')) as $script) {
            if (!$script instanceof DOMElement) continue;
            $src = strtolower(trim($script->getAttribute('src')));
            $code = (string) $script->textContent;
            $is_lenis_asset = $src !== '' && preg_match('~(?:^|[/_.-])lenis(?:[./?&_-]|$)~i', $src);
            $owns_lenis = preg_match('/\bnew\s+Lenis\s*\(|\b(?:window\.)?lenis\s*\.\s*(?:raf|start|stop|scrollTo|destroy)\s*\(/i', $code);
            if (!$is_lenis_asset && !$owns_lenis) continue;
            $script->parentNode?->removeChild($script);
            $removed = true;
        }
        foreach (iterator_to_array($dom->getElementsByTagName('style')) as $style) {
            if (!$style instanceof DOMElement) continue;
            $css = (string) $style->textContent;
            if (!preg_match('/(?:html|body)?\.lenis(?:-|\b)|\[data-lenis-/i', $css)) continue;
            $style->parentNode?->removeChild($style);
            $removed = true;
        }
        foreach (iterator_to_array($dom->getElementsByTagName('*')) as $element) {
            if (!$element instanceof DOMElement) continue;
            $classes = preg_split('/\s+/', trim($element->getAttribute('class'))) ?: [];
            $clean_classes = array_values(array_filter(
                $classes,
                static fn(string $class): bool => $class !== '' && !preg_match('/^lenis(?:-|$)/i', $class)
            ));
            if ($clean_classes !== $classes) {
                if ($clean_classes === []) $element->removeAttribute('class');
                else $element->setAttribute('class', implode(' ', $clean_classes));
                $removed = true;
            }
            foreach (iterator_to_array($element->attributes ?? []) as $attribute) {
                if (!str_starts_with(strtolower($attribute->name), 'data-lenis')) continue;
                $element->removeAttribute($attribute->name);
                $removed = true;
            }
        }
        if (!$removed) return;

        $root = $dom->documentElement;
        if ($root instanceof DOMElement) $root->setAttribute('data-kodety-runtime-removed', 'lenis');
        $head = $dom->getElementsByTagName('head')->item(0);
        if (!$head instanceof DOMElement) {
            $head = $dom->createElement('head');
            $root?->insertBefore($head, $root->firstChild);
        }
        $style = $dom->createElement('style');
        $style->setAttribute('data-kodety-native-scroll', '');
        $style->appendChild($dom->createTextNode(
            'html{scroll-behavior:smooth}@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'
        ));
        $head->appendChild($style);
    }

    /**
     * Turn a fetched HTML document into a self-contained page: absolute asset
     * URLs and inlined stylesheets. Elementor, Webflow and authored-code imports
     * preserve their published JavaScript so interactive widgets keep working.
     */
    private function prepare_imported_html(string $html, string $base_url, string $platform = 'framer'): string {
        $preserve_runtime = in_array($platform, ['webflow', 'elementor', 'code'], true);
        if (!class_exists('DOMDocument')) {
            // Minimal fallback: inject a <base> so relative URLs still resolve.
            $tag = '<base href="' . esc_url($base_url) . '">';
            return preg_match('~<head[^>]*>~i', $html)
                ? (string) preg_replace('~(<head[^>]*>)~i', '$1' . $tag, $html, 1)
                : $tag . $html;
        }
        $previous = libxml_use_internal_errors(true);
        $dom = new DOMDocument();
        $dom->loadHTML('<?xml encoding="utf-8" ?>' . $html, LIBXML_NOWARNING | LIBXML_NOERROR | LIBXML_COMPACT);
        libxml_clear_errors();
        libxml_use_internal_errors($previous);

        // Prefer an explicit <base href> for relative resolution, then drop it.
        $document_base = $base_url;
        // Authorization comes only from the fetched document URL. A remote
        // page-controlled <base> may change relative resolution, never grant
        // access to files on this WordPress host.
        $allow_local_files = $this->import_source_is_same_wordpress($base_url);
        foreach (iterator_to_array($dom->getElementsByTagName('base')) as $base_node) {
            $href = $base_node->getAttribute('href');
            if ($href !== '') $document_base = $this->import_absolutize_url($href, $base_url);
            $base_node->parentNode?->removeChild($base_node);
        }

        // Source CSP/refresh directives cannot govern the Builder's sandbox and
        // can otherwise block local project resources or navigate the canvas.
        foreach (iterator_to_array($dom->getElementsByTagName('meta')) as $meta) {
            if (!$meta instanceof DOMElement) continue;
            $http_equiv = strtolower(trim($meta->getAttribute('http-equiv')));
            if (in_array($http_equiv, ['content-security-policy', 'refresh'], true)) $meta->parentNode?->removeChild($meta);
        }

        // The published HTML contains exact entrance-animation and responsive
        // metadata even though its React hydration cannot safely remain active
        // inside an editable Builder document. Extract it before scripts leave.
        if ($platform === 'framer') $this->import_extract_framer_manifest($dom, $document_base);
        $this->import_remove_platform_badges($dom, $platform);
        if ($platform === 'framer') {
            $this->import_attach_framer_visual_cleanup($dom);
            $this->import_promote_framer_layer_labels($dom);
        } elseif ($platform === 'elementor') {
            $this->import_promote_elementor_layer_labels($dom);
            $this->import_harden_elementor_runtime_document($dom);
            $this->import_remove_elementor_lenis_runtime($dom);
        }

        // Framer hydration is incompatible with its captured/static DOM. In
        // Webflow and authored code, however, the source runtime is the most
        // accurate representation of interactions, variants and components.
        if (!$preserve_runtime) {
            foreach (iterator_to_array($dom->getElementsByTagName('script')) as $script) {
                if (!$script instanceof DOMElement) continue;
                // Framer's appear/breakpoint/handover payloads are inert data,
                // not executable code. The archived local runtime consumes them
                // later in Preview/publication, so keep these exact payloads.
                $type = strtolower(trim($script->getAttribute('type')));
                if (in_array($type, ['framer/appear', 'framer/handover', 'application/ld+json', 'application/json', 'text/plain', 'text/template', 'text/x-template'], true)) continue;
                $script->parentNode?->removeChild($script);
            }
            foreach (iterator_to_array($dom->getElementsByTagName('noscript')) as $noscript) {
                $noscript->parentNode?->removeChild($noscript);
            }
            if ($platform === 'framer') $this->import_attach_framer_responsive_runtime($dom);
        }

        $url_attributes = ['href', 'src', 'poster', 'data-src', 'data-lazy-src', 'data-original'];
        $css_budget = ['count' => 0, 'bytes' => 0];
        foreach (iterator_to_array($dom->getElementsByTagName('*')) as $node) {
            if (!$node instanceof DOMElement) continue;
            $tag = strtolower($node->tagName);

            // These links only bootstrap the original application's runtime.
            // Keeping them after scripts are removed wastes bandwidth and, on
            // Framer exports, can pull the hydration bundle back into a static
            // project that the Builder is expected to own from this point on.
            if (!$preserve_runtime && $tag === 'link') {
                $rels = preg_split('~\s+~', strtolower(trim($node->getAttribute('rel')))) ?: [];
                if (array_intersect($rels, ['modulepreload', 'prefetch', 'preconnect', 'dns-prefetch'])) {
                    $node->parentNode?->removeChild($node);
                    continue;
                }
            }

            // Inline stylesheets so the page keeps its styling standalone.
            if ($tag === 'link' && $this->import_is_stylesheet_link($node)) {
                $href = trim($node->getAttribute('href'));
                $css_url = $href === '' ? '' : $this->import_absolutize_url($href, $document_base);
                $media = $node->getAttribute('media');
                // `preload as=style` uses media="print" as an async trick; the
                // real intent is all media, so don't carry that constraint over.
                if (strtolower(trim($media)) === 'print' && strtolower($node->getAttribute('as')) === 'style') $media = '';
                $inlined = $css_url === '' ? null : $this->import_fetch_stylesheet($css_url, $css_budget, 0, $allow_local_files);
                if ($inlined !== null) {
                    $style = $dom->createElement('style');
                    if ($media !== '' && strtolower(trim($media)) !== 'all') $style->setAttribute('media', $media);
                    $style->appendChild($dom->createTextNode("\n" . $inlined . "\n"));
                    $node->parentNode?->replaceChild($style, $node);
                    continue;
                }
                // Fallback: keep the link but make its href absolute.
                if ($css_url !== '') $node->setAttribute('href', $css_url);
                continue;
            }

            // Promote lazy-loaded media so the real asset renders in the editor
            // instead of a 1x1 placeholder. Real src/srcset win when already set.
            if ($tag === 'img' || $tag === 'source') {
                foreach (['data-srcset', 'data-lazy-srcset'] as $lazy) {
                    if ($node->hasAttribute($lazy) && trim($node->getAttribute($lazy)) !== '' && trim($node->getAttribute('srcset')) === '') {
                        $node->setAttribute('srcset', $node->getAttribute($lazy));
                        break;
                    }
                }
                foreach (['data-src', 'data-lazy-src', 'data-original'] as $lazy) {
                    if ($node->hasAttribute($lazy) && trim($node->getAttribute($lazy)) !== '') {
                        $current = trim($node->getAttribute('src'));
                        // Overwrite empty or obvious placeholder sources.
                        if ($current === '' || str_starts_with($current, 'data:') || preg_match('~(blank|placeholder|spacer|1x1|lazy)~i', $current)) {
                            $node->setAttribute('src', $node->getAttribute($lazy));
                        }
                        break;
                    }
                }
            }

            foreach (array_unique(array_merge($url_attributes, $this->import_asset_attributes($node))) as $attribute) {
                if (!$node->hasAttribute($attribute)) continue;
                $value = $node->getAttribute($attribute);
                if ($value === '') continue;
                $node->setAttribute($attribute, $this->import_absolutize_url($value, $document_base));
            }
            foreach (['srcset', 'data-srcset', 'data-lazy-srcset', 'imagesrcset'] as $attribute) {
                if ($node->hasAttribute($attribute)) {
                    $node->setAttribute($attribute, $this->import_absolutize_srcset($node->getAttribute($attribute), $document_base));
                }
            }
            if ($node->hasAttribute('data-video-urls')) {
                $node->setAttribute('data-video-urls', $this->import_map_video_urls($node->getAttribute('data-video-urls'), fn(string $url): string => $this->import_absolutize_url($url, $document_base)));
            }
            // Absolutize background-image and other url() refs in inline styles.
            if ($node->hasAttribute('style')) {
                $style_value = $node->getAttribute('style');
                if (preg_match('~(?:url|image-set)\(~i', $style_value)) {
                    $node->setAttribute('style', $this->import_rewrite_css_urls($style_value, $document_base));
                }
            }
            if ($tag === 'style') {
                $node->textContent = $this->import_expand_css($node->textContent, $document_base, $css_budget, 0, $allow_local_files);
                if ($platform === 'elementor') {
                    $node->textContent = (string) preg_replace('/\s*!\s*important\b/i', '', $node->textContent);
                }
            }
            if ($preserve_runtime && $tag === 'script' && strtolower(trim($node->getAttribute('type'))) === 'module' && !$node->hasAttribute('src')) {
                $node->textContent = $this->import_rewrite_inline_module_urls($node->textContent, $document_base);
            }
        }
        if ($platform === 'elementor') {
            // Stylesheets inlined from <link> nodes are created while walking the
            // original tree and therefore need one final normalization pass.
            foreach (iterator_to_array($dom->getElementsByTagName('style')) as $style) {
                if ($style instanceof DOMElement) {
                    $style->textContent = (string) preg_replace('/\s*!\s*important\b/i', '', $style->textContent);
                }
            }
        }

        // Guarantee a UTF-8 charset so the editor decodes the markup correctly.
        $head = $dom->getElementsByTagName('head')->item(0);
        if ($head instanceof DOMElement) {
            $has_charset = false;
            foreach (iterator_to_array($head->getElementsByTagName('meta')) as $meta) {
                if ($meta->hasAttribute('charset')) { $has_charset = true; break; }
            }
            if (!$has_charset) {
                $meta = $dom->createElement('meta');
                $meta->setAttribute('charset', 'utf-8');
                $head->insertBefore($meta, $head->firstChild);
            }
        }

        $output = $this->save_html_preserving_raw_text($dom);
        if (!is_string($output) || $output === '') $output = $html;
        else $output = (string) preg_replace('~<\?xml\s+encoding=["\\\']utf-8["\\\']\s*\?>~i', '', $output, 1);
        return $output;
    }

    /**
     * Download every render-critical resource referenced by a prepared page,
     * rewrite the document to project-relative paths and return a temporary ZIP.
     * Failed optional resources stay remote instead of aborting the whole import.
     */
    private function import_bundle_page_assets(string $html, string $source_url, string $platform = 'framer', string $framer_mode = 'animated'): string {
        if (!class_exists('ZipArchive')) throw new RuntimeException('A extensão PHP ZipArchive precisa estar habilitada na hospedagem.');
        if (!class_exists('DOMDocument')) return $this->wrap_html_as_project_zip($html);

        $previous = libxml_use_internal_errors(true);
        $dom = new DOMDocument();
        $loaded = $dom->loadHTML('<?xml encoding="utf-8" ?>' . $html, LIBXML_NOWARNING | LIBXML_NOERROR | LIBXML_COMPACT);
        libxml_clear_errors();
        libxml_use_internal_errors($previous);
        if (!$loaded) return $this->wrap_html_as_project_zip($html);
        $allow_local_files = $this->import_source_is_same_wordpress($source_url);

        if (in_array($platform, ['webflow', 'elementor', 'code'], true)) $this->import_prune_duplicate_runtime_scripts($dom);
        $framer_static = $platform === 'framer' && $framer_mode === 'static';

        // The isolated capture leaves only inert import metadata behind. Move
        // interaction rules to a real project CSS file so Hover/Pressed/Focus
        // are editable in the Builder's CSS Rule mode, and keep the runtime
        // animation manifest for the client-side Motion Timeline converter.
        $framer_interaction_css = '';
        foreach (iterator_to_array($dom->getElementsByTagName('style')) as $style_node) {
            if (!$style_node instanceof DOMElement || !$style_node->hasAttribute('data-kodety-framer-interactions')) continue;
            $framer_interaction_css .= trim($style_node->textContent) . "\n";
            $style_node->parentNode?->removeChild($style_node);
        }
        $framer_manifest_data = [];
        foreach (iterator_to_array($dom->getElementsByTagName('meta')) as $meta_node) {
            if (!$meta_node instanceof DOMElement || strtolower($meta_node->getAttribute('name')) !== 'kodety-framer-import') continue;
            $decoded = rawurldecode($meta_node->getAttribute('content'));
            $parsed = json_decode($decoded, true);
            if (is_array($parsed) && ($parsed['version'] ?? null) === 1) $framer_manifest_data = $this->import_merge_framer_manifests($framer_manifest_data, $parsed);
            $meta_node->parentNode?->removeChild($meta_node);
        }
        if ($framer_static) {
            // The captured DOM is already settled at its visible state. Static
            // mode deliberately drops every Framer hydration payload and load
            // animation while retaining responsive metadata and editable CSS.
            $framer_manifest_data['version'] = 1;
            $framer_manifest_data['source'] = $framer_manifest_data['source'] ?? 'framer-static';
            $framer_manifest_data['runtime'] = false;
            $framer_manifest_data['animations'] = [];
            if (is_array($framer_manifest_data['embedded'] ?? null)) {
                unset(
                    $framer_manifest_data['embedded']['runtimeEntrypoints'],
                    $framer_manifest_data['embedded']['runtimeModuleUrls'],
                    $framer_manifest_data['embedded']['localizedRuntimeEntrypoint'],
                    $framer_manifest_data['embedded']['localizedRuntimeFiles'],
                    $framer_manifest_data['embedded']['handoverRaw'],
                    $framer_manifest_data['embedded']['appear']
                );
            }
            foreach (iterator_to_array($dom->getElementsByTagName('script')) as $script) {
                if (!$script instanceof DOMElement) continue;
                $type = strtolower(trim($script->getAttribute('type')));
                if (in_array($type, ['framer/appear', 'framer/handover'], true)
                    || $script->hasAttribute('data-kodety-framer-baseline')
                    || $script->hasAttribute('data-kodety-framer-edit-guard')
                    || $script->hasAttribute('data-kodety-framer-compat-runtime')) $script->parentNode?->removeChild($script);
            }
            foreach (iterator_to_array($dom->getElementsByTagName('*')) as $element) {
                if (!$element instanceof DOMElement) continue;
                foreach (['data-framer-hydrate-v2', 'data-kodety-framer-baseline', 'data-kodety-framer-edit-guard', 'data-kodety-framer-compat-runtime'] as $attribute) {
                    $element->removeAttribute($attribute);
                }
            }
        }
        $framer_manifest = '';
        if (trim($framer_interaction_css) !== '') {
            $head = $dom->getElementsByTagName('head')->item(0);
            if ($head instanceof DOMElement) {
                $link = $dom->createElement('link');
                $link->setAttribute('rel', 'stylesheet');
                $link->setAttribute('href', 'styles/framer-interactions.css');
                $link->setAttribute('data-kodety-framer-interactions', '');
                $head->appendChild($link);
            }
        }

        /** @var array<string,array{body:string,path:string}> $downloaded */
        $downloaded = [];
        /** @var array<string,string> Content hash => canonical local path. */
        $downloaded_by_hash = [];
        /** @var array<string,string> $rewrites */
        $rewrites = [];
        $unresolved_assets = [];
        $budget = ['count' => 0, 'bytes' => 0];
        $runtime_budget = ['count' => 0, 'bytes' => 0];
        /** @var array<string,array{body:string,path:string}> $runtime_downloaded */
        $runtime_downloaded = [];
        /** @var array<string,string> $runtime_rewrites */
        $runtime_rewrites = [];
        $runtime_remote = [];

        $register = function (string $value) use (&$downloaded, &$downloaded_by_hash, &$rewrites, &$unresolved_assets, &$budget, $source_url, $allow_local_files): string {
            $absolute = $this->import_absolutize_url(html_entity_decode(trim($value), ENT_QUOTES | ENT_HTML5, 'UTF-8'), $source_url);
            if (!preg_match('~^https?://~i', $absolute)) return $value;
            $fragment = '';
            if (($hash = strpos($absolute, '#')) !== false) {
                $fragment = substr($absolute, $hash);
                $absolute = substr($absolute, 0, $hash);
            }
            if (isset($rewrites[$absolute])) return $rewrites[$absolute] . $fragment;
            if (isset($unresolved_assets[$absolute])) return $value;
            $asset = $this->import_download_asset($absolute, $budget, $allow_local_files);
            if ($asset === null) { $unresolved_assets[$absolute] = true; return $value; }
            $content_hash = hash('sha256', $asset['body']);
            if (isset($downloaded_by_hash[$content_hash])) {
                // Framer frequently exposes the same binary through several
                // CDN/query URLs. Keep one project file and point every markup
                // alias at it instead of multiplying ZIP, Media Library and
                // iframe memory usage.
                $rewrites[$absolute] = $downloaded_by_hash[$content_hash];
                return $rewrites[$absolute] . $fragment;
            }
            $path = $this->import_asset_path($absolute, $asset['contentType']);
            // Different query variants may resolve to identical names. The URL
            // hash makes paths stable and collision-free while keeping a useful
            // filename/extension for browsers and the media panel.
            $downloaded[$absolute] = ['body' => $asset['body'], 'path' => $path];
            $downloaded_by_hash[$content_hash] = $path;
            $rewrites[$absolute] = $path;
            return $path . $fragment;
        };

        $localize_embedded_asset_urls = function (string $text) use ($register): string {
            return (string) preg_replace_callback(
                '~https?://[^\s"\'`<>()\\\\,]+~i',
                static function (array $match) use ($register): string {
                    $url = rtrim($match[0], '.;:]}');
                    $suffix = substr($match[0], strlen($url));
                    $asset_path = (string) wp_parse_url($url, PHP_URL_PATH);
                    if (!preg_match('~(?:framerusercontent\.com/(?:images|assets|third-party-assets)/|\.(?:avif|gif|jpe?g|png|svg|webp|woff2?|ttf|otf|mp4|webm|json)(?:$|[?#]))~i', $url)
                        && !preg_match('~\.(?:avif|gif|jpe?g|png|svg|webp|woff2?|ttf|otf|mp4|webm|json)$~i', $asset_path)) return $match[0];
                    $path = $register($url);
                    return str_starts_with($path, 'assets/imported/') ? $path . $suffix : $match[0];
                },
                $text
            );
        };

        $register_runtime = null;
        $register_runtime = function (string $value, bool $is_module = false) use (&$register_runtime, &$runtime_downloaded, &$runtime_rewrites, &$runtime_remote, &$runtime_budget, $source_url, $platform, $allow_local_files, $register, $localize_embedded_asset_urls): string {
            $absolute = $this->import_absolutize_url(html_entity_decode(trim($value), ENT_QUOTES | ENT_HTML5, 'UTF-8'), $source_url);
            if (!preg_match('~^https?://~i', $absolute)) return $value;
            $absolute = (string) preg_replace('~#.*$~', '', $absolute);
            if (isset($runtime_rewrites[$absolute])) return $runtime_rewrites[$absolute];
            if (isset($runtime_remote[$absolute])) return $absolute;
            $asset = $this->import_download_runtime($absolute, $runtime_budget, $allow_local_files);
            if ($asset === null) { $runtime_remote[$absolute] = true; return $absolute; }
            $path = $this->import_runtime_path($absolute, $asset['contentType']);
            $runtime_rewrites[$absolute] = $path;
            $body = $asset['body'];
            $elementor_webpack_directory = '';
            if ($platform === 'elementor'
                && str_contains($body, '__webpack_require__.u')
                && preg_match('~["\'][A-Za-z0-9][A-Za-z0-9._-]{0,180}\.bundle(?:\.min)?\.js["\']~', $body)
            ) {
                // Webpack derives its publicPath from currentScript. Keep each
                // Elementor/add-on runtime and its exact-name lazy chunks in a
                // dedicated directory so carousels, tabs, counters, etc. can
                // still load after the origin site is gone.
                $elementor_webpack_directory = 'scripts/vendor/' . substr(hash('sha256', $absolute), 0, 12);
                $runtime_name = sanitize_file_name(basename((string) wp_parse_url($absolute, PHP_URL_PATH)));
                if ($runtime_name === '' || !str_ends_with(strtolower($runtime_name), '.js')) $runtime_name = 'webpack.runtime.js';
                $path = $elementor_webpack_directory . '/' . $runtime_name;
                $runtime_rewrites[$absolute] = $path;
            }
            if ($is_module || preg_match('~\bimport\s*\(~', $body)) {
                $body = (string) preg_replace_callback(
                    '~\b(from\s*|import\s*(?:\(\s*)?)(["\'`])((?:https?://|\.{0,2}/)[^"\'`]+)\2~',
                    function (array $match) use (&$register_runtime, $absolute): string {
                        if (str_contains($match[3], '${')) return $match[0];
                        $dependency_url = $this->import_absolutize_url($match[3], $absolute);
                        $dependency_path = $register_runtime($dependency_url, true);
                        $specifier = preg_match('~^https?://~i', $dependency_path) ? $dependency_path : './' . basename($dependency_path);
                        return $match[1] . $match[2] . $specifier . $match[2];
                    },
                    $body
                );
                $body = (string) preg_replace_callback(
                    '~new\s+URL\(\s*(["\'`])((?:https?://|\.{0,2}/)[^"\'`]+)\1\s*,\s*import\.meta\.url\s*\)~',
                    function (array $match) use ($register, $absolute): string {
                        if (str_contains($match[2], '${')) return $match[0];
                        $asset_url = $this->import_absolutize_url($match[2], $absolute);
                        $asset_path = $register($asset_url);
                        if (!str_starts_with($asset_path, 'assets/imported/')) return $match[0];
                        return 'new URL(' . $match[1] . '../../' . $asset_path . $match[1] . ',import.meta.url)';
                    },
                    $body
                );
                // Component definitions and CMS handover data often carry
                // image/font URLs as plain strings instead of new URL(). Keep
                // those variant assets local as well.
                $body = $localize_embedded_asset_urls($body);
            }
            if ($elementor_webpack_directory !== ''
                && preg_match_all(
                    '~["\']([A-Za-z0-9][A-Za-z0-9._-]{0,180}\.bundle(?:\.min)?\.js)["\']~',
                    $body,
                    $chunk_matches
                )
            ) {
                $chunk_names = array_slice(array_values(array_unique($chunk_matches[1])), 0, 100);
                foreach ($chunk_names as $chunk_name) {
                    $chunk_url = $this->import_absolutize_url($chunk_name, $absolute);
                    if (isset($runtime_downloaded[$chunk_url]) || isset($runtime_remote[$chunk_url])) continue;
                    $chunk_asset = $this->import_download_runtime($chunk_url, $runtime_budget, $allow_local_files);
                    if ($chunk_asset === null) {
                        $runtime_remote[$chunk_url] = true;
                        continue;
                    }
                    $chunk_path = $elementor_webpack_directory . '/' . $chunk_name;
                    $runtime_rewrites[$chunk_url] = $chunk_path;
                    // Do not rewrite minified widget code: filenames in the
                    // runtime already point beside currentScript byte-for-byte.
                    $runtime_downloaded[$chunk_url] = [
                        'body' => $chunk_asset['body'],
                        'path' => $chunk_path,
                    ];
                }
            }
            $runtime_downloaded[$absolute] = ['body' => $body, 'path' => $path];
            return $path;
        };

        // Framer publishes a real ESM dependency graph (React, Motion, route
        // components and variant definitions). The delayed browser capture
        // records modules that actually loaded; the embedded modulepreloads and
        // literal imports complete the graph recursively here.
        $framer_runtime_entry = '';
        $framer_runtime_active = false;
        $framer_runtime_audit = ['compatible' => false, 'issues' => []];
        if ($platform === 'framer' && !$framer_static && $framer_manifest_data) {
            $embedded = is_array($framer_manifest_data['embedded'] ?? null) ? $framer_manifest_data['embedded'] : [];
            $runtime_urls = is_array($embedded['runtimeModuleUrls'] ?? null) ? $embedded['runtimeModuleUrls'] : [];
            $entry_urls = is_array($embedded['runtimeEntrypoints'] ?? null) ? $embedded['runtimeEntrypoints'] : [];
            foreach (array_slice(array_values(array_unique(array_filter($runtime_urls, 'is_string'))), 0, 160) as $runtime_url) {
                if (preg_match('~^https?://~i', $runtime_url)) $register_runtime($runtime_url, true);
            }
            foreach (array_slice(array_values(array_unique(array_filter($entry_urls, 'is_string'))), 0, 4) as $entry_url) {
                if (!preg_match('~^https?://~i', $entry_url)) continue;
                $localized_entry = $register_runtime($entry_url, true);
                if ($framer_runtime_entry === '' && str_starts_with($localized_entry, 'scripts/vendor/')) $framer_runtime_entry = $localized_entry;
            }
        }

        foreach (iterator_to_array($dom->getElementsByTagName('*')) as $node) {
            if (!$node instanceof DOMElement) continue;
            $tag = strtolower($node->tagName);
            if ($platform === 'framer' && $tag === 'script' && strtolower(trim($node->getAttribute('type'))) === 'framer/handover') {
                $node->textContent = $localize_embedded_asset_urls($node->textContent);
            }
            if ($tag === 'script' && in_array($platform, ['webflow', 'elementor', 'code'], true) && $node->hasAttribute('src')) {
                $source = trim($node->getAttribute('src'));
                if ($source !== '') {
                    $localized = $register_runtime($source, strtolower(trim($node->getAttribute('type'))) === 'module');
                    $node->setAttribute('src', $localized);
                    if (!preg_match('~^https?://~i', $localized)) {
                        $node->removeAttribute('integrity');
                        $node->removeAttribute('crossorigin');
                    }
                }
            }
            if ($platform === 'elementor') {
                if ($tag === 'script' && !$node->hasAttribute('src')) {
                    $node->textContent = $localize_embedded_asset_urls($node->textContent);
                }
                foreach (iterator_to_array($node->attributes ?? []) as $attribute) {
                    $attribute_name = strtolower($attribute->name);
                    if (!str_contains($attribute_name, 'settings') && !str_contains($attribute_name, 'config')) continue;
                    $localized_value = $localize_embedded_asset_urls($attribute->value);
                    if ($localized_value !== $attribute->value) $node->setAttribute($attribute->name, $localized_value);
                }
            }
            foreach ($this->import_asset_attributes($node) as $attribute) {
                if (!$node->hasAttribute($attribute)) continue;
                $value = trim($node->getAttribute($attribute));
                if ($value === '') continue;
                $node->setAttribute($attribute, $register($value));
            }
            foreach (['srcset', 'data-srcset', 'data-lazy-srcset', 'imagesrcset'] as $srcset_attribute) {
                if ($node->hasAttribute($srcset_attribute)) {
                    $node->setAttribute($srcset_attribute, $this->import_map_srcset($node->getAttribute($srcset_attribute), $register));
                }
            }
            if ($node->hasAttribute('data-video-urls')) {
                $node->setAttribute('data-video-urls', $this->import_map_video_urls($node->getAttribute('data-video-urls'), $register));
            }
            if ($node->hasAttribute('style') && preg_match('~(?:url|image-set)\(~i', $node->getAttribute('style'))) {
                $node->setAttribute('style', $this->import_map_css_urls($node->getAttribute('style'), $register));
            }
            if ($tag === 'style' && preg_match('~(?:url|image-set)\(~i', $node->textContent)) {
                $node->textContent = $this->import_map_css_urls($node->textContent, $register);
            }
            if ($tag === 'meta' && $node->hasAttribute('content')) {
                $key = strtolower($node->getAttribute('property') ?: $node->getAttribute('name') ?: $node->getAttribute('itemprop'));
                if (in_array($key, ['og:image', 'og:image:url', 'twitter:image', 'twitter:image:src', 'image'], true)) {
                    $node->setAttribute('content', $register($node->getAttribute('content')));
                }
            }
        }

        // Authored Webflow bundles often reference GSAP globals at module
        // evaluation time, while their library tags live later in the page.
        // Localizing those files must not preserve an accidentally racy order.
        if (in_array($platform, ['webflow', 'elementor', 'code'], true)) {
            $runtime_bodies_by_path = [];
            foreach ($runtime_downloaded as $runtime_asset) {
                $runtime_bodies_by_path[$runtime_asset['path']] = $runtime_asset['body'];
            }
            $this->stabilize_script_dependencies(
                $dom,
                static function (DOMElement $script) use ($runtime_bodies_by_path): string {
                    $source = preg_replace('~[?#].*$~', '', trim($script->getAttribute('src'))) ?: '';
                    return $runtime_bodies_by_path[$source] ?? '';
                }
            );
        }

        if ($platform === 'framer' && !$framer_static && $framer_runtime_entry !== '') {
            $framer_runtime_audit = $this->import_audit_framer_runtime_graph($framer_runtime_entry, $runtime_downloaded);
            if ($framer_runtime_audit['compatible']) {
                $framer_runtime_active = $this->import_attach_framer_compat_runtime($dom, $framer_runtime_entry, $rewrites);
            }
            if (!is_array($framer_manifest_data['embedded'] ?? null)) $framer_manifest_data['embedded'] = [];
            $framer_manifest_data['embedded']['localizedRuntimeEntrypoint'] = $framer_runtime_entry;
            $framer_manifest_data['embedded']['localizedRuntimeFiles'] = array_values(array_map(static fn(array $asset): string => $asset['path'], $runtime_downloaded));
            $framer_manifest_data['embedded']['runtimeCompatibility'] = $framer_runtime_active ? 'compatible' : 'archived-incompatible';
            if (!$framer_runtime_active && $framer_runtime_audit['issues']) {
                $framer_manifest_data['embedded']['runtimeCompatibilityIssues'] = $framer_runtime_audit['issues'];
            }
            if ($framer_runtime_active) {
                $framer_manifest_data['runtime'] = true;
            } else {
                $framer_manifest_data['runtime'] = false;
            }
        }
        $framer_manifest = $framer_manifest_data
            ? (string) wp_json_encode($framer_manifest_data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)
            : '';

        $output = $this->save_html_preserving_raw_text($dom);
        if (!is_string($output) || $output === '') $output = $html;
        else $output = (string) preg_replace('~<\?xml\s+encoding=["\\\']utf-8["\\\']\s*\?>~i', '', $output, 1);
        $path = tempnam(get_temp_dir(), 'kodety-page-assets-');
        if ($path === false) throw new RuntimeException('Não foi possível criar o pacote temporário da página.');
        $zip = new ZipArchive();
        if ($zip->open($path, ZipArchive::OVERWRITE) !== true) {
            @unlink($path);
            throw new RuntimeException('Não foi possível montar o projeto importado.');
        }
        try {
            $zip->addFromString('index.html', $output);
            $zip->addFromString('.incode/url-import.json', (string) wp_json_encode([
                'version' => 1,
                'source' => 'url-import',
                'sourceUrl' => $source_url,
                'platform' => $platform,
                'framerMode' => $platform === 'framer' ? ($framer_static ? 'static' : 'animated') : null,
                'runtime' => $platform === 'elementor'
                    ? 'published-runtime-preserved'
                    : (in_array($platform, ['webflow', 'code'], true) ? 'preserved' : ($framer_static ? 'static-editable' : ($framer_runtime_active ? 'preserved-guarded' : ($framer_runtime_entry !== '' ? 'archived-incompatible' : 'detached-hybrid')))),
                'localizedRuntimeFiles' => array_values(array_map(static fn(array $asset): string => $asset['path'], $runtime_downloaded)),
                'remoteRuntimeUrls' => array_slice(array_keys($runtime_remote), 0, 100),
                'runtimeCompatibilityIssues' => $framer_runtime_audit['issues'],
                'localizedAssetCount' => count($downloaded),
                'unresolvedAssetUrls' => array_slice(array_keys($unresolved_assets), 0, 100),
            ], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
            if ($platform === 'elementor') {
                $title_node = $dom->getElementsByTagName('title')->item(0);
                $project_name = $title_node instanceof DOMElement
                    ? trim(sanitize_text_field($title_node->textContent))
                    : '';
                if ($project_name === '') $project_name = 'Importação visual do Elementor';
                $zip->addFromString('.incode/project.json', (string) wp_json_encode([
                    'version' => 1,
                    'name' => substr($project_name, 0, 120),
                    'mainHtmlPath' => 'index.html',
                    'homeHtmlPath' => 'index.html',
                    'rootPath' => '',
                ], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
                $zip->addFromString('.incode/elementor-import.json', (string) wp_json_encode([
                    'version' => 1,
                    'source' => 'elementor',
                    'mode' => 'published-runtime',
                    'sourceUrl' => $source_url,
                    'runtime' => 'published-runtime-preserved',
                    'localizedRuntimeFiles' => array_values(array_map(static fn(array $asset): string => $asset['path'], $runtime_downloaded)),
                    'remoteRuntimeUrls' => array_slice(array_keys($runtime_remote), 0, 100),
                    'localizedAssetCount' => count($downloaded),
                    'unresolvedAssetUrls' => array_slice(array_keys($unresolved_assets), 0, 100),
                    'warnings' => array_values(array_filter([
                        $runtime_remote ? 'Alguns scripts não puderam ser localizados e continuam apontando para a origem.' : '',
                        'Widgets que dependem de AJAX, nonces, WooCommerce ou plugins do servidor original podem exigir integração manual com o backend Onun Kodety.',
                    ])),
                ], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
            }
            if (trim($framer_interaction_css) !== '') {
                $clean_interaction_css = (string) preg_replace('/\s*!\s*important\b/i', '', trim($framer_interaction_css));
                $zip->addFromString('styles/framer-interactions.css', $clean_interaction_css . "\n");
            }
            if ($framer_manifest !== '') $zip->addFromString('.incode/framer-import.json', $framer_manifest);
            foreach ($downloaded as $asset) $zip->addFromString($asset['path'], $asset['body']);
            foreach ($runtime_downloaded as $asset) {
                // JavaScript is executable source, not a CSS stylesheet. Regex
                // rewriting can corrupt strings/minified code and break widgets;
                // preserve the downloaded runtime byte-for-byte.
                $zip->addFromString($asset['path'], $asset['body']);
            }
        } finally {
            $zip->close();
        }
        return $path;
    }

    /** Resource-bearing attributes only; ordinary navigation links stay links. */
    private function import_asset_attributes(DOMElement $node): array {
        $tag = strtolower($node->tagName);
        // Webflow stores the poster on the wrapping .w-background-video div.
        $attributes = $node->hasAttribute('data-poster-url') ? ['data-poster-url'] : [];
        return array_values(array_unique(array_merge($attributes, $this->import_tag_asset_attributes($node, $tag))));
    }

    private function import_tag_asset_attributes(DOMElement $node, string $tag): array {
        if (in_array($tag, ['img', 'source'], true)) return ['src', 'poster', 'data-src', 'data-lazy-src', 'data-original'];
        if (in_array($tag, ['video', 'audio', 'track', 'embed', 'input', 'iframe'], true)) return ['src', 'poster', 'data-src', 'data-poster-url'];
        if ($tag === 'object') return ['data'];
        if (in_array($tag, ['image', 'use'], true)) return ['href', 'xlink:href'];
        if ($tag !== 'link') return [];
        $rels = preg_split('~\s+~', strtolower(trim($node->getAttribute('rel')))) ?: [];
        $as = strtolower(trim($node->getAttribute('as')));
        if (array_intersect($rels, ['icon', 'apple-touch-icon', 'mask-icon'])) return ['href'];
        if (in_array('preload', $rels, true) && in_array($as, ['font', 'image', 'audio', 'video'], true)) return ['href'];
        return [];
    }

    /** Webflow's background video runtime consumes a comma-delimited URL list. */
    private function import_map_video_urls(string $value, callable $map): string {
        return implode(',', array_map(static fn(string $url): string => trim($url) === '' ? $url : (string) $map(trim($url)), explode(',', $value)));
    }

    /** Remove only redundant runtime copies that appear after an equal/newer one. */
    private function import_prune_duplicate_runtime_scripts(DOMDocument $dom): void {
        $seen_urls = [];
        $seen_libraries = [];
        foreach (iterator_to_array($dom->getElementsByTagName('script')) as $script) {
            if (!$script instanceof DOMElement || !$script->hasAttribute('src')) continue;
            $source = trim($script->getAttribute('src'));
            if ($source === '') continue;
            $normalized = strtolower(preg_replace('~[?#].*$~', '', $source) ?: $source);
            if (isset($seen_urls[$normalized])) {
                $script->parentNode?->removeChild($script);
                continue;
            }
            $seen_urls[$normalized] = true;

            $library = '';
            $version = '0.0.0';
            if (preg_match('~/gsap/([0-9]+(?:\.[0-9]+){1,2})/gsap(?:\.min)?\.js$~i', $normalized, $match)) {
                $library = 'gsap'; $version = $match[1];
            } elseif (preg_match('~/gsap/([0-9]+(?:\.[0-9]+){1,2})/scrolltrigger(?:\.min)?\.js$~i', $normalized, $match)) {
                $library = 'scrolltrigger'; $version = $match[1];
            } elseif (preg_match('~(?:unpkg\.com|cdn\.jsdelivr\.net/npm)/split-type(?:@([0-9]+(?:\.[0-9]+){1,2}))?~i', $normalized, $match)) {
                $library = 'split-type'; $version = $match[1] ?? '0.0.0';
            }
            if ($library === '') continue;
            if (isset($seen_libraries[$library]) && version_compare($seen_libraries[$library], $version, '>=')) {
                $script->parentNode?->removeChild($script);
                continue;
            }
            $seen_libraries[$library] = $version;
        }
    }

    /**
     * Put global GSAP dependencies before the first script that consumes them.
     * If an inline classic script consumes those globals, the dependencies must
     * remain synchronous: `defer` on an external script does not delay inline
     * code and would otherwise produce `gsap is not defined` during parsing.
     *
     * @param callable(DOMElement):string $external_body
     * @return array<string,true> Script sources that must not receive defer later.
     */
    private function stabilize_script_dependencies(DOMDocument $dom, callable $external_body): array {
        $scripts = array_values(array_filter(
            iterator_to_array($dom->getElementsByTagName('script')),
            static fn($script): bool => $script instanceof DOMElement
        ));
        $dependencies = [];
        $consumers = [];
        $has_inline_consumer = false;
        foreach ($scripts as $index => $script) {
            $source = strtolower((string) preg_replace('~[?#].*$~', '', trim($script->getAttribute('src'))));
            $kind = '';
            $priority = 100;
            if (preg_match('~(?:^|[-_/])gsap(?:\.min)?_?\.js$~i', $source)) {
                $kind = 'gsap';
                $priority = 10;
            } elseif (preg_match('~(?:scrolltrigger|splittext|customease|drawsvgplugin|inertiaplugin|motionpathplugin|scrollsmoother|morphsvgplugin|draggable|observer|flip)(?:\.min)?_?\.js$~i', $source)) {
                $kind = 'gsap-plugin';
                $priority = 20;
            }
            if ($kind !== '') {
                $dependencies[] = ['node' => $script, 'priority' => $priority, 'index' => $index];
                continue;
            }
            $body = $script->hasAttribute('src') ? (string) $external_body($script) : $script->textContent;
            if ($body === '' || !preg_match('~\b(?:gsap|ScrollTrigger|SplitText|CustomEase|DrawSVGPlugin|InertiaPlugin|MotionPathPlugin|ScrollSmoother|MorphSVGPlugin|Draggable|Observer|Flip)\b~', $body)) continue;
            $consumers[] = ['node' => $script, 'index' => $index];
            if (!$script->hasAttribute('src') && strtolower(trim($script->getAttribute('type'))) !== 'module') $has_inline_consumer = true;
        }
        if (!$dependencies || !$consumers) return [];
        usort($dependencies, static fn(array $left, array $right): int => [$left['priority'], $left['index']] <=> [$right['priority'], $right['index']]);
        usort($consumers, static fn(array $left, array $right): int => $left['index'] <=> $right['index']);
        $anchor = $consumers[0]['node'];
        $parent = $anchor->parentNode;
        if (!$parent instanceof DOMNode) return [];
        $synchronous = [];
        foreach ($dependencies as $dependency) {
            /** @var DOMElement $node */
            $node = $dependency['node'];
            if ($has_inline_consumer) {
                $node->removeAttribute('async');
                $node->removeAttribute('defer');
                $synchronous[$node->getAttribute('src')] = true;
            }
            $parent->insertBefore($node, $anchor);
        }
        return $synchronous;
    }

    /**
     * Read a same-install static WordPress resource without a loopback HTTP
     * request. Only public URL roots and explicitly allowed extensions are
     * mapped; realpath containment prevents traversal and escaping symlinks.
     *
     * @param list<string> $allowed_extensions
     * @return array{body:string,contentType:string}|null
     */
    private function import_read_local_wordpress_resource(string $url, int $limit, array $allowed_extensions): ?array {
        if ($limit <= 0 || !preg_match('~^https?://~i', $url)) return null;
        $parts = wp_parse_url($url);
        if (!is_array($parts) || empty($parts['host']) || empty($parts['path'])) return null;

        $mappings = [];
        if (defined('WP_CONTENT_DIR') && function_exists('content_url')) {
            $mappings[] = ['url' => content_url('/'), 'path' => WP_CONTENT_DIR];
        }
        if (defined('WP_PLUGIN_DIR') && function_exists('plugins_url')) {
            $mappings[] = ['url' => plugins_url('/'), 'path' => WP_PLUGIN_DIR];
        }
        if (function_exists('wp_upload_dir')) {
            $uploads = wp_upload_dir(null, false, false);
            if (is_array($uploads) && !empty($uploads['baseurl']) && !empty($uploads['basedir'])) {
                $mappings[] = ['url' => (string) $uploads['baseurl'], 'path' => (string) $uploads['basedir']];
            }
        }
        if (function_exists('get_theme_root_uri') && function_exists('get_theme_root')) {
            $mappings[] = ['url' => get_theme_root_uri(), 'path' => get_theme_root()];
        }
        if (defined('ABSPATH') && defined('WPINC') && function_exists('includes_url')) {
            $mappings[] = ['url' => includes_url('/'), 'path' => ABSPATH . WPINC];
        }

        $source_host = strtolower(rtrim((string) $parts['host'], '.'));
        $source_scheme = strtolower((string) ($parts['scheme'] ?? 'http'));
        $source_port = (int) ($parts['port'] ?? ($source_scheme === 'https' ? 443 : 80));
        $source_path = rawurldecode((string) $parts['path']);
        if ($source_path === '' || str_contains($source_path, "\0") || str_contains($source_path, '\\')) return null;

        foreach ($mappings as $mapping) {
            $base = wp_parse_url((string) $mapping['url']);
            if (!is_array($base) || empty($base['host'])) continue;
            $base_host = strtolower(rtrim((string) $base['host'], '.'));
            $base_scheme = strtolower((string) ($base['scheme'] ?? 'http'));
            $base_port = (int) ($base['port'] ?? ($base_scheme === 'https' ? 443 : 80));
            if (!hash_equals($base_host, $source_host) || $base_port !== $source_port) continue;

            $base_path = '/' . trim(rawurldecode((string) ($base['path'] ?? '/')), '/') . '/';
            $normalized_source_path = '/' . ltrim($source_path, '/');
            if (!str_starts_with($normalized_source_path, $base_path)) continue;
            $relative = ltrim(substr($normalized_source_path, strlen($base_path)), '/');
            if ($relative === '') continue;
            $segments = explode('/', $relative);
            if (array_filter($segments, static fn(string $segment): bool => $segment === '' || $segment === '.' || $segment === '..' || str_starts_with($segment, '.'))) continue;

            $extension = strtolower(pathinfo(end($segments), PATHINFO_EXTENSION));
            if ($extension === '' || !in_array($extension, $allowed_extensions, true)) continue;
            $root = realpath((string) $mapping['path']);
            $candidate = $root !== false ? realpath($root . DIRECTORY_SEPARATOR . implode(DIRECTORY_SEPARATOR, $segments)) : false;
            if ($root === false || $candidate === false || !is_file($candidate) || !is_readable($candidate)) continue;
            $root_prefix = rtrim($root, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR;
            if (!str_starts_with($candidate, $root_prefix)) continue;
            $size = filesize($candidate);
            if (!is_int($size) || $size <= 0 || $size > $limit) return null;
            $body = file_get_contents($candidate);
            if (!is_string($body) || $body === '' || strlen($body) > $limit) return null;

            $content_types = [
                'avif' => 'image/avif', 'bmp' => 'image/bmp', 'css' => 'text/css',
                'eot' => 'application/vnd.ms-fontobject', 'gif' => 'image/gif', 'ico' => 'image/x-icon',
                'jpeg' => 'image/jpeg', 'jpg' => 'image/jpeg', 'js' => 'application/javascript',
                'json' => 'application/json', 'm4a' => 'audio/mp4', 'mjs' => 'application/javascript',
                'mp3' => 'audio/mpeg', 'mp4' => 'video/mp4', 'ogg' => 'audio/ogg', 'ogv' => 'video/ogg',
                'otf' => 'font/otf', 'pdf' => 'application/pdf', 'png' => 'image/png',
                'svg' => 'image/svg+xml', 'ttf' => 'font/ttf', 'webm' => 'video/webm',
                'webp' => 'image/webp', 'woff' => 'font/woff', 'woff2' => 'font/woff2',
            ];
            return ['body' => $body, 'contentType' => $content_types[$extension] ?? 'application/octet-stream'];
        }
        return null;
    }

    /** @return array{body:string,contentType:string}|null */
    private function import_download_runtime(string $url, array &$budget, bool $allow_local_files = false): ?array {
        if ($budget['count'] >= 120 || $budget['bytes'] >= 48 * MB_IN_BYTES) return null;
        // Count attempts, not only successful files. Otherwise a page with many
        // unique broken imports could bypass the graph limit indefinitely.
        $budget['count']++;
        $remaining = 48 * MB_IN_BYTES - $budget['bytes'];
        $limit = min(8 * MB_IN_BYTES, $remaining);
        if ($limit <= 0) return null;
        $local = $allow_local_files
            ? $this->import_read_local_wordpress_resource($url, $limit, ['js', 'mjs'])
            : null;
        if (is_array($local)) {
            if (preg_match('~^\s*<(?:!doctype\s+html|html\b)~i', $local['body'])) return null;
            $budget['bytes'] += strlen($local['body']);
            return $local;
        }
        if (!wp_http_validate_url($url)) return null;
        $response = $this->import_safe_remote_get($url, [
            'timeout' => 20,
            'redirection' => 4,
            'reject_unsafe_urls' => true,
            'limit_response_size' => $limit + 1,
            'user-agent' => 'KodetyImporter/1.0 (+WordPress)',
            'headers' => ['Accept' => 'text/javascript,application/javascript,text/plain,application/octet-stream,*/*;q=0.3'],
        ]);
        if (is_wp_error($response)) return null;
        $status = (int) wp_remote_retrieve_response_code($response);
        if ($status < 200 || $status >= 300) return null;
        $body = (string) wp_remote_retrieve_body($response);
        if ($body === '' || strlen($body) > $limit || preg_match('~^\s*<(?:!doctype\s+html|html\b)~i', $body)) return null;
        $content_type = strtolower(trim(explode(';', (string) wp_remote_retrieve_header($response, 'content-type'))[0]));
        $budget['bytes'] += strlen($body);
        return ['body' => $body, 'contentType' => $content_type];
    }

    private function import_runtime_path(string $url, string $content_type): string {
        $path = rawurldecode((string) wp_parse_url($url, PHP_URL_PATH));
        $name = sanitize_file_name(basename($path));
        $extension = strtolower(pathinfo($name, PATHINFO_EXTENSION));
        // Browsers enforce the MIME type of ES modules. Several WordPress
        // hosts (especially Nginx/CDN stacks) still serve .mjs as
        // application/octet-stream, which archives the complete graph but
        // prevents hydration on the published site. Localized runtime files
        // are JavaScript regardless of their source suffix, so canonicalize
        // them to the universally supported .js extension.
        $stem = sanitize_file_name(pathinfo($name, PATHINFO_FILENAME)) ?: 'runtime';
        $name = $stem . '.js';
        return 'scripts/vendor/' . substr(hash('sha256', $url), 0, 12) . '-' . ($name ?: 'runtime.js');
    }

    /** @return array{body:string,contentType:string}|null */
    private function import_download_asset(string $url, array &$budget, bool $allow_local_files = false): ?array {
        if ($budget['count'] >= 400 || $budget['bytes'] >= 96 * MB_IN_BYTES) return null;
        // Failed/invalid responses consume the request budget as well. This is
        // the hard stop for pages that emit hundreds of distinct dead URLs.
        $budget['count']++;
        $remaining = 96 * MB_IN_BYTES - $budget['bytes'];
        $limit = min(16 * MB_IN_BYTES, $remaining);
        if ($limit <= 0) return null;
        $local = $allow_local_files
            ? $this->import_read_local_wordpress_resource($url, $limit, [
                'avif','bmp','css','eot','gif','ico','jpeg','jpg','json','m4a','mp3','mp4','ogg','ogv',
                'otf','pdf','png','svg','ttf','webm','webp','woff','woff2',
            ])
            : null;
        if (is_array($local)) {
            $budget['bytes'] += strlen($local['body']);
            return $local;
        }
        if (!wp_http_validate_url($url)) return null;
        $response = $this->import_safe_remote_get($url, [
            'timeout' => 15,
            'redirection' => 3,
            'reject_unsafe_urls' => true,
            'limit_response_size' => $limit + 1,
            'user-agent' => 'KodetyImporter/1.0 (+WordPress)',
            'headers' => ['Accept' => 'image/*,font/*,audio/*,video/*,application/octet-stream,*/*;q=0.5'],
        ]);
        if (is_wp_error($response)) return null;
        $status = (int) wp_remote_retrieve_response_code($response);
        if ($status < 200 || $status >= 300) return null;
        $body = (string) wp_remote_retrieve_body($response);
        if ($body === '' || strlen($body) > $limit || preg_match('~^(?:\xEF\xBB\xBF)?\s*<(?:!doctype\s+html|html\b)~i', $body)) return null;
        $content_type = strtolower(trim(explode(';', (string) wp_remote_retrieve_header($response, 'content-type'))[0]));
        // Never package executable/server content masquerading as a visual asset.
        if (preg_match('~(?:text/(?:html|javascript)|application/(?:xhtml\+xml|javascript|x-javascript|x-httpd-php|x-php))~i', $content_type)) return null;
        $budget['bytes'] += strlen($body);
        return ['body' => $body, 'contentType' => $content_type];
    }

    private function import_asset_path(string $url, string $content_type): string {
        $path = rawurldecode((string) wp_parse_url($url, PHP_URL_PATH));
        $name = sanitize_file_name(basename($path));
        $extension = strtolower(pathinfo($name, PATHINFO_EXTENSION));
        $allowed = ['avif','bmp','css','eot','gif','ico','jpeg','jpg','json','m4a','mp3','mp4','ogg','ogv','otf','pdf','png','svg','ttf','webm','webp','woff','woff2'];
        if (!in_array($extension, $allowed, true)) {
            $extensions = [
                'image/avif' => 'avif', 'image/gif' => 'gif', 'image/jpeg' => 'jpg', 'image/png' => 'png',
                'image/svg+xml' => 'svg', 'image/webp' => 'webp', 'image/x-icon' => 'ico',
                'font/otf' => 'otf', 'font/ttf' => 'ttf', 'font/woff' => 'woff', 'font/woff2' => 'woff2',
                'application/font-woff' => 'woff', 'application/pdf' => 'pdf',
                'audio/mpeg' => 'mp3', 'video/mp4' => 'mp4', 'video/webm' => 'webm',
            ];
            $extension = $extensions[$content_type] ?? 'bin';
            $stem = sanitize_file_name(pathinfo($name, PATHINFO_FILENAME)) ?: 'asset';
            $name = $stem . '.' . $extension;
        }
        return 'assets/imported/' . substr(hash('sha256', $url), 0, 12) . '-' . ($name !== '' ? $name : 'asset.' . $extension);
    }

    private function import_map_srcset(string $srcset, callable $map): string {
        // A comma is legal inside a URL (including data: and image CDN URLs).
        // Follow HTML's candidate tokenizer: first consume the URL up to ASCII
        // whitespace, then descriptors up to a comma outside parentheses.
        $length = strlen($srcset);
        $position = 0;
        $rebuilt = [];
        while ($position < $length) {
            $position += strspn($srcset, " \t\r\n\f,", $position);
            if ($position >= $length) break;
            $start = $position;
            $position += strcspn($srcset, " \t\r\n\f", $position);
            $url = substr($srcset, $start, $position - $start);
            if (str_ends_with($url, ',')) {
                $rebuilt[] = $map(rtrim($url, ','));
                continue;
            }
            $start = $position;
            $parentheses = 0;
            while ($position < $length) {
                $character = $srcset[$position];
                if ($character === ',' && $parentheses === 0) break;
                if ($character === '(') $parentheses++;
                if ($character === ')' && $parentheses > 0) $parentheses--;
                $position++;
            }
            $descriptor = trim(substr($srcset, $start, $position - $start));
            $rebuilt[] = $map($url) . ($descriptor !== '' ? ' ' . $descriptor : '');
            $position++;
        }
        return implode(', ', $rebuilt);
    }

    private function import_map_css_urls(string $css, callable $map): string {
        // Quoted content and comments are opaque CSS tokens. Matching only
        // actual url() tokens avoids rewriting content:"url(example)" and
        // preserves parentheses, escaped quotes and SVG data URLs verbatim.
        $pattern = <<<'REGEX'
~ /\*[\s\S]*?\*/ (*SKIP)(*F)
| "(?:[^"\\]++|\\[\s\S])*+" (*SKIP)(*F)
| '(?:[^'\\]++|\\[\s\S])*+' (*SKIP)(*F)
| @import\b(?:/\*[\s\S]*?\*/|"(?:[^"\\]++|\\[\s\S])*+"|'(?:[^'\\]++|\\[\s\S])*+'|[^;"'/]++|/(?!\*))*+; (*SKIP)(*F)
| (?<![\w-])url\(\s*(?:"(?<double>(?:[^"\\]++|\\[\s\S])*+)"|'(?<single>(?:[^'\\]++|\\[\s\S])*+)'|(?<bare>(?:[^\\\s()'"]++|\\(?:[0-9a-f]{1,6}\s?|[^\r\n\f]))*+))\s*\)
~ix
REGEX;
        $css = preg_replace_callback($pattern, function (array $match) use ($map): string {
            $raw = $match['double'] ?? $match['single'] ?? $match['bare'] ?? '';
            $url = $this->import_decode_css_string($raw);
            if ($url === '' || preg_match('~^(data:|blob:|#)~i', $url)) return $match[0];
            $mapped = (string) $map($url);
            return $mapped === $url ? $match[0] : 'url(' . $this->import_quote_css_string($mapped) . ')';
        }, $css, -1, $unused, PREG_UNMATCHED_AS_NULL) ?? $css;

        // CSS Images also accepts image-set("small.webp" 1x, "large.webp" 2x).
        // Only candidate strings are URLs; type("image/avif") stays untouched.
        $image_set_pattern = <<<'REGEX'
~ /\*[\s\S]*?\*/ (*SKIP)(*F) | "(?:[^"\\]++|\\[\s\S])*+" (*SKIP)(*F) | '(?:[^'\\]++|\\[\s\S])*+' (*SKIP)(*F) | (?<![\w-])(?:-webkit-)?image-set\( ~ix
REGEX;
        $offset = 0;
        while (preg_match($image_set_pattern, $css, $match, PREG_OFFSET_CAPTURE, $offset)) {
            $start = $match[0][1] + strlen($match[0][0]);
            $end = $this->import_css_closing_parenthesis($css, $start - 1);
            if ($end === null) break;
            $body = substr($css, $start, $end - $start);
            $candidate_pattern = <<<'REGEX'
~(?:^|,)(?:\s|/\*[\s\S]*?\*/)*\K(?:"(?<double>(?:[^"\\]++|\\[\s\S])*+)"|'(?<single>(?:[^'\\]++|\\[\s\S])*+)')~
REGEX;
            $mapped_body = preg_replace_callback($candidate_pattern, function (array $candidate) use ($map): string {
                $url = $this->import_decode_css_string($candidate['double'] ?? $candidate['single'] ?? '');
                if ($url === '' || preg_match('~^(data:|blob:|#)~i', $url)) return $candidate[0];
                $mapped = (string) $map($url);
                return $mapped === $url ? $candidate[0] : $this->import_quote_css_string($mapped);
            }, $body, -1, $unused, PREG_UNMATCHED_AS_NULL) ?? $body;
            $css = substr_replace($css, $mapped_body, $start, $end - $start);
            $offset = $start + strlen($mapped_body) + 1;
        }
        return $css;
    }

    private function import_decode_css_string(string $value): string {
        return preg_replace_callback('~\\\\(?:([0-9a-f]{1,6})(?:\r\n|[ \t\r\n\f])?|(\r\n|[\r\n\f])|([\s\S]))~i', static function (array $match): string {
            if (($match[1] ?? '') !== '') {
                $codepoint = hexdec($match[1]);
                if ($codepoint === 0 || $codepoint > 0x10ffff || ($codepoint >= 0xd800 && $codepoint <= 0xdfff)) return "\xef\xbf\xbd";
                return html_entity_decode('&#' . $codepoint . ';', ENT_NOQUOTES, 'UTF-8');
            }
            return $match[3] ?? '';
        }, $value) ?? $value;
    }

    private function import_quote_css_string(string $value): string {
        return '"' . strtr($value, ['\\' => '\\\\', '"' => '\\"', "\r" => '\\d ', "\n" => '\\a ', "\f" => '\\c ']) . '"';
    }

    /** Locate a balanced CSS function without interpreting strings/comments. */
    private function import_css_closing_parenthesis(string $value, int $opening): ?int {
        $depth = 0;
        $length = strlen($value);
        for ($position = $opening; $position < $length; $position++) {
            $character = $value[$position];
            if ($character === '\\') { $position++; continue; }
            if ($character === '"' || $character === "'") {
                $quote = $character;
                while (++$position < $length) {
                    if ($value[$position] === '\\') { $position++; continue; }
                    if ($value[$position] === $quote) break;
                }
                continue;
            }
            if ($character === '/' && ($value[$position + 1] ?? '') === '*') {
                $end = strpos($value, '*/', $position + 2);
                if ($end === false) return null;
                $position = $end + 1;
                continue;
            }
            if ($character === '(') $depth++;
            if ($character === ')' && --$depth === 0) return $position;
        }
        return null;
    }

    /** Make imports in inline ES modules resolve against the source document. */
    private function import_rewrite_inline_module_urls(string $javascript, string $base_url): string {
        return (string) preg_replace_callback(
            '~\b(from\s*|import\s*(?:\(\s*)?)(["\'])(\.{0,2}/[^"\']+)\2~',
            function (array $match) use ($base_url): string {
                return $match[1] . $match[2] . $this->import_absolutize_url($match[3], $base_url) . $match[2];
            },
            $javascript
        );
    }

    private function import_is_stylesheet_link(DOMElement $node): bool {
        $rels = preg_split('~\s+~', strtolower(trim($node->getAttribute('rel')))) ?: [];
        if (in_array('stylesheet', $rels, true)) return true;
        // Async CSS pattern: <link rel="preload" as="style" onload="this.rel='stylesheet'">.
        if (in_array('preload', $rels, true) && strtolower($node->getAttribute('as')) === 'style') return true;
        return false;
    }

    /** Fetch, expand @imports and rewrite one stylesheet within a shared budget. */
    private function import_fetch_stylesheet(string $css_url, array &$budget, int $depth = 0, bool $allow_local_files = false): ?string {
        // Elementor pages commonly split core, kit, post and widget rules into
        // dozens of files. Keep the graph finite, but large enough that the
        // page-specific CSS does not stay remote after Elementor is disabled.
        $css_url = (string) preg_replace('~#.*$~', '', $css_url);
        // Browsers ignore cyclic CSS imports. Keeping an active graph also
        // prevents repeatedly downloading self-imports, while raw response
        // caching preserves the cascade when a file is imported in two layers.
        if (isset($budget['active'][$css_url])) return '';
        if ($depth > 8 || ($budget['expansions'] ?? 0) >= 160) return null;
        $budget['expansions'] = ($budget['expansions'] ?? 0) + 1;
        if (array_key_exists($css_url, $budget['responses'] ?? [])) {
            $css = $budget['responses'][$css_url];
            if ($css === null) return null;
            $budget['active'][$css_url] = true;
            try { return $this->import_expand_css($css, $css_url, $budget, $depth, $allow_local_files); }
            finally { unset($budget['active'][$css_url]); }
        }
        if ($budget['count'] >= 80 || $budget['bytes'] >= 24 * MB_IN_BYTES) return null;
        $budget['count']++;
        $budget['responses'][$css_url] = null;
        $limit = min(4 * MB_IN_BYTES, 24 * MB_IN_BYTES - $budget['bytes']);
        if ($limit <= 0) return null;
        $local = $allow_local_files
            ? $this->import_read_local_wordpress_resource($css_url, $limit, ['css'])
            : null;
        if (is_array($local)) {
            $css = $local['body'];
        } else {
            if (!wp_http_validate_url($css_url)) return null;
            $response = $this->import_safe_remote_get($css_url, [
                'timeout' => 15,
                'redirection' => 3,
                'reject_unsafe_urls' => true,
                // Read one sentinel byte so a truncated response is never
                // accepted as a complete stylesheet at the exact size limit.
                'limit_response_size' => $limit + 1,
                'user-agent' => 'KodetyImporter/1.0 (+WordPress)',
                'headers' => ['Accept' => 'text/css,*/*;q=0.1'],
            ]);
            if (is_wp_error($response)) return null;
            $status = (int) wp_remote_retrieve_response_code($response);
            if ($status < 200 || $status >= 300) return null;
            $content_type = strtolower(trim(explode(';', (string) wp_remote_retrieve_header($response, 'content-type'))[0]));
            if (!in_array($content_type, ['', 'text/css', 'text/plain', 'application/x-css', 'application/octet-stream', 'binary/octet-stream'], true)) return null;
            $css = (string) wp_remote_retrieve_body($response);
            if ($css === '' || strlen($css) > $limit) return null;
        }
        if (preg_match('~^(?:\xEF\xBB\xBF)?\s*<(?:!doctype|html\b|head\b|body\b|script\b)~i', $css)) return null;
        $budget['bytes'] += strlen($css);
        $budget['responses'][$css_url] = $css;
        $budget['active'][$css_url] = true;
        try { return $this->import_expand_css($css, $css_url, $budget, $depth, $allow_local_files); }
        finally { unset($budget['active'][$css_url]); }
    }

    /**
     * Inline nested @import stylesheets (so split CSS survives) then rewrite all
     * remaining references to absolute URLs. Cascade layers, supports() and
     * media conditions must retain their separate grammar and nesting.
     */
    private function import_expand_css(string $css, string $css_url, array &$budget, int $depth = 0, bool $allow_local_files = false): string {
        // Drop only real encoding declarations, never their appearance in text
        // or comments. Inlined CSS belongs to the UTF-8 HTML document.
        $css = preg_replace('~^(?:\xEF\xBB\xBF)?@charset\s+"[^"]*"\s*;~i', '', $css) ?? $css;
        $original_css = $css;
        $preserve_boundaries = preg_match('~@namespace\b~i', $css) === 1;
        $expanded_bytes = strlen($css);
        $css = $this->import_map_css_imports($css, function (string $url, string $conditions, string $original) use ($css_url, &$budget, $depth, $allow_local_files, &$expanded_bytes, &$preserve_boundaries): string {
            $import_url = $this->import_absolutize_url($url, $css_url);
            $fallback = '@import url(' . $this->import_quote_css_string($import_url) . ')' . ($conditions !== '' ? ' ' . $conditions : '') . ';';
            $wrappers = $this->import_css_import_wrappers($conditions);
            if ($wrappers === null) { $preserve_boundaries = true; return $fallback; }
            $nested = $this->import_fetch_stylesheet($import_url, $budget, $depth + 1, $allow_local_files);
            if ($nested === null || $expanded_bytes + strlen($nested) > 24 * MB_IN_BYTES) { $preserve_boundaries = true; return $fallback; }
            if (preg_match('~@(?:import|namespace)\b~i', $nested)) $preserve_boundaries = true;
            $expanded_bytes += strlen($nested);
            // Import conditions govern the layer's order slot too; the layer
            // must be inside supports/media rather than reserving its order
            // unconditionally when the imported rules do not apply.
            foreach ($wrappers as $wrapper) $nested = $wrapper . " {\n" . $nested . "\n}";
            return "\n" . $nested . "\n";
        });
        // Inserting rules ahead of a failed sibling @import would invalidate
        // that sibling. Namespace scopes also belong to separate stylesheets.
        // Preserve the original graph in these cases so fallback stays valid.
        if ($preserve_boundaries) return $this->import_rewrite_css_urls($original_css, $css_url);
        return $this->import_map_css_urls($css, fn(string $url): string => $this->import_absolutize_url($url, $css_url));
    }

    /** Visit complete @import rules, skipping comments and ordinary strings. */
    private function import_map_css_imports(string $css, callable $map): string {
        $pattern = <<<'REGEX'
~ /\*[\s\S]*?\*/ (*SKIP)(*F)
| "(?:[^"\\]++|\\[\s\S])*+" (*SKIP)(*F)
| '(?:[^'\\]++|\\[\s\S])*+' (*SKIP)(*F)
| @import\s+(?:url\(\s*(?:"(?<double>(?:[^"\\]++|\\[\s\S])*+)"|'(?<single>(?:[^'\\]++|\\[\s\S])*+)'|(?<bare>(?:\\(?:[0-9a-f]{1,6}\s?|[^\r\n\f])|[^\\\s()'"])+))\s*\)|"(?<string_double>(?:[^"\\]++|\\[\s\S])*+)"|'(?<string_single>(?:[^'\\]++|\\[\s\S])*+)')(?<conditions>(?:/\*[\s\S]*?\*/|"(?:[^"\\]++|\\[\s\S])*+"|'(?:[^'\\]++|\\[\s\S])*+'|[^;"'/]++|/(?!\*))*+)\s*;
~ix
REGEX;
        $position = 0;
        $imports_allowed = true;
        return preg_replace_callback($pattern, function (array $match) use ($map, $css, &$position, &$imports_allowed): string {
            $prefix = substr($css, $position, $match[0][1] - $position);
            $position = $match[0][1] + strlen($match[0][0]);
            $prefix = preg_replace('~/\*[\s\S]*?\*/~', '', $prefix) ?? $prefix;
            $prefix = preg_replace('~@charset\s+"[^"]*"\s*;|@layer\s+[^;{}]+;~i', '', $prefix) ?? $prefix;
            if (trim($prefix) !== '') $imports_allowed = false;
            // Invalid late/nested imports were ignored by the origin browser;
            // making them active would change the authored cascade.
            if (!$imports_allowed) return $match[0][0];
            $raw = $match['double'][0] ?? $match['single'][0] ?? $match['bare'][0] ?? $match['string_double'][0] ?? $match['string_single'][0] ?? '';
            return $map($this->import_decode_css_string($raw), trim($match['conditions'][0] ?? ''), $match[0][0]);
        }, $css, -1, $unused, PREG_UNMATCHED_AS_NULL | PREG_OFFSET_CAPTURE) ?? $css;
    }

    /** @return list<string>|null Wrappers in cascade layer/supports/media order. */
    private function import_css_import_wrappers(string $conditions): ?array {
        $remaining = trim(preg_replace('~/\*[\s\S]*?\*/~', ' ', $conditions) ?? $conditions);
        $wrappers = [];
        if (preg_match('~^layer\b~i', $remaining, $match)) {
            $remaining = ltrim(substr($remaining, strlen($match[0])));
            $layer = '';
            if (str_starts_with($remaining, '(')) {
                $end = $this->import_css_closing_parenthesis($remaining, 0);
                if ($end === null) return null;
                $layer = trim(substr($remaining, 1, $end - 1));
                $remaining = ltrim(substr($remaining, $end + 1));
            }
            $wrappers[] = '@layer' . ($layer !== '' ? ' ' . $layer : '');
        }
        if (preg_match('~^supports\(~i', $remaining, $match)) {
            $start = strlen($match[0]) - 1;
            $end = $this->import_css_closing_parenthesis($remaining, $start);
            if ($end === null) return null;
            $supports = trim(substr($remaining, $start + 1, $end - $start - 1));
            if ($supports === '') return null;
            // A declaration is bare in supports(display:grid), but @supports
            // needs parentheses; compound conditions and selector() already
            // have their own grammar and must not be rewritten as declarations.
            if (preg_match('~^(?:--[\w-]+|[a-z][\w-]*)\s*:~i', $supports)) $supports = '(' . $supports . ')';
            $wrappers[] = '@supports ' . $supports;
            $remaining = ltrim(substr($remaining, $end + 1));
        }
        if ($remaining !== '' && strtolower($remaining) !== 'all') $wrappers[] = '@media ' . $remaining;
        return $wrappers;
    }

    /** Rewrite url(...) and remaining @import references inside CSS to absolute URLs. */
    private function import_rewrite_css_urls(string $css, string $css_url): string {
        $css = $this->import_map_css_imports($css, function (string $url, string $conditions) use ($css_url): string {
            return '@import url(' . $this->import_quote_css_string($this->import_absolutize_url($url, $css_url)) . ')' . ($conditions !== '' ? ' ' . $conditions : '') . ';';
        });
        return $this->import_map_css_urls($css, fn(string $url): string => $this->import_absolutize_url($url, $css_url));
    }

    private function import_absolutize_srcset(string $srcset, string $base): string {
        return $this->import_map_srcset($srcset, fn(string $url): string => $this->import_absolutize_url($url, $base));
    }

    /** Resolve a possibly-relative URL against a base, RFC-3986 style. */
    private function import_absolutize_url(string $maybe, string $base): string {
        $maybe = trim($maybe);
        if ($maybe === '') return $maybe;
        // Preserve every explicit scheme, including blob:, about: and urn:.
        // Fragment-only references intentionally stay local for SVG/use and
        // anchor targets in the imported document.
        if (preg_match('~^(?:[a-z][a-z0-9+.-]*:|#)~i', $maybe)) {
            return preg_match('~^https?:~i', $maybe) ? str_replace(' ', '%20', $maybe) : $maybe;
        }
        $maybe = str_replace(' ', '%20', $maybe);
        if (str_starts_with($maybe, '//')) {
            $scheme = strtolower((string) wp_parse_url($base, PHP_URL_SCHEME)) ?: 'https';
            return $scheme . ':' . $maybe;
        }
        $parts = wp_parse_url($base);
        if (!$parts || empty($parts['scheme']) || empty($parts['host'])) return $maybe;
        $authority = $parts['scheme'] . '://' . $parts['host'] . (isset($parts['port']) ? ':' . $parts['port'] : '');

        $fragment = '';
        $query = '';
        if (($hash = strpos($maybe, '#')) !== false) { $fragment = substr($maybe, $hash); $maybe = substr($maybe, 0, $hash); }
        if (($mark = strpos($maybe, '?')) !== false) { $query = substr($maybe, $mark); $maybe = substr($maybe, 0, $mark); }

        if ($maybe === '') {
            // ?format=webp replaces the query of the current resource, not
            // its directory. This is common in responsive image/font CDNs.
            $path = (string) ($parts['path'] ?? '/');
        } elseif (str_starts_with($maybe, '/')) {
            $path = $maybe;
        } else {
            $base_path = isset($parts['path']) && $parts['path'] !== '' ? $parts['path'] : '/';
            $base_dir = (string) preg_replace('~/[^/]*$~', '/', $base_path);
            if ($base_dir === '') $base_dir = '/';
            $path = $base_dir . $maybe;
        }
        return $authority . $this->import_normalize_path($path) . $query . $fragment;
    }

    /** Collapse ./ and ../ segments in a URL path. */
    private function import_normalize_path(string $path): string {
        // RFC 3986 remove_dot_segments. Empty segments are significant on CDNs
        // and object stores, so preserve // and the slash implied by /. or /...
        $output = '';
        while ($path !== '') {
            if (str_starts_with($path, '../')) { $path = substr($path, 3); continue; }
            if (str_starts_with($path, './')) { $path = substr($path, 2); continue; }
            if (str_starts_with($path, '/./')) { $path = substr($path, 2); continue; }
            if ($path === '/.') { $path = '/'; continue; }
            if (str_starts_with($path, '/../') || $path === '/..') {
                $path = $path === '/..' ? '/' : substr($path, 3);
                $slash = strrpos($output, '/');
                $output = $slash === false ? '' : substr($output, 0, $slash);
                continue;
            }
            if ($path === '.' || $path === '..') break;
            $end = strpos($path, '/', $path[0] === '/' ? 1 : 0);
            if ($end === false) { $output .= $path; break; }
            $output .= substr($path, 0, $end);
            $path = substr($path, $end);
        }
        return $output === '' ? '/' : $output;
    }

    private static function default_optimization_settings(): array {
        return Kodety_Publication_Optimizer::defaults();
    }

    private function sanitize_optimization_settings(array $settings): array {
        // Legacy requests stay lossless; only the explicit v2 contract opts in.
        return ($settings['version'] ?? null) === Kodety_Publication_Optimizer::VERSION
            ? Kodety_Publication_Optimizer::normalize($settings)
            : Kodety_Publication_Optimizer::from_saved($settings);
    }

    private function optimization_settings(): array {
        return Kodety_Publication_Optimizer::from_preferences(get_option('kodety_optimization_settings', []));
    }

    private function optimization_report(): array {
        $report = get_option('kodety_optimization_report', []);
        return is_array($report) && ($report['release'] ?? '') === (string) get_option('kodety_current_release', '') ? $report : [];
    }

    public function optimization_status(): WP_REST_Response {
        $settings = $this->optimization_settings();
        $response = new WP_REST_Response([
            'engineVersion' => Kodety_Publication_Optimizer::VERSION,
            'settings' => $settings,
            'revision' => Kodety_Publication_Optimizer::revision($settings),
            'options' => Kodety_Publication_Optimizer::options(),
            'report' => $this->optimization_report(),
            'canSave' => $this->can_publish(),
            'release' => (string) get_option('kodety_current_release', ''),
            'publishedAt' => (string) get_option('kodety_last_published_at', ''),
        ]);
        $response->header('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0');
        return $response;
    }

    /** Shared, locked write path for wp-admin and the Publish menu. */
    private function persist_optimizations(array $payload): array|WP_Error {
        try {
            $settings = Kodety_Publication_Optimizer::normalize(is_array($payload['settings'] ?? null) ? $payload['settings'] : $payload);
        } catch (InvalidArgumentException $error) {
            return new WP_Error('kodety_optimization_invalid', $error->getMessage(), ['status' => 400]);
        }
        if (($payload['applyPublished'] ?? false) === true) $this->prepare_project_archive_request();
        return $this->with_workspace_lock(function () use ($payload, $settings): array|WP_Error {
            $current = $this->optimization_settings();
            $expected = $payload['expectedRevision'] ?? '';
            $applied = ($payload['applyPublished'] ?? false) === true;
            $source_release = is_string($payload['expectedRelease'] ?? null) ? $payload['expectedRelease'] : '';
            $reapply_key = hash('sha256', $source_release . ':' . Kodety_Publication_Optimizer::revision($settings));
            $report = $this->optimization_report();
            // The receipt is committed with the release. A lost HTTP response
            // can be retried without activating the same preferences twice.
            $replayed = $applied && $source_release !== '' && $current === $settings
                && ($report['reapplyKey'] ?? '') === $reapply_key;
            if (!$replayed && (!is_string($expected) || !hash_equals(Kodety_Publication_Optimizer::revision($current), $expected))) {
                return new WP_Error('kodety_optimization_conflict', 'As otimizações mudaram em outra janela. Recarregue as opções antes de salvar.', ['status' => 409]);
            }
            $release = (string) get_option('kodety_current_release', '');
            if ($applied && !$replayed) {
                if ($release === '' || ($payload['expectedRelease'] ?? null) !== $release) {
                    return new WP_Error('kodety_optimization_release_conflict', 'A publicação mudou. Recarregue as opções antes de aplicar ao site.', ['status' => 409]);
                }
                $workspace_id = (string) get_option('kodety_workspace_project_id', '');
                $published_id = (string) get_option('kodety_published_project_id', '');
                if ($workspace_id !== $published_id || !is_dir($this->workspace_dir())) {
                    return new WP_Error('kodety_optimization_project_conflict', 'Abra o projeto publicado antes de reaplicar suas otimizações.', ['status' => 409]);
                }
                $source = $this->snapshot_project_directory($release);
                if ($source === '') return new WP_Error('kodety_optimization_source_missing', 'A fonte desta publicação não está disponível. Publique pelo Builder para aplicar as otimizações.', ['status' => 409]);
                $transport = null;
                try {
                    $this->optimization_reapply_context = ['reappliedFrom'=>$source_release,'reapplyKey'=>$reapply_key];
                    $transport = $this->package_directory_as_zip($source, 'kodety-optimize-');
                    $release = $this->install_zip_locked($transport, (string) get_option('kodety_original_name', 'kodety-project.zip'), $settings, null, true);
                    update_option('kodety_last_published_at', current_time('c'), false);
                } finally {
                    $this->optimization_reapply_context = [];
                    if (is_string($transport) && is_file($transport)) @unlink($transport);
                }
            } elseif (!$replayed) {
                update_option('kodety_optimization_settings', $settings, false);
                if ($this->optimization_settings() !== $settings) throw new RuntimeException('As preferências não puderam ser confirmadas. Tente novamente.');
            }
            return [
                'success' => true, 'settings' => $settings,
                'revision' => Kodety_Publication_Optimizer::revision($settings),
                'appliedToPublished' => $applied, 'release' => $release,
                'replayed' => $replayed,
                'report' => $this->optimization_report(),
                'publishedAt' => (string) get_option('kodety_last_published_at', ''),
                'syncPending' => $applied && !empty($this->last_publish_sync_report['syncPending']),
                'warnings' => $applied ? ($this->last_publish_sync_report['warnings'] ?? []) : [],
            ];
        });
    }

    public function save_optimizations_rest(WP_REST_Request $request): WP_REST_Response|WP_Error {
        try {
            $payload = $request->get_json_params();
            $result = $this->persist_optimizations(is_array($payload) ? $payload : []);
            if (is_wp_error($result)) return $result;
            $response = new WP_REST_Response($result, !empty($result['syncPending']) ? 202 : 200);
            $response->header('Cache-Control', 'no-store');
            return $response;
        } catch (Throwable $error) {
            return new WP_Error('kodety_optimization_save_failed', $error->getMessage(), ['status' => 500]);
        }
    }

    public function update_theme_screenshot(WP_REST_Request $request): WP_REST_Response|WP_Error {
        if (is_multisite()) {
            return new WP_Error('kodety_multisite_unsupported', 'A escrita no tema está desativada em WordPress Multisite.', ['status' => 409]);
        }
        $image = $request->get_body();
        if ($image === '' || strlen($image) > 12 * MB_IN_BYTES) {
            return new WP_Error('kodety_invalid_screenshot', 'A captura do tema está vazia ou acima do limite.', ['status' => 400]);
        }
        $details = @getimagesizefromstring($image);
        if (!$details || ($details[2] ?? 0) !== IMAGETYPE_PNG) {
            return new WP_Error('kodety_invalid_screenshot', 'A captura do tema precisa ser uma imagem PNG válida.', ['status' => 400]);
        }
        $width = (int) ($details[0] ?? 0);
        $height = (int) ($details[1] ?? 0);
        if ($width < 600 || $height < 400 || $width > 2400 || $height > 1800) {
            return new WP_Error('kodety_invalid_screenshot_size', 'A captura do tema possui dimensões inválidas.', ['status' => 400]);
        }
        $theme_dir = trailingslashit(get_theme_root()) . 'kodety-generated';
        if (!is_dir($theme_dir)) {
            return new WP_Error('kodety_theme_missing', 'O tema Onun Kodety ainda não foi publicado.', ['status' => 404]);
        }
        $screenshot = $theme_dir . '/screenshot.png';
        $temporary = $theme_dir . '/.kodety-screenshot-' . wp_generate_password(8, false, false) . '.png';
        if (file_put_contents($temporary, $image, LOCK_EX) === false) {
            return new WP_Error('kodety_screenshot_write_failed', 'Não foi possível salvar a captura do tema.', ['status' => 500]);
        }
        if (!rename($temporary, $screenshot)) {
            @unlink($temporary);
            return new WP_Error('kodety_screenshot_write_failed', 'Não foi possível ativar a nova captura do tema.', ['status' => 500]);
        }
        return new WP_REST_Response(['success' => true, 'url' => get_theme_root_uri() . '/kodety-generated/screenshot.png']);
    }

    public function list_releases(): WP_REST_Response|WP_Error {
        try {
            $items = $this->with_workspace_lock(function (): array {
                $directories = glob($this->releases_dir() . '/*', GLOB_ONLYDIR) ?: [];
                $items = array_map(fn(string $path): array => ['id' => basename($path), 'modified' => gmdate('c', (int) filemtime($path))], $directories);
                usort($items, fn(array $a, array $b): int => strcmp($b['id'], $a['id']));
                return $items;
            });
            return new WP_REST_Response($items);
        } catch (Throwable $error) {
            return new WP_Error('kodety_release_list_failed', $error->getMessage(), ['status' => 500]);
        }
    }

    private function release_id(mixed $value): string {
        $release = trim((string) $value);
        return preg_match('/^[A-Za-z0-9_-]{1,96}$/', $release) ? $release : '';
    }

    private function snapshot_project_directory(string $release): string {
        if ($release === '' || $this->release_id($release) !== $release) return '';
        $directory = $this->releases_dir() . '/' . $release;
        $project = $directory . '/project';
        if (is_link($directory) || is_link($project) || !is_dir($project)) return '';
        return $project;
    }

    /** Build a private, disposable download while publication/deletion is locked. */
    private function prepare_snapshot_download_archive(string $release): string|WP_Error {
        try {
            return $this->with_workspace_lock(function () use ($release): string|WP_Error {
                $project = $this->snapshot_project_directory($release);
                if ($project === '') {
                    return new WP_Error('kodety_snapshot_missing', 'Este snapshot não está mais disponível. Atualize a lista e tente novamente.', ['status' => 404]);
                }
                // Keep the saved template, if any. Injecting today's CMS or
                // membership settings would silently change a historical ZIP.
                return $this->package_editable_workspace_as_zip($project, 'kodety-snapshot-', null, false);
            });
        } catch (Throwable $error) {
            return new WP_Error('kodety_snapshot_download_failed', $error->getMessage(), ['status' => 500]);
        }
    }

    /** Resolve only a short-lived handle issued by the authenticated snapshot API. */
    private function snapshot_preview_directory(string $token): string {
        if (!preg_match('/^[a-f0-9]{48}$/D', $token)) return '';
        $release = get_transient('kodety_snapshot_preview_' . $token);
        if (!is_string($release)) return '';
        $project = $this->snapshot_project_directory($release);
        return $project !== '' ? $this->collapse_single_root($project) : '';
    }

    public function snapshot_preview(WP_REST_Request $request): WP_REST_Response|WP_Error {
        try {
            $release = $this->release_id($request['release']);
            $result = $this->with_workspace_read_lock(function () use ($release): array|WP_Error {
                $project = $this->snapshot_project_directory($release);
                if ($project === '') return new WP_Error('kodety_snapshot_missing', 'Este snapshot não está mais disponível.', ['status' => 404]);
                $root = $this->collapse_single_root($project);
                $pages = [];
                foreach ($this->find_html_files($root) as $file) {
                    $relative = ltrim(str_replace('\\', '/', substr($file, strlen($root))), '/');
                    if ($relative === '' || preg_match('~(?:^|/)\.~', $relative)) continue;
                    $pages[] = $relative;
                }
                if (!$pages) return new WP_Error('kodety_snapshot_empty', 'Este snapshot não contém páginas para visualizar.', ['status' => 422]);
                $token = bin2hex(random_bytes(24));
                $ttl = 15 * MINUTE_IN_SECONDS;
                if (!set_transient('kodety_snapshot_preview_' . $token, $release, $ttl)) {
                    throw new RuntimeException('Não foi possível preparar a prévia do snapshot.');
                }
                $base = trailingslashit(home_url('/kodety/preview/' . $token));
                $main = $this->directory_main_html_path($root);
                $home = in_array($main, $pages, true) ? $main : $pages[0];
                return [
                    'release' => $release,
                    'url' => $base . implode('/', array_map('rawurlencode', explode('/', $home))),
                    'expiresAt' => gmdate('c', time() + $ttl),
                    'pages' => array_map(static fn(string $path): array => [
                        'path' => $path,
                        'url' => $base . implode('/', array_map('rawurlencode', explode('/', $path))),
                    ], $pages),
                ];
            });
            if (is_wp_error($result)) return $result;
            $response = new WP_REST_Response($result);
            $response->header('Cache-Control', 'private, no-store');
            return $response;
        } catch (Throwable $error) {
            return new WP_Error('kodety_snapshot_preview_failed', $error->getMessage(), ['status' => 500]);
        }
    }

    /** @return array{count:int,currentRelease:string,currentStored:bool,items:list<array{id:string,modified:string,current:bool,downloadUrl:string,previewUrl:string,restoreUrl:string}>} */
    private function release_snapshot_inventory(): array {
        $current = $this->release_id(get_option('kodety_current_release', ''));
        $directories = glob($this->releases_dir() . '/*', GLOB_ONLYDIR) ?: [];
        $items = [];
        foreach ($directories as $directory) {
            $id = $this->release_id(basename($directory));
            if ($id === '' || !hash_equals(basename($directory), $id) || is_link($directory)) continue;
            $items[] = [
                'id' => $id,
                'modified' => gmdate('c', (int) @filemtime($directory)),
                'current' => $current !== '' && hash_equals($current, $id),
                'downloadUrl' => current_user_can('manage_options') && $this->snapshot_project_directory($id) !== ''
                    ? add_query_arg([
                        'action' => 'kodety_download_snapshot',
                        'release' => $id,
                        '_wpnonce' => wp_create_nonce('kodety_download_snapshot_' . $id),
                    ], admin_url('admin-post.php'))
                    : '',
                'previewUrl' => current_user_can('manage_options') && $this->snapshot_project_directory($id) !== ''
                    ? rest_url('kodety/v1/releases/' . rawurlencode($id) . '/preview')
                    : '',
                'restoreUrl' => current_user_can('manage_options') && $this->can_publish() && $this->snapshot_project_directory($id) !== ''
                    ? rest_url('kodety/v1/rollback/' . rawurlencode($id))
                    : '',
            ];
        }
        usort($items, static fn(array $left, array $right): int => strcmp($right['id'], $left['id']));
        return [
            'count' => count($items),
            'currentRelease' => $current,
            'currentStored' => $current !== '' && is_dir($this->releases_dir() . '/' . $current),
            'items' => $items,
        ];
    }

    /** @return array{id:string,name:string,mode:string,isRoot:bool,hasWorkspace:bool,release:string} */
    private function storage_project_status(): array {
        $mode = $this->workspace_mode();
        $active_id = $mode === 'agency' ? $this->agency_active_project_id() : '';
        $projects = $mode === 'agency' ? $this->agency_projects() : [];
        $project = $active_id !== '' && isset($projects[$active_id]) ? $projects[$active_id] : [];
        $workspace_project_id = sanitize_key((string) get_option('kodety_workspace_project_id', ''));
        $id = $active_id !== '' ? $active_id : ($workspace_project_id !== '' ? $workspace_project_id : 'single');
        $name = trim((string) ($project['name'] ?? get_option('kodety_project_name', '')));
        if ($name === '') $name = 'Projeto atual';
        return [
            'id' => $id,
            'name' => $name,
            'mode' => $mode,
            'isRoot' => $mode !== 'agency' || !empty($project['isRoot']),
            'hasWorkspace' => is_dir($this->workspace_dir()),
            'release' => $this->release_id($project['release'] ?? get_option('kodety_current_release', '')),
        ];
    }

    public function storage_status(): WP_REST_Response|WP_Error {
        try {
            $result = $this->with_workspace_read_lock(fn(): array => [
                'snapshots' => $this->release_snapshot_inventory(),
                'project' => $this->storage_project_status(),
                'workspaceRevision' => (int) get_option('kodety_workspace_revision', 0),
            ]);
            $response = new WP_REST_Response($result);
            $response->header('Cache-Control', 'private, no-store');
            return $response;
        } catch (Throwable $error) {
            return new WP_Error('kodety_storage_read_failed', $error->getMessage(), ['status' => 503]);
        }
    }

    /** Remove every release snapshot in one locked transaction. The generated
     * theme is deliberately independent: deleting the current restore point
     * never takes the already-published site offline. */
    private function delete_release_snapshots(bool $include_current): array {
        $current = $this->release_id(get_option('kodety_current_release', ''));
        $deleted = [];
        $preserved = [];
        foreach (glob($this->releases_dir() . '/*', GLOB_ONLYDIR) ?: [] as $directory) {
            $id = $this->release_id(basename($directory));
            if ($id === '' || !hash_equals(basename($directory), $id)) continue;
            if (!$include_current && $current !== '' && hash_equals($current, $id)) {
                $preserved[] = $id;
                continue;
            }
            $this->remove_tree($directory);
            if (is_dir($directory)) {
                throw new RuntimeException('O snapshot ' . $id . ' não pôde ser removido por completo.');
            }
            $deleted[] = $id;
        }
        return [
            'deleted' => $deleted,
            'deletedCount' => count($deleted),
            'preserved' => $preserved,
            'includeCurrent' => $include_current,
            'snapshots' => $this->release_snapshot_inventory(),
        ];
    }

    /** Delete one agency project regardless of whether it owns the domain root.
     * A published replacement is preferred for the root, keeping public routing
     * stable. The shared generated theme itself is never removed here. */
    private function delete_agency_project(string $project_id): array {
        $project_id = sanitize_key($project_id);
        $projects = $this->agency_projects();
        if ($project_id === '' || !isset($projects[$project_id])) {
            throw new RuntimeException('Projeto não encontrado.');
        }
        $deleted = $projects[$project_id];
        $deleted_root = !empty($deleted['isRoot']);
        $active = $this->agency_active_project_id();
        $remaining = $projects;
        unset($remaining[$project_id]);
        $replacement_id = '';
        if ($active === $project_id && $remaining) {
            foreach ($remaining as $candidate_id => $candidate) {
                if ((string) ($candidate['release'] ?? '') !== '') {
                    $replacement_id = (string) $candidate_id;
                    break;
                }
            }
            if ($replacement_id === '') $replacement_id = (string) array_key_first($remaining);
            $this->agency_restore_project($replacement_id);
            $replacement = $remaining[$replacement_id];
            update_option('kodety_current_release', (string) ($replacement['release'] ?? ''), false);
            update_option('kodety_last_published_at', (string) ($replacement['publishedAt'] ?? ''), false);
            if (is_dir($this->releases_dir())) $this->remove_tree($this->releases_dir());
        } elseif ($active === $project_id) {
            if (is_dir($this->workspace_dir())) $this->remove_tree($this->workspace_dir());
            if (is_file($this->current_zip())) @unlink($this->current_zip());
            if (is_dir($this->releases_dir())) $this->remove_tree($this->releases_dir());
            update_option('kodety_agency_active_project', '', false);
            update_option('kodety_project_name', '', false);
            update_option('kodety_original_name', '', false);
            update_option('kodety_current_release', '', false);
            update_option('kodety_last_published_at', '', false);
            update_option('kodety_workspace_css_digest', '', false);
            update_option('kodety_workspace_revision', (int) get_option('kodety_workspace_revision', 0) + 1, false);
        }

        $directory = $this->agency_project_dir($project_id);
        if (is_dir($directory)) $this->remove_tree($directory);
        if (is_dir($directory)) throw new RuntimeException('O diretório privado do projeto não pôde ser removido.');

        $projects = $this->agency_projects();
        unset($projects[$project_id]);
        if ($deleted_root && $projects) {
            $root_id = $replacement_id;
            if ($root_id === '' || !isset($projects[$root_id])) {
                foreach ($projects as $candidate_id => $candidate) {
                    if ((string) ($candidate['release'] ?? '') !== '') {
                        $root_id = (string) $candidate_id;
                        break;
                    }
                }
            }
            if ($root_id === '' || !isset($projects[$root_id])) $root_id = (string) array_key_first($projects);
            foreach ($projects as &$candidate) $candidate['isRoot'] = false;
            unset($candidate);
            if ($root_id !== '' && isset($projects[$root_id])) $projects[$root_id]['isRoot'] = true;
        }
        update_option('kodety_agency_projects', $projects, false);
        return [
            'deletedProjectId' => $project_id,
            'deletedRoot' => $deleted_root,
            'replacementProjectId' => $replacement_id,
        ];
    }

    private function delete_single_project(): array {
        $workspace = $this->workspace_dir();
        if (is_dir($workspace)) $this->remove_tree($workspace);
        if (is_file($this->current_zip())) @unlink($this->current_zip());
        if (is_dir($this->releases_dir())) $this->remove_tree($this->releases_dir());
        if (is_dir($workspace)) throw new RuntimeException('O workspace do projeto não pôde ser removido.');
        update_option('kodety_project_name', '', false);
        update_option('kodety_original_name', '', false);
        update_option('kodety_workspace_project_id', '', false);
        update_option('kodety_current_release', '', false);
        update_option('kodety_last_published_at', '', false);
        update_option('kodety_workspace_css_digest', '', false);
        update_option('kodety_workspace_revision', (int) get_option('kodety_workspace_revision', 0) + 1, false);
        update_option('kodety_onboarding_status', 'pending', false);
        return ['deletedProjectId' => 'single', 'deletedRoot' => true, 'replacementProjectId' => ''];
    }

    public function delete_storage(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $payload = $request->get_json_params();
        $payload = is_array($payload) ? $payload : [];
        $operation = sanitize_key((string) ($payload['operation'] ?? ''));
        try {
            if ($operation === 'delete_snapshots') {
                $result = $this->with_workspace_lock(
                    fn(): array => $this->delete_release_snapshots(rest_sanitize_boolean($payload['includeCurrent'] ?? false))
                );
                return new WP_REST_Response(['success' => true] + $result);
            }
            if ($operation !== 'delete_project') {
                return new WP_Error('kodety_storage_operation_invalid', 'Ação de armazenamento inválida.', ['status' => 400]);
            }
            $project = $this->storage_project_status();
            $confirmation = sanitize_text_field((string) ($payload['confirmation'] ?? ''));
            if ($confirmation === '' || !hash_equals($project['name'], $confirmation)) {
                return new WP_Error('kodety_project_confirmation_invalid', 'Digite o nome exato do projeto para confirmar a exclusão.', ['status' => 400]);
            }
            $result = $this->with_workspace_lock(function () use ($project): array {
                return $project['mode'] === 'agency' && $project['id'] !== 'single'
                    ? $this->delete_agency_project($project['id'])
                    : $this->delete_single_project();
            });
            return new WP_REST_Response([
                'success' => true,
                'project' => $result,
                'redirectUrl' => $project['mode'] === 'agency' ? admin_url() : admin_url('admin.php?page=kodety'),
            ]);
        } catch (Throwable $error) {
            return new WP_Error('kodety_storage_delete_failed', $error->getMessage(), ['status' => 500]);
        }
    }

    public function rollback(WP_REST_Request $request): WP_REST_Response|WP_Error {
        $release = $this->release_id($request['release']);
        $expected_revision = $request->get_param('expectedWorkspaceRevision');
        try {
            $result = $this->with_workspace_lock(function () use ($release, $expected_revision): array|WP_Error {
                if ($expected_revision !== null && (!is_int($expected_revision) || $expected_revision !== (int) get_option('kodety_workspace_revision', 0))) {
                    return new WP_Error('kodety_snapshot_conflict', 'O projeto mudou desde que você abriu os snapshots. Atualize a lista e confirme a restauração novamente.', ['status' => 409]);
                }
                $release_dir = $this->releases_dir() . '/' . $release;
                $project = $this->snapshot_project_directory($release);
                if ($project === '') return new WP_Error('kodety_release_missing', 'Release não encontrada.', ['status' => 404]);
                $transport = null;
                try {
                    $transport = $this->package_directory_as_zip($project, 'kodety-rollback-');
                    $optimizations = null;
                    $settings_file = $release_dir . '/optimizations.json';
                    if (is_file($settings_file)) {
                        $decoded = json_decode((string) file_get_contents($settings_file), true);
                        if (is_array($decoded)) $optimizations = $decoded;
                    }
                    $new_release = $this->install_zip($transport, 'rollback-' . $release . '.zip', $optimizations);
                    $published_at = current_time('c');
                    update_option('kodety_last_published_at', $published_at, false);
                    $sync_pending = !empty($this->last_publish_sync_report['syncPending']);
                    $warnings = array_values(array_filter(array_map(
                        'strval',
                        is_array($this->last_publish_sync_report['warnings'] ?? null)
                            ? $this->last_publish_sync_report['warnings']
                            : []
                    )));
                    return [
                        'success' => true,
                        'publicationComplete' => !$sync_pending,
                        'releaseOnline' => true,
                        'syncPending' => $sync_pending,
                        'warnings' => $warnings,
                        'release' => $new_release,
                        'rolledBackFrom' => $release,
                        'publishedAt' => $published_at,
                        'workspaceRevision' => (int) get_option('kodety_workspace_revision', 0),
                        'cssDigest' => (string) get_option('kodety_workspace_css_digest', ''),
                    ];
                } finally {
                    if (is_string($transport) && is_file($transport)) @unlink($transport);
                }
            });
            return is_wp_error($result)
                ? $result
                : new WP_REST_Response($result, !empty($result['syncPending']) ? 202 : 200);
        } catch (Throwable $error) {
            return new WP_Error('kodety_rollback_failed', $error->getMessage(), ['status' => 500]);
        }
    }

    private function install_zip(string $zip_path, string $original_name, ?array $optimizations = null, ?string $expected_css_digest = null, bool $preserve_editable_workspace = false): string {
        if (is_multisite()) {
            throw new RuntimeException('A publicação Onun Kodety está desativada em WordPress Multisite para impedir alterações em temas compartilhados pela rede.');
        }
        return $this->with_workspace_lock(
            fn(): string => $this->install_zip_locked($zip_path, $original_name, $optimizations, $expected_css_digest, $preserve_editable_workspace)
        );
    }

    private function install_zip_locked(string $zip_path, string $original_name, ?array $optimizations = null, ?string $expected_css_digest = null, bool $preserve_editable_workspace = false): string {
        $this->last_publish_sync_report = [
            'syncPending' => false,
            'warnings' => [],
        ];
        $this->ensure_directories();
        if ($this->zip_contains_component_studio($zip_path)) {
            throw new RuntimeException('Este ZIP contém um canvas temporário de componente no lugar de uma página e não pode ser instalado.');
        }
        $release = gmdate('Ymd-His') . '-' . wp_generate_password(6, false, false);
        $release_dir = $this->releases_dir() . '/' . $release;
        $project_dir = $release_dir . '/project';
        wp_mkdir_p($project_dir);
        // Once the theme swap below completes the release is live; a later
        // failure must not delete it or report the publish as a total failure.
        $activated = false;
        $staging = null;
        $workspace_staging = null;
        $previous_published_project_id = (string) get_option('kodety_published_project_id', '');
        $previous_activation = [
            'current_release' => (string) get_option('kodety_current_release', ''),
            'optimization_settings' => get_option('kodety_optimization_settings', []),
            'optimization_report' => get_option('kodety_optimization_report', []),
            'original_name' => (string) get_option('kodety_original_name', ''),
            'workspace_revision' => (int) get_option('kodety_workspace_revision', 0),
            'workspace_css_digest' => (string) get_option('kodety_workspace_css_digest', ''),
            'project_name' => (string) get_option('kodety_project_name', ''),
            'workspace_project_id' => (string) get_option('kodety_workspace_project_id', ''),
            'published_project_id' => $previous_published_project_id,
            'theme_stylesheet' => (string) wp_get_theme()->get_stylesheet(),
        ];
        try {
            $this->extract_safe_zip($zip_path, $project_dir);
            $root = $this->collapse_single_root($project_dir);
            // Seal protected authoring branches immediately. Release sources
            // live below uploads for rollback and must remain unreadable even
            // on hosts (notably Nginx) that ignore our Apache deny rules.
            $this->seal_membership_assets($root);
            // A file that used to be a normal project asset may already have a
            // public, Kodety-managed copy in uploads. Publishing the new private
            // blob while leaving that historical URL alive would only create
            // cosmetic protection, so fail before changing the active release.
            $this->assert_no_public_managed_membership_asset_copies($root);
            $this->seal_membership_artifact($root);
            $extracted_css_digest = $this->css_digest_from_directory($root);
            if ($expected_css_digest !== null && !hash_equals($expected_css_digest, $extracted_css_digest)) {
                throw new RuntimeException('O CSS extraído não corresponde ao CSS validado no upload. Nada foi publicado.');
            }
            $draft_pages = $this->project_draft_page_paths($root);
            $html_files = array_values(array_filter(
                $this->find_html_files($root),
                function (string $absolute) use ($root, $draft_pages): bool {
                    $relative = ltrim(str_replace('\\', '/', substr($absolute, strlen(rtrim($root, '/\\')))), '/');
                    return !isset($draft_pages[$relative]);
                }
            ));
            if (!$html_files) throw new RuntimeException('O ZIP não contém arquivos HTML.');
            Kodety_Edition::assert_cookie_consent_activation($html_files);
            Kodety_Edition::assert_analytics_pro_activation($html_files, $root);
            Kodety_Edition::assert_project_collection_connections(
                $html_files,
                array_column($this->collection_definitions(), 'slug')
            );
            // Every activation path, including rollback/import of an older
            // release ZIP, must cross the same localization boundary as an
            // editable draft. Otherwise malformed routes can remain dormant
            // in the workspace and only break once the theme is published.
            $this->assert_project_localization_metadata($root);
            $this->assert_coded_build_integrity($root, $html_files);
            // The source tree is enough to build and atomically activate the
            // theme. Media is registered/re-written once after activation;
            // doing it here as well doubled every hash, DB query and thumbnail.
            $theme_slug = 'kodety-generated';
            $theme_dir = trailingslashit(get_theme_root()) . $theme_slug;
            $staging = trailingslashit(get_theme_root()) . '.kodety-staging-' . $release;
            $optimizations = $this->sanitize_optimization_settings($optimizations ?? $this->optimization_settings());
            $this->build_theme($root, $staging, $html_files, $release, $optimizations, $extracted_css_digest, $draft_pages);
            file_put_contents($release_dir . '/optimizations.json', wp_json_encode($optimizations, JSON_PRETTY_PRINT), LOCK_EX);
            // A materialized Code Component build is a release artifact. Keep
            // the separately acknowledged editable workspace intact so the
            // Builder reopens authored HTML/TSX instead of generated runtime.
            $workspace = $this->workspace_dir();
            $workspace_staging = $this->private_storage_dir() . '/.workspace-' . $release;
            $workspace_backup = $this->private_storage_dir() . '/.workspace-backup';
            if ($preserve_editable_workspace) {
                if (!is_dir($workspace)) {
                    throw new RuntimeException('O workspace editável confirmado não está disponível para esta publicação.');
                }
            } else {
                if (is_dir($workspace_staging)) $this->remove_tree($workspace_staging);
                $this->copy_workspace_tree($project_dir, $workspace_staging);
                $this->write_preview_file_manifest($this->collapse_single_root($workspace_staging));
            }
            // Keep the editable workspace scrubbed and its authoring snapshot
            // encrypted at rest. It is hydrated only into a disposable system
            // temp directory when an authorized Builder session downloads it.
            $backup = trailingslashit(get_theme_root()) . '.kodety-backup';
            if (is_dir($backup)) $this->remove_tree($backup);
            if (!$preserve_editable_workspace && is_dir($workspace_backup)) $this->remove_tree($workspace_backup);
            if (is_dir($theme_dir) && !rename($theme_dir, $backup)) throw new RuntimeException('Não foi possível preparar a atualização do tema.');
            if (!$preserve_editable_workspace && is_dir($workspace) && !rename($workspace, $workspace_backup)) {
                if (is_dir($backup)) rename($backup, $theme_dir);
                throw new RuntimeException('Não foi possível preparar a atualização do workspace.');
            }
            if (!rename($staging, $theme_dir)) {
                if (is_dir($backup)) rename($backup, $theme_dir);
                if (!$preserve_editable_workspace && is_dir($workspace_backup)) rename($workspace_backup, $workspace);
                if (is_dir($workspace_staging)) $this->remove_tree($workspace_staging);
                throw new RuntimeException('Não foi possível ativar a nova versão do tema.');
            }
            if (!$preserve_editable_workspace && !rename($workspace_staging, $workspace)) {
                $this->remove_tree($theme_dir);
                if (is_dir($backup)) rename($backup, $theme_dir);
                if (is_dir($workspace_backup)) rename($workspace_backup, $workspace);
                throw new RuntimeException('A ativação foi revertida porque o workspace editável não pôde ser atualizado com segurança.');
            }
            // Keep both filesystem backups until WordPress confirms the release
            // options and active stylesheet. A silent option/theme failure is a
            // fatal activation failure, not a partial native sync.
            try {
                $next_revision = $preserve_editable_workspace
                    ? $previous_activation['workspace_revision']
                    : $previous_activation['workspace_revision'] + 1;
                $workspace_digest = $preserve_editable_workspace
                    ? $previous_activation['workspace_css_digest']
                    : $this->css_digest_from_directory($workspace);
                $project_name = $this->project_name_from_directory($workspace);
                $project_id = $this->project_id_from_directory($workspace);
                update_option('kodety_current_release', $release, false);
                update_option('kodety_optimization_settings', $optimizations, false);
                update_option('kodety_optimization_report', $this->last_optimization_report, false);
                if ($this->optimization_settings() !== $optimizations || get_option('kodety_optimization_report', []) !== $this->last_optimization_report) {
                    throw new RuntimeException('As otimizações da release não puderam ser confirmadas.');
                }
                update_option('kodety_original_name', $original_name, false);
                update_option('kodety_workspace_revision', $next_revision, false);
                update_option('kodety_workspace_css_digest', $workspace_digest, false);
                if ($project_name !== '') update_option('kodety_project_name', $project_name, false);
                if ($project_id !== '') {
                    update_option('kodety_workspace_project_id', $project_id, false);
                    update_option('kodety_published_project_id', $project_id, false);
                }
                switch_theme($theme_slug);
                $this->assert_release_activation_checkpoint(
                    $release,
                    $next_revision,
                    $workspace_digest,
                    $theme_slug
                );

                // Analytics variants are executable theme files plus matching
                // database state, so prepare them while backups remain recoverable.
                do_action('kodety_prepare_published_analytics', $release);
            } catch (Throwable $activation_error) {
                if (is_dir($theme_dir)) $this->remove_tree($theme_dir);
                if (is_dir($backup)) rename($backup, $theme_dir);
                if (!$preserve_editable_workspace && is_dir($workspace)) $this->remove_tree($workspace);
                if (!$preserve_editable_workspace && is_dir($workspace_backup)) rename($workspace_backup, $workspace);
                update_option('kodety_current_release', $previous_activation['current_release'], false);
                update_option('kodety_optimization_settings', $previous_activation['optimization_settings'], false);
                update_option('kodety_optimization_report', $previous_activation['optimization_report'], false);
                update_option('kodety_original_name', $previous_activation['original_name'], false);
                update_option('kodety_workspace_revision', $previous_activation['workspace_revision'], false);
                update_option('kodety_workspace_css_digest', $previous_activation['workspace_css_digest'], false);
                update_option('kodety_project_name', $previous_activation['project_name'], false);
                update_option('kodety_workspace_project_id', $previous_activation['workspace_project_id'], false);
                update_option('kodety_published_project_id', $previous_activation['published_project_id'], false);
                if ($previous_activation['theme_stylesheet'] !== '') {
                    switch_theme($previous_activation['theme_stylesheet']);
                }
                throw new RuntimeException(
                    'A publicação foi revertida porque a ativação não pôde ser confirmada: '
                    . $activation_error->getMessage(),
                    0,
                    $activation_error
                );
            }
            // Point of no return: theme, workspace and Analytics now form one
            // validated and ACKed release. Everything below is housekeeping.
            $activated = true;
            if (is_dir($backup)) $this->remove_tree($backup);
            if (!$preserve_editable_workspace && is_dir($workspace_backup)) $this->remove_tree($workspace_backup);
            if (is_file($this->current_zip())) @unlink($this->current_zip());
            if ($this->workspace_mode() === 'agency') {
                $active_project_id = $this->agency_active_project_id();
                if ($active_project_id !== '') {
                    try {
                        $this->agency_snapshot_current($active_project_id);
                        $this->agency_capture_published_theme($active_project_id, $theme_dir, $release);
                    } catch (Throwable $agency_publish_error) {
                        error_log(
                            '[Onun Kodety] Release ' . $release
                            . ' online, mas a cópia pública da agência falhou: '
                            . $agency_publish_error->getMessage()
                        );
                    }
                }
            }
            // The release is already live. Non-native housekeeping remains
            // best-effort. Native Media/Page reconciliation is deliberately
            // asynchronous: image decoding or thousands of native routes must
            // never hold the publish response open or consume the request that
            // owns the newly activated theme.
            try {
                $this->purge_published_site_cache();
                if (!get_option('kodety_default_pages_cleaned')) $this->trash_default_wordpress_pages();
                $project_changed = $project_id !== ''
                    && $previous_published_project_id !== ''
                    && !hash_equals($previous_published_project_id, $project_id);
                $this->prune_release_storage($release, $project_changed ? 1 : self::RELEASE_RETENTION_LIMIT);
            } catch (Throwable $side_effect_error) {
                error_log('[Onun Kodety] Release ' . $release . ' publicada, mas uma etapa de manutenção pós-publicação falhou: ' . $side_effect_error->getMessage());
            }
            $sync_scheduled = $this->schedule_publish_sync_retry($release, 1);
            $sync_warnings = array_values(array_filter(array_map(
                'strval',
                is_array($this->last_publish_sync_report['warnings'] ?? null)
                    ? $this->last_publish_sync_report['warnings']
                    : []
            )));
            if (!$sync_scheduled) {
                $sync_message = 'A release está online, mas o WordPress não conseguiu agendar a sincronização nativa em segundo plano.';
                $sync_warnings[] = $sync_message;
                $this->record_publish_sync_error($release, $sync_message);
            }
            $this->last_publish_sync_report = [
                'syncPending' => true,
                'warnings' => $sync_warnings,
            ];
            try {
                do_action('kodety_published', $release);
            } catch (Throwable $published_hook_error) {
                error_log('[Onun Kodety] Release ' . $release . ' publicada, mas o hook pós-publicação falhou: ' . $published_hook_error->getMessage());
            }
            return $release;
        } catch (Throwable $error) {
            // The public theme and its WordPress checkpoint are already ACKed.
            // A cron/filter/cache/cleanup failure from this point forward must
            // never turn a live release into HTTP 503: the Builder would retry
            // the same archive before a receipt exists and create another live
            // release. Confirm this one as online + pending and let the normal
            // admin/cron recovery path resume the remaining native work.
            if ($activated) {
                return $this->acknowledge_activated_release_failure($release, $error);
            }
            // Only discard the staged release when it never went live. An already
            // activated theme must not be deleted just because a later step threw.
            if (is_string($staging) && is_dir($staging)) $this->remove_tree($staging);
            if (is_string($workspace_staging) && is_dir($workspace_staging)) $this->remove_tree($workspace_staging);
            if (is_dir($release_dir)) $this->remove_tree($release_dir);
            throw $error;
        }
    }

    /**
     * Convert a post-activation failure into an honest partial-success ACK.
     * The release is serving traffic and cannot be rolled back safely here;
     * returning it lets publish_project persist the idempotency receipt.
     */
    private function acknowledge_activated_release_failure(string $release, Throwable $error): string {
        $warning = 'A release está online, mas uma etapa pós-publicação ficou pendente e será retomada em segundo plano.';
        $detail = $warning . ' ' . trim($error->getMessage());
        error_log('[Onun Kodety] Release ' . $release . ' online com etapa pendente: ' . $error->getMessage());
        $warnings = array_values(array_filter(array_map(
            'strval',
            is_array($this->last_publish_sync_report['warnings'] ?? null)
                ? $this->last_publish_sync_report['warnings']
                : []
        )));
        $warnings[] = $warning;
        $this->last_publish_sync_report = [
            'syncPending' => true,
            'warnings' => array_values(array_unique($warnings)),
        ];
        try {
            $this->record_publish_sync_error($release, $detail);
        } catch (Throwable $record_error) {
            // Even the diagnostic write is housekeeping. Never lose the ACK of
            // a release that WordPress has already activated and checkpointed.
            error_log('[Onun Kodety] O aviso pós-publicação de ' . $release . ' não pôde ser persistido: ' . $record_error->getMessage());
        }
        return $release;
    }

    private function assert_release_activation_checkpoint(
        string $release,
        int $workspace_revision,
        string $css_digest,
        string $theme_stylesheet
    ): void {
        $failures = [];
        if ((string) get_option('kodety_current_release', '') !== $release) $failures[] = 'release';
        if ((int) get_option('kodety_workspace_revision', -1) !== $workspace_revision) $failures[] = 'revision';
        if ((string) get_option('kodety_workspace_css_digest', '') !== $css_digest) $failures[] = 'CSS';
        if ((string) wp_get_theme()->get_stylesheet() !== $theme_stylesheet) $failures[] = 'tema ativo';
        if ($failures) {
            throw new RuntimeException(
                'O WordPress não confirmou: ' . implode(', ', $failures) . '.'
            );
        }
    }

    /**
     * Releases are rollback points, not an append-only copy of every project
     * ever opened. Keep a small recoverable window of native source trees;
     * legacy project.zip files are removed after their contents are migrated.
     */
    private function prune_release_storage(string $current_release = '', int $limit = self::RELEASE_RETENTION_LIMIT): void {
        $limit = max(1, min(20, $limit));
        $directories = glob($this->releases_dir() . '/*', GLOB_ONLYDIR) ?: [];
        usort($directories, static function (string $left, string $right): int {
            $modified = ((int) @filemtime($right)) <=> ((int) @filemtime($left));
            return $modified !== 0 ? $modified : strcmp(basename($right), basename($left));
        });
        if ($current_release === '' && function_exists('get_option')) $current_release = (string) get_option('kodety_current_release', '');
        $keep = [];
        if ($current_release !== '' && is_dir($this->releases_dir() . '/' . $current_release)) {
            $keep[$current_release] = true;
        }
        foreach ($directories as $directory) {
            $legacy_zip = $directory . '/project.zip';
            if (is_file($legacy_zip) && is_dir($directory . '/project')) @unlink($legacy_zip);
            $name = basename($directory);
            if (isset($keep[$name])) continue;
            if (count($keep) < $limit) $keep[$name] = true;
        }
        foreach ($directories as $directory) {
            if (!isset($keep[basename($directory)])) $this->remove_tree($directory);
        }
    }

    private function extract_safe_zip(string $zip_path, string $destination): void {
        if (!class_exists('ZipArchive')) throw new RuntimeException('A extensão PHP ZipArchive precisa estar habilitada na hospedagem.');
        $zip = new ZipArchive();
        if ($zip->open($zip_path) !== true) throw new RuntimeException('O arquivo ZIP é inválido ou está corrompido.');
        if ($zip->numFiles > 10000) { $zip->close(); throw new RuntimeException('O ZIP possui arquivos demais.'); }
        $total = 0;
        $extract_entries = [];
        for ($index = 0; $index < $zip->numFiles; $index++) {
            $stat = $zip->statIndex($index);
            $archive_name = (string) ($stat['name'] ?? '');
            $name = str_replace('\\', '/', $archive_name);
            $normalized = ltrim($name, '/');
            $raw_segments = explode('/', rtrim($normalized, '/'));
            if (
                $normalized === ''
                || str_starts_with($name, '/')
                || preg_match('/^[A-Za-z]:/', $normalized)
                || in_array('..', $raw_segments, true)
                || str_contains($normalized, "\0")
            ) { $zip->close(); throw new RuntimeException('O ZIP contém um caminho inseguro.'); }
            $operating_system = 0;
            $external_attributes = 0;
            if (method_exists($zip, 'getExternalAttributesIndex')
                && $zip->getExternalAttributesIndex($index, $operating_system, $external_attributes)
                && (($external_attributes >> 16) & 0170000) === 0120000) {
                $zip->close();
                throw new RuntimeException('O ZIP contém links simbólicos não permitidos.');
            }
            $segments = array_values(array_filter(explode('/', rtrim($normalized, '/')), static fn(string $part): bool => $part !== ''));
            $basename = basename(rtrim($normalized, '/'));
            $ignored_os_metadata = in_array('__MACOSX', $segments, true)
                || in_array($basename, ['.DS_Store', 'Thumbs.db'], true);
            // Finder metadata and host-specific server configuration are not
            // website source. Silently omit them instead of rejecting an
            // otherwise valid static-site ZIP. In particular, never extract
            // an authored .htaccess: Apache directives can enable handlers or
            // execute files outside the browser-only project contract.
            $ignored_server_config = $basename === '.htaccess';
            if ($ignored_os_metadata || $ignored_server_config) continue;
            // Compatibility fallback: auxiliary dotfiles and file types the
            // browser-only Builder cannot process are omitted, but never make
            // the rest of the upload fail. `.incode`/`.coday` remain portable
            // editor metadata and therefore continue through extraction.
            if ($this->project_path_uses_zip_fallback(rtrim($normalized, '/'))) continue;
            if (str_ends_with($normalized, '/')) {
                $extract_entries[] = $archive_name;
                continue;
            }
            $size = (int) ($stat['size'] ?? 0);
            if ($size > 256 * MB_IN_BYTES) { $zip->close(); throw new RuntimeException('Um arquivo do ZIP excede 256 MB.'); }
            $total += $size;
            if ($total > self::PROJECT_ARCHIVE_MAX_BYTES) { $zip->close(); throw new RuntimeException('O conteúdo descompactado excede 800 MB.'); }
            $extract_entries[] = $archive_name;
        }
        if (!$extract_entries || !$zip->extractTo($destination, $extract_entries)) { $zip->close(); throw new RuntimeException('Não foi possível descompactar o projeto.'); }
        $zip->close();
        $macos_metadata = rtrim($destination, '/\\') . '/__MACOSX';
        if (is_dir($macos_metadata)) $this->remove_tree($macos_metadata);
        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($destination, FilesystemIterator::SKIP_DOTS),
            RecursiveIteratorIterator::CHILD_FIRST
        );
        foreach ($iterator as $file) {
            if ($file->isFile() && in_array($file->getFilename(), ['.DS_Store', 'Thumbs.db'], true)) @unlink($file->getPathname());
        }
    }

    private function zip_contains_shopify_theme(string $zip_path): bool {
        if (!class_exists('ZipArchive') || !is_file($zip_path)) return false;
        $zip = new ZipArchive();
        if ($zip->open($zip_path) !== true) return false;
        try {
            for ($index = 0; $index < $zip->numFiles; $index++) {
                $name = strtolower(ltrim(str_replace('\\', '/', (string) ($zip->statIndex($index)['name'] ?? '')), '/'));
                if (preg_match('~(?:^|/)layout/theme\.liquid$~', $name)) return true;
            }
        } finally {
            $zip->close();
        }
        return false;
    }

    /** Remove only .htaccess files written by the retired query-version cache
     * feature. Unrelated hosting rules are never touched. */
    private function remove_legacy_asset_cache_rules(): void {
        $uploads = wp_upload_dir(null, false);
        if (!is_array($uploads) || !empty($uploads['error']) || empty($uploads['basedir'])) return;
        $rules_path = trailingslashit((string) $uploads['basedir']) . 'kodety/assets/.htaccess';
        if (!is_file($rules_path) || is_link($rules_path)) return;
        $rules = file_get_contents($rules_path);
        if (!is_string($rules)) throw new RuntimeException('As regras antigas de cache não puderam ser lidas.');
        if (
            !str_starts_with($rules, '# Onun Kodety stable asset URLs')
            && !str_starts_with($rules, '# Onun Kodety asset compatibility release ')
        ) return;
        if (!@unlink($rules_path) && is_file($rules_path)) {
            throw new RuntimeException('As regras antigas de cache dos assets não puderam ser removidas.');
        }
    }

    private function run_cache_purge_step(string $label, callable $operation): void {
        try {
            $operation();
        } catch (Throwable $error) {
            error_log('[Onun Kodety] Limpeza de cache opcional falhou em ' . $label . ': ' . $error->getMessage());
        }
    }

    /** Best-effort cache invalidation after a release. Every provider is
     * isolated so a missing/broken plugin or CDN can never fail the publish. */
    private function purge_published_site_cache(): void {
        $this->run_cache_purge_step('regras legadas de assets', function (): void {
            $this->remove_legacy_asset_cache_rules();
        });
        $this->run_cache_purge_step('WordPress object cache', static function (): void {
            wp_cache_flush();
        });
        $this->run_cache_purge_step('WP Rocket', static function (): void {
            if (function_exists('rocket_clean_domain')) rocket_clean_domain();
        });
        $this->run_cache_purge_step('W3 Total Cache', static function (): void {
            if (function_exists('w3tc_flush_all')) w3tc_flush_all();
        });
        $this->run_cache_purge_step('WP Super Cache', static function (): void {
            if (function_exists('wp_cache_clear_cache')) wp_cache_clear_cache();
        });
        $this->run_cache_purge_step('SiteGround Optimizer', static function (): void {
            if (function_exists('sg_cachepress_purge_cache')) sg_cachepress_purge_cache();
        });
        $this->run_cache_purge_step('LiteSpeed API', static function (): void {
            if (class_exists('LiteSpeed_Cache_API') && method_exists('LiteSpeed_Cache_API', 'purge_all')) {
                LiteSpeed_Cache_API::purge_all();
            }
        });
        $this->run_cache_purge_step('LiteSpeed hook', static function (): void {
            do_action('litespeed_purge_all');
        });
        // The official Cloudflare WordPress plugin subscribes this hook to a
        // full zone purge when it is installed and authenticated. With no
        // listener the action is a harmless no-op.
        $this->run_cache_purge_step('Cloudflare WordPress', static function (): void {
            do_action('autoptimize_action_cachepurged');
        });
        /** Allows a host-specific cache/CDN integration to purge its edge. */
        $this->run_cache_purge_step('kodety_purge_published_cache', static function (): void {
            do_action('kodety_purge_published_cache');
        });
    }

    /** A signed license transition can change the public HTML without a release. */
    public function purge_cache_after_license_transition(bool $active, ?bool $was_active): void {
        if ($was_active !== null && $active === $was_active) return;
        $this->purge_published_site_cache();
    }

    private function build_theme(string $project_root, string $theme_dir, array $html_files, string $release, array $optimizations, ?string $expected_css_digest = null, array $draft_pages = []): void {
        $main_html = $this->resolve_main_html($project_root, $html_files);
        $web_root = trim(str_replace('\\', '/', dirname($main_html)), './');
        $static_roots = $this->project_static_roots($project_root, $web_root);
        $manifest_entries = [];
        foreach ($html_files as $absolute) {
            $relative = ltrim(str_replace('\\', '/', substr($absolute, strlen($project_root))), '/');
            // The web root is where the archive happened to place the main
            // page. It is a packaging detail, not part of the public URL.
            $route = $relative;
            foreach (array_merge([$web_root], $static_roots) as $strip) {
                if ($strip === '' || stripos($route . '/', $strip . '/') !== 0) continue;
                $route = ltrim(substr($route, strlen($strip)), '/');
            }
            $manifest_entries[] = ['route' => $route, 'relativePath' => $relative];
        }
        $route_collisions = [];
        $manifest = $this->project_page_route_map($manifest_entries, $route_collisions);
        foreach ($route_collisions as $collision) {
            $selected_path = (string) ($collision['selectedPath'] ?? '');
            $ignored_paths = array_values(array_filter(
                array_map('strval', (array) ($collision['pagePaths'] ?? [])),
                static fn(string $path): bool => $path !== $selected_path
            ));
            $this->last_publish_sync_report['warnings'][] = sprintf(
                'A rota %s tinha mais de uma página. %s foi publicada%s.',
                (string) ($collision['route'] ?? '/'),
                $selected_path !== '' ? $selected_path : 'uma versão determinística',
                $ignored_paths ? '; outro arquivo não foi escolhido para essa rota: ' . implode(', ', $ignored_paths) : ''
            );
        }
        $manifest[''] = $main_html;
        wp_mkdir_p($theme_dir . '/site');
        $this->copy_tree($project_root, $theme_dir . '/site');
        // Draft pages stay in the private editable workspace and release
        // source, but never enter the public theme — not even through a direct
        // `/wp-content/themes/.../*.html` URL that bypasses the route manifest.
        foreach (array_keys($draft_pages) as $draft_page) {
            $public_draft = $theme_dir . '/site/' . $draft_page;
            if (is_file($public_draft) && !@unlink($public_draft)) {
                throw new RuntimeException('Uma página Draft não pôde ser removida da árvore pública. A versão anterior continua ativa.');
            }
        }
        // The upload/workspace digest intentionally covers private A/B clones.
        // The public theme intentionally omits `.incode`, so this build-stage
        // comparison must compare like-for-like public trees instead of the
        // complete authoring digest supplied by install_zip_locked().
        // Compare the exact public subset on both sides. Draft HTML is
        // intentionally removed from the staged theme above, so including it
        // only in the source digest made every project with a Draft page fail
        // publication even though copy_tree() had preserved all public files.
        $public_source_css_digest = $this->css_digest_from_directory(
            $project_root,
            false,
            $draft_pages
        );
        $staged_css_digest = $this->css_digest_from_directory($theme_dir . '/site');
        if ($expected_css_digest !== null && !hash_equals($public_source_css_digest, $staged_css_digest)) {
            throw new RuntimeException('A preparação do tema descartou ou alterou CSS antes da publicação. A versão anterior continua ativa.');
        }
        // Keep authored module names and references byte-for-byte intact.
        // Browser MIME support belongs to the host/server layer; renaming
        // arbitrary .mjs/.cjs files here can invalidate dynamic imports and
        // integrity manifests from coded projects.
        // `.incode` is intentionally excluded from the public theme because it
        // contains the complete editable workspace. The frontend still needs
        // the locale map and translations, so publish only that portable,
        // non-secret subset beside the generated runtime.
        $localization = $this->project_localization($project_root);
        $membership_runtime = $this->project_membership_runtime($project_root);
        if ($membership_runtime && is_array($membership_runtime['pages'] ?? null)) {
            foreach (array_keys($draft_pages) as $draft_page) unset($membership_runtime['pages'][$draft_page]);
        }
        if ($membership_runtime) {
            // Guarded PHP payloads remain unreadable through a direct theme URL
            // while still being available to the WordPress runtime. Keeping
            // localization private as a whole also prevents translated premium
            // copy from leaking through a public JSON file.
            $this->write_membership_theme_payload($theme_dir, $membership_runtime, $release);
            $this->write_guarded_theme_payload(
                $theme_dir . '/membership-localization.php',
                $localization,
                'Private Onun Kodety membership localization.'
            );
        } else {
            $localization_json = wp_json_encode(
                $localization,
                JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
            );
            if (!is_string($localization_json) || strlen($localization_json) > 64 * 1024 * 1024) {
                throw new RuntimeException('A localização pública excede o limite seguro de publicação.');
            }
            $localization_path = $theme_dir . '/localization.json';
            $localization_temporary = $localization_path . '.tmp-' . bin2hex(random_bytes(4));
            $localization_written = file_put_contents($localization_temporary, $localization_json, LOCK_EX);
            if (
                $localization_written !== strlen($localization_json)
                || !rename($localization_temporary, $localization_path)
            ) {
                @unlink($localization_temporary);
                throw new RuntimeException('A localização pública não pôde ser gravada integralmente.');
            }
        }
        // Redirect rules are needed before WordPress resolves a page, but the
        // rest of `.incode/project.json` remains private. Publish only the
        // normalized, non-secret runtime contract.
        $redirects = $this->project_redirects($project_root);
        file_put_contents(
            $theme_dir . '/redirects.json',
            wp_json_encode($redirects, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
            LOCK_EX
        );
        // SEO runtime settings are intentionally bounded to crawler-facing
        // policy. Authoring prompts, social templates and the rest of project
        // metadata remain private.
        $seo_runtime = $this->project_seo_runtime($project_root);
        $seo_json = wp_json_encode(
            $seo_runtime,
            JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        );
        if (!is_string($seo_json) || strlen($seo_json) > 1_000_000) {
            throw new RuntimeException('As configurações públicas de SEO excedem o limite seguro de publicação.');
        }
        $seo_path = $theme_dir . '/seo.json';
        $seo_temporary = $seo_path . '.kodety-next-' . bin2hex(random_bytes(6));
        $seo_written = file_put_contents($seo_temporary, $seo_json, LOCK_EX);
        if ($seo_written !== strlen($seo_json) || !rename($seo_temporary, $seo_path)) {
            if (is_file($seo_temporary)) @unlink($seo_temporary);
            throw new RuntimeException('As configurações públicas de SEO não puderam ser gravadas na nova versão.');
        }
        // Build the crawler inventory from this exact public route manifest,
        // before the theme/workspace activation checkpoint. No asynchronous
        // native Page synchronization is required to expose these URLs.
        $sitemap_metadata_path = rtrim($project_root, '/\\') . '/.incode/project.json';
        $sitemap_metadata = is_file($sitemap_metadata_path)
            ? json_decode((string) file_get_contents($sitemap_metadata_path), true) : [];
        $sitemap_previous = [];
        try {
            $sitemap_previous = Kodety_Sitemap::read_contract(trailingslashit(get_theme_root()) . 'kodety-generated');
        } catch (Throwable $previous_sitemap_error) {
            // A damaged historical inventory cannot prevent a fresh valid
            // publication; it only means previous lastmod cannot be reused.
            error_log('[Onun Kodety sitemap] ' . $previous_sitemap_error->getMessage());
        }
        $sitemap_contract = Kodety_Sitemap::build_contract(
            $project_root, $manifest, is_array($sitemap_metadata) ? $sitemap_metadata : [],
            $seo_runtime, $localization, $membership_runtime, $redirects,
            $this->cms_template_definitions(), $release, home_url('/'), $sitemap_previous
        );
        Kodety_Sitemap::prepare($theme_dir, $sitemap_contract, Kodety_Sitemap::cms_entries($sitemap_contract));
        // Social image authoring stays private in `.incode/project.json`.
        // Publish only the bounded renderer contract needed to generate
        // per-page and per-CMS Open Graph images on this release.
        $social_images = class_exists('Kodety_Social_Images')
            ? Kodety_Social_Images::project_contract_from_directory($project_root)
            : [
                'version' => 2,
                'templates' => [],
                'siteTemplate' => null,
                'pageTemplates' => [],
                'postTypeTemplates' => [],
                'siteVariables' => [],
                'pageVariables' => [],
            ];
        foreach (['pageTemplates', 'pageVariables'] as $page_contract_key) {
            if (!is_array($social_images[$page_contract_key] ?? null)) continue;
            foreach (array_keys($draft_pages) as $draft_page) {
                unset($social_images[$page_contract_key][$draft_page]);
            }
        }
        $social_images_json = wp_json_encode(
            $social_images,
            JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        );
        // Keep this build-time ceiling aligned with the runtime reader. A
        // truncated/oversized contract must fail before theme activation;
        // silently publishing it would make the runtime clear valid generated
        // images because every assignment appeared to have disappeared.
        if (!is_string($social_images_json) || strlen($social_images_json) > 16_000_000) {
            throw new RuntimeException('Os templates de Social Image excedem o limite seguro de publicação.');
        }
        $social_images_path = $theme_dir . '/social-images.json';
        $social_images_temporary = $social_images_path . '.kodety-next-' . bin2hex(random_bytes(6));
        $social_images_written = file_put_contents(
            $social_images_temporary,
            $social_images_json,
            LOCK_EX
        );
        if ($social_images_written !== strlen($social_images_json)
            || !rename($social_images_temporary, $social_images_path)) {
            if (is_file($social_images_temporary)) @unlink($social_images_temporary);
            throw new RuntimeException('O contrato de Social Image não pôde ser gravado na nova versão.');
        }
        // The copied site is the authored runtime. Do not rename linked
        // stylesheets or rewrite their HTML references during publication.
        $this->optimize_generated_site($theme_dir . '/site', $optimizations, $release, $web_root);
        $delivery_config = wp_json_encode([
            'version' => 2, 'enabled' => $optimizations['enabled'],
            'compressHtml' => $optimizations['compressHtml'],
            'compressAssets' => $optimizations['compressAssets'],
        ]);
        if (!is_string($delivery_config) || file_put_contents($theme_dir . '/performance-config.json', $delivery_config, LOCK_EX) !== strlen($delivery_config)) {
            throw new RuntimeException('As opções de entrega da publicação não puderam ser gravadas.');
        }
        // A request made directly to a copied HTML file bypasses WordPress and
        // therefore cannot receive the PHP route rewriter or client runtime.
        // Put a tiny guard at the very start of every published document so a
        // stale/custom link to `/wp-content/themes/.../site/*.html` immediately
        // returns to the corresponding public route before site code executes.
        $direct_routes = [];
        foreach ($manifest as $route => $relative) {
            $relative = trim(str_replace('\\', '/', (string) $relative), '/');
            if ($relative === '') continue;
            if (!isset($direct_routes[$relative]) || $route === '') {
                $direct_routes[$relative] = trim((string) $route, '/');
            }
        }
        foreach ($direct_routes as $relative => $route) {
            $published_html_path = $theme_dir . '/site/' . $relative;
            if (!is_file($published_html_path)) continue;
            $published_html = (string) file_get_contents($published_html_path);
            $guarded_html = $this->inject_direct_public_route_guard($published_html, $route);
            if ($guarded_html === $published_html) continue;
            $written = file_put_contents($published_html_path, $guarded_html, LOCK_EX);
            if ($written !== strlen($guarded_html)) {
                throw new RuntimeException('A proteção das rotas públicas não pôde ser gravada na nova versão.');
            }
        }
        $header = "/*\nTheme Name: Onun Kodety Generated Site\nDescription: Tema gerado e versionado pelo Onun Kodety.\nVersion: " . esc_html($release) . "\nText Domain: kodety-generated\n*/\n";
        file_put_contents($theme_dir . '/style.css', $header, LOCK_EX);
        file_put_contents($theme_dir . '/manifest.json', wp_json_encode($manifest, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES), LOCK_EX);
        foreach (self::theme_runtime_sources() as $runtime_file => $runtime_source) {
            $runtime_content = is_file($runtime_source)
                ? file_get_contents($runtime_source)
                : false;
            if (!is_string($runtime_content)) {
                throw new RuntimeException('O arquivo-base do runtime ' . $runtime_file . ' não pôde ser lido.');
            }
            $this->assert_valid_theme_runtime_source($runtime_file, $runtime_content);
            $this->write_verified_theme_runtime_file(
                $theme_dir . '/' . $runtime_file,
                $runtime_content,
                hash('sha256', $runtime_content)
            );
        }
        // MIME compatibility is a hosting concern, not a source transform.
        // It never changes authored URLs, imports or file names.
        try {
            $this->write_asset_compatibility_rules($theme_dir, $optimizations);
        } catch (Throwable $error) {
            // Some managed/Nginx hosts reject per-directory Apache files. MIME
            // compatibility is optional and must never invalidate a publish.
            error_log('[Onun Kodety] Compatibilidade MIME opcional não aplicada: ' . $error->getMessage());
        }
    }

    private function localization_element_key(mixed $value, bool $allow_body = false): string {
        $key = is_string($value) ? trim($value) : '';
        if ($allow_body && $key === 'body') return $key;
        return preg_match('/^(?:(?:id|insertion):[A-Za-z0-9_.:-]{1,200}|path:(?:\d+(?:\/\d+)*)?)$/', $key) ? $key : '';
    }

    private function localization_unicode_length(string $value): int {
        if ($value === '') return 0;
        if (!preg_match('//u', $value)) return PHP_INT_MAX;
        $length = preg_match_all('/./us', $value);
        return is_int($length) ? $length : PHP_INT_MAX;
    }

    private function localization_collection(mixed $candidate, int $limit, string $label): array {
        if (!is_array($candidate)) return [];
        if (count($candidate) > $limit) {
            throw new DomainException(sprintf(
                'A localização excede o limite de %d %s. Nenhuma alteração foi publicada.',
                $limit,
                $label
            ));
        }
        return $candidate;
    }

    private function localization_scalar(
        mixed $value,
        int $limit = self::LOCALIZATION_MAX_SCALAR_BYTES,
        string $label = 'bytes por valor'
    ): ?string {
        if (!is_scalar($value)) return null;
        $string = (string) $value;
        if (strlen($string) > $limit) {
            throw new DomainException(sprintf(
                'A localização excede o limite de %d %s. Nenhuma alteração foi publicada.',
                $limit,
                $label
            ));
        }
        return $string;
    }

    private function project_localization_overrides(mixed $candidate): array {
        $candidate = $this->localization_collection(
            $candidate,
            self::LOCALIZATION_MAX_OVERRIDES_PER_PAGE,
            'sobrescritas por página'
        );
        $overrides = [];
        foreach ($candidate as $raw_key => $raw_override) {
            $key = $this->localization_element_key($raw_key, true);
            if ($key === '' || !is_array($raw_override)) continue;
            $override = [];
            if (array_key_exists('visible', $raw_override) && is_bool($raw_override['visible'])) {
                $override['visible'] = $raw_override['visible'];
            }
            $attributes = [];
            $raw_attributes = $this->localization_collection(
                $raw_override['attributes'] ?? [],
                self::LOCALIZATION_MAX_ATTRIBUTES_PER_OVERRIDE,
                'atributos por elemento'
            );
            foreach ($raw_attributes as $raw_name => $raw_value) {
                $name = strtolower(trim((string) $raw_name));
                if (!preg_match('/^[a-z_:][a-z0-9_.:-]*$/', $name)
                    || str_contains($name, ':')
                    || $name === 'style'
                    || $name === 'srcdoc'
                    || str_starts_with($name, 'on')
                    || $name === 'data-kodety-l10n-id'
                    || str_starts_with($name, 'data-kodety-locale-')
                    || str_starts_with($name, 'data-kodety-bind-')
                ) continue;
                if ($raw_value === null) $attributes[$name] = null;
                else {
                    $value = $this->localization_scalar($raw_value);
                    if ($value === null) continue;
                    if ($name === 'id'
                        && ($value === '' || $this->localization_unicode_length($value) > 200 || trim($value) !== $value || preg_match('/[\x00-\x20\x7F"\'<>=`]/u', $value))
                    ) continue;
                    if ($name === 'class'
                        && ($this->localization_unicode_length($value) > 2000 || preg_match('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F"\'<>=`]/u', $value))
                    ) continue;
                    if (in_array($name, ['href', 'src', 'srcset', 'poster', 'action', 'formaction'], true)) {
                        $url_value = html_entity_decode($value, ENT_QUOTES | ENT_HTML5, 'UTF-8');
                        if (preg_match('/(?:^|[\s,])(?:javascript|vbscript)\s*:/i', $url_value)
                            || (preg_match('/^\s*data\s*:/i', $url_value) && !in_array($name, ['src', 'srcset', 'poster'], true))
                            || preg_match('/^\s*data\s*:(?!image\/)/i', $url_value)
                        ) continue;
                    }
                    $attributes[$name] = $value;
                }
            }
            if ($attributes) $override['attributes'] = $attributes;
            $styles = [];
            $raw_styles = $this->localization_collection(
                $raw_override['styles'] ?? [],
                self::LOCALIZATION_MAX_STYLES_PER_OVERRIDE,
                'estilos por elemento'
            );
            foreach ($raw_styles as $raw_property => $raw_value) {
                $property = strtolower(trim((string) $raw_property));
                if (!preg_match('/^(?:--[a-z0-9_-]+|[a-z][a-z0-9-]*)$/', $property)
                    || in_array($property, ['behavior', '-moz-binding'], true)
                ) continue;
                if ($raw_value === null) $styles[$property] = null;
                else {
                    $value = $this->localization_scalar(
                        $raw_value,
                        self::LOCALIZATION_MAX_STYLE_BYTES,
                        'bytes por estilo'
                    );
                    if ($value === null || preg_match('/(?:expression\s*\(|javascript\s*:|vbscript\s*:)/i', $value)) continue;
                    $styles[$property] = $value;
                }
            }
            if ($styles) $override['styles'] = $styles;
            if ($override) $overrides[$key] = $override;
        }
        return $overrides;
    }

    private function project_localization_insertions(mixed $candidate): array {
        $candidate = $this->localization_collection(
            $candidate,
            self::LOCALIZATION_MAX_INSERTIONS_PER_PAGE,
            'seções exclusivas por página'
        );
        $order = [];
        $ordered = [];
        $insertions = [];
        foreach (array_values($candidate) as $raw_insertion) {
            if (!is_array($raw_insertion)) continue;
            $id = trim((string) ($raw_insertion['id'] ?? ''));
            if (!preg_match('/^[A-Za-z0-9_.:-]{1,200}$/', $id)) continue;
            if (!isset($ordered[$id])) {
                $order[] = $id;
                $ordered[$id] = true;
            }
            if (($raw_insertion['removed'] ?? false) === true) {
                $insertions[$id] = ['id' => $id, 'removed' => true];
                continue;
            }
            $anchor = $this->localization_element_key($raw_insertion['anchor'] ?? 'body', true);
            $position = (string) ($raw_insertion['position'] ?? 'append');
            $html = $this->localization_scalar($raw_insertion['html'] ?? '');
            if ($anchor === '' || $html === null || $html === '') continue;
            $insertions[$id] = [
                'id' => $id,
                'anchor' => $anchor,
                'position' => in_array($position, ['before', 'after', 'prepend', 'append'], true) ? $position : 'append',
                'html' => $html,
                'enabled' => ($raw_insertion['enabled'] ?? true) !== false,
            ];
        }
        return array_values(array_filter(array_map(
            static fn(string $id): ?array => $insertions[$id] ?? null,
            $order
        )));
    }

    private function project_localization_stylesheet_path(mixed $candidate): string {
        if (!is_string($candidate)) return '';
        $path = trim($candidate);
        if ($path === '' || strlen($path) > 1024 || str_contains($path, '\\')) return '';
        $path = (string) preg_replace('~^\./+~', '', $path);
        $path = (string) preg_replace('~/+~', '/', $path);
        $decoded = $path;
        $malformed_encoding = false;
        for ($pass = 0; $pass < 2; $pass++) {
            if (preg_match('/%(?![0-9A-Fa-f]{2})/', $decoded)) {
                $malformed_encoding = true;
                break;
            }
            $decoded = rawurldecode($decoded);
        }
        if (
            $path === ''
            || str_starts_with($path, '/')
            || preg_match('/[\x00-\x1F\x7F]/', $path)
            || preg_match('/[\x00-\x1F\x7F]/', $decoded)
            || $malformed_encoding
            || strpbrk($decoded, "\\?#:<>\"'`") !== false
            || preg_match('~(?:^|/)(?:\.|\.\.)(?:/|$)~', $decoded)
            || preg_match('~^(?:\.incode|\.coday)(?:/|$)~i', $decoded)
            || !preg_match('/\.css$/iD', $decoded)
        ) return '';
        return $path;
    }

    private function project_localization_page(mixed $candidate): array {
        if (!is_array($candidate)) return ['entries' => [], 'overrides' => [], 'insertions' => []];
        $page = [];
        foreach (['path' => 1024, 'title' => 10000, 'description' => 50000] as $key => $limit) {
            $value = $this->localization_scalar($candidate[$key] ?? '', $limit);
            if ($value !== null && $value !== '') $page[$key] = $value;
        }
        $stylesheet = $this->project_localization_stylesheet_path($candidate['stylesheet'] ?? null);
        if ($stylesheet !== '') $page['stylesheet'] = $stylesheet;
        $entries = [];
        $raw_entries = $this->localization_collection(
            $candidate['entries'] ?? [],
            self::LOCALIZATION_MAX_ENTRIES_PER_PAGE,
            'entradas de texto por página'
        );
        foreach ($raw_entries as $raw_key => $raw_value) {
            $key = is_string($raw_key) ? trim($raw_key) : '';
            $value = $this->localization_scalar($raw_value);
            if ($key === '' || strlen($key) > 300 || $value === null) continue;
            if (!preg_match('/^(?:id:[A-Za-z0-9_.:-]{1,200}|path:(?:\d+(?:\/\d+)*)?):(?:text|text-node:\d+|attr:[a-zA-Z0-9_.:-]+)$/', $key)) continue;
            $entries[$key] = $value;
        }
        $page['entries'] = $entries;
        $page['overrides'] = $this->project_localization_overrides($candidate['overrides'] ?? []);
        $page['insertions'] = $this->project_localization_insertions($candidate['insertions'] ?? []);
        return $page;
    }

    /** Canonicalize the Unicode/BCP-47 locale identifiers accepted by the
     * browser's Intl.getCanonicalLocales(). Keep a self-contained parser so
     * WordPress hosts without ext-intl enforce the same contract. */
    private function canonical_localization_locale_code(mixed $value): string {
        if (!is_string($value)) return '';
        $raw = trim($value);
        if ($raw === '' || strlen($raw) > 255 || !preg_match('/^[A-Za-z0-9-]+$/D', $raw)) return '';
        $parts = explode('-', $raw);
        if (in_array('', $parts, true)) return '';
        $index = 0;
        $language = strtolower((string) ($parts[$index++] ?? ''));
        // Intl.Locale implements Unicode locale identifiers, whose language
        // production deliberately excludes reserved 4-letter primaries and
        // legacy extlang forms such as `en-abc`.
        if (!preg_match('/^(?:[a-z]{2,3}|[a-z]{5,8})$/D', $language)) return '';
        $script = '';
        if (isset($parts[$index]) && preg_match('/^[A-Za-z]{4}$/D', $parts[$index])) {
            $script = ucfirst(strtolower($parts[$index++]));
        }
        $region = '';
        if (isset($parts[$index]) && preg_match('/^(?:[A-Za-z]{2}|[0-9]{3})$/D', $parts[$index])) {
            $region = ctype_digit($parts[$index]) ? $parts[$index] : strtoupper($parts[$index]);
            $index++;
        }
        $variants = [];
        $seen_variants = [];
        while (isset($parts[$index]) && preg_match('/^(?:[A-Za-z0-9]{5,8}|[0-9][A-Za-z0-9]{3})$/D', $parts[$index])) {
            $variant = strtolower($parts[$index++]);
            if (isset($seen_variants[$variant])) return '';
            $seen_variants[$variant] = true;
            $variants[] = $variant;
        }
        $extensions = [];
        $seen_singletons = [];
        while (isset($parts[$index]) && preg_match('/^[0-9A-WY-Za-wy-z]$/D', $parts[$index])) {
            $singleton = strtolower($parts[$index++]);
            if (isset($seen_singletons[$singleton])) return '';
            $seen_singletons[$singleton] = true;
            $subtags = [];
            while (isset($parts[$index]) && preg_match('/^[A-Za-z0-9]{2,8}$/D', $parts[$index])) {
                $subtags[] = strtolower($parts[$index++]);
            }
            if (!$subtags) return '';
            if ($singleton === 'u') {
                $attributes = [];
                $keywords = [];
                $subtag_index = 0;
                while (isset($subtags[$subtag_index]) && strlen($subtags[$subtag_index]) >= 3) {
                    $attribute = $subtags[$subtag_index++];
                    if (isset($attributes[$attribute])) return '';
                    $attributes[$attribute] = true;
                }
                while (isset($subtags[$subtag_index])) {
                    $key = $subtags[$subtag_index++];
                    if (strlen($key) !== 2 || isset($keywords[$key])) return '';
                    $types = [];
                    while (isset($subtags[$subtag_index]) && strlen($subtags[$subtag_index]) >= 3) {
                        $types[] = $subtags[$subtag_index++];
                    }
                    $keywords[$key] = $types;
                }
                ksort($attributes, SORT_STRING);
                ksort($keywords, SORT_STRING);
                $subtags = array_keys($attributes);
                foreach ($keywords as $key => $types) $subtags = array_merge($subtags, [$key], $types);
            }
            $extensions[] = array_merge([$singleton], $subtags);
        }
        $private = [];
        if (isset($parts[$index]) && strcasecmp($parts[$index], 'x') === 0) {
            $index++;
            while (isset($parts[$index]) && preg_match('/^[A-Za-z0-9]{1,8}$/D', $parts[$index])) {
                $private[] = strtolower($parts[$index++]);
            }
            if (!$private) return '';
        }
        if ($index !== count($parts)) return '';

        $language_aliases = [
            'in' => 'id', 'iw' => 'he', 'ji' => 'yi', 'jw' => 'jv',
            'mo' => 'ro', 'tl' => 'fil',
        ];
        if ($language === 'sh') {
            $language = 'sr';
            if ($script === '') $script = 'Latn';
        } else {
            $language = $language_aliases[$language] ?? $language;
        }
        $region_aliases = [
            'BU' => 'MM', 'DD' => 'DE', 'FX' => 'FR', 'TP' => 'TL',
            'YD' => 'YE', 'ZR' => 'CD',
        ];
        if ($region !== '' && !ctype_digit($region)) $region = $region_aliases[$region] ?? $region;
        sort($variants, SORT_STRING);
        usort($extensions, static fn(array $left, array $right): int => $left[0] <=> $right[0]);
        $canonical = array_merge(
            [$language],
            $script !== '' ? [$script] : [],
            $region !== '' ? [$region] : [],
            $variants
        );
        foreach ($extensions as $extension) $canonical = array_merge($canonical, $extension);
        if ($private) $canonical = array_merge($canonical, ['x'], $private);
        return implode('-', $canonical);
    }

    /** Extract and normalize the public localization payload without exposing
     * the rest of `.incode/project.json` in the generated theme. Version 2
     * added structural overrides; version 3 makes automatic locale routing the
     * default while keeping an explicit v3 false as the opt-out. */
    private function project_localization(string $project_root, ?array $localization_override = null): array {
        $defaults = [
            'version' => 3,
            'sourceLocale' => 'pt-BR',
            'defaultLocale' => 'pt-BR',
            'automaticLocale' => true,
            'rememberLocale' => true,
            'translatePagePaths' => false,
            'locales' => [],
            'translations' => [],
        ];
        if (!Kodety_Edition::has('localization')) return $defaults;
        if ($localization_override !== null) {
            $candidate = $localization_override;
        } else {
            $metadata_path = rtrim($project_root, '/\\') . '/.incode/project.json';
            if (!is_file($metadata_path)) return $defaults;
            $metadata = json_decode((string) file_get_contents($metadata_path), true);
            $candidate = is_array($metadata) && is_array($metadata['localization'] ?? null)
                ? $metadata['localization']
                : [];
        }
        $source = $this->canonical_localization_locale_code($candidate['sourceLocale'] ?? null)
            ?: $defaults['sourceLocale'];
        $locales = [];
        $locale_codes = [];
        $raw_locales = $this->localization_collection(
            $candidate['locales'] ?? [],
            self::LOCALIZATION_MAX_LOCALES,
            'idiomas'
        );
        foreach ($raw_locales as $raw_locale) {
            if (!is_array($raw_locale)) continue;
            $code = $this->canonical_localization_locale_code($raw_locale['code'] ?? null);
            if ($code === '' || isset($locale_codes[strtolower($code)])) continue;
            $locale_codes[strtolower($code)] = $code;
            $language = strtolower(trim((string) ($raw_locale['language'] ?? strtok($code, '-'))));
            $region = strtoupper(trim((string) ($raw_locale['region'] ?? '')));
            $locales[] = [
                'code' => $code,
                'language' => preg_match('/^[a-z]{2,3}$/', $language) ? $language : strtolower((string) strtok($code, '-')),
                'region' => preg_match('/^[A-Z0-9]{2,3}$/', $region) ? $region : '',
                'name' => sanitize_text_field((string) ($raw_locale['name'] ?? $code)),
                'slug' => sanitize_title((string) ($raw_locale['slug'] ?? strtolower($code))),
                'fallback' => $this->canonical_localization_locale_code($raw_locale['fallback'] ?? null) ?: $source,
                'enabled' => strcasecmp($code, $source) === 0 || ($raw_locale['enabled'] ?? true) !== false,
                'direction' => ($raw_locale['direction'] ?? 'ltr') === 'rtl' ? 'rtl' : 'ltr',
            ];
        }
        if (!isset($locale_codes[strtolower($source)])) {
            if (count($locales) >= self::LOCALIZATION_MAX_LOCALES) {
                throw new RuntimeException(sprintf(
                    'A localização excede o limite de %d idiomas ao incluir o idioma original. Nenhuma alteração foi publicada.',
                    self::LOCALIZATION_MAX_LOCALES
                ));
            }
            array_unshift($locales, [
                'code' => $source, 'language' => strtolower((string) strtok($source, '-')), 'region' => '',
                'name' => $source, 'slug' => '', 'fallback' => '', 'enabled' => true, 'direction' => 'ltr',
            ]);
            $locale_codes[strtolower($source)] = $source;
        } else {
            $source = $locale_codes[strtolower($source)];
        }
        $requested_default = $this->canonical_localization_locale_code($candidate['defaultLocale'] ?? null) ?: $source;
        $default = $locale_codes[strtolower($requested_default)] ?? $source;
        foreach ($locales as &$locale) {
            if ($locale['code'] === $default) $locale['slug'] = '';
            if ($locale['code'] === $source) $locale['fallback'] = '';
            else {
                $fallback_key = strtolower((string) $locale['fallback']);
                $locale['fallback'] = isset($locale_codes[$fallback_key])
                    && strcasecmp($locale_codes[$fallback_key], $locale['code']) !== 0
                    ? $locale_codes[$fallback_key]
                    : $source;
            }
        }
        unset($locale);

        $draft_pages = $this->project_draft_page_paths($project_root);
        $translations = [];
        $raw_translations = $this->localization_collection(
            $candidate['translations'] ?? [],
            self::LOCALIZATION_MAX_LOCALES,
            'conjuntos de tradução'
        );
        $translations_by_locale = [];
        foreach ($raw_translations as $raw_code => $raw_translation) {
            $code = $this->canonical_localization_locale_code($raw_code);
            if ($code !== '') $translations_by_locale[strtolower($code)] = $raw_translation;
        }
        foreach ($locale_codes as $code) {
            $raw_locale_translation = is_array($translations_by_locale[strtolower($code)] ?? null)
                ? $translations_by_locale[strtolower($code)]
                : [];
            if (!$raw_locale_translation) continue;
            $translation = ['pages' => []];
            foreach (['siteTitle' => 10000, 'siteDescription' => 50000] as $key => $limit) {
                $value = $this->localization_scalar($raw_locale_translation[$key] ?? '', $limit);
                if ($value !== null && $value !== '') $translation[$key] = $value;
            }
            $raw_pages = $this->localization_collection(
                $raw_locale_translation['pages'] ?? [],
                self::LOCALIZATION_MAX_PAGES_PER_LOCALE,
                'páginas por idioma'
            );
            foreach ($raw_pages as $raw_path => $raw_page) {
                $path = ltrim(str_replace('\\', '/', trim((string) $raw_path)), '/');
                if ($path === '' || strlen($path) > 1024 || str_contains($path, '../') || str_contains($path, "\0")) continue;
                if (isset($draft_pages[$path])) continue;
                $translation['pages'][$path] = $this->project_localization_page($raw_page);
            }
            $translations[$code] = $translation;
        }
        $automatic_locale = (int) ($candidate['version'] ?? 0) < 3
            ? true
            : (($candidate['automaticLocale'] ?? true) === true);
        return [
            'version' => 3,
            'sourceLocale' => $source,
            'defaultLocale' => $default,
            'automaticLocale' => $automatic_locale,
            'rememberLocale' => ($candidate['rememberLocale'] ?? true) !== false,
            'translatePagePaths' => ($candidate['translatePagePaths'] ?? false) === true,
            'locales' => array_values($locales),
            'translations' => $translations,
        ];
    }

    /** Reject malformed authoring metadata before an uploaded draft can replace
     * the current workspace. Runtime projection remains defensive, but silently
     * dropping a broken locale here would leave the Builder and public site with
     * different truths and could crash older clients on their next reload. */
    private function assert_project_localization_metadata(string $project_root, ?array $metadata_override = null): void {
        $metadata_path = rtrim($project_root, '/\\') . '/.incode/project.json';
        if ($metadata_override === null) {
            if (!is_file($metadata_path)) return;
            if (is_link($metadata_path)) {
                throw new DomainException('Os metadados do projeto não podem apontar para um link simbólico.');
            }
            $metadata_size = filesize($metadata_path);
            if (!is_int($metadata_size) || $metadata_size < 2 || $metadata_size > 64_000_000) {
                throw new DomainException('Os metadados do projeto excedem o limite seguro de 64 MB.');
            }
            $raw_metadata = file_get_contents($metadata_path);
            $metadata = is_string($raw_metadata) ? json_decode($raw_metadata, true) : null;
        } else {
            $metadata = $metadata_override;
        }
        if (!is_array($metadata)) {
            throw new DomainException('Os metadados do projeto não contêm JSON válido. O rascunho anterior foi preservado.');
        }
        if (!array_key_exists('localization', $metadata)) return;
        $candidate = $metadata['localization'];
        if (!is_array($candidate)) {
            throw new DomainException('A configuração de idiomas possui um formato inválido. O rascunho anterior foi preservado.');
        }
        foreach (['automaticLocale', 'rememberLocale', 'translatePagePaths', 'includePathsInAi'] as $flag) {
            if (array_key_exists($flag, $candidate) && !is_bool($candidate[$flag])) {
                throw new DomainException(sprintf('A opção %s da localização precisa ser booleana.', $flag));
            }
        }
        $raw_locales = $candidate['locales'] ?? null;
        $raw_translations = $candidate['translations'] ?? null;
        if (!is_array($raw_locales) || !$this->project_delta_array_is_list($raw_locales) || !is_array($raw_translations)) {
            throw new DomainException('As listas de idiomas e traduções possuem um formato inválido.');
        }
        if (count($raw_locales) > self::LOCALIZATION_MAX_LOCALES || count($raw_translations) > self::LOCALIZATION_MAX_LOCALES) {
            throw new DomainException('A configuração de idiomas excede o limite seguro do projeto.');
        }
        $source = $this->canonical_localization_locale_code($candidate['sourceLocale'] ?? null);
        $default = $this->canonical_localization_locale_code($candidate['defaultLocale'] ?? null);
        if ($source === '' || $default === '') {
            throw new DomainException('O idioma fonte ou padrão não usa um código BCP 47 válido.');
        }
        $locales = [];
        $enabled_slugs = [];
        foreach ($raw_locales as $raw_locale) {
            if (!is_array($raw_locale)) throw new DomainException('Um idioma do projeto possui formato inválido.');
            $code = $this->canonical_localization_locale_code($raw_locale['code'] ?? null);
            $key = strtolower($code);
            if ($code === '' || isset($locales[$key])) {
                throw new DomainException('Há um código de idioma inválido ou duplicado no projeto.');
            }
            $slug = trim((string) ($raw_locale['slug'] ?? ''), '/');
            if ($slug !== '' && !preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/D', $slug)) {
                throw new DomainException(sprintf('O prefixo de URL de %s é inválido.', $code));
            }
            $enabled = strcasecmp($code, $source) === 0 || ($raw_locale['enabled'] ?? true) !== false;
            if ($enabled) {
                $slug_key = strtolower($slug);
                if (isset($enabled_slugs[$slug_key])) {
                    throw new DomainException('Dois idiomas publicados usam o mesmo prefixo de URL.');
                }
                $enabled_slugs[$slug_key] = $code;
            }
            $locales[$key] = [
                'code' => $code,
                'enabled' => $enabled,
                'fallback' => $this->canonical_localization_locale_code($raw_locale['fallback'] ?? null),
                'slug' => $slug,
            ];
        }
        $source_key = strtolower($source);
        $default_key = strtolower($default);
        if (!isset($locales[$source_key]) || !isset($locales[$default_key]) || !$locales[$default_key]['enabled']) {
            throw new DomainException('O idioma fonte e o idioma padrão precisam existir e estar publicados.');
        }
        if ($locales[$default_key]['slug'] !== '') {
            throw new DomainException('O idioma padrão precisa usar a URL sem prefixo.');
        }
        foreach ($locales as $key => $locale) {
            if ($key === $source_key) continue;
            $fallback_key = strtolower((string) $locale['fallback']);
            if ($fallback_key === $key || !isset($locales[$fallback_key]) || !$locales[$fallback_key]['enabled']) {
                throw new DomainException(sprintf('O fallback de %s não aponta para um idioma publicado.', $locale['code']));
            }
        }
        $public_page_routes = [];
        $draft_pages = $this->project_draft_page_paths($project_root);
        $html_files = array_values(array_filter(
            $this->find_html_files($project_root),
            static function (string $absolute) use ($project_root, $draft_pages): bool {
                $relative = ltrim(str_replace('\\', '/', substr($absolute, strlen(rtrim($project_root, '/\\')))), '/');
                return !isset($draft_pages[$relative]);
            }
        ));
        if ($html_files) {
            $main_html = $this->resolve_main_html($project_root, $html_files);
            $web_root = trim(str_replace('\\', '/', dirname($main_html)), './');
            $static_roots = $this->project_static_roots($project_root, $web_root);
            foreach ($html_files as $absolute) {
                $relative = ltrim(str_replace('\\', '/', substr($absolute, strlen(rtrim($project_root, '/\\')))), '/');
                $route = $relative;
                foreach (array_merge([$web_root], $static_roots) as $strip) {
                    if ($strip === '' || stripos($route . '/', $strip . '/') !== 0) continue;
                    $route = ltrim(substr($route, strlen($strip)), '/');
                }
                $route = preg_replace('~(?:^|/)index\.html?$~i', '', $route);
                $route = preg_replace('/\.html?$/i', '', (string) $route);
                $public_page_routes[$relative] = trim((string) $route, '/');
            }
            $public_page_routes[$main_html] = '';
        }
        $translate_page_paths = ($candidate['translatePagePaths'] ?? false) === true;
        $explicit_routes_by_locale = [];
        $seen_translation_codes = [];
        foreach ($raw_translations as $raw_code => $translation) {
            $canonical_translation_code = $this->canonical_localization_locale_code($raw_code);
            $locale_key = strtolower($canonical_translation_code);
            if (
                $canonical_translation_code === ''
                ||
                isset($seen_translation_codes[$locale_key])
                || !isset($locales[$locale_key])
                || $locale_key === $source_key
                || !is_array($translation)
            ) {
                throw new DomainException('Uma coleção de traduções não pertence a um idioma configurado.');
            }
            $seen_translation_codes[$locale_key] = true;
            $pages = $translation['pages'] ?? [];
            if (!is_array($pages) || count($pages) > self::LOCALIZATION_MAX_PAGES_PER_LOCALE) {
                throw new DomainException('A lista de páginas traduzidas possui formato ou tamanho inválido.');
            }
            $explicit_routes = [];
            foreach ($pages as $page_path => $raw_page) {
                if (!is_string($page_path) || !is_array($raw_page)) {
                    throw new DomainException('Uma página traduzida possui formato inválido.');
                }
                $authored_path = trim(str_replace('\\', '/', $page_path));
                $decoded_authored_path = $authored_path;
                for ($decode_pass = 0; $decode_pass < 2; $decode_pass += 1) {
                    $decoded_authored_path = rawurldecode($decoded_authored_path);
                }
                if (
                    $authored_path === ''
                    || strlen($authored_path) > 1024
                    || str_starts_with($authored_path, '/')
                    || str_starts_with(strtolower($authored_path), '.incode/')
                    || str_starts_with(strtolower($authored_path), '.coday/')
                    || !preg_match('/\.html?$/iD', $authored_path)
                    || preg_match('/[\x00-\x1F\x7F]/', $authored_path)
                    || preg_match('/[\x00-\x1F\x7F]/', $decoded_authored_path)
                    || str_contains($decoded_authored_path, '\\')
                    || str_contains($decoded_authored_path, '?')
                    || str_contains($decoded_authored_path, '#')
                    || preg_match('~(?:^|/)(?:\.|\.\.)(?:/|$)~', $decoded_authored_path)
                ) {
                    throw new DomainException('Uma tradução referencia uma página original insegura ou inválida.');
                }
                if (!array_key_exists($authored_path, $public_page_routes)) {
                    throw new DomainException('Uma tradução referencia uma página que não existe no projeto público.');
                }
                if (array_key_exists('stylesheet', $raw_page)) {
                    $raw_stylesheet = $raw_page['stylesheet'];
                    $stylesheet = $this->project_localization_stylesheet_path($raw_stylesheet);
                    if (!is_string($raw_stylesheet) || $stylesheet === '' || $stylesheet !== $raw_stylesheet) {
                        throw new DomainException(sprintf(
                            'O stylesheet localizado de %s usa um caminho inválido ou inseguro.',
                            $page_path
                        ));
                    }
                }
                $route = trim((string) ($raw_page['path'] ?? ''), '/');
                if ($route === '') {
                    $explicit_routes[$authored_path] = '';
                    continue;
                }
                $decoded_route = $route;
                for ($decode_pass = 0; $decode_pass < 2; $decode_pass += 1) {
                    $decoded_route = rawurldecode($decoded_route);
                }
                if (
                    str_contains($route, '\\')
                    || str_contains($route, '?')
                    || str_contains($route, '#')
                    || preg_match('/[\x00-\x1F\x7F]/', $route)
                    || preg_match('/[\x00-\x1F\x7F]/', $decoded_route)
                    || str_contains($decoded_route, '\\')
                    || str_contains($decoded_route, '?')
                    || str_contains($decoded_route, '#')
                    || preg_match('~(?:^|/)(?:\.|\.\.)(?:/|$)~', $decoded_route)
                ) {
                    throw new DomainException(sprintf('A URL traduzida de %s é insegura.', $page_path));
                }
                $explicit_routes[$authored_path] = preg_replace('~/+~', '/', $decoded_route) ?? $decoded_route;
            }
            // Localized page paths remain editable draft data while the
            // feature is disabled. They do not participate in the published
            // route table and therefore must not block adding an unrelated
            // language or changing copy. The global route pass below applies
            // them once translatePagePaths is actually enabled.
            if ($translate_page_paths) {
                $effective_routes = [];
                foreach ($public_page_routes as $authored_path => $authored_route) {
                    $effective_route = $explicit_routes[$authored_path] ?? $authored_route;
                    $route_key = strtolower(trim(preg_replace('~/+~', '/', $effective_route) ?? $effective_route, '/'));
                    if (isset($effective_routes[$route_key]) && $effective_routes[$route_key] !== $authored_path) {
                        throw new DomainException('Duas páginas publicadas do mesmo idioma usam a mesma URL efetiva.');
                    }
                    $effective_routes[$route_key] = $authored_path;
                }
            }
            $explicit_routes_by_locale[$locale_key] = $explicit_routes;
        }
        $global_routes = [];
        foreach ($locales as $locale_key => $locale) {
            if (!$locale['enabled']) continue;
            $prefix = $locale_key === $default_key ? '' : trim((string) $locale['slug'], '/');
            $locale_routes = $explicit_routes_by_locale[$locale_key] ?? [];
            foreach ($public_page_routes as $authored_path => $authored_route) {
                $effective_route = $translate_page_paths
                    && $locale_key !== $source_key
                    && isset($locale_routes[$authored_path])
                    && $locale_routes[$authored_path] !== ''
                    ? $locale_routes[$authored_path]
                    : $authored_route;
                $full_route = trim(($prefix !== '' ? $prefix . '/' : '') . trim($effective_route, '/'), '/');
                $route_key = strtolower(preg_replace('~/+~', '/', $full_route) ?? $full_route);
                $owner = $locale['code'] . ':' . $authored_path;
                if (isset($global_routes[$route_key]) && $global_routes[$route_key] !== $owner) {
                    throw new DomainException('Duas páginas ou idiomas publicados resolvem para a mesma URL pública.');
                }
                $global_routes[$route_key] = $owner;
            }
        }
        // Reuse the bounded public projection for deep entry/override/insertion
        // limits after the structural checks above have established its shape.
        $this->project_localization($project_root, $candidate);
    }

    private function project_seo_runtime(string $project_root): array {
        $defaults = [
            'version' => 1,
            'sitemapEnabled' => true,
            'blockAiTrainingBots' => false,
            'robotsTxtRules' => '',
            'excludedPaths' => [],
        ];
        if (!Kodety_Edition::has('advancedSeo')) return $defaults;
        $metadata_path = rtrim($project_root, '/\\') . '/.incode/project.json';
        if (!is_file($metadata_path) || is_link($metadata_path)) return $defaults;
        $size = filesize($metadata_path);
        if (!is_int($size) || $size < 2 || $size > 32_000_000) return $defaults;
        $metadata = json_decode((string) file_get_contents($metadata_path), true);
        if (!is_array($metadata)) return $defaults;
        $site = is_array($metadata['siteSettings'] ?? null) ? $metadata['siteSettings'] : [];
        $raw_rules = str_replace(["\r\n", "\r"], "\n", (string) ($site['robotsTxtRules'] ?? ''));
        $safe_rules = [];
        foreach (array_slice(explode("\n", $raw_rules), 0, 200) as $line) {
            $line = trim(wp_strip_all_tags((string) $line));
            if ($line === '' || str_starts_with($line, '#')) {
                if ($line !== '') $safe_rules[] = substr($line, 0, 300);
                continue;
            }
            if (preg_match('/^(User-agent|Allow|Disallow|Crawl-delay|Sitemap|Host)\s*:\s*[^<>\r\n]{0,500}$/i', $line)) {
                $safe_rules[] = substr($line, 0, 600);
            }
        }
        $excluded = [];
        foreach ((array) ($metadata['pageSettings'] ?? []) as $path => $settings) {
            if (!is_string($path) || !is_array($settings) || ($settings['includeInSitemap'] ?? true) !== false) continue;
            $normalized = ltrim(str_replace('\\', '/', trim($path)), '/');
            if ($normalized !== '' && !str_contains($normalized, '..')) $excluded[] = substr($normalized, 0, 1000);
        }
        foreach (array_keys($this->project_draft_page_paths($project_root)) as $draft_page) {
            $excluded[] = $draft_page;
        }
        return [
            'version' => 1,
            'sitemapEnabled' => ($site['sitemapEnabled'] ?? true) !== false,
            'blockAiTrainingBots' => ($site['blockAiTrainingBots'] ?? false) === true,
            'robotsTxtRules' => implode("\n", $safe_rules),
            'excludedPaths' => array_values(array_unique(array_slice($excluded, 0, 5000))),
        ];
    }

    /** @param array<string,mixed> $fallback */
    private function membership_fallback_is_valid(array $fallback): bool {
        $type = (string) ($fallback['type'] ?? '');
        if ($type === 'hide') return true;
        if ($type === 'branch') {
            return in_array((string) ($fallback['branch'] ?? ''), ['guest', 'upgrade'], true);
        }
        if ($type !== 'redirect') return false;
        $url = trim((string) ($fallback['url'] ?? ''));
        if (
            $url === ''
            || strlen($url) > 4096
            || str_starts_with($url, '//')
            || preg_match('/[\x00-\x20\x7f]/', $url)
        ) return false;
        if (str_starts_with($url, '/')) return true;
        return strtolower((string) wp_parse_url($url, PHP_URL_SCHEME)) === 'https'
            && (string) wp_parse_url($url, PHP_URL_HOST) !== ''
            && (string) wp_parse_url($url, PHP_URL_USER) === ''
            && (string) wp_parse_url($url, PHP_URL_PASS) === '';
    }

    /**
     * Validate the deliberately small Builder rule language before it reaches
     * either the renderer or the download endpoint.
     *
     * @param array<string,mixed> $rule
     */
    private function membership_access_rule_is_valid(array $rule): bool {
        $requirement = is_array($rule['requirement'] ?? null) ? $rule['requirement'] : [];
        $type = (string) ($requirement['type'] ?? '');
        if (!in_array($type, ['authenticated', 'plans'], true)) return false;
        if ($type === 'plans') {
            $match = (string) ($requirement['match'] ?? '');
            $keys = $requirement['planKeys'] ?? null;
            if (
                !in_array($match, ['any', 'all'], true)
                || !is_array($keys)
                || !$keys
                || count($keys) > 100
            ) return false;
            $unique = [];
            foreach ($keys as $key) {
                if (
                    !is_string($key)
                    || !preg_match('/^[a-z0-9][a-z0-9._-]{0,79}$/', $key)
                ) return false;
                $unique[$key] = true;
            }
            if (count($unique) !== count($keys)) return false;
        }
        return is_array($rule['anonymous'] ?? null)
            && is_array($rule['denied'] ?? null)
            && $this->membership_fallback_is_valid($rule['anonymous'])
            && $this->membership_fallback_is_valid($rule['denied']);
    }

    private function membership_authored_asset_path_is_valid(string $source_path): bool {
        if (
            $source_path === ''
            || strlen($source_path) > 1024
            || str_contains($source_path, '../')
            || str_contains($source_path, "\0")
            || str_contains($source_path, '\\')
        ) return false;
        if (!str_starts_with($source_path, '.incode/')) return true;
        return preg_match(
            '~^\.incode/experiments/[A-Za-z0-9._-]{1,128}/[A-Za-z0-9._-]{1,128}/project/(?!\.incode/).+~',
            $source_path
        ) === 1;
    }

    /** Read the private transport contract produced by the Builder. The
     * generated theme receives a guarded PHP projection; `.incode` itself is
     * never copied into the public theme. */
    private function project_membership_runtime(string $project_root): array {
        $path = rtrim($project_root, '/\\') . '/.incode/membership/runtime.json';
        if (!is_file($path)) return [];
        $runtime = $this->read_membership_artifact($path);
        if (!$runtime) {
            throw new RuntimeException('O runtime privado da Área de Membros excede o limite seguro.');
        }
        if (
            (int) ($runtime['version'] ?? 0) !== 1
            || ($runtime['enabled'] ?? false) !== true
            || !is_array($runtime['pages'] ?? null)
            || count($runtime['pages']) > 5000
        ) {
            throw new RuntimeException('O runtime privado da Área de Membros é inválido.');
        }
        $project_id = strtolower(trim((string) ($runtime['projectId'] ?? '')));
        if ($project_id === '' || strlen($project_id) > 96 || !preg_match('/^[a-z0-9][a-z0-9_-]*$/', $project_id)) {
            throw new RuntimeException('A Área de Membros precisa de uma identidade de projeto válida.');
        }
        foreach ($runtime['pages'] as $page_path => $page) {
            $normalized = ltrim(str_replace('\\', '/', (string) $page_path), '/');
            if (
                $normalized === ''
                || strlen($normalized) > 1024
                || str_contains($normalized, '../')
                || str_contains($normalized, "\0")
                || !preg_match('/\.html?$/i', $normalized)
                || !is_array($page)
                || !is_array($page['gates'] ?? null)
                || count($page['gates']) > 2000
            ) {
                throw new RuntimeException('O runtime privado contém uma página ou coleção de gates inválida.');
            }
            foreach ($page['gates'] as $instance_id => $gate) {
                if (
                    !is_string($instance_id)
                    || !preg_match('/^[A-Za-z0-9][A-Za-z0-9._:-]{0,180}$/', $instance_id)
                    || !is_array($gate)
                    || !is_array($gate['rule'] ?? null)
                    || !$this->membership_access_rule_is_valid($gate['rule'])
                    || !is_string($gate['protectedHtml'] ?? null)
                    || !is_string($gate['guestHtml'] ?? null)
                    || !is_string($gate['upgradeHtml'] ?? null)
                ) {
                    throw new RuntimeException('O runtime privado contém um gate incompleto.');
                }
            }
            if (
                isset($page['pageRule'])
                && (
                    !is_array($page['pageRule'])
                    || !$this->membership_access_rule_is_valid($page['pageRule'])
                    || !is_string($page['protectedHtml'] ?? null)
                )
            ) {
                throw new RuntimeException('A proteção de página inteira está incompleta.');
            }
        }
        $assets = $runtime['assets'] ?? [];
        if (!is_array($assets) || count($assets) > 500) {
            throw new RuntimeException('O manifesto de downloads protegidos é inválido.');
        }
        $asset_total = 0;
        foreach ($assets as $asset_id => $asset) {
            $source_path = is_array($asset)
                ? ltrim(str_replace('\\', '/', (string) ($asset['sourcePath'] ?? '')), '/')
                : '';
            $contexts = is_array($asset) && is_array($asset['contexts'] ?? null)
                ? $asset['contexts']
                : [];
            if (
                !is_string($asset_id)
                || !preg_match('/^asset-[a-f0-9]{24}$/', $asset_id)
                || !is_array($asset)
                || !hash_equals($asset_id, (string) ($asset['id'] ?? ''))
                || !$this->membership_authored_asset_path_is_valid($source_path)
                || (string) ($asset['storagePath'] ?? '') !== '.incode/membership/assets/' . $asset_id . '.bin'
                || (int) ($asset['size'] ?? 0) <= 0
                || (int) ($asset['size'] ?? 0) > self::MEMBERSHIP_MAX_PROTECTED_ASSET_BYTES
                || !preg_match('/^[a-f0-9]{64}$/', (string) ($asset['sha256'] ?? ''))
                || (string) ($asset['encryption']['algorithm'] ?? '') !== 'aes-256-gcm-chunked-v1'
                || (int) ($asset['encryption']['chunkSize'] ?? 0) !== 1024 * 1024
                || trim((string) ($asset['filename'] ?? '')) === ''
                || strlen((string) ($asset['filename'] ?? '')) > 255
                || strlen((string) ($asset['mimeType'] ?? '')) > 255
                || !$contexts
                || count($contexts) > 100
            ) {
                throw new RuntimeException('Um download protegido possui metadados inválidos.');
            }
            $asset_total += (int) $asset['size'];
            if ($asset_total > self::MEMBERSHIP_MAX_PROTECTED_ASSETS_TOTAL_BYTES) {
                throw new RuntimeException('Os downloads protegidos excedem o limite total.');
            }
            foreach ($contexts as $context) {
                $rules = is_array($context) && is_array($context['allOf'] ?? null)
                    ? $context['allOf']
                    : [];
                if (!$rules || count($rules) > 64) {
                    throw new RuntimeException('Um download protegido possui política inválida.');
                }
                foreach ($rules as $rule) {
                    if (!is_array($rule) || !$this->membership_access_rule_is_valid($rule)) {
                        throw new RuntimeException('Um download protegido possui regra inválida.');
                    }
                }
            }
        }
        if ($assets) {
            $hashes_by_size = [];
            foreach ($assets as $asset) {
                $hashes_by_size[(int) $asset['size']][(string) $asset['sha256']] = true;
            }
            $root = realpath($project_root);
            if (!$root) throw new RuntimeException('O projeto de membros não pôde ser validado.');
            $iterator = new RecursiveIteratorIterator(
                new RecursiveDirectoryIterator($root, FilesystemIterator::SKIP_DOTS)
            );
            foreach ($iterator as $file) {
                if (!$file->isFile() || $file->isLink()) continue;
                $relative = ltrim(str_replace('\\', '/', substr(
                    $file->getPathname(),
                    strlen($root)
                )), '/');
                $future_public_variant = preg_match(
                    '~^\.incode/experiments/[^/]+/[^/]+/project/.+~',
                    $relative
                ) === 1;
                if (str_starts_with($relative, '.incode/') && !$future_public_variant) continue;
                $size = (int) $file->getSize();
                if (empty($hashes_by_size[$size])) continue;
                $hash = hash_file('sha256', $file->getPathname());
                if (is_string($hash) && !empty($hashes_by_size[$size][$hash])) {
                    throw new RuntimeException(
                        'Uma cópia de download protegido ainda seria publicada em “'
                        . $relative
                        . '”. Remova a duplicata antes de publicar.'
                    );
                }
            }
        }
        $runtime['assets'] = $assets;
        $runtime['projectId'] = $project_id;
        return $runtime;
    }

    /**
     * Refuse to publish a protected download while the same Kodety-managed
     * source path or byte payload is still exposed by the Media Library.
     *
     * Automatic deletion here would make publication non-atomic: if a later
     * theme build failed, the currently live site could lose an asset. The
     * explicit preflight keeps the old site untouched and gives the owner a
     * recoverable cleanup step before the security boundary changes.
     */
    private function assert_no_public_managed_membership_asset_copies(string $project_root): void {
        $runtime = $this->project_membership_runtime($project_root);
        $assets = is_array($runtime['assets'] ?? null) ? $runtime['assets'] : [];
        if (!$assets) return;

        $protected_paths = [];
        $protected_hashes_by_size = [];
        foreach ($assets as $asset) {
            if (!is_array($asset)) continue;
            $source_path = ltrim(str_replace(
                '\\',
                '/',
                trim((string) ($asset['sourcePath'] ?? ''))
            ), '/');
            if ($source_path !== '') $protected_paths[$source_path] = true;
            $size = (int) ($asset['size'] ?? 0);
            $hash = strtolower(trim((string) ($asset['sha256'] ?? '')));
            if ($size > 0 && preg_match('/^[a-f0-9]{64}$/', $hash)) {
                $protected_hashes_by_size[$size][$hash] = true;
            }
        }
        if (!$protected_paths && !$protected_hashes_by_size) return;

        $managed_ids = get_posts([
            'post_type' => 'attachment',
            // Trash does not guarantee that WordPress removed the original
            // file or generated previews from the public uploads directory.
            'post_status' => ['inherit', 'trash'],
            'posts_per_page' => 5001,
            'fields' => 'ids',
            'meta_key' => '_kodety_managed',
            'meta_value' => '1',
            'orderby' => 'ID',
            'order' => 'ASC',
            'no_found_rows' => true,
        ]);
        if (count($managed_ids) > 5000) {
            throw new RuntimeException(
                'A Mídia possui mais de 5.000 arquivos gerenciados pelo Onun Kodety. '
                . 'Limpe os anexos antigos antes de publicar downloads protegidos.'
            );
        }

        $conflicts = [];
        foreach ($managed_ids as $managed_id) {
            $managed_id = (int) $managed_id;
            if ($managed_id <= 0) continue;

            $paths = get_post_meta($managed_id, '_kodety_asset_paths', true);
            $paths = is_array($paths) ? $paths : [];
            $legacy_path = get_post_meta($managed_id, '_kodety_asset_path', true);
            if (is_string($legacy_path) && trim($legacy_path) !== '') {
                $paths[] = $legacy_path;
            }
            $path_match = false;
            foreach ($paths as $path) {
                if (!is_string($path)) continue;
                $normalized = ltrim(str_replace('\\', '/', trim($path)), '/');
                if ($normalized !== '' && isset($protected_paths[$normalized])) {
                    $path_match = true;
                    break;
                }
            }

            $payload_match = false;
            $attached_file = (string) get_attached_file($managed_id);
            if (!$path_match && $attached_file !== '' && is_file($attached_file)) {
                $size = (int) @filesize($attached_file);
                if ($size > 0 && isset($protected_hashes_by_size[$size])) {
                    $hash = hash_file('sha256', $attached_file);
                    $payload_match = is_string($hash)
                        && isset($protected_hashes_by_size[$size][$hash]);
                }
            }
            if ($path_match || $payload_match) $conflicts[] = $managed_id;
            if (count($conflicts) >= 5) break;
        }
        if (!$conflicts) return;

        throw new RuntimeException(
            'Um download que será protegido ainda possui cópia pública gerenciada '
            . 'pelo Onun Kodety na Mídia (anexo'
            . (count($conflicts) > 1 ? 's ' : ' ')
            . implode(', ', $conflicts)
            . '). Exclua permanentemente '
            . (count($conflicts) > 1 ? 'esses anexos' : 'esse anexo')
            . ' da Mídia e invalide qualquer cache/CDN antes de publicar novamente.'
        );
    }

    /** Derive a site-bound encryption key without persisting another secret. */
    private function membership_artifact_key(): string {
        return hash_hmac(
            'sha256',
            'kodety-membership-release-v1',
            wp_salt('secure_auth'),
            true
        );
    }

    private function membership_asset_key(string $project_id, string $asset_id): string {
        return hash_hmac(
            'sha256',
            'kodety-membership-asset-v1' . "\0" . $project_id . "\0" . $asset_id,
            $this->membership_artifact_key(),
            true
        );
    }

    /** Resolve a private asset path and reject traversal/symlink escapes. */
    private function membership_asset_file(string $project_root, array $asset): string {
        $storage = ltrim(str_replace('\\', '/', trim((string) ($asset['storagePath'] ?? ''))), '/');
        $id = trim((string) ($asset['id'] ?? ''));
        if (
            !preg_match('/^asset-[a-f0-9]{24}$/', $id)
            || $storage !== '.incode/membership/assets/' . $id . '.bin'
        ) {
            throw new RuntimeException('Um download protegido possui armazenamento inválido.');
        }
        $root = realpath($project_root);
        $file = realpath(rtrim($project_root, '/\\') . '/' . $storage);
        $root_canonical = is_string($root)
            ? $this->project_delta_canonical_real_path($root)
            : '';
        $file_canonical = is_string($file)
            ? $this->project_delta_canonical_real_path($file)
            : '';
        if (
            !$root
            || !$file
            || !is_file($file)
            || !str_starts_with($file_canonical, $root_canonical . '/')
        ) {
            throw new RuntimeException('Um arquivo protegido não foi encontrado.');
        }
        return $file;
    }

    /** Encrypt one source into a staged, independently authenticated blob. */
    private function seal_membership_asset_to(
        string $source,
        string $destination,
        string $asset_id,
        string $project_id,
        int $declared_size,
        string $declared_hash
    ): void {
        $input = fopen($source, 'rb');
        $output = fopen($destination, 'xb');
        if (!is_resource($input) || !is_resource($output)) {
            if (is_resource($input)) fclose($input);
            if (is_resource($output)) fclose($output);
            @unlink($destination);
            throw new RuntimeException('Não foi possível preparar a criptografia de um download.');
        }
        $prefix = random_bytes(8);
        $chunk_size = 1024 * 1024;
        $hash = hash_init('sha256');
        $bytes = 0;
        $counter = 0;
        try {
            try {
                if (fwrite($output, 'KDAYA01!' . $prefix) !== 16) {
                    throw new RuntimeException('Não foi possível iniciar o arquivo protegido.');
                }
                while (!feof($input)) {
                    $plaintext = fread($input, $chunk_size);
                    if (!is_string($plaintext)) throw new RuntimeException('Falha ao ler o download protegido.');
                    if ($plaintext === '') continue;
                    $nonce = $prefix . pack('N', $counter);
                    $tag = '';
                    $ciphertext = openssl_encrypt(
                        $plaintext,
                        'aes-256-gcm',
                        $this->membership_asset_key($project_id, $asset_id),
                        OPENSSL_RAW_DATA,
                        $nonce,
                        $tag,
                        $asset_id . "\0" . $counter,
                        16
                    );
                    if (!is_string($ciphertext) || strlen($tag) !== 16) {
                        throw new RuntimeException('A criptografia de um download protegido falhou.');
                    }
                    $record = pack('N', strlen($ciphertext)) . $tag . $ciphertext;
                    if (fwrite($output, $record) !== strlen($record)) {
                        throw new RuntimeException('Não foi possível concluir um download protegido.');
                    }
                    hash_update($hash, $plaintext);
                    $bytes += strlen($plaintext);
                    $counter++;
                }
            } finally {
                fclose($input);
                fclose($output);
            }
            $digest = hash_final($hash);
            if ($bytes !== $declared_size || !hash_equals($declared_hash, $digest)) {
                throw new RuntimeException('A integridade de um download protegido não confere.');
            }
        } catch (Throwable $error) {
            @unlink($destination);
            throw $error;
        }
        @chmod($destination, 0600);
    }

    /**
     * Encrypt private downloads in staged chunks. Each replacement is atomic;
     * if the process stops between blobs, the next pass recognizes the magic
     * header and completes the still-idempotent transaction.
     */
    private function seal_membership_assets(string $project_root): void {
        $artifact_path = rtrim($project_root, '/\\') . '/.incode/membership/runtime.json';
        if (!is_file($artifact_path)) return;
        $encoded = (string) file_get_contents($artifact_path);
        $envelope = json_decode($encoded, true);
        $artifact_was_sealed = is_array($envelope) && ($envelope['sealed'] ?? false) === true;
        $runtime = $this->read_membership_artifact($artifact_path);
        $assets = is_array($runtime['assets'] ?? null) ? $runtime['assets'] : [];
        if (!$assets) return;
        if (count($assets) > 500) {
            throw new RuntimeException('A publicação excede 500 downloads protegidos.');
        }
        if (!function_exists('openssl_encrypt') || !function_exists('openssl_decrypt')) {
            throw new RuntimeException('OpenSSL é necessário para publicar downloads protegidos.');
        }
        $project_id = strtolower(trim((string) ($runtime['projectId'] ?? '')));
        if ($project_id === '') throw new RuntimeException('Downloads protegidos exigem uma identidade de projeto.');
        $changed = false;
        $total = 0;
        $staged = [];
        try {
            foreach ($assets as $asset_id => &$asset) {
                if (!is_array($asset) || !hash_equals((string) $asset_id, (string) ($asset['id'] ?? ''))) {
                    throw new RuntimeException('O manifesto de downloads protegidos é inválido.');
                }
                $source = $this->membership_asset_file($project_root, $asset);
                $declared_size = (int) ($asset['size'] ?? 0);
                $declared_hash = strtolower(trim((string) ($asset['sha256'] ?? '')));
                if (
                    $declared_size <= 0
                    || $declared_size > self::MEMBERSHIP_MAX_PROTECTED_ASSET_BYTES
                    || !preg_match('/^[a-f0-9]{64}$/', $declared_hash)
                ) {
                    throw new RuntimeException('Um download protegido excede os limites ou não possui integridade.');
                }
                $total += $declared_size;
                if ($total > self::MEMBERSHIP_MAX_PROTECTED_ASSETS_TOTAL_BYTES) {
                    throw new RuntimeException('Os downloads protegidos excedem 64 MB.');
                }
                $algorithm = (string) ($asset['encryption']['algorithm'] ?? '');
                if ($algorithm !== '' && $algorithm !== 'aes-256-gcm-chunked-v1') {
                    throw new RuntimeException('Um download protegido usa criptografia desconhecida.');
                }
                $handle = fopen($source, 'rb');
                $magic = is_resource($handle) ? fread($handle, 8) : false;
                if (is_resource($handle)) fclose($handle);
                $sealed_and_authenticated = false;
                if ($magic === 'KDAYA01!') {
                    $verification = tempnam(sys_get_temp_dir(), 'kodety-member-verify-');
                    if (!is_string($verification)) {
                        throw new RuntimeException('Um download protegido não pôde ser verificado.');
                    }
                    @unlink($verification);
                    $candidate = $asset;
                    $candidate['encryption'] = [
                        'algorithm' => 'aes-256-gcm-chunked-v1',
                        'chunkSize' => 1024 * 1024,
                    ];
                    try {
                        $this->open_membership_asset(
                            $source,
                            $verification,
                            $candidate,
                            $project_id
                        );
                        $sealed_and_authenticated = true;
                    } catch (Throwable $error) {
                        // A fresh plaintext upload may coincidentally start with
                        // our magic bytes. Only that uncommitted state may fall
                        // back to normal encryption; committed metadata or a
                        // sealed artifact must fail closed as corruption.
                        if ($algorithm !== '' || $artifact_was_sealed) throw $error;
                    } finally {
                        @unlink($verification);
                    }
                }
                if (!$sealed_and_authenticated) {
                    if ($algorithm === 'aes-256-gcm-chunked-v1') {
                        throw new RuntimeException('Um download protegido selado está corrompido.');
                    }
                    $temporary = $source . '.sealed-' . wp_generate_password(10, false, false);
                    $this->seal_membership_asset_to(
                        $source,
                        $temporary,
                        (string) $asset_id,
                        $project_id,
                        $declared_size,
                        $declared_hash
                    );
                    $staged[$source] = $temporary;
                }
                if (
                    $algorithm !== 'aes-256-gcm-chunked-v1'
                    || (int) ($asset['encryption']['chunkSize'] ?? 0) !== 1024 * 1024
                    || !$sealed_and_authenticated
                ) {
                    $asset['encryption'] = [
                        'algorithm' => 'aes-256-gcm-chunked-v1',
                        'chunkSize' => 1024 * 1024,
                    ];
                    $changed = true;
                }
            }
            unset($asset);
            if (!$changed && !$staged) return;
            $runtime['assets'] = $assets;
            $json = wp_json_encode($runtime, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
            if (!is_string($json) || strlen($json) > 64 * MB_IN_BYTES) {
                throw new RuntimeException('O manifesto dos downloads protegidos não pôde ser atualizado.');
            }
            $artifact_bytes = $artifact_was_sealed
                ? $this->encode_membership_artifact_envelope($json)
                : $json;
            $artifact_temporary = $artifact_path . '.tmp-' . wp_generate_password(10, false, false);
            if (file_put_contents($artifact_temporary, $artifact_bytes, LOCK_EX) === false) {
                @unlink($artifact_temporary);
                throw new RuntimeException('O manifesto dos downloads protegidos não pôde ser preparado.');
            }
            try {
                foreach ($staged as $source => $temporary) {
                    if (!rename($temporary, $source)) {
                        throw new RuntimeException('Um download protegido não pôde ser ativado.');
                    }
                    @chmod($source, 0600);
                    unset($staged[$source]);
                }
                if (!rename($artifact_temporary, $artifact_path)) {
                    throw new RuntimeException('O manifesto dos downloads protegidos não pôde ser ativado.');
                }
            } catch (Throwable $error) {
                @unlink($artifact_temporary);
                throw $error;
            }
        } finally {
            unset($asset);
            foreach ($staged as $temporary) @unlink($temporary);
        }
    }

    /** Decrypt and authenticate one protected file into a non-public target. */
    private function open_membership_asset(
        string $source,
        string $destination,
        array $asset,
        string $project_id
    ): void {
        $asset_id = (string) ($asset['id'] ?? '');
        if ((string) ($asset['encryption']['algorithm'] ?? '') !== 'aes-256-gcm-chunked-v1') {
            throw new RuntimeException('O download protegido não está selado.');
        }
        $input = fopen($source, 'rb');
        $temporary = $destination . '.tmp-' . wp_generate_password(8, false, false);
        wp_mkdir_p(dirname($destination));
        $output = fopen($temporary, 'xb');
        if (!is_resource($input) || !is_resource($output)) {
            if (is_resource($input)) fclose($input);
            if (is_resource($output)) fclose($output);
            @unlink($temporary);
            throw new RuntimeException('Não foi possível abrir um download protegido.');
        }
        @chmod($temporary, 0600);
        $hash = hash_init('sha256');
        $bytes = 0;
        try {
            try {
                $magic = fread($input, 8);
                $prefix = fread($input, 8);
                if ($magic !== 'KDAYA01!' || !is_string($prefix) || strlen($prefix) !== 8) {
                    throw new RuntimeException('O download protegido está corrompido.');
                }
                $counter = 0;
                while (!feof($input)) {
                    $length_bytes = fread($input, 4);
                    if ($length_bytes === '') break;
                    if (!is_string($length_bytes) || strlen($length_bytes) !== 4) {
                        throw new RuntimeException('Um bloco do download protegido está incompleto.');
                    }
                    $length = (int) (unpack('Nlength', $length_bytes)['length'] ?? 0);
                    if ($length <= 0 || $length > 1024 * 1024) {
                        throw new RuntimeException('Um bloco do download protegido excede o limite.');
                    }
                    $tag = fread($input, 16);
                    $ciphertext = '';
                    while (strlen($ciphertext) < $length && !feof($input)) {
                        $part = fread($input, $length - strlen($ciphertext));
                        if (!is_string($part) || $part === '') break;
                        $ciphertext .= $part;
                    }
                    if (!is_string($tag) || strlen($tag) !== 16 || strlen($ciphertext) !== $length) {
                        throw new RuntimeException('Um bloco do download protegido está truncado.');
                    }
                    $plaintext = openssl_decrypt(
                        $ciphertext,
                        'aes-256-gcm',
                        $this->membership_asset_key($project_id, $asset_id),
                        OPENSSL_RAW_DATA,
                        $prefix . pack('N', $counter),
                        $tag,
                        $asset_id . "\0" . $counter
                    );
                    if (!is_string($plaintext)) {
                        throw new RuntimeException('A autenticação do download protegido falhou.');
                    }
                    if (fwrite($output, $plaintext) !== strlen($plaintext)) {
                        throw new RuntimeException('Não foi possível reconstruir o download protegido.');
                    }
                    hash_update($hash, $plaintext);
                    $bytes += strlen($plaintext);
                    $counter++;
                }
            } finally {
                fclose($input);
                fclose($output);
            }
            $declared_size = (int) ($asset['size'] ?? 0);
            $declared_hash = strtolower((string) ($asset['sha256'] ?? ''));
            $digest = hash_final($hash);
            if (
                $bytes !== $declared_size
                || !preg_match('/^[a-f0-9]{64}$/', $declared_hash)
                || !hash_equals($declared_hash, $digest)
                || !rename($temporary, $destination)
            ) {
                throw new RuntimeException('A integridade do download protegido não confere.');
            }
        } catch (Throwable $error) {
            @unlink($temporary);
            throw $error;
        }
        @chmod($destination, 0600);
    }

    /**
     * Read either a fresh Builder JSON artifact or an encrypted rollback
     * artifact. Historical source lives below uploads, where Nginx does not
     * honor `.htaccess`; encryption therefore remains the final boundary.
     *
     * @return array<string,mixed>
     */
    private function read_membership_artifact(string $path): array {
        if (!is_file($path)) return [];
        $size = (int) filesize($path);
        if ($size <= 0 || $size > 96 * MB_IN_BYTES) return [];
        $encoded = (string) file_get_contents($path);
        $candidate = json_decode($encoded, true);
        if (!is_array($candidate)) return [];
        if (($candidate['sealed'] ?? false) !== true) {
            return strlen($encoded) <= 64 * MB_IN_BYTES ? $candidate : [];
        }
        if ((int) ($candidate['version'] ?? 0) !== 1) return [];
        $algorithm = sanitize_key((string) ($candidate['algorithm'] ?? ''));
        $ciphertext = base64_decode((string) ($candidate['ciphertext'] ?? ''), true);
        if (!is_string($ciphertext) || $ciphertext === '') return [];
        $plaintext = false;
        if ($algorithm === 'sodium-secretbox' && function_exists('sodium_crypto_secretbox_open')) {
            $nonce = base64_decode((string) ($candidate['nonce'] ?? ''), true);
            if (is_string($nonce) && strlen($nonce) === SODIUM_CRYPTO_SECRETBOX_NONCEBYTES) {
                $plaintext = sodium_crypto_secretbox_open(
                    $ciphertext,
                    $nonce,
                    $this->membership_artifact_key()
                );
            }
        } elseif ($algorithm === 'aes-256-gcm' && function_exists('openssl_decrypt')) {
            $iv = base64_decode((string) ($candidate['iv'] ?? ''), true);
            $tag = base64_decode((string) ($candidate['tag'] ?? ''), true);
            if (is_string($iv) && strlen($iv) === 12 && is_string($tag) && strlen($tag) === 16) {
                $plaintext = openssl_decrypt(
                    $ciphertext,
                    'aes-256-gcm',
                    $this->membership_artifact_key(),
                    OPENSSL_RAW_DATA,
                    $iv,
                    $tag,
                    'kodety-membership-release-v1'
                );
            }
        }
        if (!is_string($plaintext) || strlen($plaintext) > 64 * MB_IN_BYTES) return [];
        $runtime = json_decode($plaintext, true);
        return is_array($runtime) ? $runtime : [];
    }

    private function encode_membership_artifact_envelope(string $encoded): string {
        $key = $this->membership_artifact_key();
        if (function_exists('sodium_crypto_secretbox')) {
            $nonce = random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);
            $sealed = [
                'sealed' => true,
                'version' => 1,
                'algorithm' => 'sodium-secretbox',
                'nonce' => base64_encode($nonce),
                'ciphertext' => base64_encode(sodium_crypto_secretbox($encoded, $nonce, $key)),
            ];
        } elseif (function_exists('openssl_encrypt')) {
            $iv = random_bytes(12);
            $tag = '';
            $ciphertext = openssl_encrypt(
                $encoded,
                'aes-256-gcm',
                $key,
                OPENSSL_RAW_DATA,
                $iv,
                $tag,
                'kodety-membership-release-v1',
                16
            );
            if (!is_string($ciphertext) || strlen($tag) !== 16) {
                throw new RuntimeException('A criptografia do snapshot da Área de Membros falhou.');
            }
            $sealed = [
                'sealed' => true,
                'version' => 1,
                'algorithm' => 'aes-256-gcm',
                'iv' => base64_encode($iv),
                'tag' => base64_encode($tag),
                'ciphertext' => base64_encode($ciphertext),
            ];
        } else {
            throw new RuntimeException('A hospedagem precisa de Sodium ou OpenSSL para publicar conteúdo de membros.');
        }
        $json = wp_json_encode($sealed, JSON_UNESCAPED_SLASHES);
        if (!is_string($json)) throw new RuntimeException('O snapshot protegido não pôde ser serializado.');
        return $json;
    }

    /** Encrypt the rollback copy atomically before its release identifier is
     * exposed. The editable workspace is hydrated separately and keeps no
     * transport artifact at all. */
    private function seal_membership_artifact(string $project_root): void {
        $path = rtrim($project_root, '/\\') . '/.incode/membership/runtime.json';
        if (!is_file($path)) return;
        $encoded = (string) file_get_contents($path);
        $candidate = json_decode($encoded, true);
        if (is_array($candidate) && ($candidate['sealed'] ?? false) === true) {
            // Verify that this site's salts can still decrypt the rollback.
            if (!$this->read_membership_artifact($path)) {
                throw new RuntimeException('O snapshot criptografado da Área de Membros não pôde ser aberto.');
            }
            return;
        }
        if (
            strlen($encoded) > 64 * MB_IN_BYTES
            || !is_array($candidate)
            || (int) ($candidate['version'] ?? 0) !== 1
            || ($candidate['enabled'] ?? false) !== true
        ) {
            throw new RuntimeException('O snapshot da Área de Membros não pode ser protegido.');
        }
        $json = $this->encode_membership_artifact_envelope($encoded);
        $temporary = $path . '.tmp-' . wp_generate_password(8, false, false);
        if (
            file_put_contents($temporary, $json, LOCK_EX) === false
            || !rename($temporary, $path)
        ) {
            @unlink($temporary);
            throw new RuntimeException('O snapshot privado não pôde ser selado para rollback.');
        }
    }

    /** Open a sealed snapshot only inside a disposable export directory. The
     * Builder hydrates editorHtml in memory after importing the ZIP. */
    private function open_membership_artifact_for_transport(string $project_root): void {
        $root = $this->collapse_single_root($project_root);
        $path = $root . '/.incode/membership/runtime.json';
        if (!is_file($path)) return;
        $runtime = $this->project_membership_runtime($root);
        if (!$runtime) {
            throw new RuntimeException('O snapshot privado da Área de Membros não pôde ser preparado.');
        }
        $root_real = realpath($root);
        if (!$root_real) throw new RuntimeException('O workspace privado não pôde ser validado.');
        $root_canonical = $this->project_delta_canonical_real_path($root_real);
        foreach ((array) ($runtime['assets'] ?? []) as $asset) {
            if (!is_array($asset)) throw new RuntimeException('Um download protegido está incompleto.');
            $source_path = ltrim(str_replace('\\', '/', trim((string) ($asset['sourcePath'] ?? ''))), '/');
            if (
                !$this->membership_authored_asset_path_is_valid($source_path)
            ) {
                throw new RuntimeException('Um download protegido possui caminho autoral inválido.');
            }
            $encrypted = $this->membership_asset_file($root, $asset);
            $destination = $root . '/' . $source_path;
            wp_mkdir_p(dirname($destination));
            $parent = realpath(dirname($destination));
            $parent_canonical = is_string($parent)
                ? $this->project_delta_canonical_real_path($parent)
                : '';
            if (
                !$parent
                || (
                    $parent_canonical !== $root_canonical
                    && !str_starts_with($parent_canonical, $root_canonical . '/')
                )
                || is_file($destination)
            ) {
                throw new RuntimeException('Um download protegido tentou sair do workspace.');
            }
            $this->open_membership_asset(
                $encrypted,
                $destination,
                $asset,
                (string) ($runtime['projectId'] ?? '')
            );
            @unlink($encrypted);
        }
        $json = wp_json_encode($runtime, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        if (!is_string($json) || file_put_contents($path, $json, LOCK_EX) === false) {
            throw new RuntimeException('O snapshot privado não pôde ser aberto para o Builder.');
        }
        @chmod($path, 0600);
    }

    private function write_guarded_theme_payload(string $path, array $payload, string $comment): void {
        $php = "<?php\n"
            . "defined('ABSPATH') || exit;\n"
            . '// ' . str_replace(["\r", "\n"], '', $comment) . "\n"
            . 'return ' . var_export($payload, true) . ";\n";
        $temporary = $path . '.kodety-next-' . bin2hex(random_bytes(6));
        $written = file_put_contents($temporary, $php, LOCK_EX);
        if ($written !== strlen($php) || !rename($temporary, $path)) {
            if (is_file($temporary)) @unlink($temporary);
            throw new RuntimeException('Não foi possível proteger os artefatos privados da publicação.');
        }
    }

    /**
     * Keep the common membership index small and load only the protected page
     * requested by WordPress. A course with hundreds of lessons must not parse
     * every lesson's private HTML on each public request.
     *
     * @param array<string,mixed> $runtime
     */
    private function write_membership_theme_payload(
        string $theme_dir,
        array $runtime,
        string $release = ''
    ): void {
        $pages = is_array($runtime['pages'] ?? null) ? $runtime['pages'] : [];
        $directory = rtrim($theme_dir, '/\\') . '/membership-pages';
        wp_mkdir_p($directory);
        $page_files = [];
        foreach ($pages as $page_path => $page) {
            if (!is_string($page_path) || !is_array($page)) {
                throw new RuntimeException('Uma página privada não pôde ser preparada para o tema.');
            }
            // Authoring paths and the full editor copy are required only while
            // reopening the Builder workspace. Public runtime shards need the
            // server-renderable branches and policies only.
            unset(
                $page['path'],
                $page['runtimePath'],
                $page['authoredPath'],
                $page['editorHtml']
            );
            foreach ((array) ($page['gates'] ?? []) as $gate_id => $gate) {
                if (!is_array($gate)) continue;
                unset($gate['id'], $gate['gateId']);
                $page['gates'][$gate_id] = $gate;
            }
            $filename = hash('sha256', $page_path) . '.php';
            $this->write_guarded_theme_payload(
                $directory . '/' . $filename,
                $page,
                'Private Onun Kodety membership page.'
            );
            $page_files[$page_path] = $filename;
        }
        unset($runtime['pages']);
        $runtime['pageFiles'] = $page_files;
        if ($release !== '') $runtime['release'] = $release;
        $this->write_guarded_theme_payload(
            rtrim($theme_dir, '/\\') . '/membership-content.php',
            $runtime,
            'Private Onun Kodety membership index.'
        );
    }

    /** Extract the ordered redirects contract while discarding incomplete,
     * disabled or unsafe rules. Runtime repeats validation as defense in depth. */
    private function project_redirects(string $project_root): array {
        if (!Kodety_Edition::has('redirects')) return ['version' => 1, 'entries' => []];
        $metadata_path = rtrim($project_root, '/\\') . '/.incode/project.json';
        if (!is_file($metadata_path)) return ['version' => 1, 'entries' => []];
        $metadata = json_decode((string) file_get_contents($metadata_path), true);
        $candidate = is_array($metadata) && is_array($metadata['redirects'] ?? null)
            ? $metadata['redirects']
            : [];
        $source_entries = is_array($candidate['entries'] ?? null)
            ? $candidate['entries']
            : (is_array($candidate['redirects'] ?? null) ? $candidate['redirects'] : []);
        $entries = [];
        foreach (array_slice($source_entries, 0, 2000) as $index => $entry) {
            if (!is_array($entry)) continue;
            $enabled = $entry['enabled'] ?? true;
            if (is_string($enabled)) $enabled = !in_array(strtolower(trim($enabled)), ['', '0', 'false', 'no', 'off'], true);
            if (!$enabled) continue;
            $source = trim((string) ($entry['source'] ?? $entry['from'] ?? $entry['sourcePath'] ?? ''));
            $destination = trim((string) ($entry['destination'] ?? $entry['to'] ?? $entry['target'] ?? ''));
            if (
                $source === ''
                || $destination === ''
                || strlen($source) > 2048
                || strlen($destination) > 4096
                || str_contains($destination, "\r")
                || str_contains($destination, "\n")
            ) continue;
            $raw_match = $entry['match'] ?? $entry['matchType'] ?? null;
            $match = strtolower(trim((string) ($raw_match ?? '')));
            if (!in_array($match, ['exact', 'prefix', 'wildcard'], true)) {
                if (in_array($match, ['starts-with', 'path-prefix'], true)) $match = 'prefix';
                elseif (in_array($match, ['glob', 'pattern'], true) || ($raw_match === null && str_contains($source, '*'))) $match = 'wildcard';
                else $match = 'exact';
            }
            if (($match === 'wildcard') !== str_contains($source, '*')) continue;
            $status = (int) ($entry['status'] ?? $entry['statusCode'] ?? $entry['code'] ?? 301);
            if (!in_array($status, [301, 302, 307, 308], true)) $status = 301;
            $preserve_query = $entry['preserveQuery'] ?? true;
            if (is_string($preserve_query)) $preserve_query = !in_array(strtolower(trim($preserve_query)), ['', '0', 'false', 'no', 'off'], true);
            $entries[] = [
                'id' => substr(preg_replace('/[^a-zA-Z0-9_-]+/', '-', (string) ($entry['id'] ?? 'redirect-' . $index)) ?: 'redirect-' . $index, 0, 96),
                'source' => $source,
                'destination' => $destination,
                'match' => $match,
                'status' => $status,
                'preserveQuery' => (bool) $preserve_query,
                'enabled' => true,
            ];
        }
        return ['version' => 1, 'entries' => $entries];
    }

    private function version_stylesheet_files(string $site_root, string $release): void {
        $root = realpath($site_root);
        if (!$root) return;
        $token = preg_replace('/[^a-zA-Z0-9_-]/', '-', $release) ?: 'release';
        $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root, FilesystemIterator::SKIP_DOTS));
        foreach ($iterator as $file) {
            if (!$file->isFile() || !in_array(strtolower($file->getExtension()), ['html', 'htm'], true)) continue;
            $html_path = $file->getPathname();
            $html_dir = dirname($html_path);
            $html = (string) file_get_contents($html_path);
            $rewritten = preg_replace_callback('~<link\b[^>]*>~i', static function (array $match) use ($root, $html_dir, $token): string {
                $tag = $match[0];
                if (!preg_match('/\brel\s*=\s*(["\'])(.*?)\1/i', $tag, $rel)) return $tag;
                $relations = preg_split('/\s+/', strtolower(trim($rel[2]))) ?: [];
                if (!in_array('stylesheet', $relations, true)) return $tag;
                if (!preg_match('/\bhref\s*=\s*(["\'])(.*?)\1/i', $tag, $href_match)) return $tag;
                $href = trim($href_match[2]);
                if ($href === '' || str_starts_with($href, 'data:') || preg_match('~^(?:https?:)?//~i', $href)) return $tag;
                $clean = preg_split('/[?#]/', $href, 2)[0] ?? '';
                if (!preg_match('/\.css$/i', $clean)) return $tag;
                $decoded = rawurldecode($clean);
                $candidate = str_starts_with($decoded, '/')
                    ? $root . '/' . ltrim($decoded, '/')
                    : $html_dir . '/' . $decoded;
                $source = realpath($candidate);
                if (!$source || !is_file($source) || !str_starts_with($source, $root . DIRECTORY_SEPARATOR)) return $tag;
                $versioned_name = preg_replace('/\.css$/i', '.kodety-' . $token . '.css', basename($source));
                if (!is_string($versioned_name) || $versioned_name === '') return $tag;
                $versioned_target = dirname($source) . '/' . $versioned_name;
                if (!copy($source, $versioned_target)) return $tag;
                $versioned_clean = preg_replace('/\.css$/i', '.kodety-' . $token . '.css', $clean);
                if (!is_string($versioned_clean)) return $tag;
                $versioned_href = $versioned_clean . substr($href, strlen($clean));
                return str_replace($href_match[0], 'href=' . $href_match[1] . $versioned_href . $href_match[1], $tag);
            }, $html);
            if (is_string($rewritten) && $rewritten !== $html) file_put_contents($html_path, $rewritten, LOCK_EX);
        }
    }

    private function optimize_generated_site(string $site_root, array $settings, string $release, string $web_root = ''): void {
        $stamped = 0;
        $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($site_root, FilesystemIterator::SKIP_DOTS));
        foreach ($iterator as $file) {
            if (!$file->isFile() || $file->isLink() || !in_array(strtolower($file->getExtension()), ['html', 'htm'], true)) continue;
            $path = $file->getPathname();
            $before = (string) file_get_contents($path);
            $html = $this->stamp_published_html($before, $release);
            if ($html !== $before) {
                if (file_put_contents($path, $html, LOCK_EX) !== strlen($html)) throw new RuntimeException('A assinatura da publicação não pôde ser gravada.');
                $stamped++;
            }
        }
        $this->last_optimization_report = (new Kodety_Publication_Optimizer())->run($site_root, $settings, $release, $web_root);
        $this->last_optimization_report += $this->optimization_reapply_context;
        $this->last_optimization_report['stampedHtml'] = $stamped;
    }

    /**
     * Add an immutable publication signature to the generated theme only. The
     * editable workspace is untouched; every publish removes stale/user-edited
     * copies and writes the current release time directly after the doctype.
     */
    private function stamp_published_html(string $html, string $release): string {
        // DOMDocument can serialize its UTF-8 parsing hint as an XML processing
        // instruction or as <!--?xml ... ?-->. Neither belongs in HTML, and a
        // rollback/republish used to accumulate one copy per release.
        $html = (string) preg_replace(
            '~\s*(?:<\?xml\s+encoding\s*=\s*["\']utf-8["\']\s*\?>|<!--\s*\?xml\s+encoding\s*=\s*["\']utf-8["\']\s*\?\s*-->)~i',
            '',
            $html
        );
        $html = (string) preg_replace(
            '~\s*<!--\s*(?:Made with (?:Onun\s+)?Kodety(?:\s+for\s+WordPress)?\s*(?:(?:·|&middot;|&#183;|&#x0*b7;|[-–—])?\s*(?:unkern|kodety)\.com)?|Published\s+[^>]*?\s+UTC)\s*-->~i',
            '',
            $html
        );
        $published_at = null;
        if (preg_match('~^(\d{8}-\d{6})~', $release, $match)) {
            $published_at = DateTimeImmutable::createFromFormat('!Ymd-His', $match[1], new DateTimeZone('UTC')) ?: null;
        }
        if (!$published_at instanceof DateTimeImmutable) $published_at = new DateTimeImmutable('now', new DateTimeZone('UTC'));
        $signature = "<!-- Made with Onun Kodety for WordPress -->\n"
            . '<!-- Published ' . $published_at->format('M j, Y, g:i A \\U\\T\\C') . ' -->';
        if (preg_match('~<!doctype\s+html[^>]*>~i', $html)) {
            return (string) preg_replace('~(<!doctype\s+html[^>]*>)~i', '$1' . "\n" . $signature, $html, 1);
        }
        return $signature . "\n" . ltrim($html);
    }

    /** Ensure a physical theme HTML URL can never become a navigable public
     * destination. This runs before authored scripts and is deliberately
     * self-contained because direct static requests bypass every PHP hook. */
    private function inject_direct_public_route_guard(string $html, string $route): string {
        if (str_contains($html, 'data-kodety-direct-public-route')) return $html;
        $route = trim(str_replace('\\', '/', $route), '/');
        $route_json = json_encode(
            $route,
            JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_UNESCAPED_SLASHES
        );
        if (!is_string($route_json)) $route_json = '""';
        $guard = '<script data-kodety-direct-public-route>(function(){'
            . 'var marker="/wp-content/themes/kodety-generated/site/",path=location.pathname,index=path.indexOf(marker);'
            . 'if(index<0)return;var root=path.slice(0,index+1),route=' . $route_json . ','
            . 'target=root+(route?route.replace(/^\\/+|\\/+$/g,"")+"/":"");'
            . 'if(target!==path)location.replace(target+location.search+location.hash);'
            . '})();</script>';
        if (preg_match('/<head(?:\s[^>]*)?>/i', $html)) {
            return (string) preg_replace_callback(
                '/<head(?:\s[^>]*)?>/i',
                static fn(array $match): string => $match[0] . $guard,
                $html,
                1
            );
        }
        return $guard . $html;
    }

    private function write_asset_compatibility_rules(string $theme_dir, array $optimizations = []): void {
        $rules = "# Onun Kodety asset compatibility\n"
            . "<IfModule mod_mime.c>\n"
            . "AddType application/javascript .js .mjs .cjs\n"
            . "AddType application/wasm .wasm\n"
            . "</IfModule>\n";
        if (!empty($optimizations['enabled']) && !empty($optimizations['compressAssets'])) {
            // Apache negotiates encoding and Vary itself; no q=0-unsafe rewrite
            // to sidecars, handler changes, or cache rules for private HTML.
            $rules .= "<IfModule mod_deflate.c>\n<IfModule mod_filter.c>\n"
                . "AddOutputFilterByType DEFLATE text/css text/javascript application/javascript application/json image/svg+xml application/xml text/plain\n"
                . "</IfModule>\n</IfModule>\n";
        }
        $written = file_put_contents($theme_dir . '/.htaccess', $rules, LOCK_EX);
        if ($written !== strlen($rules)) {
            throw new RuntimeException('As regras de compatibilidade da publicação não puderam ser gravadas integralmente.');
        }
    }

    /**
     * Validate the Builder-attested module graph before the staging theme can
     * replace the active release. JavaScript grammar is checked by Babel in
     * the Builder; PHP only verifies bounded paths, byte counts and SHA-256,
     * avoiding a second heuristic parser that could reject valid regex syntax.
     *
     * Version 1 and projects without a Builder manifest are valid pass-through
     * sites. Native local ESM is a browser feature, not evidence of an
     * incomplete build, and must be published at its authored path unchanged.
     *
     * @param array<int,string> $html_files
     */
    private function assert_coded_build_integrity(string $project_root, array $html_files): void {
        $root = realpath($project_root);
        if ($root === false || !is_dir($root)) return;
        $manifest_path = $root . '/.incode/coded-build.json';
        $manifest_exists = is_file($manifest_path);
        $build_references = [];
        foreach ($html_files as $html_file) {
            $html = is_file($html_file) ? (string) file_get_contents($html_file) : '';
            if (
                $html === ''
                || !preg_match_all('~<script\b[^>]*(?:/>|>[\s\S]*?</script\s*>)~i', $html, $script_blocks)
            ) {
                continue;
            }
            foreach ($script_blocks[0] as $script_block) {
                if (!preg_match('~^<script\b[^>]*>~i', $script_block, $opening)) continue;
                $script = $opening[0];
                if (!preg_match('~\bsrc\s*=\s*(["\'])(.*?)\1~is', $script, $source_match)) continue;
                $source = html_entity_decode(trim((string) $source_match[2]), ENT_QUOTES | ENT_HTML5, 'UTF-8');
                if ($source === '' || preg_match('~^(?:[a-z][a-z0-9+.-]*:|//|#)~i', $source)) continue;
                $clean = rawurldecode((string) (preg_split('/[?#]/', $source, 2)[0] ?? ''));
                $normalized = str_replace('\\', '/', $clean);
                if (preg_match('~(?:^|/)kodety-build/~i', ltrim($normalized, '/'))) {
                    $build_references[] = [$html_file, $normalized];
                }
            }
        }
        $build_root = realpath(rtrim($project_root, '/\\') . '/kodety-build');
        if ($build_root === false || !is_dir($build_root)) {
            if ($manifest_exists || $build_references) {
                throw new RuntimeException('O build JavaScript está ausente ou incompleto. A versão anterior continua ativa.');
            }
            return;
        }
        if (!str_starts_with($build_root, rtrim($root, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR)) {
            throw new RuntimeException('O build JavaScript aponta para fora do projeto. A versão anterior continua ativa.');
        }

        $normalize_path = static function (mixed $candidate): string {
            if (!is_string($candidate) || $candidate === '' || strlen($candidate) > 2048) return '';
            if (
                str_contains($candidate, "\0")
                || str_contains($candidate, '\\')
                || str_starts_with($candidate, '/')
            ) return '';
            $parts = explode('/', $candidate);
            if (
                !$parts
                || $parts[0] !== 'kodety-build'
                || count(array_filter($parts, static fn(string $part): bool => $part === '' || $part === '.' || $part === '..')) > 0
                || !preg_match('/\.(?:m?js|cjs)$/i', $candidate)
            ) return '';
            return implode('/', $parts);
        };

        $manifest = null;
        if ($manifest_exists) {
            $manifest_size = filesize($manifest_path);
            if ($manifest_size === false || $manifest_size > 16 * MB_IN_BYTES) {
                throw new RuntimeException('O manifesto do build JavaScript excede o limite seguro. A versão anterior continua ativa.');
            }
            $manifest = json_decode((string) file_get_contents($manifest_path), true);
            if (
                !is_array($manifest)
                || !is_int($manifest['version'] ?? null)
                || !in_array($manifest['version'], [1, 2], true)
            ) {
                throw new RuntimeException('O manifesto do build JavaScript está corrompido. A versão anterior continua ativa.');
            }
        }

        $attested_modules = [];
        $attested_entrypoints = [];
        $manifest_v2 = ($manifest['version'] ?? 0) === 2;
        if ($manifest_v2) {
            $modules = $manifest['modules'] ?? null;
            $entrypoints = $manifest['entrypoints'] ?? null;
            if (
                !is_array($modules)
                || !is_array($entrypoints)
                || count($modules) > 10_000
                || count($entrypoints) > 1_000
            ) {
                throw new RuntimeException('O manifesto do build JavaScript é inválido ou excessivo. A versão anterior continua ativa.');
            }
            $total_bytes = 0;
            $dependencies = [];
            foreach ($modules as $raw_path => $record) {
                $path = $normalize_path($raw_path);
                if ($path === '' || !is_array($record)) {
                    throw new RuntimeException('O manifesto do build JavaScript contém um caminho inválido. A versão anterior continua ativa.');
                }
                $expected_bytes = $record['bytes'] ?? null;
                $expected_hash = strtolower((string) ($record['sha256'] ?? ''));
                $raw_dependencies = $record['dependencies'] ?? null;
                if (
                    !is_int($expected_bytes)
                    || $expected_bytes < 0
                    || $expected_bytes > 32 * MB_IN_BYTES
                    || !preg_match('/^[a-f0-9]{64}$/', $expected_hash)
                    || !is_array($raw_dependencies)
                    || count($raw_dependencies) > 10_000
                ) {
                    throw new RuntimeException('O manifesto do build JavaScript contém metadados inválidos. A versão anterior continua ativa.');
                }
                $total_bytes += $expected_bytes;
                if ($total_bytes > 128 * MB_IN_BYTES) {
                    throw new RuntimeException('O build JavaScript excede o limite seguro de publicação. A versão anterior continua ativa.');
                }
                $resolved = realpath($root . '/' . $path);
                if (
                    $resolved === false
                    || !is_file($resolved)
                    || is_link($root . '/' . $path)
                    || !str_starts_with($resolved, rtrim($build_root, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR)
                ) {
                    throw new RuntimeException('O build JavaScript está incompleto. A versão anterior continua ativa.');
                }
                $actual_bytes = filesize($resolved);
                $actual_hash = hash_file('sha256', $resolved);
                if (
                    $actual_bytes !== $expected_bytes
                    || !is_string($actual_hash)
                    || !hash_equals($expected_hash, $actual_hash)
                ) {
                    throw new RuntimeException('O build JavaScript foi corrompido ou truncado. A versão anterior continua ativa.');
                }
                $attested_modules[$path] = true;
                $dependencies[$path] = $raw_dependencies;
            }
            $physical_modules = 0;
            $iterator = new RecursiveIteratorIterator(
                new RecursiveDirectoryIterator($build_root, FilesystemIterator::SKIP_DOTS)
            );
            foreach ($iterator as $file) {
                if (!$file->isFile() || !in_array(strtolower($file->getExtension()), ['js', 'mjs', 'cjs'], true)) continue;
                $physical_modules++;
                if ($physical_modules > 10_000) {
                    throw new RuntimeException('O build JavaScript excede o limite seguro de arquivos. A versão anterior continua ativa.');
                }
                $relative = ltrim(str_replace('\\', '/', substr($file->getPathname(), strlen($root))), '/');
                if (!isset($attested_modules[$relative])) {
                    throw new RuntimeException('O build JavaScript contém um módulo sem atestação. A versão anterior continua ativa.');
                }
            }
            if ($physical_modules !== count($attested_modules)) {
                throw new RuntimeException('O manifesto e os módulos JavaScript divergem. A versão anterior continua ativa.');
            }
            foreach ($dependencies as $raw_dependencies) {
                foreach ($raw_dependencies as $raw_dependency) {
                    $dependency = $normalize_path($raw_dependency);
                    if ($dependency === '' || !isset($attested_modules[$dependency])) {
                        throw new RuntimeException('O grafo de imports do build JavaScript está incompleto. A versão anterior continua ativa.');
                    }
                }
            }
            foreach ($entrypoints as $raw_entrypoint) {
                $entrypoint = $normalize_path($raw_entrypoint);
                if ($entrypoint === '' || !isset($attested_modules[$entrypoint])) {
                    throw new RuntimeException('O manifesto referencia uma entrada JavaScript inválida. A versão anterior continua ativa.');
                }
                $attested_entrypoints[$entrypoint] = true;
            }
        }

        foreach ($build_references as [$html_file, $normalized]) {
            $candidate = str_starts_with($normalized, '/')
                ? $root . '/' . ltrim($normalized, '/')
                : dirname($html_file) . '/' . $normalized;
            $resolved = realpath($candidate);
            if (
                $resolved === false
                || !is_file($resolved)
                || !str_starts_with($resolved, rtrim($build_root, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR)
            ) {
                throw new RuntimeException(
                    'O build JavaScript está incompleto: um módulo referenciado pela página não existe. A versão anterior continua ativa.'
                );
            }
            if ($manifest_v2) {
                $relative = ltrim(str_replace('\\', '/', substr($resolved, strlen($root))), '/');
                if (!isset($attested_entrypoints[$relative])) {
                    throw new RuntimeException('A página referencia uma entrada JavaScript não atestada. A versão anterior continua ativa.');
                }
            }
        }
    }

    /**
     * The static root is copied to the site root at build time, so a page
     * authored there is served at `/cases`, never at `/public/cases`. Mirrors
     * projectPublicDirectoryNames() in lib/html-editor/coded-project.ts, which
     * already publishes root aliases for these folders: `public/` always
     * counts, plus whatever `publicDir` a vite.config declares literally.
     * Returned relative to the web root, so callers can strip both in sequence.
     *
     * @return array<int,string>
     */
    private function project_static_roots(string $project_root, string $web_root): array {
        $base = rtrim($project_root . ($web_root === '' ? '' : '/' . $web_root), '/');
        $names = ['public'];
        foreach (['js', 'mjs', 'ts', 'mts'] as $extension) {
            $config = $base . '/vite.config.' . $extension;
            if (!is_file($config)) continue;
            if (!preg_match('/\bpublicDir\s*:\s*([\'"`])((?:\\\\.|(?!\1)[^\\\\])*)\1/', (string) file_get_contents($config), $match)) continue;
            $declared = trim(str_replace('\\', '/', $match[2]), '/');
            if ($declared !== '' && $declared !== '.') $names[] = $declared;
        }
        return array_values(array_filter($names, static fn(string $name): bool => is_dir($base . '/' . $name)));
    }

    private function resolve_main_html(string $project_root, array $html_files): string {
        $metadata_path = $project_root . '/.incode/project.json';
        if (is_file($metadata_path)) {
            $metadata = json_decode((string) file_get_contents($metadata_path), true);
            $declared = is_array($metadata) ? ltrim(str_replace('\\', '/', (string) ($metadata['mainHtmlPath'] ?? '')), '/') : '';
            $candidate = $declared !== '' ? realpath($project_root . '/' . $declared) : false;
            $root = realpath($project_root);
            if ($candidate && $root && str_starts_with($candidate, $root . DIRECTORY_SEPARATOR) && is_file($candidate) && preg_match('/\.html?$/i', $candidate)) {
                return $declared;
            }
        }
        $relative = array_map(
            static fn(string $path): string => ltrim(str_replace('\\', '/', substr($path, strlen($project_root))), '/'),
            $html_files
        );
        $indexes = array_values(array_filter($relative, static fn(string $path): bool => (bool) preg_match('~(^|/)index\.html?$~i', $path)));
        $candidates = $indexes ?: $relative;
        usort($candidates, static fn(string $a, string $b): int => substr_count($a, '/') <=> substr_count($b, '/') ?: strlen($a) <=> strlen($b));
        if (!$candidates) throw new RuntimeException('Não foi possível determinar a página inicial do projeto.');
        return $candidates[0];
    }

    /**
     * Page publication is backwards compatible: only an explicit `draft`
     * entry is private. The home page is always required to be active so a
     * malformed or hand-edited project cannot publish a site without `/`.
     *
     * @return array<string,true>
     */
    private function project_draft_page_paths(string $project_root): array {
        $metadata_path = rtrim($project_root, '/\\') . '/.incode/project.json';
        if (!is_file($metadata_path) || is_link($metadata_path)) return [];
        $metadata = json_decode((string) file_get_contents($metadata_path), true);
        if (!is_array($metadata)) return [];
        $statuses = is_array($metadata['pageStatuses'] ?? null) ? $metadata['pageStatuses'] : [];
        $drafts = [];
        foreach ($statuses as $raw_path => $status) {
            if ($status !== 'draft' || !is_string($raw_path)) continue;
            $path = ltrim(str_replace('\\', '/', trim($raw_path)), '/');
            if (
                $path === ''
                || strlen($path) > 1024
                || str_contains($path, '../')
                || str_contains($path, "\0")
                || str_starts_with($path, '.')
                || !preg_match('/\.html?$/i', $path)
            ) continue;
            $candidate = realpath(rtrim($project_root, '/\\') . '/' . $path);
            $root = realpath($project_root);
            if (!$candidate || !$root || !is_file($candidate) || !str_starts_with($candidate, $root . DIRECTORY_SEPARATOR)) continue;
            $drafts[$path] = true;
        }
        $home = ltrim(str_replace('\\', '/', trim((string) ($metadata['homeHtmlPath'] ?? $metadata['mainHtmlPath'] ?? ''))), '/');
        if ($home !== '' && isset($drafts[$home])) {
            throw new RuntimeException('A página inicial está marcada como Draft. Ative-a ou defina outra página inicial antes de publicar.');
        }
        return $drafts;
    }

    private function find_html_files(string $root): array {
        $files = [];
        $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root, FilesystemIterator::SKIP_DOTS));
        foreach ($iterator as $file) {
            if (!$file->isFile() || !preg_match('/\.html?$/i', $file->getFilename())) continue;
            $relative = ltrim(str_replace('\\', '/', substr($file->getPathname(), strlen(rtrim($root, '/\\')))), '/');
            // Experiment variants and all other editor metadata are private
            // implementation details, never ordinary public pages.
            if (str_starts_with($relative, '.incode/') || str_contains($relative, '/.incode/')) continue;
            $files[] = $file->getPathname();
        }
        sort($files);
        return $files;
    }

    /** Preserve JavaScript/CSS raw-text payloads around DOMDocument saves. */
    private function save_html_preserving_raw_text(DOMDocument $document): string|false {
        $raw_text = [];
        try {
            $nonce = bin2hex(random_bytes(16));
        } catch (Throwable) {
            $nonce = hash('sha256', uniqid('kodety-raw-text-', true));
        }
        $nodes = iterator_to_array((new DOMXPath($document))->query('//script | //style') ?: []);
        foreach ($nodes as $index => $node) {
            if (!$node instanceof DOMElement) continue;
            $payload = $node->textContent;
            $token = '__KODETY_RAW_TEXT_' . $nonce . '_' . $index . '__';
            while (str_contains($payload, $token)) $token .= '_';
            $raw_text[$token] = $payload;
            while ($node->firstChild) $node->removeChild($node->firstChild);
            $node->appendChild($document->createTextNode($token));
        }
        $html = $document->saveHTML();
        return is_string($html) && $raw_text ? strtr($html, $raw_text) : $html;
    }

    /**
     * Replace complete editor-materialized Custom Code blocks with inert DOM
     * placeholders. The marker token intentionally remains private to the
     * generated document and is restored byte-for-byte after optimization.
     *
     * @return array{0:string,1:array<string,string>}
     */
    private function protect_materialized_custom_code_blocks(string $html): array {
        if (!str_contains($html, 'kodety-custom-code:start')) return [$html, []];
        try {
            $nonce = bin2hex(random_bytes(16));
        } catch (Throwable) {
            $nonce = hash('sha256', uniqid('kodety-custom-code-', true));
        }
        $source = $html;
        $blocks = [];
        $protected = preg_replace_callback(
            '~<!--\s*kodety-custom-code:start\s+([^\s]+)\s*-->([\s\S]*?)<!--\s*kodety-custom-code:end\s+\1\s*-->~iu',
            static function (array $match) use (&$blocks, $nonce, $source): string {
                $token = '__KODETY_CUSTOM_CODE_BLOCK_' . $nonce . '_' . count($blocks) . '__';
                while (str_contains($source, $token) || isset($blocks[$token])) $token .= '_';
                $blocks[$token] = $match[0];
                return '<template data-kdy-custom-code-placeholder="' . $token . '"></template>';
            },
            $html
        );
        return [is_string($protected) ? $protected : $html, $blocks];
    }

    /** @param array<string,string> $blocks */
    private function restore_materialized_custom_code_blocks(string $html, array $blocks): string {
        foreach ($blocks as $token => $block) {
            $quoted = preg_quote($token, '~');
            $restored = preg_replace_callback(
                '~<template\b(?=[^>]*\bdata-kdy-custom-code-placeholder=(["\'])' . $quoted . '\1)[^>]*(?:>\s*</template\s*>|/>)~i',
                static fn(): string => $block,
                $html,
                1
            );
            if (is_string($restored)) $html = $restored;
        }
        return $html;
    }

    /**
     * Protect script/style payloads before DOM parsing or asset synchronization
     * while keeping their tag attributes visible to those transforms.
     *
     * @return array{0:string,1:array<string,string>}
     */
    private function protect_html_raw_text_payloads(string $html): array {
        if (!preg_match('~<(?:script|style)\b~i', $html)) return [$html, []];
        try {
            $nonce = bin2hex(random_bytes(16));
        } catch (Throwable) {
            $nonce = hash('sha256', uniqid('kodety-asset-raw-text-', true));
        }
        $source = $html;
        $payloads = [];
        $protected = preg_replace_callback(
            '~(<(script|style)\b[^>]*>)([\s\S]*?)(</\2\s*>)~i',
            static function (array $match) use (&$payloads, $nonce, $source): string {
                $token = '__KODETY_ASSET_RAW_TEXT_' . $nonce . '_' . count($payloads) . '__';
                while (str_contains($source, $token) || isset($payloads[$token])) $token .= '_';
                $payloads[$token] = $match[3];
                return $match[1] . $token . $match[4];
            },
            $html
        );
        return [is_string($protected) ? $protected : $html, $payloads];
    }

    /** @param array<string,string> $payloads */
    private function restore_html_raw_text_payloads(string $html, array $payloads): string {
        return $payloads ? strtr($html, $payloads) : $html;
    }

    public function maybe_sync_project_pages(): void {
        if (is_multisite()) return;
        if (!current_user_can('edit_pages')) return;
        $release = (string) get_option('kodety_current_release', '');
        if (
            $release === ''
            || (
                get_option('kodety_pages_synced_release') === $release
                && get_option(self::PAGES_SYNC_NOTIFIED_OPTION) === $release
            )
        ) return;
        // Never reconcile a complete release inside wp-admin. A project may
        // legitimately contain thousands of pages; tying that work to every
        // administrative request makes one timeout/OOM permanently lock the
        // dashboard while the front-end Builder continues to work.
        if (!$this->schedule_publish_sync_retry($release, 1)) {
            $this->record_publish_sync_error($release, 'O WordPress não conseguiu agendar a sincronização das páginas.');
        }
    }

    private function theme_runtime_source_digest(): string {
        $material = '';
        foreach (self::theme_runtime_sources() as $file => $path) {
            $content = is_file($path) ? file_get_contents($path) : false;
            if (!is_string($content)) return '';
            $material .= $file . "\0" . strlen($content) . "\0" . hash('sha256', $content) . "\0";
        }
        return hash('sha256', $material);
    }

    /** Parse trusted runtime PHP without executing it. A broken runtime source
     * must never replace the active theme and make both wp-admin and the public
     * site unavailable. */
    private function assert_valid_theme_runtime_source(string $file, string $content): void {
        if (!str_ends_with(strtolower($file), '.php')) return;
        if (!str_starts_with(ltrim($content), '<?php')) {
            throw new RuntimeException('O runtime PHP ' . $file . ' não possui uma abertura PHP válida.');
        }
        try {
            token_get_all($content, TOKEN_PARSE);
        } catch (ParseError $error) {
            throw new RuntimeException(
                'O runtime PHP ' . $file . ' contém erro de sintaxe: ' . $error->getMessage(),
                0,
                $error
            );
        }
    }

    /** A cheap stat signature detects accidental/manual edits before WordPress
     * includes functions.php. Hash validation remains inside the transactional
     * repair, so the common request path avoids reading the complete quartet. */
    private function theme_runtime_file_state(string $theme_dir): array {
        $theme_dir = rtrim($theme_dir, '/\\');
        $state = [];
        foreach (self::theme_runtime_files() as $file) {
            $path = $theme_dir . '/' . $file;
            clearstatcache(true, $path);
            $state[$file] = is_file($path)
                ? [
                    'size' => (int) filesize($path),
                    'mtime' => (int) filemtime($path),
                ]
                : ['size' => -1, 'mtime' => -1];
        }
        return $state;
    }

    public function maybe_refresh_active_theme_runtime(bool $force = false): void {
        if (is_multisite()) return;
        if (wp_get_theme()->get_stylesheet() !== 'kodety-generated') return;
        $theme = wp_get_theme('kodety-generated');
        if (!$theme->exists()) return;

        $theme_dir = rtrim($theme->get_stylesheet_directory(), '/\\');
        $version = defined('KODETY_VERSION') ? (string) KODETY_VERSION : 'unknown';
        $theme_identity = hash('sha256', str_replace('\\', '/', $theme_dir));
        $source_digest = $this->theme_runtime_source_digest();
        $ack = get_option(self::THEME_RUNTIME_ACK_OPTION, []);
        $active_file_state = $this->theme_runtime_file_state($theme_dir);
        if (
            !$force
            && $source_digest !== ''
            && is_array($ack)
            && hash_equals($version, (string) ($ack['version'] ?? ''))
            && hash_equals($theme_identity, (string) ($ack['theme'] ?? ''))
            && hash_equals($source_digest, (string) ($ack['digest'] ?? ''))
            && is_array($ack['files'] ?? null)
            && $ack['files'] === $active_file_state
        ) {
            return;
        }

        try {
            $this->refresh_theme_runtime($theme_dir);
        } catch (Throwable $error) {
            // Never take wp-admin, the Builder, or the public site down because
            // a host temporarily denied the repair. The verified old quartet
            // remains in place and the stale ACK retries on the next request.
            error_log('[Onun Kodety] Atualização transacional do runtime do tema adiada: ' . $error->getMessage());
        }
    }

    public function maybe_sync_project_assets(): void {
        if (is_multisite()) return;
        if (!current_user_can('upload_files')) return;
        $release = (string) get_option('kodety_current_release', '');
        if ($release === '' || get_option('kodety_assets_synced_release') === $release) return;
        // wp-admin is a control surface, not a media worker. Scheduling keeps
        // it available even when image decoding exceeds a host's request
        // budget; the release is already serving its assets from the theme.
        if (!$this->schedule_publish_sync_retry($release, 1)) {
            $this->record_publish_sync_error($release, 'O WordPress não conseguiu agendar a sincronização dos assets.');
        }
    }

    /**
     * A release is already serving traffic when this worker runs. Reconcile only
     * stale native ACKs for that exact release and use bounded exponential
     * backoff. Status polling may execute the same worker without a watchdog;
     * the fifth failed attempt is terminal and never wraps back to attempt one.
     */
    public function retry_publish_sync(
        string $release,
        int $attempt = 1,
        bool $schedule_watchdog = true
    ): void {
        $release = $this->release_id($release);
        $current_release = (string) get_option('kodety_current_release', '');
        if ($release === '') return;
        if ($current_release === '' || !hash_equals($current_release, $release)) {
            $this->clear_publish_sync_retries($release);
            return;
        }

        $attempt = max(1, min(self::PUBLISH_SYNC_RETRY_MAX_ATTEMPTS, $attempt));
        $previous_error = $this->publish_sync_error($release);
        if (!empty($previous_error['terminal'])) {
            $this->clear_publish_sync_retries($release);
            return;
        }
        $previous_attempt = max(0, (int) ($previous_error['attempt'] ?? 0));
        // A status poll can overtake an event already persisted by WP-Cron.
        // Ignore that stale payload instead of consuming the same attempt twice.
        if ($previous_attempt >= $attempt) return;

        // WordPress removes a single cron event before invoking its callback.
        // Pre-schedule only a later bounded attempt. The current attempt still
        // runs if scheduling fails; an authenticated poll can then resume it.
        if (
            $schedule_watchdog
            && $attempt < self::PUBLISH_SYNC_RETRY_MAX_ATTEMPTS
            && !$this->schedule_publish_sync_retry($release, $attempt + 1)
        ) {
            $this->record_publish_sync_error(
                $release,
                'O WordPress não conseguiu agendar o próximo worker de sincronização em segundo plano.',
                $previous_attempt
            );
        }

        $pending = true;
        try {
            $pending = $this->with_native_sync_lock(function () use ($release, $attempt): bool {
                $current_release = (string) get_option('kodety_current_release', '');
                if ($current_release === '' || !hash_equals($current_release, $release)) return false;

                $pending = false;
                if ((string) get_option('kodety_assets_synced_release', '') !== $release) {
                    try {
                        $this->sync_project_assets($release);
                    } catch (Throwable $error) {
                        $pending = true;
                        $this->record_publish_sync_error(
                            $release,
                            $error->getMessage(),
                            $attempt,
                            $attempt >= self::PUBLISH_SYNC_RETRY_MAX_ATTEMPTS
                        );
                        error_log('[Onun Kodety] Retry assíncrono de assets falhou para ' . $release . ': ' . $error->getMessage());
                    }
                }
                if ((string) get_option('kodety_pages_synced_release', '') !== $release) {
                    try {
                        $this->sync_project_pages($release);
                    } catch (Throwable $error) {
                        $pending = true;
                        $this->record_publish_sync_error(
                            $release,
                            $error->getMessage(),
                            $attempt,
                            $attempt >= self::PUBLISH_SYNC_RETRY_MAX_ATTEMPTS
                        );
                        error_log('[Onun Kodety] Retry assíncrono de páginas falhou para ' . $release . ': ' . $error->getMessage());
                    }
                }
                if (
                    (string) get_option('kodety_pages_synced_release', '') === $release
                    && (string) get_option(self::PAGES_SYNC_NOTIFIED_OPTION, '') !== $release
                ) {
                    try {
                        $this->notify_pages_sync_completed($release);
                    } catch (Throwable $error) {
                        $pending = true;
                        $this->record_publish_sync_error(
                            $release,
                            $error->getMessage(),
                            $attempt,
                            $attempt >= self::PUBLISH_SYNC_RETRY_MAX_ATTEMPTS
                        );
                        error_log('[Onun Kodety] Hook de páginas sincronizadas falhou para ' . $release . ': ' . $error->getMessage());
                    }
                }

                if ((string) get_option('kodety_current_release', '') !== $release) return false;
                return $pending
                    || (string) get_option('kodety_assets_synced_release', '') !== $release
                    || (string) get_option('kodety_pages_synced_release', '') !== $release
                    || (string) get_option(self::PAGES_SYNC_NOTIFIED_OPTION, '') !== $release;
            });
        } catch (Throwable $error) {
            if ($error->getMessage() === 'Outra sincronização nativa ainda está em andamento.') {
                $this->record_publish_sync_error($release, $error->getMessage(), $previous_attempt);
                return;
            }
            $pending = true;
            $this->record_publish_sync_error(
                $release,
                $error->getMessage(),
                $attempt,
                $attempt >= self::PUBLISH_SYNC_RETRY_MAX_ATTEMPTS
            );
            error_log('[Onun Kodety] Worker nativo adiado para ' . $release . ': ' . $error->getMessage());
        }
        if ((string) get_option('kodety_current_release', '') !== $release) {
            $this->clear_publish_sync_retries($release);
            return;
        }
        if (!$pending) {
            $this->clear_publish_sync_retries($release);
            $this->clear_publish_sync_error($release);
        } elseif ($attempt >= self::PUBLISH_SYNC_RETRY_MAX_ATTEMPTS) {
            $latest_error = $this->publish_sync_error($release);
            $message = trim((string) ($latest_error['message'] ?? ''));
            if ($message === '') {
                $message = 'A sincronização nativa não confirmou todos os ACKs após as tentativas permitidas.';
            }
            $this->record_publish_sync_error($release, $message, $attempt, true);
            $this->clear_publish_sync_retries($release);
            error_log('[Onun Kodety] Sync nativo da release ' . $release . ' terminou com falha após retries limitados.');
        } else {
            $latest_error = $this->publish_sync_error($release);
            if ((int) ($latest_error['attempt'] ?? 0) < $attempt) {
                $this->record_publish_sync_error(
                    $release,
                    'A sincronização nativa não confirmou todos os ACKs.',
                    $attempt
                );
            }
        }
    }

    private function notify_pages_sync_completed(string $release): void {
        if (
            $release === ''
            || (string) get_option('kodety_current_release', '') !== $release
            || (string) get_option('kodety_pages_synced_release', '') !== $release
            || (string) get_option(self::PAGES_SYNC_NOTIFIED_OPTION, '') === $release
        ) {
            return;
        }
        do_action('kodety_pages_sync_completed', $release);
        update_option(self::PAGES_SYNC_NOTIFIED_OPTION, $release, false);
        if ((string) get_option(self::PAGES_SYNC_NOTIFIED_OPTION, '') !== $release) {
            throw new RuntimeException('O WordPress não confirmou o hook final das páginas nativas.');
        }
    }

    private function schedule_publish_sync_retry(string $release, int $attempt, ?int $delay_override = null): bool {
        if (!function_exists('wp_schedule_single_event')) return false;
        $release = $this->release_id($release);
        if ($release === '') return false;
        // A terminal release is intentionally inert until a new publication.
        // Treat it as already handled so admin_init cannot recreate attempt 1
        // on every request after the bounded worker chain was exhausted.
        if (!empty($this->publish_sync_error($release)['terminal'])) return true;
        $attempt = max(1, min(self::PUBLISH_SYNC_RETRY_MAX_ATTEMPTS, $attempt));
        $args = [$release, $attempt];
        if (function_exists('wp_next_scheduled')) {
            // One release owns one worker chain. An admin request arriving
            // during exponential backoff must not add a fresh attempt-1 job.
            for ($scheduled_attempt = 1; $scheduled_attempt <= self::PUBLISH_SYNC_RETRY_MAX_ATTEMPTS; $scheduled_attempt++) {
                if (wp_next_scheduled(self::PUBLISH_SYNC_RETRY_HOOK, [$release, $scheduled_attempt])) return true;
            }
        }
        $delay = $delay_override !== null
            ? max(0, min(DAY_IN_SECONDS, $delay_override))
            : ($attempt === 1
                ? 0
                : min(60 * 60, MINUTE_IN_SECONDS * (2 ** max(0, $attempt - 2))));
        $scheduled = wp_schedule_single_event(
            time() + $delay,
            self::PUBLISH_SYNC_RETRY_HOOK,
            $args,
            true
        );
        if (is_wp_error($scheduled) || $scheduled === false) {
            $message = is_wp_error($scheduled) ? $scheduled->get_error_message() : 'retorno falso';
            error_log('[Onun Kodety] Não foi possível agendar retry de publicação para ' . $release . ': ' . $message);
            return false;
        }
        if ($delay === 0) $this->publish_sync_cron_dispatch_pending = true;
        return true;
    }

    private function clear_publish_sync_retries(string $release): void {
        if (!function_exists('wp_clear_scheduled_hook')) return;
        for ($attempt = 1; $attempt <= self::PUBLISH_SYNC_RETRY_MAX_ATTEMPTS; $attempt++) {
            wp_clear_scheduled_hook(self::PUBLISH_SYNC_RETRY_HOOK, [$release, $attempt]);
        }
    }

    private function clear_publish_sync_retry_attempt(string $release, int $attempt): void {
        if (!function_exists('wp_clear_scheduled_hook')) return;
        wp_clear_scheduled_hook(self::PUBLISH_SYNC_RETRY_HOOK, [
            $release,
            max(1, min(self::PUBLISH_SYNC_RETRY_MAX_ATTEMPTS, $attempt)),
        ]);
    }

    private function record_publish_sync_error(
        string $release,
        string $message,
        int $attempt = 0,
        bool $terminal = false
    ): void {
        $existing = $this->publish_sync_error($release);
        if ($attempt <= 0 && $existing !== []) {
            $attempt = max(0, (int) ($existing['attempt'] ?? 0));
            $terminal = $terminal || !empty($existing['terminal']);
        }
        update_option(self::PUBLISH_SYNC_ERROR_OPTION, [
            'release' => $release,
            'message' => trim($message),
            'at' => time(),
            'attempt' => max(0, min(self::PUBLISH_SYNC_RETRY_MAX_ATTEMPTS, $attempt)),
            'terminal' => $terminal,
        ], false);
    }

    /** @return array<string,mixed> */
    private function publish_sync_error(string $release): array {
        $error = get_option(self::PUBLISH_SYNC_ERROR_OPTION, []);
        return is_array($error) && (string) ($error['release'] ?? '') === $release
            ? $error
            : [];
    }

    private function publish_sync_requires_poll_resume(string $release): bool {
        if (
            !function_exists('wp_schedule_single_event')
            || !function_exists('wp_next_scheduled')
            || !function_exists('spawn_cron')
            || (defined('DISABLE_WP_CRON') && DISABLE_WP_CRON)
        ) {
            return true;
        }
        for ($attempt = 1; $attempt <= self::PUBLISH_SYNC_RETRY_MAX_ATTEMPTS; $attempt++) {
            if (wp_next_scheduled(self::PUBLISH_SYNC_RETRY_HOOK, [$release, $attempt])) return false;
        }
        return true;
    }

    private function clear_publish_sync_error(string $release): void {
        $error = get_option(self::PUBLISH_SYNC_ERROR_OPTION, []);
        if (is_array($error) && (string) ($error['release'] ?? '') === $release) {
            update_option(self::PUBLISH_SYNC_ERROR_OPTION, [], false);
        }
    }

    /** Dispatch the immediately-due first retry without waiting for another
     * wp-admin request. Hosts with external cron keep their normal policy. */
    public function dispatch_publish_sync_cron(): void {
        if (!$this->publish_sync_cron_dispatch_pending) return;
        $this->publish_sync_cron_dispatch_pending = false;
        if ((defined('DISABLE_WP_CRON') && DISABLE_WP_CRON) || !function_exists('spawn_cron')) return;
        spawn_cron(microtime(true));
    }

    public function sync_project_assets(?string $expected_release = null): array {
        if (is_multisite()) return [];
        $release = $this->active_release_for_sync($expected_release);
        $theme = wp_get_theme('kodety-generated');
        $theme_dir = $theme->exists() ? $theme->get_stylesheet_directory() : '';
        $site_root = $theme_dir ? $theme_dir . '/site' : '';
        return $this->sync_assets_from_root($site_root, true, true, $release);
    }

    private function active_release_for_sync(?string $expected_release = null): string {
        $release = $this->release_id(get_option('kodety_current_release', ''));
        $expected_release = $expected_release === null ? '' : $this->release_id($expected_release);
        if ($release === '') throw new RuntimeException('Nenhuma release ativa está disponível para sincronização.');
        if ($expected_release !== '' && !hash_equals($release, $expected_release)) {
            throw new RuntimeException('A release ativa mudou durante a sincronização nativa.');
        }
        return $release;
    }

    /** Import binary project files into the WordPress Media Library. The
     * workspace keeps its relative source paths for editing/export; only the
     * published theme has references rewritten to attachment URLs. */
    private function sync_assets_from_root(
        string $site_root,
        bool $rewrite_references,
        bool $cleanup_obsolete,
        string $release
    ): array {
        if (!$site_root || !is_dir($site_root)) {
            throw new RuntimeException('A raiz publicada do projeto não está disponível.');
        }
        $uploads = wp_upload_dir();
        if (!empty($uploads['error']) || empty($uploads['basedir']) || empty($uploads['baseurl'])) {
            throw new RuntimeException('O diretório de uploads do WordPress não está disponível.');
        }

        $extensions = ['jpg','jpeg','png','gif','webp','avif','svg','mp4','webm','mov','mp3','wav','ogg','m4a','pdf','woff','woff2','ttf','otf'];
        $assets = [];
        $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($site_root, FilesystemIterator::SKIP_DOTS));
        foreach ($iterator as $file) {
            if (!$file->isFile() || !in_array(strtolower($file->getExtension()), $extensions, true)) continue;
            $relative = ltrim(str_replace('\\', '/', substr($file->getPathname(), strlen($site_root))), '/');
            $assets[$relative] = $file->getPathname();
        }

        $url_map = [];
        $attachment_ids = [];
        $attachment_by_hash = [];
        $paths_by_attachment = [];
        $failures = [];
        foreach ($assets as $relative => $source) {
            $source_hash = md5_file($source) ?: '';
            if ($source_hash === '') {
                $failures[] = $relative . ' (não foi possível ler o arquivo de origem)';
                continue;
            }
            $existing = get_posts([
                'post_type' => 'attachment', 'post_status' => ['inherit', 'trash'], 'posts_per_page' => -1, 'fields' => 'ids',
                'meta_key' => '_kodety_asset_path', 'meta_value' => $relative,
            ]);
            $attachment_id = $source_hash !== '' ? (int) ($attachment_by_hash[$source_hash] ?? 0) : 0;
            if (!$attachment_id) {
                foreach ($existing as $candidate_id) {
                    $candidate_id = (int) $candidate_id;
                    if (get_post_meta($candidate_id, '_kodety_managed', true) !== '1') continue;
                    $candidate_hash = (string) get_post_meta($candidate_id, '_kodety_asset_hash', true);
                    if ($source_hash !== '' && $candidate_hash !== '' && hash_equals($source_hash, $candidate_hash)) {
                        $attachment_id = $candidate_id;
                        break;
                    }
                }
            }
            if (!$attachment_id && $source_hash !== '') {
                $hash_matches = get_posts([
                    'post_type' => 'attachment', 'post_status' => ['inherit', 'trash'], 'posts_per_page' => -1, 'fields' => 'ids',
                    'meta_key' => '_kodety_asset_hash', 'meta_value' => $source_hash,
                ]);
                foreach ($hash_matches as $candidate_id) {
                    $candidate_id = (int) $candidate_id;
                    if (get_post_meta($candidate_id, '_kodety_managed', true) !== '1') continue;
                    $attachment_id = $candidate_id;
                    break;
                }
            }
            $attached_file = $attachment_id ? (string) get_attached_file($attachment_id) : '';
            $previous_metadata = $attachment_id ? wp_get_attachment_metadata($attachment_id) : false;
            $canonical_relative = (string) ($paths_by_attachment[$attachment_id][0] ?? '');
            if ($canonical_relative === '' && $attachment_id) {
                $canonical_relative = (string) get_post_meta($attachment_id, '_kodety_asset_path', true);
            }
            if ($canonical_relative === '') $canonical_relative = $relative;
            $canonical_relative = ltrim(str_replace('\\', '/', $canonical_relative), '/');
            if (
                $canonical_relative === ''
                || str_contains($canonical_relative, '../')
                || str_contains($canonical_relative, "\0")
            ) {
                $canonical_relative = $relative;
            }
            // WordPress' "big image" feature changes get_attached_file() to a
            // generated *-scaled image. Reusing that derivative as our source
            // target made every release create -scaled-scaled chains and redo
            // expensive AVIF/JPEG decoding. Onun Kodety assets instead keep one
            // canonical, content-addressed original in uploads.
            $upload_relative = $this->asset_upload_path($canonical_relative, $source_hash);
            $target = trailingslashit($uploads['basedir']) . $upload_relative;
            $attachment_path_changed = $attachment_id > 0
                && str_replace('\\', '/', $attached_file) !== str_replace('\\', '/', $target);
            $target_directory = dirname($target);
            if (!is_dir($target_directory) && !wp_mkdir_p($target_directory)) {
                $failures[] = $relative . ' (não foi possível preparar o diretório de upload)';
                continue;
            }
            $target_existed = is_file($target);
            $target_hash = is_file($target) ? (md5_file($target) ?: '') : '';
            $asset_changed = !is_file($target) || $source_hash === '' || !hash_equals($source_hash, $target_hash);
            if ($asset_changed && !@copy($source, $target)) {
                $failures[] = $relative . ' (a cópia para uploads falhou)';
                continue;
            }
            $mime = wp_check_filetype(basename($target))['type'] ?: $this->asset_mime_type($target);
            $url = $this->public_upload_asset_url($uploads, $upload_relative);
            if ($url === '') {
                $failures[] = $relative . ' (não foi possível formar uma URL pública segura para o upload)';
                continue;
            }
            $is_new_attachment = !$attachment_id;
            $post = [
                'ID' => $attachment_id, 'post_type' => 'attachment', 'post_status' => 'inherit',
                'post_title' => sanitize_text_field(pathinfo(basename($relative), PATHINFO_FILENAME)),
                'post_mime_type' => $mime, 'guid' => $url,
            ];
            $result = $attachment_id ? wp_update_post($post, true) : wp_insert_attachment($post, $target, 0, true);
            if (is_wp_error($result) || (int) $result <= 0) {
                $detail = is_wp_error($result) ? $result->get_error_message() : 'o WordPress retornou um ID inválido';
                $failures[] = $relative . ' (' . $detail . ')';
                if ($is_new_attachment && !$target_existed && is_file($target)) @unlink($target);
                continue;
            }
            $attachment_id = (int) $result;
            update_attached_file($attachment_id, $target);
            $attached_file_readback = str_replace('\\', '/', (string) get_attached_file($attachment_id));
            $attached_relative_readback = ltrim(str_replace(
                '\\',
                '/',
                (string) get_post_meta($attachment_id, '_wp_attached_file', true)
            ), '/');
            if (
                $attached_file_readback !== str_replace('\\', '/', $target)
                || $attached_relative_readback !== ltrim(str_replace('\\', '/', $upload_relative), '/')
            ) {
                $failures[] = $relative . ' (o arquivo anexado não pôde ser confirmado)';
                if ($is_new_attachment) wp_delete_attachment($attachment_id, true);
                continue;
            }
            $asset_identity = [
                '_kodety_managed' => '1',
                '_kodety_release' => $release,
                '_kodety_asset_hash' => md5_file($target) ?: $source_hash,
            ];
            foreach ($asset_identity as $meta_key => $meta_value) {
                update_post_meta($attachment_id, $meta_key, $meta_value);
            }
            $identity_valid = true;
            foreach ($asset_identity as $meta_key => $meta_value) {
                if ((string) get_post_meta($attachment_id, $meta_key, true) !== $meta_value) {
                    $identity_valid = false;
                    break;
                }
            }
            if (!$identity_valid) {
                $failures[] = $relative . ' (a identidade do anexo não pôde ser confirmada)';
                if ($is_new_attachment) wp_delete_attachment($attachment_id, true);
                continue;
            }
            $metadata_is_current = (string) get_post_meta($attachment_id, '_kodety_asset_metadata_version', true) === '1'
                && $this->managed_asset_metadata_is_current($attachment_id, $target);
            if ($asset_changed || $is_new_attachment || $attachment_path_changed || !$metadata_is_current) {
                $metadata = $this->generate_managed_asset_metadata($attachment_id, $target);
                wp_update_attachment_metadata($attachment_id, $metadata);
                // update_post_meta() legitimately returns false when the value
                // is byte-identical. The readback, not that ambiguous return,
                // is the authoritative success condition.
                if (!$this->managed_asset_metadata_is_current($attachment_id, $target)) {
                    delete_post_meta($attachment_id, '_kodety_asset_metadata_version');
                    $failures[] = $relative . ' (a metadata intrínseca do asset não pôde ser confirmada)';
                    if ($is_new_attachment) wp_delete_attachment($attachment_id, true);
                    continue;
                }
                update_post_meta($attachment_id, '_kodety_asset_metadata_version', '1');
                if ((string) get_post_meta($attachment_id, '_kodety_asset_metadata_version', true) !== '1') {
                    $failures[] = $relative . ' (a versão da metadata não pôde ser confirmada)';
                    if ($is_new_attachment) wp_delete_attachment($attachment_id, true);
                    continue;
                }
                $this->cleanup_managed_asset_derivatives(
                    $attachment_id,
                    $target,
                    $attached_file,
                    is_array($previous_metadata) ? $previous_metadata : [],
                    (string) $uploads['basedir']
                );
            }
            $url_map[$relative] = $url;
            $attachment_ids[] = $attachment_id;
            $paths_by_attachment[$attachment_id][] = $relative;
            if ($source_hash !== '') $attachment_by_hash[$source_hash] = $attachment_id;
        }
        if ($failures) {
            $visible_failures = array_slice($failures, 0, 5);
            if (count($failures) > count($visible_failures)) {
                $visible_failures[] = sprintf('+%d arquivo(s) com falha', count($failures) - count($visible_failures));
            }
            throw new RuntimeException('A sincronização de assets ficou pendente: ' . implode('; ', $visible_failures));
        }
        $attachment_ids = array_values(array_unique(array_map('intval', $attachment_ids)));
        foreach ($paths_by_attachment as $attachment_id => $relative_paths) {
            $relative_paths = array_values(array_unique(array_filter(array_map('strval', $relative_paths))));
            if (!$relative_paths) continue;
            update_post_meta((int) $attachment_id, '_kodety_asset_path', $relative_paths[0]);
            update_post_meta((int) $attachment_id, '_kodety_asset_paths', $relative_paths);
            $stored_primary = (string) get_post_meta((int) $attachment_id, '_kodety_asset_path', true);
            $stored_paths = get_post_meta((int) $attachment_id, '_kodety_asset_paths', true);
            $stored_paths = is_array($stored_paths)
                ? array_values(array_unique(array_filter(array_map('strval', $stored_paths))))
                : [];
            if ($stored_primary !== $relative_paths[0] || $stored_paths !== $relative_paths) {
                $failures[] = $relative_paths[0] . ' (o vínculo entre caminho e anexo não pôde ser confirmado)';
            }
        }
        if ($failures) {
            throw new RuntimeException('A sincronização de assets ficou pendente: ' . implode('; ', array_slice($failures, 0, 5)));
        }
        return $this->with_workspace_lock(function () use (
            $release,
            $rewrite_references,
            $cleanup_obsolete,
            $url_map,
            $attachment_ids
        ): array {
            $this->active_release_for_sync($release);
            $active_theme = wp_get_theme('kodety-generated');
            $active_theme_dir = $active_theme->exists() ? $active_theme->get_stylesheet_directory() : '';
            $active_site_root = $active_theme_dir ? $active_theme_dir . '/site' : '';
            if ($active_site_root === '' || !is_dir($active_site_root)) {
                throw new RuntimeException('A raiz publicada mudou antes do commit dos assets.');
            }

            // Theme references must point to every confirmed attachment before
            // an obsolete native asset can be removed. Re-resolving the active
            // root under the publication lock prevents an old worker from
            // rewriting a theme that replaced its scanned source tree.
            if ($rewrite_references && $url_map) {
                $this->rewrite_theme_asset_references($active_site_root, $url_map);
                // The release was already purged when it first went online, but
                // native asset reconciliation intentionally runs afterwards and
                // can rewrite HTML/CSS in place. Validate the release identity
                // after the verified writes and purge again before ACKing sync.
                // Always purge on a retry too: the previous attempt may have
                // completed the writes and then failed while invalidating cache.
                $this->active_release_for_sync($release);
                $this->purge_published_site_cache();
            }
            $failures = [];
            $kept_files = [];
            foreach ($attachment_ids as $attachment_id) {
                $kept_file = str_replace('\\', '/', (string) get_attached_file((int) $attachment_id));
                if ($kept_file !== '') $kept_files[$kept_file] = true;
            }
            if ($cleanup_obsolete) {
                $managed_attachments = get_posts([
                    // Include leftovers that older builds only moved to Trash. A
                    // trash status does not remove the physical media file.
                    'post_type' => 'attachment', 'post_status' => ['inherit', 'trash'], 'posts_per_page' => -1, 'fields' => 'ids',
                    'meta_key' => '_kodety_managed', 'meta_value' => '1',
                ]);
                foreach ($managed_attachments as $managed_id) {
                    $managed_id = (int) $managed_id;
                    if (in_array($managed_id, $attachment_ids, true)) continue;
                    $obsolete_file = str_replace('\\', '/', (string) get_attached_file($managed_id));
                    if ($obsolete_file !== '' && isset($kept_files[$obsolete_file])) {
                        // Two historical rows may reference one deduplicated file.
                        // Clear the obsolete row's file metadata so core deletion
                        // cannot remove the canonical file retained by another ID.
                        wp_update_attachment_metadata($managed_id, []);
                        update_attached_file($managed_id, '');
                    }
                    if (!wp_delete_attachment($managed_id, true)) {
                        $failures[] = 'anexo #' . $managed_id . ' (a remoção do asset obsoleto falhou)';
                    }
                }
            }
            foreach ($attachment_ids as $attachment_id) {
                $attachment_id = (int) $attachment_id;
                $file = (string) get_attached_file($attachment_id);
                $expected_hash = (string) get_post_meta($attachment_id, '_kodety_asset_hash', true);
                $actual_hash = is_file($file) ? (md5_file($file) ?: '') : '';
                if ($file === '' || $expected_hash === '' || !hash_equals($expected_hash, $actual_hash)) {
                    $failures[] = 'anexo #' . $attachment_id . ' (o arquivo canônico não resistiu à limpeza)';
                }
            }
            if ($failures) {
                throw new RuntimeException('A limpeza de assets ficou pendente: ' . implode('; ', array_slice($failures, 0, 5)));
            }
            $this->active_release_for_sync($release);
            update_option('kodety_assets_synced_release', $release, false);
            if ((string) get_option('kodety_assets_synced_release', '') !== $release) {
                throw new RuntimeException('O WordPress não confirmou o ACK final da sincronização de assets.');
            }
            return $attachment_ids;
        });
    }

    private function asset_upload_path(string $relative, string $hash = ''): string {
        $parts = array_values(array_filter(explode('/', str_replace('\\', '/', $relative)), 'strlen'));
        $parts = array_map(static fn(string $part): string => sanitize_file_name($part), $parts);
        if ($parts && $hash !== '') {
            $filename = array_pop($parts);
            $extension = pathinfo($filename, PATHINFO_EXTENSION);
            $basename = pathinfo($filename, PATHINFO_FILENAME);
            $filename = $basename . '-' . substr($hash, 0, 12) . ($extension !== '' ? '.' . $extension : '');
            $parts[] = $filename;
        }
        return 'kodety/assets/' . implode('/', $parts);
    }

    /** Keep the historical absolute-URL contract used by the published theme,
     * while repairing a same-origin upload_url_path that exposes a filesystem
     * prefix or an HTTP origin behind HTTPS termination. A real external CDN
     * remains untouched. */
    private function public_upload_base_url(array $uploads): string {
        $configured = rtrim(trim((string) ($uploads['baseurl'] ?? '')), '/');
        if ($configured === '') return '';

        $home = rtrim(function_exists('home_url') ? (string) home_url('/') : '', '/');
        $configured_host = strtolower((string) parse_url($configured, PHP_URL_HOST));
        $home_host = strtolower((string) parse_url($home, PHP_URL_HOST));
        $configured_port = (int) (parse_url($configured, PHP_URL_PORT) ?: 0);
        $home_port = (int) (parse_url($home, PHP_URL_PORT) ?: 0);
        if (
            $configured_host !== ''
            && $home_host !== ''
            && (
                !hash_equals($home_host, $configured_host)
                || ($configured_port !== 0 && $home_port !== 0 && $configured_port !== $home_port)
            )
        ) {
            return $configured;
        }

        $path = (string) parse_url($configured, PHP_URL_PATH);
        $basedir = rtrim(str_replace('\\', '/', (string) ($uploads['basedir'] ?? '')), '/');
        $content_directory = defined('WP_CONTENT_DIR')
            ? rtrim(str_replace('\\', '/', (string) WP_CONTENT_DIR), '/')
            : '';
        $content_path = function_exists('content_url')
            ? rtrim((string) parse_url(content_url('/'), PHP_URL_PATH), '/')
            : '';

        if (
            $basedir !== ''
            && $content_directory !== ''
            && ($basedir === $content_directory || str_starts_with($basedir, $content_directory . '/'))
        ) {
            $relative = ltrim(substr($basedir, strlen($content_directory)), '/');
            $path = rtrim($content_path !== '' ? $content_path : '/wp-content', '/')
                . ($relative !== '' ? '/' . $relative : '');
        } else {
            $content_offset = stripos($path, '/wp-content/');
            if ($content_offset !== false) {
                $suffix = substr($path, $content_offset + strlen('/wp-content'));
                $path = rtrim($content_path !== '' ? $content_path : '/wp-content', '/')
                    . '/' . ltrim($suffix, '/');
            }
        }

        $path = '/' . ltrim((string) preg_replace('~/+~', '/', $path), '/');
        $decoded_path = rawurldecode($path);
        if ($path === '/' || str_contains($decoded_path, "\0") || preg_match('~(?:^|/)\.\.(?:/|$)~', $decoded_path)) {
            return '';
        }

        $scheme = strtolower((string) parse_url($home, PHP_URL_SCHEME));
        $host = (string) parse_url($home, PHP_URL_HOST);
        if ($scheme === '' || $host === '') return '';
        if (str_contains($host, ':') && !str_starts_with($host, '[')) $host = '[' . $host . ']';
        $port = (int) (parse_url($home, PHP_URL_PORT) ?: 0);
        $origin = $scheme . '://' . $host . ($port > 0 ? ':' . $port : '');
        return $origin . rtrim($path, '/');
    }

    private function public_upload_asset_url(array $uploads, string $relative): string {
        $base = $this->public_upload_base_url($uploads);
        if ($base === '') return '';
        $segments = array_values(array_filter(explode('/', str_replace('\\', '/', $relative)), 'strlen'));
        if (!$segments || in_array('..', $segments, true)) return '';
        return $base . '/' . implode('/', array_map('rawurlencode', $segments));
    }

    /**
     * Build only the intrinsic attachment metadata for a byte-exact project
     * asset. The static site already owns responsive variants and references
     * the full file. Calling wp_generate_attachment_metadata() would still be
     * allowed to decode, rotate, convert or resize the original, which is both
     * unnecessary here and unsafe for large AVIF/JPEG files on small hosts.
     */
    private function generate_managed_asset_metadata(int $attachment_id, string $file): array {
        $relative = ltrim(str_replace(
            '\\',
            '/',
            (string) get_post_meta($attachment_id, '_wp_attached_file', true)
        ), '/');
        $metadata = [];
        $image_size = function_exists('wp_getimagesize')
            ? wp_getimagesize($file)
            : @getimagesize($file);
        if (is_array($image_size) && isset($image_size[0], $image_size[1])) {
            $metadata['width'] = (int) $image_size[0];
            $metadata['height'] = (int) $image_size[1];
            $metadata['sizes'] = [];
        } else {
            $mime = wp_check_filetype(basename($file))['type'] ?: $this->asset_mime_type($file);
            if (str_starts_with((string) $mime, 'video/') || str_starts_with((string) $mime, 'audio/')) {
                if (!function_exists('wp_read_video_metadata') || !function_exists('wp_read_audio_metadata')) {
                    require_once ABSPATH . 'wp-admin/includes/media.php';
                }
                $media_metadata = str_starts_with((string) $mime, 'video/')
                    ? wp_read_video_metadata($file)
                    : wp_read_audio_metadata($file);
                if (is_array($media_metadata)) {
                    // Embedded cover extraction would create another attachment;
                    // the project already owns every visual asset explicitly.
                    unset($media_metadata['image']);
                    $metadata = $media_metadata;
                }
            }
        }
        $metadata['file'] = $relative;
        $metadata['filesize'] = function_exists('wp_filesize')
            ? (int) wp_filesize($file)
            : (int) @filesize($file);
        return $metadata;
    }

    private function managed_asset_metadata_is_current(int $attachment_id, string $canonical_file): bool {
        if (str_replace('\\', '/', (string) get_attached_file($attachment_id)) !== str_replace('\\', '/', $canonical_file)) {
            return false;
        }
        $relative = ltrim(str_replace(
            '\\',
            '/',
            (string) get_post_meta($attachment_id, '_wp_attached_file', true)
        ), '/');
        $metadata = wp_get_attachment_metadata($attachment_id);
        if (!is_array($metadata) || (string) ($metadata['file'] ?? '') !== $relative) return false;
        return !isset($metadata['sizes']) || (is_array($metadata['sizes']) && $metadata['sizes'] === []);
    }

    /** Remove only files that belonged to this managed attachment before its
     * canonical metadata was confirmed. Shared paths and anything outside the
     * Onun Kodety uploads namespace are deliberately preserved. */
    private function cleanup_managed_asset_derivatives(
        int $attachment_id,
        string $canonical_file,
        string $previous_file,
        array $previous_metadata,
        string $uploads_basedir
    ): void {
        $base = rtrim(str_replace('\\', '/', $uploads_basedir), '/');
        $canonical = str_replace('\\', '/', $canonical_file);
        $namespace = $base . '/kodety/assets/';
        if ($base === '' || !str_starts_with($canonical, $namespace)) return;

        $candidates = [];
        $add_candidate = static function (string $candidate) use (&$candidates, $base): void {
            $candidate = str_replace('\\', '/', $candidate);
            if ($candidate === '') return;
            if (!str_starts_with($candidate, '/')) $candidate = $base . '/' . ltrim($candidate, '/');
            $candidates[$candidate] = true;
        };
        $add_candidate($previous_file);
        $metadata_file = (string) ($previous_metadata['file'] ?? '');
        if ($metadata_file !== '') $add_candidate($metadata_file);
        $metadata_directory = $metadata_file !== '' ? dirname($metadata_file) : '';
        foreach ((array) ($previous_metadata['sizes'] ?? []) as $size) {
            if (!is_array($size) || empty($size['file'])) continue;
            $add_candidate(($metadata_directory !== '' ? $metadata_directory . '/' : '') . (string) $size['file']);
        }
        if (!empty($previous_metadata['original_image'])) {
            $add_candidate(($metadata_directory !== '' ? $metadata_directory . '/' : '') . (string) $previous_metadata['original_image']);
        }

        $canonical_info = pathinfo($canonical);
        $canonical_stem = (string) ($canonical_info['filename'] ?? '');
        $canonical_extension = (string) ($canonical_info['extension'] ?? '');
        $canonical_directory = (string) ($canonical_info['dirname'] ?? '');
        if ($canonical_stem !== '' && $canonical_extension !== '') {
            foreach (glob($canonical_directory . '/' . $canonical_stem . '-*.' . $canonical_extension) ?: [] as $candidate) {
                $basename = basename($candidate);
                if (preg_match(
                    '/^' . preg_quote($canonical_stem, '/') . '-(?:(?:scaled|rotated)(?:-(?:scaled|rotated))*|(?:scaled|rotated)-\\d+x\\d+|\\d+x\\d+)\\.' . preg_quote($canonical_extension, '/') . '$/i',
                    $basename
                )) {
                    $add_candidate($candidate);
                }
            }
        }

        foreach (array_keys($candidates) as $candidate) {
            $candidate = str_replace('\\', '/', $candidate);
            if (
                $candidate === $canonical
                || !str_starts_with($candidate, $namespace)
                || !is_file($candidate)
                || $this->managed_asset_file_is_shared($candidate, $attachment_id, $base)
            ) {
                continue;
            }
            @unlink($candidate);
        }
    }

    private function managed_asset_file_is_shared(string $file, int $attachment_id, string $uploads_basedir): bool {
        $file = str_replace('\\', '/', $file);
        $base = rtrim(str_replace('\\', '/', $uploads_basedir), '/') . '/';
        if (!str_starts_with($file, $base)) return true;
        $relative = substr($file, strlen($base));
        $matches = get_posts([
            'post_type' => 'attachment',
            'post_status' => ['inherit', 'trash'],
            'posts_per_page' => -1,
            'fields' => 'ids',
            'meta_key' => '_wp_attached_file',
            'meta_value' => $relative,
        ]);
        foreach ($matches as $candidate_id) {
            if ((int) $candidate_id !== $attachment_id) return true;
        }
        return false;
    }

    private function asset_mime_type(string $file): string {
        return match (strtolower(pathinfo($file, PATHINFO_EXTENSION))) {
            'svg' => 'image/svg+xml', 'avif' => 'image/avif', 'webm' => 'video/webm', 'mov' => 'video/quicktime',
            'mp3' => 'audio/mpeg', 'wav' => 'audio/wav', 'ogg' => 'audio/ogg', 'm4a' => 'audio/mp4', 'pdf' => 'application/pdf',
            'woff' => 'font/woff', 'woff2' => 'font/woff2', 'ttf' => 'font/ttf', 'otf' => 'font/otf',
            default => 'application/octet-stream',
        };
    }

    private function rewrite_theme_asset_references(string $site_root, array $url_map): void {
        $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($site_root, FilesystemIterator::SKIP_DOTS));
        foreach ($iterator as $file) {
            if (!$file->isFile() || !in_array(strtolower($file->getExtension()), ['html','htm','css'], true)) continue;
            $extension = strtolower($file->getExtension());
            $document_relative = ltrim(str_replace('\\', '/', substr($file->getPathname(), strlen($site_root))), '/');
            $original = file_get_contents($file->getPathname());
            if ($original === false) {
                throw new RuntimeException('Não foi possível ler ' . $document_relative . ' para reescrever os assets.');
            }
            $content = $original;
            $raw_text_payloads = [];
            if (in_array($extension, ['html', 'htm'], true)) {
                [$content, $raw_text_payloads] = $this->protect_html_raw_text_payloads($content);
            }
            $replace = function (string $reference) use ($document_relative, $url_map): string {
                if ($reference === '' || preg_match('~^(?:[a-z][a-z0-9+.-]*:|//|#)~i', $reference)) return $reference;
                $suffix = '';
                if (preg_match('/([?#].*)$/', $reference, $match)) { $suffix = $match[1]; $reference = substr($reference, 0, -strlen($suffix)); }
                $decoded = rawurldecode(ltrim($reference, '/'));
                $candidates = str_starts_with($reference, '/')
                    ? [$decoded, dirname($document_relative) . '/' . $decoded]
                    : [dirname($document_relative) . '/' . $decoded, $decoded];
                foreach ($candidates as $path) {
                    $segments = [];
                    foreach (explode('/', str_replace('\\', '/', $path)) as $segment) {
                        if ($segment === '' || $segment === '.') continue;
                        if ($segment === '..') array_pop($segments); else $segments[] = $segment;
                    }
                    $resolved = implode('/', $segments);
                    if (isset($url_map[$resolved])) return $url_map[$resolved] . $suffix;
                }
                return $reference . $suffix;
            };
            if (in_array($extension, ['html', 'htm'], true)) {
                $content = preg_replace_callback('/\b(src|href|poster)=([\'\"])([^\'\"]+)\2/i', static fn(array $m): string => $m[1] . '=' . $m[2] . $replace($m[3]) . $m[2], $content) ?? $content;
                $content = preg_replace_callback('/(?<![\w:-])(srcset|imagesrcset|data-srcset|data-lazy-srcset)(\s*=\s*)([\'\"])(.*?)\3/is', function (array $m) use ($replace): string {
                    return $m[1] . $m[2] . $m[3] . $this->import_map_srcset($m[4], $replace) . $m[3];
                }, $content) ?? $content;
                $content = preg_replace_callback('/<meta\b[^>]*>/i', static function (array $m) use ($replace): string {
                    $tag = $m[0];
                    if (!preg_match('/\b(?:property|name|itemprop)=([\'\"])(?:og:image(?::url)?|twitter:image(?::src)?|image)\1/i', $tag)) return $tag;
                    return preg_replace_callback(
                        '/\bcontent=([\'\"])([^\'\"]+)\1/i',
                        static fn(array $content_match): string => 'content=' . $content_match[1]
                            . $replace($content_match[2])
                            . $content_match[1],
                        $tag,
                        1
                    ) ?? $tag;
                }, $content) ?? $content;
            }
            $content = $extension === 'css'
                ? $this->import_map_css_urls($content, $replace)
                : (preg_replace_callback('/url\(\s*([\'\"]?)([^)\'\"]+)\1\s*\)/i', static fn(array $m): string => 'url(' . $m[1] . $replace(trim($m[2])) . $m[1] . ')', $content) ?? $content);
            if ($raw_text_payloads) $content = $this->restore_html_raw_text_payloads($content, $raw_text_payloads);
            if ($content === $original) continue;
            $written = @file_put_contents($file->getPathname(), $content, LOCK_EX);
            if ($written === false || $written !== strlen($content)) {
                throw new RuntimeException('Não foi possível reescrever os assets em ' . $document_relative . '.');
            }
            $persisted = @file_get_contents($file->getPathname());
            if (
                !is_string($persisted)
                || strlen($persisted) !== strlen($content)
                || !hash_equals(hash('sha256', $content), hash('sha256', $persisted))
            ) {
                throw new RuntimeException(
                    'A validação final dos assets falhou em ' . $document_relative . '.'
                );
            }
        }
    }

    public function attachment_fields_to_edit(array $fields, WP_Post $post): array {
        if (
            get_post_meta($post->ID, '_kodety_managed', true) !== '1'
            || !current_user_can('upload_files')
            || !$this->can_publish()
        ) {
            return $fields;
        }
        $url = add_query_arg(['page' => 'kodety-replace-asset', 'attachment' => $post->ID], admin_url('admin.php'));
        $fields['kodety_asset'] = [
            'label' => 'Onun Kodety', 'input' => 'html',
            'html' => '<a class="button" href="' . esc_url($url) . '">Substituir arquivo</a><p class="description">Atualiza o site e o projeto do editor.</p>',
        ];
        return $fields;
    }

    public function replace_asset_page(): void {
        $attachment_id = absint($_GET['attachment'] ?? 0);
        if (!$this->can_publish()) wp_die('Sem permissão para publicar o site.', '', ['response' => 403]);
        if (!$attachment_id || !current_user_can('edit_post', $attachment_id) || get_post_meta($attachment_id, '_kodety_managed', true) !== '1') wp_die('Asset Onun Kodety inválido.', '', ['response' => 404]);
        $paths = $this->attachment_asset_paths($attachment_id);
        ?>
        <div class="wrap kodety-replace-asset-page">
            <h1>Substituir asset</h1>
            <p>Arquivo<?php echo count($paths) === 1 ? '' : 's'; ?> do projeto: <code><?php echo esc_html(implode(', ', $paths)); ?></code></p>
            <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" enctype="multipart/form-data">
                <input type="hidden" name="action" value="kodety_replace_asset">
                <input type="hidden" name="attachment_id" value="<?php echo esc_attr((string) $attachment_id); ?>">
                <?php wp_nonce_field('kodety_replace_asset_' . $attachment_id); ?>
                <input type="file" name="kodety_asset_file" required>
                <?php submit_button('Substituir arquivo'); ?>
            </form>
        </div>
        <?php
    }

    public function replace_asset(): void {
        if (!$this->can_publish()) wp_die('Sem permissão para publicar o site.', '', ['response' => 403]);
        $attachment_id = absint($_POST['attachment_id'] ?? 0);
        if (!$attachment_id || !current_user_can('edit_post', $attachment_id)) wp_die('Sem permissão.', '', ['response' => 403]);
        check_admin_referer('kodety_replace_asset_' . $attachment_id);
        $file = $_FILES['kodety_asset_file'] ?? null;
        $target = get_attached_file($attachment_id);
        $relative_paths = $this->attachment_asset_paths($attachment_id);
        if (!$file || !$target || !$relative_paths || ($file['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK) wp_die('Falha ao receber o arquivo.', '', ['response' => 400]);
        if (strtolower(pathinfo((string) $file['name'], PATHINFO_EXTENSION)) !== strtolower(pathinfo($target, PATHINFO_EXTENSION))) wp_die('Use um arquivo com a mesma extensão do asset original.', '', ['response' => 400]);
        $replacement_targets = [$target];
        foreach ($relative_paths as $relative) {
            $theme_file = trailingslashit(get_theme_root()) . 'kodety-generated/site/' . $relative;
            if (is_file($theme_file)) $replacement_targets[] = $theme_file;
            array_push($replacement_targets, ...$this->native_workspace_asset_targets($relative));
        }
        try {
            $this->replace_files_atomically($replacement_targets, (string) $file['tmp_name']);
        } catch (Throwable $error) {
            wp_die(esc_html($error->getMessage()), 'Falha ao substituir asset', ['response' => 500, 'back_link' => true]);
        }
        update_post_meta($attachment_id, '_kodety_asset_hash', md5_file($target) ?: '');
        $metadata = $this->generate_managed_asset_metadata($attachment_id, $target);
        if (is_array($metadata)) wp_update_attachment_metadata($attachment_id, $metadata);
        clean_post_cache($attachment_id);
        wp_safe_redirect(add_query_arg(['post' => $attachment_id, 'action' => 'edit', 'kodety_replaced' => '1'], admin_url('post.php')));
        exit;
    }

    /** @return list<string> */
    private function attachment_asset_paths(int $attachment_id): array {
        $paths = get_post_meta($attachment_id, '_kodety_asset_paths', true);
        if (!is_array($paths)) $paths = [];
        $primary = (string) get_post_meta($attachment_id, '_kodety_asset_path', true);
        if ($primary !== '') array_unshift($paths, $primary);
        return array_values(array_unique(array_filter(array_map(static function ($path): string {
            return ltrim(str_replace('\\', '/', (string) $path), '/');
        }, $paths), static fn(string $path): bool => $path !== '' && !str_contains($path, '../') && !str_contains($path, "\0"))));
    }

    public function delete_unused_themes(): void {
        if (!current_user_can('delete_themes')) wp_die('Sem permissão.', '', ['response' => 403]);
        check_admin_referer('kodety_delete_unused_themes');
        require_once ABSPATH . 'wp-admin/includes/theme.php';
        $active = wp_get_theme();
        $protected = array_filter([$active->get_stylesheet(), $active->get_template()]);
        $deleted = 0;
        $failed = 0;
        foreach (wp_get_themes() as $stylesheet => $theme) {
            if (in_array($stylesheet, $protected, true)) continue;
            $result = delete_theme($stylesheet);
            if ($result === true) $deleted++; else $failed++;
        }
        wp_safe_redirect(add_query_arg(['kodety_themes_deleted' => $deleted, 'kodety_themes_failed' => $failed], admin_url('themes.php')));
        exit;
    }

    /** @return list<string> */
    private function native_workspace_asset_targets(string $relative): array {
        $relative = ltrim(str_replace('\\', '/', $relative), '/');
        if ($relative === '' || str_contains($relative, '../') || str_contains($relative, "\0")) return [];
        $release = (string) get_option('kodety_current_release', '');
        $directories = array_filter([
            $this->workspace_dir(),
            $release ? $this->releases_dir() . '/' . $release . '/project' : '',
        ], 'is_dir');
        $targets = [];
        foreach ($directories as $directory) {
            $root = $this->collapse_single_root($directory);
            $target = $root . '/' . $relative;
            if (!is_file($target)) continue;
            $target_real = realpath($target);
            $root_real = realpath($root);
            if (!$target_real || !$root_real || !str_starts_with($target_real, trailingslashit($root_real))) continue;
            $targets[] = $target_real;
        }
        return array_values(array_unique($targets));
    }

    /** Stage every copy beside its destination, then swap all files as one
     * recoverable operation. A failed theme/workspace write rolls earlier
     * destinations back instead of leaving three different asset versions. */
    private function replace_files_atomically(array $targets, string $source): void {
        $targets = array_values(array_unique(array_filter(array_map('strval', $targets), 'is_file')));
        if (!$targets || !is_file($source)) throw new RuntimeException('O arquivo de substituição não está disponível.');
        $token = function_exists('wp_generate_password')
            ? wp_generate_password(10, false, false)
            : bin2hex(random_bytes(5));
        $staged = [];
        $backups = [];
        try {
            foreach ($targets as $target) {
                $temporary = dirname($target) . '/.' . basename($target) . '.kodety-next-' . $token;
                if (!copy($source, $temporary)) throw new RuntimeException('Não foi possível preparar todas as cópias do asset.');
                $permissions = @fileperms($target);
                if (is_int($permissions)) @chmod($temporary, $permissions & 0777);
                $staged[$target] = $temporary;
            }
            foreach ($staged as $target => $temporary) {
                $backup = dirname($target) . '/.' . basename($target) . '.kodety-backup-' . $token;
                if (!rename($target, $backup)) throw new RuntimeException('Não foi possível preparar a troca atômica do asset.');
                $backups[$target] = $backup;
                if (!rename($temporary, $target)) throw new RuntimeException('Não foi possível ativar a nova versão do asset.');
                unset($staged[$target]);
            }
            foreach ($backups as $backup) @unlink($backup);
        } catch (Throwable $error) {
            foreach (array_reverse($backups, true) as $target => $backup) {
                if (is_file($target)) @unlink($target);
                if (is_file($backup)) @rename($backup, $target);
            }
            throw $error;
        } finally {
            foreach ($staged as $temporary) if (is_file($temporary)) @unlink($temporary);
            foreach ($backups as $backup) if (is_file($backup)) @unlink($backup);
        }
    }

    public function sync_project_pages(?string $expected_release = null): array {
        return $this->with_workspace_lock(function () use ($expected_release): array {
        $release = $this->active_release_for_sync($expected_release);
        $theme = wp_get_theme('kodety-generated');
        $theme_dir = $theme->exists() ? $theme->get_stylesheet_directory() : '';
        $manifest_path = $theme_dir ? $theme_dir . '/manifest.json' : '';
        if (!$manifest_path || !is_file($manifest_path)) {
            throw new RuntimeException('O manifesto de páginas da release não está disponível.');
        }
        $manifest = json_decode((string) file_get_contents($manifest_path), true);
        if (!is_array($manifest)) {
            throw new RuntimeException('O manifesto de páginas da release é inválido.');
        }

        $manifest_entries = [];
        foreach ($manifest as $route => $relative) {
            if (!is_string($route) || !is_string($relative)) continue;
            $manifest_entries[] = ['route' => $route, 'relativePath' => $relative];
        }
        // Validate ownership before even refreshing runtime PHP. A malformed
        // release cannot touch files, native pages, options, ACKs or hooks.
        $route_map = $this->project_page_route_map($manifest_entries);
        $canonical = [];
        foreach ($route_map as $route => $relative) {
            if (!isset($canonical[$relative]) || $route === '' || strlen($route) < strlen($canonical[$relative])) $canonical[$relative] = $route;
        }
        $this->refresh_theme_runtime($theme_dir);

        $managed_pages = get_posts([
            'post_type' => 'page',
            'post_status' => 'any',
            'posts_per_page' => -1,
            'orderby' => 'ID',
            'order' => 'ASC',
            // Some older releases wrote the route/path before writing the
            // managed flag. Treat every Onun Kodety identity marker as authoritative
            // so those pages are reused instead of silently duplicated.
            'meta_query' => [
                'relation' => 'OR',
                ['key' => '_kodety_managed', 'value' => '1'],
                ['key' => '_kodety_html_path', 'compare' => 'EXISTS'],
                ['key' => '_kodety_route', 'compare' => 'EXISTS'],
                ['key' => '_kodety_release', 'compare' => 'EXISTS'],
            ],
        ]);
        $front_page_id = (int) get_option('page_on_front');
        $by_path = [];
        $by_route = [];
        foreach ($managed_pages as $managed_page) {
            if (!$managed_page instanceof WP_Post) continue;
            $managed_id = (int) $managed_page->ID;
            $managed_path = $this->canonical_project_page_path((string) get_post_meta($managed_id, '_kodety_html_path', true));
            $managed_route = $this->canonical_project_page_route((string) get_post_meta($managed_id, '_kodety_route', true));
            if ($managed_path !== '') $by_path[$managed_path][] = $managed_id;
            // Older releases stored only the route. Retain that identity when
            // the file name changes, otherwise every publish creates a new
            // page and leaves the former one behind as a draft.
            if ($managed_route !== '') $by_route[$managed_route][] = $managed_id;
            if ($managed_route === '' && $front_page_id === $managed_id) $by_route[''][] = $managed_id;
        }

        $synced = [];
        $duplicates = [];
        $failures = [];
        $front_page_candidate = 0;
        foreach ($canonical as $relative => $route) {
            $relative = $this->canonical_project_page_path($relative);
            $route = $this->canonical_project_page_route($route);
            $candidates = array_map('intval', array_values(array_unique(array_merge($by_path[$relative] ?? [], $by_route[$route] ?? []))));
            // Keep identity stable across every publish. The front page wins,
            // then an already-published page, then the oldest remaining ID.
            // A modification timestamp must never decide which record survives.
            usort($candidates, static function(int $left, int $right) use ($front_page_id): int {
                $left_rank = [
                    $left === $front_page_id ? 0 : 1,
                    get_post_status($left) === 'publish' ? 0 : 1,
                    $left,
                ];
                $right_rank = [
                    $right === $front_page_id ? 0 : 1,
                    get_post_status($right) === 'publish' ? 0 : 1,
                    $right,
                ];
                return $left_rank <=> $right_rank;
            });
            $page_id = $candidates ? (int) array_shift($candidates) : 0;
            $is_new_page = $page_id <= 0;
            $title = $route === '' ? 'Início' : ucwords(str_replace(['-', '_'], ' ', basename($route)));
            $page = [
                'ID' => $page_id,
                'post_type' => 'page',
                'post_status' => 'publish',
                'post_title' => $title,
                'post_name' => $route === '' ? 'inicio' : sanitize_title(basename($route)),
                'post_content' => '',
            ];
            // An explicit update makes the one-page-per-route invariant clear
            // and avoids WordPress treating an invalid/zero ID as a new draft.
            try {
                $result = $page_id > 0 ? wp_update_post(wp_slash($page), true) : wp_insert_post(wp_slash($page), true);
            } catch (Throwable $error) {
                $failures[] = ($route === '' ? '/' : '/' . $route) . ' (' . $error->getMessage() . ')';
                continue;
            }
            if (is_wp_error($result) || (int) $result <= 0) {
                $detail = is_wp_error($result) ? $result->get_error_message() : 'o WordPress retornou um ID inválido';
                $failures[] = ($route === '' ? '/' : '/' . $route) . ' (' . $detail . ')';
                continue;
            }
            $page_id = (int) $result;
            $identity = [
                '_kodety_managed' => '1',
                '_kodety_html_path' => $relative,
                '_kodety_route' => $route,
                '_kodety_release' => $release,
            ];
            $identity_error = '';
            try {
                foreach ($identity as $meta_key => $meta_value) {
                    update_post_meta($page_id, $meta_key, $meta_value);
                }
                foreach ($identity as $meta_key => $meta_value) {
                    if ((string) get_post_meta($page_id, $meta_key, true) !== $meta_value) {
                        $identity_error = 'a identidade ' . $meta_key . ' não pôde ser confirmada';
                        break;
                    }
                }
            } catch (Throwable $error) {
                $identity_error = $error->getMessage();
            }
            if ($identity_error !== '') {
                if ($is_new_page) wp_trash_post($page_id);
                $failures[] = ($route === '' ? '/' : '/' . $route) . ' (' . $identity_error . ')';
                continue;
            }
            foreach ($candidates as $candidate_id) $duplicates[] = (int) $candidate_id;
            $synced[] = $page_id;
            if ($route === '') $front_page_candidate = $page_id;
        }

        if ($failures) {
            $visible_failures = array_slice($failures, 0, 5);
            if (count($failures) > count($visible_failures)) {
                $visible_failures[] = sprintf('+%d rota(s) com falha', count($failures) - count($visible_failures));
            }
            // Successful routes are safe to update again. Destructive
            // reconciliation and the release ACK wait until every route succeeds.
            throw new RuntimeException('A sincronização de páginas ficou pendente: ' . implode('; ', $visible_failures));
        }

        $this->active_release_for_sync($release);
        if ($front_page_candidate > 0) {
            update_option('show_on_front', 'page');
            update_option('page_on_front', $front_page_candidate);
            if (
                (string) get_option('show_on_front', '') !== 'page'
                || (int) get_option('page_on_front', 0) !== $front_page_candidate
            ) {
                throw new RuntimeException('A página inicial foi criada, mas o WordPress não confirmou sua ativação.');
            }
        }

        // Do not keep obsolete Onun Kodety pages as visible drafts. They are moved
        // to the native trash (recoverable) and duplicate references from old
        // releases are consolidated into their current page.
        $obsolete = array_unique(array_merge(
            array_map(static fn(WP_Post $page): int => (int) $page->ID, $managed_pages),
            $duplicates
        ));
        foreach ($obsolete as $page_id) {
            $page_id = (int) $page_id;
            if (
                $page_id > 0
                && !in_array($page_id, $synced, true)
                && !wp_trash_post($page_id)
            ) {
                $failures[] = '/' . $page_id . ' (a página obsoleta/duplicada não pôde ir para a Lixeira)';
            }
        }
        if ($failures) {
            throw new RuntimeException('A limpeza de páginas ficou pendente: ' . implode('; ', array_slice($failures, 0, 5)));
        }
        $this->active_release_for_sync($release);
        update_option('kodety_pages_synced_release', $release, false);
        if ($release === '' || (string) get_option('kodety_pages_synced_release', '') !== $release) {
            throw new RuntimeException('O WordPress não confirmou o ACK final da sincronização de páginas.');
        }
        return $synced;
        });
    }

    /** Normalize the persistent identity of a generated HTML file. */
    private function canonical_project_page_path(string $path): string {
        $path = ltrim(str_replace('\\', '/', trim($path)), '/');
        while (str_starts_with($path, './')) $path = substr($path, 2);
        return $path;
    }

    /** Normalize routes independently from their generated file path. */
    private function canonical_project_page_route(string $route): string {
        return trim(str_replace('\\', '/', trim($route)), '/');
    }

    /** Match the Builder's intrinsic clean-route semantics for authored HTML. */
    private function intrinsic_project_page_route(string $route): string {
        $route = trim(str_replace('\\', '/', trim($route)), '/');
        // Strip non-path bytes before recognizing index/HTML suffixes. Doing
        // this afterwards lets `about.html#preview.html` retain the first
        // extension and evade the same route as `about/index.html`.
        $route = (string) (preg_split('/[?#]/', $route, 2)[0] ?? '');
        $route = (string) preg_replace('~(?:^|/)index\.html?$~i', '', $route);
        $route = (string) preg_replace('/\.html?$/i', '', $route);
        // `normalizeRedirectPath()` drops query/fragment bytes and keeps a
        // malformed percent-encoded path verbatim when decodeURIComponent
        // rejects it. Mirror that behavior instead of emitting invalid UTF-8
        // into an actionable publication error.
        $decoded_candidate = rawurldecode($route);
        $valid_percent_encoding = preg_match('/%(?![A-Fa-f0-9]{2})/', $route) !== 1;
        $valid_utf8 = function_exists('mb_check_encoding')
            ? mb_check_encoding($decoded_candidate, 'UTF-8')
            : preg_match('//u', $decoded_candidate) === 1;
        $decoded = $valid_percent_encoding && $valid_utf8 ? $decoded_candidate : $route;
        $segments = [];
        foreach (explode('/', $decoded) as $segment) {
            if ($segment === '' || $segment === '.') continue;
            if ($segment === '..') {
                array_pop($segments);
                continue;
            }
            $segments[] = $segment;
        }
        return implode('/', $segments);
    }

    private function fold_project_page_route(string $route): string {
        return function_exists('mb_strtolower') ? mb_strtolower($route, 'UTF-8') : strtolower($route);
    }

    /**
     * Resolve one deterministic owner per canonical public route. Imported
     * projects can legitimately contain aliases such as `about.html` and
     * `about/index.html`; that ambiguity must be reported, never turn the
     * complete publication into HTTP 409. The last archive entry wins to keep
     * the behavior used by releases created before route diagnostics existed.
     *
     * @param list<array{route:string,relativePath:string}> $entries
     * @param list<array{route:string,pagePaths:list<string>,selectedPath:string}>|null $collisions
     * @return array<string,string> Canonical route without leading slash => relative path.
     */
    private function project_page_route_map(array $entries, ?array &$collisions = null): array {
        /** @var array<string,array{route:string,selectedRoute:string,selectedPath:string,pagePaths:array<string,true>}> $owners */
        $owners = [];
        foreach ($entries as $entry) {
            if (!is_array($entry)) continue;
            $relative = $this->canonical_project_page_path((string) ($entry['relativePath'] ?? ''));
            if ($relative === '' || !preg_match('/\.html?$/i', $relative)) continue;
            $route = $this->intrinsic_project_page_route((string) ($entry['route'] ?? ''));
            $folded = $this->fold_project_page_route($route);
            if (!isset($owners[$folded])) {
                $owners[$folded] = [
                    'route' => $folded === '' ? '/' : '/' . $folded,
                    'selectedRoute' => $route,
                    'selectedPath' => $relative,
                    'pagePaths' => [],
                ];
            }
            $owners[$folded]['pagePaths'][$relative] = true;
            $owners[$folded]['selectedRoute'] = $route;
            $owners[$folded]['selectedPath'] = $relative;
        }

        $routes = [];
        $detected_collisions = [];
        foreach ($owners as $owner) {
            $routes[$owner['selectedRoute']] = $owner['selectedPath'];
            $page_paths = array_keys($owner['pagePaths']);
            if (count($page_paths) < 2) continue;
            usort($page_paths, static fn(string $left, string $right): int => strnatcasecmp($left, $right) ?: strcmp($left, $right));
            $detected_collisions[] = [
                'route' => $owner['route'],
                'pagePaths' => $page_paths,
                'selectedPath' => $owner['selectedPath'],
            ];
        }
        usort(
            $detected_collisions,
            static fn(array $left, array $right): int => strnatcasecmp($left['route'], $right['route'])
                ?: strcmp($left['route'], $right['route'])
        );
        $collisions = $detected_collisions;
        return $routes;
    }

    private function refresh_theme_runtime(string $theme_dir): void {
        if ($theme_dir === '' || wp_get_theme()->get_stylesheet() !== 'kodety-generated') return;
        $theme_dir = rtrim($theme_dir, '/\\');
        if (!is_dir($theme_dir)) {
            throw new RuntimeException('O diretório do tema gerado não está disponível.');
        }

        /** @var array<string,array{content:string,hash:string}> $sources */
        $sources = [];
        $digest_material = '';
        foreach (self::theme_runtime_sources() as $file => $source_path) {
            $content = is_file($source_path) ? file_get_contents($source_path) : false;
            if (!is_string($content)) {
                throw new RuntimeException('O arquivo-base do runtime ' . $file . ' não pôde ser lido.');
            }
            $this->assert_valid_theme_runtime_source($file, $content);
            $hash = hash('sha256', $content);
            $sources[$file] = ['content' => $content, 'hash' => $hash];
            $digest_material .= $file . "\0" . strlen($content) . "\0" . $hash . "\0";
        }
        $runtime_digest = hash('sha256', $digest_material);
        $version = defined('KODETY_VERSION') ? (string) KODETY_VERSION : 'unknown';
        $theme_identity = hash('sha256', str_replace('\\', '/', $theme_dir));
        $ack_before = get_option(self::THEME_RUNTIME_ACK_OPTION, null);

        $lock_path = $theme_dir . '/.kodety-runtime-update.lock';
        $lock_handle = fopen($lock_path, 'c+');
        if (!is_resource($lock_handle)) {
            throw new RuntimeException('Não foi possível abrir o lock do runtime do tema.');
        }
        if (!flock($lock_handle, LOCK_EX)) {
            fclose($lock_handle);
            throw new RuntimeException('Não foi possível adquirir o lock do runtime do tema.');
        }

        /** @var array<string,array{exists:bool,content:string,hash:string,backup:string}> $snapshots */
        $snapshots = [];
        /** @var array<string,string> $staged */
        $staged = [];
        /** @var array<string,true> $replaced */
        $replaced = [];
        $token = '';
        $committed = false;
        try {
            $changed = [];
            foreach (self::theme_runtime_files() as $file) {
                $target = $theme_dir . '/' . $file;
                $exists = is_file($target);
                $content = $exists ? file_get_contents($target) : '';
                if ($exists && !is_string($content)) {
                    throw new RuntimeException('O runtime ativo ' . $file . ' não pôde ser fotografado.');
                }
                $content = is_string($content) ? $content : '';
                $hash = hash('sha256', $content);
                $snapshots[$file] = [
                    'exists' => $exists,
                    'content' => $content,
                    'hash' => $hash,
                    'backup' => '',
                ];
                if (!$exists || !hash_equals($sources[$file]['hash'], $hash)) $changed[] = $file;
            }

            if ($changed) {
                try {
                    $token = bin2hex(random_bytes(12));
                } catch (Throwable) {
                    $token = hash('sha256', uniqid('kodety-runtime-', true));
                }

                // Snapshot the complete quartet before replacing any member.
                // Backups and staged files live beside their targets so every
                // final rename is an atomic same-filesystem operation.
                foreach (self::theme_runtime_files() as $file) {
                    if (!$snapshots[$file]['exists']) continue;
                    $backup = $theme_dir . '/.' . $file . '.kodety-backup-' . $token;
                    $this->write_verified_theme_runtime_file(
                        $backup,
                        $snapshots[$file]['content'],
                        $snapshots[$file]['hash']
                    );
                    $snapshots[$file]['backup'] = $backup;
                }
                foreach ($changed as $file) {
                    $temporary = $theme_dir . '/.' . $file . '.kodety-stage-' . $token;
                    $this->write_verified_theme_runtime_file(
                        $temporary,
                        $sources[$file]['content'],
                        $sources[$file]['hash']
                    );
                    $staged[$file] = $temporary;
                    $this->theme_runtime_transaction_checkpoint('after_stage', $file);
                }

                foreach ($changed as $file) {
                    $target = $theme_dir . '/' . $file;
                    $temporary = $staged[$file];
                    if (!rename($temporary, $target)) {
                        throw new RuntimeException('Não foi possível ativar atomicamente o runtime ' . $file . '.');
                    }
                    unset($staged[$file]);
                    $replaced[$file] = true;
                    $this->assert_theme_runtime_file(
                        $target,
                        $sources[$file]['hash'],
                        strlen($sources[$file]['content'])
                    );
                    $this->theme_runtime_transaction_checkpoint('after_commit', $file);
                }
            }

            $ack = [
                'version' => $version,
                'digest' => $runtime_digest,
                'theme' => $theme_identity,
                'files' => $this->theme_runtime_file_state($theme_dir),
            ];
            update_option(self::THEME_RUNTIME_ACK_OPTION, $ack, false);
            $stored_ack = get_option(self::THEME_RUNTIME_ACK_OPTION, []);
            if (
                !is_array($stored_ack)
                || !hash_equals($version, (string) ($stored_ack['version'] ?? ''))
                || !hash_equals($runtime_digest, (string) ($stored_ack['digest'] ?? ''))
                || !hash_equals($theme_identity, (string) ($stored_ack['theme'] ?? ''))
            ) {
                throw new RuntimeException('O WordPress não confirmou o ACK do runtime do tema.');
            }
            $committed = true;
        } catch (Throwable $error) {
            $rollback_errors = [];
            foreach (array_reverse(self::theme_runtime_files()) as $file) {
                if (!isset($snapshots[$file], $replaced[$file])) continue;
                $target = $theme_dir . '/' . $file;
                $snapshot = $snapshots[$file];
                if (!$snapshot['exists']) {
                    if (is_file($target) && !unlink($target)) {
                        $rollback_errors[] = $file . ' (não foi possível remover o arquivo novo)';
                    }
                    continue;
                }
                $backup = $snapshot['backup'];
                if ($backup === '' || !is_file($backup) || !rename($backup, $target)) {
                    $rollback_errors[] = $file . ' (não foi possível restaurar o snapshot)';
                    continue;
                }
                $snapshots[$file]['backup'] = '';
                try {
                    $this->assert_theme_runtime_file(
                        $target,
                        $snapshot['hash'],
                        strlen($snapshot['content'])
                    );
                } catch (Throwable $rollback_error) {
                    $rollback_errors[] = $file . ' (' . $rollback_error->getMessage() . ')';
                }
            }
            if ($ack_before === null) delete_option(self::THEME_RUNTIME_ACK_OPTION);
            else update_option(self::THEME_RUNTIME_ACK_OPTION, $ack_before, false);

            if ($rollback_errors) {
                throw new RuntimeException(
                    'A atualização do runtime falhou e o rollback ficou incompleto: '
                    . implode('; ', $rollback_errors),
                    0,
                    $error
                );
            }
            throw $error;
        } finally {
            foreach ($staged as $temporary) if (is_file($temporary)) @unlink($temporary);
            foreach ($snapshots as $snapshot) {
                if ($snapshot['backup'] !== '' && is_file($snapshot['backup'])) @unlink($snapshot['backup']);
            }
            flock($lock_handle, LOCK_UN);
            fclose($lock_handle);
        }

        // This secondary repair may touch component HTML/runtime assets, so it
        // must never run against a partially upgraded PHP quartet.
        if ($committed) $this->repair_published_code_component_runtime($theme_dir);
    }

    private function write_verified_theme_runtime_file(string $path, string $content, string $expected_hash): void {
        $written = file_put_contents($path, $content, LOCK_EX);
        if ($written !== strlen($content)) {
            throw new RuntimeException('A gravação verificada do runtime ficou incompleta.');
        }
        $this->assert_theme_runtime_file($path, $expected_hash, strlen($content));
    }

    private function assert_theme_runtime_file(string $path, string $expected_hash, int $expected_length): void {
        clearstatcache(true, $path);
        $content = is_file($path) ? file_get_contents($path) : false;
        if (
            !is_string($content)
            || strlen($content) !== $expected_length
            || !hash_equals($expected_hash, hash('sha256', $content))
        ) {
            throw new RuntimeException('O readback/hash do arquivo ' . basename($path) . ' divergiu.');
        }
    }

    /**
     * Deliberately narrow fault seam used by the focused transaction harness.
     * In production the filter defaults to an empty string and has no effect.
     */
    private function theme_runtime_transaction_checkpoint(string $checkpoint, string $file): void {
        $failure = apply_filters(
            'kodety_theme_runtime_transaction_fault',
            '',
            $checkpoint,
            $file
        );
        if (is_string($failure) && $failure !== '') throw new RuntimeException($failure);
    }

    /** Backfill the self-hosted React runtime into releases published before
     * Code Components started emitting import maps. Existing releases keep
     * working immediately after the plugin update, without requiring users to
     * edit or recreate their component instances. */
    private function repair_published_code_component_runtime(string $theme_dir): void {
        $site_root = rtrim($theme_dir, '/\\') . '/site';
        $runtime_source = KODETY_DIR . 'assets/code-component-react-runtime.mjs';
        if (!is_dir($site_root) || !is_file($runtime_source)) return;

        $html_files = $this->find_html_files($site_root);
        $component_files = [];
        foreach ($html_files as $html_file) {
            $html = (string) file_get_contents($html_file);
            if (str_contains($html, 'data-coday-code-components-runtime')) $component_files[$html_file] = $html;
        }
        if (!$component_files) return;

        $runtime_dir = $site_root . '/.coday/runtime';
        if (!is_dir($runtime_dir)) wp_mkdir_p($runtime_dir);
        if (!is_dir($runtime_dir) || !copy($runtime_source, $runtime_dir . '/react.mjs')) return;

        $specifiers = ['react', 'react/jsx-runtime', 'react/jsx-dev-runtime', 'react-dom', 'react-dom/client', '@coday/components', 'framer'];
        foreach ($component_files as $html_file => $html) {
            $relative = ltrim(str_replace('\\', '/', substr($html_file, strlen($site_root))), '/');
            $directory = trim(str_replace('\\', '/', dirname($relative)), './');
            $depth = $directory === '' ? 0 : substr_count($directory, '/') + 1;
            $prefix = $depth > 0 ? str_repeat('../', $depth) : './';
            $runtime_url = $prefix . '.coday/runtime/react.mjs';
            $imports = array_fill_keys($specifiers, $runtime_url);
            $import_map = '<script type="importmap" data-coday-code-components-importmap>'
                . wp_json_encode(['imports' => $imports], JSON_UNESCAPED_SLASHES)
                . '</script>';
            $html = (string) preg_replace(
                '/\s*<script\b[^>]*data-coday-code-components-importmap[^>]*>[\s\S]*?<\/script>/i',
                '',
                $html
            );
            $html = (string) preg_replace(
                '/(<script\b[^>]*data-coday-code-components-runtime[^>]*>)/i',
                $import_map . "\n$1",
                $html,
                1
            );
            file_put_contents($html_file, $html, LOCK_EX);
        }
    }

    public function page_row_actions(array $actions, WP_Post $post): array {
        $url = $this->managed_page_editor_url($post);
        if ($url === '' || !current_user_can(self::CAP_EDIT_WORKSPACE)) return $actions;
        unset($actions['edit'], $actions['inline hide-if-no-js']);
        $translate = static fn(string $label): string => class_exists('Kodety_Admin_I18n')
            ? Kodety_Admin_I18n::instance()->translate($label)
            : $label;
        $kodety_actions = ['kodety_edit' => '<a href="' . esc_url($url) . '">' . $this->dashboard_icon('edit') . '<span>' . esc_html($translate('Editar no Onun Kodety')) . '</span></a>'];
        if (current_user_can(self::CAP_MANAGE_CMS_TEMPLATES)) {
            $template_url = wp_nonce_url(
                add_query_arg(['action' => 'kodety_set_cms_template', 'post' => $post->ID], admin_url('admin-post.php')),
                'kodety_set_cms_template_' . $post->ID
            );
            $kodety_actions['kodety_cms_template'] = '<a href="' . esc_url($template_url) . '">' . $this->dashboard_icon('pages') . '<span>' . esc_html($translate('Usar como template CMS')) . '</span></a>';
        }
        return $kodety_actions + $actions;
    }

    public function managed_edit_post_link(?string $link, int $post_id, string $context): ?string {
        if (!current_user_can(self::CAP_EDIT_WORKSPACE)) return $link;
        $post = get_post($post_id);
        if (!$post instanceof WP_Post) return $link;
        $editor_url = $this->managed_page_editor_url($post);
        return $editor_url !== '' ? $editor_url : $link;
    }

    private function managed_page_editor_url(WP_Post $post): string {
        if ($post->post_type !== 'page') return '';
        $path = (string) get_post_meta($post->ID, '_kodety_html_path', true);
        if ($path !== '') return add_query_arg('kodety_html', $path, home_url('/kodety/editor/'));
        return get_post_meta($post->ID, '_kodety_managed', true) === '1'
            ? home_url('/kodety/editor/')
            : '';
    }

    private function trash_default_wordpress_pages(): array {
        $default_titles = ['Página de exemplo', 'Sample Page', 'Política de privacidade', 'Privacy Policy'];
        $default_slugs = ['pagina-de-exemplo', 'sample-page', 'politica-de-privacidade', 'privacy-policy'];
        $trashed = [];
        $pages = get_posts([
            'post_type' => 'page',
            'post_status' => ['publish', 'draft', 'pending', 'private', 'future'],
            'numberposts' => -1,
        ]);
        foreach ($pages as $page) {
            if (!in_array($page->post_title, $default_titles, true) && !in_array($page->post_name, $default_slugs, true)) continue;
            if ((int) get_option('wp_page_for_privacy_policy') === $page->ID) update_option('wp_page_for_privacy_policy', 0);
            if (wp_trash_post($page->ID)) $trashed[] = $page->ID;
        }
        update_option('kodety_default_pages_cleaned', gmdate('c'), false);
        return $trashed;
    }

    public function page_post_states(array $states, WP_Post $post): array {
        if (get_post_meta($post->ID, '_kodety_managed', true) === '1') $states['kodety'] = 'Onun Kodety';
        return $states;
    }

    private function workspace_dir(): string {
        $workspace = $this->private_storage_dir() . '/workspace';
        $shared_project_id = $this->shared_project_id();
        if ($shared_project_id === '' || $shared_project_id === $this->agency_active_project_id()) {
            return $workspace;
        }
        $projects = $this->agency_projects();
        if (!isset($projects[$shared_project_id])) return $workspace;
        return $this->agency_project_dir($shared_project_id) . '/workspace';
    }

    private function private_storage_dir(): string {
        return $this->storage_dir . '/private';
    }

    private function releases_dir(): string {
        return $this->private_storage_dir() . '/releases';
    }

    private function has_workspace(): bool {
        return is_dir($this->workspace_dir()) || is_file($this->current_zip());
    }

    /** One-time conversion from archive-backed state to ordinary WordPress
     * files. A failed current-workspace conversion is retained and retried on
     * the next request; an invalid historical rollback is simply discarded. */
    private function migrate_native_workspace_storage(): bool {
        $legacy_releases = $this->storage_dir . '/releases';
        if (is_dir($legacy_releases)) {
            foreach (glob($legacy_releases . '/*', GLOB_ONLYDIR) ?: [] as $legacy_release) {
                $destination = $this->releases_dir() . '/' . basename($legacy_release);
                if (!is_dir($destination) && @rename($legacy_release, $destination)) continue;
                if (!is_dir($destination)) $this->copy_workspace_tree($legacy_release, $destination);
                $this->remove_tree($legacy_release);
            }
            @rmdir($legacy_releases);
        }
        $workspace = $this->workspace_dir();
        $legacy_current = $this->current_zip();
        if (!is_dir($workspace) && is_file($legacy_current)) {
            try {
                $this->repair_component_studio_workspace($legacy_current);
                $this->activate_workspace_from_zip($legacy_current);
            } catch (Throwable $error) {
                error_log('[Onun Kodety] Não foi possível migrar current.zip para o workspace nativo: ' . $error->getMessage());
                return false;
            }
        }
        if (is_dir($workspace) && is_file($legacy_current)) @unlink($legacy_current);

        foreach (glob($this->releases_dir() . '/*', GLOB_ONLYDIR) ?: [] as $release_dir) {
            $legacy = $release_dir . '/project.zip';
            $project = $release_dir . '/project';
            if (!is_dir($project) && is_file($legacy)) {
                $staging = $release_dir . '/.project-migration';
                try {
                    if (is_dir($staging)) $this->remove_tree($staging);
                    wp_mkdir_p($staging);
                    $this->extract_safe_zip($legacy, $staging);
                    if (!$this->find_html_files($staging) || $this->directory_contains_component_studio($staging)) {
                        throw new RuntimeException('snapshot inválido');
                    }
                    if (!rename($staging, $project)) throw new RuntimeException('não foi possível ativar o snapshot');
                } catch (Throwable $error) {
                    if (is_dir($staging)) $this->remove_tree($staging);
                    error_log('[Onun Kodety] Release legada removida durante migração: ' . basename($release_dir) . ' (' . $error->getMessage() . ')');
                    $this->remove_tree($release_dir);
                    continue;
                }
            }
            if (is_dir($project)) {
                $project_root = $this->collapse_single_root($project);
                $this->seal_membership_assets($project_root);
                $this->seal_membership_artifact($project_root);
                if (is_file($legacy)) @unlink($legacy);
            }
        }

        if (is_dir($workspace)) {
            try {
                $workspace_root = $this->collapse_single_root($workspace);
                $this->seal_membership_assets($workspace_root);
                $this->seal_membership_artifact($workspace_root);
                $this->write_preview_file_manifest($workspace_root);
                update_option('kodety_workspace_css_digest', $this->css_digest_from_directory($workspace), false);
                $project_name = $this->project_name_from_directory($workspace);
                if ($project_name !== '') update_option('kodety_project_name', $project_name, false);
                $workspace_project_id = $this->project_id_from_directory($workspace);
                if ($workspace_project_id !== '') update_option('kodety_workspace_project_id', $workspace_project_id, false);
                $current_release = (string) get_option('kodety_current_release', '');
                $published_project = $current_release !== '' ? $this->releases_dir() . '/' . $current_release . '/project' : '';
                if ($published_project !== '' && is_dir($published_project)) {
                    $published_project_id = $this->project_id_from_directory($published_project);
                    if ($published_project_id !== '') update_option('kodety_published_project_id', $published_project_id, false);
                }
            } catch (Throwable $error) {
                // Native storage is already valid. Media registration can be
                // retried by the normal admin sync without rolling it back.
                error_log('[Onun Kodety] Workspace migrado; sincronização de mídia pendente: ' . $error->getMessage());
            }
        }
        return true;
    }

    /** Prepare native Builder previews when an imported project contains Liquid. */
    private function prepare_shopify_theme_workspace(string $directory): bool {
        $root = $this->collapse_single_root($directory);
        if (!is_file($root . '/layout/theme.liquid')) return false;
        // Draft ZIPs already contain the editable previews and their exact
        // Liquid token map. Rebuilding those files on every autosave would
        // discard canvas edits and make the extracted workspace differ from
        // the bytes the Builder actually sent.
        $existing_metadata_path = $root . '/.incode/shopify-theme.json';
        if (is_file($existing_metadata_path)) {
            $existing_metadata = json_decode((string) file_get_contents($existing_metadata_path), true);
            if (
                is_array($existing_metadata)
                && ($existing_metadata['version'] ?? null) === 1
                && ($existing_metadata['kind'] ?? '') === 'shopify-theme'
                && is_array($existing_metadata['previewSources'] ?? null)
                && !empty($existing_metadata['previewSources'])
            ) {
                return true;
            }
        }
        $section_files = glob($root . '/sections/*.liquid') ?: [];
        $section_files = array_values(array_filter($section_files, 'is_file'));
        if (!$section_files) return false;
        sort($section_files, SORT_STRING);
        usort($section_files, static function (string $left, string $right): int {
            $preferred = static fn(string $path): int => preg_match('/(?:main-product|main-collection|featured-collection|image-banner)\.liquid$/i', $path) ? 0 : 1;
            return $preferred($left) <=> $preferred($right) ?: strcmp($left, $right);
        });
        $theme_name = 'Tema Shopify';
        $schema_path = $root . '/config/settings_schema.json';
        if (is_file($schema_path)) {
            $schema = json_decode((string) file_get_contents($schema_path), true);
            if (is_array($schema)) {
                foreach ($schema as $item) {
                    if (!is_array($item)) continue;
                    $candidate = trim((string) ($item['theme_name'] ?? $item['name'] ?? ''));
                    if ($candidate === '' || strcasecmp($candidate, 'Theme settings') === 0) continue;
                    $theme_name = substr(sanitize_text_field($candidate), 0, 120);
                    break;
                }
            }
        }
        $css_files = glob($root . '/assets/*.css') ?: [];
        sort($css_files, SORT_STRING);
        $preview_sources = [];
        if (!is_dir($root . '/shopify-preview')) wp_mkdir_p($root . '/shopify-preview');
        foreach (array_slice($section_files, 0, 160) as $index => $source_file) {
            $relative_source = ltrim(str_replace('\\', '/', substr($source_file, strlen($root))), '/');
            $stem = sanitize_file_name(pathinfo($source_file, PATHINFO_FILENAME)) ?: 'section-' . ($index + 1);
            $preview_relative = $index === 0 ? 'index.html' : 'shopify-preview/' . $stem . '.html';
            $source_liquid = (string) file_get_contents($source_file);
            $liquid = $source_liquid;
            $schema_block = '';
            $liquid = (string) preg_replace_callback(
                '~{%\s*schema\s*%}[\s\S]*?{%\s*endschema\s*%}~i',
                static function (array $match) use (&$schema_block): string {
                    $schema_block = (string) $match[0];
                    return '<!--KODETY_LIQUID_SCHEMA_BLOCK-->';
                },
                $liquid,
                1
            );
            $configuration = $this->merge_shopify_preview_configuration(
                $this->shopify_schema_preview_configuration($schema_block),
                $this->shopify_section_preview_configuration($root, $stem)
            );
            $tokens = [];
            $preview_overrides = [];
            $token_index = 0;
            $preview_token = static function (string $token, string $preview) use (&$tokens, &$preview_overrides, &$token_index): string {
                $token_index++;
                $id = str_pad(base_convert((string) $token_index, 10, 36), 3, '0', STR_PAD_LEFT);
                $tokens[$id] = $token;
                $preview_overrides[$id] = $preview;
                return '__KODETY_LIQUID_OUTPUT_' . $id . '__';
            };
            $liquid = (string) preg_replace_callback(
                '~{%[-]?\s*stylesheet\s*[-]?%}([\s\S]*?){%[-]?\s*endstylesheet\s*[-]?%}~i',
                static fn(array $match): string => $preview_token(
                    (string) $match[0],
                    '<style data-kodety-shopify-stylesheet>'
                        . str_ireplace('</style', '<\/style', (string) ($match[1] ?? ''))
                        . '</style>'
                ),
                $liquid
            );
            $liquid = (string) preg_replace_callback(
                '~{%[-]?\s*style\s*[-]?%}([\s\S]*?){%[-]?\s*endstyle\s*[-]?%}~i',
                static fn(array $match): string => $preview_token(
                    (string) $match[0],
                    '<style data-kodety-shopify-style>'
                        . str_ireplace('</style', '<\/style', (string) ($match[1] ?? ''))
                        . '</style>'
                ),
                $liquid
            );
            $liquid = (string) preg_replace_callback(
                '~{%[-]?\s*javascript\s*[-]?%}[\s\S]*?{%[-]?\s*endjavascript\s*[-]?%}~i',
                static fn(array $match): string => $preview_token((string) $match[0], ''),
                $liquid
            );
            $liquid = (string) preg_replace_callback(
                '~{%[-]?\s*doc\s*[-]?%}[\s\S]*?{%[-]?\s*enddoc\s*[-]?%}~i',
                static fn(array $match): string => $preview_token((string) $match[0], ''),
                $liquid
            );
            $liquid = (string) preg_replace_callback(
                '~{%[-]?\s*comment\s*[-]?%}[\s\S]*?{%[-]?\s*endcomment\s*[-]?%}~i',
                static fn(array $match): string => $preview_token((string) $match[0], ''),
                $liquid
            );
            $liquid = (string) preg_replace_callback(
                '~{%[-]?\s*capture\b[\s\S]*?[-]?%}[\s\S]*?{%[-]?\s*endcapture\s*[-]?%}~i',
                static fn(array $match): string => $preview_token((string) $match[0], ''),
                $liquid
            );
            $liquid = (string) preg_replace_callback(
                '~{%[-]?[\s\S]*?[-]?%}~',
                function (array $match) use ($root, $configuration, $preview_token): string {
                    $token = (string) $match[0];
                    $preview = $this->shopify_control_preview($token, $root, $configuration);
                    return $preview === null ? $token : $preview_token($token, $preview);
                },
                $liquid
            );
            $preview_source = (string) preg_replace_callback(
                '~{{-?[\s\S]*?-?}}|{%-?[\s\S]*?-?%}~',
                static function (array $match) use (&$tokens, &$token_index): string {
                    $token_index++;
                    $id = str_pad(base_convert((string) $token_index, 10, 36), 3, '0', STR_PAD_LEFT);
                    $token = (string) $match[0];
                    $tokens[$id] = $token;
                    return str_starts_with($token, '{{')
                        ? '__KODETY_LIQUID_OUTPUT_' . $id . '__'
                        : '__KODETY_LIQUID_CONTROL_' . $id . '__';
                },
                $liquid
            );
            $projection = $this->project_shopify_liquid_preview(
                $preview_source,
                $tokens,
                $this->shopify_preview_settings($configuration),
                $preview_overrides
            );
            $preview_source = (string) $projection['html'];
            $links = [];
            foreach ($css_files as $css_file) {
                $href = ($index === 0 ? 'assets/' : '../assets/') . rawurlencode(basename($css_file));
                $links[] = '<link rel="stylesheet" href="' . esc_attr($href) . '">';
            }
            $preview = '<!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'
                . esc_html(str_replace('-', ' ', $stem))
                . ' — Shopify</title>' . implode('', $links)
                . '</head>'
                . '<body data-label="Shopify Section Preview" data-kodety-shopify-preview="true">'
                . '<main data-kodety-shopify-source-root data-kodety-shopify-source="' . esc_attr($relative_source) . '">'
                . $preview_source . '</main></body></html>';
            $target = $root . '/' . $preview_relative;
            if (!is_dir(dirname($target))) wp_mkdir_p(dirname($target));
            if (file_put_contents($target, $preview, LOCK_EX) === false) {
                throw new RuntimeException('Não foi possível criar a prévia editável do projeto Liquid.');
            }
            $preview_sources[$preview_relative] = array_filter([
                'sourcePath' => $relative_source,
                'tokens' => $tokens,
                'attributeBindings' => $projection['attributeBindings'],
                'tableControlGroups' => $this->shopify_table_control_groups($preview_source),
                'schemaBlock' => $schema_block,
                'sourceDigest' => $this->shopify_source_digest($source_liquid),
                'previewDigest' => $this->shopify_source_digest($preview),
            ], static fn(mixed $value): bool => $value !== '');
        }
        wp_mkdir_p($root . '/.incode');
        $metadata = [
            'version' => 1,
            'kind' => 'shopify-theme',
            'themeRoot' => '',
            'previewSources' => $preview_sources,
        ];
        if (file_put_contents($root . '/.incode/shopify-theme.json', (string) wp_json_encode($metadata, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE), LOCK_EX) === false) {
            throw new RuntimeException('Não foi possível registrar o suporte Liquid do projeto.');
        }
        if (file_put_contents($root . '/.incode/project.json', (string) wp_json_encode([
            'version' => 1,
            'name' => $theme_name,
            'mainHtmlPath' => 'index.html',
            'homeHtmlPath' => 'index.html',
            'rootPath' => '',
            'projectType' => 'shopify-theme',
        ], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE), LOCK_EX) === false) {
            throw new RuntimeException('Não foi possível registrar o projeto Shopify.');
        }
        return true;
    }

    private function shopify_json_document(string $source): ?array {
        $normalized = (string) preg_replace('/^\xEF\xBB\xBF/', '', $source);
        $normalized = (string) preg_replace('~^\s*/\*[\s\S]*?\*/\s*~', '', $normalized, 1);
        $decoded = json_decode($normalized, true);
        return is_array($decoded) ? $decoded : null;
    }

    private function shopify_schema_preview_configuration(string $schema_block): array {
        $json = trim((string) preg_replace(
            ['~^{%[-]?\s*schema\s*[-]?%}~i', '~{%[-]?\s*endschema\s*[-]?%}$~i'],
            '',
            $schema_block
        ));
        $schema = $this->shopify_json_document($json);
        if (!is_array($schema)) return [];
        $settings = [];
        foreach (is_array($schema['settings'] ?? null) ? $schema['settings'] : [] as $setting) {
            if (!is_array($setting)) continue;
            $id = trim((string) ($setting['id'] ?? ''));
            if ($id !== '' && array_key_exists('default', $setting) && $setting['default'] !== null) {
                $settings[$id] = $setting['default'];
            }
        }
        $preset = [];
        foreach (is_array($schema['presets'] ?? null) ? $schema['presets'] : [] as $candidate) {
            if (is_array($candidate)) {
                $preset = $candidate;
                break;
            }
        }
        return array_filter([
            'settings' => array_merge($settings, is_array($preset['settings'] ?? null) ? $preset['settings'] : []),
            'blocks' => is_array($preset['blocks'] ?? null) ? $preset['blocks'] : [],
            'block_order' => is_array($preset['block_order'] ?? null) ? array_values($preset['block_order']) : [],
        ], static fn(mixed $value): bool => $value !== []);
    }

    private function merge_shopify_preview_configuration(array $fallback, array $configured): array {
        if (!$configured) return $fallback;
        $merged = array_merge($fallback, $configured);
        $merged['settings'] = array_merge(
            is_array($fallback['settings'] ?? null) ? $fallback['settings'] : [],
            is_array($configured['settings'] ?? null) ? $configured['settings'] : []
        );
        if (empty($configured['blocks']) && !empty($fallback['blocks'])) $merged['blocks'] = $fallback['blocks'];
        if (empty($configured['block_order']) && !empty($fallback['block_order'])) $merged['block_order'] = $fallback['block_order'];
        return $merged;
    }

    private function shopify_section_preview_configuration(string $root, string $section_type): array {
        $candidates = array_merge(
            glob($root . '/sections/*.json') ?: [],
            glob($root . '/templates/*.json') ?: []
        );
        usort($candidates, static function (string $left, string $right) use ($section_type): int {
            $score = static function (string $path) use ($section_type): int {
                if (preg_match('~/sections/' . preg_quote($section_type, '~') . '-group\.json$~i', str_replace('\\', '/', $path))) return 0;
                if (preg_match('~/templates/index\.json$~i', str_replace('\\', '/', $path))) return 1;
                if (preg_match('~/sections/[^/]+-group\.json$~i', str_replace('\\', '/', $path))) return 2;
                return 3;
            };
            return $score($left) <=> $score($right) ?: strcmp($left, $right);
        });
        foreach ($candidates as $path) {
            $document = $this->shopify_json_document((string) file_get_contents($path));
            $sections = is_array($document['sections'] ?? null) ? $document['sections'] : [];
            if (!$sections) continue;
            $order = is_array($document['order'] ?? null) ? array_map('strval', $document['order']) : [];
            $ids = array_values(array_unique(array_merge($order, array_keys($sections))));
            foreach ($ids as $id) {
                $configuration = $sections[$id] ?? null;
                if (is_array($configuration) && strcasecmp((string) ($configuration['type'] ?? ''), $section_type) === 0) {
                    return $configuration;
                }
            }
        }
        return [];
    }

    private function shopify_preview_settings(array $configuration): array {
        $result = [];
        foreach (is_array($configuration['settings'] ?? null) ? $configuration['settings'] : [] as $key => $value) {
            $result[(string) $key] = is_scalar($value) ? (string) $value : '';
        }
        return $result;
    }

    private function shopify_preview_source_path(string $kind, string $name): string {
        $safe = preg_replace('/\.liquid$/i', '', trim($name)) ?: '';
        if (!preg_match('/^[a-z0-9_-]+$/i', $safe)) return '';
        return $kind . '/' . $safe . '.liquid';
    }

    private function shopify_preview_fallback_block(array $configuration, string $type): string {
        $values = [];
        foreach (is_array($configuration['settings'] ?? null) ? $configuration['settings'] : [] as $value) {
            if (!is_string($value) || trim($value) === '' || str_starts_with(trim($value), 't:')) continue;
            $values[] = trim($value);
            if (count($values) >= 4) break;
        }
        $content = '';
        foreach ($values as $value) $content .= preg_match('/^\s*</', $value) ? $value : '<p>' . esc_html($value) . '</p>';
        $label = ucwords(str_replace(['_', '-'], ' ', $type)) ?: 'Shopify Block';
        return '<div data-label="' . esc_attr($label) . '" data-kodety-shopify-block-preview="true">'
            . ($content !== '' ? $content : 'Conteúdo do bloco') . '</div>';
    }

    private function strip_shopify_projection_bindings(string $source): string {
        return (string) preg_replace([
            '~<!--/?KODETY_LIQUID_OUTPUT:[a-z0-9]+-->~i',
            '~<!--KODETY_LIQUID:[a-z0-9]+-->~i',
            '~<!--KODETY_LIQUID_SCHEMA_BLOCK-->~',
            '~\sdata-kodety-liquid-(?:attr|control|output-attribute|rcdata)-[a-z0-9]+=(?:"[^"]*"|\'[^\']*\')~i',
        ], '', $source);
    }

    private function project_static_shopify_liquid(string $source, array $settings): string {
        $tokens = [];
        $token_index = 0;
        $tokenized = (string) preg_replace_callback(
            '~{{-?[\s\S]*?-?}}|{%-?[\s\S]*?-?%}~',
            static function (array $match) use (&$tokens, &$token_index): string {
                $token_index++;
                $id = str_pad(base_convert((string) $token_index, 10, 36), 3, '0', STR_PAD_LEFT);
                $token = (string) $match[0];
                $tokens[$id] = $token;
                return str_starts_with($token, '{{')
                    ? '__KODETY_LIQUID_OUTPUT_' . $id . '__'
                    : '__KODETY_LIQUID_CONTROL_' . $id . '__';
            },
            $source
        );
        $projection = $this->project_shopify_liquid_preview($tokenized, $tokens, $settings);
        return $this->strip_shopify_projection_bindings((string) $projection['html']);
    }

    private function render_shopify_preview_fragment(
        string $root,
        string $source_path,
        array $configuration = [],
        int $depth = 0,
        array $stack = []
    ): string {
        if ($depth > 10 || isset($stack[$source_path])) return '';
        $absolute = $root . '/' . ltrim($source_path, '/');
        if (!is_file($absolute)) {
            return $this->shopify_preview_fallback_block($configuration, (string) ($configuration['type'] ?? 'block'));
        }
        $stack[$source_path] = true;
        $schema_block = '';
        $source = (string) file_get_contents($absolute);
        $source = (string) preg_replace_callback(
            '~{%[-]?\s*schema\s*[-]?%}[\s\S]*?{%[-]?\s*endschema\s*[-]?%}~i',
            static function (array $match) use (&$schema_block): string {
                $schema_block = (string) $match[0];
                return '';
            },
            $source,
            1
        );
        $resolved = $this->merge_shopify_preview_configuration(
            $this->shopify_schema_preview_configuration($schema_block),
            $configuration
        );
        $source = (string) preg_replace_callback(
            '~{%[-]?\s*stylesheet\s*[-]?%}([\s\S]*?){%[-]?\s*endstylesheet\s*[-]?%}~i',
            static fn(array $match): string => '<style data-kodety-shopify-stylesheet>'
                . str_ireplace('</style', '<\/style', (string) ($match[1] ?? '')) . '</style>',
            $source
        );
        $source = (string) preg_replace_callback(
            '~{%[-]?\s*style\s*[-]?%}([\s\S]*?){%[-]?\s*endstyle\s*[-]?%}~i',
            static fn(array $match): string => '<style data-kodety-shopify-style>'
                . str_ireplace('</style', '<\/style', (string) ($match[1] ?? '')) . '</style>',
            $source
        );
        $source = (string) preg_replace(
            [
                '~{%[-]?\s*javascript\s*[-]?%}[\s\S]*?{%[-]?\s*endjavascript\s*[-]?%}~i',
                '~{%[-]?\s*doc\s*[-]?%}[\s\S]*?{%[-]?\s*enddoc\s*[-]?%}~i',
                '~{%[-]?\s*comment\s*[-]?%}[\s\S]*?{%[-]?\s*endcomment\s*[-]?%}~i',
                '~{%[-]?\s*capture\b[\s\S]*?[-]?%}[\s\S]*?{%[-]?\s*endcapture\s*[-]?%}~i',
            ],
            '',
            $source
        );
        $source = (string) preg_replace_callback(
            '~{%[-]?\s*content_for\s+[\'"]blocks[\'"][\s\S]*?[-]?%}~i',
            fn(): string => $this->render_shopify_preview_blocks($root, $resolved, $depth + 1, $stack),
            $source
        );
        $source = (string) preg_replace_callback(
            '~{%[-]?\s*content_for\s+[\'"]block[\'"]([\s\S]*?)[-]?%}~i',
            function (array $match) use ($root, $resolved, $depth, $stack): string {
                preg_match('~\btype\s*:\s*[\'"]([a-z0-9_-]+)[\'"]~i', (string) ($match[1] ?? ''), $type_match);
                preg_match('~\bid\s*:\s*[\'"]([a-z0-9_-]+)[\'"]~i', (string) ($match[1] ?? ''), $id_match);
                $type = (string) ($type_match[1] ?? '');
                $id = (string) ($id_match[1] ?? '');
                $blocks = is_array($resolved['blocks'] ?? null) ? $resolved['blocks'] : [];
                $block = $id !== '' && is_array($blocks[$id] ?? null) ? $blocks[$id] : ['type' => $type];
                return $this->render_shopify_preview_block($root, $block, $id !== '' ? $id : $type, $depth + 1, $stack);
            },
            $source
        );
        $source = (string) preg_replace_callback(
            '~{%[-]?\s*(?:render|include)\s+[\'"]([a-z0-9_-]+)[\'"][\s\S]*?[-]?%}~i',
            function (array $match) use ($root, $resolved, $depth, $stack): string {
                $snippet = $this->shopify_preview_source_path('snippets', (string) ($match[1] ?? ''));
                return $snippet !== ''
                    ? $this->render_shopify_preview_fragment($root, $snippet, $resolved, $depth + 1, $stack)
                    : '';
            },
            $source
        );
        return $this->project_static_shopify_liquid($source, $this->shopify_preview_settings($resolved));
    }

    private function shopify_semantic_block_preview(
        string $root,
        array $configuration,
        string $type,
        int $depth = 0,
        array $stack = []
    ): ?string {
        $normalized = strtolower((string) preg_replace('/^_+/', '', $type));
        $settings = is_array($configuration['settings'] ?? null) ? $configuration['settings'] : [];
        $setting = static function (array $keys) use ($settings): string {
            foreach ($keys as $key) {
                $value = $settings[$key] ?? null;
                if (is_string($value) && trim($value) !== '' && !str_starts_with(trim($value), 't:')) return trim($value);
                if (is_int($value) || is_float($value) || is_bool($value)) return (string) $value;
            }
            return '';
        };
        $text_markup = static function (string $fallback, array $keys) use ($setting): string {
            $value = $setting($keys);
            if ($value === '') $value = $fallback;
            return preg_match('/^\s*</', $value) ? $value : esc_html($value);
        };
        if (preg_match('/^(?:group|content|content-without-appearance)$/', $normalized)) {
            $direction = $setting(['content_direction']) === 'row' ? 'row' : 'column';
            $gap = max(0, min(100, (int) ($setting(['gap']) ?: 16)));
            return '<div data-label="Shopify Group" style="display:flex;flex-direction:' . $direction . ';gap:' . $gap
                . 'px;align-items:flex-start;min-width:0">'
                . $this->render_shopify_preview_blocks($root, $configuration, $depth + 1, $stack) . '</div>';
        }
        if (preg_match('/^(?:text|inline-text|heading|title|rich-text)$/', $normalized) || preg_match('/(?:^|-)title$/', $normalized)) {
            $fallback = preg_match('/heading|title/', $normalized) ? '<h3>Título de exemplo</h3>' : '<p>Conteúdo de exemplo</p>';
            return '<div data-label="Shopify Text" style="max-width:100%;color:inherit">'
                . $text_markup($fallback, ['text', 'heading', 'title', 'content', 'description', 'caption']) . '</div>';
        }
        if (preg_match('/menu|link-list|footer-links/', $normalized)) {
            return '<nav data-label="Shopify Menu" style="display:grid;gap:10px;min-width:140px"><strong>'
                . esc_html($setting(['heading', 'title']) ?: 'Links')
                . '</strong><a href="#" style="color:inherit">Novidades</a><a href="#" style="color:inherit">Produtos</a><a href="#" style="color:inherit">Contato</a></nav>';
        }
        if (preg_match('/^(?:image|media|collection-image|product-card-image|blog-post-image)$/', $normalized) || preg_match('/(?:^|-)image$/', $normalized)) {
            return '<img data-label="Shopify Image" src="' . esc_attr($this->shopify_liquid_preview_value('{{ image }}', 'src'))
                . '" alt="' . esc_attr($setting(['alt', 'heading', 'title']) ?: 'Imagem de exemplo')
                . '" style="display:block;width:100%;min-height:180px;aspect-ratio:4/3;object-fit:cover;background:#eceae4">';
        }
        if (str_contains($normalized, 'logo')) {
            return '<strong data-label="Shopify Logo" style="display:inline-flex;align-items:center;min-height:36px;font-size:20px;letter-spacing:.08em">'
                . esc_html($setting(['text', 'heading']) ?: 'MINHA LOJA') . '</strong>';
        }
        if (preg_match('/button|add-to-cart|buy-buttons/', $normalized)) {
            $fallback = preg_match('/cart|buy/', $normalized) ? 'Adicionar ao carrinho' : 'Saiba mais';
            return '<a data-label="Shopify Button" href="#" style="display:inline-flex;min-height:44px;padding:10px 18px;align-items:center;justify-content:center;border-radius:6px;background:#171717;color:#fff;text-decoration:none">'
                . esc_html($setting(['label', 'text', 'button_label']) ?: $fallback) . '</a>';
        }
        if (preg_match('/email-signup|newsletter/', $normalized)) {
            return '<form data-label="Shopify Newsletter" style="display:flex;gap:8px;flex-wrap:wrap"><input type="email" placeholder="seu@email.com" style="min-height:44px;padding:10px 12px;border:1px solid #c8c8c8"><button type="button" style="min-height:44px;padding:10px 16px">Cadastrar</button></form>';
        }
        if (str_contains($normalized, 'divider')) return '<hr data-label="Shopify Divider" style="width:100%;border:0;border-top:1px solid currentColor;opacity:.2">';
        if (str_contains($normalized, 'spacer')) return '<div data-label="Shopify Spacer" style="height:32px"></div>';
        if (preg_match('/social|payment-icons/', $normalized)) return '<div data-label="Shopify Icons" style="display:flex;gap:8px;flex-wrap:wrap"><span>●</span><span>●</span><span>●</span></div>';
        if (str_contains($normalized, 'price')) return '<strong data-label="Shopify Price">R$ 189,00</strong>';
        if (str_contains($normalized, 'product')) return '<article data-label="Shopify Product" style="display:grid;gap:10px"><h3>Produto de exemplo</h3><p>R$ 189,00</p></article>';
        return null;
    }

    private function render_shopify_preview_block(
        string $root,
        array $configuration,
        string $id,
        int $depth = 0,
        array $stack = []
    ): string {
        $type = trim((string) ($configuration['type'] ?? ''));
        if ($type === '' || str_starts_with($type, '@')) return '';
        $path = $this->shopify_preview_source_path('blocks', $type);
        $semantic = $this->shopify_semantic_block_preview($root, $configuration, $type, $depth, $stack);
        $content = $semantic ?? ($path !== '' && is_file($root . '/' . $path)
            ? $this->render_shopify_preview_fragment($root, $path, $configuration, $depth + 1, $stack)
            : $this->shopify_preview_fallback_block($configuration, $type));
        $label = ucwords(str_replace(['_', '-'], ' ', $type)) ?: $type;
        return '<div data-label="' . esc_attr($label) . '" data-kodety-shopify-block="' . esc_attr($id !== '' ? $id : $type) . '">'
            . $content . '</div>';
    }

    private function render_shopify_preview_blocks(
        string $root,
        array $configuration,
        int $depth = 0,
        array $stack = []
    ): string {
        $blocks = is_array($configuration['blocks'] ?? null) ? $configuration['blocks'] : [];
        $declared = is_array($configuration['block_order'] ?? null) ? array_map('strval', $configuration['block_order']) : [];
        $order = array_values(array_unique(array_merge($declared, array_keys($blocks))));
        $result = [];
        foreach ($order as $id) {
            $block = is_array($blocks[$id] ?? null) ? $blocks[$id] : [];
            $result[] = $this->render_shopify_preview_block($root, $block, $id, $depth + 1, $stack);
        }
        return implode("\n", $result);
    }

    private function shopify_control_preview(string $token, string $root, array $configuration): ?string {
        if (preg_match('~^{%[-]?\s*content_for\s+[\'"]blocks[\'"]~i', $token)) {
            return $this->render_shopify_preview_blocks($root, $configuration);
        }
        if (preg_match('~^{%[-]?\s*content_for\s+[\'"]block[\'"]([\s\S]*?)[-]?%}$~i', $token, $block_match)) {
            preg_match('~\btype\s*:\s*[\'"]([a-z0-9_-]+)[\'"]~i', (string) ($block_match[1] ?? ''), $type_match);
            preg_match('~\bid\s*:\s*[\'"]([a-z0-9_-]+)[\'"]~i', (string) ($block_match[1] ?? ''), $id_match);
            $type = (string) ($type_match[1] ?? '');
            $id = (string) ($id_match[1] ?? '');
            $blocks = is_array($configuration['blocks'] ?? null) ? $configuration['blocks'] : [];
            $block = $id !== '' && is_array($blocks[$id] ?? null) ? $blocks[$id] : ['type' => $type];
            return $this->render_shopify_preview_block($root, $block, $id !== '' ? $id : $type);
        }
        if (preg_match('~^{%[-]?\s*(?:render|include)\s+[\'"]([a-z0-9_-]+)[\'"][\s\S]*?[-]?%}$~i', $token, $snippet_match)) {
            $snippet = $this->shopify_preview_source_path('snippets', (string) ($snippet_match[1] ?? ''));
            return $snippet !== '' ? $this->render_shopify_preview_fragment($root, $snippet, $configuration) : '';
        }
        return null;
    }

    /** @return array{html:string,attributeBindings:array<string,array<string,string>>} */
    private function project_shopify_liquid_preview(
        string $source,
        array $tokens,
        array $settings = [],
        array $preview_overrides = []
    ): array {
        $bindings = [];
        $binding_index = 0;
        $raw_element = '';
        $preview_value_for = function (string $id, string $attribute = '') use ($tokens, $settings, $preview_overrides): string {
            if (!array_key_exists($id, $preview_overrides)) {
                return $this->shopify_liquid_preview_value((string) ($tokens[$id] ?? ''), $attribute, $settings);
            }
            $value = (string) ($preview_overrides[$id] ?? '');
            if ($attribute === 'style') return '--kodety-liquid-preview:1';
            if ($attribute === 'class') return '';
            return $attribute !== '' ? trim((string) preg_replace('/\s+/', ' ', strip_tags($value))) : $value;
        };
        $parts = $this->split_shopify_liquid_preview_markup($source);
        foreach ($parts as $index => $part) {
            if (!preg_match('~^<\s*(textarea|title)\b~i', $part)) continue;
            $value = (string) ($parts[$index + 1] ?? '');
            if (!preg_match('/__KODETY_LIQUID_(?:OUTPUT|CONTROL)_[a-z0-9]+__/i', $value)) continue;
            $source_value = (string) preg_replace_callback(
                '/__KODETY_LIQUID_(?:OUTPUT|CONTROL)_([a-z0-9]+)__/i',
                static fn(array $match): string => (string) ($tokens[$match[1]] ?? $match[0]),
                $value
            );
            $preview_value = (string) preg_replace_callback(
                '/__KODETY_LIQUID_OUTPUT_([a-z0-9]+)__/i',
                static fn(array $match): string => $preview_value_for((string) $match[1]),
                $value
            );
            $preview_value = (string) preg_replace('/__KODETY_LIQUID_CONTROL_[a-z0-9]+__/i', '', $preview_value);
            $binding_index++;
            $binding_id = str_pad(base_convert((string) $binding_index, 10, 36), 3, '0', STR_PAD_LEFT);
            $bindings[$binding_id] = [
                'attribute' => '#rcdata',
                'sourceValue' => $source_value,
                'previewValue' => $preview_value,
            ];
            $parts[$index] = (string) preg_replace(
                '~(\s*/?>)$~',
                ' data-kodety-liquid-rcdata-' . $binding_id . '=""$1',
                $part,
                1
            );
            $parts[$index + 1] = esc_html($preview_value);
        }
        $projected = '';
        foreach ($parts as $part) {
            if (str_starts_with($part, '<')) {
                $lower = strtolower($part);
                if (preg_match('~^<\s*(script|style|textarea|title)(?:\s|>)~', $lower, $open)) $raw_element = (string) $open[1];
                if ($raw_element !== '' && preg_match('~^<\s*/' . preg_quote($raw_element, '~') . '\s*>~', $lower)) $raw_element = '';
                if (preg_match('~^<\s*/~', $part) || str_starts_with($part, '<!--') || !str_contains($part, '__KODETY_LIQUID_')) {
                    $projected .= $part;
                    continue;
                }
                $markers = [];
                $bind_attribute = function (array $match, bool $quoted) use (&$bindings, &$binding_index, &$markers, $tokens, $preview_value_for): string {
                    $value = (string) $match[4 + ($quoted ? 1 : 0)];
                    if (!preg_match('/__KODETY_LIQUID_(?:OUTPUT|CONTROL)_[a-z0-9]+__/i', $value)) return (string) $match[0];
                    $attribute_name = (string) $match[2];
                    $attribute = strtolower($attribute_name);
                    $source_value = (string) preg_replace_callback(
                        '/__KODETY_LIQUID_(?:OUTPUT|CONTROL)_([a-z0-9]+)__/i',
                        static fn(array $token_match): string => (string) ($tokens[$token_match[1]] ?? $token_match[0]),
                        $value
                    );
                    $preview_value = (string) preg_replace_callback(
                        '/__KODETY_LIQUID_OUTPUT_([a-z0-9]+)__/i',
                        static fn(array $token_match): string => $preview_value_for((string) $token_match[1], $attribute),
                        $value
                    );
                    $preview_value = (string) preg_replace('/__KODETY_LIQUID_CONTROL_[a-z0-9]+__/i', '', $preview_value);
                    $binding_index++;
                    $binding_id = str_pad(base_convert((string) $binding_index, 10, 36), 3, '0', STR_PAD_LEFT);
                    $bindings[$binding_id] = [
                        'attribute' => $attribute_name,
                        'sourceValue' => $source_value,
                        'previewValue' => $preview_value,
                        'sourceAttribute' => $attribute_name . (string) $match[3]
                            . ($quoted ? (string) $match[4] : '')
                            . $source_value
                            . ($quoted ? (string) $match[4] : ''),
                    ];
                    $markers[] = ' data-kodety-liquid-attr-' . $binding_id . '="' . esc_attr($attribute) . '"';
                    $quote = $quoted ? (string) $match[4] : '"';
                    $escaped = $quote === '"'
                        ? str_replace('"', '&quot;', $preview_value)
                        : str_replace("'", '&#39;', $preview_value);
                    return (string) $match[1] . $match[2] . $match[3] . $quote . $escaped . $quote;
                };
                $tag = (string) preg_replace_callback(
                    '~(\s)([^\s=/>]+)(\s*=\s*)(["\'])([\s\S]*?)\4~',
                    static fn(array $match): string => $bind_attribute($match, true),
                    $part
                );
                $tag = (string) preg_replace_callback(
                    '~(\s)([^\s=/>]+)(\s*=\s*)([^\s"\'=<>`]+)~',
                    static fn(array $match): string => $bind_attribute($match, false),
                    $tag
                );
                $tag = (string) preg_replace_callback(
                    '/__KODETY_LIQUID_CONTROL_([a-z0-9]+)__/i',
                    static fn(array $match): string => ' data-kodety-liquid-control-' . $match[1] . '="" ',
                    $tag
                );
                $tag = (string) preg_replace_callback(
                    '/__KODETY_LIQUID_OUTPUT_([a-z0-9]+)__/i',
                    static fn(array $match): string => ' data-kodety-liquid-output-attribute-' . $match[1] . '="" ',
                    $tag
                );
                if ($markers) $tag = (string) preg_replace('~(\s*/?>)$~', implode('', $markers) . '$1', $tag, 1);
                $projected .= $tag;
                continue;
            }
            if ($raw_element !== '') {
                $projected .= $part;
                continue;
            }
            $text = (string) preg_replace_callback(
                '/__KODETY_LIQUID_OUTPUT_([a-z0-9]+)__/i',
                static function (array $match) use ($preview_value_for): string {
                    $value = $preview_value_for((string) $match[1]);
                    $preview = preg_match('/^\s*</', $value) ? $value : esc_html($value);
                    return '<!--KODETY_LIQUID_OUTPUT:' . $match[1] . '-->' . $preview
                        . '<!--/KODETY_LIQUID_OUTPUT:' . $match[1] . '-->';
                },
                $part
            );
            $projected .= (string) preg_replace('/__KODETY_LIQUID_CONTROL_([a-z0-9]+)__/i', '<!--KODETY_LIQUID:$1-->', $text);
        }
        return ['html' => $projected, 'attributeBindings' => $bindings];
    }

    /**
     * Quote-aware HTML segmentation for Liquid previews. A comparison such as
     * `data-test="2 > 1"` must not truncate the tag, and script/style bodies
     * remain inert even when they contain angle brackets.
     *
     * @return list<string>
     */
    private function split_shopify_liquid_preview_markup(string $source): array {
        $parts = [];
        $length = strlen($source);
        $cursor = 0;
        $raw_element = '';
        while ($cursor < $length) {
            $tag_start = $raw_element !== ''
                ? stripos($source, '</' . $raw_element, $cursor)
                : strpos($source, '<', $cursor);
            if ($tag_start === false) {
                $parts[] = substr($source, $cursor);
                break;
            }
            if ($tag_start > $cursor) $parts[] = substr($source, $cursor, $tag_start - $cursor);
            $tag_end = -1;
            if (substr($source, $tag_start, 4) === '<!--') {
                $comment_end = strpos($source, '-->', $tag_start + 4);
                $tag_end = $comment_end === false ? $length : $comment_end + 3;
            } else {
                $quote = '';
                for ($index = $tag_start + 1; $index < $length; $index++) {
                    $character = $source[$index];
                    if ($quote !== '') {
                        if ($character === $quote && ($index === 0 || $source[$index - 1] !== '\\')) $quote = '';
                        continue;
                    }
                    if ($character === '"' || $character === "'") {
                        $quote = $character;
                        continue;
                    }
                    if ($character === '>') {
                        $tag_end = $index + 1;
                        break;
                    }
                }
                if ($tag_end < 0) $tag_end = $length;
            }
            $tag = substr($source, $tag_start, $tag_end - $tag_start);
            $parts[] = $tag;
            if (preg_match('~^<\s*/\s*(script|style|textarea|title)\b~i', $tag, $closing) && strtolower((string) $closing[1]) === $raw_element) {
                $raw_element = '';
            }
            if ($raw_element === '' && !preg_match('~^<\s*/~', $tag) && !preg_match('~/\s*>$~', $tag)) {
                $raw_element = preg_match('~^<\s*(script|style|textarea|title)\b~i', $tag, $opening)
                    ? strtolower((string) $opening[1])
                    : '';
            }
            $cursor = $tag_end;
        }
        return $parts;
    }

    /** @return list<list<string>> */
    private function shopify_table_control_groups(string $source): array {
        preg_match_all(
            '~((?:__KODETY_LIQUID_CONTROL_[a-z0-9]+__\s*)+)(?=<tr\b)~i',
            $source,
            $groups
        );
        $result = [];
        foreach ((array) ($groups[1] ?? []) as $group) {
            preg_match_all('/__KODETY_LIQUID_CONTROL_([a-z0-9]+)__/i', (string) $group, $ids);
            if (!empty($ids[1])) $result[] = array_values(array_map('strval', $ids[1]));
        }
        return $result;
    }

    private function shopify_liquid_preview_value(string $token, string $attribute = '', array $settings = []): string {
        $expression = strtolower(trim((string) preg_replace('/^{{-?\s*|\s*-?}}$/', '', $token)));
        $key = preg_match('/(?:section|block)\.settings\.([a-z0-9_-]+)/', $expression, $bound)
            ? (string) $bound[1]
            : '';
        $configured = $key !== '' && array_key_exists($key, $settings) ? (string) $settings[$key] : null;
        if ($configured !== null && preg_match('/{{|{%/', $configured)) {
            if (preg_match('/color|background|foreground/', $key)) $configured = '#eceae4';
            elseif (preg_match('/gap|width|height|size|count|columns|padding|margin|radius|opacity/', $key)) $configured = '0';
            else $configured = 'Conteúdo de exemplo';
        }
        if ($configured !== null && str_starts_with(trim($configured), 't:')) $configured = 'Texto traduzido';
        if (in_array($attribute, ['src', 'poster', 'srcset'], true)) {
            if ($configured !== null && preg_match('~^(?:https?:|data:|\.{0,2}/)~i', $configured)) return $configured;
            return 'data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 1200 1200%22%3E%3Crect width=%221200%22 height=%221200%22 fill=%22%23eceae4%22/%3E%3Cpath d=%22M330 760l170-190 120 120 120-150 170 220z%22 fill=%22%23c9c5ba%22/%3E%3Ccircle cx=%22440%22 cy=%22410%22 r=%2270%22 fill=%22%23d8ff64%22/%3E%3C/svg%3E';
        }
        if (in_array($attribute, ['href', 'action'], true)) {
            if ($configured !== null && preg_match('~^(?:https?:|#|/)~i', $configured)) return $configured;
            if ($configured !== null && str_contains($configured, 'collection')) return '/collections/colecao-em-destaque';
            if ($configured !== null && str_contains($configured, 'product')) return '/products/produto-de-exemplo';
            if (str_contains($expression, 'cart')) return '/cart';
            if (str_contains($expression, 'collection')) return '/collections/colecao-em-destaque';
            if (str_contains($expression, 'product') || str_contains($expression, 'url')) return '/products/produto-de-exemplo';
            return '#';
        }
        if ($configured !== null) return $configured;
        if (in_array($attribute, ['id', 'for'], true)) return 'shopify-preview';
        if ($attribute === 'class') return '';
        if ($attribute === 'style') return '--kodety-liquid-preview:1';
        if (preg_match('/compare_at_price|price|money|amount/', $expression)) return 'R$ 189,00';
        if (preg_match('/product\.title|card_product\.title/', $expression)) return 'Produto de exemplo';
        if (str_contains($expression, 'collection.title')) return 'Coleção em destaque';
        if (preg_match('/article\.title|blog\.title/', $expression)) return 'Novidades da loja';
        if (str_contains($expression, 'shop.name')) return 'Minha loja';
        if (preg_match('/vendor|brand/', $expression)) return 'Marca Shopify';
        if (preg_match('/variant\.title|option/', $expression)) return 'Opção padrão';
        if (preg_match('/description|content|body_html/', $expression)) return 'Uma descrição clara e envolvente para apresentar este conteúdo.';
        if (preg_match('/quantity|count|index|size/', $expression)) return '1';
        if (preg_match('/date|created_at|published_at/', $expression)) return '2 de agosto de 2026';
        if (preg_match('/image|media|featured/', $expression)) return '';
        if (preg_match('/(?:section|block)\.settings\.([a-z0-9_-]+)/', $expression, $setting)) {
            $key = (string) $setting[1];
            if (preg_match('/heading|title/', $key)) return 'Título da seção';
            if (preg_match('/button|label|link/', $key)) return 'Saiba mais';
            if (preg_match('/text|description|caption|subheading/', $key)) return 'Conteúdo de exemplo para editar visualmente.';
            $label = ucwords(str_replace(['_', '-'], ' ', $key));
            return $label !== '' ? $label : 'Conteúdo de exemplo';
        }
        if (preg_match('/\|\s*t\b|translation/', $expression)) return 'Texto traduzido';
        return 'Conteúdo de exemplo';
    }

    private function shopify_source_digest(string $source): string {
        $hash = 0x811c9dc5;
        $length = strlen($source);
        for ($index = 0; $index < $length; $index++) {
            $hash ^= ord($source[$index]);
            $hash = ($hash * 0x01000193) & 0xffffffff;
        }
        return str_pad(strtolower(dechex($hash)), 8, '0', STR_PAD_LEFT);
    }

    private function activate_workspace_from_zip(
        string $zip_path,
        ?string $expected_digest = null,
        bool $restore_template_state = false,
        ?string $expected_project_digest = null
    ): string {
        $token = function_exists('wp_generate_password')
            ? wp_generate_password(8, false, false)
            : bin2hex(random_bytes(4));
        $staging = $this->private_storage_dir() . '/.workspace-next-' . $token;
        $workspace = $this->workspace_dir();
        $backup = $this->private_storage_dir() . '/.workspace-previous';
        if (is_dir($staging)) $this->remove_tree($staging);
        wp_mkdir_p($staging);
        try {
            $this->extract_safe_zip($zip_path, $staging);
            // Prove that extraction preserved the uploaded archive before any
            // Builder-only Liquid previews are generated. Those previews are
            // legitimate workspace additions and therefore must not be
            // compared with the digest of the original Shopify theme ZIP.
            $extracted_digest = $this->css_digest_from_directory($staging);
            if ($expected_digest !== null && !hash_equals($expected_digest, $extracted_digest)) {
                throw new RuntimeException('O workspace extraído divergiu do conteúdo recebido.');
            }
            if ($expected_project_digest !== null) {
                $extracted_root = $this->collapse_single_root($staging);
                $extracted_project_digest = $this->project_digest_from_directory($extracted_root);
                if (!hash_equals($expected_project_digest, $extracted_project_digest)) {
                    throw new RuntimeException('O workspace extraído não preservou a árvore completa recebida.');
                }
            }
            $this->prepare_shopify_theme_workspace($staging);
            $workspace_html_files = $this->find_html_files($staging);
            if (!$workspace_html_files) throw new RuntimeException('O projeto não contém páginas HTML.');
            Kodety_Edition::assert_project_collection_connections(
                $workspace_html_files,
                array_column($this->collection_definitions(), 'slug')
            );
            if ($this->directory_contains_component_studio($staging)) {
                throw new RuntimeException('O canvas temporário de um componente não pode substituir o workspace.');
            }
            // Workspaces live below uploads on common WordPress hosts. Apache
            // deny files are not a security boundary on Nginx, so keep the
            // private authoring snapshot encrypted and public HTML scrubbed.
            $staging_root = $this->collapse_single_root($staging);
            $this->assert_project_localization_metadata($staging_root);
            $this->seal_membership_assets($staging_root);
            $this->seal_membership_artifact($staging_root);
            $this->write_preview_file_manifest($staging_root);
            if (is_dir($backup)) $this->remove_tree($backup);
            if (is_dir($workspace) && !rename($workspace, $backup)) {
                throw new RuntimeException('Não foi possível preparar a troca do workspace.');
            }
            if (!rename($staging, $workspace)) {
                if (is_dir($backup)) rename($backup, $workspace);
                throw new RuntimeException('Não foi possível ativar o workspace nativo.');
            }
            if ($restore_template_state) {
                try {
                    $restore_project_id = $this->project_id_from_directory($workspace);
                    if ($restore_project_id === '') $restore_project_id = $this->cms_workspace_project_id();
                    $this->restore_project_template_state($workspace, $restore_project_id);
                } catch (Throwable $error) {
                    if (is_dir($workspace)) $this->remove_tree($workspace);
                    if (is_dir($backup)) rename($backup, $workspace);
                    throw $error;
                }
            }
            if (is_dir($backup)) $this->remove_tree($backup);
            if (is_file($this->current_zip())) @unlink($this->current_zip());
            return $workspace;
        } catch (Throwable $error) {
            if (is_dir($staging)) $this->remove_tree($staging);
            throw $error;
        }
    }

    /** Clone editable source including `.incode`; public theme copies use the
     * separate copy_tree() helper that deliberately omits editor metadata. */
    private function copy_workspace_tree(string $source, string $destination): void {
        wp_mkdir_p($destination);
        foreach (new DirectoryIterator($source) as $item) {
            if ($item->isDot()) continue;
            $target = $destination . '/' . $item->getFilename();
            if ($item->isDir()) {
                $this->copy_workspace_tree($item->getPathname(), $target);
            } elseif (!$item->isLink() && !copy($item->getPathname(), $target)) {
                throw new RuntimeException('Não foi possível copiar ' . $item->getFilename() . ' para o workspace.');
            }
        }
    }

    /** Restore authoring HTML from the private membership transport artifact.
     * Callers must use a disposable directory: the canonical workspace keeps
     * the artifact sealed and its HTML scrubbed while at rest. */
    private function hydrate_membership_workspace(string $directory): void {
        $root = $this->collapse_single_root($directory);
        $artifact_path = $root . '/.incode/membership/runtime.json';
        if (!is_file($artifact_path)) return;
        $artifact = $this->read_membership_artifact($artifact_path);
        if (
            (int) ($artifact['version'] ?? 0) !== 1
            || ($artifact['enabled'] ?? false) !== true
            || !is_array($artifact['pages'] ?? null)
        ) {
            throw new RuntimeException('O snapshot privado da Área de Membros é inválido.');
        }
        $root_real = realpath($root);
        if (!$root_real) throw new RuntimeException('O workspace da Área de Membros não pôde ser validado.');
        $root_canonical = $this->project_delta_canonical_real_path($root_real);
        foreach ($artifact['pages'] as $page) {
            if (!is_array($page) || !is_string($page['path'] ?? null) || !is_string($page['editorHtml'] ?? null)) {
                throw new RuntimeException('Uma página privada da Área de Membros está incompleta.');
            }
            $relative = ltrim(str_replace('\\', '/', $page['path']), '/');
            if ($relative === '' || str_contains($relative, '../') || str_contains($relative, "\0") || !preg_match('/\.html?$/i', $relative)) {
                throw new RuntimeException('O snapshot da Área de Membros contém um caminho inválido.');
            }
            $target = $root . '/' . $relative;
            $target_parent = realpath(dirname($target));
            $target_parent_canonical = is_string($target_parent)
                ? $this->project_delta_canonical_real_path($target_parent)
                : '';
            if (
                !$target_parent
                || (
                    $target_parent_canonical !== $root_canonical
                    && !str_starts_with($target_parent_canonical, $root_canonical . '/')
                )
            ) {
                throw new RuntimeException('O snapshot da Área de Membros tentou sair do workspace.');
            }
            $editor_html = $page['editorHtml'];
            if (file_put_contents($target, $editor_html, LOCK_EX) !== strlen($editor_html)) {
                throw new RuntimeException('Não foi possível restaurar uma página privada no workspace.');
            }
        }
        @unlink($artifact_path);
        @rmdir(dirname($artifact_path));
    }

    /** @return list<array<string,mixed>> */
    private function sanitize_project_template_fields(mixed $fields): array {
        if (!is_array($fields)) return [];
        $allowed_types = ['text', 'textarea', 'richtext', 'image', 'url', 'number', 'boolean', 'date', 'color'];
        $reserved = ['title', 'excerpt', 'content', 'featured_image', 'featured_image_alt', 'permalink', 'date', 'author', 'slug', 'status'];
        $clean = [];
        foreach (array_slice($fields, 0, 200) as $field) {
            if (!is_array($field)) continue;
            $name = sanitize_key((string) ($field['name'] ?? $field['key'] ?? ''));
            if ($name === '' || isset($clean[$name]) || in_array($name, $reserved, true)) continue;
            $type = sanitize_key((string) ($field['type'] ?? 'text'));
            if (!in_array($type, $allowed_types, true)) $type = 'text';
            $clean[$name] = [
                'name' => $name,
                'label' => sanitize_text_field((string) ($field['label'] ?? $name)) ?: $name,
                'type' => $type,
                'description' => sanitize_textarea_field((string) ($field['description'] ?? '')),
                'required' => rest_sanitize_boolean($field['required'] ?? false),
                'default' => $this->sanitize_cms_field_default($type, $field['default'] ?? ''),
                'min' => isset($field['min']) && $field['min'] !== '' ? (float) $field['min'] : '',
                'max' => isset($field['max']) && $field['max'] !== '' ? (float) $field['max'] : '',
                'step' => isset($field['step']) && (float) $field['step'] > 0 ? (float) $field['step'] : 1,
                'unit' => sanitize_text_field((string) ($field['unit'] ?? '')),
            ];
        }
        return array_values($clean);
    }

    /** @return list<array<string,mixed>> */
    private function sanitize_project_template_collections(mixed $collections): array {
        if (!is_array($collections)) return [];
        $clean = [];
        foreach (array_slice($collections, 0, 100) as $collection) {
            if (!is_array($collection)) continue;
            $slug = sanitize_key((string) ($collection['slug'] ?? ''));
            if (!preg_match('/^kodety_[a-z0-9_]{1,14}$/', $slug)) continue;
            $name = substr(sanitize_text_field((string) ($collection['name'] ?? '')), 0, 120);
            if ($name === '') continue;
            $clean[$slug] = [
                'slug' => $slug,
                'name' => $name,
                'singular' => substr(sanitize_text_field((string) ($collection['singular'] ?? $name)), 0, 120) ?: $name,
                'urlSlug' => substr(sanitize_title((string) ($collection['urlSlug'] ?? $name)), 0, 180),
                'fields' => $this->sanitize_project_template_fields($collection['fields'] ?? []),
            ];
        }
        return array_values($clean);
    }

    /** @return array<string,list<array<string,mixed>>> */
    private function sanitize_project_template_field_definitions(mixed $definitions): array {
        if (!is_array($definitions)) return [];
        $clean = [];
        foreach (array_slice($definitions, 0, 200, true) as $post_type => $fields) {
            $post_type = sanitize_key((string) $post_type);
            if ($post_type === '') continue;
            $normalized = $this->sanitize_project_template_fields($fields);
            if ($normalized) $clean[$post_type] = $normalized;
        }
        return $clean;
    }

    /** @return array<string,string> */
    private function sanitize_project_template_mappings(mixed $templates, string $project_root = ''): array {
        if (!is_array($templates)) return [];
        $clean = [];
        foreach (array_slice($templates, 0, 200, true) as $post_type => $html_path) {
            $post_type = sanitize_key((string) $post_type);
            $html_path = ltrim(str_replace('\\', '/', sanitize_text_field((string) $html_path)), '/');
            if (
                $post_type === ''
                || $html_path === ''
                || str_contains($html_path, '../')
                || !preg_match('/\.html?$/i', $html_path)
            ) continue;
            if ($project_root !== '' && !is_file(rtrim($project_root, '/\\') . '/' . $html_path)) continue;
            $clean[$post_type] = $html_path;
        }
        return $clean;
    }

    /** Portable authoring state not already stored in .incode/project.json. */
    private function project_template_manifest(): array {
        $field_definitions = $this->project_cms_option('kodety_field_definitions', []);
        return [
            'schemaVersion' => self::PROJECT_TEMPLATE_SCHEMA_VERSION,
            'kind' => 'kodety-project-template',
            'kodetyVersion' => defined('KODETY_VERSION') ? KODETY_VERSION : '',
            'cms' => [
                // CMS content remains WordPress content; templates only carry
                // the schema and the page-to-collection mapping.
                'collections' => $this->sanitize_project_template_collections($this->collection_definitions()),
                'fieldDefinitions' => $this->sanitize_project_template_field_definitions($field_definitions),
                'templates' => $this->sanitize_project_template_mappings($this->cms_template_definitions()),
            ],
            'membership' => class_exists('Kodety_Members')
                ? ['settings' => Kodety_Members::template_settings()]
                : ['settings' => []],
            'analytics' => class_exists('Kodety_Analytics')
                ? ['settings' => Kodety_Analytics::template_settings()]
                : ['settings' => []],
            'excludes' => [
                'users',
                'members',
                'subscriptions',
                'orders',
                'analyticsEvents',
                'emailContacts',
                'credentials',
                'extensionInstallations',
            ],
        ];
    }

    private function project_template_manifest_json(): string {
        $encoded = wp_json_encode(
            $this->project_template_manifest(),
            JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
        );
        if (!is_string($encoded) || strlen($encoded) > self::PROJECT_TEMPLATE_MAX_BYTES) {
            throw new RuntimeException('As configurações portáteis do projeto ultrapassam o limite seguro.');
        }
        return $encoded;
    }

    private function project_template_state_digest(): string {
        return hash('sha256', $this->project_template_manifest_json());
    }

    /**
     * Restore only an explicitly imported template. Ordinary autosaves never
     * replay this file, preventing an open Builder tab from reverting newer
     * CMS changes made elsewhere.
     */
    private function restore_project_template_state(string $directory, string $project_id = ''): bool {
        $project_id = sanitize_key($project_id);
        $root = $this->collapse_single_root($directory);
        $path = $root . '/' . self::PROJECT_TEMPLATE_MANIFEST;
        if (!is_file($path)) return false;
        $bytes = filesize($path);
        if ($bytes === false || $bytes <= 0 || $bytes > self::PROJECT_TEMPLATE_MAX_BYTES) {
            throw new RuntimeException('O manifesto de template está vazio ou acima do limite seguro.');
        }
        $manifest = json_decode((string) file_get_contents($path), true);
        if (
            !is_array($manifest)
            || (int) ($manifest['schemaVersion'] ?? 0) !== self::PROJECT_TEMPLATE_SCHEMA_VERSION
            || (string) ($manifest['kind'] ?? '') !== 'kodety-project-template'
        ) {
            throw new RuntimeException('O manifesto de template não é compatível com esta versão do Onun Kodety.');
        }
        $cms = is_array($manifest['cms'] ?? null) ? $manifest['cms'] : [];
        $next = [
            'kodety_collections' => $this->sanitize_project_template_collections($cms['collections'] ?? []),
            'kodety_field_definitions' => $this->sanitize_project_template_field_definitions($cms['fieldDefinitions'] ?? []),
            'kodety_cms_templates' => $this->sanitize_project_template_mappings($cms['templates'] ?? [], $root),
        ];
        $previous = [];
        foreach ($next as $option => $value) {
            $stored = $this->project_cms_option_for_scope($option, $project_id, []);
            $previous[$option] = is_array($stored) ? $stored : [];
        }
        $previous_membership = class_exists('Kodety_Members') ? Kodety_Members::settings() : null;
        $previous_analytics = class_exists('Kodety_Analytics') ? Kodety_Analytics::template_settings() : null;
        try {
            foreach ($next as $option => $value) {
                if (!$this->write_cms_option_for_scope_with_ack($option, $value, $project_id)) {
                    throw new RuntimeException('O WordPress não confirmou a restauração de ' . $option . '.');
                }
            }
            $membership = is_array($manifest['membership'] ?? null) ? $manifest['membership'] : [];
            $membership_settings = is_array($membership['settings'] ?? null) ? $membership['settings'] : [];
            if (
                class_exists('Kodety_Members')
                && !Kodety_Members::restore_template_settings($membership_settings)
            ) {
                throw new RuntimeException('O WordPress não confirmou as configurações portáteis de Membership.');
            }
            $analytics = is_array($manifest['analytics'] ?? null) ? $manifest['analytics'] : [];
            $analytics_settings = is_array($analytics['settings'] ?? null) ? $analytics['settings'] : [];
            if (
                class_exists('Kodety_Analytics')
                && !Kodety_Analytics::restore_template_settings($analytics_settings)
            ) {
                throw new RuntimeException('O WordPress não confirmou as configurações portáteis do Analytics.');
            }
        } catch (Throwable $error) {
            foreach ($previous as $option => $value) {
                $this->write_cms_option_for_scope_with_ack($option, $value, $project_id);
            }
            if (is_array($previous_membership)) {
                update_option('kodety_membership_settings', $previous_membership, false);
            }
            if (is_array($previous_analytics) && class_exists('Kodety_Analytics')) {
                Kodety_Analytics::restore_template_settings($previous_analytics);
            }
            throw $error;
        }
        $current_project_id = $this->cms_workspace_project_id();
        if ($project_id === '' || ($current_project_id !== '' && hash_equals($current_project_id, $project_id))) {
            $this->register_collections();
            flush_rewrite_rules(false);
        }
        do_action('kodety_project_template_restored', $manifest, $root, $project_id);
        return true;
    }

    /**
     * Build a disposable transport archive from native files.
     *
     * @param array<string,string> $extra_entries
     */
    private function package_directory_as_zip(
        string $directory,
        string $prefix = 'kodety-export-',
        array $extra_entries = []
    ): string {
        if (!class_exists('ZipArchive')) throw new RuntimeException('A extensão PHP ZipArchive precisa estar habilitada na hospedagem.');
        if (!is_dir($directory)) throw new RuntimeException('O workspace nativo não foi encontrado.');
        $path = tempnam(get_temp_dir(), $prefix);
        if ($path === false) throw new RuntimeException('Não foi possível preparar o download temporário.');
        $zip = new ZipArchive();
        if ($zip->open($path, ZipArchive::OVERWRITE) !== true) {
            @unlink($path);
            throw new RuntimeException('Não foi possível montar o ZIP temporário.');
        }
        try {
            $root_length = strlen(rtrim($directory, '/\\')) + 1;
            $files = [];
            $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($directory, FilesystemIterator::SKIP_DOTS));
            foreach ($iterator as $file) if ($file->isFile() && !$file->isLink()) $files[] = $file->getPathname();
            sort($files, SORT_STRING);
            foreach ($files as $file) {
                $relative = str_replace('\\', '/', substr($file, $root_length));
                if (array_key_exists($relative, $extra_entries)) continue;
                if (!$zip->addFile($file, $relative)) throw new RuntimeException('Não foi possível incluir ' . $relative . ' no transporte.');
            }
            foreach ($extra_entries as $relative => $contents) {
                $relative = ltrim(str_replace('\\', '/', (string) $relative), '/');
                if (
                    $relative === ''
                    || str_contains($relative, '../')
                    || str_contains($relative, "\0")
                    || !is_string($contents)
                    || !$zip->addFromString($relative, $contents)
                ) {
                    throw new RuntimeException('Não foi possível incluir uma configuração portátil no transporte.');
                }
            }
        } catch (Throwable $error) {
            $zip->close();
            @unlink($path);
            throw $error;
        }
        $zip->close();
        return $path;
    }

    /**
     * Build the authorized Builder representation without ever hydrating the
     * canonical workspace below uploads. Only the transport snapshot is opened
     * in PHP's system temp area; the Builder then hydrates it in memory. The
     * temp directory is removed before this method returns and the caller
     * deletes the resulting ZIP immediately after reading it.
     */
    private function package_editable_workspace_as_zip(
        string $directory,
        string $prefix = 'kodety-project-',
        ?string $template_manifest = null,
        bool $include_current_template = true
    ): string {
        $extra_entries = $include_current_template ? [
            self::PROJECT_TEMPLATE_MANIFEST => $template_manifest ?? $this->project_template_manifest_json(),
        ] : [];
        $root = $this->collapse_single_root($directory);
        $artifact = $root . '/.incode/membership/runtime.json';
        if (!is_file($artifact)) {
            return $this->package_directory_as_zip($directory, $prefix, $extra_entries);
        }
        $token = function_exists('wp_generate_password')
            ? wp_generate_password(10, false, false)
            : bin2hex(random_bytes(5));
        $temporary_directory = trailingslashit(get_temp_dir()) . 'kodety-workspace-' . $token;
        if (is_dir($temporary_directory)) $this->remove_tree($temporary_directory);
        wp_mkdir_p($temporary_directory);
        try {
            $this->copy_workspace_tree($directory, $temporary_directory);
            $this->open_membership_artifact_for_transport($temporary_directory);
            return $this->package_directory_as_zip($temporary_directory, $prefix, $extra_entries);
        } finally {
            if (is_dir($temporary_directory)) $this->remove_tree($temporary_directory);
        }
    }

    private function project_name_from_directory(string $directory): string {
        $candidates = [];
        $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($directory, FilesystemIterator::SKIP_DOTS));
        foreach ($iterator as $file) {
            if (!$file->isFile() || $file->getFilename() !== 'project.json' || basename($file->getPath()) !== '.incode') continue;
            $candidates[] = $file->getPathname();
        }
        usort($candidates, static fn(string $left, string $right): int => substr_count($left, DIRECTORY_SEPARATOR) <=> substr_count($right, DIRECTORY_SEPARATOR));
        foreach ($candidates as $metadata_path) {
            $metadata = json_decode((string) file_get_contents($metadata_path), true);
            if (!is_array($metadata) || !is_string($metadata['name'] ?? null)) continue;
            $name = sanitize_text_field(wp_trim_words(trim($metadata['name']), 12, ''));
            if ($name !== '') return $name;
        }
        return '';
    }

    private function normalize_project_id(mixed $value): string {
        $raw = is_string($value) ? strtolower(trim($value)) : '';
        $project_id = preg_replace('/[^a-z0-9_-]+/', '-', $raw);
        return is_string($project_id) && $project_id !== '' ? substr($project_id, 0, 96) : '';
    }

    private function project_id_from_zip(string $zip_path): string {
        if (!class_exists('ZipArchive')) return '';
        $zip = new ZipArchive();
        if ($zip->open($zip_path) !== true) return '';
        $candidates = [];
        try {
            for ($index = 0; $index < $zip->numFiles; $index++) {
                $name = ltrim(str_replace('\\', '/', (string) $zip->getNameIndex($index)), '/');
                if (
                    $name === ''
                    || basename($name) !== 'project.json'
                    || basename(dirname($name)) !== '.incode'
                ) continue;
                $candidates[] = [
                    'index' => $index,
                    'depth' => substr_count($name, '/'),
                    'name' => $name,
                ];
            }
            usort($candidates, static function (array $left, array $right): int {
                $depth = ((int) $left['depth']) <=> ((int) $right['depth']);
                return $depth !== 0 ? $depth : strcmp((string) $left['name'], (string) $right['name']);
            });
            foreach ($candidates as $candidate) {
                $metadata = json_decode((string) $zip->getFromIndex((int) $candidate['index']), true);
                $project_id = $this->normalize_project_id(
                    is_array($metadata) ? ($metadata['projectId'] ?? '') : ''
                );
                if ($project_id !== '') return $project_id;
            }
            return '';
        } finally {
            $zip->close();
        }
    }

    private function project_id_from_directory(string $directory): string {
        $candidates = [];
        $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($directory, FilesystemIterator::SKIP_DOTS));
        foreach ($iterator as $file) {
            if (!$file->isFile() || $file->getFilename() !== 'project.json' || basename($file->getPath()) !== '.incode') continue;
            $candidates[] = $file->getPathname();
        }
        usort($candidates, static fn(string $left, string $right): int => substr_count($left, DIRECTORY_SEPARATOR) <=> substr_count($right, DIRECTORY_SEPARATOR));
        foreach ($candidates as $metadata_path) {
            $metadata = json_decode((string) file_get_contents($metadata_path), true);
            $project_id = $this->normalize_project_id(
                is_array($metadata) ? ($metadata['projectId'] ?? '') : ''
            );
            if ($project_id !== '') return $project_id;
        }
        return '';
    }

    private function directory_contains_component_studio(string $directory): bool {
        foreach ($this->find_html_files($directory) as $html_path) {
            $html = file_get_contents($html_path);
            if (is_string($html) && str_contains($html, 'data-kodety-component-studio')) return true;
        }
        return false;
    }

    private function directory_main_html_path(string $directory): string {
        $root = $this->collapse_single_root($directory);
        $metadata = $root . '/.incode/project.json';
        if (!is_file($metadata)) return '';
        $decoded = json_decode((string) file_get_contents($metadata), true);
        return is_array($decoded) ? ltrim(str_replace('\\', '/', (string) ($decoded['mainHtmlPath'] ?? '')), '/') : '';
    }

    private function repair_component_studio_directory(string $workspace): bool {
        if (!$this->directory_contains_component_studio($workspace)) return false;
        $main_html = $this->directory_main_html_path($workspace);
        $directories = glob($this->releases_dir() . '/*/project', GLOB_ONLYDIR) ?: [];
        rsort($directories, SORT_STRING);
        $fallback = '';
        foreach ($directories as $candidate) {
            if ($this->directory_contains_component_studio($candidate)) continue;
            if ($main_html !== '' && $this->directory_main_html_path($candidate) !== $main_html) continue;
            $fallback = $candidate;
            break;
        }
        if ($fallback === '') throw new RuntimeException('O workspace contém um canvas temporário e não há release saudável para recuperar.');
        $root = $this->collapse_single_root($workspace);
        $fallback_root = $this->collapse_single_root($fallback);
        $replaced = 0;
        foreach ($this->find_html_files($root) as $html_path) {
            $html = (string) file_get_contents($html_path);
            if (!str_contains($html, 'data-kodety-component-studio')) continue;
            $relative = ltrim(str_replace('\\', '/', substr($html_path, strlen($root))), '/');
            $healthy = $fallback_root . '/' . $relative;
            if (is_file($healthy) && copy($healthy, $html_path)) $replaced++;
        }
        if ($replaced === 0 || $this->directory_contains_component_studio($workspace)) {
            throw new RuntimeException('A recuperação não conseguiu restaurar as páginas do workspace.');
        }
        update_option('kodety_workspace_revision', (int) get_option('kodety_workspace_revision', 0) + 1, false);
        update_option('kodety_workspace_css_digest', $this->css_digest_from_directory($workspace), false);
        update_option('kodety_draft_updated_at', current_time('c'), false);
        return true;
    }

    private function collapse_single_root(string $directory): string {
        $items = array_values(array_filter(scandir($directory) ?: [], fn(string $item): bool => !in_array($item, ['.','..','__MACOSX','.DS_Store'], true)));
        return count($items) === 1 && is_dir($directory . '/' . $items[0]) ? $directory . '/' . $items[0] : $directory;
    }

    private function ensure_directories(): void {
        wp_mkdir_p($this->releases_dir());
        $private = $this->private_storage_dir();
        if (!is_file($private . '/index.php')) file_put_contents($private . '/index.php', "<?php\n// Private Onun Kodety workspace.\n");
        if (!is_file($private . '/.htaccess')) file_put_contents($private . '/.htaccess', "<IfModule mod_authz_core.c>\nRequire all denied\n</IfModule>\n<IfModule !mod_authz_core.c>\nDeny from all\n</IfModule>\n");
        if (!is_file($private . '/web.config')) file_put_contents($private . '/web.config', "<?xml version=\"1.0\" encoding=\"UTF-8\"?><configuration><system.webServer><security><authorization><remove users=\"*\" roles=\"\" verbs=\"\"/><add accessType=\"Deny\" users=\"*\"/></authorization></security></system.webServer></configuration>\n");
        if (!is_file($this->storage_dir . '/index.php')) file_put_contents($this->storage_dir . '/index.php', "<?php\n// Silence is golden.\n");
        if (!is_file($this->storage_dir . '/.htaccess')) file_put_contents($this->storage_dir . '/.htaccess', "Options -Indexes\n<FilesMatch \\\"\\.zip$\\\">\nRequire all denied\n</FilesMatch>\n");
    }

    /** Synchronize a file changed by MCP with the native editable workspace. */
    public function mcp_sync_project_file(string $relative, string $source): void {
        $relative = ltrim(str_replace('\\', '/', $relative), '/');
        if ($relative === '' || str_contains($relative, '../') || str_contains($relative, "\0")) return;
        $workspace = $this->workspace_dir();
        if (!is_dir($workspace)) return;
        $workspace_root = $this->collapse_single_root($workspace);
        $target = $workspace_root . '/' . $relative;
        wp_mkdir_p(dirname($target));
        $source_real = realpath($source);
        $target_real = realpath($target);
        if (!$source_real || !$target_real || $source_real !== $target_real) copy($source, $target);
        $this->write_preview_file_manifest($workspace_root);
        update_option('kodety_workspace_css_digest', $this->css_digest_from_directory($workspace), false);
    }

    public function mcp_delete_project_file(string $relative): void {
        $relative = ltrim(str_replace('\\', '/', $relative), '/');
        if ($relative === '' || str_contains($relative, '../') || str_contains($relative, "\0")) return;
        $workspace = $this->workspace_dir();
        if (!is_dir($workspace)) return;
        $workspace_root = $this->collapse_single_root($workspace);
        $target = $workspace_root . '/' . $relative;
        if (is_file($target)) @unlink($target);
        $this->write_preview_file_manifest($workspace_root);
        update_option('kodety_workspace_css_digest', $this->css_digest_from_directory($workspace), false);
    }

    public function mcp_publish_current_project(): string {
        $workspace = $this->workspace_dir();
        if (!is_dir($workspace)) throw new RuntimeException('Nenhum projeto Onun Kodety está disponível para publicação.');
        $transport = $this->package_directory_as_zip($workspace, 'kodety-mcp-');
        try {
            return $this->install_zip($transport, 'kodety-mcp.zip');
        } finally {
            if (is_file($transport)) @unlink($transport);
        }
    }

    private function current_zip(): string { return $this->storage_dir . '/current.zip'; }

    /** Copy the authored public tree without allowing a partial theme release.
     * Every file is verified after copy because a successful directory walk
     * alone does not prove that the host persisted the same bytes. */
    private function copy_tree(string $source, string $destination): void {
        if (!is_dir($source)) {
            throw new RuntimeException('A origem da árvore pública do tema não está disponível. A versão anterior continua ativa.');
        }
        if ((!is_dir($destination) && !wp_mkdir_p($destination)) || !is_dir($destination)) {
            throw new RuntimeException('Não foi possível criar a árvore pública do tema. A versão anterior continua ativa.');
        }
        foreach (new DirectoryIterator($source) as $item) {
            if ($item->isDot()) continue;
            if ($item->isDir() && $item->getFilename() === '.incode') continue;
            $target = $destination . '/' . $item->getFilename();
            if ($item->isDir()) {
                $this->copy_tree($item->getPathname(), $target);
                continue;
            }
            $source_path = $item->getPathname();
            if (!$item->isFile() || !@copy($source_path, $target)) {
                throw new RuntimeException('Não foi possível copiar um arquivo para a árvore pública do tema. A versão anterior continua ativa.');
            }
            clearstatcache(true, $source_path);
            clearstatcache(true, $target);
            $source_size = @filesize($source_path);
            $target_size = @filesize($target);
            $source_hash = @hash_file('sha256', $source_path);
            $target_hash = @hash_file('sha256', $target);
            if (
                $source_size === false
                || $target_size === false
                || $source_size !== $target_size
                || !is_string($source_hash)
                || !is_string($target_hash)
                || !hash_equals($source_hash, $target_hash)
            ) {
                throw new RuntimeException('Um arquivo divergiu durante a preparação da árvore pública do tema. A versão anterior continua ativa.');
            }
        }
    }

    private function remove_tree(string $directory): void {
        if (!is_dir($directory)) return;
        $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($directory, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
        foreach ($iterator as $item) $item->isDir() ? rmdir($item->getPathname()) : unlink($item->getPathname());
        rmdir($directory);
    }

    private function redirect_notice(string $type, string $message): void {
        wp_safe_redirect(add_query_arg([
            'page' => $this->project_admin_page_slug(),
            'kodety_notice' => rawurlencode($message),
            'kodety_type' => $type,
        ], admin_url('admin.php')));
        exit;
    }

    public function admin_notice(): void {
        if (isset($_GET['kodety_themes_deleted'])) {
            $deleted = absint($_GET['kodety_themes_deleted']);
            $failed = absint($_GET['kodety_themes_failed'] ?? 0);
            echo '<div class="notice kodety-notice notice-' . ($failed ? 'warning' : 'success') . ' is-dismissible"><p>' . esc_html(sprintf('%d tema(s) inativo(s) removido(s).', $deleted)) . ($failed ? ' ' . esc_html(sprintf('%d não puderam ser removidos.', $failed)) : '') . '</p></div>';
            return;
        }
        if (
            empty($_GET['kodety_notice'])
            || !in_array((string) ($_GET['page'] ?? ''), ['kodety', 'kodety-project-settings'], true)
        ) return;
        $type = ($_GET['kodety_type'] ?? '') === 'success' ? 'success' : 'error';
        echo '<div class="notice kodety-notice notice-' . esc_attr($type) . ' is-dismissible"><p>' . esc_html(rawurldecode(sanitize_text_field(wp_unslash($_GET['kodety_notice'])))) . '</p></div>';
    }
}
